```jac
"""Direct randomized launch controller: models one day-1 assignment,
physical execution, open exposure, and freezer progress through typed
edges and a walker that performs the day-1 traversal natively.

Core entities (2-4 archetypes):
  - Assignment: the randomized day-1 work given to one writer.
  - PhysicalExecution: the exclusive-writer work tied to an assignment.
  - ExposureWindow: the open exposure carrying exact work/assignment/receipt lineage.
  - FreezerState: the freezer progress that must advance on PASS.

Relationships (typed edges):
  - IssuedTo: Assignment -> PhysicalExecution (assignment binds work).
  - OpensExposure: PhysicalExecution -> ExposureWindow (work opens exposure).
  - ProgressesFreezer: ExposureWindow -> FreezerState (exposure advances freezer).
"""

node Assignment {
    has title: str = "";
    has receipt: str = "";
    has accepted_risk: bool = False;
}

node PhysicalExecution {
    has work_id: str = "";
    has writer: str = "";
    has completed: bool = False;
}

node ExposureWindow {
    has label: str = "";
    has lineage_ok: bool = False;
    has rolled_back: bool = False;
}

node FreezerState {
    has can_advance: bool = False;
    has day_one_done: bool = False;
}

edge IssuedTo {
    has bound_at: str = "";
}

edge OpensExposure {
    has opened_at: str = "";
}

edge ProgressesFreezer {
    has sealed: bool = False;
}

walker DayOneRunner {
    has assignment_title: str = "";
    has receipt_seal: str = "";

    can start with Root entry {
        print(f"Day-1 runner engaged for assignment: {self.assignment_title}");
        visit [->:IssuedTo:->];
    }

    can execute with PhysicalExecution entry {
        here.completed = True;
        print(f"physical work {here.work_id} executed by exclusive writer {here.writer}");
        visit [->:OpensExposure:->];
    }

    can open_exposure with ExposureWindow entry {
        here.lineage_ok = True;
        here.rolled_back = False;
        print(f"exposure '{here.label}' open with exact lineage: assignment={self.assignment_title}, receipt={self.receipt_seal}");
        visit [->:ProgressesFreezer:->];
    }

    can advance_freezer with FreezerState entry {
        here.can_advance = True;
        here.day_one_done = True;
        print("freezer is able to advance; day-1 randomized assignment is ACTIVE");
        visit [-->] else { disengage; }
    }
}

with entry {
    a = Assignment(
        title="randomized-day-1",
        receipt="rcpt-attempt-225-A",
        accepted_risk=True,
    );
    e = PhysicalExecution(
        work_id="work-225-A",
        writer="exclusive-writer-1",
        completed=False,
    );
    w = ExposureWindow(label="day-1-exposure", lineage_ok=False, rolled_back=False);
    f = FreezerState(can_advance=False, day_one_done=False);

    root +>:IssuedTo(bound_at="2026-08-29T00:00Z"):+> a;
    a +>:IssuedTo(bound_at="2026-08-29T00:01Z"):+> e;
    e +>:OpensExposure(opened_at="2026-08-29T00:02Z"):+> w;
    w +>:ProgressesFreezer(sealed=True):+> f;

    root spawn DayOneRunner(
        assignment_title="randomized-day-1",
        receipt_seal="rcpt-attempt-225-A",
    );
}
```

import io;
import from contextlib { redirect_stdout }

test "typed edges preserve the complete assignment lineage" {
    a = Assignment(
        title="randomized-day-1",
        receipt="rcpt-attempt-225-A",
        accepted_risk=True,
    );
    e = PhysicalExecution(
        work_id="work-225-A",
        writer="exclusive-writer-1",
    );
    w = ExposureWindow(label="day-1-exposure");
    f = FreezerState();

    root +>:IssuedTo(bound_at="2026-08-29T00:00Z"):+> a;
    a +>:IssuedTo(bound_at="2026-08-29T00:01Z"):+> e;
    e +>:OpensExposure(opened_at="2026-08-29T00:02Z"):+> w;
    w +>:ProgressesFreezer(sealed=True):+> f;

    assert len([root ->:IssuedTo:->]) == 1, "root edge count mismatch";
    assert a in [root ->:IssuedTo:->], "assignment target missing";
    assert len([a ->:IssuedTo:->]) == 1, "assignment edge count mismatch";
    assert e in [a ->:IssuedTo:->], "execution target missing";
    assert w in [e ->:OpensExposure:->], "exposure target missing";
    assert f in [w ->:ProgressesFreezer:->], "freezer target missing";
    assert a.accepted_risk == True, f"accepted risk: {a.accepted_risk}";
    assert e.completed == False, f"initial completion: {e.completed}";
    assert w.lineage_ok == False, f"initial lineage: {w.lineage_ok}";
    assert f.day_one_done == False, f"initial freezer state: {f.day_one_done}";
}

test "physical execution opens exposure and advances the freezer" {
    e = PhysicalExecution(
        work_id="work-225-B",
        writer="exclusive-writer-2",
    );
    w = ExposureWindow(label="day-1-exposure-b");
    f = FreezerState();

    e +>:OpensExposure(opened_at="2026-08-29T01:02Z"):+> w;
    w +>:ProgressesFreezer(sealed=True):+> f;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = e spawn DayOneRunner(
            assignment_title="randomized-day-1",
            receipt_seal="rcpt-attempt-225-B",
        );
    }
    out = buf.getvalue();

    assert e.completed == True, f"execution completion: {e.completed}";
    assert w.lineage_ok == True, f"exposure lineage: {w.lineage_ok}";
    assert w.rolled_back == False, f"exposure rollback: {w.rolled_back}";
    assert f.can_advance == True, f"freezer advance: {f.can_advance}";
    assert f.day_one_done == True, f"day one state: {f.day_one_done}";
    assert "physical work work-225-B executed by exclusive writer exclusive-writer-2" in out, f"missing execution output: {out}";
    assert "exposure 'day-1-exposure-b' open with exact lineage: assignment=randomized-day-1, receipt=rcpt-attempt-225-B" in out, f"missing exposure output: {out}";
    assert "freezer is able to advance; day-1 randomized assignment is ACTIVE" in out, f"missing freezer output: {out}";
}

test "root launch dispatches execution through downstream stages" {
    a = Assignment(
        title="randomized-day-1",
        receipt="rcpt-attempt-225-C",
        accepted_risk=True,
    );
    e = PhysicalExecution(
        work_id="work-225-C",
        writer="exclusive-writer-3",
    );
    w = ExposureWindow(label="day-1-exposure-c");
    f = FreezerState();

    root +>:IssuedTo(bound_at="2026-08-29T02:00Z"):+> e;
    a +>:IssuedTo(bound_at="2026-08-29T02:01Z"):+> e;
    e +>:OpensExposure(opened_at="2026-08-29T02:02Z"):+> w;
    w +>:ProgressesFreezer(sealed=True):+> f;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DayOneRunner(
            assignment_title=a.title,
            receipt_seal=a.receipt,
        );
    }
    out = buf.getvalue();

    assert "Day-1 runner engaged for assignment: randomized-day-1" in out, f"missing launch output: {out}";
    assert e.completed == True, f"root-dispatched execution: {e.completed}";
    assert w.lineage_ok == True, f"root-dispatched lineage: {w.lineage_ok}";
    assert f.day_one_done == True, f"root-dispatched freezer: {f.day_one_done}";
}

Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""Hospital ward doors.

One ward ability serves two kinds of clinical staff at once using a
union trigger (``with Nurse | Doctor entry``); a plain visitor matches
neither type, so the ward stays silent for them.
"""

node Ward {
    has ward_name: str;

    # Union trigger: fires for a Nurse OR a Doctor, not for others.
    can staff_enter with Nurse | Doctor entry {
        print(f"{visitor.badge} badged into the {self.ward_name} ward");
        visitor.shift_visits += 1;
    }
}

walker Nurse {
    has badge: str;
    has shift_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can make_rounds with Ward entry {
        visit [-->];
    }
}

walker Doctor {
    has badge: str;
    has shift_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can make_rounds with Ward entry {
        visit [-->];
    }
}

# A plain family visitor matches neither type: no ward ability fires
# for them, so their pass through the wards is completely silent.
walker FamilyVisitor {
    can start with Root entry {
        visit [-->];
    }

    can wander with Ward entry {
        visit [-->];
    }
}

with entry {
    icu = Ward(ward_name="ICU");
    general = Ward(ward_name="General");
    root ++> icu ++> general;

    nurse = Nurse(badge="N-101");
    root spawn nurse;
    doctor = Doctor(badge="D-55");
    root spawn doctor;
    guest = FamilyVisitor();
    root spawn guest;

    print(f"nurse visited {nurse.shift_visits} wards, "
          f"doctor visited {doctor.shift_visits}; the family visitor "
          f"triggered no ward response at all");
}
```

"""Test annex for hospital ward doors program."""

import io;
import from contextlib { redirect_stdout }

test "nurse badging prints badge and increments shift_visits" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    nurse = Nurse(badge="N-101");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
    }
    out = buf.getvalue();

    assert "N-101 badged into the ICU ward" in out, f"missing ICU badge line: {out!r}";
    assert "N-101 badged into the General ward" in out, f"missing General badge line: {out!r}";
    assert nurse.shift_visits == 2, f"expected 2 ward visits, got {nurse.shift_visits}";
}

test "doctor badging prints badge and increments shift_visits" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn doctor;
    }
    out = buf.getvalue();

    assert "D-55 badged into the ICU ward" in out, f"missing ICU badge line: {out!r}";
    assert "D-55 badged into the General ward" in out, f"missing General badge line: {out!r}";
    assert doctor.shift_visits == 2, f"expected 2 ward visits, got {doctor.shift_visits}";
}

test "family visitor triggers no ward response and no shift_visits increment" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    # FamilyVisitor has no badge field; confirm no badge line is printed
    # for any ward and no error is raised by spawn.
    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn guest;
    }
    out = buf.getvalue();

    assert "badged into" not in out, f"family visitor produced badge output: {out!r}";
    # ensure neither ward_name leaked through any print either
    assert "ICU" not in out and "General" not in out, f"unexpected ward text for visitor: {out!r}";
}

test "multiple staff of both kinds count visits independently" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General") ++> Ward(ward_name="Pediatrics");

    nurse_a = Nurse(badge="N-A");
    nurse_b = Nurse(badge="N-B");
    doctor_x = Doctor(badge="D-X");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse_a;
        root spawn nurse_b;
        root spawn doctor_x;
    }
    out = buf.getvalue();

    # Each staff member should see every ward exactly once -> 3 visits
    assert nurse_a.shift_visits == 3, f"nurse_a expected 3 visits, got {nurse_a.shift_visits}";
    assert nurse_b.shift_visits == 3, f"nurse_b expected 3 visits, got {nurse_b.shift_visits}";
    assert doctor_x.shift_visits == 3, f"doctor_x expected 3 visits, got {doctor_x.shift_visits}";

    # Every badge should appear once per ward
    for badge in ["N-A", "N-B", "D-X"] {
        for ward in ["ICU", "General", "Pediatrics"] {
            line = f"{badge} badged into the {ward} ward";
            assert line in out, f"missing line {line!r} in output: {out!r}";
        }
    }
}

Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""Account moderation sweep: audit members, boost admins, greet every bot."""

node Account {
    has handle: str = "";
    has reputation: int = 0;
    has is_admin: bool = False;
}

node Bot {
    has model_name: str = "";
}

walker Auditor {
    can start with Root entry {
        print("Beginning moderation sweep...");
        visit [-->];
    }

    can audit with Account entry {
        if here.is_admin {
            boosted = here.reputation + 5;
            print(f"[ADMIN] {here.handle} reputation boosted to {boosted}");
            here.reputation = boosted;
        } else {
            print(f"[MEMBER] {here.handle} reputation steady at {here.reputation}");
        }
        visit [-->];
    }
}

walker Greeter {
    can start with Root entry {
        print("Welcome desk open.");
        visit [-->];
    }

    can greet with Bot entry {
        print(f"Hello bot ({here.model_name})! Welcome aboard.");
        visit [-->];
    }
}

with entry {
    root ++> Account(handle="alice", reputation=42)
        ++> Account(handle="bob_admin", reputation=99, is_admin=True)
        ++> Account(handle="carol", reputation=15)
        ++> Bot(model_name="Scout")
        ++> Bot(model_name="Sentry");

    root spawn Auditor();
    root spawn Greeter();
}
```

```jac
import io;
import from contextlib { redirect_stdout }

test "member accounts are audited without reputation changes" {
    alice = Account(handle="alice", reputation=42);
    root ++> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert alice.reputation == 42, f"got {alice.reputation}";
    assert "[MEMBER] alice reputation steady at 42" in out, f"missing member audit: {out}";
}

test "admin reputation is boosted by five" {
    admin = Account(handle="bob_admin", reputation=99, is_admin=True);
    root ++> admin;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert admin.reputation == 104, f"got {admin.reputation}";
    assert "[ADMIN] bob_admin reputation boosted to 104" in out, f"missing admin boost: {out}";
}

test "welcome desk greets every bot" {
    root ++> Account(handle="alice", reputation=42);
    scout = Bot(model_name="Scout");
    sentry = Bot(model_name="Sentry");
    root ++> scout;
    root ++> sentry;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Greeter();
    }
    out = buf.getvalue();

    assert "Hello bot (Scout)! Welcome aboard." in out, f"missing Scout greeting: {out}";
    assert "Hello bot (Sentry)! Welcome aboard." in out, f"missing Sentry greeting: {out}";
}
