Given the Jac program below, write a passing `jac test` suite for it. Output only the test file.

```jac
"""Library catalog: model books as nodes with typed fields and defaults.

Demonstrates `has` defaults (year 0, available True) plus a librarian
walker that sweeps the shelf announcing each book's IN/OUT status.
"""

node Book {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Librarian {
    has shelf_label: str = "Main";

    can start with Root entry {
        print(f"Shelving books for {self.shelf_label} shelf");
        visit [-->];
    }

    can shelve with Book entry {
        status = "IN" if here.available else "OUT";
        print(f"[{status}] {here.title} ({here.year})");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", year=1965)
        ++> Book(title="Neuromancer", year=1984)
        ++> Book(title="Circe", year=2018, available=False);

    root spawn Librarian(shelf_label="Sci-Fi & Fantasy");
}
```

"""Test annex for the library catalog program."""

import io;
import from contextlib { redirect_stdout }

# Test 1: default field values — year=0, available=True
test "default fields on Book" {
    root ++> Book(title="Untitled");
    b = [root -->][0];
    assert b.title == "Untitled", f"expected title 'Untitled', got {b.title}";
    assert b.year == 0, f"expected default year 0, got {b.year}";
    assert b.available == True, f"expected default available True, got {b.available}";
}

# Test 2: walker prints shelf header and every book's IN/OUT status
test "librarian prints all books with status" {
    root ++> Book(title="Dune", year=1965);
    root ++> Book(title="Neuromancer", year=1984);
    root ++> Book(title="Circe", year=2018, available=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Librarian(shelf_label="Sci-Fi");
    }
    out = buf.getvalue();

    assert "Shelving books for Sci-Fi shelf" in out, f"missing shelf header: {out}";
    assert "[IN] Dune (1965)" in out, f"missing IN marker for Dune: {out}";
    assert "[IN] Neuromancer (1984)" in out, f"missing IN marker for Neuromancer: {out}";
    assert "[OUT] Circe (2018)" in out, f"missing OUT marker for Circe: {out}";
}

# Test 3: default shelf label is "Main"
test "default shelf label" {
    root ++> Book(title="Solo", year=2001);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Librarian();
    }
    out = buf.getvalue();

    assert "Shelving books for Main shelf" in out, f"missing default shelf header: {out}";
    assert "[IN] Solo (2001)" in out, f"missing book print: {out}";
}

# Test 4: fan-out graph — three direct children of root
test "fan out graph shape" {
    root ++> Book(title="A", year=100);
    root ++> Book(title="B", year=200);
    root ++> Book(title="C", year=300, available=False);

    assert len([root -->]) == 3, f"root should have 3 direct children, got {len([root -->])}";
}

# Test 5: available=False book is announced as OUT, not IN
test "unavailable book shows OUT" {
    root ++> Book(title="Gone", year=1999, available=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Librarian(shelf_label="Drama");
    }
    out = buf.getvalue();

    assert "[OUT] Gone (1999)" in out, f"missing OUT marker: {out}";
    assert "[IN] Gone" not in out, f"Gone should be OUT, not IN: {out}";
    assert "Shelving books for Drama shelf" in out, f"missing shelf header: {out}";
}

