```jac
"""License audit on transitive dependencies.

Models the essential scenario from issue #84: a project's package manifest
pulls in transitive dependencies, each of which declares a license. A
walker crawls the dependency graph, classifies each package's license
against an allowlist, and reports findings.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has approved: bool = False;
    has audited: bool = False;
    has blocked: bool = False;
    has reason: str = "";
}

node AuditReport {
    has total: int = 0;
    has compatible: int = 0;
    has incompatible: int = 0;
    has unknown: int = 0;
}

edge DependsOn { }
edge Reports { }

walker LicenseAuditor {
    has allowlist: list[str] = [];
    has visited: list[str] = [];
    has report_node: AuditReport = AuditReport();

    def classify(license: str) -> str {
        normalized = license.strip().upper();
        if normalized == "" {
            return "unknown";
        }
        approved = False;
        for entry in self.allowlist {
            if entry.upper() == normalized {
                approved = True;
            }
        }
        if approved {
            return "compatible";
        }
        return "incompatible";
    }

    def already_seen(name: str) -> bool {
        seen = False;
        for v in self.visited {
            if v == name {
                seen = True;
            }
        }
        return seen;
    }

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        if self.already_seen(here.name) {
            visit [-->];
            return;
        }
        self.visited.append(here.name);
        verdict = self.classify(here.license);
        self.report_node.total += 1;
        if verdict == "compatible" {
            here.approved = True;
            here.audited = True;
            self.report_node.compatible += 1;
            print(f"[OK]   {here.name}@{here.version} -> {here.license}");
        } elif verdict == "incompatible" {
            here.audited = True;
            here.blocked = True;
            here.reason = "license not in allowlist";
            self.report_node.incompatible += 1;
            print(f"[FAIL] {here.name}@{here.version} -> {here.license} (gates build)");
        } else {
            here.audited = True;
            here.blocked = True;
            here.reason = "license unknown / not declared";
            self.report_node.unknown += 1;
            print(f"[?]    {here.name}@{here.version} -> (unknown)");
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    allow = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"];

    # Direct dependencies (children of root manifest)
    newtonsoft = Package(name="Newtonsoft.Json", version="13.0.3", license="MIT");
    serilog = Package(name="Serilog", version="3.1.1", license="Apache-2.0");

    # Transitive pull-ins
    step_codepages = Package(name="System.Text.Encoding.CodePages",
                             version="8.0.0", license="MIT");
    sci_immutable = Package(name="System.Collections.Immutable",
                            version="8.0.0", license="MIT");
    serilog_sinks_file = Package(name="Serilog.Sinks.File", version="5.0.0",
                                 license="Apache-2.0");

    # Incompatible transitive: silently leaked GPL into an MIT project
    sharpziplib = Package(name="SharpZipLib", version="1.4.2", license="GPL-3.0");

    # Unknown / undeclared transitive
    contrib_legacy = Package(name="Contrib.Legacy", version="1.0.0", license="");

    # A cyclic reference: Two packages co-depend (tests cycle handling)
    libalpha = Package(name="LibAlpha", version="2.0.0", license="BSD-3-Clause");
    libbeta = Package(name="LibBeta", version="1.5.0", license="MIT");

    root ++> newtonsoft;
    root ++> serilog;

    newtonsoft +>:DependsOn:+> step_codepages;
    newtonsoft +>:DependsOn:+> sci_immutable;
    newtonsoft +>:DependsOn:+> sharpziplib;

    serilog +>:DependsOn:+> serilog_sinks_file;
    serilog_sinks_file +>:DependsOn:+> contrib_legacy;

    # Cycle: libalpha <-> libbeta
    libalpha +>:DependsOn:+> libbeta;
    libbeta +>:DependsOn:+> libalpha;

    auditor = LicenseAuditor(allowlist=allow);
    root spawn auditor;

    print("");
    print(f"Audit summary: total={auditor.report_node.total}, "
          f"compatible={auditor.report_node.compatible}, "
          f"incompatible={auditor.report_node.incompatible}, "
          f"unknown={auditor.report_node.unknown}");

    all_pkgs = [
        newtonsoft, serilog, step_codepages, sci_immutable,
        serilog_sinks_file, sharpziplib, contrib_legacy,
        libalpha, libbeta
    ];
    blocking = [];
    for node in all_pkgs {
        if node.blocked {
            blocking.append(f"{node.name}@{node.version} ({node.reason})");
        }
    }
    if len(blocking) > 0 {
        print(f"Build would fail: {len(blocking)} blocking license finding(s):");
        for b in blocking {
            print(f"  - {b}");
        }
    } else {
        print("Build would pass: no blocking license findings.");
    }
}
