import io;
import from contextlib { redirect_stdout }

test "audits reachable dependencies and blocks incompatible licenses" {
    allow = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"];
    direct_a = Package(name="Direct.A", version="1.0", license="MIT");
    direct_b = Package(name="Direct.B", version="2.0", license="Apache-2.0");
    blocked = Package(name="Blocked", version="3.0", license="GPL-3.0");
    unknown = Package(name="Unknown", version="4.0", license="");

    root ++> direct_a;
    root ++> direct_b;
    direct_a +>:DependsOn:+> blocked;
    direct_b +>:DependsOn:+> unknown;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LicenseAuditor(allowlist=allow);
    }
    out = buf.getvalue();

    assert len([root-->]) == 2, f"got {len([root-->])} direct dependencies";
    assert res.report_node.total == 4, f"got {res.report_node.total}";
    assert res.report_node.compatible == 2, f"got {res.report_node.compatible}";
    assert res.report_node.incompatible == 1, f"got {res.report_node.incompatible}";
    assert res.report_node.unknown == 1, f"got {res.report_node.unknown}";
    assert direct_a.audited, f"got {direct_a.audited}";
    assert direct_a.approved, f"got {direct_a.approved}";
    assert not direct_a.blocked, f"got {direct_a.blocked}";
    assert blocked.blocked, f"got {blocked.blocked}";
    assert blocked.reason == "license not in allowlist", f"got {blocked.reason}";
    assert unknown.blocked, f"got {unknown.blocked}";
    assert unknown.reason == "license unknown / not declared", f"got {unknown.reason}";
    assert "[FAIL]" in out, f"missing failure finding: {out}";
    assert "[?]" in out, f"missing unknown finding: {out}";
}

test "allowlist matching is normalized while unknown stays fail closed" {
    allow = ["MIT"];
    accepted = Package(name="Accepted", version="1.0", license=" mit ");
    rejected = Package(name="Rejected", version="1.0", license="OSL-3.0");
    missing = Package(name="Missing", version="1.0", license="");

    root ++> accepted;
    root ++> rejected;
    root ++> missing;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LicenseAuditor(allowlist=allow);
    }

    assert res.report_node.total == 3, f"got {res.report_node.total}";
    assert res.report_node.compatible == 1, f"got {res.report_node.compatible}";
    assert res.report_node.incompatible == 1, f"got {res.report_node.incompatible}";
    assert res.report_node.unknown == 1, f"got {res.report_node.unknown}";
    assert accepted.approved, f"got {accepted.approved}";
    assert not rejected.approved, f"got {rejected.approved}";
    assert rejected.blocked, f"got {rejected.blocked}";
    assert missing.blocked, f"got {missing.blocked}";
}

test "audit follows dependency edges but ignores unreachable packages" {
    allow = ["MIT"];
    reachable = Package(name="Reachable", version="1.0", license="MIT");
    transitive = Package(name="Transitive", version="1.0", license="GPL-3.0");
    detached = Package(name="Detached", version="1.0", license="GPL-3.0");

    root ++> reachable;
    reachable +>:DependsOn:+> transitive;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LicenseAuditor(allowlist=allow);
    }

    assert res.report_node.total == 2, f"got {res.report_node.total}";
    assert res.report_node.compatible == 1, f"got {res.report_node.compatible}";
    assert res.report_node.incompatible == 1, f"got {res.report_node.incompatible}";
    assert transitive.blocked, f"got {transitive.blocked}";
    assert not detached.audited, f"got {detached.audited}";
    assert not detached.blocked, f"got {detached.blocked}";
}

