"""GPU resource graph: walk submits to host-visible buffers and count first-touch faults."""

node Submit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has submit_id: int = 0;
    has draw_count: int = 0;
}

node Texture {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has texture_id: int = 0;
    has size_mib: int = 0;
    has reused: bool = False;
}

node BufferObject {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has bo_id: int = 0;
    has mapped: bool = True;
    has first_touch_pages: int = 0;
}

node MemoryPool {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has capacity_mib: int = 0;
}

edge Submitted { }
edge UsesTexture { }
edge BackedBy { }
edge AllocatedFrom { }

walker PageFaultAudit {
    has hop_budget: int = 20;
    has fault_pages: int = 0;
    has mapped_buffers: int = 0;

    can start with Root entry {
        print("walking submit resource graph");
        visit [->:Submitted:->] else { disengage; }
    }

    can inspect_submit with Submit entry {
        if self.hop_budget <= 0 {
            print("cycle/depth guard stopped the audit");
            disengage;
        }
        self.hop_budget = self.hop_budget - 1;
        print(f"submit {here.submit_id}: {here.draw_count} draws");
        visit [->:UsesTexture:->] else { disengage; }
    }

    can inspect_texture with Texture entry {
        if self.hop_budget <= 0 {
            print("cycle/depth guard stopped the audit");
            disengage;
        }
        self.hop_budget = self.hop_budget - 1;
        if here.reused {
            print(f"reused texture {here.texture_id}: {here.size_mib} MiB");
        } else {
            print(f"new texture {here.texture_id}: {here.size_mib} MiB");
        }
        visit [->:BackedBy:->] else { disengage; }
    }

    can inspect_buffer with BufferObject entry {
        if self.hop_budget <= 0 {
            print("cycle/depth guard stopped the audit");
            disengage;
        }
        self.hop_budget = self.hop_budget - 1;
        if here.mapped {
            self.mapped_buffers = self.mapped_buffers + 1;
            self.fault_pages = self.fault_pages + here.first_touch_pages;
            print(f"BO {here.bo_id}: {here.first_touch_pages} faults and PAT/iomem walks");
        }
        visit [->:AllocatedFrom:->] else { disengage; }
    }

    can inspect_pool with MemoryPool entry {
        print(f"pool {here.title}: {here.capacity_mib} MiB host-visible capacity");
    }
}

with entry {
    pool = MemoryPool(title="host-visible VRAM", year=2024, available=True, capacity_mib=4096);
    fresh_bo = BufferObject(title="fresh image BO", year=2024, available=True, bo_id=101, mapped=True, first_touch_pages=8192);
    cached_bo = BufferObject(title="reused image BO", year=2024, available=True, bo_id=42, mapped=True, first_touch_pages=0);
    fresh_texture = Texture(title="new texture", year=2024, available=True, texture_id=9001, size_mib=32, reused=False);
    cached_texture = Texture(title="reused texture", year=2023, available=True, texture_id=42, size_mib=32, reused=True);
    first_submit = Submit(title="frame 1", year=2024, available=True, submit_id=1, draw_count=46);
    second_submit = Submit(title="frame 2", year=2024, available=True, submit_id=2, draw_count=47);

    root +>:Submitted:+> first_submit;
    root +>:Submitted:+> second_submit;
    first_submit +>:UsesTexture:+> fresh_texture;
    first_submit +>:UsesTexture:+> cached_texture;
    second_submit +>:UsesTexture:+> cached_texture;
    fresh_texture +>:BackedBy:+> fresh_bo;
    cached_texture +>:BackedBy:+> cached_bo;
    fresh_bo +>:AllocatedFrom:+> pool;
    cached_bo +>:AllocatedFrom:+> pool;

    audit = PageFaultAudit(hop_budget=20);
    root spawn audit;
    print(f"audit total: {audit.fault_pages} faults/PAT walks across {audit.mapped_buffers} mapped BOs");
}
