import io;
import from contextlib { redirect_stdout }

test "audits fresh and reused mapped buffers" {
    pool = MemoryPool(title="host pool", capacity_mib=4096);
    fresh_bo = BufferObject(bo_id=101, mapped=True, first_touch_pages=8192);
    reused_bo = BufferObject(bo_id=42, mapped=True, first_touch_pages=0);
    fresh_texture = Texture(texture_id=9001, size_mib=32, reused=False);
    reused_texture = Texture(texture_id=42, size_mib=32, reused=True);
    submit = Submit(submit_id=1, draw_count=46);

    root +>:Submitted:+> submit;
    submit +>:UsesTexture:+> fresh_texture;
    submit +>:UsesTexture:+> reused_texture;
    fresh_texture +>:BackedBy:+> fresh_bo;
    reused_texture +>:BackedBy:+> reused_bo;
    fresh_bo +>:AllocatedFrom:+> pool;
    reused_bo +>:AllocatedFrom:+> pool;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PageFaultAudit(hop_budget=20);
    }
    out = buf.getvalue();

    assert res.fault_pages == 8192, f"got {res.fault_pages}";
    assert res.mapped_buffers == 2, f"got {res.mapped_buffers}";
    assert "new texture 9001" in out, f"missing fresh texture output: {out}";
    assert "reused texture 42" in out, f"missing reused texture output: {out}";
    assert "pool host pool" in out, f"missing pool output: {out}";
}

test "ignores first touches from unmapped buffers" {
    pool = MemoryPool(title="host pool", capacity_mib=1024);
    bo = BufferObject(bo_id=77, mapped=False, first_touch_pages=4096);
    texture = Texture(texture_id=7, size_mib=16, reused=False);
    submit = Submit(submit_id=2, draw_count=10);

    root +>:Submitted:+> submit;
    submit +>:UsesTexture:+> texture;
    texture +>:BackedBy:+> bo;
    bo +>:AllocatedFrom:+> pool;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PageFaultAudit(hop_budget=20);
    }
    out = buf.getvalue();

    assert res.fault_pages == 0, f"got {res.fault_pages}";
    assert res.mapped_buffers == 0, f"got {res.mapped_buffers}";
    assert "BO 77" not in out, f"unexpected unmapped BO output: {out}";
    assert "pool host pool" in out, f"missing pool output: {out}";
}

test "stops when the hop budget is exhausted" {
    submit = Submit(submit_id=3, draw_count=1);
    root +>:Submitted:+> submit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PageFaultAudit(hop_budget=0);
    }
    out = buf.getvalue();

    assert res.fault_pages == 0, f"got {res.fault_pages}";
    assert res.mapped_buffers == 0, f"got {res.mapped_buffers}";
    assert "cycle/depth guard stopped the audit" in out, f"missing guard output: {out}";
}

