import io;
import from contextlib { redirect_stdout }

test "scout collects all prices and peak" {
    root ++> Airport(title="JFK");
    jfk = [root -->][0];
    ord_hub = Airport(title="ORD");
    lax = Airport(title="LAX");
    jfk +>:FlightLeg(price=450.0):+> ord_hub;
    ord_hub +>:FlightLeg(price=320.0):+> lax;
    jfk +>:FlightLeg(price=520.0):+> lax;

    scout = root spawn Scout();
    assert sorted(scout.prices) == [320.0, 450.0, 520.0], f"got {scout.prices}";
    assert scout.max_fare == 520.0, f"peak={scout.max_fare}";
    assert len(scout.legs) == 3, f"legs={len(scout.legs)}";
}

test "scout with no legs yields empty reports and zero peak" {
    root ++> Airport(title="AAA");
    scout = root spawn Scout();
    assert scout.prices == [], f"prices={scout.prices}";
    assert scout.legs == [], f"legs={scout.legs}";
    assert scout.max_fare == 0.0, f"max={scout.max_fare}";
}

test "normalized_fare returns fraction of peak" {
    jfk = Airport(title="JFK");
    ord_hub = Airport(title="ORD");
    jfk +>:FlightLeg(price=450.0):+> ord_hub;
    leg1 = [edge jfk ->:FlightLeg:-> ord_hub][0];
    peak = 520.0;
    assert leg1.normalized_fare(peak) == 450.0 / 520.0, f"leg1 share={leg1.normalized_fare(peak)}";
}

test "normalized_fare fail-closed on non-positive peak" {
    a = Airport(title="A");
    b = Airport(title="B");
    a +>:FlightLeg(price=300.0):+> b;
    leg = [edge a ->:FlightLeg:-> b][0];
    assert leg.normalized_fare(0.0) == 0.0, "zero peak must yield 0.0";
    assert leg.normalized_fare(-50.0) == 0.0, "negative peak must yield 0.0";
}

test "scout + normalized_fare main loop prints expected fractions" {
    root ++> Airport(title="JFK");
    jfk = [root -->][0];
    ord_hub = Airport(title="ORD");
    lax = Airport(title="LAX");
    jfk +>:FlightLeg(price=450.0):+> ord_hub;
    ord_hub +>:FlightLeg(price=320.0):+> lax;
    jfk +>:FlightLeg(price=520.0):+> lax;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        scout = root spawn Scout();
        peak = scout.max_fare;
        print(f"Network peak fare: ${peak}");
        for leg in scout.legs {
            share = leg.normalized_fare(peak);
            print(f"Leg ${leg.price} is {share} of peak fare (${peak})");
        }
    }
    out = buf.getvalue();
    assert "Network peak fare: $520.0" in out, f"missing peak line: {out}";
    assert "Leg $450.0 is 0.8653846153846154 of peak fare ($520.0)" in out, f"missing 450 line: {out}";
    assert "Leg $320.0 is 0.6153846153846154 of peak fare ($520.0)" in out, f"missing 320 line: {out}";
    assert "Leg $520.0 is 1.0 of peak fare ($520.0)" in out, f"missing 520 line: {out}";
}

