```jac
"""Security architecture: route event reactions through ModuleExecutor.

Models the core scenario from the issue: an event router that *bypasses*
the canonical executor boundary, dispatching handler reactions directly
with no authority check, no entitlement gate, no audit, and no cycle
policy. A canonical walker shows the bypass, and a fixed walker shows
the proper boundary-crossing path.
"""

# ---------------------------------------------------------------------------
# Entities
# ---------------------------------------------------------------------------

node Module {
    has name: str = "";
    has declared_action: str = "";
    has action_permissions: list[str] = [];
    has entitlement_gate: str = "";
}

node Reaction {
    has name: str = "";
    has target_kind: str = "handler";
    has permissions: list[str] = [];
}

node Event {
    has event_type: str = "";
    has producer: str = "";
    has envelope_permissions: list[str] = [];
}

node AuditLog {
    has entries: list[str] = [];
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

edge ReactionDispatched { }
edge EventEnveloped { }
edge ModuleAction { }

# ---------------------------------------------------------------------------
# Walker: the bypass.  Walks Reaction -> Module directly with no authority.
# This is what the issue says is broken: no executor boundary, no
# entitlement gate, no audit, no cycle guard, no dead-end handling.
# ---------------------------------------------------------------------------

walker BypassRouter {
    has routed_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can dispatch with Reaction entry {
        print(f"[BYPASS] reaction '{here.name}' firing without executor");
        self.routed_count += 1;
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Walker: the canonical path.  Reaction must cross the ModuleExecutor
# boundary, the entitlement gate must match, the audit log must record
# the dispatch, and cycles on the Event graph must be detected and
# stopped (visitors in jac 0.36.1 do NOT auto-dedupe cyclic edges).
# ---------------------------------------------------------------------------

walker CanonicalRouter {
    has event_id: str = "evt-0";
    has event_type: str = "";
    has event_producer: str = "";
    has seen_events: list[str] = [];
    has dispatched: int = 0;
    has denied: int = 0;
    has audited: list[str] = [];

    can start with Root entry {
        print(f"[CANONICAL] event {self.event_id} ({self.event_type}) "
              f"from {self.event_producer} entering ModuleExecutor");
        visit [-->];
    }

    can audit_dispatch with Module entry {
        gate_ok = here.entitlement_gate == "enforce";
        action_ok = here.declared_action != "";
        perm_ok = len(here.action_permissions) > 0;
        if gate_ok and action_ok and perm_ok {
            self.dispatched += 1;
            line = (f"dispatch module={here.name} "
                    f"action={here.declared_action} "
                    f"perms={here.action_permissions}");
            self.audited.append(line);
            print(f"[CANONICAL]   allowed: {line}");
        } else {
            self.denied += 1;
            print(f"[CANONICAL]   denied: module={here.name} "
                  f"gate_ok={gate_ok} action_ok={action_ok} "
                  f"perm_ok={perm_ok}");
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: cascade invalidation across an Event graph that may contain
# cycles.  Walkers in jac 0.36.1 do not dedupe; the guard set below is
# the explicit cycle policy the issue warns about.
# ---------------------------------------------------------------------------

walker CascadeInvalidate {
    has invalidated: list[str] = [];
    has guarded: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can follow with Event entry {
        already = False;
        for prior in self.guarded {
            if prior == here.event_type {
                already = True;
            }
        }
        if already {
            print(f"[CASCADE] cycle guard fired on {here.event_type}, disengaging");
            disengage;
        }
        self.guarded.append(here.event_type);
        self.invalidated.append(here.event_type);
        print(f"[CASCADE] invalidated event {here.event_type}");
        visit [-->] else { disengage; }
    }
}

# ---------------------------------------------------------------------------
# Demo graph: bypass path vs canonical path vs cyclic event cascade.
# ---------------------------------------------------------------------------

with entry {
    # --- Bypass demo: Reaction -> Module direct edge, no executor ---
    bypass_rxn = Reaction(name="bypass-rxn", target_kind="handler",
                          permissions=[]);
    bypass_mod = Module(name="bypass-mod", declared_action="",
                        action_permissions=[],
                        entitlement_gate="");
    root ++> bypass_rxn +>:ReactionDispatched:+> bypass_mod;

    # --- Canonical demo: Reaction -> Module over the executor boundary ---
    canon_rxn = Reaction(name="canon-rxn", target_kind="handler",
                         permissions=["evt.consume"]);
    canon_mod = Module(name="canon-mod", declared_action="consume",
                         action_permissions=["evt.consume"],
                         entitlement_gate="enforce");
    audit = AuditLog();
    root ++> canon_rxn +>:ReactionDispatched:+> canon_mod;
    root ++> audit;

    # --- Cyclic event cascade: A -> B -> C -> A ---
    ev_a = Event(event_type="A", producer="svc-a",
                 envelope_permissions=["evt.consume"]);
    ev_b = Event(event_type="B", producer="svc-b",
                 envelope_permissions=["evt.consume"]);
    ev_c = Event(event_type="C", producer="svc-c",
                 envelope_permissions=["evt.consume"]);
    root ++> ev_a +>:EventEnveloped:+> ev_b +>:EventEnveloped:+> ev_c;
    ev_c +>:EventEnveloped:+> ev_a;

    print("=== bypass (broken) ===");
    bypass = BypassRouter();
    root spawn bypass;
    print(f"bypass routed {bypass.routed_count} reactions with "
          f"no authority, no entitlement, no audit");

    print("\n=== canonical (fixed) ===");
    cr = CanonicalRouter(event_id="evt-1",
                          event_type="evt.consume",
                          event_producer="svc-a");
    root spawn cr;

    print("\n=== cyclic cascade invalidation ===");
    ci = CascadeInvalidate();
    root spawn ci;
    print(f"cascade invalidated: {ci.invalidated}");
}
