```jac
"""Statement RU accounting: producer-side evidence over a physical-plan forest.

Models the executor-side evidence collector that walks the Main plan, the
deduplicated CTE definition forest, and the scalar-subquery (Apply) trees
to gather per-executor RU input. Each executor archetype owns the
display-neutral scalar snapshot it publishes; the Statement RU consumer
walks the forest with one collector walker, accumulating evidence in a
single typed registry.

The four core archetypes picked here are:

  - ScanExecutor: response-level key-size evidence (request root).
  - SortTopNExecutor: lifecycle-bounded sufficient statistics.
  - RecursiveCTE: explicit opportunity + disposition states.
  - Apply: explicit outer/inner/cache opportunity states.

The collector walker enforces the IDForStorage-deduplicated CTE count
and fails closed when evidence is structurally inconsistent.
"""

# ----------------------------------------------------------------------
# Node archetypes
# ----------------------------------------------------------------------

node ScanExecutor {
    has plan_id: int = 0;
    has request_id: str = "";
    has resp_total_key_bytes: int = 0;
    has consumed: bool = False;
}

node SortTopNExecutor {
    has plan_id: int = 0;
    has lifecycle_id: str = "";
    has rows_in: int = 0;
    has began: bool = False;
    has completed: bool = False;
    has incomplete: bool = False;
}

node RecursiveCTE {
    has cte_id: int = 0;
    has phase_attempts: int = 0;
    has completed_rounds: int = 0;
    has skipped: bool = False;
    has executed_zero: bool = False;
    has evidence_missing: bool = False;
}

node Apply {
    has apply_id: int = 0;
    has outer_rows: int = 0;
    has filtered_outer: int = 0;
    has cache_hits: int = 0;
    has logical_inners: int = 0;
    has physical_inners: int = 0;
    has cancelled: bool = False;
}

# ----------------------------------------------------------------------
# Edge archetypes (typed where the relationship carries meaning)
# ----------------------------------------------------------------------

edge LivesUnderPlan {}
edge CTEEdge { has storage_id: int = 0; }
edge InnerOf {}

# ----------------------------------------------------------------------
# Walker: Statement RU consumer
# ----------------------------------------------------------------------

walker Collector {
    has evidence_complete: bool = True;
    has scan_bytes_total: int = 0;
    has sort_log_sum: float = 0.0;
    has cte_seen_storage_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    # CTE definitions: count each IDForStorage exactly once.
    can gather_cte with RecursiveCTE entry {
        sid = here.cte_id;
        first = True;
        for prev in self.cte_seen_storage_ids {
            if prev == sid {
                first = False;
            }
        }
        if first {
            self.cte_seen_storage_ids.append(sid);
            if here.evidence_missing {
                self.evidence_complete = False;
            }
            if here.skipped and here.executed_zero {
                self.evidence_complete = False;
            }
        }
        visit [->:CTEEdge:->];
    }

    # Apply subtree: collect outer/inner/cache evidence; fail closed
    # when positive rows appear without any physical inner execution
    # (every physical opportunity must have been attempted).
    can gather_apply with Apply entry {
        if here.outer_rows > 0 and here.physical_inners == 0 and not here.cancelled {
            self.evidence_complete = False;
        }
        visit [->:InnerOf:->];
    }

    # Response-level scan evidence: aggregate request-scoped key bytes,
    # including close-time unconsumed responses.
    can gather_scan with ScanExecutor entry {
        self.scan_bytes_total += here.resp_total_key_bytes;
        visit [->:LivesUnderPlan:->];
    }

    # Sort/TopN: per-lifecycle sufficient statistic. Repeated CTE rounds
    # and correlated Apply executions merge by plan_id; rows are summed
    # per lifecycle so the consumer cannot reconstruct sum(n*log(n))
    # from aggregate rows alone.
    can gather_sort with SortTopNExecutor entry {
        n = here.rows_in;
        if n > 1 {
            contrib = n * (n.bit_length() - 1);
            self.sort_log_sum += float(contrib);
        }
        if here.began and (not here.completed) and (not here.incomplete) {
            self.evidence_complete = False;
        }
        visit [->:LivesUnderPlan:->];
    }
}

# ----------------------------------------------------------------------
# Demonstration wiring
# ----------------------------------------------------------------------

with entry {
    # --- CTE forest (deduplicated by IDForStorage) -------------------
    cte_seed = RecursiveCTE(
        cte_id=42,
        phase_attempts=1,
        completed_rounds=0,
        skipped=False,
        executed_zero=True
    );
    cte_recursive = RecursiveCTE(
        cte_id=42,
        phase_attempts=3,
        completed_rounds=2,
        skipped=False,
        executed_zero=False
    );
    cte_skipped = RecursiveCTE(
        cte_id=99,
        phase_attempts=0,
        completed_rounds=0,
        skipped=True,
        executed_zero=False
    );

    # --- Apply subtree: outer rows with cache hits, one cancel ------
    apply_root = Apply(
        apply_id=1,
        outer_rows=10,
        filtered_outer=3,
        cache_hits=4,
        logical_inners=7,
        physical_inners=3,
        cancelled=False
    );
    apply_cancelled = Apply(
        apply_id=2,
        outer_rows=5,
        filtered_outer=1,
        cache_hits=0,
        logical_inners=2,
        physical_inners=0,
        cancelled=True
    );

    # --- Sort/TopN with lifecycle-bounded sufficient statistics ----
    sort_a = SortTopNExecutor(
        plan_id=10, lifecycle_id="L1",
        rows_in=100, began=True, completed=True, incomplete=False
    );
    sort_b = SortTopNExecutor(
        plan_id=10, lifecycle_id="L2",
        rows_in=50, began=True, completed=True, incomplete=False
    );

    # --- Scan executors under a single request root ----------------
    scan_main = ScanExecutor(
        plan_id=1, request_id="R-1",
        resp_total_key_bytes=2048, consumed=True
    );
    scan_unconsumed = ScanExecutor(
        plan_id=1, request_id="R-1",
        resp_total_key_bytes=512, consumed=False
    );

    # Wire the forest.
    cte_seed +>:CTEEdge(storage_id=42):+> cte_recursive;
    root ++> cte_seed;
    root ++> cte_skipped;

    apply_root +>:InnerOf:+> apply_cancelled;
    root ++> apply_root;

    root ++> sort_a +>:LivesUnderPlan:+> sort_b;

    scan_main +>:LivesUnderPlan:+> scan_unconsumed;
    root ++> scan_main;

    collector = Collector();
    root spawn collector;

    print(f"scan_bytes_total = {collector.scan_bytes_total}");
    print(f"sort_log_sum = {collector.sort_log_sum}");
    print(f"cte storage_ids seen = {collector.cte_seen_storage_ids}");
    print(f"evidence_complete = {collector.evidence_complete}");
}
```

"""Regression tests for the Statement RU producer-side evidence collector."""

import io;
import from contextlib { redirect_stdout }

# ----------------------------------------------------------------------
# Test helpers
# ----------------------------------------------------------------------

def make_root_with(roots: list) -> Root {
    r = Root();
    for n in roots {
        r ++> n;
    }
    return r;
}

def run_collector(rt: Root) -> Collector {
    buf = io.StringIO();
    collector = Collector();
    with redirect_stdout(buf) {
        rt spawn collector;
    }
    return collector;
}

# ----------------------------------------------------------------------
# Tests
# ----------------------------------------------------------------------

test "scan bytes aggregate including close-time unconsumed responses" {
    consumed = ScanExecutor(
        plan_id=1, request_id="R-1",
        resp_total_key_bytes=2048, consumed=True
    );
    unconsumed = ScanExecutor(
        plan_id=1, request_id="R-1",
        resp_total_key_bytes=512, consumed=False
    );
    consumed +>:LivesUnderPlan:+> unconsumed;
    rt = make_root_with([consumed]);

    c = run_collector(rt);

    assert c.scan_bytes_total == 2560, f"got {c.scan_bytes_total}";
}

test "sort lifecycle sufficient statistic summed across repeated rounds" {
    # Two lifecycles on the same plan_id must NOT collapse into
    # sum(n)*log(sum(n)); the collector should record sum(n*log(n))
    # across per-lifecycle rows.
    s1 = SortTopNExecutor(
        plan_id=10, lifecycle_id="L1",
        rows_in=100, began=True, completed=True, incomplete=False
    );
    s2 = SortTopNExecutor(
        plan_id=10, lifecycle_id="L2",
        rows_in=50, began=True, completed=True, incomplete=False
    );
    s1 +>:LivesUnderPlan:+> s2;
    rt = make_root_with([s1]);

    c = run_collector(rt);

    # 100*(100.bit_length()-1) + 50*(50.bit_length()-1)
    # = 100*6 + 50*5 = 600 + 250 = 850
    assert c.sort_log_sum == 850.0, f"got {c.sort_log_sum}";
}

test "cte deduplicated by storage id keeps skipped and executed-zero distinct" {
    seed = RecursiveCTE(
        cte_id=42, phase_attempts=1, completed_rounds=0,
        skipped=False, executed_zero=True
    );
    rec = RecursiveCTE(
        cte_id=42, phase_attempts=3, completed_rounds=2,
        skipped=False, executed_zero=False
    );
    skipped = RecursiveCTE(
        cte_id=99, phase_attempts=0, completed_rounds=0,
        skipped=True, executed_zero=False
    );
    seed +>:CTEEdge(storage_id=42):+> rec;
    rt = make_root_with([seed, skipped]);

    c = run_collector(rt);

    assert len(c.cte_seen_storage_ids) == 2, f"got {c.cte_seen_storage_ids}";
    assert 42 in c.cte_seen_storage_ids;
    assert 99 in c.cte_seen_storage_ids;
    assert c.evidence_complete == True, f"got {c.evidence_complete}";
}

test "registered zero and missing evidence are kept distinct" {
    # executed_zero with positive phase_attempts: registered zero outcome
    # is fine; the collector must NOT mark evidence as missing/incomplete
    # just because no rows were produced.
    zero = RecursiveCTE(
        cte_id=7, phase_attempts=2, completed_rounds=0,
        skipped=False, executed_zero=True
    );
    missing = RecursiveCTE(
        cte_id=8, phase_attempts=1, completed_rounds=0,
        skipped=False, executed_zero=False,
        evidence_missing=True
    );
    rt = make_root_with([zero, missing]);

    c = run_collector(rt);

    assert 7 in c.cte_seen_storage_ids;
    assert 8 in c.cte_seen_storage_ids;
    # The missing-evidence node must flip the collector to incomplete
    # while the registered-zero node does not on its own.
    assert c.evidence_complete == False, f"got {c.evidence_complete}";
}

test "skipped combined with executed_zero is structurally inconsistent" {
    bad = RecursiveCTE(
        cte_id=55, phase_attempts=1, completed_rounds=0,
        skipped=True, executed_zero=True
    );
    rt = make_root_with([bad]);

    c = run_collector(rt);

    assert 55 in c.cte_seen_storage_ids;
    assert c.evidence_complete == False, f"got {c.evidence_complete}";
}

test "apply with outer rows but zero physical inners and no cancel fails closed" {
    inner = Apply(
        apply_id=1, outer_rows=10, filtered_outer=0,
        cache_hits=0, logical_inners=10,
        physical_inners=0, cancelled=False
    );
    rt = make_root_with([inner]);

    c = run_collector(rt);

    assert c.evidence_complete == False, f"got {c.evidence_complete}";
}

test "apply cancelled with zero physical inners is allowed" {
    inner = Apply(
        apply_id=2, outer_rows=5, filtered_outer=1,
        cache_hits=0, logical_inners=2,
        physical_inners=0, cancelled=True
    );
    rt = make_root_with([inner]);

    c = run_collector(rt);

    assert c.evidence_complete == True, f"got {c.evidence_complete}";
}

test "apply cache hits and logical vs physical inner counts recorded" {
    inner = Apply(
        apply_id=3, outer_rows=10, filtered_outer=3,
        cache_hits=4, logical_inners=7,
        physical_inners=3, cancelled=False
    );
    rt = make_root_with([inner]);

    c = run_collector(rt);

    assert c.evidence_complete == True, f"got {c.evidence_complete}";
}

test "sort began but not completed and not marked incomplete fails closed" {
    s = SortTopNExecutor(
        plan_id=20, lifecycle_id="L-mid",
        rows_in=10, began=True, completed=False, incomplete=False
    );
    rt = make_root_with([s]);

    c = run_collector(rt);

    assert c.evidence_complete == False, f"got {c.evidence_complete}";
}

test "empty recursion (zero rounds) is complete and deduplicated" {
    # Two CTEs on the same id, both with zero rounds: still one
    # entry in the deduplicated set and evidence is complete.
    a = RecursiveCTE(
        cte_id=77, phase_attempts=0, completed_rounds=0,
        skipped=False, executed_zero=True
    );
    b = RecursiveCTE(
        cte_id=77, phase_attempts=0, completed_rounds=0,
        skipped=False, executed_zero=True
    );
    a +>:CTEEdge(storage_id=77):+> b;
    rt = make_root_with([a]);

    c = run_collector(rt);

    assert c.cte_seen_storage_ids == [77], f"got {c.cte_seen_storage_ids}";
    assert c.evidence_complete == True, f"got {c.evidence_complete}";
}

test "limited recursion with partial completed rounds is complete" {
    a = RecursiveCTE(
        cte_id=31, phase_attempts=3, completed_rounds=2,
        skipped=False, executed_zero=False
    );
    rt = make_root_with([a]);

    c = run_collector(rt);

    assert 31 in c.cte_seen_storage_ids;
    assert c.evidence_complete == True, f"got {c.evidence_complete}";
}

