"""Weather sweep: stations report temperatures as a walker traverses them."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"{here.name} @ {here.location}: {here.celsius} C");
        visit [-->];
    }
}

walker SweepReporter {
    has readings: list[float] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Station entry {
        self.readings.append(here.celsius);
        visit [-->];
    }

    can finish with Root exit {
        lo = min(self.readings);
        hi = max(self.readings);
        print(f"All readings: {self.readings}");
        print(f"Min: {lo} C, Max: {hi} C");
    }
}

with entry {
    root ++> Station(name="North", location="Anchorage", celsius=-3.5)
        ++> Station(name="East", location="Denver", celsius=18.0)
        ++> Station(name="South", location="Phoenix", celsius=34.2)
        ++> Station(name="West", location="Seattle", celsius=11.7);

    root spawn WeatherSweep();
    root spawn SweepReporter();
}
