```jac
"""Recursive 30-day dependency age check.

Models a resolved dependency graph as nodes (packages) connected by typed
edges (depends-on relationships) and walks it with a walker that rejects
packages newer than the policy threshold. A Developer Mode bypass disables
the age gate. Cycle-safe via an explicit visited set — jac 0.36.1 walkers
do not auto-dedupe on cyclic graphs.
"""

node Package {
    has title: str = "";
    has age_days: int = 0;
}

edge DependsOn {
    has pinned: bool = False;
}

walker AgeAuditor {
    has threshold: int = 30;
    has developer_mode: bool = False;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        if here.title in self.visited {
            visit [-->];
            disengage;
        }
        self.visited.append(here.title);
        if self.developer_mode {
            print(f"[DEV-MODE] {here.title} age={here.age_days}d bypassed");
            visit [->:DependsOn:->];
        } elif here.age_days > self.threshold {
            print(f"[REJECT] {here.title} age={here.age_days}d exceeds {self.threshold}d threshold");
            visit [-->];
        } else {
            print(f"[OK] {here.title} age={here.age_days}d");
            visit [->:DependsOn:->];
        }
    }
}

with entry {
    app_shell = Package(title="app-shell", age_days=45);
    ui_kit = Package(title="ui-kit", age_days=10);
    state_mgr = Package(title="state-mgr", age_days=120);
    utils = Package(title="utils", age_days=5);

    root ++> app_shell;
    app_shell +>:DependsOn(pinned=True):+> ui_kit;
    app_shell +>:DependsOn:+> state_mgr;
    app_shell +>:DependsOn:+> utils;

    legacy = Package(title="legacy-adapter", age_days=200);
    root +>:DependsOn:+> legacy;
    legacy +>:DependsOn:+> state_mgr;

    print("--- strict audit ---");
    root spawn AgeAuditor(threshold=30, developer_mode=False);

    print("--- developer mode bypass ---");
    root spawn AgeAuditor(threshold=30, developer_mode=True);
}
