"""Tests for the private update_todo walker.

Behavior under test:
- update_todo walks from Root, finds the Todo whose jid matches todo_id,
  mutates title/done in place, reports the update, and disengages early.
- A bogus todo_id produces no report.
- Default new_title="" leaves the title unchanged; default new_done=None
  leaves the done flag unchanged.
"""

import io;
import from contextlib { redirect_stdout }

test "update mutates title and done in place and reports" {
    root ++> Todo(title="draft blog post", done=False);
    [root -->][0].title = "draft blog post";

    todo_id = jid([root -->][0]);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn update_todo(
            todo_id=todo_id,
            new_title="publish blog post",
            new_done=True
        );
    }

    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    report0 = res.reports[0];
    assert report0["updated"] == todo_id, f"wrong updated id: {report0}";
    assert report0["title"] == "publish blog post", f"title not mutated: {report0}";
    assert report0["done"] is True, f"done not mutated: {report0}";

    node_ref = [root -->][0];
    assert node_ref.title == "publish blog post", f"node title not mutated: {node_ref.title}";
    assert node_ref.done is True, f"node done not mutated: {node_ref.done}";
}

test "bogus id yields no report and leaves node untouched" {
    root ++> Todo(title="keep me", done=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn update_todo(todo_id="n0suchid", new_title="ghost");
    }

    assert len(res.reports) == 0, f"expected 0 reports, got {res.reports}";

    node_ref = [root -->][0];
    assert node_ref.title == "keep me", f"title should be untouched: {node_ref.title}";
    assert node_ref.done is False, f"done should be untouched: {node_ref.done}";
