"""Delivery route dispatcher.

Each route carries a cargo weight in tonnes. A truck may only be dispatched
when its load is at least 2 tonnes and at most 8 tonnes on the same leg.
A walker inspects every depot and prints which routes qualify for dispatch.
"""

node Route {
    has name: str = "";
    has weight: float = 0.0;
}

node Depot {
    has location: str = "";

    def qualifies(w: float) -> bool {
        return w >= 2.0 and w <= 8.0;
    }
}

edge Serves {}

walker Dispatcher {
    has dispatched_count: int = 0;

    can start with Root entry {
        print("Starting dispatch inspection across all depots");
        visit [-->];
    }

    can inspect_depot with Depot entry {
        print(f"Depot at {here.location}:");
        visit [-->];
    }

    can inspect_route with Route entry {
        status = "DISPATCH" if here.weight >= 2.0 and here.weight <= 8.0 else "HOLD";
        if status == "DISPATCH" {
            self.dispatched_count += 1;
        }
        print(f"  [{status}] {here.name} ({here.weight}t)");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    north = Depot(location="North");
    south = Depot(location="South");
    east = Depot(location="East");

    north ++> Route(name="N-A", weight=1.5)
        ++> Route(name="N-B", weight=3.0)
        ++> Route(name="N-C", weight=7.5)
        ++> Route(name="N-D", weight=9.0);

    south ++> Route(name="S-A", weight=2.0)
        ++> Route(name="S-B", weight=5.5)
        ++> Route(name="S-C", weight=8.0);

    east ++> Route(name="E-A", weight=0.5)
        ++> Route(name="E-B", weight=4.0)
        ++> Route(name="E-C", weight=10.0);

    root ++> north ++> south ++> east;

    d = Dispatcher();
    root spawn d;

    print(f"Total routes dispatched: {d.dispatched_count}");
}
