"""Hiking trail: waypoints chained from trailhead to summit, counted by a hiker walker."""

node Trailhead {
    has name: str = "Trailhead";
}

node Waypoint {
    has marker: bool = True;
}

node Summit {
    has name: str = "Summit";
}

walker Hiker {
    has stop_count: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can at_trailhead with Trailhead entry {
        print(f"At {here.name}");
        visit [-->];
    }

    can pass_waypoint with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can at_summit with Summit entry {
        print(f"Reached {here.name} — passed {self.stop_count} waypoints");
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}
```

"""Test annex for hiking trail hiker walker."""

import io;
import from contextlib { redirect_stdout }


test "hiker counts waypoints and prints each stop" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Per-stop announcements must number 1..N in order.
    assert "Stop 1" in out, f"missing Stop 1 in: {out}";
    assert "Stop 2" in out, f"missing Stop 2 in: {out}";
    assert "Stop 3" in out, f"missing Stop 3 in: {out}";
    # Completion line must reflect final waypoint count.
    assert "passed 3 waypoints" in out, f"missing completion count in: {out}";

    # Final stop_count on the walker matches the chain length.
    assert res.stop_count == 3, f"expected stop_count=3, got {res.stop_count}";
}

test "hiker with no waypoints prints only the completion line" {
    root ++> Trailhead() ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # No "Stop" announcements should appear when there are zero waypoints.
    assert "Stop " not in out, f"unexpected stop output with no waypoints: {out}";
    # Completion line must report zero waypoints.
    assert "passed 0 waypoints" in out, f"missing zero-count completion in: {out}";
    assert res.stop_count == 0, f"expected stop_count=0, got {res.stop_count}";
}

test "hiker visits trailhead then waypoints then summit in order" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Visit order: trailhead greeting, then Stop 1, then summit line.
    th_pos = out.find("At Trailhead");
    stop_pos = out.find("Stop 1");
    sum_pos = out.find("Reached Summit");
    assert th_pos != -1, f"missing trailhead greeting in: {out}";
    assert stop_pos != -1, f"missing Stop 1 in: {out}";
    assert sum_pos != -1, f"missing summit line in: {out}";
    assert th_pos < stop_pos < sum_pos, (
        f"expected trailhead<stop<summit ordering, got th={th_pos} stop={stop_pos} sum={sum_pos} :: {out}"
    );
    assert res.stop_count == 1, f"expected stop_count=1, got {res.stop_count}";
}

test "trail chain contains the correct node types in order" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    # The first downstream node from root must be the Trailhead.
    children = [root-->];
    assert len(children) == 1, f"expected 1 child of root, got {len(children)}";
    assert "Trailhead" in type(children[0]).__name__, (
        f"expected Trailhead first, got {type(children[0]).__name__}"
    );

    # Walking the chain: Trailhead -> Waypoint -> Waypoint -> Summit.
    trail = children[0];
    n_waypoints = 0;
    n_summits = 0;
    visited = [trail];
    while len([trail-->]) > 0 {
        next_node = [trail-->][0];
        visited.append(next_node);
        if "Waypoint" in type(next_node).__name__ {
            n_waypoints += 1;
        }
        if "Summit" in type(next_node).__name__ {
            n_summits += 1;
        }
        trail = next_node;
    }
    assert n_waypoints == 2, f"expected 2 waypoints, counted {n_waypoints}";
    assert n_summits == 1, f"expected 1 summit, counted {n_summits}";
}

test "waypoint marker flag defaults to True" {
    wp = Waypoint();
    assert wp.marker == True, f"expected marker=True default, got {wp.marker}";
}

