import io;
import from contextlib { redirect_stdout }

test "counts validated tasks during pipeline audit" {
    root ++> Task(
        title="movement",
        task_title="movement",
        depends_on="design",
        validated=True
    );
    root ++> Task(
        title="collision",
        task_title="collision",
        depends_on="movement",
        validated=True
    );
    res = root spawn PipelineAuditor();
    assert res.validated_count == 2, f"expected 2 validated tasks, got {res.validated_count}";
    assert len(res.gaps) == 0, f"expected no gaps for validated tasks, got {res.gaps}";
}

test "records gap for unvalidated task with dependency" {
    root ++> Task(
        title="collision",
        task_title="collision",
        depends_on="design",
        validated=False
    );
    res = root spawn PipelineAuditor();
    assert res.validated_count == 0, f"expected 0 validated tasks, got {res.validated_count}";
    assert len(res.gaps) == 1, f"expected one gap, got {res.gaps}";
    assert "collision" in res.gaps[0], f"missing task title in gap: {res.gaps[0]}";
    assert "depends on design" in res.gaps[0], f"missing dependency in gap: {res.gaps[0]}";
}

