"""Invitation acceptance: pending → accepted transition at edge tier.

Models a playlist owner who issues an invitation to a recipient, and a
recipient walker that observes the invitation, attempts to accept it, and
walks the relation graph. Mirrors the issue's local-update / wait-for-edge
scenario where a transaction is allocated, local acceptance is admitted,
but the edge-tier settlement is the contested step.
"""

node User {
    has user_id: str = "";
    has role: str = "member";
}

node Playlist {
    has title: str = "";
    has owner_id: str = "";
}

node Invitation {
    has inv_id: str = "";
    has subject: str = "";
    has role: str = "listener";
    has status: str = "pending";
    has tx_id: str = "";
}

edge Owns {}
edge PendingInvite {}
edge AcceptedInvite {}

walker Recipient {
    has session_user: str = "";
    has receipt_deadline: int = 10;
    has current_status: str = "pending";
    has edge_settled: bool = False;

    def start -> None {
        self.session_user = "alice";
    }

    def observe(inv: Invitation) -> str {
        return inv.status;
    }

    def attempt_accept(inv: Invitation) -> str {
        # Old-state guard: subject matches and status is pending.
        if inv.subject == self.session_user and inv.status == "pending" {
            # Self-EXISTS over pre-update snapshot keeps the row pending in
            # the new-state predicate while the adjacent predicate accepts it.
            # Contradiction surfaces as no edge-tier settlement.
            new_status = "accepted";
            inv.status = new_status;
            inv.tx_id = "tx-1907";
            self.current_status = new_status;
            self.edge_settled = False;
            return new_status;
        }
        return inv.status;
    }

    def wait_for_edge() -> bool {
        # Bounded receipt deadline; no mutation error, just never settles.
        self.edge_settled = False;
        return self.edge_settled;
    }

    can begin with Root entry {
        visit [-->];
    }

    can look with Playlist entry {
        visit [->:PendingInvite:->];
    }

    can decide with Invitation entry {
        before = self.observe(here);
        after = self.attempt_accept(here);
        settled = self.wait_for_edge();
        print(
            f"invitation {here.inv_id}: {before} -> {after} "
            f"(tx={here.tx_id}, settled={settled})"
        );
        visit [-->];
    }
}

with entry {
    owner = User(user_id="bob", role="owner");
    recipient = User(user_id="alice", role="member");
    pl = Playlist(title="Late Night Jazz", owner_id="bob");
    inv = Invitation(
