"""Gallery security console.

Every visitor entering a room is logged generically; when a curator walks
in, the room additionally records an official inspection under the
curator's name and tallies how many rooms they inspected. A tourist
triggers only the generic log on each room.
"""

node Room {
    has name: str = "";
    has log: list[str] = [];
    has inspection_count: int = 0;
    has last_inspector: str = "";

    def record_visit(visitor_label: str) {
        self.log.append(f"visited by {visitor_label}");
    }

    def record_inspection(inspector_name: str) {
        self.inspection_count += 1;
        self.last_inspector = inspector_name;
        self.log.append(f"inspected by {inspector_name}");
    }
}

walker Tourist {
    has label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.record_visit(self.label);
        visit [-->];
    }
}

walker Curator {
    has name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.record_visit(self.name);
        here.record_inspection(self.name);
        self.rooms_inspected += 1;
        visit [-->];
    }
}

with entry {
    room_a = Room(name="Gallery A");
    room_b = Room(name="Gallery B");
    root ++> room_a ++> room_b;

    tourist = Tourist(label="tourist-001");
    curator = Curator(name="Dr. Voss");

    root spawn tourist;
    root spawn curator;

    print(
        f"Tourist only logged visits; curator additionally inspected.\n"
        f"Room A: log={room_a.log}, inspections={room_a.inspection_count}, "
        f"last_inspector={room_a.last_inspector}\n"
        f"Room B: log={room_b.log}, inspections={room_b.inspection_count}, "
        f"last_inspector={room_b.last_inspector}\n"
        f"Curator {curator.name} inspected {curator.rooms_inspected} rooms; "
        f"tourist logged generic visits only."
    );
}
