```jac
"""Assembly call-target traversal: resolve external member references against
selected assembly participants using a typed catalog correspondence plan."""

node LibraryBodyIndex {
    has name: str = "";
    has descriptor: str = "";
    has is_active: bool = True;
}

node SelectedParticipant {
    has name: str = "";
    has is_available: bool = True;
    has is_ambiguous: bool = False;
    has is_inactive_shadow: bool = False;
}

node ExternalMemberRef {
    has member_name: str = "";
    has signature_kind: str = "declaring";
    has call_site_id: str = "";
}

node Definition {
    has name: str = "";
    has matches: bool = True;
}

node MissingMember {
    has reason: str = "member-missing";
}

node CorrespondencePlan {
    has is_frozen: bool = False;
    has requests: list[str] = [];
}

edge Retains {
    has role: str = "selected";
}

edge Targets {
    has kind: str = "call-target";
}

edge ResolvesTo {
    has outcome: str = "resolved-definition";
}

walker CallGraphProjection {
    has outcomes: list[str] = [];
    has plan_frozen: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can inspect_index with LibraryBodyIndex entry {
        print(f"Assembly index: {here.name} ({here.descriptor})");
        if not here.is_active {
            disengage;
        }
        visit [-->];
    }

    can select_participants with SelectedParticipant entry {
        if here.is_ambiguous or here.is_inactive_shadow {
            print(f"  skip {here.name}: ambiguous/shadow");
            visit [-->];
        }
        if not here.is_available {
            self.outcomes.append("candidate-unavailable");
            print(f"  unavailable: {here.name}");
            visit [-->];
        }
        visit [-->];
    }

    can plan_correspondence with CorrespondencePlan entry {
        if not here.is_frozen {
            self.plan_frozen = False;
            visit [-->];
        } else {
            self.plan_frozen = True;
            print(f"Plan frozen with {len(here.requests)} requests");
            visit [-->];
        }
    }

    can resolve_member_refs with ExternalMemberRef entry {
        if not self.plan_frozen {
            self.outcomes.append("correspondence-incomplete");
            print(f"  {here.member_name}: plan not frozen");
            visit [-->];
        }
        physical_site = here.call_site_id;
        print(f"  call-site {physical_site} -> {here.member_name}");
        visit [-->];
    }

    can collect_outcomes with Definition entry {
        self.outcomes.append("resolved-definition");
        print(f"  resolved: {here.name}");
        visit [-->];
    }

    can collect_missing with MissingMember entry {
        self.outcomes.append(here.reason);
        print(f"  outcome: {here.reason}");
        visit [-->];
    }
}

with entry {
    body_index = LibraryBodyIndex(
        name="App.Assembly",
        descriptor="app,v1.0",
        is_active=True
    );
    platform = SelectedParticipant(name="Platform");
    package = SelectedParticipant(name="Package");
    shadow = SelectedParticipant(
        name="Shadow",
        is_ambiguous=True
    );
    missing_platform = SelectedParticipant(
        name="EmptyPlatform",
        is_available=False
    );
    plan = CorrespondencePlan(
        is_frozen=True,
        requests=["declaring", "parameter", "return", "generic", "custom-modifier"]
    );
    member_ref = ExternalMemberRef(
        member_name="Helper.WriteLine",
        signature_kind="declaring",
        call_site_id="site-0x42"
    );
    defn = Definition(name="Helper.WriteLine", matches=True);
    missing = MissingMember(reason="member-missing");

    root +>:Retains(role="owner"):+> body_index;
    body_index +>:Retains(role="selected"):+> platform;
    body_index +>:Retains(role="selected"):+> package;
    body_index +>:Retains(role="selected"):+> shadow;
    body_index +>:Retains(role="selected"):+> missing_platform;
    body_index +>:Retains(role="manifest"):+> plan;
    body_index +>:Targets(kind="call-target"):+> member_ref;
    member_ref +>:ResolvesTo(outcome="resolved-definition"):+> defn;
    platform +>:ResolvesTo(outcome="member-missing"):+> missing;

    proj = CallGraphProjection();
    root spawn proj;
    print(f"Outcomes: {proj.outcomes}");
}
