```jac
"""DOCX package ingestion: bounded ZIP/OOXML traversal with cycle guards.

Models a sanitized DOCX package where Parts (XML payloads) are linked via
typed Relationship edges (with a TargetMode and an Id), and a Package walker
walks the relationship graph to collect reachable parts while rejecting
external targets, traversal-style escape attempts, and duplicate-id cycles.
"""

node Part {
    has part_name: str = "";
    has content_kind: str = "xml";
    has content: str = "";
    has visited: bool = False;
}

node Relationship {
    has rel_id: str = "";
    has target_mode: str = "Internal";
    has part_ref: Part | None = None;
}

walker Inspector {
    has seen_ids: list[str] = [];
    has rejected_external: int = 0;
    has rejected_traversal: int = 0;
    has rejected_cycle: int = 0;
    has accepted: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_rel with Relationship entry {
        if here.target_mode == "External" {
            self.rejected_external += 1;
            print(f"[REJECT external] {here.rel_id} -> external target");
            return;
        }

        target_name = here.part_ref.part_name if here.part_ref is not None else "";
        if target_name.startswith("../") or target_name.startswith("/") {
            self.rejected_traversal += 1;
            print(f"[REJECT traversal] {here.rel_id} -> {target_name}");
            return;
        }

        if here.rel_id in self.seen_ids {
            self.rejected_cycle += 1;
            print(f"[REJECT cycle] {here.rel_id} already seen");
            return;
        }
        self.seen_ids.append(here.rel_id);

        self.accepted.append(target_name);
        visit [-->];
    }

    can inspect_part with Part entry {
        if here.visited {
            return;
        }
        here.visited = True;
        print(f"[PART] {here.part_name} ({here.content_kind})");
        visit [-->];
    }
}

with entry {
    document = Part(part_name="word/document.xml", content_kind="xml",
                    content="<doc>hi</doc>");
    styles = Part(part_name="word/styles.xml", content_kind="xml",
                  content="<styles/>");
    theme = Part(part_name="word/theme/theme1.xml", content_kind="xml",
                 content="<theme/>");
    image = Part(part_name="word/media/image1.png", content_kind="png",
                 content="(binary)");
    backdoor = Part(part_name="../../etc/passwd", content_kind="xml",
                    content="(escape)");

    rel_doc_styles = Relationship(rel_id="rId1", target_mode="Internal",
                                  part_ref=styles);
    rel_doc_theme = Relationship(rel_id="rId2", target_mode="Internal",
                                 part_ref=theme);
    rel_doc_image = Relationship(rel_id="rId3", target_mode="Internal",
                                 part_ref=image);
    rel_doc_ext = Relationship(rel_id="rId4", target_mode="External",
                               part_ref=None);
    rel_doc_backdoor = Relationship(rel_id="rId5", target_mode="Internal",
                                    part_ref=backdoor);

    document ++> rel_doc_styles ++> styles;
    document ++> rel_doc_theme ++> theme;
    document ++> rel_doc_image ++> image;
    document ++> rel_doc_ext;
    document ++> rel_doc_backdoor;

    cycle_a = Relationship(rel_id="rId1", target_mode="Internal",
                           part_ref=styles);
    cycle_b = Relationship(rel_id="rId1", target_mode="Internal",
                           part_ref=theme);
    styles ++> cycle_a;
    theme ++> cycle_b;

    root ++> document;

    inspector = Inspector();
    root spawn inspector;

    print(f"accepted: {inspector.accepted}");
    print(f"rejected_external={inspector.rejected_external}, "
          f"rejected_traversal={inspector.rejected_traversal}, "
          f"rejected_cycle={inspector.rejected_cycle}");
}
