test "duplicate rel_id cycles are bounded and parts marked visited" {
    rt = Root();

    document = Part(part_name="word/document.xml", content_kind="xml",
                    content="<doc>hi</doc>");
    styles = Part(part_name="word/styles.xml", content_kind="xml",
                  content="<styles/>");
    theme = Part(part_name="word/theme/theme1.xml", content_kind="xml",
                 content="<theme/>");

    rel_doc_styles = Relationship(rel_id="rId1", target_mode="Internal",
                                  part_ref=styles);
    rel_doc_theme = Relationship(rel_id="rId2", target_mode="Internal",
                                 part_ref=theme);

    # duplicate-id cycle: styles and theme each carry a relationship
    # with the same rel_id "rId1" pointing back into the document.
    cycle_a = Relationship(rel_id="rId1", target_mode="Internal",
                           part_ref=styles);
    cycle_b = Relationship(rel_id="rId1", target_mode="Internal",
                           part_ref=theme);

    document ++> rel_doc_styles ++> styles;
    document ++> rel_doc_theme ++> theme;
    styles ++> cycle_a;
    theme ++> cycle_b;
    rt ++> document;

    inspector = Inspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = rt spawn Inspector();
    }
    out = buf.getvalue();

    assert "[REJECT cycle]" in out, f"expected cycle marker: {out}";
    assert inspector.rejected_cycle >= 1, f"got {inspector.rejected_cycle}";
    # First-seen rel_id is accepted; only the duplicate is rejected.
    assert inspector.accepted.count("word/styles.xml") == 1, f"got {inspector.accepted}";
    assert document.visited, "document part should be marked visited";
    assert styles.visited, "styles part should be marked visited";
    assert theme.visited, "theme part should be marked visited";
    assert inspector.rejected_external == 0, f"got {inspector.rejected_external}";
    assert inspector.rejected_traversal == 0, f"got {inspector.rejected_traversal}";
}

