    # Deterministic acceptance order: styles, theme, image.
    assert inspector.accepted == [
        "word/styles.xml",
        "word/theme/theme1.xml",
        "word/media/image1.png",
    ], f"got {inspector.accepted}";
    assert inspector.rejected_external == 0, f"got {inspector.rejected_external}";
    assert inspector.rejected_traversal == 0, f"got {inspector.rejected_traversal}";
    assert inspector.rejected_cycle == 0, f"got {inspector.rejected_cycle}";
    # Every reachable part emitted a [PART] line.
    assert out.count("[PART]") == 4, f"got {out.count('[PART]')}";
    assert "[PART] word/document.xml" in out, f"missing document part: {out}";
    assert "[PART] word/media/image1.png (png)" in out, f"missing image: {out}";
}

