"""Dungeon crawler: chain of room nodes with one treasure vault; a hunter
walker counts rooms as it visits them and disengages the moment it finds
the treasure so nothing past the vault is ever entered."""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->];
    }

    can search with Room entry {
        self.rooms_inspected += 1;
        if here.is_treasure {
            print(f"[{self.rooms_inspected}] {here.name} -> TREASURE FOUND! Ending the hunt.");
            disengage;
        } else {
            print(f"[{self.rooms_inspected}] {here.name} -> empty, pressing on");
            visit [-->];
        }
    }
}

with entry {
    root ++> Room(name="Entry Hall")
        ++> Room(name="Flooded Corridor")
        ++> Room(name="Spider Alcove")
        ++> Room(name="Bone Pit")
        ++> Room(name="Treasure Vault", is_treasure=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Lair");

    hunter = Hunter();
    root spawn hunter;
    print(f"Total rooms inspected: {hunter.rooms_inspected} (vault found, search ended)");
}
