"""Recursive CTE-style subquery: model a tree where the recursive CTE
result feeds into a downstream query, exactly the scenario from issue
#1237. A walker descends the tree collecting IDs (the CTE), then another
walker uses that collected set as a subquery filter against a separate
collection of Foo nodes (the consumer query).
"""

node TreeNode {
    has id: int = 0;
    has name: str = "";
}

node Foo {
    has id: int = 0;
    has label: str = "";
}

edge ParentOf { }

walker CollectSubtree {
    has collected_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with TreeNode entry {
        self.collected_ids.append(here.id);
        visit [->:ParentOf:->];
    }
}

walker QueryWithSubquery {
    has allowed_ids: list[int] = [];
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can filter with Foo entry {
        if here.id in self.allowed_ids {
            self.matches.append(here.label);
        }
        visit [-->];
    }
}

with entry {
    # Build the tree (the source the recursive CTE walks).
    r = TreeNode(id=0, name="root");
    a = TreeNode(id=1, name="a");
    b = TreeNode(id=2, name="b");
    c = TreeNode(id=3, name="c");
    d = TreeNode(id=4, name="d");
    r +>:ParentOf:+> a;
    a +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> d;
    root ++> r;

    # Step 1: recursive CTE walk to gather ids.
    cte = CollectSubtree();
    r spawn cte;
    print(f"CTE collected ids: {cte.collected_ids}");

    # Step 2: consumer query filtered by the subquery result.
    f1 = Foo(id=1, label="foo-A");
    f2 = Foo(id=2, label="foo-B");
    f3 = Foo(id=3, label="foo-C");
    f4 = Foo(id=5, label="foo-E");
    f5 = Foo(id=99, label="foo-OTHER");
    root ++> f1 ++> f2 ++> f3 ++> f4 ++> f5;

    consumer = QueryWithSubquery(allowed_ids=cte.collected_ids);
    root spawn consumer;
    print(f"Subquery-filtered foos: {consumer.matches}");
}
```

"""Regression tests for issue #1237: recursive CTE-style subquery.

The scenario models a Base-Query whose result feeds into a downstream
query. Two walkers cooperate:
  - CollectSubtree: recursively walks a ParentOf tree, gathering node ids.
  - QueryWithSubquery: filters a collection of Foo nodes by membership
    in the id set produced by CollectSubtree.

These tests assert the behavior described in the issue: the CTE walker
descends through every reachable node in the tree, and the consumer
walker only yields Foo nodes whose id appears in the collected set.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "collect subtree gathers every descendant id in parent-of order" {
    rt_node = Root();
    root_node = TreeNode(id=0, name="root");
    a = TreeNode(id=1, name="a");
    b = TreeNode(id=2, name="b");
    c = TreeNode(id=3, name="c");
    d = TreeNode(id=4, name="d");
    root_node +>:ParentOf:+> a;
    a +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> d;
    rt_node ++> root_node;

    cte = CollectSubtree();
    root_node spawn cte;

    # Root plus all four descendants must be present.
    assert 0 in cte.collected_ids, f"root id missing: {cte.collected_ids}";
    assert 1 in cte.collected_ids, f"id 1 missing: {cte.collected_ids}";
    assert 2 in cte.collected_ids, f"id 2 missing: {cte.collected_ids}";
    assert 3 in cte.collected_ids, f"id 3 missing: {cte.collected_ids}";
    assert 4 in cte.collected_ids, f"id 4 missing: {cte.collected_ids}";
    assert len(cte.collected_ids) == 5,
        f"expected exactly 5 ids, got {cte.collected_ids}";
}

# ---------------------------------------------------------------------------
test "collect subtree from a leaf collects only that leaf" {
    rt_node = Root();
    root_node = TreeNode(id=7, name="lone");
    rt_node ++> root_node;

    cte = CollectSubtree();
    root_node spawn cte;

    # A leaf with no outgoing ParentOf edges contributes exactly one id.
    assert cte.collected_ids == [7],
        f"expected [7], got {cte.collected_ids}";
}

# ---------------------------------------------------------------------------
test "subquery filter matches only foos whose id is in the CTE result" {
    rt_node = Root();
    root_node = TreeNode(id=10, name="root");
    a = TreeNode(id=1, name="a");
    b = TreeNode(id=2, name="b");
    c = TreeNode(id=3, name="c");
    root_node +>:ParentOf:+> a;
    root_node +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    rt_node ++> root_node;

    # Collect ids from the tree.
    cte = CollectSubtree();
    root_node spawn cte;

    # Build a separate collection of Foo nodes — the consumer table.
    f1 = Foo(id=1, label="foo-A");
    f2 = Foo(id=2, label="foo-B");
    f3 = Foo(id=3, label="foo-C");
    f4 = Foo(id=4, label="foo-D");
    f5 = Foo(id=99, label="foo-OTHER");
    rt_node ++> f1 ++> f2 ++> f3 ++> f4 ++> f5;

    # Run the consumer query using CTE ids as the subquery filter.
    buf = io.StringIO();
    consumer = QueryWithSubquery(allowed_ids=cte.collected_ids);
    with redirect_stdout(buf) {
        rt_node spawn consumer;
    }

    # Collected ids are {10, 1, 2, 3}; only Foo nodes with id 1, 2, 3 match.
    assert "foo-A" in consumer.matches,
        f"foo-A should match id=1; got {consumer.matches}";
    assert "foo-B" in consumer.matches,
        f"foo-B should match id=2; got {consumer.matches}";
    assert "foo-C" in consumer.matches,
        f"foo-C should match id=3; got {consumer.matches}";
    assert "foo-D" not in consumer.matches,
        f"foo-D (id=4) must not match; got {consumer.matches}";
    assert "foo-OTHER" not in consumer.matches,
        f"foo-OTHER (id=99) must not match; got {consumer.matches}";
    assert len(consumer.matches) == 3,
        f"expected exactly 3 matches, got {consumer.matches}";
}

# ---------------------------------------------------------------------------
test "subquery with empty CTE result yields no foo matches" {
    rt_node = Root();
    # Tree with a single node — collecting from a fresh, separate subtree
    # gives us an allowed_ids list we can deliberately restrict.
    root_node = TreeNode(id=0, name="only");
    rt_node ++> root_node;

    cte = CollectSubtree();
    root_node spawn cte;

    f1 = Foo(id=1, label="foo-A");
    f2 = Foo(id=2, label="foo-B");
    rt_node ++> f1 ++> f2;

    # Force an empty allowed set to simulate a CTE that yielded nothing.
    consumer = QueryWithSubquery(allowed_ids=[]);
    rt_node spawn consumer;

    assert consumer.matches == [],
        f"empty subquery must yield no matches, got {consumer.matches}";
}

