"""Tests for the Result safety predicate demo (issue #102).

Exercises the four §2.1 carve-outs the predicate must distinguish:
  - populated `cause` chain on a clean ok Result         -> ACCEPT, traverses CausedBy
  - BigInt Map key reproduction (ADR 0015 defect)       -> DROP with specific reason
  - revoked-proxy hostile input                          -> DROP with specific reason
  - ResultChain misinput                                 -> DIAGNOSE (not DROP)
  - ok() shape                                           -> ACCEPT, no chain traversal
  - async kind                                           -> DIAGNOSE
"""

import io;
import from contextlib { redirect_stdout }


def run_audit(rt: Root, label: str = "") -> SafetyAuditor {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = SafetyAuditor();
        rt spawn auditor;
    }
    return auditor;
}


test "clean ok Result is ACCEPT and walks the cause chain" {
    rt = Root();
    ok_node = Result(kind="ok", ok_value="hello");
    cause_a = Cause(label="benign-cause-1");
    cause_b = Cause(label="benign-cause-2");
    rt ++> ok_node +>:CausedBy(note="primary"):+> cause_a
              +>:CausedBy(note="root"):+> cause_b;

    auditor = run_audit(rt);
    assert ok_node.verdict == "ACCEPT", f"clean ok should be ACCEPT, got {ok_node.verdict}";
    assert ok_node.safe is True, f"clean ok should be safe=True, got {ok_node.safe}";
    assert ok_node.reasons == [], f"clean ok should have no reasons, got {ok_node.reasons}";
    assert auditor.cost == 3, f"expected 3 visits (Result + 2 Causes), got {auditor.cost}";
}

test "BigInt key err is DROP with bigint-key-throws-stringify reason" {
    rt = Root();
    err_node = Result(kind="err", err_code="BIGINT_KEY",
                      message="Map key was BigInt");
    cause_a = Cause(label="bigint-map-key");
    cause_b = Cause(label="non-serializable-host");
    rt ++> err_node +>:CausedBy(note="parent"):+> cause_a
              +>:CausedBy(note="root"):+> cause_b;

    auditor = run_audit(rt);
    assert err_node.verdict == "DROP", f"BigInt key must DROP, got {err_node.verdict}";
    assert err_node.safe is False, f"BigInt key err must be safe=False, got {err_node.safe}";
    assert "bigint-key-throws-stringify" in err_node.reasons, f"missing ADR-0015 reason, got {err_node.reasons}";
    assert auditor.cost == 1, f"DROP must disengage on the Result (cost 1), got {auditor.cost}";
}

test "revoked proxy err is DROP with revoked-proxy reason" {
    rt = Root();
    proxy_err = Result(kind="err", err_code="REVOKED_PROXY",
                       message="Proxy access revoked");
    rt ++> proxy_err;

    auditor = run_audit(rt);
    assert proxy_err.verdict == "DROP", f"revoked proxy must DROP, got {proxy_err.verdict}";
    assert proxy_err.safe is False, f"revoked proxy must be safe=False, got {proxy_err.safe}";
    assert "revoked-proxy" in proxy_err.reasons, f"missing revoked-proxy reason, got {proxy_err.reasons}";
    assert auditor.cost == 1, f"DROP on Result alone costs 1 visit, got {auditor.cost}";
}

test "ResultChain misinput is DIAGNOSE not DROP, with distinct reason" {
    rt = Root();
    mis = ResultChain(label="chain-shaped");
    rt ++> mis;

