    assert mis.safe is False, f"ResultChain misinput must be safe=False, got {mis.safe}";
    assert "result-chain-misinput" in mis.reasons, f"missing result-chain-misinput reason, got {mis.reasons}";
    assert auditor.cost == 1, f"DIAGNOSE on ResultChain costs 1 visit, got {auditor.cost}";
