"""Workflowy MCP migration demo: model the stateless MCP handler refactor.

The real issue replaces a stateful Durable Object (``WorkflowyMCP``) with a
stateless ``createMcpHandler`` factory.  The interesting graph problem is the
*tool registry*: nine tools depend on each other (some call others internally)
and share two resources (the D1 mirror ``DB`` and the Workflowy ``API_KEY``).
Cascade teardown of the old DO must drop every tool registration so a fresh
factory can rebuild them in a known order.  We model that as native Jac
nodes/edges and walk it.
"""

node Tool {
    has name: str = "";
    has schema_wrapped: bool = False;
    has deprecated_overload: bool = False;
    has uses_db: bool = True;
    has uses_api_key: bool = True;
}

node Resource {
    has name: str = "";
    has kind: str = "";
}

node LegacyDO {
    has class_name: str = "";
    has deployed: bool = True;
}

edge Registers {
    has order: int = 0;
}

edge Dependson {}

edge MountedOn {}

walker CascadeAudit {
    has visited: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("MCP 2026-07-28 migration audit starting...");
        visit [-->];
    }

    can audit_tool with Tool entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"  cycle hit on tool {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        status = "wrapped" if here.schema_wrapped else "raw(deprecated)";
        print(f"  tool[{here.name}] schema={status}");
        visit [->:Registers:->];
    }

    can audit_resource with Resource entry {
        print(f"  resource[{here.name}] kind={here.kind}");
        visit [->:MountedOn:->];
    }

    can audit_legacy with LegacyDO entry {
        print(f"  legacy DO class={here.class_name} deployed={here.deployed}");
        print("  -> must run wrangler migration with deleted_classes before teardown");
        visit [->:Registers:->];
    }
}

walker CascadeTeardown {
    can start with Root entry {
        print("Cascade teardown: dropping every tool registration on the legacy DO...");
        visit [->:Registers:->];
    }

    can drop_tool with Tool entry {
        print(f"  unregistering tool {here.name}");
        here.schema_wrapped = False;
        here.deprecated_overload = False;
        visit [->:Registers:->];
    }

    can drop_legacy with LegacyDO entry {
        print(f"  destroying DO class {here.class_name}");
        here.deployed = False;
        visit [->:Registers:->];
    }
}

walker RebuildFactory {
    has wired: list[str] = [];

    can start with Root entry {
        print("Rebuilding stateless handler: createMcpHandler(createServer)");
        visit [->:MountedOn:->];
    }

    can rewire with Resource entry {
        print(f"  wiring resource {here.name} ({here.kind}) into factory");
        visit [->:MountedOn:->];
    }

    can retag_tool with Tool entry {
        self.wired.append(here.name);
        print(f"  re-registering {here.name} with z.object() wrapper");
        visit [-->];
    }
}

with entry {
    db = Resource(name="DB", kind="d1_databases");
    api_key = Resource(name="WORKFLOWY_API_KEY", kind="secret");
    oauth_kv = Resource(name="OAUTH_KV", kind="kv_namespaces");

    legacy = LegacyDO(class_name="WorkflowyMCP", deployed=True);

    search_nodes = Tool(name="search_nodes");
    sync_now = Tool(name="sync_now");
    get_node = Tool(name="get_node");
    update_node = Tool(name="update_node");
    delete_node = Tool(name="delete_node");

    # Register order is observable (matches the v1 init() sequence).
    legacy +>:Registers(order=1):+> search_nodes;
    legacy +>:Registers(order=2):+> get_node;
    legacy +>:Registers(order=3):+> update_node;
    legacy +>:Registers(order=4):+> delete_node;
