"""Tests for the Hiking trail program."""

import io;
import from contextlib { redirect_stdout }

# Helper: capture stdout from spawning a Hiker on a root
def run_hiker(target: int = 3) -> tuple {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target=target);
    }
    return (buf.getvalue(), res);
}

test "hiker stops at every waypoint and counts them" {
    root ++> Waypoint(title="Trailhead", elevation=1200)
        ++> Waypoint(title="Meadow Bend", elevation=1480)
        ++> Waypoint(title="Ridge Crossing", elevation=1820)
        ++> Waypoint(title="Lookout Knob", elevation=2150)
        ++> Waypoint(title="Summit", elevation=2450);

    (out, res) = run_hiker(target=99);

    # Should have visited every waypoint (5 total)
    assert res.stops == 5, f"expected 5 stops, got {res.stops}";

    # Each waypoint should appear in the output with Stop #N: TITLE at ELEVATIONm
    assert "Stop #1: Trailhead at 1200m" in out, f"missing trailhead stop: {out}";
    assert "Stop #2: Meadow Bend at 1480m" in out, f"missing meadow stop: {out}";
    assert "Stop #3: Ridge Crossing at 1820m" in out, f"missing ridge stop: {out}";
    assert "Stop #4: Lookout Knob at 2150m" in out, f"missing lookout stop: {out}";
    assert "Stop #5: Summit at 2450m" in out, f"missing summit stop: {out}";

    # With target=99 we never hit completion
    assert "Trail complete" not in out, f"should not be complete: {out}";
}

test "hiker disengages after reaching target count" {
    root ++> Waypoint(title="A", elevation=100)
        ++> Waypoint(title="B", elevation=200)
        ++> Waypoint(title="C", elevation=300)
        ++> Waypoint(title="D", elevation=400);

    (out, res) = run_hiker(target=3);

    assert res.stops == 3, f"expected 3 stops (target met), got {res.stops}";
    assert "Stop #1: A at 100m" in out, f"missing A: {out}";
    assert "Stop #2: B at 200m" in out, f"missing B: {out}";
    assert "Stop #3: C at 300m" in out, f"missing C: {out}";
    assert "Trail complete after 3 waypoints." in out, f"missing completion line: {out}";
    # D should never be reached because we disengaged after #3
    assert "Stop #4" not in out, f"should not reach D: {out}";
    assert "D at 400m" not in out, f"should not print D: {out}";
}

test "hiker with default target of 3 disengages early on long chain" {
    root ++> Waypoint(title="T0", elevation=0)
        ++> Waypoint(title="T1", elevation=1)
        ++> Waypoint(title="T2", elevation=2)
        ++> Waypoint(title="T3", elevation=3)
        ++> Waypoint(title="T4", elevation=4);

    # Using default target=3
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stops == 3, f"expected 3 stops with default target, got {res.stops}";
    assert "Stop #1: T0" in out, f"missing T0: {out}";
    assert "Stop #2: T1" in out, f"missing T1: {out}";
    assert "Stop #3: T2" in out, f"missing T2: {out}";
    assert "Trail complete after 3 waypoints." in out, f"missing completion: {out}";
    assert "T3" not in out, f"should not reach T3: {out}";
    assert "T4" not in out, f"should not reach T4: {out}";
}

test "hiker disengages if there are no waypoints" {
    # root has no outgoing edges to Waypoint nodes
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target=3);
    }
    out = buf.getvalue();

    assert res.stops == 0, f"expected 0 stops with no waypoints, got {res.stops}";
    assert out == "", f"expected no output, got {out!r}";
}

test "trail is a single chain from trailhead to summit" {
    # Build the same chain as the demo
    root ++> Waypoint(title="Trailhead", elevation=1200)
        ++> Waypoint(title="Meadow Bend", elevation=1480)
        ++> Waypoint(title="Ridge Crossing", elevation=1820)
        ++> Waypoint(title="Lookout Knob", elevation=2150)
        ++> Waypoint(title="Summit", elevation=2450);

    # root should have exactly ONE direct child (chain start)
    direct = [root -->];
    assert len(direct) == 1, f"expected 1 direct child of root, got {len(direct)}";

    # Walk the chain: there should be exactly 5 waypoints reachable total
    cur = direct[0];
    count = 1;
    nexts = [cur -->];
    while len(nexts) > 0 {
        assert len(nexts) == 1, f"expected chain node {cur.title} to have 1 next, got {len(nexts)}";
        cur = nexts[0];
        count += 1;
        nexts = [cur -->];
    }
    assert count == 5, f"expected 5 waypoints in chain, got {count}";
    assert cur.title == "Summit", f"expected chain to end at Summit, got {cur.title}";
    assert cur.elevation == 2450, f"expected summit elevation 2450, got {cur.elevation}";
}

