"""Orchard maintenance walk: log pumps and sprinklers, reset idle counters, report totals."""

node Device {
    has label: str = "";
    has kind: str = "";
    has idle_hours: int = 0;

    def reset_idle() {
        self.idle_hours = 0;
    }
}

node Pump(Device) {
    has kind: str = "pump";
    has gph: int = 0;
}

node Sprinkler(Device) {
    has kind: str = "sprinkler";
    has radius_ft: int = 0;
