    can start with Root entry {
        print("Crew beginning orchard tour");
        visit [-->] else { disengage; }
    }

    can service with Pump | Sprinkler entry {
        label = f"[{here.kind.upper()}] {here.label}";
        print(f"{label} idle for {here.idle_hours}h — servicing now");
        here.reset_idle();
        self.serviced += 1;
        report label;
    }

    can continue_walk with Pump | Sprinkler exit {
        visit [-->] else { disengage; }
    }
}

with entry {
    grove_a = Pump(label="North-well", gph=400, idle_hours=12);
    grove_b = Sprinkler(label="Row-3-sprinkler", radius_ft=15, idle_hours=48);
    grove_c = Pump(label="Reserve-pump", gph=250, idle_hours=3);
    root ++> grove_a ++> grove_b ++> grove_c;

    crew = Crew();
    root spawn crew;

    print(f"Devices serviced this round: {crew.serviced}");
}
