        if here.fraud {
            print(f"[HALT] Fraud detected on order '{here.title}' (${here.amount}) - audit aborted");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] Invalid order '{here.title}' (${here.amount}) - continuing");
            visit [-->];
        }
        print(f"[OK] Audited order '{here.title}' (${here.amount})");
        visit [-->];
    }
}

with entry {
    root ++> Order(title="Order-A", amount=120.50)
        ++> Order(title="Order-B", amount=75.00, valid=False)
        ++> Order(title="Order-C", amount=240.00)
        ++> Order(title="Order-D", amount=99.99, fraud=True)
        ++> Order(title="Order-E", amount=310.25);
    root spawn OrderAuditor();
}
