"""Warehouse packing line: stations announce the robot they serve, robots announce every station they stop at.

Models a three-station line. Stations emit a "serving Robot X" announcement
when a robot arrives; robots emit a "stopped at Station N" announcement at
each station. We count stops per robot and boxes packed per station.
"""

node Station {
    has label: str = "";
    has boxes_packed: int = 0;
}

walker RobotRunner {
    has robot_id: str = "";
    has stops: int = 0;

    can announce with Station entry {
        print(f"Robot {self.robot_id}: stopped at Station {here.label}");
        self.stops += 1;
        here.boxes_packed += 1;
        print(f"Station {here.label}: serving Robot {self.robot_id}");
        visit [-->] else { disengage; }
    }

    can start with Root entry {
        visit [-->];
    }
}

with entry {
    s1 = Station(label="1");
    s2 = Station(label="2");
    s3 = Station(label="3");
    root ++> s1 ++> s2 ++> s3;

    for rid in ["R-A", "R-B", "R-C"] {
        runner = RobotRunner(robot_id=rid);
        root spawn runner;
    }
}
