                        xlsx_aggregate="pass_count:7");
    second = ActionTrace(base_action="shot", outcome="saved",
                         qualifier="header", progression="transition",
                         direction="forward", distance="short",
                         gk_relation="saved", team_reflection="final_third",
                         xlsx_aggregate="shot_count:2");

    root ++> m;
    m +>:HasActor:+> actor;
    actor +>:HasTrace:+> first;
    first +>:Follows:+> second;

    buf = io.StringIO();
