        analyst = root spawn AnalystTrace();
    }
    out = buf.getvalue();

    assert analyst.visited == ["pass|complete|through_ball", "shot|saved|header"], f"got {analyst.visited}";
    assert analyst.interpretation == "interpreter: rhythm_change after final_third", f"got {analyst.interpretation}";
    assert "[action] pass (through_ball) x=pass_count:7" in out, f"missing pass action: {out}";
