    assert "[action] shot (header) x=shot_count:2" in out, f"missing shot action: {out}";
}

test "analyst guard stops a repeated action cycle" {
    m = Match(match_id="M-103", period=1, minute=44);
    actor = Actor(actor_id="A-9", name="Striker", team_id="T-HOME");
    first = ActionTrace(base_action="pass", outcome="complete", qualifier="through_ball");
    second = ActionTrace(base_action="shot", outcome="saved", qualifier="header");

    root ++> m;
    m +>:HasActor:+> actor;
    actor +>:HasTrace:+> first;
    first +>:Follows:+> second;
    second +>:Follows:+> first;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        analyst = root spawn AnalystTrace();
    }
    out = buf.getvalue();

    assert len(analyst.visited) == 2, f"visited {analyst.visited}";
    assert analyst.visited[0] == "pass|complete|through_ball", f"got {analyst.visited}";
    assert analyst.visited[1] == "shot|saved|header", f"got {analyst.visited}";
    assert "repeated pattern detected: pass|complete|through_ball" in out, f"missing cycle marker: {out}";
}

