"""Employee management foundation: self-referencing org hierarchy with
recursive traversal, lifecycle history, and deletion-policy checks.

Models the essential scenario from the issue using native Jac archetypes
(typed edges + walker traversal) instead of hand-rolled recursion."""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Employee {
    has employee_number: str = "";
    has first_name: str = "";
    has last_name: str = "";
    has status: str = "ACTIVE";        # ACTIVE | TERMINATED | SUSPENDED
    has employment_type: str = "FULL_TIME";  # FULL_TIME | PART_TIME | CONTRACT | INTERN
    has hire_date: str = "";
    has department: str = "";
    has position: str = "";
    has full_name: str = "";
    has tenure_years: int = 0;
    has has_payroll_history: bool = False;
    has has_leave_history: bool = False;
    has has_active_leave_request: bool = False;
}

node EmploymentEvent {
    has event_type: str = "HIRE";     # HIRE | TRANSFER | PROMOTION | DEMOTION | SALARY_ADJUSTMENT | TERMINATION
    has event_date: str = "";
    has notes: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges: relationships carry meaning, so they are typed.
# ---------------------------------------------------------------------------

edge ReportsTo { }      # employee -> manager (self-referencing hierarchy)
edge HasEvent { }       # employee -> EmploymentEvent (lifecycle history)

# ---------------------------------------------------------------------------
# Walker: recursive org-tree walk + deletion-policy audit + history dump.
# Carries an explicit visited set because jac 0.36.1 walkers have no
# built-in once-per-node visitation (a manager reachable via two report
# lines would otherwise be counted twice / looped over).
# ---------------------------------------------------------------------------

walker HierarchyAuditor {
    has visited_ids: list = [];
    has chain: list = [];
    has events_seen: int = 0;
    has blocked_deletions: list = [];
    has terminated_with_leave: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Recursive descent: walk every direct report (typed edge) and audit.
    can audit with Employee entry {
        # Cycle / re-entry guard (domain logic: source recurses over a
        # self-referencing FK, which can cycle in corrupt data).
        already = False;
        for vid in self.visited_ids {
            if vid == here {
                already = True;
            }
        }
        if already {
            print(f"[cycle/seen] skipping {here.full_name}");
            disengage;
        }
        self.visited_ids.append(here);

        # Build the reporting chain as we descend.
        self.chain.append(here.full_name);
        print(
            f"  {'  ' * (len(self.chain) - 1)}{here.full_name} "
            f"({here.employee_number}) — {here.position}, "
            f"{here.department}, status={here.status}, "
            f"tenure={here.tenure_years}y"
        );

        # BR-HCM-001: cannot delete if payroll or leave history exists.
        if here.has_payroll_history or here.has_leave_history {
            reason = "payroll_history" if here.has_payroll_history else "leave_history";
            self.blocked_deletions.append((here.full_name, reason));
        }

        # BR-HCM-003: cannot terminate employee with active leave requests.
        if here.status == "TERMINATED" and here.has_active_leave_request {
            self.terminated_with_leave.append(here.full_name);
        }

        # Recurse through the self-referencing manager edge.
        visit [->:ReportsTo:->];
    }

    # Lifecycle history side: collect events on a separate traversal.
    can collect_events with EmploymentEvent entry {
        self.events_seen = self.events_seen + 1;
        print(f"  history: {here.event_type} on {here.event_date} — {here.notes}");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo: build a small tenant with a 3-level hierarchy, a terminated-but-
# blocked employee, and a cyclic edge to exercise the cycle guard.
