"""Semantic dependency graph with typed edges and explicit cycle detection."""

node WitnessCase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
}

node SemanticFact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has exact_value: str = "";
    has invalidated: bool = False;
}

node EvaluationPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has effect_summary: str = "";
}

edge Supports { }
edge DependsOn { }
edge LowersTo { }

walker SemanticAudit {
    has seen: list[str] = [];

    can start with Root entry {
        print("auditing semantic witnesses");
        visit [-->] else { disengage; }
    }

    can inspect_witness with WitnessCase entry {
        print(f"witness: {here.title}");
        visit [->:Supports:->] else { disengage; }
    }

    can inspect_fact with SemanticFact entry {
        if here.key in self.seen {
            print(f"cycle refused at {here.title}");
            disengage;
        } else {
            self.seen.append(here.key);
            status = "invalidated" if here.invalidated else "current";
            print(f"fact: {here.title} [{status}] = {here.exact_value}");
            visit [->:DependsOn:->] else { disengage; }
        }
    }

    can inspect_plan with EvaluationPlan entry {
        print(f"bounded plan: {here.title} ({here.effect_summary})");
        visit [-->] else { disengage; }
    }
}

with entry {
    witness = WitnessCase(
        title="short-circuit witness",
        year=2025,
        key="u07-short-circuit"
    );
    context_fact = SemanticFact(
        title="boolean context",
        year=2025,
        key="context",
        exact_value="scalar"
    );
    value_fact = SemanticFact(
        title="constant value",
        year=2025,
        key="value",
        exact_value="defined",
        invalidated=True
    );
    plan = EvaluationPlan(
        title="bounded EIR evaluation",
        year=2025,
        key="eir",
        effect_summary="pure and resource-bounded"
    );

    root ++> witness;
    witness +>:Supports:+> context_fact;
    context_fact +>:DependsOn:+> value_fact;
    value_fact +>:DependsOn:+> context_fact;
    value_fact +>:LowersTo:+> plan;

    root spawn SemanticAudit();
}
