test "audits dependency cycle and refuses repeat" {
    witness = WitnessCase(
        title="short-circuit witness",
        year=2025,
        key="u07-short-circuit"
    );
    context_fact = SemanticFact(
        title="boolean context",
        year=2025,
        key="context",
        exact_value="scalar"
    );
    value_fact = SemanticFact(
        title="constant value",
        year=2025,
        key="value",
        exact_value="defined"
    );
    plan = EvaluationPlan(
        title="bounded EIR evaluation",
        year=2025,
        key="eir",
        effect_summary="pure and resource-bounded"
    );

    root ++> witness;
    witness +>:Supports:+> context_fact;
    context_fact +>:DependsOn:+> value_fact;
    value_fact +>:DependsOn:+> context_fact;
    value_fact +>:LowersTo:+> plan;

    assert len([root-->]) == 1, f"got {len([root-->])}";
    assert witness in [root-->], f"missing witness";
    assert context_fact in [witness ->:Supports:->], f"missing context fact";
    assert value_fact in [context_fact ->:DependsOn:->], f"missing value fact";
    assert context_fact in [value_fact ->:DependsOn:->], f"missing cycle edge";
    assert plan in [value_fact ->:LowersTo:->], f"missing lowering edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SemanticAudit();
    }
    out = buf.getvalue();

    assert "auditing semantic witnesses" in out, f"got {out}";
    assert "witness: short-circuit witness" in out, f"got {out}";
    assert "fact: boolean context [current] = scalar" in out, f"got {out}";
    assert "fact: constant value [current] = defined" in out, f"got {out}";
    assert "cycle refused at boolean context" in out, f"got {out}";
}

test "reports invalidation and bounded plan effects" {
    witness = WitnessCase(
        title="folding witness",
        year=2025,
        key="u08-folding"
    );
    invalid_fact = SemanticFact(
        title="stale constant",
        year=2025,
        key="stale",
        exact_value="unknown",
        invalidated=True
    );
    plan = EvaluationPlan(
        title="bounded evaluation",
        year=2025,
        key="bounded",
        effect_summary="resource-bounded"
    );

    root ++> witness;
    witness +>:Supports:+> invalid_fact;
    invalid_fact +>:LowersTo:+> plan;

    assert invalid_fact.invalidated == True, f"got {invalid_fact.invalidated}";
    assert plan in [invalid_fact ->:LowersTo:->], f"missing plan edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn SemanticAudit();
        plan spawn SemanticAudit();
    }
