    assert "fact: stale constant [invalidated] = unknown" in out, f"got {out}";
    assert "bounded plan: bounded evaluation (resource-bounded)" in out, f"got {out}";
}

test "follows dependency edges but not lowering edges" {
    witness = WitnessCase(
        title="ordering witness",
