"""Flight network: priced legs normalize against the scout's peak fare report."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has origin_code: str = "";
    has dest_code: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.price / peak;
    }
}

walker FareScout {
    has peak_fare: float = 0.0;
    has fare_report: list[float] = [];
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can sweep with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.fare_report.append(leg.price);
            if leg.price > self.peak_fare {
                self.peak_fare = leg.price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");
    bos = Airport(code="BOS");

    root ++> jfk;

    leg_jfk_lax = FlightLeg(
        price=450.0, origin_code="JFK", dest_code="LAX"
    );
    jfk +>:leg_jfk_lax:+> lax;

    leg_lax_ord = FlightLeg(
        price=320.0, origin_code="LAX", dest_code="ORD"
    );
    lax +>:leg_lax_ord:+> ord;

    leg_ord_bos = FlightLeg(
        price=580.0, origin_code="ORD", dest_code="BOS"
    );
    ord +>:leg_ord_bos:+> bos;

    leg_bos_jfk = FlightLeg(
        price=275.0, origin_code="BOS", dest_code="JFK"
    );
    bos +>:leg_bos_jfk:+> jfk;

    leg_jfk_ord = FlightLeg(
        price=510.0, origin_code="JFK", dest_code="ORD"
    );
    jfk +>:leg_jfk_ord:+> ord;

    scout = FareScout();
    root spawn scout;

    peak = scout.peak_fare;
    print(
        f"Scout peak fare: ${peak} "
        f"(reported {len(scout.fare_report)} prices)"
    );

    legs = [
        leg_jfk_lax,
        leg_lax_ord,
        leg_ord_bos,
        leg_bos_jfk,
        leg_jfk_ord,
    ];
    for leg in legs {
        share = leg.fare_fraction(peak);
        print(
            f"{leg.origin_code}->{leg.dest_code} "
            f"${leg.price} is {share:.2%} of top fare"
        );
    }
}
