"""Regression tests for the worktree-adoption parent-removal guard.

Each test builds a fresh graph and runs the Archiver walker the way
ArchiveService would. We assert:

  * archiving an *adopted* worktree refuses to touch the parent, walks
    every SharesParent neighbor, and surfaces the would-be collateral;
  * archiving an *internal* worktree is allowed and removes nothing
    outside the worktree itself;
  * a target_task that does not match any worktree does not mutate the
    walker's blocked/collateral state;
  * cyclic SharesParent edges do not send the audit into an infinite
    loop (visited-guard works).
"""

import io;
import from contextlib { redirect_stdout }

# ---- 1. adopted worktree: parent removal must be blocked and the
#         collateral list must enumerate every node sharing the parent.

test "adopted worktree archive is refused and reports collateral" {
    parent = "/tmp/dp-adopted";
    repo = Repo(name="repo", parent_dir=parent);
    adopted = Worktree(
        branch="feature",
        path=f"{parent}/repo.feature",
        adopted=True,
        task_id="task-A"
    );
    sent = Sibling(label=f"{parent}/unrelated-sentinel");

    root ++> repo;
    root ++> adopted;
    root ++> sent;

    repo +>:HasWorktree(since="2026-08-11"):+> adopted;
    adopted +>:SharesParent(parent_dir=parent):+> repo;
    adopted +>:SharesParent(parent_dir=parent):+> sent;
    repo +>:SharesParent(parent_dir=parent):+> sent;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Archiver(target_task="task-A");
    }
    out = buf.getvalue();

    assert res.blocked is True, f"adopted archive must be blocked, got blocked={res.blocked}";

    # The audit must enumerate the main repo, the adopted worktree itself,
    # and the unrelated sentinel -- three distinct labels.
    assert len(res.collateral) == 3, (
        f"expected 3 collateral labels, got {len(res.collateral)}: {res.collateral}"
    );

    repo_label = f"repo:repo at {parent}/repo";
    wt_label = "worktree[adopted]:" + f"{parent}/repo.feature";
    sent_label = f"sibling:{parent}/unrelated-sentinel";

    assert repo_label in res.collateral, f"main repo not listed: {res.collateral}";
    assert wt_label in res.collateral, f"adopted worktree not listed: {res.collateral}";
    assert sent_label in res.collateral, f"unrelated sentinel not listed: {res.collateral}";

    # The guard's refusal marker must be on stdout so the caller can act.
    assert "[blocked]" in out, f"missing [blocked] marker: {out}";
    assert "refusing to remove parent" in out, f"missing refusal message: {out}";

    # The shared-parent directory itself is never added as collateral --
    # only the entries that would have been destroyed are listed.
    assert parent not in res.collateral, (
        f"parent dir {parent} leaked into collateral: {res.collateral}"
    );
}

# ---- 2. internal worktree: archive is allowed and only the worktree
#         itself appears in the collateral list (no SharesParent blast).

test "internal worktree archive is allowed and stays local" {
    safe_path = "~/.posthog-code/worktrees/repo/repo.bugfix";
    wt = Worktree(
        branch="bugfix",
        path=safe_path,
        adopted=False,
        task_id="task-I"
    );
    root ++> wt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Archiver(target_task="task-I");
    }
    out = buf.getvalue();

    assert res.blocked is False, (
        f"internal archive must NOT be blocked, got blocked={res.blocked}"
    );
    assert res.collateral == [safe_path], (
        f"internal collateral should be exactly [{safe_path}], got {res.collateral}"
    );
    assert "[internal]" in out, f"missing [internal] marker: {out}";
    assert "[blocked]" not in out, f"internal archive wrongly reported blocked: {out}";
}

# ---- 3. unknown task id: walker must not invent collateral or block.

test "unknown task id leaves walker state untouched" {
    parent = "/tmp/dp-unknown";
    repo = Repo(name="repo", parent_dir=parent);
    adopted = Worktree(
        branch="feature",
        path=f"{parent}/repo.feature",
        adopted=True,
        task_id="task-real"
    );
    root ++> repo;
    root ++> adopted;
    repo +>:HasWorktree(since="2026-08-11"):+> adopted;
    adopted +>:SharesParent(parent_dir=parent):+> repo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Archiver(target_task="task-does-not-exist");
    }

    assert res.blocked is False, (
        f"unmatched task must not flip blocked=True, got {res.blocked}"
    );
    assert res.collateral == [], (
        f"unmatched task must leave collateral empty, got {res.collateral}"
    );
}

# ---- 4. cyclic SharesParent edges: the visited-guard prevents an
#         infinite walk and still produces the full collateral list.

test "cyclic SharesParent edges do not loop the audit" {
    parent = "/tmp/dp-cycle";
    repo = Repo(name="repo", parent_dir=parent);
    adopted = Worktree(
        branch="feature",
        path=f"{parent}/repo.feature",
        adopted=True,
        task_id="task-C"
    );
    sent = Sibling(label=f"{parent}/unrelated-sentinel");

    root ++> repo;
    root ++> adopted;
    root ++> sent;

    # Bidirectional SharesParent edges -- a cycle by construction.
    adopted +>:SharesParent(parent_dir=parent):+> repo;
    repo +>:SharesParent(parent_dir=parent):+> adopted;
    adopted +>:SharesParent(parent_dir=parent):+> sent;
    sent +>:SharesParent(parent_dir=parent):+> adopted;
    repo +>:SharesParent(parent_dir=parent):+> sent;
    sent +>:SharesParent(parent_dir=parent):+> repo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Archiver(target_task="task-C");
    }

    # Each node labeled exactly once -- no duplicates despite the cycles.
    assert res.blocked is True, f"cyclic adopted archive must be blocked, got {res.blocked}";
    assert len(res.collateral) == 3, (
        f"cyclic audit must yield 3 unique labels, got {len(res.collateral)}: {res.collateral}"
    );

    repo_label = f"repo:repo at {parent}/repo";
    wt_label = "worktree[adopted]:" + f"{parent}/repo.feature";
    sent_label = f"sibling:{parent}/unrelated-sentinel";

    assert res.collateral.count(repo_label) == 1, f"repo label duplicated: {res.collateral}";
    assert res.collateral.count(wt_label) == 1, f"worktree label duplicated: {res.collateral}";
    assert res.collateral.count(sent_label) == 1, f"sibling label duplicated: {res.collateral}";
}

