```jac
"""SPF recursive dependency graph: model nested include/redirect chains, cycle detection, and lookup budget."""

# Domain archetypes
node Domain {
    has name: str = "";
    has spf_record: str = "";
    has lookup_count: int = 0;
    has void_lookups: int = 0;
    has failures: int = 0;
    has dynamic_terms: int = 0;
    has est_response_bytes: int = 0;
}

# Reference: this domain points to another domain via include/redirect/mx/a mechanisms
edge Ref {
    has mechanism: str = "";
    has qualifier: str = "pass";
}

# Walker that performs the recursive SPF dependency walk
walker SpfAuditor {
    has max_depth: int = 5;
    has max_lookups: int = 10;
    has visited: list[str] = [];
    has depth: int = 0;
    has budget_remaining: int = 10;
    has cycles_found: int = 0;
    has void_lookups: int = 0;
    has failures: int = 0;
    has dynamic_terms: int = 0;
    has est_response_bytes: int = 0;
    has dependency_order: list[str] = [];

    can start with Root entry {
        print("SPF recursive dependency audit starting");
        visit [-->];
    }

    can audit with Domain entry {
        # Cycle detection
        if here.name in self.visited {
            self.cycles_found += 1;
            print(f"[CYCLE] already visited {here.name}");
            self.budget_remaining = 0;
            disengage;
        }

        # Depth limit
        if self.depth >= self.max_depth {
            self.failures += 1;
            print(f"[DEPTH-LIMIT] at depth {self.depth} for {here.name}");
            disengage;
        }

        # Lookup budget check
        if self.budget_remaining <= 0 {
            self.failures += 1;
            print(f"[BUDGET-EXHAUSTED] cannot inspect {here.name}");
            disengage;
        }

        # Account for the SPF record lookup itself
        self.visited.append(here.name);
        self.budget_remaining -= 1;
        self.depth += 1;
        here.lookup_count = self.depth;
        self.dependency_order.append(here.name);
        self.est_response_bytes += len(here.spf_record);

        # Detect void lookups (empty records)
        if here.spf_record == "" {
            self.void_lookups += 1;
            print(f"[VOID] {here.name} has empty SPF record");
            disengage;
        }

        # Detect dynamic terms (exists: and macros)
        if "exists:" in here.spf_record or "%{" in here.spf_record {
            self.dynamic_terms += 1;
        }

        print(f"[INSPECT depth={self.depth} budget={self.budget_remaining}] {here.name}: {here.spf_record}");

        # Traverse typed reference edges to dependencies
        visit [->:Ref:->] else { disengage; }
    }
}

with entry {
    # Build a small SPF dependency graph with a cycle and varied mechanisms
    a = Domain(name="example.com", spf_record="v=spf1 include:_spf.example.com -all");
    b = Domain(name="_spf.example.com", spf_record="v=spf1 include:vendor.com mx -all");
    c = Domain(name="vendor.com", spf_record="v=spf1 ip4:192.0.2.0/24 a -all");
    d = Domain(name="mail.vendor.com", spf_record="v=spf1 ip4:198.51.100.1 -all");
