    b +>:Ref(mechanism="include"):+> c;
    c +>:Ref(mechanism="mx"):+> d;
    c +>:Ref(mechanism="include"):+> e;

    auditor = SpfAuditor(max_depth=5, max_lookups=10);
    root spawn auditor;

    print("--- AUDIT SUMMARY ---");
    print(f"Dependency order: {auditor.dependency_order}");
    print(f"Total lookups consumed: {len(auditor.dependency_order)}");
    print(f"Cycles found: {auditor.cycles_found}");
    print(f"Void lookups: {auditor.void_lookups}");
    print(f"Failures (depth/budget): {auditor.failures}");
    print(f"Dynamic terms seen: {auditor.dynamic_terms}");
    print(f"Est. response bytes: {auditor.est_response_bytes}");
