"""Test annex for the maze Pathfinder."""

import io;
import from contextlib { redirect_stdout }

node Cell { has row: int = 0; has col: int = 0; has is_exit: bool = False; }
edge Open { has direction: str = ""; }
walker Pathfinder {
    has trail: list[str] = [];
    has found: bool = False;
    has seen: list[str] = [];
}

test "straight corridor finds exit and prints path" {
    # Build a 1x4 straight corridor: entrance -> three open cells -> exit.
    c00 = Cell(row=0, col=0);
    c01 = Cell(row=0, col=1);
    c02 = Cell(row=0, col=2);
    c03 = Cell(row=0, col=3, is_exit=True);
    c00 +>:Open(direction="E"):+> c01;
    c01 +>:Open(direction="E"):+> c02;
    c02 +>:Open(direction="E"):+> c03;
    root ++> c00;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Pathfinder();
    }
    out = buf.getvalue();

    # Exit must have been located.
    assert res.found == True, f"expected found=True, got {res.found}";

    # Printed path must contain the header and all four coords in order.
    assert "Path to exit:" in out, f"missing header in: {out}";
    assert "(0,0)" in out, f"missing start in: {out}";
    assert "(0,3)" in out, f"missing exit in: {out}";

    # Trail must record the exact route taken through the corridor.
    assert res.trail == ["(0,0)", "(0,1)", "(0,2)", "(0,3)"], (
        f"unexpected trail: {res.trail}"
    );
}

test "dead end forces backtrack and still finds exit" {
    # A T-shape with a dead end on one branch. DFS should explore the
    # dead end first (depth-first), backtrack, then take the other branch
    # to the exit.
    start = Cell(row=0, col=0);
    a = Cell(row=0, col=1);   # leads to dead end
    dead = Cell(row=0, col=2);
    b = Cell(row=1, col=1);   # leads to exit
    exit_c = Cell(row=2, col=1, is_exit=True);

    start +>:Open(direction="E"):+> a;
    a +>:Open(direction="E"):+> dead;       # dead end, no further edges
    a +>:Open(direction="S"):+> b;
    b +>:Open(direction="S"):+> exit_c;

    root ++> start;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Pathfinder();
    }

    assert res.found == True, f"expected to find exit, got found={res.found}";

    # Trail must visit start, then walk into the dead end (depth-first),
    # then back out and continue to the exit.
    assert res.trail[0] == "(0,0)", f"trail must start at entrance: {res.trail}";
    assert "(0,2)" in res.trail, f"trail should have probed the dead end: {res.trail}";
    assert res.trail[-1] == "(2,1)", f"trail must end at exit: {res.trail}";

    # The dead end must appear BEFORE the south branch in the trail
    # (i.e. depth-first push, not breadth-first).
    dead_idx = res.trail.index("(0,2)");
    south_idx = res.trail.index("(1,1)");
    assert dead_idx < south_idx, (
        f"dead end should be visited before branching south; "
        f"dead_idx={dead_idx}, south_idx={south_idx}, trail={res.trail}"
    );

    # seen list must be unique (cycle guard).
    assert len(res.seen) == len(set(res.seen)), (
        f"seen must contain no duplicates: {res.seen}"
    );
}

test "no path to exit leaves found False" {
    # Entrance connects to a single open cell, but neither is the exit and
    # neither has any onward edge to an exit. The walker should exhaust
    # reachable cells and report not found.
    start = Cell(row=0, col=0);
    n1 = Cell(row=0, col=1);
    n2 = Cell(row=1, col=0);  # orphan with no edges
    start +>:Open(direction="E"):+> n1;
    root ++> start;
    root ++> n2;

    res = root spawn Pathfinder();

    assert res.found == False, f"expected found=False, got {res.found}";

    # The walker should have visited the reachable cells but stopped
    # without printing a path. Since the spec only prints on success,
    # we verify no "Path to exit:" header was emitted by checking that
    # the trail does NOT contain an exit coordinate.
    for step in res.trail {
        assert "(-1" not in step, f"unexpected exit coord in trail: {res.trail}";
    }

    # Both reachable cells should appear in seen (DFS exhausted them).
    assert "(0,0)" in res.seen, f"entrance should be in seen: {res.seen}";
    assert "(0,1)" in res.seen, f"reachable neighbor should be in seen: {res.seen}";
}

test "entrance is itself the exit" {
    # Trivial maze: the entrance is the exit. The walker should immediately
    # detect is_exit on the very first Cell it enters and report.
    start = Cell(row=2, col=2, is_exit=True);
    root ++> start;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Pathfinder();
    }
    out = buf.getvalue();

    assert res.found == True, f"expected found=True, got {res.found}";
    assert "Path to exit:" in out, f"missing path header in: {out}";
    assert "(2,2)" in out, f"missing entrance/exit coord in: {out}";

    # Trail must contain the single starting cell.
    assert res.trail == ["(2,2)"], f"trail should be just the start, got {res.trail}";
}

test "cycle is handled without infinite loop" {
    # A small loop: start -> a -> b -> back to start, with the exit one
    # step off the cycle. The cycle guard (seen list) must keep DFS finite.
    start = Cell(row=0, col=0);
    a = Cell(row=0, col=1);
    b = Cell(row=1, col=1);
    exit_c = Cell(row=1, col=2, is_exit=True);

    start +>:Open(direction="E"):+> a;
    a +>:Open(direction="S"):+> b;
    b +>:Open(direction="W"):+> start;   # creates a cycle
    b +>:Open(direction="E"):+> exit_c;

    root ++> start;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Pathfinder();
    }
    out = buf.getvalue();

    assert res.found == True, f"expected to escape cycle and find exit, got {res.found}";
    assert "(1,2)" in out, f"exit coord should be printed: {out}";

    # The cycle means start is reachable from itself, but the seen guard
    # must prevent re-entry. seen should have no duplicates and a bounded
    # length (at most the reachable cells, which is 4).
    assert len(res.seen) == len(set(res.seen)), (
        f"seen must be duplicate-free (cycle guard failed): {res.seen}"
    );
    assert len(res.seen) <= 4, (
        f"seen should be bounded by reachable cells; got {len(res.seen)}: {res.seen}"
    );

    # Trail must end at the exit.
    assert res.trail[-1] == "(1,2)", f"trail should end at exit: {res.trail}";
}
```

