"""Registry identity audit: walk organization membership to scoped publishers and packages."""

node Principal {
    has subject: str = "";
    has kind: str = "human";
    has role: str = "publisher";
    has active: bool = True;
}

node Organization {
    has registry_id: str = "";
    has slug: str = "";
    has display_name: str = "";
}

node Package {
    has name: str = "";
    has owner_id: str = "";
    has publisher_mode: str = "self";
    has visibility: str = "public";
    has invalidated: bool = False;
}

edge Membership: Organization --> Principal {
    has role: str = "publisher";
}

edge Publishes: Principal --> Package {
    has scope: str = "";
}

walker AuthorityAudit {
    has published_count: int = 0;
    has reports: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_org with Organization entry {
        print(f"org {here.display_name} [{here.registry_id}]");
        visit [here ->:Membership:->] else { disengage; }
    }

    can inspect_principal with Principal entry {
        if here.active and (here.role == "publisher" or here.role == "admin") {
            print(f"active {here.kind} {here.subject} as {here.role}");
            visit [here ->:Publishes:->] else { disengage; }
        } else {
            print(f"revoked {here.kind} {here.subject}; no package traversal");
        }
