    has threshold: float = 40.0;

    can start with Root entry {
        print("Health inspector beginning kitchen line walk-through");
        visit [-->] else { disengage; }
    }

    # Union trigger: fires for ANY station type. Both abilities below are
    # bound to the same Station archetype, so every station triggers both.
    can inspect with Station entry {
        # --- Temperature check ---
        if here.temperature > self.threshold {
            here.violations += 1;
            self.violation_count += 1;
            verdict = "VIOLATION";
        } else {
            verdict = "OK";
        }
        # --- Visit log ---
        self.visited.append(here.name);
        print(
            f"[{verdict}] {here.name} @ {here.temperature} C "
            f"(lifetime violations: {here.violations})"
        );
        visit [-->] else { disengage; }
    }
}

with entry {
