    greeter = Greeter(origin="Oak", target="Maple");
    with redirect_stdout(buf) {
        oak spawn greeter;
    }
    out = buf.getvalue();

    assert greeter.reached, "Oak greeter must reach Maple via forward traversal only";
    assert "[Oak] reached buddy house 'Maple'" in out, f"missing Maple greeting in output: {out}";
}


test "greeter cannot bounce back and forth forever" {
    # Only a single node wired back to itself via Buddy edges; the cycle
    # guard (visited flag + next_nodes filtering) must prevent infinite
    # bouncing and produce a dead-end.
    maple = House(name="Maple");
    maple +>:Buddy(since="2024"):+> maple;
    root ++> maple;

    buf = io.StringIO();
    greeter = Greeter(origin="Maple", target="Oak");
    with redirect_stdout(buf) {
        maple spawn greeter;
    }
    out = buf.getvalue();

    # Walker had nowhere to go (the only Buddy edge points back to a
    # visited house) so it must disengage and not loop forever.
    assert not greeter.reached, "greeter should not have reached non-existent target";
    assert "dead end" in out, f"expected dead-end message, got: {out}";
}


test "greeter reports failure when target does not exist on path" {
    # Two houses linked, but the walker is looking for a house name
    # that isn't anywhere in the graph. Should disengage without reaching.
    maple = House(name="Maple");
    oak = House(name="Oak");
    maple +>:Buddy(since="2024"):+> oak;
    oak +>:Buddy(since="2024"):+> maple;
    root ++> maple ++> oak;

    buf = io.StringIO();
    greeter = Greeter(origin="Maple", target="Elm");
    with redirect_stdout(buf) {
        maple spawn greeter;
    }
    out = buf.getvalue();

    assert not greeter.reached, "greeter must not claim success when target is missing";
    assert "dead end" in out, f"expected dead-end when target missing, got: {out}";
}


test "visited flag is set during traversal to block re-entry" {
    maple = House(name="Maple");
    oak = House(name="Oak");
    maple +>:Buddy(since="2024"):+> oak;
    oak +>:Buddy(since="2024"):+> maple;
    root ++> maple ++> oak;

    # A self-loop would let an unguarded walker bounce indefinitely.
    # First confirm the self-loop setup would normally allow bouncing.
    assert len([maple ->:Buddy:->]) == 1, "self Buddy edge must exist for cycle test";

    greeter = Greeter(origin="Maple", target="Oak");
    maple spawn greeter;

    # The walker visited Maple (the entry node), so the cycle guard
    # must have marked it. This is what prevents infinite bouncing.
    assert maple.visited, "entry House must be marked visited during traversal";
    assert greeter.reached, "greeter must still reach its target in a finite graph";
}

