"""Shared task board with open-attachment archetype, user-owned contributions, full private CRUD, and a stats walker."""

# Edge archetype: open-attachment policy encoded once.
edge AttachedTo {
    has since: str = "";
}

# Task: a user-owned contribution.
node Task {
    has task_id: str = "";
    has title: str = "";
    has description: str = "";
    has assignee: str = "";
    has owner_id: str = "";
    has done: bool = False;
}

# Board: the open structure teammates attach to.
node Board {
    has board_name: str = "";
}

# Walker that performs CRUD on tasks. The owner_id gates mutation.
walker TaskCrud {
    has actor_id: str = "";
    has target_task_id: str = "";
    has new_title: str = "";
    has new_description: str = "";
    has new_assignee: str = "";
    has new_done: bool = False;
    has action: str = "create";
    has task_counter: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can operate_on_board with Board entry {
        if self.action == "create" {
            self.task_counter += 1;
            tid = f"T-{self.task_counter}";
            new_task = Task(
                task_id=tid,
                title=self.new_title,
                description=self.new_description,
                assignee=self.new_assignee,
                owner_id=self.actor_id,
                done=False
            );
            here +>:AttachedTo(since="now"):+> new_task;
            print(f"[CREATE] {tid} '{self.new_title}' by {self.actor_id}");
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can operate_on_task with Task entry {
        if self.action == "update" and here.task_id == self.target_task_id {
            if here.owner_id != self.actor_id {
                print(f"[DENY] {self.actor_id} cannot update {here.task_id} (owned by {here.owner_id})");
            } else {
                if self.new_title != "" { here.title = self.new_title; }
                if self.new_description != "" { here.description = self.new_description; }
                if self.new_assignee != "" { here.assignee = self.new_assignee; }
                here.done = self.new_done;
                print(f"[UPDATE] {here.task_id} -> '{here.title}', done={here.done}");
            }
            disengage;
        }
        if self.action == "delete" and here.task_id == self.target_task_id {
            if here.owner_id != self.actor_id {
                print(f"[DENY] {self.actor_id} cannot delete {here.task_id} (owned by {here.owner_id})");
            } else {
                tid_local = here.task_id;
                del here;
                print(f"[DELETE] {tid_local} removed");
            }
            disengage;
        }
        if self.action == "list" {
            status = "DONE" if here.done else "OPEN";
            print(f"[READ] {here.task_id} '{here.title}' (assignee={here.assignee}, {status})");
        }
        visit [-->];
    }
}

# Stats walker: walks the board once and reports totals, completion
# rate, and per-assignee counts in a single response.
walker BoardStats {
    has total: int = 0;
    has done_count: int = 0;
    has counts: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can tally with Board entry {
        visit [-->];
    }

    can count_task with Task entry {
        self.total += 1;
        if here.done {
            self.done_count += 1;
        }
        key = here.assignee;
        current = self.counts.get(key, 0);
        self.counts[key] = current + 1;
        visit [-->];
    }

    can report with Root exit {
        rate = 0.0;
        if self.total > 0 {
            rate = (self.done_count / self.total) * 100.0;
        }
        print(f"[STATS] total={self.total} done={self.done_count} completion={rate:.1f}%");
        print(f"[ASSIGNEE COUNTS] {self.counts}");
    }
}

