"""Tests for the hiking trail program: a chain of plain waypoints from trailhead to summit, with a hiker that counts stops."""

import io;
import from contextlib { redirect_stdout }

# Test 1: Default 5-stop trail (1 trailhead + 3 waypoints + 1 summit) is traversed in order,
# each stop is numbered sequentially, and a completion line is printed.
test "default trail produces numbered stops and completion" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # The hiker must have visited exactly 5 nodes.
    assert res.stop_num == 5, f"expected stop_num == 5, got {res.stop_num}";

    # Stops must be numbered sequentially 1..5.
    assert "Stop 1: Trailhead" in out, f"missing Stop 1: Trailhead in: {out}";
    assert "Stop 2: waypoint" in out, f"missing Stop 2: waypoint in: {out}";
    assert "Stop 3: waypoint" in out, f"missing Stop 3: waypoint in: {out}";
    assert "Stop 4: waypoint" in out, f"missing Stop 4: waypoint in: {out}";
    assert "Stop 5: Summit" in out, f"missing Stop 5: Summit in: {out}";

    # Completion line must appear exactly once with the correct count.
    assert out.count("Hike complete — passed 5 stops along the trail.") == 1, f"expected 1 completion line, got: {out}";
}

# Test 2: A minimal trail (trailhead + summit, no intermediate waypoints) still prints both stops and the completion line.
test "minimal trail trailhead to summit" {
    root ++> Trailhead()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stop_num == 2, f"expected stop_num == 2, got {res.stop_num}";
    assert "Stop 1: Trailhead" in out, f"missing Trailhead stop in: {out}";
    assert "Stop 2: Summit" in out, f"missing Summit stop in: {out}";
    assert "Hike complete — passed 2 stops along the trail." in out, f"missing completion in: {out}";
}

# Test 3: A longer trail with many waypoints proves the counter keeps incrementing and the summary uses the final total.
test "longer trail with many waypoints counts all stops" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stop_num == 7, f"expected stop_num == 7, got {res.stop_num}";
    # First and last stops.
    assert "Stop 1: Trailhead" in out, f"missing Stop 1 in: {out}";
    assert "Stop 7: Summit" in out, f"missing Stop 7 in: {out}";
    # Middle waypoint stops use the generic "waypoint" label since they have no title.
    assert "Stop 4: waypoint" in out, f"missing Stop 4 in: {out}";
    # Completion reports the final count.
    assert "Hike complete — passed 7 stops along the trail." in out, f"missing completion in: {out}";
}

# Test 4: The graph built is a true chain — each node has exactly one successor in the trail.
test "chain shape each node has one successor" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    # Root has exactly one direct child: the Trailhead.
    root_children = [root-->];
    assert len(root_children) == 1, f"expected root to have 1 child, got {len(root_children)}";

    # Follow the chain and confirm 5 nodes reachable, each with exactly one outgoing edge.
    cur = root_children[0];
    count = 1;
    for i in range(10) {
        nxt = [cur-->];
        if len(nxt) == 0 { break; }
        assert len(nxt) == 1, f"expected single successor at step {i}, got {len(nxt)}";
        cur = nxt[0];
        count += 1;
    }
