```jac
"""Dependency lookup with epoch-based cycle detection.

Models the nanvix dlfcn scenario: a lookup walker traverses a graph of
libraries connected by typed dependency edges. Instead of allocating a
per-call visited set (the hand-rolled BTreeSet machinery), the walker
relies on a global epoch counter stamped onto each dependency node via
its `last_visited_epoch` field — graph coloring, native-style.
"""

# ----- Entity archetypes -----

node DlNode {
    has name: str = "";
    has last_visited_epoch: int = 0;
    has bound: bool = False;
}

node Library {
    has name: str = "";
}

# A typed edge: "this DlNode depends on that Library" (and, transitively,
# all of its DlNodes). Carries no payload beyond the relationship.
edge DependsOn { }

# ----- Walker -----

walker Lookup {
    # Global epoch counter — incremented at the start of every lookup.
    # Lives on the walker instance so each spawned walker has its own
    # coloring run, exactly like the per-call atomic in the issue.
    has epoch: int = 0;
    # Bound libraries accumulated during the traversal.
    has bound_order: list[str] = [];

    can begin with Root entry {
        # Bump the global epoch for this lookup. This is the analog of
        # `CURRENT_EPOCH.fetch_add(1, Relaxed)` in the proposal.
        self.epoch = Lookup.next_epoch();
        visit [-->];
    }

    can follow_lib with Library entry {
        print(f"  entering library {here.name}");
        # Now descend into every DlNode attached via DependsOn.
        visit [->:DependsOn:->];
    }

    can color_and_bind with DlNode entry {
        # Graph-coloring check: if this node already carries the current
        # epoch, we are revisiting it on a cycle — skip without locking.
        if here.last_visited_epoch == self.epoch {
            print(f"  skip {here.name}: already colored this epoch (cycle)");
            return;
        }
        # Stamp the node with the current epoch — the "color" for this
        # round. Then do the bind work that the issue's lookup performs.
        here.last_visited_epoch = self.epoch;
        here.bound = True;
        self.bound_order.append(here.name);
        print(f"  bound {here.name}");
        visit [-->];
    }

    # Shared, monotonically increasing epoch source across all walkers.
    static has _clock: int = 0;

    static def next_epoch() -> int {
        Lookup._clock = Lookup._clock + 1;
        return Lookup._clock;
    }
}

# ----- Demo wiring -----

with entry {
    # Build a small library graph with a cycle, the bug that motivated
    # the original BTreeSet fix and the proposed coloring scheme.
    lib_a = Library(name="lib_a");
    lib_b = Library(name="lib_b");
    lib_c = Library(name="lib_c");

    # Dependency nodes hang off each library via typed DependsOn edges.
    # The same node may be reached from multiple libraries — the cycle.
    a1 = DlNode(name="a1");
    a2 = DlNode(name="a2");
    b1 = DlNode(name="b1");
    c1 = DlNode(name="c1");
    shared = DlNode(name="shared");   # creates the cycle a1 -> b1 -> shared -> a2 -> shared

    root ++> lib_a;
    root ++> lib_b;
    root ++> lib_c;

    lib_a +>:DependsOn:+> a1;
    a1 +>:DependsOn:+> b1;
    lib_b +>:DependsOn:+> b1;
    b1 +>:DependsOn:+> shared;
    shared +>:DependsOn:+> a2;
    lib_a +>:DependsOn:+> a2;
    a2 +>:DependsOn:+> shared;        # back-edge forming the cycle
    lib_c +>:DependsOn:+> c1;

    print("=== first lookup (epoch 1) ===");
    lk1 = Lookup();
    root spawn lk1;
    print(f"bound order: {lk1.bound_order}");
    # The shared node must be bound exactly once even though it is
    # reachable on two distinct paths — coloring guarantees that.

    print("=== second lookup (epoch 2) ===");
    lk2 = Lookup();
    root spawn lk2;
    print(f"bound order: {lk2.bound_order}");
}
```

"""Tests for the epoch-based cycle detection walker in main.jac."""

import io;
import from contextlib { redirect_stdout }

# Helper: run a lookup walker on a freshly built graph and capture stdout.
def run_lookup(root_nodes: list) -> tuple {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        for r in root_nodes {
            res = r spawn Lookup();
        }
    }
    return (buf.getvalue(), res);
}

test "shared node is bound exactly once per lookup" {
    lib_a = Library(name="lib_a");
    lib_b = Library(name="lib_b");
    lib_c = Library(name="lib_c");

    a1 = DlNode(name="a1");
    a2 = DlNode(name="a2");
    b1 = DlNode(name="b1");
    c1 = DlNode(name="c1");
    shared = DlNode(name="shared");

    root ++> lib_a;
    root ++> lib_b;
    root ++> lib_c;

    lib_a +>:DependsOn:+> a1;
    a1 +>:DependsOn:+> b1;
    lib_b +>:DependsOn:+> b1;
    b1 +>:DependsOn:+> shared;
    shared +>:DependsOn:+> a2;
    lib_a +>:DependsOn:+> a2;
    a2 +>:DependsOn:+> shared;
    lib_c +>:DependsOn:+> c1;

    (out, lk) = run_lookup([root]);

    assert lk.bound_order.count("shared") == 1, (
        f"shared should be bound once, got {lk.bound_order}"
    );
    # The cycle must produce a skip marker for the second visit.
    assert "already colored this epoch" in out, (
        f"missing cycle-skip marker in output: {out}"
    );
}

test "every reachable DlNode is bound exactly once" {
    lib_a = Library(name="lib_a");
    lib_b = Library(name="lib_b");

    a1 = DlNode(name="a1");
    a2 = DlNode(name="a2");
    b1 = DlNode(name="b1");
    shared = DlNode(name="shared");

    root ++> lib_a;
    root ++> lib_b;

    lib_a +>:DependsOn:+> a1;
    a1 +>:DependsOn:+> b1;
    lib_b +>:DependsOn:+> b1;
    b1 +>:DependsOn:+> shared;
    shared +>:DependsOn:+> a2;
    lib_a +>:DependsOn:+> a2;
    a2 +>:DependsOn:+> shared;

    (out, lk) = run_lookup([root]);

    # All five DlNodes must appear, each exactly once.
    for n in ["a1", "a2", "b1", "shared"] {
        assert lk.bound_order.count(n) == 1, (
            f"{n} should be bound exactly once, got {lk.bound_order}"
        );
    }
    assert len(lk.bound_order) == 4, (
        f"expected 4 binds, got {lk.bound_order}"
    );
}

test "bound flag is set on every reached DlNode" {
    lib_a = Library(name="lib_a");
    a1 = DlNode(name="a1");

    root ++> lib_a;
    lib_a +>:DependsOn:+> a1;

    (out, lk) = run_lookup([root]);

    assert a1.bound is True, f"a1 should be bound, got {a1.bound}";
    assert a1.last_visited_epoch == lk.epoch, (
        f"a1 epoch should match walker epoch {lk.epoch}, "
        f"got {a1.last_visited_epoch}"
    );
}

test "disjoint library does not pollute other branches" {
    lib_a = Library(name="lib_a");
    lib_c = Library(name="lib_c");
    a1 = DlNode(name="a1");
    c1 = DlNode(name="c1");

    root ++> lib_a;
    root ++> lib_c;
    lib_a +>:DependsOn:+> a1;
    lib_c +>:DependsOn:+> c1;

    (out, lk) = run_lookup([root]);

    assert "a1" in lk.bound_order, f"a1 should be bound: {lk.bound_order}";
    assert "c1" in lk.bound_order, f"c1 should be bound: {lk.bound_order}";
    # No cycle markers on this acyclic graph.
    assert "already colored this epoch" not in out, (
        f"unexpected cycle marker on DAG: {out}"
    );
}

test "epoch counter advances between successive lookups" {
    lib_a = Library(name="lib_a");
    a1 = DlNode(name="a1");

    root ++> lib_a;
    lib_a +>:DependsOn:+> a1;

    buf1 = io.StringIO();
    with redirect_stdout(buf1) {
        root spawn Lookup();
    }

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        root spawn Lookup();
    }

    # After two lookups the global clock must have advanced at least twice.
    assert Lookup._clock >= 2, (
        f"global epoch clock should advance, got {Lookup._clock}"
    );
}

