"""Build system dependency auditor.

Walks a build-task DAG (with shared dependencies forming diamonds) and
sums the build minutes of every task exactly once, even though diamond
re-entry would otherwise re-visit the same task on multiple paths.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker Auditor {
    # Cycle/diamond policy: explicit guard set. Walkers in jac 0.36.1
    # do NOT dedupe nodes on `visit [-->]`, so we carry the dedupe
    # ourselves. A task already audited is skipped on later paths.
    has seen: list[Task] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Task entry {
        # Guard: if we've already counted this task, don't count it again.
        already = False;
        for prior in self.seen {
            if prior == here {
                already = True;
                break;
            }
        }
        if not already {
            print(f"Auditing {here.title} ({here.minutes} min)");
            self.total_minutes = self.total_minutes + here.minutes;
            self.seen.append(here);
            visit [-->];
        }
    }
}

with entry {
    # Diamond shape:
    #     core
    #    /    \
    #  app    cli
    #    \    /
    #     pack
    core = Task(title="core-lib", minutes=10);
    app = Task(title="app", minutes=5);
    cli = Task(title="cli", minutes=7);
    pack = Task(title="packager", minutes=3);

    # Diamond wiring: pack is reachable via app AND via cli.
    root ++> core ++> app ++> pack;
    core ++> cli ++> pack;

    auditor = Auditor();
    root spawn auditor;
    print(f"Total build minutes (each task counted once): {auditor.total_minutes}");
}
```

