"""Tests for the build dependency auditor.

Each test builds its own diamond DAG and asserts that the Auditor
counts every reachable Task exactly once, regardless of how many
paths reach it.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helper: run an Auditor on a freshly built root and capture stdout.
# ---------------------------------------------------------------------------
def run_auditor(root_node) -> tuple {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = Auditor();
        root_node spawn auditor;
    }
    return (buf.getvalue(), auditor);
}

# ---------------------------------------------------------------------------
# Test 1: canonical diamond. `pack` is reached via app AND via cli.
# Sum must equal 10 + 5 + 7 + 3 = 25 minutes, and `pack` audited exactly once.
# ---------------------------------------------------------------------------
test "diamond counts shared dependency once" {
    core = Task(title="core-lib", minutes=10);
    app = Task(title="app", minutes=5);
    cli = Task(title="cli", minutes=7);
    pack = Task(title="packager", minutes=3);

    root ++> core;
    core ++> app;
    app ++> pack;
    core ++> cli;
    cli ++> pack;

    (out, auditor) = run_auditor(root);
    assert auditor.total_minutes == 25,
        f"expected 25 minutes (10+5+7+3), got {auditor.total_minutes}";
    # pack must appear exactly once in the audit log
    pack_lines = [l for l in out.split("\n") if "Auditing packager" in l];
    assert len(pack_lines) == 1,
        f"packager audited {len(pack_lines)} times, expected 1. Output:\n{out}";
    assert len(auditor.seen) == 4,
        f"expected 4 unique tasks seen, got {len(auditor.seen)}";
}

# ---------------------------------------------------------------------------
# Test 2: deeper diamond. core -> {app, cli}; app -> {pkg, lib};
# cli -> {pkg, lib}; pkg -> leaf; lib -> leaf. The leaf is reachable
# via 4 distinct paths. Each task counted once. Sum = core+app+cli+
# pkg+lib+leaf.
# ---------------------------------------------------------------------------
test "deeper diamond leaf is still counted once" {
    core = Task(title="core", minutes=2);
    app = Task(title="app", minutes=3);
    cli = Task(title="cli", minutes=4);
    pkg = Task(title="pkg", minutes=5);
    lib = Task(title="lib", minutes=6);
    leaf = Task(title="leaf", minutes=7);

    root ++> core;
    core ++> app;
    core ++> cli;
    app ++> pkg;
    app ++> lib;
    cli ++> pkg;
    cli ++> lib;
    pkg ++> leaf;
    lib ++> leaf;

    (out, auditor) = run_auditor(root);
    # 2+3+4+5+6+7 = 27
    assert auditor.total_minutes == 27,
        f"expected 27 minutes, got {auditor.total_minutes}";
    leaf_lines = [l for l in out.split("\n") if "Auditing leaf" in l];
    assert len(leaf_lines) == 1,
        f"leaf audited {len(leaf_lines)} times, expected 1";
    pkg_lines = [l for l in out.split("\n") if "Auditing pkg" in l];
    assert len(pkg_lines) == 1,
        f"pkg audited {len(pkg_lines)} times, expected 1";
    assert len(auditor.seen) == 6,
        f"expected 6 unique tasks seen, got {len(auditor.seen)}";
}

# ---------------------------------------------------------------------------
# Test 3: linear chain (no diamond). Each node reached by exactly one path,
# so the guard is never tripped. Sum equals the simple chain sum.
# ---------------------------------------------------------------------------
test "linear chain still sums correctly" {
    a = Task(title="a", minutes=1);
    b = Task(title="b", minutes=2);
    c = Task(title="c", minutes=3);

    root ++> a ++> b ++> c;

    (out, auditor) = run_auditor(root);
    assert auditor.total_minutes == 6,
        f"expected 6 minutes (1+2+3), got {auditor.total_minutes}";
    assert len(auditor.seen) == 3,
        f"expected 3 unique tasks seen, got {len(auditor.seen)}";
    # all three should have been audited
    for tname in ["a", "b", "c"] {
        assert f"Auditing {tname}" in out,
            f"missing audit line for {tname}. Output:\n{out}";
    }
}

# ---------------------------------------------------------------------------
# Test 4: root with no outgoing edges. The walker takes the `else { disengage; }`
# branch and never enters a Task. Nothing audited, total_minutes stays 0.
# ---------------------------------------------------------------------------
test "empty graph audits nothing" {
    (out, auditor) = run_auditor(root);
    assert auditor.total_minutes == 0,
        f"expected 0 minutes for empty graph, got {auditor.total_minutes}";
    assert len(auditor.seen) == 0,
        f"expected empty seen list, got {len(auditor.seen)}";
    assert "Total" not in out, f"unexpected summary line: {out}";
}

# ---------------------------------------------------------------------------
# Test 5: triple-fan diamond. root -> {x, y, z}; all three converge on `sink`.
# Without dedupe, sink would be counted 3 times. With the guard it is counted
# exactly once.
# ---------------------------------------------------------------------------
test "triple fan into single sink" {
    x = Task(title="x", minutes=1);
    y = Task(title="y", minutes=1);
    z = Task(title="z", minutes=1);
    sink = Task(title="sink", minutes=100);

    root ++> x ++> sink;
    root ++> y ++> sink;
    root ++> z ++> sink;

    (out, auditor) = run_auditor(root);
    # x,y,z,sink = 1+1+1+100 = 103
    assert auditor.total_minutes == 103,
        f"expected 103 minutes, got {auditor.total_minutes}";
    sink_lines = [l for l in out.split("\n") if "Auditing sink" in l];
    assert len(sink_lines) == 1,
        f"sink audited {len(sink_lines)} times (expected 1). Output:\n{out}";
    # seen list must contain exactly 4 distinct task instances
    assert len(auditor.seen) == 4,
        f"expected 4 unique tasks seen, got {len(auditor.total_minutes)}";
}
