    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon.");
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        print(f"Checking {here.name} (room {self.rooms_seen})");
        if here.is_treasure {
            print(f"Treasure found in {here.name}! Search complete after {self.rooms_seen} rooms.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Entry Hall")
        ++> Room(name="Armory")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Throne Room");

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter saw {hunter.rooms_seen} rooms before stopping.");
}
