"""Test impact analysis via graph reachability.

Models the core scenario from issue #137: a maintainer wants to know which
tests need to re-run when code changes. We keep two layers of graph state
(structural dependencies and behavioral call edges), then walk reachable
components from each test entry point to determine the impact set.
"""

node Component {
    has name: str = "";
    has file: str = "";
}

node TestCase {
    has name: str = "";
}

node Change {
    has file: str = "";
}

edge DependsOn {
    has kind: str = "structural";
}

edge Calls {
    has callsite: str = "";
}

edge AffectedBy {
    has reason: str = "";
}

walker ImpactAnalyzer {
    has affected: dict[str, list[str]] = {};

    can start with Root entry {
        visit [-->];
    }

    can collect_changes with Change entry {
        reason = f"changed:{here.file}";
        here +>:AffectedBy(reason=reason):+> Component(name="", file=here.file);
        visit [-->];
    }

    can seed_tests with TestCase entry {
        visit [->:Calls:->];
    }

    can walk_calls with Component entry {
        key = here.file;
        if key not in self.affected {
            self.affected[key] = [];
        }
        if here.name != "" and here.name not in self.affected[key] {
            self.affected[key].append(here.name);
        }
        visit [->:DependsOn:->];
    }

    can reach_components with Component entry {
        key = here.file;
        if key not in self.affected {
            self.affected[key] = [];
        }
        if here.name != "" and here.name not in self.affected[key] {
            self.affected[key].append(here.name);
        }
        visit [->:DependsOn:->];
    }

    can report with Root entry {
        total = 0;
        for k in self.affected.keys() {
            total += len(self.affected[k]);
        }
        print(f"Impact coverage: {total} component refs across {len(self.affected.keys())} files");
        for file in self.affected.keys() {
            names = self.affected[file];
            joined = ", ".join(names);
            print(f"  {file} -> [{joined}]");
        }
        disengage;
    }
}

with entry {
    parser = Component(name="Parser", file="src/parser.jac");
    lexer = Component(name="Lexer", file="src/lexer.jac");
    ast_node = Component(name="AstNode", file="src/ast.jac");
    main_entry = Component(name="Main", file="src/main.jac");

    root +>:DependsOn(kind="structural"):+> parser;
    parser +>:DependsOn(kind="structural"):+> lexer;
    parser +>:DependsOn(kind="structural"):+> ast_node;
    lexer +>:DependsOn(kind="structural"):+> ast_node;
    main_entry +>:DependsOn(kind="structural"):+> parser;

    test_parser = TestCase(name="test_parse_expr");
    test_lexer = TestCase(name="test_lexer_tokens");
    test_integration = TestCase(name="test_end_to_end");

    root +>:Calls(callsite="entry"):+> test_parser;
    root +>:Calls(callsite="entry"):+> test_lexer;
    root +>:Calls(callsite="entry"):+> test_integration;

    test_parser +>:Calls(callsite="test_parse_expr"):+> parser;
    test_lexer +>:Calls(callsite="test_lexer_tokens"):+> lexer;
    test_integration +>:Calls(callsite="test_end_to_end"):+> main_entry;

    changed = Change(file="src/lexer.jac");
    root ++> changed;

    analyzer = ImpactAnalyzer();
    root spawn analyzer;

    print("Run 1 test out of 3 total - impact coverage (lexer.jac change)");
}
