```jac
"""Restaurant kitchen line health inspection.

A patrol walker visits every station on the line (grill, fryer, cold prep).
At each station, two separate checks fire on every visit: a temperature
violation check (flagging anything above 40 C) and a visit log entry.
Both checks must run at every station.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Patrol {
    has visited: list[str] = [];

    can start with Root entry {
        print("Starting kitchen line health inspection...");
        visit [-->];
    }

    can sweep with Grill | Fryer | ColdPrep entry {
        # Check 1: temperature violation flag (>40 C)
        violation = "VIOLATION" if here.is_violation() else "OK";
        print(f"[{violation}] {here.name}: {here.temperature} C");

        # Check 2: log every station visit
        self.visited.append(here.name);
        print(f"  logged visit to {here.name} (total visits: {len(self.visited)})");

        visit [-->];
    }
}

with entry {
    grill = Grill(name="Grill", temperature=85.0);
    fryer = Fryer(name="Fryer", temperature=180.0);
    cold = ColdPrep(name="Cold Prep", temperature=4.0);
    root ++> grill ++> fryer ++> cold;

    inspector = Patrol();
    root spawn inspector;

    print(f"\nInspection complete. Stations visited: {inspector.visited}");
    print(f"Total stations logged: {len(inspector.visited)}");
}
