"""Test annex for the kitchen line health inspection program."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: violation flagging and visit log for grill (hot) ----------
test "grill flagged as violation and visit logged" {
    g = Grill(name="Grill", temperature=85.0);
    root ++> g;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p = Patrol();
        root spawn p;
    }
    out = buf.getvalue();

    assert "Starting kitchen line health inspection..." in out, f"missing start message: {out}";
    assert "[VIOLATION] Grill: 85.0 C" in out, f"expected violation line for grill: {out}";
    assert "logged visit to Grill (total visits: 1)" in out, f"expected visit log for grill: {out}";
    assert p.visited == ["Grill"], f"expected visited=['Grill'], got {p.visited}";
}

# ---------- Test 2: safe station (cold prep) prints OK and is still logged ---
test "cold prep marked OK but still logged as a visit" {
    c = ColdPrep(name="Cold Prep", temperature=4.0);
    root ++> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p = Patrol();
        root spawn p;
    }
    out = buf.getvalue();

    assert "[OK] Cold Prep: 4.0 C" in out, f"expected OK line for cold prep: {out}";
    assert "logged visit to Cold Prep (total visits: 1)" in out, f"expected visit log for cold prep: {out}";
    assert p.visited == ["Cold Prep"], f"expected visited=['Cold Prep'], got {p.visited}";
}

# ---------- Test 3: full line visits every station and flags violations ---
test "patrol walks the whole line and both checks fire at every station" {
    g = Grill(name="Grill", temperature=85.0);
    f = Fryer(name="Fryer", temperature=180.0);
    cp = ColdPrep(name="Cold Prep", temperature=4.0);
    root ++> g ++> f ++> cp;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p = Patrol();
        root spawn p;
    }
    out = buf.getvalue();

    # Every station must produce BOTH a status line and a log line.
    assert "[VIOLATION] Grill: 85.0 C" in out, f"missing grill status: {out}";
    assert "logged visit to Grill (total visits: 1)" in out, f"missing grill log: {out}";

    assert "[VIOLATION] Fryer: 180.0 C" in out, f"missing fryer status: {out}";
    assert "logged visit to Fryer (total visits: 2)" in out, f"missing fryer log: {out}";

    assert "[OK] Cold Prep: 4.0 C" in out, f"missing cold prep status: {out}";
    assert "logged visit to Cold Prep (total visits: 3)" in out, f"missing cold prep log: {out}";

    # Visit log records every station exactly once, in traversal order.
    assert p.visited == ["Grill", "Fryer", "Cold Prep"], f"unexpected visit order: {p.visited}";
    assert len(p.visited) == 3, f"expected 3 visits, got {len(p.visited)}";
}

# ---------- Test 4: threshold boundary (>40 means 40.0 itself is OK) ----------
test "boundary at 40 C is OK and 40.01 C is a violation, both still logged" {
    safe = Grill(name="BorderSafe", temperature=40.0);
    hot = Fryer(name="BorderHot", temperature=40.01);
    root ++> safe ++> hot;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p = Patrol();
        root spawn p;
    }
    out = buf.getvalue();

    assert "[OK] BorderSafe: 40.0 C" in out, f"40.0 should be OK: {out}";
    assert "[VIOLATION] BorderHot: 40.01 C" in out, f"40.01 should violate: {out}";

    # Both stations must still be in the visit log — checks are independent.
    assert "BorderSafe" in p.visited, f"BorderSafe missing from visits: {p.visited}";
    assert "BorderHot" in p.visited, f"BorderHot missing from visits: {p.visited}";
    assert len(p.visited) == 2, f"expected 2 logged visits, got {len(p.visited)}";
}

