```jac
"""Typhon profiler config ergonomics: modeled as a graph where enabling a leaf
flag without its ancestors is a silent no-op.

The 232-flag Typhon:Profiler:* tree resolves strictly parent-implies-children:
"Parent off -> all descendants off (regardless of their own keys)." Enabling a
leaf without its ancestors is a silent no-op -- no warning, no data, a
plausible-looking trace. The ConfigAuditor walker traverses every flag from
the root and reports which ones are actually live in the trace vs. which were
silently dropped because an ancestor on the path to root was disabled.
"""

# A flag node: a leaf or branch in the Profiler config tree.
node Flag {
    has name: str = "";
    has enabled: bool = False;
    has children: list = [];
    has is_root: bool = False;
}

# Typed edge from a parent flag to a child flag in the Profiler tree.
edge SubFlag { }

walker ConfigAuditor {
    has live_flags: list = [];
    has silently_dropped: list = [];

    can start with Root entry {
        # Begin by entering each top-level flag branch from the root.
        visit [->:SubFlag:->];
    }

    can audit with Flag entry {
        # Root catalog has no enablement; its descendants do.
        if here.is_root {
            visit [->:SubFlag:->];
        } elif here.enabled {
            # Seed: a flag is only live if no known-broken ancestor
            # silently dropped it (i.e. an ancestor was off but a leaf
            # was hand-enabled). If this flag itself is on the known-
            # broken list, treat it as dropped for the summary.
            self.live_flags.append(here.name);
            visit [->:SubFlag:->];
        } else {
            # This flag is OFF; every descendant is silently dropped.
            for child in here.children {
                self.silently_dropped.append(child);
            }
            visit [->:SubFlag:->];
        }
    }

    can summarize with Root entry {
        final_live: list = [];
        final_dropped: list = [];

        for n in self.live_flags {
            if n in self.silently_dropped {
                final_dropped.append(n);
            } else {
                final_live.append(n);
            }
        }

        print("LIVE FLAGS (actually emitted to trace):");
        for n in final_live {
            print(f"  + {n}");
        }
        print("");
        print("SILENTLY DROPPED (enabled but ancestor off):");
        for n in final_dropped {
            print(f"  ! {n}");
        }
    }
}

with entry {
    # Build a small slice of the flag catalog: a Profiler root with a
    # Runtime child and an AdaptiveWaiter child. The Runtime branch contains
    # ThreadScheduling (a real flag) and TieredCompilation (a leaf that the
    # July investigator enabled by hand, forgetting its Runtime parent).
    profiler = Flag(name="Profiler", is_root=True);
    runtime = Flag(name="Runtime", children=["TieredCompilation"]);
    sched = Flag(name="ThreadScheduling", enabled=True);
    tiered = Flag(name="TieredCompilation", enabled=True);
    adaptive = Flag(name="AdaptiveWaiter", enabled=False);
    yields = Flag(name="YieldOrSleep", enabled=True);

    root +>:SubFlag:+> profiler;
    profiler +>:SubFlag:+> runtime;
    runtime +>:SubFlag:+> sched;
    runtime +>:SubFlag:+> tiered;
    profiler +>:SubFlag:+> adaptive;
    adaptive +>:SubFlag:+> yields;

    auditor = ConfigAuditor();
    root spawn auditor;
}
```

