"""Metro line operation: drivers traverse segments and accumulate track
distance while hearing station announcements; inspectors walk the same
stations but rack up zero distance."""

node Station {
    has name: str = "";
    has line: str = "";
    has signage_ok: bool = True;
    has segment_km: float = 0.0;
}

walker Inspector {
    has line_name: str = "Blue";
    has distance_km: float = 0.0;
    has stops_visited: int = 0;
    has signage_issues: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Station entry {
        status = "OK" if here.signage_ok else "BROKEN";
        print(f"[Inspector/{self.line_name}] {here.name}: signage {status}");
        self.stops_visited += 1;
        if not here.signage_ok {
            self.signage_issues += 1;
        }
        visit [-->];
    }
}

walker Driver {
    has line_name: str = "Blue";
    has distance_km: float = 0.0;
    has stops_visited: int = 0;

    can start with Root entry {
        print(f"[Driver/{self.line_name}] departing terminus");
        visit [-->];
    }

    can roll with Station entry {
        announcement = f"Now approaching {here.name} on the {here.line} line";
        print(f"[Driver/{self.line_name}] {announcement}");
        self.distance_km += here.segment_km;
        self.stops_visited += 1;
        visit [-->];
    }
}

with entry {
    root ++> Station(name="Central", line="Blue", signage_ok=True, segment_km=1.2)
        ++> Station(name="Market", line="Blue", signage_ok=True, segment_km=0.8)
        ++> Station(name="Harbor", line="Blue", signage_ok=False, segment_km=2.5)
        ++> Station(name="Airport", line="Blue", signage_ok=True, segment_km=3.0);

    inspector = Inspector(line_name="Blue");
    root spawn inspector;

    driver = Driver(line_name="Blue");
    root spawn driver;

    print(
        f"Driver covered {driver.distance_km} km across "
        f"{driver.stops_visited} stops; Inspector audited "
        f"{inspector.stops_visited} stops covering "
        f"{inspector.distance_km} km and flagged "
        f"{inspector.signage_issues} signage issue(s)."
    );
}
