"""Translation-table catalog demo with locale fallback and cycle-safe traversal."""

node Product {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Category {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
    has audit_seen: bool = False;
}

node Brand {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Translation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has entity_kind: str = "";
    has locale: str = "";
    has name: str = "";
    has slug: str = "";
    has description: str = "";
}

edge ProductTranslation {
    has source_column: str = "";
}

edge CategoryTranslation {
    has source_column: str = "";
}

edge BrandTranslation {
    has source_column: str = "";
}

edge CategoryParent {
    has relation: str = "parent";
}

edge ProductCategory { }
edge ProductBrand { }

walker ProductReader {
    has requested_locale: str = "";
    has default_locale: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Product entry {
        print(f"product: {here.title} ({here.slug})");
        visit [->:ProductTranslation:->] else {
            disengage;
        }
    }

    can resolve with Translation entry {
        if here.locale == self.requested_locale {
            print(f"selected {here.entity_kind} [{here.locale}]: {here.name}");
        } else {
            if here.locale == self.default_locale {
                print(f"fallback {here.entity_kind} [{here.locale}]: {here.name}");
            }
        }
        visit [-->] else {
            print("translation branch complete");
        }
    }
}

walker CatalogAudit {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_category with Category entry {
        if here.audit_seen {
            print(f"cycle detected at category {here.slug}");
            disengage;
        } else {
            here.audit_seen = True;
            print(f"category: {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }

