"""Validated relation graph with evidence and cycle-safe traversal."""

node Entity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has seen: bool = False;
}

node Chunk {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has text: str = "";
}

edge RelatedTo {
    has predicate: str = "";
    has confidence: float = 0.0;
}

edge Evidence {
    has confidence: float = 0.0;
    has run_id: str = "";
}

walker RelationWalker {
    has max_hops: int = 4;
    has hops: int = 0;
    has found: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can follow with Entity entry {
        if here.seen {
            print(f"cycle guard stopped at {here.name}");
            disengage;
        }
        here.seen = True;
        self.found.append(here.name);
        print(f"entity: {here.name}");

        if self.hops >= self.max_hops {
            print(f"hop cap reached at {here.name}");
            disengage;
        }

        self.hops += 1;
        visit [->:RelatedTo:->] else { disengage; }
    }

    can inspect with Chunk entry {
        print(f"evidence chunk: {here.title}");
        visit [->:Evidence:->] else { disengage; }
    }
}

with entry {
    alice = Entity(name="Alice", title="Alice", year=2024);
    bob = Entity(name="Bob", title="Bob", year=2024);
    carol = Entity(name="Carol", title="Carol", year=2024);
    source = Chunk(
        title="Seed chunk",
        text="Alice knows Bob and Bob knows Carol."
    );

    root ++> alice;
    root ++> source;

    alice +>:RelatedTo(predicate="knows", confidence=0.98):+> bob;
    bob +>:RelatedTo(predicate="knows", confidence=0.97):+> carol;
    carol +>:RelatedTo(predicate="knows", confidence=0.96):+> alice;

    source +>:Evidence(confidence=0.99, run_id="run-1"):+> alice;

    root spawn RelationWalker(max_hops=4);
}
```

import io;
import from contextlib { redirect_stdout }

test "cycle-safe relation traversal" {
    alice = Entity(name="Alice", title="Alice", year=2024);
    bob = Entity(name="Bob", title="Bob", year=2024);
    carol = Entity(name="Carol", title="Carol", year=2024);

    root ++> alice;
    alice +>:RelatedTo(predicate="knows", confidence=0.98):+> bob;
    bob +>:RelatedTo(predicate="knows", confidence=0.97):+> carol;
    carol +>:RelatedTo(predicate="knows", confidence=0.96):+> alice;

    assert len([alice ->:RelatedTo:->]) == 1, f"wrong Alice edges";
    assert bob in [alice ->:RelatedTo:->], f"Bob is not Alice's relation target";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RelationWalker(max_hops=4);
    }
    out = buf.getvalue();

    assert len(res.found) == 3, f"got {res.found}";
    assert res.found[0] == "Alice", f"got {res.found}";
    assert res.found[1] == "Bob", f"got {res.found}";
    assert res.found[2] == "Carol", f"got {res.found}";
