"""TLAS shrink path: model the post-#2929 reality where shrink_tlas_to_fit
sets a pending flag rather than destroying the slot, and a separate ensure
fold-in pass only drops the scratch when the slot is genuinely unbuilt.
A walker demonstrates reachability of the case-1 arm and the (now arbitrary)
call ordering between shrink and ensure."""

node TLASSlot {
    has slot_index: int = 0;
    has max_instances: int = 0;
    has is_built: bool = False;
}

edge Allocates {
    has tick: int = 0;
}

walker ShrinkRequest {
    has slot_index: int = 0;
    has pending_flag: bool = False;
    has visited_slots: list[int] = [];

    can start with Root entry {
        print(f"shrink_tlas_to_fit(scratch, slot={self.slot_index}): request pending, NOT destroy");
        self.pending_flag = True;
        visit [->:Allocates:->];
    }

    can record_shrink_request with TLASSlot entry {
        if here.slot_index == self.slot_index {
            self.visited_slots.append(here.slot_index);
            here.max_instances = here.max_instances - 1 if here.max_instances > 0 else 0;
            print(f"  -> slot {here.slot_index} marked for shrink (max_instances now {here.max_instances})");
        }
        visit [->:Allocates:->];
    }
}

walker EnsureState {
    has slot_index: int = 0;
    has freed_scratch: bool = False;

    can start with Root entry {
        visit [->:Allocates:->];
    }

    can fold_into_slot with TLASSlot entry {
        if here.slot_index == self.slot_index and not here.is_built {
            here.is_built = True;
            self.freed_scratch = True;
            print(f"  -> case-1 REACHED: slot {here.slot_index} was None/never rebuilt; scratch dropped entirely");
            visit [->:Allocates:->];
        }
        visit [->:Allocates:->];
    }
}

walker ScratchAudit {
    has reachable_case_one: bool = False;
    has visited: list[int] = [];

    can start with Root entry {
        print("ScratchAudit: which case-1 producers can actually reach case 1 now?");
        visit [->:Allocates:->];
    }

    can tally with TLASSlot entry {
        self.visited.append(here.slot_index);
        if not here.is_built {
            self.reachable_case_one = True;
            print(f"  slot {here.slot_index} is_unbuilt -> case 1 reachable");
        } else {
            print(f"  slot {here.slot_index} is_built -> case 1 NOT reachable here");
        }
        visit [->:Allocates:->];
    }
}

with entry {
    slot0 = TLASSlot(slot_index=0, max_instances=4, is_built=True);
    slot1 = TLASSlot(slot_index=1, max_instances=2, is_built=False);
    root +>:Allocates(tick=1):+> slot0;
    root +>:Allocates(tick=2):+> slot1;

    print("--- shrink_tlas_to_fit(scratch, slot=1) ---");
    root spawn ShrinkRequest(slot_index=1);

    print("--- ensure_tlas_state folds the shrink ---");
    root spawn EnsureState(slot_index=1);

    print("--- audit reachability of case-1 arm ---");
    auditor = ScratchAudit();
    root spawn auditor;
    verdict = "REACHABLE" if auditor.reachable_case_one else "UNREACHABLE";
    print(f"case-1 arm on this graph: {verdict}");
    print("post-#2929 reality: shrink_tlas_to_fit no longer destroys the slot,");
    print("so the draw.rs 'run AFTER so destroyed slot drops scratch' claim is stale.");
}
