```jac
"""Runtime-composed ensemble registry.

Models ADR-047's four named gaps as a graph: sub-DAGs hold a frozen
dependency graph; a validator enforces AS-2 (validate-before-load)
before a sub-DAG can be admitted into the registry; a composer walks
the registry and, when a requested shape is missing, materializes one
by composing validated parts at runtime. The four gaps appear as typed
edges that the composer traverses.

Walks the auditor over the registry, prints gap status, and refuses to
admit any sub-DAG that fails validation.
"""

node SubDAG {
    has name: str = "";
    has frozen: bool = True;
    has validated: bool = False;
    has depends_on: list[str] = [];
}

node Validator {
    has gate_name: str = "AS-2";
}

node Composer {
    has requested_shape: str = "";
    has composed: bool = False;
}

node Registry {
    has capacity: int = 16;
}

# Typed edges: each gap from ADR-047 becomes a relationship the composer
# traverses, so the dispatch/resolver/freeze/registry path is the graph.
edge GapSingleTarget {}
edge GapScalarResolver {}
edge GapFrozenDAG {}
edge GapRegistryAdmission {}
edge Validates {}
edge Composes {}
edge PartOf {}

walker Auditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_registry with Registry entry {
        self.findings.append(f"registry capacity={here.capacity}");
        visit [->:PartOf:->];
    }

    can audit_validator with Validator entry {
        self.findings.append(f"validator {here.gate_name} active");
        visit [->:Validates:->];
    }

    can audit_subdag with SubDAG entry {
        # Cycle policy: every sub-DAG must be frozen at parse time and
        # validated before it can be admitted. We keep both checks as
        # explicit gates — they are domain logic, not scaffolding.
        line = f"{here.name}: frozen={here.frozen} validated={here.validated}";
        self.findings.append(line);
        if not here.frozen {
            self.findings.append(f"REJECT {here.name}: DAG not frozen at parse");
        } elif not here.validated {
            self.findings.append(f"REJECT {here.name}: fails AS-2 validate-before-load");
        } else {
            # Only admitted, validated parts expose the four gaps.
            self.findings.append(f"  gap: {here.name} exposes single-target dispatch");
            self.findings.append(f"  gap: {here.name} exposes scalar-only resolver");
            self.findings.append(f"  gap: {here.name} exposes parse-time frozen DAG");
        }
        visit [-->];
    }

    can audit_composer with Composer entry {
        # The composer composes only from validated parts — that's the
        # trust-accumulation guard. If no part covers the requested
        # shape, refuse to materialize (no runtime spec -> EnsembleConfig
        # path means we stop here, we don't fabricate one).
        self.findings.append(f"composer requested: {here.requested_shape}");
        visit [-->];
    }
}

with entry {
    # Two validated sub-DAGs, one that fails the freeze gate (DAG mutated
    # after parse) and one that fails AS-2 (admitted without validation).
    # Both must be refused by the auditor.
    dag_a = SubDAG(name="A", frozen=True, validated=True, depends_on=["B"]);
    dag_b = SubDAG(name="B", frozen=True, validated=True, depends_on=[]);
    dag_unfrozen = SubDAG(name="C", frozen=False, validated=True, depends_on=[]);
    dag_unvalidated = SubDAG(name="D", frozen=True, validated=False, depends_on=[]);

    validator = Validator(gate_name="AS-2");
    composer = Composer(requested_shape="compose-at-runtime");
    registry = Registry(capacity=16);

    # Wire the graph: root -> registry -> validator -> sub-DAGs,
    # sub-DAGs expose the four named gaps as typed edges,
    # composer composes from validated parts.
    root ++> registry
        +>:PartOf:+> validator
        +>:Validates:+> dag_a
        +>:Validates:+> dag_b
        +>:Validates:+> dag_unfrozen
        +>:Validates:+> dag_unvalidated;

    # Typed gap edges from validated sub-DAGs into the composer.
    dag_a +>:GapFrozenDAG:+> composer;
    dag_a +>:GapSingleTarget:+> composer;
    dag_a +>:GapScalarResolver:+> composer;
    dag_b +>:GapFrozenDAG:+> composer;
    dag_b +>:GapSingleTarget:+> composer;
    dag_b +>:GapScalarResolver:+> composer;

    # Unvalidated / unfrozen parts remain in the graph but carry no
    # edges into the composer — they cannot compose anything
    # (trust-accumulation guard survives as a structural rule, not a
    # runtime check).

    # Walk the auditor from root. It refuses to follow an unvalidated
    # sub-DAG into the gaps — rejection is recorded, traversal continues.
    auditor = Auditor();
    root spawn auditor;

    for line in auditor.findings {
        print(line);
    }
}
