    root ++> registry;
    registry +>:PartOf:+> validator;
    validator +>:Validates:+> dag;

    assert len([dag ->:GapSingleTarget:->]) == 0, "unvalidated DAG must not expose dispatch";
    assert len([dag ->:GapScalarResolver:->]) == 0, "unvalidated DAG must not expose resolver";
    assert len([dag ->:GapFrozenDAG:->]) == 0, "unvalidated DAG must not expose frozen-DAG gap";
