"""AIPM build dependency analysis: model crates as nodes, dependencies as
typed edges, and walk the critical path to surface the slowest compilation
units — like a build-time hotspot report.

The issue is that the build serializes on a chain of heavy transitive deps
(``rustls`` → ``hyper-rustls`` → ``reqwest`` → ``jsonschema`` →
``libaipm-engine-spec`` build script → ``libaipm`` → ``aipm``). We model
each crate as a node, each ``depends_on`` relationship as a typed edge
carrying the kind of dependency (normal vs. build-script), and let a
walker traverse downstream to find the critical-path bottleneck.
"""

# --- Node archetypes ---------------------------------------------------------

# Base shape so union triggers can touch shared fields uniformly.
node Unit {
    has name: str = "";
    has compile_seconds: float = 0.0;
}

node Crate(Unit) {
    has kind: str = "lib";

    override def label() -> str {
        return f"Crate({self.name})";
    }
}

node BuildScript(Unit) {
    has produces: str = "";

    def label() -> str {
        return f"BuildScript({self.name})";
    }
}

# --- Typed edges (the relationships carry meaning) ----------------------------

# Normal compile-time dependency: consumer -> provider.
edge DependsOn {
    has via: str = "link";
}

# A build-script-only dependency: the consumer's build.rs blocks on this.
# This is the relationship that creates the serialization bottleneck.
edge BuildScriptDeps {
}

# --- Walkers -----------------------------------------------------------------

# Walks the transitive dependency closure downstream from a starting crate
# and accumulates total compile cost along the way, like a build scheduler
# estimating wall-clock impact of a dep-chain change.
walker CriticalPath {
    has visited_names: list[str] = [];
    has total_seconds: float = 0.0;
    has max_single: float = 0.0;
    has max_single_name: str = "";
    has chain: list[str] = [];

    can start with Root entry {
        print(f"=== Build-time critical path analysis ===");
        visit [-->];
    }

    # Union trigger: fires for a Crate OR a BuildScript node. We only
    # touch fields shared by the base shape (name string + cost figure).
    can inspect with Crate | BuildScript entry {
        # --- Cycle policy (explicit, per Jac 0.36 semantics) ---
        # The dep graph can loop (e.g. test-only cycles). Skip revisits
        # so we never spin forever — this is the domain logic the source
        # maintained, kept here.
        if here.name in self.visited_names {
            return;
        }
        self.visited_names.append(here.name);
        self.chain.append(here.name);

        cost = here.compile_seconds;
        self.total_seconds = self.total_seconds + cost;
        if cost > self.max_single {
            self.max_single = cost;
            self.max_single_name = here.name;
        }
        print(f"  [{cost:>5.1f}s] {here.name}  ({here.label()})");

        # Keep walking downstream over both edge types.
        visit [->:DependsOn:->];
        visit [->:BuildScriptDeps:->];
    }
}

# Targets a specific bottleneck pattern: a BuildScript whose build-time
# is gated by an expensive downstream compile unit (the `rustls` ->
# `reqwest` -> `jsonschema` chain from the issue).
walker BuildScriptBottleneck {
    has offenders: list[str] = [];

    can start with Root entry {
        print(f"=== Build-script bottleneck scan ===");
        visit [-->];
    }

    can probe with BuildScript entry {
        # Walk the build-script's deps; flag heavy downstream units.
        heavy = [->:BuildScriptDeps:->];
        for n in heavy {
            if n.compile_seconds > 10.0 {
                note = f"{here.name} blocked on {n.name} ({n.compile_seconds}s)";
                self.offenders.append(note);
                print(f"  BOTTLENECK: {note}");
            }
        }
        visit [->:BuildScriptDeps:->];
    }
}

# --- Demo wiring -------------------------------------------------------------

with entry {
    # Native crates that build slowly (C/asm), as in the report.
    aws_lc_sys = Crate(name="aws-lc-sys", compile_seconds=59.7, kind="native");
    libgit2_sys = Crate(name="libgit2-sys", compile_seconds=50.4, kind="native");
    rustls = Crate(name="rustls", compile_seconds=14.5, kind="lib");
    reqwest = Crate(name="reqwest", compile_seconds=11.5, kind="lib");

    # Lighter pure-Rust crates further up the chain.
    jsonschema = Crate(name="jsonschema", compile_seconds=13.6, kind="lib");
    hyper_rustls = Crate(name="hyper-rustls", compile_seconds=2.5, kind="lib");
    tokio_rustls = Crate(name="tokio-rustls", compile_seconds=2.0, kind="lib");

    # Workspace crates and the gated build script.
    engine_spec_build = BuildScript(
        name="libaipm-engine-spec", compile_seconds=0.0, produces="libaipm-engine-spec"
    );
    engine_spec = Crate(name="libaipm-engine-spec", compile_seconds=3.0, kind="lib");
    libaipm = Crate(name="libaipm", compile_seconds=4.0, kind="lib");
    aipm = Crate(name="aipm", compile_seconds=1.5, kind="bin");

    # Build-script dep edges: the C/asm native crates and the heavy
    # HTTP/TLS stack gate `libaipm-engine-spec`'s build.rs.
    engine_spec_build +>:BuildScriptDeps:+> aws_lc_sys;
    engine_spec_build +>:BuildScriptDeps:+> libgit2_sys;
    engine_spec_build +>:BuildScriptDeps:+> rustls;
    engine_spec_build +>:BuildScriptDeps:+> reqwest;
    engine_spec_build +>:BuildScriptDeps:+> jsonschema;

    # Normal link-time dependency edges along the critical path.
    jsonschema +>:DependsOn:+> reqwest;
    reqwest +>:DependsOn:+> rustls;
    rustls +>:DependsOn:+> hyper_rustls;
    rustls +>:DependsOn:+> tokio_rustls;

    # Final link chain: build script produces lib -> lib -> bin.
    engine_spec +>:DependsOn:+> engine_spec_build;
    libaipm +>:DependsOn:+> engine_spec;
    aipm +>:DependsOn:+> libaipm;

    # Attach to root so both walkers can spawn and walk.
    root ++> engine_spec_build;
    root ++> aipm;

    # --- Run the analyses ----------------------------------------------------
    cp = CriticalPath();
    root spawn cp;
    print("");
    print(f"Total compile seconds on walked chain: {cp.total_seconds:.1f}");
    print(f"Heaviest single unit: {cp.max_single_name} ({cp.max_single:.1f}s)");

    print("");
    bs = BuildScriptBottleneck();
    root spawn bs;
    print("");
    print(f"Found {len(bs.offenders)} build-script bottleneck(s)");
}
