"""Delivery route dispatcher: model depots and routes as a graph, then walk it to flag dispatch-eligible legs."""

node Route {
    has destination: str = "";
    has cargo_tonnes: float = 0.0;
}

node Depot {
    has name: str = "";
    has routes: list = [];

    def add_route(r: Route) -> None {
        self.routes.append(r);
    }

    def qualify(r: Route) -> bool {
        return r.cargo_tonnes >= 2.0 and r.cargo_tonnes <= 8.0;
    }
}

walker DispatchAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Depot entry {
        print(f"Depot {here.name}:");
        for r in here.routes {
            label = "DISPATCH" if here.qualify(r) else "HOLD";
            print(f"  [{label}] -> {r.destination} ({r.cargo_tonnes}t)");
        }
        visit [-->];
    }
}

with entry {
    north = Depot(name="North");
    south = Depot(name="South");

    north.add_route(Route(destination="Riverside", cargo_tonnes=3.5));
    north.add_route(Route(destination="Hilltop", cargo_tonnes=1.2));
    north.add_route(Route(destination="Lakeside", cargo_tonnes=8.0));

    south.add_route(Route(destination="Meadowford", cargo_tonnes=5.0));
    south.add_route(Route(destination="Pinegrove", cargo_tonnes=9.4));
    south.add_route(Route(destination="Cedarvale", cargo_tonnes=2.0));

    root ++> north ++> south;

    root spawn DispatchAuditor();
}
