test "executor visits each component once and emits exactly one stitch per junction" {
    buf = io.StringIO();
    a = Component(
        name="A",
        generators=[MeshGenerator(name="ag", offset=0.0)],
        junctions=[ComponentJunction(name="aj1"), ComponentJunction(name="aj2")],
