        f"each junction should fire exactly once, got {counts}; full log: {log}"
    );

    # addMeshGenerator lines must also appear exactly once per registered gen.
    gen_counts = {"ag": 0, "bg": 0};
    i = 0;
    while i < len(log) {
        e = log[i];
        if e == "addMeshGenerator on A: ag" {
            gen_counts["ag"] += 1;
        }
        if e == "addMeshGenerator on B: bg" {
            gen_counts["bg"] += 1;
        }
        i += 1;
