    assert gen_counts == {"ag": 1, "bg": 1}, (
        f"each generator should be added exactly once, got {gen_counts}; log: {log}"
    );
}

test "late-declared generator does not retroactively satisfy already-logged junction" {
    # Mirrors the issue's hazard: a component ends up with a junction list
    # populated and a generator list that is mutated to contain a mesh
    # generator AFTER the junction was registered. The executor still sees
