    late = Component(name="late", generators=[], junctions=[ComponentJunction(name="late_j")]);
    root ++> late;
    late.generators = [MeshGenerator(name="late_g", offset=9.0)];
    with redirect_stdout(buf) {
        res = root spawn PipelineExecutor();
    }
    log = res.log;

    found_stitch = False;
    found_no_gen = False;
    i = 0;
    while i < len(log) {
        e = log[i];
        if e.startswith("junction late_j on late -> stitches from last generator late_g") {
            found_stitch = True;
        }
        if e.startswith("!! junction late_j on late found NO generator") {
