"""Hotel guests pass by service desks; each desk charges the passing guest.

A walker models a guest strolling past a row of service desks. Each desk
adds its price to whichever guest is currently passing and prints the
charge as it happens. At the end we report what each guest owes.
"""

node Guest {
    has name: str = "";
    has total_owed: float = 0.0;
}

node ServiceDesk {
    has service: str = "";
    has price: float = 0.0;
}

walker StrollingGuest {
    has guest: Guest;

    can start with Root entry {
        visit [-->];
    }

    can pass_desk with ServiceDesk entry {
        self.guest.total_owed += here.price;
        print(f"{self.guest.name} got charged ${here.price} for {here.service} (now owes ${self.guest.total_owed})");
        visit [-->];
    }
}

walker Checkout {
    can start with Root entry {
        visit [-->];
    }

    can total with Guest entry {
        print(f"Checkout: {here.name} owes ${here.total_owed}");
        visit [-->];
    }
}

with entry {
    alice = Guest(name="Alice");
    bob = Guest(name="Bob");
    root ++> alice ++> bob;

    spa = ServiceDesk(service="spa session", price=80.0);
    dinner = ServiceDesk(service="room-service dinner", price=45.0);
    laundry = ServiceDesk(service="express laundry", price=20.0);
    root ++> spa ++> dinner ++> laundry;

    root spawn StrollingGuest(guest=alice);
    root spawn StrollingGuest(guest=bob);
    root spawn Checkout();
}
