```jac
"""Docker build cache: model the dependency graph that the build walks and
the cache invalidation that turns a tiny source edit into a 50-minute
DuckDB rebuild.

Entities: BuildStage (the heavy compile units), CacheMount (the named
BuildKit cache directories), SourceFile (the leaf source files that
trigger invalidation), and JobBudget (the parallelism/memory policy).

Relationships are typed edges:
  - depends_on   : a stage depends on another stage's output
  - caches_into  : a stage populates a named cache mount
  - invalidates  : a source file invalidates a stage when changed
  - bounded_by   : a stage is constrained by a job budget

The walker BuildAuditor walks the dependency graph from a starting
stage, accumulates the set of source files that would invalidate any
reachable stage, and reports the total cost. The cycle guard
(``visited`` set) is preserved because cycle detection on a dependency
graph is domain logic, not scaffolding.
"""

node BuildStage {
    has name: str = "";
    has kind: str = "";
    has compile_seconds: int = 0;
}

node CacheMount {
    has name: str = "";
    has persistent: bool = True;
}

node SourceFile {
    has path: str = "";
    has changed: bool = False;
}

node JobBudget {
    has label: str = "";
    has jobs: int = 1;
    has memory_cap_mb: int = 0;
}

edge depends_on  { has reason: str = ""; }
edge caches_into { }
edge invalidates { }
edge bounded_by  { }

walker BuildAuditor {
    has visited: list = [];
    has changed_files: list = [];
    has reachable_stages: list = [];
    has total_compile_seconds: int = 0;
    has native_invalidated: bool = False;

    can start with Root entry {
        print("BuildAuditor starting from root");
        visit [-->] else { disengage; }
    }

    can audit with BuildStage entry {
        if here.name in self.visited {
            print(f"  cycle detected at stage '{here.name}', disengaging");
            disengage;
        }
        self.visited.append(here.name);
        self.reachable_stages.append(here.name);
        self.total_compile_seconds += here.compile_seconds;
        if here.kind == "native" {
            self.native_invalidated = True;
        }
        print(f"  auditing stage '{here.name}' "
              f"(kind={here.kind}, cost={here.compile_seconds}s, "
              f"running total={self.total_compile_seconds}s)");

        visit [->:depends_on:->];
        visit [->:invalidates:->];
    }

    can collect_change with SourceFile entry {
        if here.changed and here.path not in self.changed_files {
            self.changed_files.append(here.path);
            print(f"  changed source noted: {here.path}");
        }
        # Leaves: no further traversal.
        visit [-->] else { disengage; }
    }

    can skip with CacheMount entry {
        visit [-->] else { disengage; }
    }

    can skip_job with JobBudget entry {
        visit [-->] else { disengage; }
    }
}

with entry {
    # ---- Build stages (the expensive compile units) ----
    app_stage    = BuildStage(name="app-crate",        kind="app",        compile_seconds=45);
    parser_stage = BuildStage(name="parser-crate",     kind="app",        compile_seconds=20);
    duckdb_stage = BuildStage(name="libduckdb-sys",    kind="native",     compile_seconds=2700);
    serde_stage  = BuildStage(name="serde",            kind="dependency", compile_seconds=120);
    tokio_stage  = BuildStage(name="tokio",            kind="dependency", compile_seconds=180);

    # ---- Cache mounts (the BuildKit cache directories) ----
    cargo_registry = CacheMount(name="cargo-registry", persistent=True);
    cargo_target   = CacheMount(name="cargo-target",   persistent=True);
    npm_cache      = CacheMount(name="npm",           persistent=True);

    # ---- Source files (the leaves that trigger invalidation) ----
    parser_rs   = SourceFile(path="src-tauri/src/parser.rs",   changed=True);
    main_rs     = SourceFile(path="src-tauri/src/main.rs",     changed=False);
    cargo_toml  = SourceFile(path="src-tauri/Cargo.toml",      changed=False);

    # ---- Job budgets (the parallelism/memory policy) ----
    low_mem  = JobBudget(label="low-mem",  jobs=1, memory_cap_mb=2048);
    balanced = JobBudget(label="balanced", jobs=4, memory_cap_mb=0);

    # ---- Wire the dependency graph ----
    parser_stage +>:depends_on(reason="uses DuckDB bindings"):+> duckdb_stage;
    app_stage    +>:depends_on(reason="calls into parser"):+> parser_stage;
    app_stage    +>:depends_on(reason="async runtime"):+> tokio_stage;
    parser_stage +>:depends_on(reason="serialization"):+> serde_stage;

    # ---- Wire source-file invalidations ----
    parser_rs  +>:invalidates:+> parser_stage;
    main_rs    +>:invalidates:+> app_stage;
    cargo_toml +>:invalidates:+> serde_stage;
    cargo_toml +>:invalidates:+> tokio_stage;

    # ---- Wire cache mounts (informational; auditor skips them) ----
    cargo_registry +>:caches_into:+> duckdb_stage;
    cargo_target   +>:caches_into:+> duckdb_stage;
    cargo_target   +>:caches_into:+> serde_stage;
    cargo_target   +>:caches_into:+> tokio_stage;
    npm_cache      +>:caches_into:+> app_stage;

    # ---- Wire job budgets ----
    duckdb_stage +>:bounded_by:+> low_mem;

    # ---- Root holds everything reachable from the entry point ----
    root ++> app_stage
        ++> cargo_registry
        ++> cargo_target
        ++> npm_cache
        ++> parser_rs
        ++> main_rs
        ++> cargo_toml
        ++> low_mem
        ++> balanced;

    # ---- Spawn the auditor starting from the app stage ----
    print("=== Docker build cache audit ===");
    print(f"Job budget in effect: {low_mem.label} "
          f"(jobs={low_mem.jobs}, cap={low_mem.memory_cap_mb}MB)");
    print("Walking the dependency graph from app-crate...");
    root spawn BuildAuditor();
}
