"""Repository-context topology: model workspaces, projects, packages, build
targets and entrypoints as nodes with typed edges, and traverse them with a
walker that performs the cascade-invalidation walk the issue complains about.

The repository-context provider plane maintains evidence-backed topology facts.
When a workspace changes (new digest, a project removed, a target invalidated)
the dependent facts must be re-validated. The original code hand-rolled this
cascade as a manual recursion over `parent_id` / adjacency maps; here we use
typed edges and a walker with an explicit cycle guard.
"""

# ---------- node archetypes ----------

node Workspace {
    has name: str = "";
    has digest: str = "";
}

node Project {
    has name: str = "";
    has kind: str = "library";
    has manifest_version: str = "";
    has invalidated: bool = False;
}

node Package {
    has name: str = "";
    has version: str = "";
}

node BuildTarget {
    has name: str = "";
    has coverage: str = "complete";
}

node Entrypoint {
    has name: str = "";
    has shell_cmd: str = "";
}

# ---------- typed edges ----------

edge Contains {
    has role: str = "member";
}

edge DependsOn {
    has authority: str = "tool-resolved";
}

edge Produces {
    has kind: str = "binary";
}

edge EntrypointOf {
}

# ---------- walker: cascade-invalidation over the repository graph ----------

walker CascadeInvalidate {
    has visited: list[str] = [];
    has queue: list = [];
    has invalidations: list[str] = [];
    has depth_cap: int = 32;

    can start with Root entry {
        # Begin at every workspace under root.
        visit [-->];
    }

    can descend with Workspace entry {
        self.queue = [];
        self.invalidations = [];
        print(f"workspace[{here.name}] digest={here.digest} "
              f"-> invalidate dependent projects");
        visit [-->];
    }

    can collect with Project | Package | BuildTarget | Entrypoint entry {
        # Union trigger: any graph node reached via Contains enters the
        # invalidation frontier. The dependency walker below will decide
        # which other nodes are transitively affected.
        self.queue.append(here);
        visit [-->];
    }

    can propagate with Project entry {
        # Cycle guard: never revisit a project; depth cap so pathological
        # dep graphs can't loop forever (probe-verified: jac 0.36.1 has
        # no built-in dedupe for visit, so the guard is explicit).
        key = f"Project::{here.name}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        if here.invalidated {
            return;
        }
        here.invalidated = True;
        self.invalidations.append(here.name);
        print(f"  invalidate project[{here.name}] kind={here.kind} "
              f"manifest_v={here.manifest_version}");

        # Cascade: every project we depend on must be reconsidered.
        visit [->:DependsOn:->];
    }

    can propagate_with_target with BuildTarget entry {
        key = f"BuildTarget::{here.name}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);
        if here.coverage == "unsupported" {
            print(f"  skip target[{here.name}]: unsupported coverage");
            disengage;
        }
        print(f"  target[{here.name}] coverage={here.coverage}");
    }

    can propagate_with_entrypoint with Entrypoint entry {
        key = f"Entrypoint::{here.name}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);
        print(f"  entrypoint[{here.name}] cmd={here.shell_cmd}");
    }
}

# ---------- demo wiring ----------

with entry {
    # Two workspaces side by side, each with projects, packages, targets,
    # entrypoints and inter-project dependencies.
    ws_alpha = Workspace(name="alpha", digest="sha256:aaaa");
    ws_beta = Workspace(name="beta", digest="sha256:bbbb");

    root ++> ws_alpha;
    root ++> ws_beta;

    # --- alpha workspace ---
    p_alpha_core = Project(
        name="alpha-core",
        kind="library",
        manifest_version="1.2.0"
    );
    p_alpha_cli = Project(
        name="alpha-cli",
        kind="application",
        manifest_version="0.4.0"
    );
    pkg_alpha_json = Package(name="@alpha/json", version="2.0.0");

    t_alpha_core = BuildTarget(name="alpha-core:lib", coverage="complete");
    t_alpha_cli = BuildTarget(name="alpha-cli:bin", coverage="partial");

    ep_alpha_cli = Entrypoint(name="alpha-cli.run", shell_cmd="alpha run");

    ws_alpha ++> p_alpha_core;
    ws_alpha ++> p_alpha_cli;
    ws_alpha ++> pkg_alpha_json;
    p_alpha_core +>:Contains(role="source-root"):+> pkg_alpha_json;
    p_alpha_core +>:Produces(kind="static-lib"):+> t_alpha_core;
    p_alpha_cli +>:Produces(kind="executable"):+> t_alpha_cli;
    t_alpha_cli +>:EntrypointOf:+> ep_alpha_cli;

    # --- beta workspace ---
    p_beta_lib = Project(
        name="beta-lib",
        kind="library",
        manifest_version="3.1.4"
    );
    p_beta_app = Project(
        name="beta-app",
        kind="application",
        manifest_version="0.9.0"
    );

    t_beta_lib = BuildTarget(name="beta-lib:cdylib", coverage="complete");
    t_beta_app = BuildTarget(name="beta-app:bin", coverage="complete");
    ep_beta_app = Entrypoint(name="beta-app.serve", shell_cmd="beta serve");

    ws_beta ++> p_beta_lib;
    ws_beta ++> p_beta_app;
    p_beta_lib +>:Produces(kind="cdylib"):+> t_beta_lib;
    p_beta_app +>:Produces(kind="executable"):+> t_beta_app;
    t_beta_app +>:EntrypointOf:+> ep_beta_app;

    # --- cross-project dependencies (tool-resolved authority) ---
    p_alpha_cli +>:DependsOn(authority="tool-resolved"):+> p_alpha_core;
    p_beta_app +>:DependsOn(authority="tool-resolved"):+> p_beta_lib;
    p_beta_app +>:DependsOn(authority="tool-resolved"):+> p_alpha_cli;

    # Spawn the cascade walker on root.
    root spawn CascadeInvalidate();
}
