"""Tests for ContinuationAudit and TruncationProbe walkers — binding correctness,
typed rejections, single-use semantics, and non-terminal truncation."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helper: build the canonical binding chain and return (repo, snap, scope,
# req, order, tok) so each test gets a fresh graph.
# ---------------------------------------------------------------------------
def build_chain() {
    repo = RepositoryRoot(root_id="repo-7");
    snap = Snapshot(snapshot_id="snap-2024-11-01");
    scope = QueryScope(scope="public_symbols");
    req = NormalizedRequest(normalized_query="name:continuation AND kind:edge");
    order = Ordering(ordering="alpha:asc");
    tok = ContinuationToken(token_id="ct-1", resume_position=40);

    repo +>:OwnsSnapshot(snapshot_id="snap-2024-11-01"):+> snap;
    snap +>:HoldsScope(scope="public_symbols"):+> scope;
    scope +>:HoldsRequest(normalized_query="name:continuation AND kind:edge"):+> req;
    req +>:HoldsOrdering(ordering="alpha:asc"):+> order;
    order +>:HoldsOrdering:+> tok;
    return [repo, snap, scope, req, order, tok];
}

test "valid resume succeeds and surfaces rows" {
    (repo, snap, scope, req, order, tok) = build_chain();

    audit = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn audit;

    assert audit.outcome == "RESUMED", f"got {audit.outcome}";
    assert audit.rows_resumed == 40, f"rows={audit.rows_resumed}";
    assert tok.consumed == True, f"token not consumed: {tok.consumed}";
}

test "changed snapshot is rejected with typed outcome" {
    (repo, snap, scope, req, order, tok) = build_chain();

    bad = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-OTHER",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn bad;

    assert bad.outcome == "REJECTED_SNAPSHOT", f"got {bad.outcome}";
    assert tok.consumed == False, f"token must remain fresh: {tok.consumed}";
}

test "changed normalized query is rejected with typed outcome" {
    (repo, snap, scope, req, order, tok) = build_chain();

    bad_q = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:something_else",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn bad_q;

    assert bad_q.outcome == "REJECTED_QUERY", f"got {bad_q.outcome}";
    assert tok.consumed == False, f"token must remain fresh: {tok.consumed}";
}

test "drifted resume position is rejected with typed outcome" {
    (repo, snap, scope, req, order, tok) = build_chain();

    bad_p = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=80
    );
    repo spawn bad_p;

    assert bad_p.outcome == "REJECTED_POSITION", f"got {bad_p.outcome}";
    assert tok.consumed == False, f"token must remain fresh: {tok.consumed}";
}

test "truncation must never be reported as terminal completeness" {
    (repo, snap, scope, req, order, tok) = build_chain();

    # page_size strictly less than total_known => must NOT look terminal.
    probe = TruncationProbe(page_size=50, total_known=137);
    root spawn probe;
    assert probe.terminal_appearance == False, f"got {probe.terminal_appearance}";

    # Equal sizes DO look terminal — this is the boundary the issue forbids
    # only when truncated; equality is genuine completeness.
    probe2 = TruncationProbe(page_size=137, total_known=137);
    root spawn probe2;
    assert probe2.terminal_appearance == True, f"got {probe2.terminal_appearance}";
}

