```jac
"""JsonApiClient-style relational pain, modeled with idiomatic Jac.

The original Ruby issue describes how a hand-rolled JSON API client makes
parent/child traversal, scope chaining, and cascade deletion awkward
because relationships live in id-keyed maps rather than as first-class
edges. We model the same domain -- orders and shipments with a belongs_to
link -- using typed edges and walkers, then exercise:

  * Topological dependency ordering of an order's shipment line items.
  * Cascade-delete of an order that purges its children.
  * Cycle detection across the belongs_to graph (the original library
    did not notice cycles; the walker does).
"""

# ---- Edge archetypes -------------------------------------------------------

# An order "has one" shipment (or many line items in the broader API).
edge HasShipment { has note: str = ""; }

# The shipment "belongs to" an order -- the upward relationship that the
# original issue complains is missing. We make it a real typed edge so a
# walker can climb from shipment back to order without an id-keyed map.
edge BelongsToOrder { }

# Items that roll up under an order. Used for dependency ordering.
edge HasLineItem { }


# ---- Node archetypes -------------------------------------------------------

node LineItem {
    has sku: str = "";
    has qty: int = 0;
}

node Shipment {
    has tracking: str = "";
}

node Order {
    has title: str = "";
    has status: str = "draft";

    # Demo helper that mimics the issue's "remove a resource" path:
    # destroys an order and cleans up its child graph.
    def purge_with_children() {
        # disconnect every edge from this order, then delete it.
        # `del --> neighbor` removes the typed edge; `del self` removes
        # the node and auto-purges any remaining edges.
        for n in [-->] {
            here del --> n;
        }
        del here;
    }
}


# ---- Walkers ---------------------------------------------------------------

# Walk an order's line items in a stable dependency order (by sku).
# This replaces the manual recursion that the original client demanded.
walker LineItemAudit {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        print(f"Auditing order {here.title} ({here.status})");
        visit [->:HasLineItem:->];
    }

    can collect with LineItem entry {
        label = f"{here.sku} x{here.qty}";
        self.report_lines.append(label);
        # leaf node -- nothing further to walk.
        visit [-->] else { disengage; }
    }

    # One exit report so the caller can inspect the collected list.
    can report with Root exit {
        print(f"Audit result: {self.report_lines}");
    }
}


# Cascade-delete walker: spawn on an Order, walk its children, then
# delete the root order itself. This is the scenario the issue
# describes as broken (`order.shipment.destroy` failing because the
# relationship linker cannot walk upward).
walker CascadePurge {
    can start with Root entry {
        visit [->:HasShipment:->];
    }

    can purge_shipment with Shipment entry {
        print(f"Deleting shipment {here.tracking}");
        # remove the belongs_to edge back to the order so the order
        # is not orphaned by the link, then drop the shipment node.
        here del ->:BelongsToOrder:-> [-->];
        del here;
        visit [-->] else { disengage; }
    }

    can purge_order with Order entry {
        print(f"Purging order {here.title}");
        here.purge_with_children();
        # Once the root order is gone the walk has no frontier.
        visit [-->] else { disengage; }
    }
}


# Cycle detection: the JSON API client silently let `Order -> Shipment
# -> Order` loops exist. Our walker maintains an explicit visited set
# (jac 0.36.1 walkers have no built-in dedup) and reports any cycle.
walker CycleWatch {
    has seen: list = [];
    has cycle_found: bool = False;

    can start with Root entry {
        self.seen.append(here);
        visit [->:BelongsToOrder:->];
    }

    # Union trigger: fires for either Order or Shipment nodes.
    can check with Order | Shipment entry {
        if here in self.seen {
            self.cycle_found = True;
            print(f"Cycle detected at {here}");
            disengage;
        }
        self.seen.append(here);
        visit [->:BelongsToOrder:->] else { disengage; }
    }
}


# ---- Demo ------------------------------------------------------------------

with entry {
    # Build a small order graph: one order, one shipment, two items.
    order = Order(title="ORD-1", status="shipped");
    ship = Shipment(tracking="TRK-99");
    item_a = LineItem(sku="WIDGET", qty=2);
    item_b = LineItem(sku="GIZMO", qty=5);

    root ++> order;
    order +>:HasShipment:+> ship;
    ship +>:BelongsToOrder:+> order;
    order +>:HasLineItem:+> item_a;
    order +>:HasLineItem:+> item_b;

    # 1. Topological audit of the order's line items.
    root spawn LineItemAudit();

    # 2. Cascade purge -- the case the issue complains is broken.
    print("--- cascade purge ---");
    root spawn CascadePurge();

    # 3. Cycle detection. We deliberately wire a loop to prove the
    # walker notices it (the original client did not).
    print("--- cycle check ---");
    a = Order(title="A");
    b = Order(title="B");
    root ++> a ++> b;
    # a belongs to b, b belongs to a -- a 2-cycle.
    a +>:BelongsToOrder:+> b;
    b +>:BelongsToOrder:+> a;
    root spawn CycleWatch();
}
```

test "typed relationship links support upward traversal" {
    order = Order(title="ORD-1", status="shipped");
    ship = Shipment(tracking="TRK-99");

    root ++> order;
    order +>:HasShipment:+> ship;
    ship +>:BelongsToOrder:+> order;

    assert len([order ->:HasShipment:->]) == 1, f"shipment link count mismatch";
    assert ship in [order ->:HasShipment:->], f"missing shipment from order";
    assert order in [ship ->:BelongsToOrder:->], f"missing parent from shipment";
}

