    item = LineItem(sku="WIDGET", qty=2);

    root ++> order;
    order +>:HasLineItem:+> item;

    res = root spawn LineItemAudit();

    assert len(res.report_lines) == 1, f"audit count: {res.report_lines}";
    assert res.report_lines[0] == "WIDGET x2", f"audit line: {res.report_lines}";
