    root +>:BelongsToOrder:+> first_order;
    first_order +>:BelongsToOrder:+> second_order;
    second_order +>:BelongsToOrder:+> first_order;

    res = root spawn CycleWatch();

    assert res.cycle_found == True, f"cycle flag: {res.cycle_found}";
    assert len(res.seen) == 3, f"visited nodes: {res.seen}";
}

