"""Sidebar collections tree: walk ordered folders and invalidate ancestors on moves."""

node Library {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Collection {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has depth: int = 0;
    has invalidated: bool = False;
}

edge Contains {
    has position: int = 0;
}

walker SidebarIndexer {
    has scanned: int = 0;
    has depth_bound_hits: int = 0;
    has max_depth: int = 6;

    can start with Library entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can scan with Collection entry {
        self.scanned = self.scanned + 1;
        here.invalidated = True;
        print(f"album:list -> {here.title} at depth {here.depth}");

        if here.depth >= self.max_depth {
            self.depth_bound_hits = self.depth_bound_hits + 1;
            print(f"depth bound reached at {here.title}");
        } else {
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }
}

walker MoveInvalidator {
    has touched: int = 0;

    can invalidate with Collection entry {
        here.invalidated = True;
        self.touched = self.touched + 1;
        print(f"album:move invalidated {here.title}");
        visit [<--] else {
            disengage;
        }
    }
}

