"""Native graph demo for transform readiness and dependency-cycle detection."""

node Artifact {
    has output_id: str = "";
    has available: bool = True;
}

node Transform {
    has name: str = "";
    has declared_inputs: int = 0;
    has distinct_inputs: int = 0;
    has available_inputs: int = 0;
    has missing_input: str = "";
    has state: str = "pending";
}

edge DependsOn {
    has input_id: str = "";
}

walker DependencyResolver {
    can begin with Root entry {
        print("resolving transform dependencies");
        visit [-->] else { disengage; }
    }

    can inspect with Transform entry {
        if (here.state != "pending") {
            skip;
        } else {
            if (here.distinct_inputs == here.available_inputs) {
                here.state = "ready";
                print(f"{here.name} is ready: {here.available_inputs}/{here.distinct_inputs} distinct inputs from {here.declared_inputs} declarations");
            } else {
                here.state = "blocked";
                print(f"{here.name} is unresolved: {here.available_inputs}/{here.distinct_inputs} distinct inputs available; missing {here.missing_input}");
            }
            visit [->:DependsOn:->] else {
                print(f"{here.name} uses the empty-input fallback");
                disengage;
            }
        }
    }
}

walker CycleDetector {
    has route: str = "";

    can inspect with Transform entry {
        if (here.state != "pending") {
            print(f"cycle detected: {self.route} -> {here.name}");
            disengage;
        } else {
            here.state = "visiting";
            next_route = here.name if self.route == "" else f"{self.route} -> {here.name}";
            self.route = next_route;
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

with entry {
    src = Artifact(output_id="src");
    t1 = Transform(name="t1", declared_inputs=1, distinct_inputs=1, available_inputs=1);
    t2 = Transform(name="t2", declared_inputs=2, distinct_inputs=2, available_inputs=2);
    partial = Transform(name="partial", declared_inputs=2, distinct_inputs=2, available_inputs=1, missing_input="t1");
    duplicate = Transform(name="duplicate", declared_inputs=2, distinct_inputs=1, available_inputs=1);
    empty = Transform(name="empty");
    c1 = Transform(name="c1");
    c2 = Transform(name="c2");

    root ++> t1;
    root ++> t2;
    root ++> partial;
    root ++> duplicate;
    root ++> empty;

    t1 +>:DependsOn(input_id="src"):+> src;
    t2 +>:DependsOn(input_id="src"):+> src;
    t2 +>:DependsOn(input_id="t1"):+> t1;
    partial +>:DependsOn(input_id="src"):+> src;
    duplicate +>:DependsOn(input_id="src"):+> src;

    c1 +>:DependsOn(input_id="c2"):+> c2;
    c2 +>:DependsOn(input_id="c1"):+> c1;

    root spawn DependencyResolver();
    c1 spawn CycleDetector();
}
