"""Build system dependency auditor: traverse a diamond DAG and total build minutes,
counting each task exactly once even when reached via multiple paths."""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has total_minutes: int = 0;
    has visited_ids: list = [];

    can start with Root entry {
        print("Starting dependency audit...");
        visit [-->];
    }

    can audit with Task entry {
        already_counted = False;
        for vid in self.visited_ids {
            if vid == here {
                already_counted = True;
            }
        }
        if not already_counted {
            self.visited_ids.append(here);
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"Auditing {here.title} (+{here.minutes} min)");
        } else {
            print(f"Skipping duplicate path to {here.title}");
        }
        visit [-->];
    }
}

with entry {
    core = Task(title="core-lib", minutes=10);
    io = Task(title="io-lib", minutes=8);
    utils = Task(title="utils", minutes=5);
    parser = Task(title="parser", minutes=12);
    compiler = Task(title="compiler", minutes=20);
    linker = Task(title="linker", minutes=7);

    # Diamond DAG: core and io are shared by parser and compiler; linker depends on both.
    root ++> core ++> utils ++> parser ++> linker;
    root ++> io ++> utils;
    root ++> core ++> parser;
    root ++> io ++> compiler ++> linker;

    auditor = Auditor();
