"""Water pipeline tracer: walk a pipe graph from the intake, log each segment,
note dead-end valves gracefully, and summarize the full route."""

node Valve {
    has name: str = "";
    has pressure: float = 0.0;
    has capped: bool = False;
}

edge Pipe {
    has diameter: str = "";
    has length_m: float = 0.0;
}

walker Tracer {
    has route: list[str] = [];
    has dead_ends: list[str] = [];
    has depth_limit: int = 25;
    has depth: int = 0;

    can start with Root entry {
        self.route = [];
        self.dead_ends = [];
        self.depth = 0;
        visit [-->];
    }

    can trace with Valve entry {
        segment = f"{here.name} (P={here.pressure:.1f})";
        self.route.append(segment);
        self.depth += 1;

        if self.depth >= self.depth_limit {
            print(f"[DEPTH-LIMIT] bail out at {here.name}");
            self.dead_ends.append(here.name);
            return;
        }

        if here.capped {
            print(f"[DEAD-END] capped valve: {here.name}");
            self.dead_ends.append(here.name);
            return;
        }

        next_nodes = [->:Pipe:->];
        if not next_nodes {
            print(f"[DEAD-END] no outgoing pipe from {here.name}");
            self.dead_ends.append(here.name);
            return;
        }

        print(f"[FLOW] {here.name} -> {len(next_nodes)} pipe(s) downstream");
        visit next_nodes else {
            print(f"[DEAD-END] traverse failed at {here.name}");
            self.dead_ends.append(here.name);
            disengage;
        };
    }

    can summarize with Root exit {
        print("");
        print("=== PIPELINE TRACE SUMMARY ===");
        if not self.route {
            print("No valves reached from intake.");
        } else {
            step = 0;
            for label in self.route {
                print(f"  {step}: {label}");
                step += 1;
            }
        }
        print(f"Total valves visited: {len(self.route)}");
        print(f"Dead ends encountered: {len(self.dead_ends)}");
        for name in self.dead_ends {
            print(f"  - {name}");
        }
    }
}

with entry {
    intake = Valve(name="Intake-A", pressure=120.0);
    junction_b = Valve(name="Junction-B", pressure=110.0);
    junction_c = Valve(name="Junction-C", pressure=105.0);
    capped_d = Valve(name="Cap-D", pressure=0.0, capped=True);
    service_e = Valve(name="Service-E", pressure=95.0);
    stub_f = Valve(name="Stub-F", pressure=0.0, capped=True);

    root +>:Pipe(diameter="24in", length_m=10.0):+> intake;
    intake +>:Pipe(diameter="18in", length_m=30.0):+> junction_b;
    intake +>:Pipe(diameter="18in", length_m=25.0):+> junction_c;
    junction_b +>:Pipe(diameter="12in", length_m=15.0):+> capped_d;
    junction_b +>:Pipe(diameter="12in", length_m=40.0):+> service_e;
    junction_c +>:Pipe(diameter="10in", length_m=8.0):+> stub_f;

    root spawn Tracer(depth_limit=25);
}
