"""TMA menu release: restaurant grouping, derivative lineage, and split-leakage audit."""

node Restaurant {
    has restaurant_id: str = "";
    has name: str = "";
}

node MenuImage {
    has image_id: str = "";
    has is_source: bool = True;
    has caption: str = "";
    has split_name: str = "";
}

node MenuGroup {
    has group_key: str = "";
    has split_name: str = "";
}

node TrainingSplit {
    has split_name: str = "";
    has allows_augmented: bool = False;
}

edge Owns { }
edge DerivedFrom { has aug_type: str = ""; }
edge MemberOf { }
edge BoundTo { }

walker Grouper {
    can start with Root entry {
        print("--- Resolving deterministic group keys ---");
        visit [-->];
    }

    can resolve with Restaurant entry {
        key = here.restaurant_id if here.restaurant_id != "" else "document_fallback";
        print(f"  {here.name} -> group key '{key}'");
        visit [-->];
    }
}

walker ReleasePackager {
    has seen_ids: list[str] = [];
    has stamp_split: str = "";

    can start with Root entry {
        print("");
        print("--- Packaging release: stamp splits through lineage ---");
        visit [-->];
    }

    can stamp_group with MenuGroup entry {
        self.stamp_split = here.split_name;
        self.seen_ids = [];
        print(f"Group {here.group_key} bound to split '{self.stamp_split}'");
        visit [<-:MemberOf:<-] else { disengage; };
    }

    can stamp_image with MenuImage entry {
        if here.image_id in self.seen_ids {
            disengage;
        }
        self.seen_ids += [here.image_id];
        here.split_name = self.stamp_split;
        kind = "SOURCE" if here.is_source else "AUG";
        print(f"  stamp {here.image_id} [{kind}] -> {self.stamp_split}");
        visit [<-:DerivedFrom:<-] else { disengage; };
    }
}

walker LeakageAuditor {
    has violations: int = 0;
    has lineage_seen: list[str] = [];
    has root_split: str = "";
    has in_lineage_walk: bool = False;

    can start with Root entry {
        print("");
        print("=== Auditing split leakage across derivative lineage ===");
        visit [-->];
    }

    can inspect with MenuImage entry {
        if self.in_lineage_walk {
            if here.image_id in self.lineage_seen {
                print(f"  [CYCLE] {here.image_id}");
                self.violations += 1;
                self.in_lineage_walk = False;
                disengage;
            }
            self.lineage_seen += [here.image_id];
            status = "OK" if here.split_name == self.root_split else "LEAK";
            if status == "LEAK" {
                self.violations += 1;
                print(f"  [{status}] {here.image_id} in '{here.split_name}', want '{self.root_split}'");
            } else {
                print(f"  [{status}] derivative {here.image_id}");
            }
            visit [<-:DerivedFrom:<-] else {
                self.in_lineage_walk = False;
                disengage;
            };
        } else {
            if here.is_source {
                self.root_split = here.split_name;
                self.lineage_seen = [];
                self.in_lineage_walk = True;
                print(f"Lineage root {here.image_id} (split='{self.root_split}')");
                visit [<-:DerivedFrom:<-] else {
                    self.in_lineage_walk = False;
                    disengage;
                };
            }
            visit [-->];
        }
    }
}

with entry {
    train = TrainingSplit(split_name="train", allows_augmented=True);
    val = TrainingSplit(split_name="val", allows_augmented=False);

    rest_noodle = Restaurant(restaurant_id="r_noodle", name="Noodle House");
    rest_taco = Restaurant(restaurant_id="r_taco", name="Taco Cart");

    grp_noodle = MenuGroup(group_key="r_noodle", split_name="train");
    grp_taco = MenuGroup(group_key="r_taco", split_name="val");

    grp_noodle +>:BoundTo:+> train;
    grp_taco +>:BoundTo:+> val;

    src_menu = MenuImage(image_id="img_001", is_source=True, caption="page 1 OCR");
    aug_blur = MenuImage(image_id="img_001_blur", is_source=False, caption="blur corruption");
    aug_crop = MenuImage(image_id="img_001_crop", is_source=False, caption="crop augmentation");
    src_taco = MenuImage(image_id="img_002", is_source=True, caption="taco page 1");

