    root ++> grp_noodle ++> grp_taco;
    root ++> src_menu ++> aug_blur ++> aug_crop;
    root ++> src_taco;

    rest_noodle +>:Owns:+> src_menu;
    rest_taco +>:Owns:+> src_taco;

    aug_blur +>:DerivedFrom(aug_type="blur"):+> src_menu;
    aug_crop +>:DerivedFrom(aug_type="crop"):+> src_menu;

