"""Online store checkout: one walker handles many product types via union triggers.

Each product archetype knows its own shipping and handling rules. The
``Cashier`` walker walks the cart and uses a single union ability on the
common ``Product`` base so every concrete type triggers the right line on
the receipt.
"""

node Product {
    has name: str = "";
    has price: float = 0.0;

    def shipping_cost() -> float;
    def handling_cost() -> float;
}

node PaperBook(Product) {
    has weight_lb: float = 0.0;

    override def shipping_cost() -> float {
        return self.weight_lb * 1.50;
    }
    override def handling_cost() -> float {
        return 0.75;
    }
}

node DigitalBook(Product) {
    has size_mb: float = 0.0;

    override def shipping_cost() -> float {
        return 0.0;
    }
    override def handling_cost() -> float {
        return 0.10;
    }
}

node Electronics(Product) {
    has warranty_months: int = 0;

    override def shipping_cost() -> float {
        return 9.99;
    }
    override def handling_cost() -> float {
        return 2.50;
    }
}

node Clothing(Product) {
    has size: str = "M";

    override def shipping_cost() -> float {
        return 4.99;
    }
    override def handling_cost() -> float {
        return 0.50;
    }
}

walker Cashier {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has handling: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    # Union trigger: fires for any concrete Product subtype.
    # Only fields/methods shared by every Product subclass are touched
    # here (name, price, shipping_cost, handling_cost).
    can ring_up with PaperBook | DigitalBook | Electronics | Clothing entry {
        ship = here.shipping_cost();
        hand = here.handling_cost();
        line_total = here.price + ship + hand;
        self.subtotal += here.price;
        self.shipping += ship;
        self.handling += hand;
        print(
            f"{here.name}: ${here.price:.2f} + ship ${ship:.2f}"
            f" + handling ${hand:.2f} = ${line_total:.2f}"
        );
        visit [-->];
    }
}

with entry {
    cart = [
        PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.2),
        DigitalBook(name="Refactoring (eBook)", price=24.00, size_mb=12.5),
        Electronics(name="Wireless Headphones", price=149.00, warranty_months=24),
        Clothing(name="Hoodie", price=45.00, size="L"),
    ];

    root ++> cart[0] ++> cart[1] ++> cart[2] ++> cart[3];

    cashier = Cashier();
    root spawn cashier;

    grand_total = cashier.subtotal + cashier.shipping + cashier.handling;
    print("---");
    print(f"Subtotal : ${cashier.subtotal:.2f}");
    print(f"Shipping : ${cashier.shipping:.2f}");
    print(f"Handling : ${cashier.handling:.2f}");
    print(f"Total    : ${grand_total:.2f}");
}
