    can invalidate_snapshots with Snapshot entry {
        if here.dependency_fingerprint != self.current_fingerprint {
            here.valid = False;
            self.invalidated_count += 1;
            print(f"Stale cache entry {here.cache_key} for {here.sha} invalidated");
        }
    }
}

