        mapped_key = self.tour_lookup.get(here.show_date);
        if mapped_key is None {
            self.missing_count += 1;
            audit = RollupAudit(
                show_date=here.show_date,
                tour_key="",
                tour_key_missing=True,
                severity="error",
                note=f"tourKey missing for showDate={here.show_date}"
            );
            here ++> audit;
            print(f"[ERROR] tourKeyMissing=true showDate={here.show_date} title={here.title}");
        } else {
            print(f"[OK]    showDate={here.show_date} tour={mapped_key} title={here.title}");
        }
        visit [-->];
    }
}

walker DriftScanner {
    has drifted_dates: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Show entry {
        visit [-->];
    }

    can collect with RollupAudit entry {
        if here.tour_key_missing {
            self.drifted_dates.append(here.show_date);
        }
        visit [-->];
    }

    can collect_root with Root exit {
        if len(self.drifted_dates) > 0 {
            print(f"admin badge: {len(self.drifted_dates)} tour-key-missing docs -> {self.drifted_dates}");
        } else {
            print("admin badge: no drift detected");
        }
    }
}

with entry {
    # Calendar snapshot: only 2 of the 4 shows are mapped to tours.
    # Mirrors the production divergence: some rollups ran before the
    # snapshot had a tour group for their date.
    calendar = {
        "2024-07-10": "Sphere Run",
        "2024-08-12": "Sphere Run",
        # "2024-06-05" and "2024-09-20" intentionally missing -> drift
    };

    s1 = Show(title="Sphere Run Opener", show_date="2024-07-10");
    s2 = Show(title="Sphere Run Mid", show_date="2024-08-12");
    s3 = Show(title="Pre-tour Tune-up", show_date="2024-06-05");
    s4 = Show(title="Unscheduled Pickup", show_date="2024-09-20");

    root ++> s1 ++> s2 ++> s3 ++> s4;

    auditor = RollupAuditor(tour_lookup=calendar);
    root spawn auditor;

    print(f"--- audit summary: tour_key_missing count = {auditor.missing_count} ---");

    scanner = DriftScanner();
    root spawn scanner;
}
