```jac
"""Health-inspect a restaurant kitchen line.

Two inspectors sweep every station: one flags stations whose temperature
exceeds 40 C, the other logs every station visit. Both must run at every
station, so each walker exposes a single union ability that fires once
per station node and chains into the next via a typed edge.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

edge NextStation { has label: str = ""; }

walker TempInspector {
    can start with Root entry {
        visit [-->];
    }

    can sweep with Station entry {
        flag = "VIOLATION" if here.celsius > 40.0 else "OK";
        print(f"[{flag}] {here.name} at {here.celsius} C");
        visit [-->] else { disengage; }
    }
}

walker VisitLogger {
    can start with Root entry {
        visit [-->];
    }

    can log with Station entry {
        print(f"  log: visited {here.name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    grill = Station(name="Grill", celsius=180.0);
    fryer = Station(name="Fryer", celsius=22.0);
    cold = Station(name="Cold Prep", celsius=5.0);
    root ++> grill ++> fryer ++> cold;

    print("== Temperature inspection ==");
    root spawn TempInspector();
    print("== Visit log ==");
    root spawn VisitLogger();
}
```

"""Tests for the kitchen health-inspection walkers.

We exercise the two walkers independently against fresh per-test graphs so
that each test asserts exactly one behavior (temp flagging vs. visit log),
plus a combined test that verifies both run at every station.
"""

import io;
import from contextlib { redirect_stdout }

# --- helpers ---------------------------------------------------------------

def build_line(cold_c: float = 5.0, fryer_c: float = 22.0, grill_c: float = 180.0) {
    grill = Station(name="Grill", celsius=grill_c);
    fryer = Station(name="Fryer", celsius=fryer_c);
    cold = Station(name="Cold Prep", celsius=cold_c);
    root ++> grill ++> fryer ++> cold;
    return [grill, fryer, cold];
}

# --- tests -----------------------------------------------------------------

test "temp inspector flags hot station and clears cool ones" {
    build_line();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TempInspector();
    }
    out = buf.getvalue();
    # Grill at 180 C must be flagged VIOLATION; fryer (22) and cold (5) must be OK.
    assert "[VIOLATION] Grill at 180.0 C" in out, f"expected Grill violation, got: {out!r}";
    assert "[OK] Fryer at 22.0 C" in out, f"expected Fryer OK, got: {out!r}";
    assert "[OK] Cold Prep at 5.0 C" in out, f"expected Cold Prep OK, got: {out!r}";
    # Boundary: exactly 40.0 C is NOT a violation (strict greater-than).
    assert "[OK] Grill at 40.0 C" not in out, "40.0 C boundary wrongly produced in first run";
}

test "temp inspector boundary: exactly 40 C is not a violation" {
    grill = Station(name="Grill", celsius=40.0);
    fryer = Station(name="Fryer", celsius=40.0);
    cold = Station(name="Cold Prep", celsius=40.0);
    root ++> grill ++> fryer ++> cold;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TempInspector();
    }
    out = buf.getvalue();
    assert "VIOLATION" not in out, f"40.0 C must not be flagged: {out!r}";
    assert out.count("[OK]") == 3, f"expected 3 OK lines at 40 C, got: {out!r}";
}

test "visit logger records every station exactly once" {
    build_line();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn VisitLogger();
    }
    out = buf.getvalue();
    # Each station must be logged exactly once, in graph order.
    assert "  log: visited Grill" in out, f"missing Grill log: {out!r}";
    assert "  log: visited Fryer" in out, f"missing Fryer log: {out!r}";
    assert "  log: visited Cold Prep" in out, f"missing Cold Prep log: {out!r}";
    assert out.count("log: visited") == 3, f"expected exactly 3 log lines, got: {out!r}";
    # Logger must not emit temperature flags.
    assert "VIOLATION" not in out and "[OK]" not in out, f"logger emitted temp flags: {out!r}";
}

test "both walkers run at every station in a single inspection" {
    build_line();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TempInspector();
        root spawn VisitLogger();
    }
    out = buf.getvalue();
    # Every station name appears in both a temp line and a log line.
    for name in ["Grill", "Fryer", "Cold Prep"] {
        temp_lines = [ln for ln in out.splitlines() if (name in ln and ("VIOLATION" in ln or "[OK]" in ln))];
        log_lines = [ln for ln in out.splitlines() if (name in ln and "log: visited" in ln)];
        assert len(temp_lines) == 1, f"{name}: expected 1 temp line, got {temp_lines!r} in {out!r}";
        assert len(log_lines) == 1, f"{name}: expected 1 log line, got {log_lines!r} in {out!r}";
    }
    # Headers come from the demo entry block; tests must still see both
    # kinds of output regardless.
    assert "VIOLATION" in out, "combined run lost violation signal";
    assert "log: visited" in out, "combined run lost log signal";
}

