    # Only Buddy and Tweety should have been vaccinated.
    assert len(res.patients) == 2, f"expected 2 patients, got {res.patients}";
    assert res.shots_given == 2, f"expected 2 shots, got {res.shots_given}";

    # Names recorded in walk order.
    assert res.patients[0] == "Buddy", f"first patient should be Buddy, got {res.patients[0]}";
    assert res.patients[1] == "Tweety", f"second patient should be Tweety, got {res.patients[1]}";

    # Walker's own list (independent of the walker instance returned)
    # should match what spawn returned.
    assert vet.patients == res.patients, f"vet.patients {vet.patients} != res.patients {res.patients}";
    assert vet.shots_given == res.shots_given, f"vet.shots_given {vet.shots_given} != res.shots_given {res.shots_given}";

    # Mutation during walk: every pet that needed a vaccine must now be cleared.
    pets = [root -->];
    for p in pets {
        if p.name in ["Buddy", "Tweety"] {
            assert p.needs_vaccine == False, f"{p.name} should be vaccinated now, but needs_vaccine={p.needs_vaccine}";
        } else {
            assert p.needs_vaccine == False, f"{p.name} was never flagged, should remain False";
        }
