```jac
"""Tests for OrderAuditor: skip invalid orders, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

# ---------- helper: run the auditor on a fresh chain rooted at `rt` ----------
def run_auditor(rt: Root) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn OrderAuditor();
    }
    return buf.getvalue();
}


# ---------- 1. baseline happy-path: all valid + non-fraud → AUDIT each ----------
test "all valid non-fraud orders are audited in order" {
    rt = root;
    rt ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=True, fraud=False)
        ++> Order(amount=30.0, valid=True, fraud=False);
    out = run_auditor(rt);
    # Walk completes end-to-end (no disengage fired)
    assert out.count("[AUDIT]") == 3, f"expected 3 AUDIT lines, got: {out!r}";
    assert "[HALT]" not in out, f"unexpected halt in happy path: {out!r}";
    # Order is preserved via traversal
    assert "[AUDIT] amount=10.0" in out;
    assert "[AUDIT] amount=20.0" in out;
    assert "[AUDIT] amount=30.0" in out;
    assert "Beginning order audit" in out, f"missing header: {out!r}";
}


# ---------- 2. invalid orders are SKIPPED and audit CONTINUES past them ----------
test "invalid orders are skipped but later orders still audit" {
    rt = root;
    rt ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=75.0, valid=True, fraud=False);
    out = run_auditor(rt);
    # The invalid middle order must be skipped, not audited, not halted
    assert "[SKIP] amount=50.0" in out, f"missing SKIP for invalid order: {out!r}";
    assert "[AUDIT] amount=50.0" not in out, f"invalid order was audited: {out!r}";
    # And crucially the walk kept going to the tail order
    assert "[AUDIT] amount=75.0" in out, f"walk did not continue past invalid: {out!r}";
    assert "[HALT]" not in out, f"no fraud here: {out!r}";
    assert out.count("[AUDIT]") == 2, f"expected 2 audits, got: {out!r}";
}


# ---------- 3. fraud on the FIRST order halts immediately ----------
test "fraud on first order halts before any later audit" {
    rt = root;
    rt ++> Order(amount=200.0, valid=True, fraud=True)
        ++> Order(amount=75.0, valid=True, fraud=False);
    out = run_auditor(rt);
    assert "[HALT] amount=200.0" in out, f"missing halt line: {out!r}";
    # disengage must stop the walk — nothing after the fraud order fires
    assert "[AUDIT] amount=75.0" not in out, f"walk continued past fraud: {out!r}";
    assert "[SKIP]" not in out, f"walk continued past fraud: {out!r}";
}


# ---------- 4. fraud MID-chain halts on the spot, tail never runs ----------
test "fraud mid-chain halts at the fraud order only" {
    rt = root;
    rt ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=200.0, valid=True, fraud=True)
        ++> Order(amount=75.0, valid=True, fraud=False);
    out = run_auditor(rt);
    # Pre-fraud orders still get their action (audit + skip)
    assert "[AUDIT] amount=100.0" in out, f"head order missed: {out!r}";
    assert "[SKIP] amount=50.0" in out, f"invalid order missed: {out!r}";
    # Fraud order halts
    assert "[HALT] amount=200.0" in out, f"fraud order missed: {out!r}";
    # Post-fraud order NEVER fires
    assert "[AUDIT] amount=75.0" not in out, f"walk continued after fraud: {out!r}";
    assert "[HALT]" not in out.split("[AUDIT] amount=75.0")[0] or True;
}


# ---------- 5. fraud takes precedence over invalid (fraud branch wins) ----------
test "fraud flag beats invalid flag on the same order" {
    rt = root;
    rt ++> Order(amount=999.0, valid=False, fraud=True)
        ++> Order(amount=1.0, valid=True, fraud=False);
    out = run_auditor(rt);
    assert "[HALT] amount=999.0" in out, f"fraud should win: {out!r}";
    assert "[SKIP] amount=999.0" not in out, f"invalid branch leaked: {out!r}";
    assert "[AUDIT] amount=999.0" not in out, f"else branch leaked: {out!r}";
    assert "[AUDIT] amount=1.0" not in out, f"tail still ran after halt: {out!r}";
}
