```jac
"""Permission scope resolution: model files/folders as nodes and walk
the authorization hierarchy with a walker that resolves access without
recursively climbing parent_id chains."""

node Project {
    has name: str = "";
}

node Folder {
    has label: str = "";
    has owner_project_name: str = "";
    has access_scope_label: str = "";
}

node File {
    has label: str = "";
}

node AccessScope {
    has label: str = "";
    has kind: str = "PROJECT";
}

node AccessGrant {
    has principal_name: str = "";
    has principal_kind: str = "USER";
    has role: str = "READ";
}

edge Owns {
    has since: str = "";
}

edge ScopedBy {
}

edge Grants {
}

edge Contains {
}

walker AccessResolver {
    has user_name: str = "alice";
    has requested_role: str = "READ";
    has verdict: str = "DENY";
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect with Project entry {
        print(f"[Project] {here.name}");
        visit [-->];
    }

    can inspect_scope with AccessScope entry {
        print(f"[Scope]   {here.label} (kind={here.kind})");
        if here.kind == "PROJECT" {
            for grant in [-->](?:AccessGrant) {
                if grant.principal_kind == "USER" and grant.principal_name == self.user_name {
                    if self._role_satisfies(grant.role) {
                        self.verdict = "ALLOW";
                        self.reason = f"project scope {here.label} grants {grant.role} to {grant.principal_name}";
                    }
                }
            }
        } else {
            for grant in [-->](?:AccessGrant) {
                ok_user = (grant.principal_kind == "USER" and grant.principal_name == self.user_name);
                ok_proj = (grant.principal_kind == "PROJECT");
                if (ok_user or ok_proj) and self._role_satisfies(grant.role) {
                    self.verdict = "ALLOW";
                    self.reason = f"folder scope {here.label} grants {grant.role} to {grant.principal_name}";
                }
            }
        }
        visit [-->];
    }

    can inspect_folder with Folder entry {
        print(f"[Folder]  {here.label} -> owner={here.owner_project_name} scope={here.access_scope_label}");
        visit [-->];
    }

    can inspect_file with File entry {
        print(f"[File]    {here.label}");
        visit [-->];
    }

    def _role_satisfies(granted: str) -> bool {
        rank = {"READ": 1, "WRITE": 2, "ADMIN": 3};
        return rank.get(granted, 0) >= rank.get(self.requested_role, 0);
    }
}

walker ScopePrinter {
    can start with Root entry {
        print("--- Authorization hierarchy walk ---");
        visit [-->];
    }

    can show_project with Project entry {
        print(f"Project: {here.name}");
        visit [-->];
    }

    can show_scope with AccessScope entry {
        print(f"  Scope[{here.kind}]: {here.label}");
        visit [-->];
    }

    can show_folder with Folder entry {
        print(f"    Folder: {here.label} (owner={here.owner_project_name}, scope={here.access_scope_label})");
        visit [-->];
    }

    can show_file with File entry {
        print(f"      File: {here.label}");
        visit [-->];
    }
}

with entry {
    proj_a = Project(name="ProjectA");
    proj_b = Project(name="ProjectB");
    root ++> proj_a ++> proj_b;

    proj_scope = AccessScope(label="ScopeA", kind="PROJECT");
    shared_scope = AccessScope(label="ScopeSharedX", kind="FOLDER");
    proj_a ++> proj_scope;
    proj_b ++> shared_scope;

    proj_scope +>:Grants:+> AccessGrant(principal_name="alice", principal_kind="USER", role="WRITE");
    proj_scope +>:Grants:+> AccessGrant(principal_name="bob", principal_kind="USER", role="READ");
    shared_scope +>:Grants:+> AccessGrant(principal_name="alice", principal_kind="USER", role="READ");
    shared_scope +>:Grants:+> AccessGrant(principal_name="ProjectB", principal_kind="PROJECT", role="READ");

    folder_x = Folder(label="FolderX", owner_project_name="ProjectA", access_scope_label="ScopeSharedX");
    folder_y = Folder(label="FolderY", owner_project_name="ProjectA", access_scope_label="ScopeA");
    folder_z = Folder(label="FolderZ", owner_project_name="ProjectB", access_scope_label="ScopeB-proj");
    proj_a ++> folder_x;
    proj_a ++> folder_y;
    proj_b ++> folder_z;

    file1 = File(label="readme.md");
    file2 = File(label="design.txt");
    file3 = File(label="budget.csv");
    folder_x ++> file1;
    folder_y ++> file2;
    folder_z ++> file3;

    root spawn ScopePrinter();

    print("");
    print("--- Resolving alice's WRITE on File/file1 (shared folder scope) ---");
    resolver = AccessResolver(user_name="alice", requested_role="WRITE");
    file1 spawn resolver;
    print(f"verdict={resolver.verdict}  reason={resolver.reason}");

    print("");
    print("--- Resolving alice's READ on File/file3 (other project's project scope) ---");
    resolver2 = AccessResolver(user_name="alice", requested_role="READ");
    file3 spawn resolver2;
    print(f"verdict={resolver2.verdict}  reason={resolver2.reason}");

    print("");
    print("--- Resolving bob's ADMIN on File/file1 (should be DENY) ---");
    resolver3 = AccessResolver(user_name="bob", requested_role="ADMIN");
    file1 spawn resolver3;
    print(f"verdict={resolver3.verdict}  reason={resolver3.reason}");
}
