    body +>:IterationBack:+> r;
    body ++> terminal;
    r +>:IterationExit:+> exit_sink;
    exit_sink +>:TopicRestore:+> topic;

    establish_edges = [edge it ->:IterableEstablish:->];
    bind_edges = [edge r ->:TopicBind:->];

    assert len([root-->]) == 1, f"root children: {len([root-->])}";
    assert it in [root-->], f"iterable is not rooted: {it.producer_id}";
    assert len(establish_edges) == 1, f"establish edges: {len(establish_edges)}";
