```jac
"""Codex review re-entry guard.

Models the scenario from issue #34288: a built-in review turn inherits a
local skill whose description matches review tasks, and that skill launches
another ``codex review``. Without a host-level guard each review turn
re-selects the same inherited skill and the chain recurses.

We model:

* a ``ReviewTurn`` node (one built-in review session),
* a ``Skill`` node carrying an optional ``launches_review`` flag,
* the typed ``InheritsSkill`` edge from turn -> skill,
* the typed ``Invokes`` edge representing a launch.

A ``ReviewChain`` walker walks each turn's inherited skills, and refuses to
descend into a child review turn once the chain depth exceeds the host's
``max_depth``. This is the host-level nested-review guard the issue asks
for; it preserves the domain rule (no unbounded re-entry) while moving the
traversal off hand-rolled recursion.
"""

node Skill {
    has name: str = "";
    has description: str = "";
    has launches_review: bool = False;
    # Mirror of parent turn's depth, used when deciding whether to spawn
    # another review. Kept on the skill so the union ability only touches
    # fields that exist on every node it handles.
    has depth: int = 0;
}

node ReviewTurn {
    has label: str = "";
    has depth: int = 0;
}

edge InheritsSkill {
    has inherited_at: str = "";
}

edge Invokes {
    has command: str = "";
}

walker ReviewChain {
    has max_depth: int = 2;
    has visited_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_turn with ReviewTurn entry {
        # Domain rule: a review turn must not re-enter review past max_depth.
        if self.max_depth <= 0 {
            print(f"[GUARD] depth exhausted at {here.label}; refusing to re-enter review");
            disengage;
        }
        print(f"[TURN depth={here.depth}] {here.label}");
        # Visit inherited skills (typed edge traversal).
        visit [->:InheritsSkill:->];
    }

    can inspect_skill with Skill entry {
        tag = "REVIEW-LAUNCHING" if here.launches_review else "ordinary";
        print(f"  skill[{tag}] {here.name} :: {here.description}");
        # If the skill launches a review, descend into a child turn.
        if here.launches_review {
            child_depth = here.depth + 1;
            if child_depth >= self.max_depth {
                print(f"  [GUARD] would exceed max_depth={self.max_depth}; not spawning child review");
                disengage;
            }
            # Build a child review turn and wire it to the same inherited skill.
            child = ReviewTurn(label=f"child-{here.name}", depth=child_depth);
            here +>:InheritsSkill(inherited_at="reentry"):+> child;
            child +>:Invokes(command="codex review --base origin/main"):+> here;
            visit [-->];
        }
    }
}

with entry {
    # The broad local skill that triggers re-entry (the immediate cause).
    broad_skill = Skill(
        name="local-review-helper",
        description="broad match for code-review tasks",
        launches_review=True,
        depth=0
    );

    # A well-scoped, non-recursive skill for contrast.
    narrow_skill = Skill(
        name="lint-helper",
        description="narrow match, only runs linters",
        launches_review=False,
        depth=0
    );

    # Root review turn inherits the broad skill (the original report's case).
    root_turn = ReviewTurn(label="root-review", depth=0);
    root ++> root_turn;
    root_turn +>:InheritsSkill(inherited_at="parent"):+> broad_skill;
    root_turn +>:InheritsSkill(inherited_at="parent"):+> narrow_skill;

    # Spawn the walker with a tight cap to mirror the requested host guard.
    ReviewChain(max_depth=2) spawn root;
}
