"""PalioBoard modernization spec: tracer-bullet tasks with dependencies,
bounded contexts as node archetypes, dependencies as typed edges, and a
walker that detects dependency cycles before scheduling."""

# A Context is a DDD bounded context (e.g. Race, Jockey, Betting).
node Context {
    has name: str = "";
    has owner: str = "";
    has status: str = "open";
}

# A TracerBullet is a thin vertical slice that crosses one or more contexts
# to prove the toolchain end-to-end.
node TracerBullet {
    has title: str = "";
    has sequence: int = 0;
    has done: bool = False;
}

# A Dependency is a typed edge: this bullet MUST complete before `target`
# can start. Carries `kind` so we can distinguish hard-block vs soft-info.
edge DependsOn {
    has kind: str = "hard";
}

# SpecWalker walks the bullet graph in dependency order, detects cycles
# (because jac 0.36.1 walkers have no built-in visited-set — the issue's
# hand-rolled machinery exists precisely because of this), and reports.
walker SpecWalker {
    has order: list[str] = [];
    has guard: list[str] = [];
    has cycle: str = "";

    can start with Root entry {
        visit [-->];
    }

    # Single union ability over the two entity archetypes we touch.
    can traverse with Context | TracerBullet entry {
        name = str(here);
        if name in self.guard {
            self.cycle = name;
            disengage;
        }
        self.guard.append(name);
        self.order.append(name);
        visit [->:DependsOn:->];
    }
}

with entry {
    # Bounded contexts from the spec.
    race_ctx = Context(name="Race", owner="collepasso");
    jockey_ctx = Context(name="Jockey", owner="palio");
    betting_ctx = Context(name="Betting", owner="open");

    # Tracer-bullet sequence: scaffolding -> API contract -> FE feature -> e2e.
    scaffold = TracerBullet(title="scaffold", sequence=1);
    contract = TracerBullet(title="api-contract", sequence=2);
    feature = TracerBullet(title="fe-feature", sequence=3);
    e2e = TracerBullet(title="e2e-tracer", sequence=4);

    # Wire contexts under root and chain bullets with typed DependsOn edges.
    root ++> race_ctx ++> jockey_ctx ++> betting_ctx;
    scaffold +>:DependsOn:+> contract;
    contract +>:DependsOn:+> feature;
    feature +>:DependsOn:+> e2e;
    root ++> scaffold;

    spec = SpecWalker();
    root spawn spec;

    if spec.cycle != "" {
        print(f"CYCLE detected touching {spec.cycle}");
    } else {
        print("Tracer-bullet order (dependency-first):");
        for step in spec.order {
            print(f"  - {step}");
        }
    }
}
