"""NIP-68 picture composition: bytes-only MIME derivation across all sources.

A private byte classifier sits inside the picture crate. It is the ONLY
authority that mints the closed ``m`` field on ``PictureImage``. Upload
descriptors, URL extensions, request headers, and caller strings are
never consulted as authority -- at most they are checked for consistency,
and disagreement is a typed refusal.

The walker ``MintedImage`` walks the graph from each composition source
(direct upload, BUD-05 transformed retrieval, in-memory fixture) through
the shared picture boundary, exercising the same byte-derived classifier
on each path. Mutating the source-side descriptor/header string cannot
change the derived ``m``.
"""

node VerifiedAsset {
    has source_label: str = "";
    has size: int = 0;
    has sha256: str = "";
    has sig0: int = 0;
    has sig1: int = 0;
    has sig2: int = 0;
    has sig3: int = 0;
}

node BlobDescriptor {
    has source_label: str = "";
    has claimed_mime: str = "";
}

node ClassifiedFormat {
    has source_label: str = "";
    has mime: str = "";
    has refusal: str = "";
}

node PictureImage {
    has source_label: str = "";
    has m: str = "";
    has descriptor_claimed: str = "";
}

node Refusal {
    has source_label: str = "";
    has reason: str = "";
}

edge VerifiedBy {
    has via: str = "";
}

edge WantsMime {
    has claimed: str = "";
}

edge Derives {
    has via: str = "";
}

edge RefusedBy {
    has why: str = "";
}

walker MintedImage {
    has path_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_asset with VerifiedAsset entry {
        self.path_log.append(
            f"asset[{here.source_label}] sig=({here.sig0:02x},{here.sig1:02x},{here.sig2:02x},{here.sig3:02x})"
        );
        visit [-->];
    }

    can inspect_descriptor with BlobDescriptor entry {
        self.path_log.append(
            f"descriptor[{here.source_label}] claim={here.claimed_mime}"
        );
        visit [-->];
    }

    can inspect_format with ClassifiedFormat entry {
        label = here.mime if here.mime != "" else "(none)";
        self.path_log.append(
            f"format[{here.source_label}] m={label} refusal={here.refusal}"
        );
        visit [-->];
    }

    can inspect_picture with PictureImage entry {
        label = here.m if here.m != "" else "(none)";
        self.path_log.append(
            f"picture[{here.source_label}] m={label} claimed={here.descriptor_claimed}"
        );
        visit [-->];
    }

    can inspect_refusal with Refusal entry {
        self.path_log.append(
            f"refusal[{here.source_label}] why={here.reason}"
        );
        visit [-->];
    }
}

