"""Hiking trail: plain waypoints between trailhead and summit, traversed by a hiker walker."""

node Waypoint {
    has label: str = "";
    has order: int = 0;
}

walker Hiker {
    has stop_count: int = 0;
    has goal: int = 4;

    can start with Root entry {
        print("Hiker begins the ascent from the trailhead.");
        visit [-->];
    }

    can hike with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop #{self.stop_count}: {here.label}");
        if self.stop_count >= self.goal {
            print(f"Trail complete — passed {self.stop_count} waypoints and reached the summit!");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    base = Waypoint(label="Trailhead", order=1);
    w1 = Waypoint(label="Creek Crossing", order=2);
    w2 = Waypoint(label="Lookout Ridge", order=3);
    w3 = Waypoint(label="Alpine Meadow", order=4);
    summit = Waypoint(label="Summit", order=5);
    root ++> base ++> w1 ++> w2 ++> w3 ++> summit;

    root spawn Hiker();
}
