"""Combined depot query: from the root, fan out to every depot, walk every store each depot serves, and flag stores with stock below 20 units."""

node Store {
    has name: str = "";
    has stock: int = 0;
}

node Depot {
    has name: str = "";
}

edge Serves {
    has since: str = "";
}

walker StockAuditor {
    has low_stock_count: int = 0;
    has flagged: list[str] = [];

    can start with Root entry {
        print("Auditing all depots from combined root query");
        visit [-->];
    }

    can fan_out with Depot entry {
        print(f"  -> scanning depot: {here.name}");
        visit [-->];
    }

    can check_store with Store entry {
        if here.stock < 20 {
            status = "LOW";
            self.low_stock_count += 1;
            self.flagged.append(here.name);
        } else {
            status = "OK";
        }
        print(f"    [{status}] {here.name}: stock={here.stock}");
    }
}

with entry {
    d1 = Depot(name="Depot-North");
    d2 = Depot(name="Depot-South");
    d3 = Depot(name="Depot-East");
    root ++> d1 ++> d2 ++> d3;

    d1 +>:Serves(since="2020"):+> Store(name="North-A", stock=45);
    d1 +>:Serves(since="2020"):+> Store(name="North-B", stock=12);
    d2 +>:Serves(since="2021"):+> Store(name="South-A", stock=30);
    d2 +>:Serves(since="2021"):+> Store(name="South-B", stock=8);
    d2 +>:Serves(since="2021"):+> Store(name="South-C", stock=55);
    d3 +>:Serves(since="2022"):+> Store(name="East-A", stock=15);
    d3 +>:Serves(since="2022"):+> Store(name="East-B", stock=70);

    auditor = StockAuditor();
    root spawn auditor;
}
