"""Sandbox seed router: model the AniList locale-routing dependency and
walk the cache graph with a walker that traces the cold-start path the
spec implicitly relied on, demonstrating why hand-rolled adjacency forces
specs to depend on live fetches instead of typed-edge traversal.
"""

# --- Node archetypes ----------------------------------------------------------

node Anime {
    has anilist_id: int = 0;
    has title: str = "";
    has source: str = "";     # "seeded" or "anilist-live"
    has available: bool = True;
}

node LocaleRoute {
    has code: str = "";       # "en", "zh-Hant", ...
    has path_template: str = "";
}

node Spec {
    has name: str = "";
    has network_dependent: bool = False;
}

node Runner {
    has label: str = "";
    has warmed: bool = False;
}

# --- Typed edges (relationships that carry meaning) ---------------------------

edge SeededFixture {}        # fixture --seeded--> anime (deterministic local data)
edge ColdFetch {}           # anime --cold_fetch--> anime (the slow AniList pull)
edge RoutesTo {}            # locale --routes_to--> anime
edge AssertedBy {}          # spec --asserted_by--> locale (or spec --asserted_by--> anime)
edge WarmUp {}              # runner --warm_up--> route (healthy baseline)

# --- Walkers ------------------------------------------------------------------

walker ColdStartTracer {
    has visited_ids: list = [];
    has cold_start_seen: bool = False;
    has spec_network_dependent: bool = False;

    can begin with Root entry {
        print(f"[trace] starting cold-start walk from root");
        visit [-->];
    }

    can inspect_seed with Anime entry {
        # If this anime was fetched live (not seeded), flag it: a spec that
        # points here will fail when the network is slow or refused.
        self.visited_ids.append(here.anilist_id);
        if here.source == "anilist-live" {
            self.cold_start_seen = True;
            print(f"[trace] /anime/{here.anilist_id} ({here.title}) "
                  f"served via COLD live fetch - spec at risk");
        } else {
            print(f"[trace] /anime/{here.anilist_id} ({here.title}) "
                  f"served via SEEDED fixture - deterministic");
        }
        visit [->:ColdFetch:->];
    }

    can inspect_locale with LocaleRoute entry {
        # Show which anime each locale routes to and whether that target
        # is a seeded fixture or a cold live fetch.
        targets = [here->:RoutesTo:->];
        for target in targets {
            label = "seeded" if target.source == "seeded" else "live-fetch";
            print(f"[trace] locale {here.code} -> /anime/"
                  f"{target.anilist_id} ({label})");
            self.visited_ids.append(target.anilist_id);
            if target.source == "anilist-live" {
                self.cold_start_seen = True;
                self.spec_network_dependent = True;
            }
        }
        visit [-->];
    }

    can inspect_spec with Spec entry {
        # Surface the spec's dependency shape: if a spec asserts a route
        # whose anime is live-fetched, the spec is network-dependent.
        deps = [here->:AssertedBy:->];
        live = False;
        for d in deps {
            sub = [d->:RoutesTo:->];
            for t in sub {
                if t.source == "anilist-live" { live = True; }
            }
        }
        is_live = live;
        here.network_dependent = is_live;
        if live { self.spec_network_dependent = True; }
        risk = "NETWORK-DEPENDENT" if live else "deterministic";
        print(f"[trace] spec '{here.name}' is {risk}");
        visit [-->];
    }

    can inspect_runner with Runner entry {
        print(f"[trace] runner {here.label} warmed={here.warmed}");
        visit [-->];
    }
}

walker CacheInvalidator {
    has purged_ids: list = [];

    can begin with Root entry {
        print(f"[invalidate] cascading cache purge from root");
        visit [-->];
    }

    can purge with Anime entry {
        # Simulate the cascade: drop an anime and any locale routes that
        # pointed at it, forcing a refetch on next access.
        self.purged_ids.append(here.anilist_id);
        print(f"[invalidate] dropped /anime/{here.anilist_id} "
                f"({here.title}); refetch required");
        visit [-->];
    }

    can purge_route with LocaleRoute entry {
        sentinel = -1;
        self.purged_ids.append(sentinel);
        print(f"[invalidate] cleared locale route {here.code} "
                f"({here.path_template})");
        visit [-->];
    }
}

# --- Demonstration graph ------------------------------------------------------
with entry {
    # Seeded fixtures (the good path the issue wants extended).
    a21    = Anime(anilist_id=21,   title="One Piece",            source="seeded");
    a11061 = Anime(anilist_id=11061, title="Cowboy Bebop",        source="seeded");

    # Anime 1535: still left as a live fetch - this is the bug surface.
    a1535  = Anime(anilist_id=1535, title="Naruto",                source="anilist-live");

    en   = LocaleRoute(code="en",     path_template="/en/anime/{id}");
    hant = LocaleRoute(code="zh-Hant", path_template="/zh-Hant/anime/{id}");
    bare = LocaleRoute(code="*",       path_template="/anime/{id}");

    routing_spec = Spec(name="locale-routing.spec.ts");
    episode_spec = Spec(name="episode-display.spec.ts");
    auth_spec    = Spec(name="auth.spec.ts");

    runner = Runner(label="github-runner", warmed=True);

    # Wire the graph.
    root +>:SeededFixture:+> a21;
    root +>:SeededFixture:+> a11061;
    root +>:ColdFetch:+> a1535;

    bare +>:RoutesTo:+> a21;        # /anime/21  -> seeded (fixed by the patch)
    en   +>:RoutesTo:+> a21;        # /en/anime/21
    hant +>:RoutesTo:+> a21;        # /zh-Hant/anime/21

    bare +>:RoutesTo:+> a1535;      # /anime/1535 -> live (still fragile)
    en   +>:RoutesTo:+> a11061;     # /en/anime/11061

    routing_spec +>:AssertedBy:+> bare;
    routing_spec +>:AssertedBy:+> en;
    routing_spec +>:AssertedBy:+> hant;
    episode_spec +>:AssertedBy:+> a21;
    auth_spec    +>:AssertedBy:+> bare;

    runner +>:WarmUp:+> bare;
    runner +>:WarmUp:+> en;
    runner +>:WarmUp:+> hant;

    # Spawn the walker that traces the cold-start path and tells us
    # which specs are still network-dependent.
    tracer = ColdStartTracer();
    root spawn tracer;

    print("");
    print(f"[summary] visited anime ids: {tracer.visited_ids}");
    print(f"[summary] cold-start path observed: {tracer.cold_start_seen}");
    net_dep = tracer.spec_network_dependent;
    summary_label = "NETWORK-DEPENDENT" if net_dep else "deterministic";
    print(f"[summary] locale-routing.spec is {summary_label}");

    # Cascade purge to show the hand-rolled traversal the issue describes.
    print("");
    inv = CacheInvalidator();
    root spawn inv;
    print(f"[summary] purged ids (incl. synthetic route markers): {inv.purged_ids}");
}
