"""Project-folder database tree: recursively activate/deactivate nested projects.

Models the Maproom/qmapshack issue where a folder's activation checkbox must
cascade down to every nested project. The cascade is expressed as a typed
edge traversal performed by an ActivateFolder walker; cycle safety is kept
explicit because walkers in jac 0.36.1 do not deduplicate visited nodes
(visit [-->] on a cyclic graph hangs).
"""

node ProjectFolder {
    has name: str = "";
    has activated: bool = False;
}

node Project {
    has title: str = "";
    has loaded: bool = False;
}

edge Contains {
    has depth: int = 0;
}

walker ActivateFolder {
    has desired_state: bool = True;
    has touched: int = 0;

    can start with Root entry {
        print(f"[cascading {'activate' if self.desired_state else 'deactivate'}] from root");
        visit [-->];
    }

    can cascade_folder with ProjectFolder entry {
        here.activated = self.desired_state;
        self.touched += 1;
        print(f"  folder  {here.name:<10} -> activated={here.activated}");
        visit [->:Contains:->];
    }

    can cascade_project with Project entry {
        here.loaded = self.desired_state;
        self.touched += 1;
        print(f"  project {here.title:<10} -> loaded={here.loaded}");
        # project leaves cannot cascade further
    }
}

# A separate walker that demonstrates an alternate reachability-style walk:
# collect every project beneath a given root folder using a guard set so the
# traversal terminates even if the folder graph accidentally contains a cycle.
walker CollectProjects {
    has seen: list[str] = [];
    can start with Root entry {
        visit [-->];
    }
    can into_folder with ProjectFolder entry {
        key = f"folder::{here.name}";
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        visit [->:Contains:->];
    }
    can into_project with Project entry {
        key = f"project::{here.title}";
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        print(f"  reachable project: {here.title}");
    }
}

with entry {
    # Build a small nested tree:
    #   Europe
    #     ├── Alps
    #     │    ├── TourA
    #     │    └── TourB
    #     └── Pyrenees
    #          └── TourC
    alps = ProjectFolder(name="Alps");
    pyrenees = ProjectFolder(name="Pyrenees");
    europe = ProjectFolder(name="Europe");
    root ++> europe;

    europe +>:Contains(depth=1):+> alps;
    europe +>:Contains(depth=1):+> pyrenees;

    tour_a = Project(title="TourA");
    tour_b = Project(title="TourB");
