    tour_c = Project(title="TourC");
    pyrenees +>:Contains(depth=2):+> tour_c;

    # Demonstrate: activating "Europe" must load every nested project.
    print("=== activate Europe ===");
    europe spawn ActivateFolder(desired_state=True);
    print(f"Europe folder activated={europe.activated}");
    print(f"Alps folder activated={alps.activated}");
    print(f"Pyrenees folder activated={pyrenees.activated}");
    print(f"TourA loaded={tour_a.loaded}, TourB loaded={tour_b.loaded}, TourC loaded={tour_c.loaded}");

    # Demonstrate: deactivating "Alps" must unload only its subtree.
    print("=== deactivate Alps ===");
    alps spawn ActivateFolder(desired_state=False);
    print(f"Alps folder activated={alps.activated}");
    print(f"Europe folder still activated={europe.activated}");
    print(f"TourA loaded={tour_a.loaded}, TourB loaded={tour_b.loaded}");

    # Demonstrate: a reachability-style walk over the same tree.
