import io;
import from contextlib { redirect_stdout }

test "diamond counts core exactly once" {
    core = Task(name="core", minutes=10);
    module_a = Task(name="module_a", minutes=25);
    module_b = Task(name="module_b", minutes=15);
    app = Task(name="app", minutes=5);

    root ++> core
        ++> module_a ++> core
        ++> module_b ++> core
        ++> app ++> module_a ++> module_b;

    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    # Each task must be printed exactly once.
    assert out.count("[10m] core") == 1, f"core should print once, got: {out}";
    assert out.count("[25m] module_a") == 1, f"module_a should print once, got: {out}";
    assert out.count("[15m] module_b") == 1, f"module_b should print once, got: {out}";
    assert out.count("[5m] app") == 1, f"app should print once, got: {out}";

    # Totals must reflect deduplication: 4 unique tasks, 10+25+15+5 = 55 minutes.
    summary = res.totals();
    assert summary["count"] == 4, f"expected 4 unique tasks, got {summary['count']}";
    assert summary["minutes"] == 55, f"expected 55 minutes, got {summary['minutes']}";
    assert "core" in summary["tasks"], f"core missing from tasks: {summary['tasks']}";
    assert "module_a" in summary["tasks"], f"module_a missing from tasks: {summary['tasks']}";
    assert "module_b" in summary["tasks"], f"module_b missing from tasks: {summary['tasks']}";
    assert "app" in summary["tasks"], f"app missing from tasks: {summary['tasks']}";
}

