```jac
"""Pythia λ_ca-vs-loss collapse demo.

Models the issue: per-checkpoint LM loss on a fixed Pile slice is
recomputed for a chain of Pythia checkpoints, then a walker collapses
the resulting (loss, λ_ca) pairs to a single residual so we can see
whether the collapse holds across checkpoints.

No I/O, no external libraries — just the graph machinery the issue is
complaining about, lifted into nodes / typed edges / walkers.
"""

# --------------------------------------------------------------------
# Entity archetypes
# --------------------------------------------------------------------

node Checkpoint {
    has step: int = 0;
    has seed: int = 0;
    has loss: float = 0.0;
    has lambda_ca: float = 0.0;
    has is_pile: bool = True;
}

node EvalSlice {
    has name: str = "";
    has token_count: int = 0;
    has is_training_distribution: bool = False;
}

node CollapseTest {
    has label: str = "";
    has seed_floor: float = 0.0;
}

# --------------------------------------------------------------------
# Typed edges
# --------------------------------------------------------------------

edge ScoredOn {
    has note: str = "";
}

edge NextStep {
    has delta_step: int = 0;
}

edge SeedSibling {
}

edge Produces {
}

# --------------------------------------------------------------------
# Walker that recomputes loss-style information and then "collapses"
# --------------------------------------------------------------------

walker LossCollapser {
    has slice_name: str = "pile-val";
    has pairs: list[tuple[float, float]] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with EvalSlice entry {
        if not here.is_training_distribution {
            print(f"skipping non-training slice: {here.name}");
            disengage;
        }
        visit [->:ScoredOn:->];
    }

    can sweep with Checkpoint entry {
        self.pairs.append((here.loss, here.lambda_ca));
        visit [->:NextStep:->];
    }

    can finalise with CollapseTest entry {
        if len(self.pairs) == 0 {
            print(f"{here.label}: no pairs to collapse");
            disengage;
        }
        sx = 0.0;
        sy = 0.0;
        sxy = 0.0;
        sxx = 0.0;
        for (l, lam) in self.pairs {
            sx += l;
            sy += lam;
            sxy += l * lam;
            sxx += l * l;
        }
        n = float(len(self.pairs));
        denom = n * sxx - sx * sx;
        slope = 0.0 if denom == 0.0 else (n * sxy - sx * sy) / denom;
        mean_l = sx / n;
        mean_lam = sy / n;
        residual = 0.0;
        for (l, lam) in self.pairs {
            pred = mean_lam + slope * (l - mean_l);
            d = lam - pred;
            residual += d * d;
        }
        residual = residual / n;
        floor = here.seed_floor;
        verdict = "collapse" if residual <= floor else "no-collapse";
        print(
            f"{here.label}: pairs={len(self.pairs)} "
            f"slope={slope:.4f} residual={residual:.4f} "
            f"floor={floor:.4f} -> {verdict}"
        );
    }
}

# --------------------------------------------------------------------
# Walker that walks the seed family of a single configuration to
# establish the per-model noise floor (arXiv:2507.02119).
# --------------------------------------------------------------------

walker SeedFloorProbe {
    has values: list[float] = [];
    has target_step: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can probe with Checkpoint entry {
        if here.step != self.target_step {
            visit [->:NextStep:->];
        } else {
            self.values.append(here.loss);
            visit [->:SeedSibling:->];
        }
    }
}

# --------------------------------------------------------------------
# Demo wiring
# --------------------------------------------------------------------

with entry {
    pile = EvalSlice(name="pile-val", token_count=100000, is_training_distribution=True);
    wikitext = EvalSlice(name="wikitext-103", token_count=100000, is_training_distribution=False);

    c0 = Checkpoint(step=1000, seed=0, loss=3.10, lambda_ca=0.92);
    c1 = Checkpoint(step=2000, seed=0, loss=2.70, lambda_ca=0.78);
    c2 = Checkpoint(step=3000, seed=0, loss=2.45, lambda_ca=0.55);

    c0b = Checkpoint(step=1000, seed=1, loss=3.12, lambda_ca=0.93);
    c0c = Checkpoint(step=1000, seed=2, loss=3.08, lambda_ca=0.91);

    root ++> pile ++> wikitext;
    root ++> c0 +>:NextStep(delta_step=1000):+> c1 +>:NextStep(delta_step=1000):+> c2;
    c0 +>:SeedSibling:+> c0b;
    c0 +>:SeedSibling:+> c0c;

    pile +>:ScoredOn(note="recomputed"):+> c0;
    pile +>:ScoredOn(note="recomputed"):+> c1;
    pile +>:ScoredOn(note="recomputed"):+> c2;

    test_real = CollapseTest(label="pile-real-floor", seed_floor=0.0);
    test_tiny = CollapseTest(label="pile-tiny-floor", seed_floor=1e-9);

    root ++> test_real;
    root ++> test_tiny;
    test_real +>:Produces:+> pile;
    test_tiny +>:Produces:+> pile;

    floor_probe = SeedFloorProbe(target_step=1000);
    pile spawn floor_probe;
    floor = 0.0;
    if len(floor_probe.values) > 0 {
        mean = 0.0;
        for v in floor_probe.values {
            mean += v;
        }
        mean = mean / float(len(floor_probe.values));
        var = 0.0;
        for v in floor_probe.values {
            d = v - mean;
            var += d * d;
        }
        var = var / float(len(floor_probe.values));
        floor = var;
    }
    test_real.seed_floor = floor;
    print(f"measured seed-floor at step 1000 from {len(floor_probe.values)} seeds = {floor:.6f}");

    real_walker = LossCollapser(slice_name="pile-val");
    pile spawn real_walker;
    print(f"real_walker pairs: {real_walker.pairs}");

    tiny_walker = LossCollapser(slice_name="pile-val");
    pile spawn tiny_walker;
    print(f"tiny_walker pairs: {tiny_walker.pairs}");
}
