"""Recovery replay compatibility audit with typed dependency-closure traversal."""

node RecoveryReceipt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_commit_sha: str = "";
    has target_base_sha: str = "";
    has replayed_paths_digest: str = "";
    has analysis_profile: str = "";
    has verdict: str = "UNKNOWN_DEFER";
}

node ReplayPath {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_digest: str = "";
    has target_digest: str = "";
    has replayed: bool = True;
}

node Dependency {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has dependency_kind: str = "";
    has source_identity: str = "";
    has target_identity: str = "";
    has unresolved: bool = False;
    has dynamic: bool = False;
}

edge Replays { }
edge Requires { }
edge DependsOn { }

walker ClosureAuditor {
    has visited: list[str] = [];
    has drift_count: int = 0;
    has unknown_count: int = 0;

    can start with Root entry {
        print("Auditing recovery semantic compatibility closure");
        visit [-->] else {
            disengage;
        }
    }

    can audit_receipt with RecoveryReceipt entry {
        print(f"receipt {here.title}: {here.verdict}");
        print(f"source={here.source_commit_sha}, target={here.target_base_sha}");
        visit [->:Replays:->] else {
            disengage;
        }
    }

    can audit_path with ReplayPath entry {
        if here.source_digest == here.target_digest {
            print(f"path {here.title}: byte-identical replay");
        } else {
            print(f"path {here.title}: replay digest mismatch");
            self.drift_count += 1;
        }

        visit [->:Requires:->] else {
            disengage;
        }
    }

    can audit_dependency with Dependency entry {
        if here.title in self.visited {
            print(f"cycle or repeated dependency guarded: {here.title}");
            disengage;
        } else {
            self.visited.append(here.title);

            if here.unresolved or here.dynamic {
                print(f"UNKNOWN_DEFER: {here.title} ({here.dependency_kind})");
                self.unknown_count += 1;
            } else {
                if here.source_identity == here.target_identity {
                    print(f"closure match: {here.title}");
                } else {
                    print(f"dependency drift: {here.title} ({here.dependency_kind})");
                    self.drift_count += 1;
                }
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

