    has fed: bool = False;

    def meal() -> str {
        return "meat";
    }
}

node Parrot {
    has name: str = "";
    has fed: bool = False;

    def meal() -> str {
        return "seed";
    }
}

node Zebra {
    has name: str = "";
    has fed: bool = False;

    def meal() -> str {
        return "standard feed";
    }
}

node TourParty {
    has label: str = "";
}

walker Zookeeper {
    has rounds: int = 0;

    can start with TourParty entry {
        visit [-->];
    }

    can feed with Lion | Parrot | Zebra entry {
        meal_name = here.meal();
        here.fed = True;
        self.rounds += 1;
        print(f"Zookeeper feeds {here.name} the {meal_name}.");
        visit [-->];
    }
}

walker SchoolGroup {
    can start with TourParty entry {
        visit [-->];
    }

    can observe with Lion | Parrot | Zebra entry {
        print(f"School group watches {here.name}.");
        visit [-->];
    }
}

with entry {
    lion = Lion(name="Simba");
    parrot = Parrot(name="Kiwi");
    zebra = Zebra(name="Stripes");

    kiosk = InfoKiosk(park_name="Sunrise Safari");
    party = TourParty(label="Morning Tour");

    party ++> kiosk ++> lion ++> parrot ++> zebra;

    keeper = Zookeeper();
    party spawn keeper;
    pupils = SchoolGroup();
    party spawn pupils;

    print(f"Zookeeper completed {keeper.rounds} feeding rounds.");
}
