"""Build-system dependency graph: walk tasks via shared-library edges and
report total build minutes, auditing each task exactly once even when
multiple paths reach it (diamond DAGs)."""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

edge Needs {
    has reason: str = "runtime";
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    def audit_task(task: Task) {
        if task.name not in self.visited {
            self.visited.append(task.name);
            self.total_minutes += task.minutes;
            print(f"[+] {task.name} (+{task.minutes} min, total={self.total_minutes})");
        } else {
            print(f"[skip] {task.name} already audited");
        }
    }

    can audit with Task entry {
        self.audit_task(here);
        visit [-->];
    }
}

# Walkers in jac 0.36.1 have no built-in dedupe; the explicit `visited`
# list on the walker is the audit-once guarantee across diamond paths.

with entry {
    # Diamond DAG:
    #   core <-- utils <-- app <-- reports
    #   core <--   ui   <-- app
    root ++> Task(name="core",     minutes=10)
        ++> Task(name="utils",    minutes=5)
        ++> Task(name="ui",       minutes=7)
        ++> Task(name="app",      minutes=8)
        ++> Task(name="reports",  minutes=3);

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"\nTotal build minutes (each task audited once): {auditor.total_minutes}");
}
```

"""Tests for BuildAuditor: diamond DAG deduplication and total minute aggregation."""

import io;
import from contextlib { redirect_stdout }

test "diamond: each task audited exactly once, total minutes correct" {
    root ++> Task(name="core", minutes=10)
        ++> Task(name="utils", minutes=5)
        ++> Task(name="ui", minutes=7)
        ++> Task(name="app", minutes=8)
        ++> Task(name="reports", minutes=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.total_minutes == 33, f"expected 33 total minutes, got {auditor.total_minutes}";

    expected = ["core", "utils", "ui", "app", "reports"];
    for name in expected {
        assert name in auditor.visited, f"{name} missing from visited list: {auditor.visited}";
        assert auditor.visited.count(name) == 1, f"{name} visited multiple times: {auditor.visited}";
    }

    assert "[+] core (+10 min, total=10)" in out, f"missing core audit line: {out}";
    assert "[+] reports (+3 min, total=33)" in out, f"missing reports audit line: {out}";
    assert "[skip]" not in out, f"diamond should not produce skips, got: {out}";
}

test "linear chain: all tasks audited once in order" {
    root ++> Task(name="a", minutes=1)
        ++> Task(name="b", minutes=2)
        ++> Task(name="c", minutes=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.total_minutes == 6, f"expected 6 total minutes, got {auditor.total_minutes}";
    assert auditor.visited == ["a", "b", "c"], f"unexpected visit order: {auditor.visited}";
    assert "[+] a (+1 min, total=1)" in out, f"missing a line: {out}";
    assert "[+] b (+2 min, total=3)" in out, f"missing b line: {out}";
    assert "[+] c (+3 min, total=6)" in out, f"missing c line: {out}";
    assert "[skip]" not in out, f"linear chain should have no skips: {out}";
}

test "diamond convergence: shared deps hit twice, counted once" {
    root ++> Task(name="lib", minutes=4)
        ++> Task(name="left", minutes=2)
        ++> Task(name="right", minutes=3)
        ++> Task(name="top", minutes=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.total_minutes == 14, f"expected 14 total (4+2+3+5), got {auditor.total_minutes}";
    assert auditor.visited.count("lib") == 1, f"lib audited multiple times: {auditor.visited}";
    assert auditor.visited.count("top") == 1, f"top audited multiple times: {auditor.visited}";

    audit_lines = [l for l in out.split("\n") if l.startswith("[+]")];
    skip_lines = [l for l in out.split("\n") if l.startswith("[skip]")];
    assert len(audit_lines) == 4, f"expected 4 audit lines, got {len(audit_lines)}: {audit_lines}";
    assert len(skip_lines) == 0, f"expected 0 skip lines on first pass, got: {skip_lines}";
}

test "zero minute task: counted as visited but adds nothing" {
    root ++> Task(name="noop", minutes=0)
        ++> Task(name="work", minutes=7);

    buf = io.StringIO();
    with redirect_stdout(buf) {
