    assert "noop" in auditor.visited, f"noop should appear in visited: {auditor.visited}";
    assert "work" in auditor.visited, f"work should appear in visited: {auditor.visited}";
    assert "[+] noop (+0 min, total=0)" in buf.getvalue(), f"missing noop line: {buf.getvalue()}";
}

test "wide fanout: many parallel tasks all audited" {
    root ++> Task(name="t1", minutes=1)
        ++> Task(name="t2", minutes=2)
        ++> Task(name="t3", minutes=3)
        ++> Task(name="t4", minutes=4)
