```jac
"""Kitchen line health-inspection walker.

Models a grill, fryer, and cold prep station as nodes with temperature
readings. A single ``Inspector`` walker visits every station and runs
two checks: a temperature violation flag (anything above 40 C) and a
visit log entry. Both checks fire at every station via union triggers.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;

    # Shared method so the union ability below can call it on any
    # station subtype without narrowing.
    def reading_label() -> str {
        status = "VIOLATION" if self.celsius > 40.0 else "OK";
        return f"{self.name}: {self.celsius} C [{status}]";
    }
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Inspector {
    has violation_count: int = 0;
    has visit_count: int = 0;

    can start with Root entry {
        print("Beginning kitchen line inspection");
        visit [-->];
    }

    # First check: flag any station above 40 C. Fires on every station.
    can flag_violation with Grill | Fryer | ColdPrep entry {
        if here.celsius > 40.0 {
            self.violation_count += 1;
            print(f"  FLAG  {here.reading_label()}");
        } else {
            print(f"  pass  {here.reading_label()}");
        }
    }

    # Second check: log every station visit. Also fires on every station.
    can log_visit with Grill | Fryer | ColdPrep entry {
        self.visit_count += 1;
        print(f"  LOG   visit #{self.visit_count} -> {here.name}");
        visit [-->];
    }
}

with entry {
    root ++> Grill(name="Grill", celsius=185.0)
        ++> Fryer(name="Fryer", celsius=165.0)
        ++> ColdPrep(name="Cold Prep", celsius=4.0)
        ++> Grill(name="Pastry Oven", celsius=38.0);

    root spawn Inspector();

    print(f"Inspection complete: {Inspector.visit_count} visits, "
          f"{Inspector.violation_count} violations flagged.");
}
