"""Tests for the Kitchen line health-inspection walker."""

import io;
import from contextlib { redirect_stdout }

# ---- Test 1: Both checks fire on every station ------------------------------
test "both checks fire on every station" {
    root ++> Grill(name="Grill", celsius=185.0)
        ++> Fryer(name="Fryer", celsius=165.0)
        ++> ColdPrep(name="Cold Prep", celsius=4.0)
        ++> Grill(name="Pastry Oven", celsius=38.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Both check types must appear in the captured output.
    assert "FLAG" in out, f"missing FLAG marker: {out}";
    assert "LOG" in out, f"missing LOG marker: {out}";

    # Every station must be visited and logged once.
    assert res.visit_count == 4, f"expected 4 visits, got {res.visit_count}";
    # Every station must be temperature-checked.
    assert "Beginning kitchen line inspection" in out, f"missing start: {out}";
}

# ---- Test 2: Violation threshold is strictly above 40 C ---------------------
test "violation threshold is strictly above 40 C" {
    # 40.0 is NOT a violation; 40.01 IS a violation.
    root ++> Grill(name="BoundaryGrill", celsius=40.0)
        ++> Fryer(name="HotFryer", celsius=40.01)
        ++> ColdPrep(name="Fridge", celsius=3.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Exactly one violation (the 40.01 fryer); 40.0 is borderline, not a violation.
    assert res.violation_count == 1, f"expected 1 violation, got {res.violation_count}";
    assert res.visit_count == 3, f"expected 3 visits, got {res.visit_count}";

    # The boundary station must be marked OK, the 40.01 one must be flagged.
    assert "BoundaryGrill: 40.0 C [OK]" in out, f"missing boundary OK line: {out}";
    assert "HotFryer: 40.01 C [VIOLATION]" in out, f"missing hot fryer FLAG: {out}";
    assert "FLAG" in out, f"missing FLAG marker: {out}";
    assert "Fridge: 3.0 C [OK]" in out, f"missing fridge OK line: {out}";
}

# ---- Test 3: All stations are logged regardless of temperature --------------
test "every station is logged even when safe" {
    # All three are well below 40 C -> no violations, but every visit is logged.
    root ++> Grill(name="Grill", celsius=20.0)
        ++> Fryer(name="Fryer", celsius=30.0)
        ++> ColdPrep(name="Cold Prep", celsius=4.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # No violations at all.
    assert res.violation_count == 0, f"expected 0 violations, got {res.violation_count}";
    # But every station was still visited and logged.
    assert res.visit_count == 3, f"expected 3 visits, got {res.visit_count}";

    # Each station's name must appear in a LOG line.
    assert "LOG   visit #1 -> Grill" in out, f"missing Grill log: {out}";
    assert "LOG   visit #2 -> Fryer" in out, f"missing Fryer log: {out}";
    assert "LOG   visit #3 -> Cold Prep" in out, f"missing Cold Prep log: {out}";

    # No FLAG lines should appear when all stations are safe.
    assert "FLAG" not in out, f"unexpected FLAG line in safe run: {out}";
}

# ---- Test 4: All violations are flagged and visit log runs independently ----
test "flagging and logging are independent checks" {
    # All three stations above 40 C: every one is flagged AND logged.
    root ++> Grill(name="Grill", celsius=185.0)
        ++> Fryer(name="Fryer", celsius=165.0)
        ++> ColdPrep(name="HotColdPrep", celsius=45.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Three stations, three violations, three visits.
    assert res.violation_count == 3, f"expected 3 violations, got {res.violation_count}";
    assert res.visit_count == 3, f"expected 3 visits, got {res.visit_count}";

    # For every station there must be BOTH a FLAG line and a LOG line.
    for name in ["Grill", "Fryer", "HotColdPrep"] {
        flag_line = [l for l in out.splitlines() if "FLAG" in l and name in l];
        log_line = [l for l in out.splitlines() if "LOG" in l and name in l];
        assert len(flag_line) == 1, f"expected 1 FLAG line for {name}, got {flag_line} in: {out}";
        assert len(log_line) == 1, f"expected 1 LOG line for {name}, got {log_line} in: {out}";
    }
}

