"""Warehouse inventory audit: assign stable unique ids to items, persist
them to storage during the walk, and dump the graph structure hanging
off the root for a visual sanity check."""

# Nodes -----------------------------------------------------------------
node Item {
    has title: str = "";
    has sku: str = "";
    has uid: str = "";
    has persisted: bool = False;
}

# Edges -----------------------------------------------------------------
edge Shelves { has aisle: str = ""; }
edge Stocks { has shelf_id: str = ""; }

# Walker ----------------------------------------------------------------
walker Auditor {
    can start with Root entry {
        print(f"Audit pass starting from root");
        visit [-->];
    }

    can enter_warehouse with Item entry {
        # Generate a stable unique id by combining title + sku.
        # External systems can reference items by this uid.
        here.uid = f"uid:{here.title}:{here.sku}";
        print(f"  item '{here.title}' assigned {here.uid}");

        # Persist this item to "storage" during the walk. We mark it
        # persisted in-place; in a real system this would flush to disk.
        here.persisted = True;
        print(f"  item '{here.title}' persisted to storage");

        visit [-->];
    }
}

walker Dumper {
    can start with Root entry {
        print("Graph dump (children of root):");
        for n in [-->] {
            print(f"  - Item(title={n.title}, sku={n.sku}, "
                  f"uid={n.uid}, persisted={n.persisted})");
        }
        visit [-->];
    }

    can visit_nodes with Item entry {
        # Reachable via typed edges off root; no-op but keeps the walker
        # honest as a real traverser that descends into the structure.
        visit [-->];
    }
}

# Demo ------------------------------------------------------------------
with entry {
    # Build a small warehouse graph: root --Shelves--> Item nodes.
    apples = Item(title="Apples", sku="FRT-001");
    milk = Item(title="Milk", sku="DRY-014");
    bread = Item(title="Bread", sku="BKY-007");

    root +>:Shelves(aisle="A"):+> apples;
    root +>:Shelves(aisle="A"):+> milk;
    root +>:Shelves(aisle="B"):+> bread;

    # Walk 1: audit (assign uids + persist).
    root spawn Auditor();

    # Walk 2: dump the graph structure for a visual sanity check.
    root spawn Dumper();
}
