"""Learning-path routing demo.

Models the digital-synth knowledge-base routing problem: nine orphan
documents must be attached to role-based learning paths so that a
reader walking the graph from the root reaches every document. The
walker performs the same reachability traversal that the issue
complains about being hand-rolled, and reports any document that is
still orphaned.
"""

node Document {
    has title: str = "";
    has difficulty: int = 0;
    has routed: bool = False;
}

node LearningPath {
    has role: str = "";
    has depth: int = 0;
}

edge Contains {
    has order: int = 0;
}

walker RouteAuditor {
    has visited_docs: list = [];
    has visited_paths: list = [];
    has orphans: list = [];

    can start with Root entry {
        print("Beginning learning-path routing audit");
        visit [-->];
    }

    can audit_path with LearningPath entry {
        self.visited_paths.append(here.role);
        print(f"Path: {here.role} (depth {here.depth})");
        visit [->:Contains:->];
    }

    can audit_doc with Document entry {
        title = here.title if here.title != "" else "untitled";
        if not here.routed {
            self.orphans.append(title);
        }
        self.visited_docs.append(title);
        visit [->:Contains:->];
    }

    can collect_doc with Document entry {
        title = here.title if here.title != "" else "untitled";
        here.routed = True;
        self.visited_docs.append(title);
    }
}

walker OrphanScanner {
    has orphans: list = [];

    can start with Root entry {
        print("Scanning for orphaned documents");
        visit [-->];
    }

    can check with Document entry {
        if not here.routed {
            self.orphans.append(here.title);
            print(f"  ORPHAN: {here.title}");
        }
        visit [-->];
    }

    can skip_path with LearningPath entry {
        visit [-->];
    }
}

with entry {
    beginner = LearningPath(role="Beginner", depth=1);
    sound = LearningPath(role="Sound Design", depth=2);
    dsp = LearningPath(role="DSP/Developer", depth=3);
    advanced = LearningPath(role="Advanced Synthesis", depth=4);

