    noise = Document(title="noise-types-and-modulation", difficulty=5, routed=True);
    bit = Document(title="bit-reduction-and-lofi-effects", difficulty=5, routed=True);
    voc = Document(title="vocoding-and-formant-synthesis", difficulty=7, routed=True);
    stereo = Document(title="stereo-and-spatial-processing", difficulty=5, routed=True);
    arp = Document(title="arpeggiator-and-sequencer-design", difficulty=6, routed=True);
    filters = Document(title="filters-and-tone-shaping", difficulty=4, routed=True);

    advanced +>:Contains(order=1):+> fm;
    advanced +>:Contains(order=2):+> wt;
    advanced +>:Contains(order=3):+> gran;

    sound +>:Contains(order=1):+> ring;
    sound +>:Contains(order=2):+> noise;
