"""Dependency license audit: walk the transitive dependency graph and flag licenses outside the allowlist."""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has available: bool = True;
}

edge DependsOn {
    has version_range: str = "";
}

walker LicenseAuditor {
    has allowlist: list[str] = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"];
    has seen: list[str] = [];
    has violations: list[str] = [];

    def is_allowed(lic: str) -> bool {
        for entry in self.allowlist {
            if entry == lic {
                return True;
            }
        }
        return False;
    }

    def already_seen(n: Package) -> bool {
        for s in self.seen {
            if s == n.name {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

