        res = root spawn LicenseAuditor();
    }
    out = buf.getvalue();
    assert len(res.violations) == 0, f"expected 0 violations, got {res.violations}";
    assert len(res.seen) == 1, f"expected 1 package scanned, got {res.seen}";
    assert "[OK] Newtonsoft.Json@13.0.1 -> MIT" in out, f"missing OK line: {out}";
