"""Quiz grader walker with strictly typed integer reports.

Demonstrates a walker whose `report` is constrained to `int` so that
scores cannot be reported as strings. Quiz nodes carry a student name
and an integer score; the grader walks a chain of quizzes, reports
each score, and computes the class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has reports: list[int] = [];
    can start with Root entry {
        visit [-->];
    }
    can grade with Quiz entry {
        self.reports.append(here.score);
        report here.score;
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student="Ada", score=88)
        ++> Quiz(student="Bao", score=72)
        ++> Quiz(student="Cleo", score=95)
        ++> Quiz(student="Dani", score=61);

    grader = Grader();
    root spawn grader;

    print("Collected scores:", grader.reports);
    total = 0;
    for s in grader.reports {
        total = total + s;
    }
    avg = total / len(grader.reports);
    print(f"Class average: {avg}");
}
