"""Environment variable resolution with cycle detection.

Models the JENKINS-33239 scenario where a variable like
LD_LIBRARY_PATH=$ORACLE_HOME/lib:$LD_LIBRARY_PATH gets expanded
recursively until it runs out of memory. Here we express the
definition graph as typed edges between Variable nodes and let a
walker traverse it. Without a cycle guard the walker would loop
forever (the original bug); with the guard it terminates and
reports the offending cycle.
"""

node Variable {
    has name: str = "";
    has value: str = "";
}

# A definition edge says: this variable's R-value references that
# variable (e.g. LD_LIBRARY_PATH -> LD_LIBRARY_PATH is the self-cycle
# that triggers the bug).
edge Refs {
    has var_name: str = "";
}

walker Resolver {
    has max_depth: int = 32;
    has seen: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand with Variable entry {
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[HALT] depth>{self.max_depth} at {here.name} -- runaway recursion (the JENKINS-33239 bug)");
            disengage;
        }
        if here.name in self.seen {
            cycle = self.seen[-1] + " -> " + here.name;
            print(f"[CYCLE] {cycle}");
            disengage;
        }
        self.seen.append(here.name);
        print(f"resolve {here.name} = {here.value} (path={' -> '.join(self.seen)})");
        # Follow every typed reference this variable makes in its R-value.
        visit [->:Refs:->];
    }
}

with entry {
    # Build the graph: LD_LIBRARY_PATH references both ORACLE_HOME/lib
    # and itself -- the self-reference is exactly the JENKINS-33239 case.
    path = Variable(name="LD_LIBRARY_PATH", value="$ORACLE_HOME/lib:$LD_LIBRARY_PATH");
    oracle = Variable(name="ORACLE_HOME", value="/opt/oracle");
    home = Variable(name="HOME", value="/root");

    # Typed edges carry the referenced variable's name as payload.
    path +>:Refs(var_name="ORACLE_HOME"):+> oracle;
    path +>:Refs(var_name="LD_LIBRARY_PATH"):+> path;
    oracle +>:Refs(var_name="HOME"):+> home;

    root ++> path;

    print("--- scenario 1: graph with self-cycle (the reported bug) ---");
    Resolver() spawn root;

    print("");
    print("--- scenario 2: same walker, no self-cycle, terminates cleanly ---");
    safe = Variable(name="PATH", value="path1:$HOME");
    safe +>:Refs(var_name="HOME"):+> home;
    root ++> safe;
    Resolver() spawn safe;
}
```

"""Regression tests for the JENKINS-33239 variable-resolution walker.

Exercises the three behaviors the program promises:
  1. Self-referential definitions are detected as a cycle and the walker
     disengages instead of looping forever.
  2. Acyclic reference chains terminate cleanly and visit every variable.
  3. A long acyclic chain trips the max_depth guard and disengages with
     the runaway-recursion message (the runaway recursion bug).
"""

import io;
import from contextlib { redirect_stdout }

test "self-cycle is detected and walker disengages instead of looping forever" {
    rt = Root();

    path_v = Variable(name="LD_LIBRARY_PATH", value="$LD_LIBRARY_PATH");
    path_v +>:Refs(var_name="LD_LIBRARY_PATH"):+> path_v;
    rt ++> path_v;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Resolver();
    }
    out = buf.getvalue();

    # Cycle marker must be printed and the offending edge named.
    assert "[CYCLE]" in out, f"expected cycle marker, got: {out}";
    assert "LD_LIBRARY_PATH" in out, f"expected LD_LIBRARY_PATH in output, got: {out}";
    # The runaway-recursion message must NOT appear -- cycle guard fires first.
    assert "[HALT]" not in out, f"cycle guard should stop before max_depth, got: {out}";
}

test "acyclic reference chain resolves all variables and terminates cleanly" {
    rt = Root();

    safe = Variable(name="PATH", value="path1:$HOME");
    home = Variable(name="HOME", value="/root");
    safe +>:Refs(var_name="HOME"):+> home;
    rt ++> safe;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = safe spawn Resolver();
    }
    out = buf.getvalue();

    # Both variables should be resolved; no cycle, no depth halt.
    assert "resolve PATH" in out, f"expected PATH resolution, got: {out}";
    assert "resolve HOME" in out, f"expected HOME resolution, got: {out}";
    assert "[CYCLE]" not in out, f"no cycle expected in acyclic graph, got: {out}";
    assert "[HALT]" not in out, f"no depth halt expected for short chain, got: {out}";

    # The walker tracks both names in its `seen` list in traversal order.
    assert res.seen == ["PATH", "HOME"], f"seen traversal wrong: {res.seen}";
}

test "long acyclic chain trips max_depth guard and reports runaway recursion" {
    rt = Root();

    # Build a chain n0 -> n1 -> n2 -> ... -> n40, each with a typed
    # Refs edge carrying the next variable's name. No cycles, but the
    # chain is longer than max_depth=32, so the guard must fire.
    first = Variable(name="n0", value="$n1");
    rt ++> first;
    cur = first;
    i = 1;
    while i <= 40 {
        nxt = Variable(name=f"n{i}", value=f"$n{i + 1}");
        cur +>:Refs(var_name=f"n{i}"):+> nxt;
        cur = nxt;
        i += 1;
    }

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = first spawn Resolver();
    }
    out = buf.getvalue();

    # The runaway-recursion marker must fire for a chain past max_depth.
    assert "[HALT]" in out, f"expected depth halt, got: {out}";
    assert "runaway recursion" in out, f"expected runaway message, got: {out}";

    # No cycle was present, so cycle marker must not appear.
    assert "[CYCLE]" not in out, f"no cycle expected in a long chain, got: {out}";

    # Depth at disengage must exceed the configured max_depth.
    assert res.depth > res.max_depth, (
        f"depth {res.depth} should exceed max_depth {res.max_depth}"
    );
}

test "fresh walker instance does not inherit seen list from prior traversal" {
    rt = Root();

    a_v = Variable(name="A", value="$B");
    b_v = Variable(name="B", value="/b");
    a_v +>:Refs(var_name="B"):+> b_v;
    rt ++> a_v;

    buf1 = io.StringIO();
    with redirect_stdout(buf1) {
        res1 = rt spawn Resolver();
    }
    out1 = buf1.getvalue();
    assert "resolve A" in out1 and "resolve B" in out1, f"first walk failed: {out1}";
    assert res1.seen == ["A", "B"], f"first seen wrong: {res1.seen}";

    # A brand-new walker on the same graph must start with an empty `seen`
    # list -- otherwise the bug would mask itself as a cycle on every run.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        res2 = rt spawn Resolver();
    }
    out2 = buf2.getvalue();
    assert res2.seen == ["A", "B"], f"second walk seen wrong: {res2.seen}";
    assert "[CYCLE]" not in out2, f"fresh walker should not falsely detect cycle, got: {out2}";
}

