"""Bitrix Deal Intelligence: model deals, activities, and predictions as a typed graph.

The original (rejected) architecture shoved full deal activity history into
Neo4j alongside identity-resolution data, then walked it with hand-rolled
recursion over parent/child id maps. This demo lifts the relationship into
typed edges and lets a walker traverse deal histories natively — including
the cycle guard the original code had to maintain by hand.
"""

node Deal {
    has title: str = "";
    has stage: str = "NEW";
    has amount: float = 0.0;
    has won: bool = False;

    def label() -> str {
        return f"{self.title} [{self.stage}]";
    }
}

node Activity {
    has kind: str = "";
    has note: str = "";
    has ts: str = "";
}

node Prediction {
    has model_version: str = "";
    has win_probability: float = 0.0;
}

node Salesperson {
    has name: str = "";
}

edge Owns { }
edge HistoryOf { }
edge ScoredBy { }
edge ParticipatedIn { }

walker DealIntel {
    has visited: list[str] = [];
    has guard: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can scan_deals with Deal entry {
        key = str(id(here));
        if key in self.guard {
            print(f"[cycle] already walked {here.label()} — skipping");
            disengage;
        }
        self.guard.add(key);
        self.visited.append(here.label());
        print(f"deal -> {here.label()} amt={here.amount} won={here.won}");
        visit [->:HistoryOf:->];
    }

    can scan_activities with Activity entry {
        self.visited.append(f"{here.kind}@{here.ts}: {here.note}");
        print(f"  activity -> {here.kind} ({here.ts}) {here.note}");
        visit [->:HistoryOf:->];
    }

    can scan_predictions with Prediction entry {
        print(f"  prediction -> v{here.model_version} p={here.win_probability}");
    }
}

walker CascadeInvalidator {
    has removed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can purge_deal with Deal entry {
        self.removed.append(here.label());
        print(f"removing deal {here.label()} and its history + predictions");
        del here;
    }
}

walker DependencyOrder {
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can order_deal with Deal entry {
        self.order.append(here.title);
        print(f"step {len(self.order)}: train/eval against {here.title}");
        visit [-->];
    }
}

with entry {
    alice = Salesperson(name="Alice");
    bob = Salesperson(name="Bob");

    d1 = Deal(title="Acme renewal", stage="PROPOSAL", amount=12000.0);
    d2 = Deal(title="Globex upsell", stage="NEGOTIATION", amount=38000.0);
    d3 = Deal(title="Initech new", stage="NEW", amount=5500.0);

    a1 = Activity(kind="call", note="budget confirmed", ts="2024-01-15");
    a2 = Activity(kind="meeting", note="demo with CTO", ts="2024-01-18");
    a3 = Activity(kind="task", note="send proposal", ts="2024-01-20");

    p1 = Prediction(model_version="v1.2", win_probability=0.78);
    p2 = Prediction(model_version="v1.2", win_probability=0.41);

    root ++> alice ++> bob;
    alice +>:Owns:+> d1;
    alice +>:Owns:+> d2;
    bob +>:Owns:+> d3;

    d1 +>:HistoryOf:+> a1;
    d1 +>:HistoryOf:+> a2;
    d1 +>:HistoryOf:+> a3;
    d2 +>:HistoryOf:+> a1;

    d1 +>:ScoredBy:+> p1;
    d2 +>:ScoredBy:+> p2;

    print("=== DealIntel traversal (with cycle guard) ===");
    root spawn DealIntel();

    print("\n=== Dependency ordering across deals ===");
    root spawn DependencyOrder();

    print("\n=== Cascade invalidation: drop d1 and everything attached ===");
