"""Memory knowledge graph: typed-edge layer over memories with BFS walkers.

Models the memento-mcp v1 wedge in idiomatic Jac — six closed edge types
over `Memory` nodes, plus walker analogues of `subgraph` (BFS expansion to
configurable depth), `shortestPath` (BFS shortest path with hop cap), and
`CascadeInvalidator` (reachability-based invalidation). Walkers carry an
explicit visited set because Jac 0.36 has no built-in once-per-node
visitation, which is the cycle policy this issue requires.
"""

node Memory {
    has memory_id: str = "";
    has title: str = "";
    has available: bool = True;
}

edge RelatesTo { has weight: float = 1.0; }
edge Supersedes { has weight: float = 1.0; }
edge CausedBy { has weight: float = 1.0; }
edge MitigatedBy { has weight: float = 1.0; }
edge References { has weight: float = 1.0; }
edge Implements { has weight: float = 1.0; }

walker SubgraphExplorer {
    has depth: int = 2;
    has report_nodes: list = [];
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can expand with Memory entry {
        already = False;
        for mid in self.visited {
            if mid == here.memory_id {
                already = True;
            }
        }
        if not already {
            self.visited[here.memory_id] = True;
            self.report_nodes.append(here);
        }
        if self.depth > 0 {
            self.depth -= 1;
            visit [->:RelatesTo:->];
            visit [->:Supersedes:->];
            visit [->:CausedBy:->];
            visit [->:MitigatedBy:->];
            visit [->:References:->];
            visit [->:Implements:->];
        }
    }
}

walker PathFinder {
    has target_id: str = "";
    has max_hops: int = 4;
    has found_path: list = [];
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can search with Memory entry {
        already = False;
        for mid in self.visited {
            if mid == here.memory_id {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited[here.memory_id] = True;
        if here.memory_id == self.target_id {
            self.found_path = [here];
            disengage;
        }
        if self.max_hops <= 0 {
            disengage;
        }
        self.max_hops -= 1;
        visit [->:RelatesTo:->];
        visit [->:Supersedes:->];
        visit [->:CausedBy:->];
        visit [->:MitigatedBy:->];
        visit [->:References:->];
        visit [->:Implements:->];
    }
}

walker CascadeInvalidator {
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Memory entry {
        already = False;
        for mid in self.visited {
            if mid == here.memory_id {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited[here.memory_id] = True;
        here.available = False;
        print(f"Invalidated: {here.title}");
        visit [->:RelatesTo:->];
        visit [->:Supersedes:->];
        visit [->:CausedBy:->];
        visit [->:MitigatedBy:->];
        visit [->:References:->];
        visit [->:Implements:->];
    }
}

with entry {
    pitfall = Memory(memory_id="m1", title="Pitfall: off-by-one in index");
    pattern = Memory(memory_id="m2", title="Pattern: bounds-check helper");
    arch = Memory(memory_id="m3", title="Architecture: layered memory store");
    decision = Memory(memory_id="m4", title="Decision: use BFS for graph queries");

    pitfall +>:CausedBy:+> pattern;
    pattern +>:MitigatedBy:+> pitfall;
    arch +>:References:+> decision;
    decision +>:Implements:+> arch;
    pitfall +>:RelatesTo:+> arch;

    root ++> pitfall;
    root ++> pattern;
    root ++> arch;
    root ++> decision;

    print("=== Subgraph from pitfall (depth=2) ===");
    explorer = SubgraphExplorer(depth=2);
    pitfall spawn explorer;
    titles = [];
    for m in explorer.report_nodes {
        titles.append(m.title);
    }
    print(f"Nodes reached: {titles}");

    print("\n=== Shortest path pitfall -> decision (max_hops=4) ===");
    finder = PathFinder(target_id="m4", max_hops=4);
    pitfall spawn finder;
    if len(finder.found_path) > 0 {
        path_titles = [];
        for m in finder.found_path {
            path_titles.append(m.title);
        }
        print(f"Path: {path_titles}");
    } else {
        print("No path found within hop limit.");
    }

    print("\n=== Cascade invalidate from arch ===");
    arch spawn CascadeInvalidator();
}
