node AegisModule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has invalidated: bool = False;
}

node IndexSymbol {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has line: int = 0;
}

edge Imports {
    has required: bool = True;
}

edge Defines {
    has line: int = 0;
