"""Tests for archetype-level open WRITE access policy.

Verifies that `__jac_access__` defined on `DocsCache` returns
AccessLevel.WRITE, that `CachedEntry` (a subtype) inherits it, and
that the paired `CacheLink` edge type also reports AccessLevel.WRITE.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. Archetype hook: DocsCache.__jac_access__ == WRITE
# ---------------------------------------------------------------------------
test "docs cache archetype hook returns WRITE" {
    dc = DocsCache(topic="x", payload="y", rebuilt_at=0);
    level = dc.__jac_access__();
    assert level == AccessLevel.WRITE, f"expected WRITE, got {level}";
}

# ---------------------------------------------------------------------------
# 2. Subtype inherits the open policy from its parent archetype
# ---------------------------------------------------------------------------
test "subtype inherits open WRITE policy" {
    ce = CachedEntry(topic="sub", payload="z", rebuilt_at=2);
    level = ce.__jac_access__();
    assert level == AccessLevel.WRITE, f"subtype must inherit WRITE, got {level}";
}

# ---------------------------------------------------------------------------
# 3. Paired edge type also returns AccessLevel.WRITE
# ---------------------------------------------------------------------------
test "cache link edge type returns WRITE" {
    # Build a tiny graph so the edge exists as an object with a hook.
    root ++> DocsCache(topic="a", payload="aa", rebuilt_at=1);
    a = [root -->][0];
    a +>:CacheLink:+> DocsCache(topic="b", payload="bb", rebuilt_at=2);

    edges = [a ->:CacheLink:->];
    assert len(edges) >= 1, "expected a CacheLink edge to exist";
    e = edges[0];
    level = e.__jac_access__();
    assert level == AccessLevel.WRITE, f"CacheLink hook must return WRITE, got {level}";
}

# ---------------------------------------------------------------------------
# 4. Open WRITE includes READ: list_cache walker still traverses the graph
#    built by rebuild_cache, and rebuild_cache can add children to Root.
# ---------------------------------------------------------------------------
test "rebuild_cache and list_cache still work under open policy" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn rebuild_cache(entries={
            "alpha": "one",
            "beta":  "two",
            "gamma": "three",
        });
    }
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    assert res.reports[0]["rebuilt"] == 3, f"expected rebuilt=3, got {res.reports[0]}";

    # Exactly three DocsCache children hang directly off Root.
    direct = [root -->];
    assert len(direct) == 3, f"expected 3 direct children, got {len(direct)}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        listing = root spawn list_cache();
    }
    out = buf2.getvalue();
    # One row per cached entry, in some order.
    assert "alpha" in out, f"missing alpha in listing: {out}";
    assert "beta"  in out, f"missing beta in listing: {out}";
    assert "gamma" in out, f"missing gamma in listing: {out}";
    assert len(listing.reports) == 1, f"expected 1 report, got {len(listing.reports)}";
    assert len(listing.reports[0]) == 3, f"expected 3 listed entries, got {listing.reports[0]}";
}

# ---------------------------------------------------------------------------
# 5. Open policy applies to every instance (invariant), not a per-instance
#    grant: many instances all independently return WRITE.
# ---------------------------------------------------------------------------
test "openness is invariant across many instances" {
    instances = [
        DocsCache(topic="t1", payload="p1", rebuilt_at=0),
        DocsCache(topic="t2", payload="p2", rebuilt_at=1),
        DocsCache(topic="t3", payload="p3", rebuilt_at=2),
        CachedEntry(topic="t4", payload="p4", rebuilt_at=3),
        CachedEntry(topic="t5", payload="p5", rebuilt_at=4),
    ];
    for (i, n) in enumerate(instances) {
        lvl = n.__jac_access__();
        assert lvl == AccessLevel.WRITE, f"instance {i} not WRITE: {lvl}";
    }
}

