"""Factory zone patrol: one walker inspects temperature and smoke sensors."""

node Sensor {
    has label: str = "";

    def is_alert() -> bool {
        return False;
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }
}

node Zone {
    has name: str = "";
}

walker Patrol {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Zone entry {
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        line = f"[ALERT] {here.label}" if here.is_alert() else f"nominal: {here.label}";
        print(line);
        if here.is_alert() {
            self.alerts.append(here.label);
        }
    }
}

with entry {
    zone_a = Zone(name="Zone A");
    zone_b = Zone(name="Zone B");
    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="Temp-1", celsius=68.0);
    zone_a ++> TempSensor(label="Temp-2", celsius=91.5);
    zone_a ++> SmokeSensor(label="Smoke-1", ppm=12.0);
    zone_b ++> SmokeSensor(label="Smoke-2", ppm=60.0);
    zone_b ++> TempSensor(label="Temp-3", celsius=74.5);

    patroller = Patrol();
    root spawn patroller;

    print(f"Alerts triggered: {patroller.alerts}");
}
