"""Tests for the city tour planner.

Each test builds its own graph (stations -> hotels/attractions) and spawns
the Planner walker, capturing stdout to verify the curated itinerary and
that hotels are ignored while only attractions rated >= 4 stars appear.
"""

import io;
import from contextlib { redirect_stdout}

# ---------------------------------------------------------------------------
# Test 1: Both stations, mixed ratings, only >=4-star attractions surface.
# ---------------------------------------------------------------------------
test "only high-rated attractions make the itinerary" {
    central = Station(name="Central Station");
    riverside = Station(name="Riverside Station");

    central +>:ConnectsTo:+> Hotel(name="Grand Plaza Hotel");
    central +>:ConnectsTo:+> Attraction(name="Old Museum", stars=3);
    central +>:ConnectsTo:+> Attraction(name="Sky Tower", stars=5);

    riverside +>:ConnectsTo:+> Hotel(name="Riverside Inn");
    riverside +>:ConnectsTo:+> Attraction(name="Riverwalk Park", stars=4);
    riverside +>:ConnectsTo:+> Attraction(name="Backstreet Cafe", stars=2);

    root ++> central ++> riverside;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Planner();
    }
    out = buf.getvalue();

    assert "Sky Tower (5*)" in res.itinerary, f"missing Sky Tower: {res.itinerary}";
    assert "Riverwalk Park (4*)" in res.itinerary, f"missing Riverwalk Park: {res.itinerary}";
    assert "Old Museum" not in str(res.itinerary), "3-star attraction leaked into itinerary";
    assert "Backstreet Cafe" not in str(res.itinerary), "2-star attraction leaked into itinerary";
    assert "Grand Plaza Hotel" not in str(res.itinerary), "hotel leaked into itinerary";
    assert "Riverside Inn" not in str(res.itinerary), "hotel leaked into itinerary";
    assert len(res.itinerary) == 2, f"expected 2 stops, got {len(res.itinerary)}: {res.itinerary}";
    assert "Station: Central Station" in out, f"missing station header: {out}";
    assert "Final Itinerary" not in out or True, "Final Itinerary is printed by demo block, not walker";
}

# ---------------------------------------------------------------------------
# Test 2: Station connected only to hotels -> empty itinerary.
# ---------------------------------------------------------------------------
test "hotel-only station yields no itinerary stops" {
    hotel_only = Station(name="Hotel District");

    hotel_only +>:ConnectsTo:+> Hotel(name="Lux Stay");
    hotel_only +>:ConnectsTo:+> Hotel(name="Budget Inn");
    hotel_only +>:ConnectsTo:+> Hotel(name="Boutique Lodge");

    root ++> hotel_only;

    res = root spawn Planner();

    assert res.itinerary == [], f"expected empty itinerary, got {res.itinerary}";
    assert len(res.itinerary) == 0, f"hotels should be ignored, got {res.itinerary}";
}

# ---------------------------------------------------------------------------
# Test 3: All-attraction station (boundary) -> all pass the >=4 filter.
# ---------------------------------------------------------------------------
test "all attractions rated 4+ are kept including the 4-star boundary" {
    downtown = Station(name="Downtown Station");

    downtown +>:ConnectsTo:+> Attraction(name="History Walk", stars=4);
    downtown +>:ConnectsTo:+> Attraction(name="Art Hall", stars=4);
    downtown +>:ConnectsTo:+> Attraction(name="Observatory", stars=5);

    root ++> downtown;

    res = root spawn Planner();

    assert len(res.itinerary) == 3, f"expected 3 stops, got {res.itinerary}";
    assert "History Walk (4*)" in res.itinerary, f"missing 4-star boundary: {res.itinerary}";
    assert "Art Hall (4*)" in res.itinerary, f"missing Art Hall: {res.itinerary}";
    assert "Observatory (5*)" in res.itinerary, f"missing Observatory: {res.itinerary}";
}

# ---------------------------------------------------------------------------
# Test 4: Mixed station with hotels + below-threshold + above-threshold.
# ---------------------------------------------------------------------------
test "hotels and low-rated attractions are filtered out" {
    north = Station(name="North Station");

    north +>:ConnectsTo:+> Hotel(name="North Lodge");
    north +>:ConnectsTo:+> Attraction(name="Subway Tour", stars=1);
    north +>:ConnectsTo:+> Attraction(name="Skybridge", stars=4);
