"""Vacuous-guard walk: a placement detector that returns early on `None`
silently degrades to a no-op, so its own tripwire is conditioned on the
precondition it is meant to assert.

Models the onnx-genai/onnx-genai #1817 defect class natively in Jac: a
`PlacementCheck` walker is supposed to prove that every spawned worker
actually saw a topology (a `Host` node) and was routed through it. A guard
that returns early when the host is missing also skips the very flag that
catches the skip, so the run stays green while the guarantee is gone.

The positive arm (instance #1173's pattern) is added: a synthetic defect
node forces the walker through a leg that MUST increment the saw flag,
proving the detector can detect. Without it, "saw_placement_check = 0"
is consistent both with "the guarantee held" and "the check is broken".
"""

node Host {
    has name: str = "";
    has cores: int = 0;
}

node Worker {
    has name: str = "";
    has placed: bool = False;
}

node DefectProbe {
    has label: str = "";
}

edge SpawnedOn {}

walker PlacementCheck {
    has saw_placement_check: bool = False;
    has host_present: bool = True;

    can start with Root entry {
        visit [->:SpawnedOn:->];
    }

    # The vacuous-guard leg: present when the topology resolves.
    can route_with_host with Host entry {
        if self.host_present {
            self.saw_placement_check = True;
            print(f"[host={here.name}] topology OK across {here.cores} cores");
        } else {
            # Real defect path: the precondition failed. We still want to
            # see this leg, so we DO NOT `return` silently — we surface it.
            print(f"[host={here.name}] precondition FAILED: no topology");
        }
        visit [->:SpawnedOn:->];
    }

    can land with Worker entry {
        here.placed = self.saw_placement_check;
        status = "PLACED" if here.placed else "UNPLACED";
        print(f"[worker={here.name}] {status}");
        visit [->:SpawnedOn:->];
    }

    # Positive arm of the detector: an injected defect MUST trip the flag.
    # Without this, a `saw_placement_check = False` result is unfalsifiable.
    can catch_defect with DefectProbe entry {
        print(f"[defect={here.label}] detector fired on injected probe");
        self.saw_placement_check = True;
        disengage;
    }
}

with entry {
    h = Host(name="linux-cpu", cores=8);

    # The realistic run: topology resolves, sweep is supposed to assert.
    # Walker takes the Host leg first, then visits the workers it spawned.
    h +>:SpawnedOn:+> Worker(name="onnx-genai-spmd-n0-0");
    h +>:SpawnedOn:+> Worker(name="onnx-genai-spmd-n0-1");

    # Positive arm: a synthetic defect wired into the same graph, so the
    # detector has a falsifier. If the detector ever silently no-ops, this
    # branch will still fire and flip the flag — the run cannot stay green
    # while the check is broken.
    h +>:SpawnedOn:+> DefectProbe(label="comm-truncation");

    # --- demo run #1: the leg the issue actually worries about ---
    print("=== run 1: topology resolves (host_present=True) ===");
    w1 = PlacementCheck(host_present=True);
    h spawn w1;
    print(f"saw_placement_check = {w1.saw_placement_check}");

    # --- demo run #2: defect injected, detector MUST trip ---
    print("=== run 2: defect probe, positive arm of the detector ===");
    w2 = PlacementCheck(host_present=False);
    # Reach the DefectProbe directly through the same typed edge.
    probe = DefectProbe(label="run-2-tripwire");
    root +>:SpawnedOn:+> probe;
    probe spawn w2;
    print(f"saw_placement_check = {w2.saw_placement_check}");
}
