"""Dungeon crawler: chain of rooms with one vault holding the treasure.

A Hunter walker traverses the dungeon forward, counting rooms seen,
and disengages the moment it reaches the vault so no room past the
treasure is ever visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        if here.is_vault {
            print(f"Treasure found in '{here.name}' after {self.rooms_seen} room(s) searched");
            print(f"Hunter disengages; rooms past the vault are never visited");
            disengage;
        }
        print(f"Checked '{here.name}' — no treasure");
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Foyer")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Chamber")
        ++> Room(name="Never Reached");

    root spawn Hunter();
}
