"""Grover impact analysis: model cryptographic primitives and walk the
threat graph to flag vulnerable components under Grover's quadratic
speedup, then emit an upgrade-recommendation report."""

# ---- Base entity: all crypto components share these fields -------------

node CryptoComponent {
    has name: str = "";
    has kind: str = "";
    has bit_strength: int = 0;
    has grover_effective: int = 0;
    has vulnerable: bool = False;
    has recommendation: str = "";
}

# ---- Concrete component archetypes ------------------------------------

node SymmetricCipher(CryptoComponent) {
    has key_size: int = 0;
}

node HashFunction(CryptoComponent) {
    has digest_size: int = 0;
}

node HmacVariant(CryptoComponent) {
    has key_length: int = 0;
    has underlying_hash: str = "";
}

# A plain visitor — never matched by the union trigger.
node RelatedArtifact {
    has note: str = "";
}

# ---- Typed edges ------------------------------------------------------

edge DependsOn { }
edge MitigatedBy { }

# ---- Walker: a single auditor that traverses the threat graph ---------

walker GroverAuditor {
    has report_lines: list = [];
    has visited: list = [];

    can start with Root entry {
        print("=== Grover Quadratic Speedup Impact Audit ===");
        visit [-->] else { disengage; }
    }

    can audit_component with SymmetricCipher | HashFunction | HmacVariant entry {
        if self.visited.count(here) > 0 {
            visit [->:DependsOn:->] else { disengage; }
        }
        self.visited = self.visited + [here];

        status = "VULNERABLE" if here.vulnerable else "SAFE";
        line = f"[{status}] {here.kind} '{here.name}' "
            f"(classical={here.bit_strength}, "
            f"grover={here.grover_effective}) -> {here.recommendation}";
        self.report_lines = self.report_lines + [line];

        visit [->:DependsOn:->] else { disengage; }
    }

    can note_artifact with RelatedArtifact entry {
        visit [-->] else { disengage; }
    }

    can summarize with Root entry {
        print(f"Audited {len(self.report_lines)} components under Grover:");
        for entry in self.report_lines {
            print(f"  - {entry}");
        }
        vulnerable_count = 0;
        for entry in self.report_lines {
            if entry.startswith("[VULNERABLE]") {
                vulnerable_count = vulnerable_count + 1;
            }
        }
        print(f"Vulnerable components: {vulnerable_count}");
        print("Minimum quantum-safe baseline: AES-256 / SHA-384 / HMAC-256");
    }
}

