test "nurse badges into every ward and increments shift_visits" {
    icu = Ward(ward_name="ICU");
    general = Ward(ward_name="General");
    root ++> icu ++> general;

    nurse = Nurse(badge="N-101");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn nurse;
    }
    out = buf.getvalue();

    # One print per ward (2 wards), each naming the badge and the ward.
    assert "N-101 badged into the ICU ward" in out, f"missing ICU badge line: {out}";
    assert "N-101 badged into the General ward" in out, f"missing General badge line: {out}";
    # Exactly two ward visits during the shift.
    assert nurse.shift_visits == 2, f"expected 2 ward visits, got {nurse.shift_visits}";
}

test "doctor also triggers the union ability on every ward" {
    icu = Ward(ward_name="ICU");
    general = Ward(ward_name="General");
    root ++> icu ++> general;

    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn doctor;
    }
    out = buf.getvalue();

    assert "D-55 badged into the ICU ward" in out, f"missing ICU badge line: {out}";
    assert "D-55 badged into the General ward" in out, f"missing General badge line: {out}";
    assert doctor.shift_visits == 2, f"expected 2 ward visits, got {doctor.shift_visits}";
}

test "family visitor triggers no ward response at all" {
    icu = Ward(ward_name="ICU");
    general = Ward(ward_name="General");
    root ++> icu ++> general;

    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn guest;
    }
    out = buf.getvalue();

    # The ward's union ability must NOT fire for a FamilyVisitor.
    assert out == "", f"family visitor should be silent, got: {out!r}";
    assert "badged into" not in out, f"unexpected badge line for visitor: {out}";
}

test "union trigger fires for both Nurse and Doctor but not Visitor" {
    icu = Ward(ward_name="ICU");
    general = Ward(ward_name="General");
    root ++> icu ++> general;

    nurse = Nurse(badge="N-9");
    doctor = Doctor(badge="D-3");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
        root spawn doctor;
    }
    out = buf.getvalue();

    # Staff entries present
    assert "N-9 badged into the ICU ward" in out;
    assert "N-9 badged into the General ward" in out;
    assert "D-3 badged into the ICU ward" in out;
    assert "D-3 badged into the General ward" in out;

    # Each staff member counted their own wards independently.
    assert nurse.shift_visits == 2, f"nurse visits={nurse.shift_visits}";
    assert doctor.shift_visits == 2, f"doctor visits={doctor.shift_visits}";

    # Now a visitor: still silent, and earlier output is unchanged.
