"""Async-delegation wakeup settlement: model the adoption branch that drops provenance.

The bug: when a background delegate_task fan-out completes and the session is
idle, the delivery is persisted without `_source: "process_wakeup"` (and without
`_wakeup_meta`). The transcript then renders the raw envelope as a plain user
bubble instead of a collapsed wakeup card. The root cause lives in the turn
adoption branch of settlement: the helper that marks the agent-returned user row
historical only wrote `_active_turn_token` and never routed through
`stamp_message_source`.

This program models the essential entities and traversal natively in Jac:
  - Session          (an agent session)
  - Turn             (a settled agent turn row, with optional source stamp)
  - WakeupDelivery   (an async-delegation wakeup envelope attached to a session)

The typed edge TurnAdoptedIn marks the adoption relationship: the same
settlement path that *materializes* an eager checkpoint also calls the
adoption helper. The wakeup walker walks TurnAdoptedIn edges from a session
and reports which turns kept their provenance and which lost it.
"""

node Session {
    has name: str = "";
    has save_mode: str = "deferred";  # "deferred" | "eager"
}

node Turn {
    has title: str = "";
    has role: str = "user";
    has active_turn_token: str = "";
    has source: str = "";            # "process_wakeup" when stamped; "" when dropped
    has wakeup_meta: str = "";       # display metadata that rides along with the stamp
    has fork_child_turn: bool = False;
    has raw_envelope: str = "";      # the multi-kB raw payload, when present
}

node WakeupDelivery {
    has title: str = "";
    has envelope_header: str = "";   # e.g. "[ASYNC DELEGATION BATCH COMPLETE — ...]"
    has collapsed: bool = True;      # what the client should render
}

edge TurnAdoptedIn { }              # the adoption relationship at settlement

walker AdoptionAuditor {
    has reported: int = 0;
    has dropped: int = 0;

    can start with Root entry {
        print(f"=== Auditing adoption branch in settlement (save_mode focus) ===");
        visit [-->];
    }

    can audit_session with Session entry {
        label = "deferred (adoption branch active)" if here.save_mode == "deferred" else "eager (materialize branch active)";
        print(f"Session {here.name} [{label}]");
        visit [->:TurnAdoptedIn:->];
    }

    can audit_turn with Turn entry {
        self.reported += 1;
        if here.source == "" {
            self.dropped += 1;
            print(f"  [DROPPED] turn {here.title!r} role={here.role} "
                  f"token={here.active_turn_token!r} source=<missing> "
                  f"wakeup_meta=<missing> fork_marker={here.fork_child_turn}");
            print(f"           -> raw envelope would render as a plain user bubble "
                  f"({len(here.raw_envelope)} bytes uncollapsed)");
        } else {
            print(f"  [STAMPED] turn {here.title!r} role={here.role} "
                  f"token={here.active_turn_token!r} source={here.source!r} "
                  f"wakeup_meta={here.wakeup_meta!r}");
        }
        visit [-->];
    }

    can audit_wakeup with WakeupDelivery entry {
        print(f"  wakeup delivery {here.title!r} header={here.envelope_header!r} "
              f"collapsed_expected={here.collapsed}");
        visit [-->];
    }
}

walker FixPropagation {
    can start with Root entry {
        print(f"=== After fix: helper routes through stamp_message_source ===");
        visit [-->];
    }

    can sweep_session with Session entry {
        print(f"Session {here.name}: re-stamping adopted turns that lost provenance");
        visit [->:TurnAdoptedIn:->];
    }

    can sweep_turn with Turn entry {
        if here.source == "" and here.role == "user" {
            here.source = "process_wakeup";
            here.wakeup_meta = "async_delegation";
            print(f"  re-stamped {here.title!r} -> source={here.source!r} "
                  f"wakeup_meta={here.wakeup_meta!r}");
        }
        if not here.fork_child_turn and here.title.startswith("fork-") {
            here.fork_child_turn = True;
            print(f"  restored fork marker on {here.title!r}");
        }
        visit [-->];
    }
}

with entry {
    s_deferred = Session(name="idle-origin-session", save_mode="deferred");
    s_eager = Session(name="eager-origin-session", save_mode="eager");

    # Deferred session: turns adopt (no eager checkpoint), so source is dropped.
    t_async_batch = Turn(
        title="async-batch",
        role="user",
        active_turn_token="tok-001",
        source="",
        wakeup_meta="",
        raw_envelope="[ASYNC DELEGATION BATCH COMPLETE — deleg_abc123]\n"
                     "task_a: ok\ntask_b: ok\n... (3.7 KB raw payload) ...",
    );
    t_fork_child = Turn(
        title="fork-child-1",
        role="user",
        active_turn_token="tok-002",
        source="",
        fork_child_turn=False,
        raw_envelope="forked branch payload",
    );
    w_async = WakeupDelivery(
        title="deleg_abc123",
        envelope_header="[ASYNC DELEGATION BATCH COMPLETE — deleg_abc123]",
        collapsed=True,
    );
    s_deferred +>:TurnAdoptedIn:+> t_async_batch;
    s_deferred +>:TurnAdoptedIn:+> t_fork_child;
    s_deferred +>:TurnAdoptedIn:+> w_async;

    # Eager session: materialize branch stamps correctly.
    t_normal_wakeup = Turn(
        title="bg-process-wakeup",
        role="user",
        active_turn_token="tok-003",
        source="process_wakeup",
        wakeup_meta="background_process",
        raw_envelope="[IMPORTANT: Background process finished]",
    );
    s_eager +>:TurnAdoptedIn:+> t_normal_wakeup;

    root ++> s_deferred ++> s_eager;

    auditor = AdoptionAuditor();
    root spawn auditor;
    print(f"audit summary: reported={auditor.reported} dropped={auditor.dropped}");
    print(f"expected: adoption branch dropped source on {2} turns (async + fork)");

    fixer = FixPropagation();
    root spawn fixer;

    print("=== Re-audit after fix ===");
    recheck = AdoptionAuditor();
    root spawn recheck;
    print(f"audit summary: reported={recheck.reported} dropped={recheck.dropped}");
}
