"""DogBuild strategy review gate.

Models the issue's core entities as graph nodes: a Plan that authorizes
work, an ImplementationAgent that does the work, a Discovery that emerges
during investigation, and a ReviewRequest that is emitted when a discovery
crosses a strategy boundary. A walker audits the plan -> discovery chain
and decides whether a review round is required before the agent may
proceed, exactly as the issue mandates.
"""

# ---- Domain entities ----------------------------------------------------

node Plan {
    has title: str = "";
    has authorized_approach: str = "";
    has acceptance_criteria: str = "";
}

node ImplementationAgent {
    has name: str = "";
    has acted_on_discovery: bool = False;
}

node Discovery {
    has finding: str = "";
    has triggers_review: bool = False;
    has changed_assumption: str = "";
}

node ReviewRequest {
    has reason: str = "";
    has raised_by: str = "";
}

node ReviewedDiscovery {
    has finding: str = "";
}

# ---- Relationships (typed edges) ---------------------------------------

edge Authorizes {
    has approved_on: str = "";
}

edge Investigating {
    has packet_id: str = "";
}

edge Surfaced {
    has evidence: str = "";
}

edge EscalatesTo {
    has category: str = "";
}

edge ApprovedAfter {
    has decision: str = "";
}

# ---- Walker that enforces the strategy-review gate ---------------------

walker StrategyAuditor {
    has violations: list = [];
    has reviews_required: int = 0;
    has material_categories: list = [
        "architecture",
        "scope",
        "acceptance_policy",
        "sequencing",
        "authority",
        "safety_policy",
        "settled_decision",
    ];

    can start with Root entry {
        visit [->:Authorizes:->];
    }

    can audit_plan with Plan entry {
        print(f"[PLAN] authorized: {here.authorized_approach}");
        visit [->:Investigating:->];
    }

    can audit_agent with ImplementationAgent entry {
        print(f"[AGENT] {here.name} acted={here.acted_on_discovery}");
        if here.acted_on_discovery {
            self.violations.append(
                f"{here.name} implemented without strategy review"
            );
        }
        visit [->:Surfaced:->];
    }

    can classify_discovery with Discovery entry {
        cat = here.changed_assumption;
        is_material = (cat in self.material_categories) or here.triggers_review;
        if is_material {
            self.reviews_required += 1;
            print(
                f"[GATE] MATERIAL discovery on '{cat}': "
                f"{here.finding} -> review required"
            );
            visit [->:EscalatesTo:->];
        } else {
            print(
                f"[GATE] routine detail on '{cat}': "
                f"no review needed -> {here.finding}"
            );
            visit [-->];
        }
    }

    can record_request with ReviewRequest entry {
        print(
            f"[REVIEW] request raised by {here.raised_by}: {here.reason}"
        );
        visit [->:ApprovedAfter:->];
    }

    can note_resolution with ReviewedDiscovery entry {
        print(f"[OK] cleared for implementation: {here.finding}");
        visit [-->];
    }
}

# ---- Demonstration graph -------------------------------------------------

with entry {
    plan = Plan(
        title="Staging E2E registration hardening",
        authorized_approach="make registration idempotent and retry-safe",
        acceptance_criteria="no duplicate registrations under transient 500s",
    );

    # Two agents: one stops at the gate (compliant), one implements (violation).
    compliant_agent = ImplementationAgent(
        name="agent-A", acted_on_discovery=False,
    );
    rogue_agent = ImplementationAgent(
        name="agent-B", acted_on_discovery=True,
    );

    # Routine discovery: a missing deterministic test stays inside the plan.
    routine = Discovery(
        finding="add deterministic unit test for retry counter reset",
        triggers_review=False,
        changed_assumption="internal_data_structure",
    );

    # Material discovery: acceptance policy was changed by the agent.
    material_acceptance = Discovery(
        finding="keep issue open until a natural staging 500 is observed",
        triggers_review=True,
        changed_assumption="acceptance_policy",
    );

    # Material discovery: architecture changed without review.
    material_arch = Discovery(
        finding="switch to client-generated UUID + probe/retry",
        triggers_review=True,
        changed_assumption="architecture",
    );

    # Wire the graph: Root --Authorizes--> Plan --Investigating--> Agent
    # Agent --Surfaced--> Discovery --EscalatesTo--> ReviewRequest
    # ReviewRequest --ApprovedAfter--> ReviewedDiscovery
    root +>:Authorizes(approved_on="2025-01-10"):+> plan;

    plan +>:Investigating(packet_id="P-174"):+> compliant_agent
        +>:Surfaced(evidence="unit test gap"):+> routine
        +>:EscalatesTo(category="acceptance_policy"):+> ReviewRequest(
            reason="closure semantics changed",
            raised_by="agent-A",
        )
        +>:ApprovedAfter(decision="hold open"):+> ReviewedDiscovery(
            finding="closure deferred to strategy"
        );

    plan +>:Investigating(packet_id="P-216"):+> rogue_agent
        +>:Surfaced(evidence="uuid race"):+> material_acceptance;

    plan +>:Investigating(packet_id="P-216"):+> rogue_agent
        +>:Surfaced(evidence="uuid race"):+> material_arch;

    auditor = StrategyAuditor();
    root spawn auditor;

    print(
        f"reviews_required={auditor.reviews_required} "
        f"violations={auditor.violations}"
    );
}
