    frz = [cand[0] ->:FreezesInto:->][?:Freeze][0];
    frz +>:AdmitsLens:+> Lens(reviewer="alice", admitted=True);
    frz +>:AdmitsLens:+> Lens(reviewer="bob", admitted=True);
    lens_a = [frz ->:AdmitsLens:->][?:Lens][0];
    lens_a +>:AllowsCorrection:+> Correction(bounded=True, count=1);
    corr = [lens_a ->:AllowsCorrection:->][?:Correction][0];
    corr +>:TargetsValidation:+> Validation(evidence="tests pass", targeted=True);
    vald = [corr ->:TargetsValidation:->][?:Validation][0];
    vald +>:ApprovesAndBurns:+> Approval(final=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    assert "Atomic compact-v2 lifecycle audit starting" in out, f"missing startup line: {out}";
    assert "[consent] candidate: RFC-7" in out, f"missing consent line: {out}";
    assert "[freeze] freeze_id=F-001" in out, f"missing freeze line: {out}";
    assert "[lens] admitted reviewer=alice" in out, f"missing alice lens line: {out}";
    assert "[lens] admitted reviewer=bob" in out, f"missing bob lens line: {out}";
    assert "[correction] bounded, count=1" in out, f"missing correction line: {out}";
    assert "[validation] evidence=tests pass" in out, f"missing validation line: {out}";
    assert "[burn] approval final; no receipt retained" in out, f"missing burn line: {out}";
    # Exactly one consent line even with two lenses after it.
    assert out.count("[consent]") == 1, f"expected exactly one consent line, got: {out}";
    # Burn is terminal: nothing follows it.
    burn_idx = out.index("[burn]");
    assert burn_idx == len(out) - len("[burn] approval final; no receipt retained\n"), f"burn not terminal: {out}";
}

# ---------------------------------------------------------------------------
# 2. No-consent candidate is reported and the walk advances (does not
#    refuse the whole audit; consent is informational on the candidate).
# ---------------------------------------------------------------------------
test "candidate without consent is reported but traversal continues" {
