"""Wildlife park feeding rounds.

The kiosk greets every tour party regardless of type. Zookeepers feed each
animal its species-appropriate meal (meat for lions, seed for parrots,
standard feed otherwise). School groups simply watch the animals.
"""

node Lion {
    has name: str = "";

    def meal() -> str {
        return "meat";
    }
}

node Parrot {
    has name: str = "";

    def meal() -> str {
        return "seed";
    }
}

node Zebra {
    has name: str = "";

    def meal() -> str {
        return "standard feed";
    }
}

node Enclosure {
    has label: str = "";
}

# Each tour party is modeled as a walker. A shared base walker would force
# us to share every `has` field across every party type, which loses the
# per-type identity we want. So each party declares its own abilities.

walker Zookeeper {
    has rounds: int = 0;

    can start with Root entry {
        print("Kiosk: Welcome to the wildlife park!");
        visit [-->];
    }

    can walk_halls with Enclosure entry {
        visit [-->];
    }

    # Union trigger: the keeper feeds lions AND parrots AND zebras, but
    # not the school group itself. The shared `meal()` method is defined
    # on every animal node, so one ability covers all of them.
    can feed with Lion | Parrot | Zebra entry {
        food = here.meal();
        print(f"Zookeeper feeds {here.name} the {food}");
        self.rounds += 1;
    }
}

walker SchoolGroup {
    can start with Root entry {
        print("Kiosk: Welcome to the wildlife park!");
        visit [-->];
    }

    can walk_halls with Enclosure entry {
        visit [-->];
    }

    # School groups only watch animals, so the union trigger matches all
    # three animal types and just observes them.
    can observe with Lion | Parrot | Zebra entry {
        print(f"School group watches {here.name}");
    }
}

with entry {
    savanna = Enclosure(label="Savanna");
    aviary = Enclosure(label="Aviary");
    meadow = Enclosure(label="Meadow");

    root ++> savanna ++> aviary ++> meadow;
    savanna ++> Lion(name="Leo");
    aviary ++> Parrot(name="Polly");
    meadow ++> Zebra(name="Zara");

    print("=== Zookeeper rounds ===");
    zk = Zookeeper();
    root spawn zk;
    print(f"Zookeeper completed {zk.rounds} feedings");

    print("=== School group visit ===");
    root spawn SchoolGroup();
}
