    assert "[INVALIDATE]" in out, f"missing INVALIDATE marker: {out}";
    assert "purging domain and downstream" in out, f"domain not purged: {out}";
    assert "purging parsing" not in out, f"parsing should not match prefix: {out}";
    assert "purging persistence" not in out, f"persistence should not match prefix: {out}";
}

test "auditor walks allowed import direction through dependency chain" {
    domain = Layer(name="domain");
    parsing = Layer(name="parsing");
    errors = Layer(name="errors");

    root ++> domain;
    domain +>:Allowed(reason="uses parsers"):+> parsing;
    parsing +>:Allowed(reason="raises"):+> errors;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
    }

