"""Quiz grader: walks a chain of Quiz nodes and reports integer scores."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.scores.append(here.score);
        visit [-->] else {
            disengage;
        }
    }

    def report -> int {
        total = 0;
        for s in self.scores {
            total = total + s;
        }
        avg = total // len(self.scores) if len(self.scores) > 0 else 0;
        return avg;
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=72)
        ++> Quiz(student="Cara", score=95)
        ++> Quiz(student="Dan", score=61);

    g = Grader();
    root spawn g;

    print(f"Class average: {g.report()}");
}
