"""Tests for the road-trip playlist: inline track creation + Player walker."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: Inline chain builds 3 tracks off root in one statement ----------
test "inline chain produces three tracks off root" {
    root ++> Track(title="Nightcall", artist="Kavinsky", seconds=258)
        ++> Track(title="Genesis", artist="Grimes", seconds=249)
        ++> Track(title="Midnight City", artist="M83", seconds=244);

    # Root has exactly ONE direct child -- `++>` is a chain, not a fan-out.
    assert len([root-->]) == 1, f"expected 1 direct child of root, got {len([root-->])}";

    # Walk the chain end-to-end and count Track nodes.
    cur = root;
    n = 0;
    while [cur-->] {
        n += 1;
        cur = [cur-->][0];
    }
    assert n == 3, f"expected 3 tracks along the chain, got {n}";
}

# ---------- Test 2: Player walker prints now-playing lines in order ----------
test "player prints three now-playing lines in chain order" {
    root ++> Track(title="Nightcall", artist="Kavinsky", seconds=258)
        ++> Track(title="Genesis", artist="Grimes", seconds=249)
        ++> Track(title="Midnight City", artist="M83", seconds=244);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    lines = out.splitlines();

    # Filter to lines that begin with the now-playing marker.
    play_lines = [ln for ln in lines if ln.startswith("Now playing:")];
    assert len(play_lines) == 3, f"expected 3 now-playing lines, got {len(play_lines)}: {lines}";

    # Each must mention the corresponding track, in chain order.
    assert "Nightcall" in play_lines[0], f"line 0 missing Nightcall: {play_lines[0]}";
    assert "Kavinsky" in play_lines[0], f"line 0 missing Kavinsky: {play_lines[0]}";
    assert "258" in play_lines[0], f"line 0 missing 258: {play_lines[0]}";

