    assert "M83" in play_lines[2], f"line 2 missing M83: {play_lines[2]}";
    assert "244" in play_lines[2], f"line 2 missing 244: {play_lines[2]}";

    # Walker's running total must equal the sum of the seconds.
    assert res.elapsed == 258 + 249 + 244, f"got elapsed={res.elapsed}";
