"""Weather sweep: stations hold readings; a walker visits each and gathers min/max."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_temp: float = 0.0;
    has max_temp: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        self.readings.append(here.celsius);
        if len(self.readings) == 1 {
            self.min_temp = here.celsius;
            self.max_temp = here.celsius;
        } else {
            lo = self.min_temp if here.celsius > self.min_temp else here.celsius;
            hi = self.max_temp if here.celsius < self.max_temp else here.celsius;
            self.min_temp = lo;
            self.max_temp = hi;
        }
        print(f"{here.name} @ {here.location}: {here.celsius} C");
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North", location="42N", celsius=12.5)
        ++> Station(name="East", location="12E", celsius=18.0)
        ++> Station(name="South", location="35S", celsius=24.3)
        ++> Station(name="West", location="8W", celsius=9.7);

    sweep = WeatherSweep();
    root spawn sweep;

    print(f"All readings: {sweep.readings}");
    print(f"Min: {sweep.min_temp} C, Max: {sweep.max_temp} C");
}
