```jac
"""agenteval-bench docs RFC: model the documentation overhaul plan as a graph.

Entities are DocSection, SectionStatus, and Feature nodes connected by typed
edges. A DocsAuditor walker traverses the dependency graph to perform the
exact kind of traversal a hand-rolled implementation would have done:
reachability, cycle detection across section dependencies, and cascading
invalidation when a section's status changes (planned -> drafted -> published).
"""

# --- base node for shared fields --------------------------------------------

node DocArtifact {
    has display_name: str = "";
    has category: str = "";
}

# --- node archetypes --------------------------------------------------------

node DocSection(DocArtifact) {
    has title: str = "";
    has doc_kind: str = "";      # "readme" | "spec" | "roadmap" | "hygiene"
    has status: str = "planned"; # "planned" | "drafted" | "published"
}

node SectionStatus(DocArtifact) {
    has label: str = "";
    has severity: int = 0;       # higher = more critical for release
}

node Feature(DocArtifact) {
    has name: str = "";
    has priority: int = 0;       # community-ranked priority for the RFC
    has planned: bool = True;
}

# --- typed edges (relationship carries meaning) -----------------------------

edge DependsOn {
    has reason: str = "";
}

edge Documents {
    has section_kind: str = "";
}

edge Targets {
    has audience: str = "";
}

# --- the auditor walker -----------------------------------------------------

walker DocsAuditor {
    has visited_keys: list[str] = [];
    has cycle_detected: bool = False;
    has depth_cap: int = 8;
    has depth: int = 0;

    can start with Root entry {
        print(f"=== Docs RFC audit starting (depth cap {self.depth_cap}) ===");
        visit [-->];
    }

    can audit_doc with DocSection entry {
        # Mark this node visited via its display_name; explicit cycle
        # policy because walkers have no built-in dedupe in jac 0.36.1.
        if here.display_name in self.visited_keys {
            self.cycle_detected = True;
            print(f"[CYCLE] revisit of '{here.display_name}' — cycle policy fired");
            disengage;
        }
        self.visited_keys.append(here.display_name);
        self.depth += 1;

        if self.depth > self.depth_cap {
            print(f"[DEPTH CAP] exceeded {self.depth_cap}; disengaging");
            disengage;
        }

        # Domain logic preserved: cascading invalidation when a doc section
        # moves out of `published`. Status is only on DocSection.
        if here.status == "published" {
            print(f"[OK]   published doc: '{here.title}'");
        } elif here.status == "drafted" {
            print(f"[WIP]  drafted doc:   '{here.title}'");
        } else {
            print(f"[TODO] planned doc:   '{here.title}'");
        }

        visit [->:DependsOn:->] else { disengage; }
    }

    can audit_status with SectionStatus entry {
        if here.display_name in self.visited_keys {
            disengage;
        }
        self.visited_keys.append(here.display_name);
        badge = "P0" if here.severity >= 3 else (
                "P1" if here.severity >= 2 else "P2");
        print(f"[STATUS {badge}] '{here.label}' (severity {here.severity})");
    }

    can audit_feature with Feature entry {
        if here.display_name in self.visited_keys {
            disengage;
        }
        self.visited_keys.append(here.display_name);
        badge = "P0" if here.priority >= 8 else (
                "P1" if here.priority >= 5 else "P2");
        state = "planned" if here.planned else "shipped";
        print(f"[FEATURE {badge}] '{here.name}' ({state})");
    }
}

walker PriorityRanker {
    can start with Root entry {
        print("=== Community priority ranking ===");
        visit [-->];
    }

    can rank with Feature entry {
        badge = "P0" if here.priority >= 8 else (
                "P1" if here.priority >= 5 else "P2");
        state = "planned" if here.planned else "shipped";
        print(f"[{badge}] {here.name} ({state})");
        visit [-->];
    }
}

# --- demo wiring ------------------------------------------------------------

with entry {
    # Doc sections the maintainer proposed in the RFC.
    readme     = DocSection(title="README.md",        doc_kind="readme",  status="drafted",  display_name="README.md",     category="doc_section");
    spec       = DocSection(title="docs/spec.md",     doc_kind="spec",    status="planned",  display_name="docs/spec.md",  category="doc_section");
    roadmap    = DocSection(title="docs/roadmap.md",  doc_kind="roadmap", status="planned",  display_name="docs/roadmap.md", category="doc_section");
    hygiene    = DocSection(title="CODEOWNERS/.gitignore", doc_kind="hygiene", status="published", display_name="CODEOWNERS/.gitignore", category="doc_section");

    # Section statuses (separate nodes so the walker ability can hit them).
    s_drafted  = SectionStatus(label="drafted",   severity=2, display_name="drafted",   category="section_status");
    s_planned  = SectionStatus(label="planned",   severity=1, display_name="planned",   category="section_status");
    s_publish  = SectionStatus(label="published", severity=3, display_name="published", category="section_status");

    # Community-ranked features the RFC asks the community to prioritize.
    f_llm_judge   = Feature(name="LLM-as-judge", priority=9, planned=True,  display_name="LLM-as-judge", category="feature");
    f_compare     = Feature(name="compare",     priority=8, planned=True,  display_name="compare",      category="feature");
    f_report      = Feature(name="report",      priority=6, planned=True,  display_name="report",       category="feature");
    f_typer_cli   = Feature(name="typer CLI",   priority=5, planned=True,  display_name="typer CLI",    category="feature");
    f_plugins     = Feature(name="plugins",     priority=3, planned=False, display_name="plugins",      category="feature");

    # Wire the documentation dependency graph with typed edges. The
    # DependsOn edges encode "this doc can't be finalized until that one
    # exists" — the exact relationship the hand-rolled adjacency dict used
    # to model. README -> spec, spec -> roadmap, roadmap -> hygiene form a
    # chain; spec also depends on hygiene, so traversal naturally exercises
    # multi-parent reachability and (if reordered) cycle detection.
    root ++> readme ++> spec ++> roadmap ++> hygiene;
    spec +>:DependsOn(reason="spec references hygiene policy"):+> hygiene;
    readme  +>:Documents(section_kind="overview"):+> s_publish;
    spec    +>:Documents(section_kind="contract"):+> s_planned;
    roadmap +>:Documents(section_kind="milestones"):+> s_planned;

    # Features attached to the spec node via typed Targets edges.
    spec +>:Targets(audience="adopters"):+>     f_llm_judge;
    spec +>:Targets(audience="contributors"):+> f_compare;
    spec +>:Targets(audience="CI integrators"):+> f_report;
    spec +>:Targets(audience="adopters"):+>     f_typer_cli;
    spec +>:Targets(audience="contributors"):+> f_plugins;

    # Spawn the auditor on root — it will walk the chain and dispatch
    # to type-specific abilities for DocSection, SectionStatus, Feature.
    root spawn DocsAuditor(depth_cap=6);
    print("");
    root spawn PriorityRanker();
}
