    can sweep with Capability entry {
        if here.title == self.target_title {
            print(f"  [cascade] found '{here.title}' -> removing with descendants");
            self.removed_count += 1;
            del here;
            disengage;
        }
        visit [->:ParentOf:->];
    }
}

