"""Signed immutable optimization evidence bundles.

Models the essential scenario from the v1.8 roadmap issue natively: configs,
metrics, and artifacts hang off experiments through typed edges; a bundle
walker walks the evidence tree, proves it's acyclic (cycle detection), and
performs a cascade invalidation that purges dependent studies when their
upstream evidence is withdrawn.
"""

node Config {
    has title: str = "";
    has checksum: str = "";
    has revoked: bool = False;
}

node Metric {
    has name: str = "";
    has value: float = 0.0;
}

node Artifact {
    has path: str = "";
    has size_kb: int = 0;
}

node EvidenceBundle {
    has bundle_id: str = "";
    has signature: str = "valid";
    has published: bool = True;
    has visited: bool = False;
}

edge DerivedFrom {
    has weight: float = 1.0;
}

edge Contains {}

walker Auditor {
    has trail: list[str] = [];
    has cycle_found: bool = False;
    has seen: list[str] = [];

    can start with Root entry {
        print(f"Auditor engaged: trail={self.trail}");
        visit [-->];
    }

    can descend with EvidenceBundle entry {
        if here.visited {
            self.cycle_found = True;
            print(f"[CYCLE] re-entered bundle {here.bundle_id}");
            disengage;
        }
        here.visited = True;
        self.seen.append(here.bundle_id);
        self.trail.append(here.bundle_id);
        print(f"entering bundle {here.bundle_id} (sig={here.signature})");
        if here.signature == "invalid" {
            print(f"  signature FAILED on {here.bundle_id}");
        }
        visit [-->];
    }

    can record_config with Config entry {
        verdict = "REVOKED" if here.revoked else "OK";
        self.trail.append(f"cfg:{here.title}:{verdict}");
        print(f"  config [{verdict}] {here.title} ck={here.checksum}");
    }

    can record_metric with Metric entry {
        self.trail.append(f"m:{here.name}={here.value}");
        print(f"  metric {here.name}={here.value}");
    }

    can record_artifact with Artifact entry {
        self.trail.append(f"art:{here.path}/{here.size_kb}kb");
        print(f"  artifact {here.path} ({here.size_kb}kb)");
    }
}

walker CascadeInvalidator {
    has purged: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        print("Cascade invalidator sweeping dependents");
        visit [-->];
    }

    can sweep with EvidenceBundle entry {
        if self.depth > 4 {
            print(f"  depth cap hit at {here.bundle_id}, disengaging");
            disengage;
        }
        if here.published {
            here.published = False;
            self.purged.append(here.bundle_id);
            print(f"  invalidated bundle {here.bundle_id}");
        }
        self.depth += 1;
        visit [<--];
    }
}

with entry {
    # Wire a small evidence graph: one root bundle, a peer bundle, and
    # concrete evidence members linked by typed edges that carry meaning.
    root_bundle = EvidenceBundle(bundle_id="B-001", signature="valid");
    peer_bundle = EvidenceBundle(bundle_id="B-002", signature="invalid");
    nested_bundle = EvidenceBundle(bundle_id="B-003", signature="valid");

    root ++> root_bundle;
    root ++> peer_bundle;
    root ++> nested_bundle;

    # Typed edges record the derivation lineage (DerivedFrom) and the
    # membership of the bundle (Contains).
    root_bundle +>:Contains:+> Config(
        title="model.yaml", checksum="sha256:aaaa"
    );
    root_bundle +>:Contains:+> Config(
        title="data.yaml", checksum="sha256:bbbb", revoked=True
    );
    root_bundle +>:Contains:+> Metric(name="accuracy", value=0.91);
    root_bundle +>:Contains:+> Artifact(path="model.ckpt", size_kb=2048);

    peer_bundle +>:Contains:+> Metric(name="f1", value=0.73);
    peer_bundle +>:Contains:+> Artifact(path="notes.txt", size_kb=2);

    # Cross-bundle lineage via DerivedFrom; this is the path the cycle
    # guard in Auditor has to police.
    peer_bundle +>:DerivedFrom(weight=0.8):+> root_bundle;
    nested_bundle +>:DerivedFrom(weight=0.5):+> peer_bundle;

    # Force a cycle to demonstrate the guard: nested -> peer -> root
    # already exists, and we close the loop root -> nested.
    root_bundle +>:DerivedFrom(weight=1.0):+> nested_bundle;

    # Demo 1: walk the evidence and run cycle / signature audit.
    print("=== AUDIT PASS ===");
    root spawn Auditor();

    print("");
    print("=== CASCADE INVALIDATION ===");
    CascadeInvalidator() spawn root;

    # Demo 2: when a primary config is revoked, dependents (the bundles
    # that derived from it) are pulled from publication.
    print("");
    print("=== POST-CASCADE STATE ===");
    for b in [root_bundle, peer_bundle, nested_bundle] {
        state = "live" if b.published else "purged";
        print(f"  {b.bundle_id}: {state}");
    }
