import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. The librarian must walk every book reachable from root and print each
#    one with the correct IN/OUT status derived from `available`.
# ---------------------------------------------------------------------------
test "walker visits every book and prints correct status" {
    root ++> Book(title="Dune", year=1965)
        ++> Book(title="Neuromancer", year=1984)
        ++> Book(title="Circe", year=2018, available=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Librarian();
    }
    out = buf.getvalue();

    # Exactly three book lines were printed (one per book).
    lines = [l for l in out.strip().split("\n") if l != ""];
    assert len(lines) == 3, f"expected 3 printed lines, got {len(lines)}: {out!r}";

    # Default-available books get [IN], the explicitly unavailable one gets [OUT].
    assert "[IN] Dune (1965)" in out, f"missing Dune IN line: {out!r}";
    assert "[IN] Neuromancer (1984)" in out, f"missing Neuromancer IN line: {out!r}";
    assert "[OUT] Circe (2018)" in out, f"missing Circe OUT line: {out!r}";

    # Status must follow the availability flag — make sure no book is mislabeled.
    assert "[OUT] Dune" not in out, "Dune is available, must not be OUT";
    assert "[IN] Circe" not in out, "Circe is unavailable, must not be IN";
}

# ---------------------------------------------------------------------------
# 2. The node defaults promised by the spec: year defaults to 0 and
#    available defaults to True when omitted.
# ---------------------------------------------------------------------------
test "node defaults year to 0 and available to True" {
    b1 = Book(title="Untitled Year Book");
    b2 = Book(title="Default Available Book");
    root ++> b1 ++> b2;

    assert b1.year == 0, f"year should default to 0, got {b1.year}";
    assert b1.available is True, f"available should default to True, got {b1.available}";
    assert b2.year == 0, f"year should default to 0, got {b2.year}";
    assert b2.available is True, f"available should default to True, got {b2.available}";
}

# ---------------------------------------------------------------------------
# 3. Explicit field values must override the defaults — year and available
#    are both settable on construction.
# ---------------------------------------------------------------------------
test "explicit field values override defaults" {
    unknown_year = Book(title="Unknown Year");
    out_book = Book(title="Checked Out", year=2000, available=False);
    in_book = Book(title="On Shelf", year=2010, available=True);
    root ++> unknown_year ++> out_book ++> in_book;

    assert unknown_year.year == 0, "explicit-less year must stay default 0";
    assert unknown_year.available is True, "explicit-less available must stay default True";

    assert out_book.year == 2000, f"expected year 2000, got {out_book.year}";
    assert out_book.available is False, f"expected available False, got {out_book.available}";

    assert in_book.year == 2010, f"expected year 2010, got {in_book.year}";
    assert in_book.available is True, f"expected available True, got {in_book.available}";

    # Spot-check the field values from the graph view rather than relying on
    # insertion order — books appear in the spawned node list too.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Librarian();
    }
    out = buf.getvalue();
    assert "[OUT] Checked Out (2000)" in out, f"missing OUT line for checked-out book: {out!r}";
    assert "[IN] On Shelf (2010)" in out, f"missing IN line for on-shelf book: {out!r}";
}

# ---------------------------------------------------------------------------
# 4. A walk over a shelf with no books must produce no book lines and must
#    not crash the walker (Root entry still fires and dispatches `visit`).
# ---------------------------------------------------------------------------
test "walker on an empty shelf produces no book output and does not crash" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Librarian();
    }
    out = buf.getvalue();
    assert out.strip() == "", f"expected no output for empty shelf, got {out!r}";
    # The walker still ran to completion without raising.
    assert res is not None, "walker should return a result even on empty shelf";
}

