        methods=["as_int"],
        impl_digest="impl-M"
    );
    seconds = TypeDecl(
        kind="struct",
        name="Seconds",
        fields=["float v"],
        methods=["as_int"],
        impl_digest="impl-S"
    );

    rt ++> config_a;
    rt ++> config_b;
    rt ++> metres;
    rt ++> seconds;

    config_a +>:DependsOn(kind="field"):+> metres;
    config_a +>:DependsOn(kind="field"):+> seconds;
    config_b +>:DependsOn(kind="field"):+> metres;
    config_b +>:DependsOn(kind="field"):+> seconds;

    builder = DigestBuilder();
    rt spawn builder;

    assert config_a.declared_digest == config_b.declared_digest, (
        f"shape digests differ: {config_a.declared_digest!r} vs {config_b.declared_digest!r}"
    );
    assert config_a.resolved_digest == config_b.resolved_digest, (
        f"resolved digests differ: {config_a.resolved_digest!r} vs {config_b.resolved_digest!r}"
    );
}

test "distinct names with identical shape keep distinct identity" {
    rt = root;
    metres = TypeDecl(
        kind="struct",
        name="Metres",
        fields=["float v"],
        methods=["as_int"],
        impl_digest="impl-M"
    );
    seconds = TypeDecl(
        kind="struct",
        name="Seconds",
        fields=["float v"],
        methods=["as_int"],
        impl_digest="impl-S"
    );

    rt ++> metres;
    rt ++> seconds;

    builder = DigestBuilder();
    rt spawn builder;

    assert metres.resolved_digest != seconds.resolved_digest, (
        f"name should distinguish identity: {metres.resolved_digest!r}"
    );
    assert metres.declared_digest != seconds.declared_digest, (
        f"shape digest should include name: {metres.declared_digest!r}"
