"""Xark build cache invalidation: model compiler, source, artifact, and extraction stamp
as a graph; a walker walks dependencies to decide whether to invalidate cached artifacts."""

# Each build artifact emitted by the compiler
node Artifact {
    has name: str = "";
    has required: bool = True;
    has present: bool = False;
    has hash: str = "";
}

# Extraction inputs that must participate in the cache key
node ExtractionKey {
    has compiler_bin: str = "";
    has field: str = "";
    has profile_mode: bool = False;
    has output_dir: str = "";
    has schema: str = "";
    has stamp: str = "";
}

# A Rust source file the compiler reads (mtimes must NOT be touched)
node SourceFile {
    has path: str = "";
    has mtime: int = 0;
}

# A dependency crate Cargo caches separately from the circuit crate
node DependencyCrate {
    has name: str = "";
    has rebuilt: bool = False;
}

# A Cargo cache target directory
node CargoCache {
    has target_dir: str = "";
}

# Edges model the relationships the issue is about
edge ProducedBy {}
edge DependsOn {}
edge Fingerprinted {}
edge ReadsSource {}

# Walker that audits whether artifacts need regeneration and whether
# dependencies should be left cached.
walker CacheAuditor {
    has mismatches: list[str] = [];
    has missing_required: list[str] = [];
    has invalidations: list[str] = [];
    has dependency_rebuilds: list[str] = [];

    can start with Root entry {
        print("Cache audit begins");
        visit [->:ProducedBy:->];
        visit [->:Fingerprinted:->];
    }

    can check_artifact with Artifact entry {
        # rule 1: cargo_status.success() must precede reading existing artifact
        cargo_status_ok = here.present;
        # rule 2: required artifacts (circuit.json, r1cs.json, profile.json in profile mode)
        if here.required and not here.present {
            self.missing_required.append(here.name);
        }
        # acceptance gate 1: broken rust must not be reported as success
        if not cargo_status_ok and here.hash != "" {
            note = "STALE: " + here.name + " cargo_status=false but artifact hash=" + here.hash;
            self.mismatches.append(note);
        }
        visit [-->];
    }

    can check_key with ExtractionKey entry {
        # acceptance gate 3: compiler change, field, profile, output, schema all invalidate
        parts_list: list[str] = [
            here.compiler_bin,
            here.field,
            str(here.profile_mode),
            here.output_dir,
            here.schema
        ];
        joined = ",".join(parts_list);
        if here.stamp != joined {
            drift = "stamp drift: stored=" + here.stamp + " computed=" + joined;
            self.invalidations.append(drift);
        }
        # acceptance gate 5: dependency crates must NOT be rebuilt on key change
        visit [->:Fingerprinted:->];
    }

    can mark_invalidation with CargoCache entry {
        if len(self.invalidations) > 0 {
            # package-scoped clean (decision A): only the circuit package is cleaned
            print("  -> package-scoped clean on " + here.target_dir);
        }
        visit [->:DependsOn:->];
        visit [-->];
    }

    can protect_dependency with DependencyCrate entry {
        # acceptance gate 5: dependency must NOT be invalidated by extraction-key drift
        line = here.name + ":rebuilt=" + str(here.rebuilt);
        self.dependency_rebuilds.append(line);
        visit [-->];
    }
}

with entry {
    # extraction key: compiler + field + profile_mode + output + schema
    key = ExtractionKey(
        compiler_bin="xark-0.4.2",
