"""UDLM profile conformance walker.

Models the issue's core scenario: a UDLM mechanism (a profile record shape
with a `contains` bundle of references plus settings) decoupled from a
named Profile Set artifact. The walker audits which profiles an estate
declares against which profile-set version it pins, then cascades
invalidation down `contains` chains when a referenced sub-bundle is
missing or stale.
"""

node Mechanism {
    has spec_version: str = "";
    has profile_set_ref: str = "";
    has profile: str = "";
    has valid: bool = True;
}

node ProfileSet {
    has set_id: str = "";
    has set_version: str = "";
    has posture_count: int = 0;
}

node Posture {
    has name: str = "";
    has kind: str = "";
}

node Reference {
    has target: str = "";
    has stale: bool = False;
}

edge Conforms {
    has since: str = "";
}

edge Contains {
    has ordinal: int = 0;
}

edge Defines {
    has slot: str = "";
}

edge References {
    has optional: bool = False;
}

walker ProfileAuditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with Mechanism entry {
        m = here;
        self.findings.append(
            f"udlm={m.spec_version} set={m.profile_set_ref} profile={m.profile}"
        );
        if m.spec_version == "" or m.profile_set_ref == "" {
            m.valid = False;
            self.findings.append("  FAIL: missing udlm_version or profile_set");
            disengage;
        }
        visit [-->];
    }

    can cross_set with ProfileSet entry {
        s = here;
        if s.set_version == "" {
            self.findings.append(f"  FAIL: profile set {s.set_id} has no version");
        } else {
            self.findings.append(
                f"  OK: profile set {s.set_id}@{s.set_version} "
                f"defines {s.posture_count} postures"
            );
        }
        visit [-->];
    }

    can check_posture with Posture entry {
        p = here;
        self.findings.append(f"  posture: {p.name} ({p.kind})");
        visit [-->];
    }

    can invalidate_references with Reference entry {
        r = here;
        if r.stale {
            r.target = "[INVALIDATED]";
            self.findings.append(f"  CASCADE: reference -> {r.target} marked stale");
        }
        visit [-->];
    }
}

with entry {
    fsi_set = ProfileSet(set_id="udlm/profiles", set_version="2.0", posture_count=6);
    fsi_posture = Posture(name="fsi", kind="regulated");
    sovereign_posture = Posture(name="sovereign", kind="data-sovereignty");

    estate = Mechanism(
        spec_version="1.0",
        profile_set_ref="udlm/profiles@2.0",
        profile="fsi"
    );

    ref_audit = Reference(target="audit-trail");
    ref_retention = Reference(target="retention-7y");
    ref_retention.stale = True;
    ref_provider = Reference(target="attestation-gated");

    root +>:Conforms(since="2024-01"):+> estate;
    estate +>:Defines(slot="profile"):+> fsi_set;
    fsi_set +>:Defines(slot="posture"):+> fsi_posture;
    fsi_set +>:Defines(slot="posture"):+> sovereign_posture;
    estate +>:Contains(ordinal=1):+> ref_audit;
    estate +>:Contains(ordinal=2):+> ref_retention;
    estate +>:Contains(ordinal=3):+> ref_provider;

    auditor = ProfileAuditor();
    root spawn auditor;

    print("=== UDLM conformance audit ===");
    for note in auditor.findings {
        print(note);
    }
    print(f"estate.valid = {estate.valid}");
    print(f"retention ref after cascade = {ref_retention.target}");
