"""HCA schema override register: 12 deliberate divergences from CELLxGENE 7.0.0.

Models the override register as a graph of Override nodes connected to SchemaLayer
nodes, walked by a Reconciler walker that detects upstream divergence and reports
which inherited (un-overridden) fields silently follow the 7.0.0 baseline.
"""

node Override {
    has number: int = 0;
    has title: str = "";
    has layer: str = "";
    has commit: str = "";
    has issue: str = "";
    has direction: str = "";
}

node SchemaLayer {
    has name: str = "";
    has baseline_version: str = "7.0.0";
}

edge OverrideOf {
    has since: str = "";
}

edge InheritedFrom {
    has reason: str = "";
}

walker Reconciler {
    has visited: list[str] = [];
    has strict_count: int = 0;
    has relax_count: int = 0;
    has extend_count: int = 0;

    can start with Root entry {
        self.visited = [];
        visit [->:OverrideOf:->];
    }

    can audit with Override entry {
        if here.direction == "tighten" or here.direction == "invert (privacy)" {
            self.strict_count += 1;
        } elif here.direction == "relax" {
            self.relax_count += 1;
        } elif here.direction == "extend" {
            self.extend_count += 1;
        } else {
            # reject CXG relocation / ahead of upstream / superseded
            self.extend_count += 1;
        }
        here_title = here.title;
        self.visited.append(f"#{here.number} {here_title} ({here.direction})");
        visit [->:OverrideOf:->];
    }

    can sweep with SchemaLayer entry {
        next_label = f"layer={here.name} baseline={here.baseline_version}";
        self.visited.append(next_label);
        visit [-->] else {
            report {
                "traversal": self.visited,
                "tighten_or_invert": self.strict_count,
                "relax": self.relax_count,
                "extend_or_other": self.extend_count,
            };
            disengage;
        }
    }
}

