```jac
"""Recursive task planner: model PlanGraph as a typed-edge DAG and walk it.

Models the scenario from issue #4122 — a planner that expands tasks into
sub-graphs must validate the sub-graph for cycles, otherwise a cyclic
dynamic expansion produces an unbounded traversal. Two walkers demonstrate
the fix: ``RawExpansion`` reproduces the buggy path (raw edges, no cycle
guard, hangs on cyclic input) and ``ValidatedExpansion`` reproduces the
fixed path (returns the validated graph and walks it with an explicit
visited set, so cycles terminate cleanly).
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Task {
    has title: str = "";
    has done: bool = False;
}

# A ``PlanGraph`` is the planner's view of a sub-task DAG. It owns its task
# nodes plus the typed ``DependsOn`` edges that connect them.
node PlanGraph {
    has label: str = "";
    has task_count: int = 0;
    has validated: bool = False;
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

# ``DependsOn`` is the typed edge that encodes "task A must finish before
# task B can start".  The walker follows these to perform topological
# ordering; declaring them as a typed edge replaces the raw ``Map<id,
# id[]>`` adjacency scaffolding from the buggy TypeScript code.
edge DependsOn { }

# ``Contains`` ties a ``Task`` to its owning ``PlanGraph`` so the walker
# can iterate only over the tasks that belong to the sub-graph it is
# validating.
edge Contains { }

# ---------------------------------------------------------------------------
# Walkers
# ---------------------------------------------------------------------------

# Reproduces the *buggy* code path from issue #4122: the planner used to
# discard the validated graph and walk the raw edges. Because the walker
# has no visited-set in 0.36.1, a cyclic sub-graph here would loop
# forever — the very symptom the issue calls out.
walker RawExpansion {
    has visited_count: int = 0;
    has max_steps: int = 0;
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can expand with PlanGraph entry {
        print(f"[raw] expanding {self.reason!r} ({here.task_count} tasks)");
        self.visited_count = 0;
        visit [->:Contains:->];
    }

    # No cycle guard — exactly the behaviour the issue reports.  We cap
    # steps only to keep the demo finite; the cap is *not* the cycle
    # policy, it is a demo safety net so the script terminates.
    can traverse with Task entry {
        self.visited_count += 1;
        if self.visited_count > self.max_steps {
            print("[raw] step cap reached — cyclic sub-graph undetected, "
                  "planner would loop forever in production");
            disengage;
        }
        visit [->:DependsOn:->];
    }
}

# Reproduces the *fixed* code path: the validated graph is what gets
# walked. ``ValidatedExpansion`` carries an explicit visited-set (the
# cycle policy that must survive the lift), so a cyclic sub-graph
# terminates on the second visit instead of looping.
walker ValidatedExpansion {
    has visited_count: int = 0;
    has visited_titles: list[str] = [];
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can expand with PlanGraph entry {
        if not here.validated {
            print(f"[validated] rejecting sub-graph {here.label!r}: "
                  "no cycle/topology check performed");
            disengage;
        }
        print(f"[validated] expanding {self.reason!r} ({here.task_count} tasks)");
        self.visited_count = 0;
        self.visited_titles = [];
        visit [->:Contains:->];
    }

    # Cycle guard — the domain rule that issue #4122 was failing to
    # enforce.  We record every title we have already walked; a repeat
    # means the sub-graph has a cycle and traversal stops cleanly with a
    # ``CyclicDependencyError``-shaped report.
    can traverse with Task entry {
        if here.title in self.visited_titles {
            print(f"[validated] CyclicDependencyError: "
                  f"task {here.title!r} revisited");
            disengage;
        }
        self.visited_titles.append(here.title);
        self.visited_count += 1;
        order = "pending" if not here.done else "done";
        print(f"  step {self.visited_count}: {here.title} ({order})");
        visit [->:DependsOn:->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # --- Sub-graph A: a clean DAG, both walkers must finish it -----------
    a_intake = Task(title="A:intake", done=True);
    a_parse = Task(title="A:parse");
    a_plan = Task(title="A:plan");
    a_execute = Task(title="A:execute");
    sub_a = PlanGraph(label="subgraph-A", task_count=4, validated=True);

    sub_a +>:Contains:+> a_intake;
    sub_a +>:Contains:+> a_parse;
    sub_a +>:Contains:+> a_plan;
    sub_a +>:Contains:+> a_execute;

    # Dependencies: intake -> parse -> plan -> execute
    a_intake +>:DependsOn:+> a_parse;
    a_parse +>:DependsOn:+> a_plan;
    a_plan +>:DependsOn:+> a_execute;

    # --- Sub-graph B: cyclic dynamic expansion (intake -> review -> intake)
    b_intake = Task(title="B:intake");
    b_review = Task(title="B:review");
    b_close = Task(title="B:close");
    sub_b = PlanGraph(label="subgraph-B", task_count=3, validated=True);

    sub_b +>:Contains:+> b_intake;
    sub_b +>:Contains:+> b_review;
    sub_b +>:Contains:+> b_close;

    b_intake +>:DependsOn:+> b_review;
    b_review +>:DependsOn:+> b_intake;   # <-- cycle
    b_intake +>:DependsOn:+> b_close;

    # --- Sub-graph C: looks valid by structure but was never validated,
    #     so the fixed walker must refuse it.
    c_only = Task(title="C:only");
    sub_c = PlanGraph(label="subgraph-C", task_count=1, validated=False);
    sub_c +>:Contains:+> c_only;

    root ++> sub_a ++> sub_b ++> sub_c;

    # ---- Buggy path: raw edges, no cycle guard -------------------------
    raw_walker = RawExpansion(reason="recursive expansion",
                              max_steps=20);
    root spawn raw_walker;
    print(f"[raw] walker terminated after {raw_walker.visited_count} steps");

    # ---- Fixed path: validated graph + explicit visited-set ------------
    fixed_walker = ValidatedExpansion(reason="recursive expansion");
    root spawn fixed_walker;
    print(f"[validated] walker terminated after "
          f"{fixed_walker.visited_count} steps");
}
