"""HLSL helper ordering: model helpers as nodes connected by Call edges,
then emit them in topological order, falling back to forward declarations
for cycles. Mirrors issue #1521 from CrossGL/crosstl."""

node HlslHelper {
    has name: str = "";
    has body: str = "";
    has qualifiers: str = "in";
    has array_extent: int = 0;
    has is_recursive: bool = False;
    has emitted: bool = False;
    has signature: str = "";
}

edge Call {
    has call_site: str = "";
}

walker EmitHelpers {
    has package: str = "main";
    has order: list[str] = [];
    has diagnostics: list[str] = [];
    has cycle_stack: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    def is_in_stack(h_name: str) -> bool {
        for s in self.cycle_stack {
            if s == h_name {
                return True;
            }
        }
        return False;
    }

    def make_forward_decl(h: HlslHelper) -> str | None {
        if h.is_recursive and h.array_extent == 0 and h.qualifiers in ("in", "out", "inout") {
            return f"{h.signature}; // forward decl for {h.name}";
        }
        return None;
    }

    can topo_emit with HlslHelper entry {
        if here.emitted {
            visit [-->];
            return;
        }
        if self.is_in_stack(here.name) {
            fwd = self.make_forward_decl(here);
            if fwd is not None {
                print(fwd);
                self.diagnostics.append(fwd);
            } else {
                err = f"[ERROR] cannot declare {here.name} legally in HLSL";
                print(err);
                self.diagnostics.append(err);
            }
            here.emitted = True;
            visit [-->];
            return;
        }
        self.cycle_stack.append(here.name);
        unresolved = False;
        for callee in [->:Call:->] {
            if not callee.emitted {
                unresolved = True;
                break;
            }
        }
        if unresolved {
            self.cycle_stack.pop();
            visit [->:Call:->];
            return;
        }
        print(here.body);
        self.order.append(here.name);
        here.emitted = True;
        self.cycle_stack.pop();
        visit [-->];
    }
}

walker BuildGraph {
    can start with Root entry {
        visit [-->];
    }

    can index with HlslHelper entry {
        if here.signature == "" {
            arr = f"[{here.array_extent}]" if here.array_extent > 0 else "";
            here.signature = f"void {here.name}{arr}({here.qualifiers} float x)";
        }
        visit [-->];
    }
}

with entry {
    # --- Build helpers ---------------------------------------------------------
    run_main = HlslHelper(name="run_main", body="void run_main(in float x) { load_safe(x); load_unsafe(x); }");
    load_safe = HlslHelper(name="load_safe", body="void load_safe(in float x) { return; }");
    load_unsafe = HlslHelper(name="load_unsafe", body="void load_unsafe(in float x) { helper_a(x); helper_b(x); }");
    helper_a = HlslHelper(name="helper_a", body="void helper_a(in float x) { return; }");
    helper_b = HlslHelper(name="helper_b", body="void helper_b(in float x) { return; }");

    # Mutually recursive SCC: a <-> b (HLSL allows forward decls for these).
    rec_a = HlslHelper(name="rec_a", body="void rec_a(in float x) { rec_b(x); }", is_recursive=True);
    rec_b = HlslHelper(name="rec_b", body="void rec_b(in float x) { rec_a(x); }", is_recursive=True);

    # An illegal-to-forward-declare helper (array extent on a recursive helper).
    bad_rec = HlslHelper(
        name="bad_rec",
        body="void bad_rec(in float x) { bad_rec(x); }",
        is_recursive=True,
        array_extent=4
    );

    # --- Wire calls (typed Call edges) -----------------------------------------
    root ++> run_main;
    run_main +>:Call(call_site="load_safe(x)"):+> load_safe;
    run_main +>:Call(call_site="load_unsafe(x)"):+> load_unsafe;
    load_unsafe +>:Call(call_site="helper_a(x)"):+> helper_a;
    load_unsafe +>:Call(call_site="helper_b(x)"):+> helper_b;
    rec_a +>:Call(call_site="rec_b(x)"):+> rec_b;
    rec_b +>:Call(call_site="rec_a(x)"):+> rec_a;
    bad_rec +>:Call(call_site="bad_rec(x)"):+> bad_rec;

    # --- First, give every helper a signature ---------------------------------
    indexer = BuildGraph();
    root spawn indexer;

    # --- Emit in dependency order ---------------------------------------------
    emit = EmitHelpers(package="main");
    root spawn emit;

    print("---");
    print(f"emission order: {emit.order}");
    print(f"diagnostics: {emit.diagnostics}");
}
