test "indexes typed helper calls" {
    caller = HlslHelper(name="caller", body="caller");
    callee = HlslHelper(name="callee", body="callee");
    root ++> caller;
    caller +>:Call(call_site="callee(x)"):+> callee;
    indexer = BuildGraph();
    root spawn indexer;
    assert caller.signature == "void caller(in float x)", f"got {caller.signature}";
    assert callee.signature == "void callee(in float x)", f"got {callee.signature}";
    call_targets = [caller ->:Call:->];
    assert len(call_targets) == 1, f"got {len(call_targets)}";
    assert callee in [caller ->:Call:->], f"missing callee edge";
}

test "emits callees before callers" {
    leaf = HlslHelper(name="leaf", body="void leaf(in float x) { return; }");
    middle = HlslHelper(name="middle", body="void middle(in float x) { leaf(x); }");
    caller = HlslHelper(name="caller", body="void caller(in float x) { middle(x); }");
    root ++> leaf;
    root ++> middle;
    root ++> caller;
    middle +>:Call(call_site="leaf(x)"):+> leaf;
    caller +>:Call(call_site="middle(x)"):+> middle;
    indexer = BuildGraph();
    root spawn indexer;
    emitter = EmitHelpers(package="main");
    root spawn emitter;
    assert emitter.order == ["leaf", "middle", "caller"], f"got {emitter.order}";
    assert leaf.emitted == True, f"leaf emitted={leaf.emitted}";
    assert middle.emitted == True, f"middle emitted={middle.emitted}";
    assert caller.emitted == True, f"caller emitted={caller.emitted}";
}

test "forward declarations preserve legal signatures and reject arrays" {
    rec = HlslHelper(name="rec", body="rec", is_recursive=True, signature="void rec(in float x)");
    bad = HlslHelper(name="bad", body="bad", is_recursive=True, array_extent=4, signature="void bad[4](in float x)");
    root ++> rec;
    root ++> bad;
    emitter = EmitHelpers(package="pkg");
    decl = emitter.make_forward_decl(rec);
    rejected = emitter.make_forward_decl(bad);
    assert decl == "void rec(in float x); // forward decl for rec", f"got {decl}";
    assert rejected == None, f"got {rejected}";
}

