"""Weather sweep: stations hold a location and Celsius reading; a walker
visits each one and reports the temperature without disengaging mid-walk,
then the demo prints the full list plus min/max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[tuple[str, float]] = [];
    has min_t: float = 0.0;
    has max_t: float = 0.0;
    has count: int = 0;

    can start with Root entry {
        print("Weather sweep starting...");
        visit [-->];
    }

    can read with WeatherStation entry {
        print(f"At {here.location}: {here.celsius} C");
        self.readings.append((here.location, here.celsius));
        if self.count == 0 {
            self.min_t = here.celsius;
            self.max_t = here.celsius;
        } else {
            if here.celsius < self.min_t {
                self.min_t = here.celsius;
            }
            if here.celsius > self.max_t {
                self.max_t = here.celsius;
            }
        }
        self.count += 1;
        visit [-->];
    }

    can finish with Root exit {
        if self.count == 0 {
            print("No stations visited.");
            disengage;
        }
        print("All readings:");
        for (loc, temp) in self.readings {
            print(f"  {loc}: {temp} C");
        }
        print(f"Min: {self.min_t} C");
        print(f"Max: {self.max_t} C");
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Airport", celsius=19.0)
        ++> WeatherStation(location="Hilltop", celsius=27.3)
        ++> WeatherStation(location="Harbor", celsius=15.8);
    sweeper = WeatherSweep();
    root spawn sweeper;
}
