    has available: bool = True;
    has pid: int = 0;
    has command: str = "";
    has shell: bool = False;
    has suspicious: bool = False;
}

edge BeginsCall { }

edge Executes {
    has mode: str = "";
}

edge Spawned {
    has reason: str = "";
}

walker ProcessAudit {
    has visited_count: int = 0;
    has depth: int = 0;
    has max_depth: int = 2;

    can start with Root entry {
        print("audit: following one tool call into its process tree");
        visit [->:BeginsCall:->] else { disengage; }
