import io;
import from contextlib { redirect_stdout }

test "follows typed process tree and stops at depth limit" {
    call = ToolCall(tool_name="bash", request="run git status");
    root +>:BeginsCall:+> call;

    first = Process(pid=100, command="bash -lc git status", shell=True);
    call +>:Executes(mode="fork"):+> first;

    second = Process(
        pid=101,
        command="bash -lc bash -lc git status",
        shell=True,
        suspicious=True
    );
    first +>:Spawned(reason="tool wrapper"):+> second;

    leaf = Process(pid=102, command="git status");
    second +>:Spawned(reason="leaf command"):+> leaf;

    assert len([root-->]) == 1, f"unexpected root children: {len([root-->])}";
    assert call in [root ->:BeginsCall:->], f"missing call edge";
    assert first in [call ->:Executes:->], f"missing executes edge";
    assert second in [first ->:Spawned:->], f"missing first spawn edge";
    assert leaf in [second ->:Spawned:->], f"missing leaf spawn edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ProcessAudit(max_depth=2);
    }
    out = buf.getvalue();

    assert res.visited_count == 3, f"got {res.visited_count}";
    assert res.depth == 2, f"got {res.depth}";
    assert "warning: recursive shell growth detected" in out, f"missing warning: {out}";
    assert "depth guard stopped further spawning" in out, f"missing guard: {out}";
}

test "zero depth prevents recursive spawning" {
    call = ToolCall(tool_name="bash", request="run command");
    root +>:BeginsCall:+> call;

    first = Process(pid=200, command="bash -lc command", shell=True);
    call +>:Executes(mode="fork"):+> first;

    second = Process(pid=201, command="bash -lc bash", shell=True, suspicious=True);
    first +>:Spawned(reason="wrapper"):+> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ProcessAudit(max_depth=0);
    }
    out = buf.getvalue();

    assert res.visited_count == 1, f"got {res.visited_count}";
    assert res.depth == 0, f"got {res.depth}";
    assert "pid=200" in out, f"missing first process: {out}";
    assert "pid=201" not in out, f"unexpected recursive process: {out}";
    assert "depth guard stopped further spawning" in out, f"missing guard: {out}";
}

test "missing process edge fails closed" {
    call = ToolCall(tool_name="bash", request="run command");
    root +>:BeginsCall:+> call;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ProcessAudit();
    }
    out = buf.getvalue();

    assert res.visited_count == 0, f"got {res.visited_count}";
    assert "tool=bash request=run command" in out, f"missing tool output: {out}";
    assert "pid=" not in out, f"unexpected process traversal: {out}";
}

test "declared defaults remain safe for ordinary processes" {
    call = ToolCall(tool_name="bash", request="echo ok");
