"""Module-dependency refactor: model cyclic Python imports as graph machinery.

Demonstrates how cyclic module dependencies (agents.py <-> config.py <-> viz.py)
collapse to a typed-edge graph, traversed by a walker that breaks the cycles
via dependency inversion (extracting shared helpers into leaf modules).
"""

node Module {
    has name: str = "";
    has path: str = "";
    has lazy_imports: int = 0;
}

edge DependsOn {
    has call_sites: int = 0;
    has lazy: bool = False;
}

edge Inverts {
    has kind: str = "";
}

edge Provides {
    has symbols: str = "";
}

walker CycleBreaker {
    has extracted: list[str] = [];
    has resolved: bool = False;

    can start with Root entry {
        print("Scanning module graph for circular dependencies...");
        visit [->:DependsOn:->];
    }

    can scan with Module entry {
        print(f"  module: {here.name} (lazy imports: {here.lazy_imports})");
        visit [->:DependsOn:->];
    }

    can audit with Module entry {
        if here.lazy_imports > 0 {
            print(f"  CYCLE detected via {here.name}: "
                  f"{here.lazy_imports} local import(s)");
        }
        visit [->:Inverts:->];
    }

    can extract with Module entry {
        kind = "leaf helper";
        print(f"  extracting {here.name} as {kind}: {here.path}");
        self.extracted.append(here.name);
        visit [->:Provides:->];
    }

    can verify with Module entry {
        if len(self.extracted) >= 2 and not self.resolved {
            self.resolved = True;
            print("  DAG restored: all cyclic imports inverted via "
                  "leaf modules");
        }
        visit [->:DependsOn:->];
    }

    can summarize with Module entry {
        print(f"  {here.name} now imports lazily: 0 (was {here.lazy_imports})");
    }
}

with entry {
    config = Module(name="config", path="scripts/lib/config.py", lazy_imports=1);
    agents = Module(name="agents", path="scripts/lib/agents.py", lazy_imports=5);
    viz = Module(name="viz", path="scripts/lib/viz.py", lazy_imports=0);

    templating = Module(name="templating", path="scripts/lib/templating.py");
    viz_hooks = Module(name="viz_hooks", path="scripts/lib/viz_hooks.py");

    config +>:DependsOn(call_sites=2, lazy=True):+> agents;
    agents +>:DependsOn(call_sites=4, lazy=True):+> config;

    agents +>:DependsOn(call_sites=3, lazy=True):+> viz;
    viz +>:DependsOn(call_sites=1, lazy=False):+> agents;

    config +>:Inverts(kind="dependency-inversion"):+> templating;
    agents +>:Inverts(kind="dependency-inversion"):+> templating;
    agents +>:Inverts(kind="dependency-inversion"):+> viz_hooks;
    viz +>:Inverts(kind="dependency-inversion"):+> viz_hooks;

    templating +>:Provides(symbols="substitute, strip_inactive_conditional_blocks"):+> config;
    templating +>:Provides(symbols="substitute, strip_inactive_conditional_blocks"):+> agents;
    viz_hooks +>:Provides(symbols="inject_viz_prompt_block"):+> agents;
    viz_hooks +>:Provides(symbols="inject_viz_prompt_block"):+> viz;

    auditor = CycleBreaker();
    print("=== Before refactor ===");
    print(f"  config lazy imports: {config.lazy_imports}");
    print(f"  agents lazy imports: {agents.lazy_imports}");
    print(f"  viz lazy imports:    {viz.lazy_imports}");
    print("");

    print("=== Walker: CycleBreaker ===");
    root spawn auditor;

    print("");
    print("=== After refactor ===");
    print(f"  extracted leaf modules: {auditor.extracted}");
    print(f"  DAG restored:           {auditor.resolved}");
    print(f"  cycle broken:           yes (templating + viz_hooks as leaves)");
}
