"""Data center clearance: technicians walk a corridor of server rooms and are
admitted or denied by each room based on their clearance level. A denied
technician ends their walk immediately — they never reach deeper rooms.
We report how many rooms each technician successfully reached."""

node ServerRoom {
    has room_name: str = "";
    has required_clearance: int = 0;
}

walker Technician {
    has technician_name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach with ServerRoom entry {
        if self.clearance >= here.required_clearance {
            self.rooms_reached += 1;
            print(f"{self.technician_name} admitted to {here.room_name} "
                  f"(needs {here.required_clearance}, has {self.clearance})");
            visit [-->];
        } else {
            print(f"{self.technician_name} DENIED at {here.room_name} "
                  f"(needs {here.required_clearance}, has {self.clearance})");
            disengage;
        }
    }
}

with entry {
    room1 = ServerRoom(room_name="Lobby Cage", required_clearance=1);
    room2 = ServerRoom(room_name="Storage Array", required_clearance=2);
    room3 = ServerRoom(room_name="Core Rack", required_clearance=3);
    room4 = ServerRoom(room_name="Cold Aisle", required_clearance=4);

    root ++> room1 ++> room2 ++> room3 ++> room4;

    junior = Technician(technician_name="Alice (L2)", clearance=2);
    root spawn junior;
    print(f"-> {junior.technician_name} reached {junior.rooms_reached} rooms");

    senior = Technician(technician_name="Bob (L5)", clearance=5);
    root spawn senior;
    print(f"-> {senior.technician_name} reached {senior.rooms_reached} rooms");

    intern = Technician(technician_name="Carol (L1)", clearance=1);
    root spawn intern;
    print(f"-> {intern.technician_name} reached {intern.rooms_reached} rooms");
}
