"""Flight network: legs store ticket prices; a scout walker reports peak fare for normalization."""

node Airport {
    has title: str = "";
    has code: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(top_fare: float) -> float {
        if top_fare <= 0.0 {
            return 0.0;
        }
        return self.price / top_fare;
    }
}

walker Scout {
    has reports: list[float] = [];
    has seen_codes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can map with Airport entry {
        if here.code in self.seen_codes {
            disengage;
        }
        self.seen_codes.append(here.code);
        for leg in [edge ->:FlightLeg:->] {
            report leg.price;
            self.reports.append(leg.price);
        }
        visit [-->];
    }
}

with entry {
    sfo = Airport(code="SFO", title="San Francisco");
    lax = Airport(code="LAX", title="Los Angeles");
    den = Airport(code="DEN", title="Denver");
    jfk = Airport(code="JFK", title="New York");

    sfo +>: (leg_sl := FlightLeg(price=320.0)):+> lax;
    lax +>: (leg_ld := FlightLeg(price=180.0)):+> den;
    den +>: (leg_dj := FlightLeg(price=410.0)):+> jfk;
    jfk +>: (leg_js := FlightLeg(price=290.0)):+> sfo;

    all_legs = [leg_sl, leg_ld, leg_dj, leg_js];

    root ++> sfo;

    scout = root spawn Scout();
    top = max(scout.reports) if scout.reports else 0.0;

    print(f"Scout collected {len(scout.reports)} fares; peak ticket is ${top}");
    for leg in all_legs {
        fraction = leg.fare_fraction(top);
        print(f"${leg.price} leg costs {fraction:.2f} of peak fare");
    }
}
