```jac
"""Fleet MDM Windows profile failure surfacing + dismiss demo.

Models the host -> Windows profiles graph and the failed-remove rows
that admins need to (1) see on the OS settings tab and (2) dismiss
once they have investigated. The walker traverses failed-removal rows
along a typed Removes edge, marks them dismissed, and prunes the
edges (cascade cleanup) — exactly the operation the Fleet issue
#50525 is asking for.
"""

node Host {
    has hostname: str = "";
}

node WindowsProfile {
    has profile_id: str = "";
    has name: str = "";
    has operation_type: str = "remove";
}

node FailedRemoval {
    has detail: str = "";
    has status: str = "failed";
    has dismissed: bool = False;
}

edge OwnsProfile {}

edge Removes {
    has attempted_at: str = "";
}

walker SurfaceFailed {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with Host entry {
        visit [->:OwnsProfile:->];
    }

    can find_failures with WindowsProfile entry {
        visit [->:Removes:->];
    }

    can collect with FailedRemoval entry {
        if not here.dismissed {
            line = f"[FAILED] {here.detail} | status={here.status}";
            self.findings.append(line);
        }
        visit [-->];
    }
}

walker DismissFailed {
    has target_detail: str = "";
    has cleared: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk_host with Host entry {
        visit [->:OwnsProfile:->];
    }

    can walk_profile with WindowsProfile entry {
        visit [->:Removes:->];
    }

    can dismiss with FailedRemoval entry {
        if not here.dismissed and (self.target_detail == "" or here.detail == self.target_detail) {
            here.dismissed = True;
            self.cleared += 1;
        }
        visit [-->];
    }
}

with entry {
    # Two hosts, each with profiles; the second profile on host-b
    # has a failed-remove row that the admin needs to surface + clear.
    host_a = Host(hostname="finance-laptop-01");
    host_b = Host(hostname="eng-laptop-07");

    prof_a1 = WindowsProfile(profile_id="win-cfg-001", name="BitLocker Policy");
    prof_b1 = WindowsProfile(profile_id="win-cfg-042", name="Wifi Enterprise");
    prof_b2 = WindowsProfile(profile_id="win-cfg-077", name="Defender Exclusions");

    root +>:OwnsProfile:+> host_a;
    host_a +>:OwnsProfile:+> prof_a1;

    root +>:OwnsProfile:+> host_b;
    host_b +>:OwnsProfile:+> prof_b1;
    host_b +>:OwnsProfile:+> prof_b2;

    failure_b1 = FailedRemoval(detail="Failed to remove: timeout from MDM channel", status="failed");
    failure_b2 = FailedRemoval(detail="Failed to remove: access denied (0x80070005)", status="failed");
    prof_b1 +>:Removes(attempted_at="2025-03-14T10:22:00Z"):+> failure_b1;
    prof_b2 +>:Removes(attempted_at="2025-03-15T08:05:00Z"):+> failure_b2;

    # 1. Surface every failed-remove row across the fleet.
    surface = root spawn SurfaceFailed();
    print("=== Failed removals surfaced ===");
    for line in surface.findings {
        print(line);
    }
    print(f"total visible failures: {len(surface.findings)}");

    # 2. Admin dismisses the access-denied failure after investigating.
    clearer = DismissFailed(target_detail="Failed to remove: access denied (0x80070005)");
    root spawn clearer;
    print(f"=== Dismissed {clearer.cleared} failure(s) ===");

    # 3. Re-survey: dismissed rows must no longer appear.
    resurface = root spawn SurfaceFailed();
    print("=== Remaining failures after dismiss ===");
    for line in resurface.findings {
        print(line);
    }
    print(f"total visible failures: {len(resurface.findings)}");
}
