    h +>:OwnsProfile:+> p2;

    f1 = FailedRemoval(detail="Failed to remove: timeout from MDM channel", status="failed");
    f2 = FailedRemoval(detail="Failed to remove: access denied (0x80070005)", status="failed");
    f3 = FailedRemoval(detail="Failed to remove: bad signature", status="failed", dismissed=True);
