    assert f1.dismissed, "f1 should be dismissed";
    assert f2.dismissed, "f2 should be dismissed";
    assert f3.dismissed, "f3 was already dismissed; must stay dismissed";

    resurface = r spawn SurfaceFailed();
    assert len(resurface.findings) == 0, f"expected 0 remaining failures, got {resurface.findings}";
