"""Checkout: dispatch by product kind and print an itemized receipt."""

node Product {
    has name: str = "";
    has price: float = 0.0;
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;

    def shipping_cost() -> float {
        return 2.50 + 1.50 * self.weight_lb;
    }

    def handling_fee() -> float {
        return 0.50;
    }

    def kind_label() -> str {
        return "Paper Book";
    }
}

node DigitalBook(Product) {
    has file_size_mb: float = 10.0;

    def shipping_cost() -> float {
        return 0.00;
    }

    def handling_fee() -> float {
        return 0.25;
    }

    def kind_label() -> str {
        return "Digital Book";
    }
}

node Electronics(Product) {
    has warranty_months: int = 12;

    def shipping_cost() -> float {
        return 9.99;
    }

    def handling_fee() -> float {
        return 1.00 + 0.10 * self.warranty_months;
    }

    def kind_label() -> str {
        return f"Electronics ({self.warranty_months}mo warranty)";
    }
}

node Clothing(Product) {
    has size: str = "M";

    def shipping_cost() -> float {
        return 4.99;
    }

    def handling_fee() -> float {
        return 0.75;
    }

    def kind_label() -> str {
        return f"Clothing (size {self.size})";
    }
}

walker Cashier {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has handling: float = 0.0;
    has lines: list = [];

    can start with Root entry {
        print("=== CHECKOUT RECEIPT ===");
        visit [-->];
    }

    can ring with PaperBook | DigitalBook | Electronics | Clothing entry {
        label = here.kind_label();
        ship = here.shipping_cost();
        hand = here.handling_fee();
        line_total = here.price + ship + hand;

        self.lines.append({
            "label": label,
            "name": here.name,
            "price": here.price,
            "ship": ship,
            "hand": hand,
            "line_total": line_total,
        });

        self.subtotal += here.price;
        self.shipping += ship;
        self.handling += hand;

        print(
            f"  {label}: {here.name} "
            f"${here.price:.2f} + ship ${ship:.2f} + handling ${hand:.2f}"
        );

        visit [-->];
    }
}

with entry {
    root ++> PaperBook(name="The Hobbit", price=14.99, weight_lb=1.2)
        ++> DigitalBook(name="Lambda Calculus Primer", price=9.99, file_size_mb=4.5)
        ++> Electronics(name="Bluetooth Earbuds", price=59.99, warranty_months=24)
        ++> Clothing(name="Cotton Tee", price=19.99, size="L");

    cashier = Cashier();
    root spawn cashier;

    grand = cashier.subtotal + cashier.shipping + cashier.handling;
    print("---");
    print(f"Subtotal:  ${cashier.subtotal:.2f}");
    print(f"Shipping:  ${cashier.shipping:.2f}");
    print(f"Handling:  ${cashier.handling:.2f}");
    print(f"TOTAL:     ${grand:.2f}");
}
