test "electronics handling grows with warranty months and shipping is flat" {
    e = Electronics(name="Laptop", price=999.99, warranty_months=36);

    assert e.shipping_cost() == 9.99, f"electronics ship: {e.shipping_cost()}";
    expected_hand = 1.00 + 0.10 * 36;  # 4.60
    assert e.handling_fee() == expected_hand, f"hand {e.handling_fee()} vs {expected_hand}";
    assert e.kind_label() == "Electronics (36mo warranty)", f"label: {e.kind_label()}";
