test "cashier accumulates subtotal, shipping, handling and prints totals" {
    root ++> PaperBook(name="The Hobbit", price=14.99, weight_lb=1.2);
    root ++> DigitalBook(name="Lambda Primer", price=9.99, file_size_mb=4.5);
    root ++> Electronics(name="Earbuds", price=59.99, warranty_months=24);
    root ++> Clothing(name="Tee", price=19.99, size="L");

    cashier = Cashier();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn cashier;
        grand = cashier.subtotal + cashier.shipping + cashier.handling;
        print("---");
        print(f"Subtotal:  ${cashier.subtotal:.2f}");
        print(f"Shipping:  ${cashier.shipping:.2f}");
        print(f"Handling:  ${cashier.handling:.2f}");
        print(f"TOTAL:     ${grand:.2f}");
    }
    out = buf.getvalue();

    # Sum of all item prices
    expected_subtotal = 14.99 + 9.99 + 59.99 + 19.99;  # 104.96
    assert abs(cashier.subtotal - expected_subtotal) < 1e-6, f"subtotal {cashier.subtotal} vs {expected_subtotal}";

    # PaperBook: 2.50 + 1.50*1.2 = 4.30; Digital: 0.00;
    # Electronics: 9.99; Clothing: 4.99 => 19.28
    expected_shipping = (2.50 + 1.50 * 1.2) + 0.00 + 9.99 + 4.99;
    assert abs(cashier.shipping - expected_shipping) < 1e-6, f"ship {cashier.shipping} vs {expected_shipping}";

    # PaperBook: 0.50; Digital: 0.25;
    # Electronics: 1.00 + 0.10*24 = 3.40; Clothing: 0.75 => 4.90
    expected_handling = 0.50 + 0.25 + (1.00 + 0.10 * 24) + 0.75;
    assert abs(cashier.handling - expected_handling) < 1e-6, f"hand {cashier.handling} vs {expected_handling}";

    expected_total = expected_subtotal + expected_shipping + expected_handling;
    assert abs((cashier.subtotal + cashier.shipping + cashier.handling) - expected_total) < 1e-6, "total mismatch";

    assert f"Subtotal:  ${expected_subtotal:.2f}" in out, f"subtotal line missing: {out}";
    assert f"Shipping:  ${expected_shipping:.2f}" in out, f"shipping line missing: {out}";
    assert f"Handling:  ${expected_handling:.2f}" in out, f"handling line missing: {out}";
    assert f"TOTAL:     ${expected_total:.2f}" in out, f"total line missing: {out}";
    assert len(cashier.lines) == 4, f"expected 4 receipt lines, got {len(cashier.lines)}";
}

