Models the CAMPFIRE scenario where runtime identity is episodic (walker lineage
!= remembered experience), and the handoff from a bounded HEAD into a fresh
aperture must be visible, falsifiable, and rotated before the lane becomes
expensive to enter. The walker below traverses the HEAD chain exactly once
(cycle policy: visited-set) and records per-segment observation deltas on
its own ledger; the HEAD retains only pointers, never the predecessor's
whole body.
"""

# ---------- nodes (entity archetypes) ----------

node Kernel {
    has name: str = "";
    has baseline: str = "v0.2.7";
}

node Head {
    has label: str = "";
    has bounded_size: int = 0;
    has material_delta: str = "";
}

node Omission {
    has what: str = "";
    has reason: str = "";
}

node Ledger {
    has name: str = "";
}

node FutureBuild {
    has label: str = "";
    has is_derived: bool = True;
}

# ---------- edges (relationships carry meaning) ----------

edge PointsTo { }
edge Omits    { }
edge Records  { }
edge Probes   { }

# ---------- walker: episodic CC traversal ----------

walker CC {
    has lane_label: str = "CAMPFIRE";
    has ledger: list[str] = [];
    has seen: list[str] = [];

    def already_visited(label: str) -> bool {
        for prior in self.seen {
            if prior == label {
                return True;
            }
        }
        return False;
    }

    def visited_count() -> int {
        return len(self.seen);
    }

    can start with Root entry {
        print(f"[CC:{self.lane_label}] episodic runtime spawned — no remembered experience");
        visit [->:PointsTo:->];
    }

    can audit with Head entry {
        if self.already_visited(here.label) {
            print(f"[CC] cycle detected at HEAD={here.label} — disengage");
            disengage;
        }
        self.seen.append(here.label);

        self.ledger.append(
            f"HEAD={here.label} aperture={here.bounded_size}t delta={here.material_delta or '<none>'}"
        );
        print(f"[CC] observed {self.ledger[-1]}");
        visit [->:PointsTo:->];
    }

    can finalize with Root entry {
        print(f"[CC] ledger entries: {len(self.ledger)}");
        for item in self.ledger {
            print(f"  - {item}");
        }
    }

    can om_audit with Omission entry {
        print(f"[CC] omission noted: {here.what} ({here.reason})");
    }

    def probe_future(fb: FutureBuild) -> None {
        kind = "derived" if fb.is_derived else "primitive";
        print(f"[CC] future-build={fb.label} kind={kind} — adversarial probe required");
    }
}

# ---------- walker: rotation probe (aperture-stays-small check) ----------

walker RotationProbe {
    has threshold: int = 3;
    has counted: int = 0;

    can start with Root entry {
        print("[RotationProbe] checking that bounded HEAD chain stays small");
        visit [->:PointsTo:->];
    }

    can measure with Head entry {
        self.counted += 1;
        if self.counted >= self.threshold {
            print("[RotationProbe] lane is becoming expensive to enter — rotate");
            disengage;
        }
        print(f"[RotationProbe] HEAD={here.label} size={here.bounded_size}t");
        visit [->:PointsTo:->];
    }
}

# ---------- demo wiring ----------

with entry {
    kernel = Kernel(name="TRACE", baseline="v0.2.7");

    head1 = Head(label="H1", bounded_size=800, material_delta="+scene-pair added");
    head2 = Head(label="H2", bounded_size=900, material_delta="none");
    head3 = Head(label="H3", bounded_size=1100, material_delta="future-build pointer");

    kernel +>:PointsTo:+> head1;
    head1 +>:PointsTo:+> head2;
    head2 +>:PointsTo:+> head3;

    kernel +>:Omits:+> Omission(what="COM#36 whole-body", reason="targeted connector reads only");
    kernel +>:Omits:+> Omission(what="predecessor thread end-to-end", reason="barrier persists");

    kernel +>:Records:+> Ledger(name="external-ledger-A");

    kernel +>:Probes:+> FutureBuild(label="FUTURE_BUILD_v0_1", is_derived=True);

    print("=== CC episodic traversal ===");
    cc_walker = CC(lane_label="CAMPFIRE/bounded-FW-CC");
    root spawn cc_walker;

    print("=== rotation probe (cycle policy: depth cap, not visited-set) ===");
    root spawn RotationProbe(threshold=3);
}
```

import io;
import from contextlib { redirect_stdout }

test "CC records each HEAD once and detects cycles" {
    h1 = Head(label="H1", bounded_size=800, material_delta="+scene-pair added");
    h2 = Head(label="H2", bounded_size=900, material_delta="none");
    h3 = Head(label="H3", bounded_size=1100, material_delta="future-build pointer");

    root +>:PointsTo:+> h1;
    h1 +>:PointsTo:+> h2;
    h2 +>:PointsTo:+> h3;
    h3 +>:PointsTo:+> h1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CC(lane_label="CAMPFIRE/bounded-FW-CC");
    }
    out = buf.getvalue();

    assert len(res.seen) == 3, f"got seen={res.seen}";
    assert len(res.ledger) == 3, f"got ledger={res.ledger}";
    assert res.ledger[0] == "HEAD=H1 aperture=800t delta=+scene-pair added", f"got {res.ledger[0]}";
    assert "cycle detected at HEAD=H1" in out, f"missing cycle marker: {out}";
}

test "RotationProbe disengages at the bounded threshold" {
    h1 = Head(label="H1", bounded_size=800);
    h2 = Head(label="H2", bounded_size=900);
    h3 = Head(label="H3", bounded_size=1100);
    h4 = Head(label="H4", bounded_size=1200);

    root +>:PointsTo:+> h1;
    h1 +>:PointsTo:+> h2;
    h2 +>:PointsTo:+> h3;
    h3 +>:PointsTo:+> h4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RotationProbe(threshold=3);
    }
    out = buf.getvalue();

    assert res.counted == 3, f"got counted={res.counted}";
    assert "lane is becoming expensive to enter — rotate" in out, f"missing rotation marker: {out}";
    assert "HEAD=H4" not in out, f"walk continued past threshold: {out}";
}

test "Continuity links preserve omission and future-build meaning" {
    kernel = Kernel(name="TRACE", baseline="v0.2.7");
    root ++> kernel;

    om1 = Omission(
        what="COM#36 whole-body",
        reason="targeted connector reads only"
    );
    om2 = Omission(
        what="predecessor thread end-to-end",
        reason="barrier persists"
    );
    ledger = Ledger(name="external-ledger-A");
    future = FutureBuild(label="FUTURE_BUILD_v0_1", is_derived=True);

    kernel +>:Omits:+> om1;
    kernel +>:Omits:+> om2;
    kernel +>:Records:+> ledger;
    kernel +>:Probes:+> future;

    root_children = [root-->];
    omission_edges = [kernel ->:Omits:->];
    record_edges = [kernel ->:Records:->];
    probe_edges = [kernel ->:Probes:->];

    assert len(root_children) == 1, f"got root children={len(root_children)}";
    assert kernel in root_children, f"kernel is not rooted";
    assert len(omission_edges) == 2, f"got omissions={len(omission_edges)}";
    assert om1 in omission_edges, f"missing first omission";
    assert om2 in omission_edges, f"missing second omission";
    assert ledger in record_edges, f"missing ledger link";
    assert future in probe_edges, f"missing future probe link";
    assert future.is_derived, f"got is_derived={future.is_derived}";
}

