}

test "sweep reports correct min and max temperatures" {
    root ++> Station(location="Alpha", celsius=-3.0)
        ++> Station(location="Beta", celsius=0.0)
        ++> Station(location="Gamma", celsius=42.0)
        ++> Station(location="Delta", celsius=15.5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
        lo = min(sweep.readings);
        hi = max(sweep.readings);
        print(f"Min temperature: {lo}°C");
        print(f"Max temperature: {hi}°C");
    }
    out = buf.getvalue();

    assert lo == -3.0, f"expected min -3.0, got {lo}";
    assert hi == 42.0, f"expected max 42.0, got {hi}";
    assert "Min temperature: -3.0°C" in out, f"missing min line: {out}";
    assert "Max temperature: 42.0°C" in out, f"missing max line: {out}";
}

test "walker does not stop at any station" {
    # The sweep must visit ALL stations — its `visit [-->] else { disengage; }`
    # on Root entry is the only place disengage should fire (when no stations
    # exist). With four stations attached, the walker should not disengage early.
    root ++> Station(location="X", celsius=1.0)
        ++> Station(location="Y", celsius=2.0)
        ++> Station(location="Z", celsius=3.0);

    sweep = WeatherSweep();
    root spawn sweep;

    assert len(sweep.readings) == 3, f"walker stopped early; got {len(sweep.readings)} readings";
    assert sweep.readings == [1.0, 2.0, 3.0], f"unexpected readings: {sweep.readings}";
}

test "sweep on empty graph prints banner and no station lines" {
    # With no stations, Root entry's `visit [-->] else { disengage; }` fires
    # disengage immediately. No station reports should appear, readings stays
    # empty, and min/max would be undefined.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
    }
    out = buf.getvalue();

    assert "Weather sweep beginning..." in out, f"banner missing on empty graph: {out}";
    assert "Station" not in out, f"unexpected station line on empty graph: {out}";
    assert len(sweep.readings) == 0, f"expected 0 readings, got {len(sweep.readings)}";
}

test "single station sweep records exactly one reading" {
    root ++> Station(location="Solo", celsius=7.25);

    sweep = WeatherSweep();
    root spawn sweep;

    assert len(sweep.readings) == 1, f"expected 1 reading, got {len(sweep.readings)}";
    assert sweep.readings[0] == 7.25, f"expected 7.25, got {sweep.readings[0]}";
    assert min(sweep.readings) == 7.25, f"min should equal sole reading";
    assert max(sweep.readings) == 7.25, f"max should equal sole reading";
}

