"""M3C orphan-vertex modeling: marching-cubes candidates, triangles, and
compaction that produces unreferenced (orphan) output vertices.

Mirrors the issue's two approaches (marking vs. compaction) as two walkers
that traverse the candidate->triangle relationship and report whether
each candidate is referenced by any triangle.
"""

# A candidate node generated by the marching-cubes sweep near the
# volume boundary. `node_type > 0` is what marks it as surviving compaction.
node Candidate {
    has label: str = "";
    has node_type: int = 0;
    has referenced: bool = False;
}

# A triangle node that fans out to the three candidates it references.
# The reference signal lives on the typed edge from triangle -> candidate.
node Triangle {
    has label: str = "";
}

# Typed edge: a triangle references a candidate at a given slot index.
edge Uses {
    has slot: int = 0;
}

# Compacted output vertex: produced from a Candidate whose node_type > 0.
# This is the artifact whose count the issue complains about.
node OutputVertex {
    has label: str = "";
}

# Typed edge linking an output vertex back to the candidate it came from.
edge EmittedFrom {}

# Approach 1: re-check every kept candidate by walking its candidate
# neighbors. A candidate with no outgoing Uses edges AND node_type > 0 is
# the orphan class the issue describes.
walker MarkingAudit {
    has orphan_labels: list[str] = [];
    has kept_count: int = 0;
    has unreferenced_kept: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Candidate entry {
        if here.node_type > 0 {
            self.kept_count += 1;
            if not here.referenced {
                self.unreferenced_kept += 1;
                self.orphan_labels.append(here.label);
            }
        }
        visit [-->];
    }
}

# Approach 2: simulate the "drop orphans at compaction" fix. It walks the
# candidate chain and only emits OutputVertex nodes for candidates that
# are both kept AND referenced, mirroring the suggested post-fix pipeline.
walker CompactionAudit {
    has emitted: list[str] = [];
    has skipped_orphans: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can compact with Candidate entry {
        if here.node_type > 0 and here.referenced {
            self.emitted.append(here.label);
        } elif here.node_type > 0 {
            self.skipped_orphans.append(here.label);
        }
        visit [-->];
    }
}

with entry {
    # 4 candidates on a candidate chain hanging off root.
    c1 = Candidate(label="c1", node_type=2, referenced=True);
    c2 = Candidate(label="c2", node_type=3, referenced=True);
    c3 = Candidate(label="c3", node_type=4, referenced=False);
    c4 = Candidate(label="c4", node_type=0, referenced=False);

    root ++> c1 ++> c2 ++> c3 ++> c4;

    # Two triangles fan out to c1 and c2 via typed Uses edges.
    t1 = Triangle(label="t1");
    t2 = Triangle(label="t2");
    root ++> t1 +>:Uses(slot=0):+> c1;
    root ++> t1 +>:Uses(slot=1):+> c2;
    root ++> t2 +>:Uses(slot=0):+> c1;
    root ++> t2 +>:Uses(slot=2):+> c2;

    # Approach 1: report the orphan count under today's marking.
    a1 = MarkingAudit();
    root spawn a1;
    print(f"approach1 kept={a1.kept_count} "
          f"orphan_kept={a1.unreferenced_kept} "
          f"labels={a1.orphan_labels}");

    # Approach 2: simulate the compaction fix and show what the output
    # vertex list would look like with orphans dropped.
    a2 = CompactionAudit();
    root spawn a2;
    print(f"approach2 emitted={a2.emitted} "
          f"dropped_orphans={a2.skipped_orphans}");

    # Materialize the post-fix OutputVertex nodes to show the walker-driven
    # graph rewrite the issue recommends in option 2.
    for label in a2.emitted {
        root ++> OutputVertex(label=label);
    }
    print("post-fix: only referenced+kept candidates became OutputVertex nodes");
}
