"""Tests for CAM recompute cascade model."""

import io;
import from contextlib { redirect_stdout }

test "cascade recomputes dirty ops and skips clean ops" {
    doc = Document(name="Doc1");
    job = Job(label="J1");
    tc = ToolController(label="TC");
    op_clean = Operation(label="CleanOp", last_exec_ms=500);
    op_dirty = Operation(label="DirtyOp", last_exec_ms=300);

    doc +>:Owns:+> job;
    job +>:Owns:+> tc;
    tc +>:Owns:+> op_clean;
    tc +>:Owns:+> op_dirty;
    op_dirty.dirty = True;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = doc spawn RecomputeCascade();
    }
    out = buf.getvalue();

    assert "DirtyOp" in out, f"dirty op should be reported: {out}";
    assert "CleanOp" in out, f"clean op should still be visited: {out}";
    assert res.recomputed_count >= 1, (
        f"dirty op must increment recomputed_count, got {res.recomputed_count}"
    );
    assert res.skipped_count >= 1, (
        f"clean op must increment skipped_count, got {res.skipped_count}"
    );
    assert op_dirty.dirty == False, "dirty flag must be cleared after recompute";
    assert op_clean.dirty == False, "clean op untouched";
}

test "cascade disengages when global recompute disabled" {
    doc = Document(name="Doc2", global_recompute=False);
    job = Job(label="J2");
    op = Operation(label="OpX", last_exec_ms=200);

    doc +>:Owns:+> job;
    job +>:Owns:+> op;
    op.dirty = True;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = doc spawn RecomputeCascade();
    }
    out = buf.getvalue();

    assert "skip-doc" in out, f"doc disable must emit skip-doc: {out}";
    assert "OpX" not in out, (
        f"op must not be touched when doc disabled: {out}"
    );
    assert res.recomputed_count == 0, (
        f"nothing recomputed when doc disabled, got {res.recomputed_count}"
    );
}

test "budgeted recompute cancels when cumulative exceeds budget" {
    doc = Document(name="Doc3");
    job = Job(label="J3");
    tc = ToolController(label="TC3");
    op1 = Operation(label="CheapOp", last_exec_ms=400);
    op2 = Operation(label="PriceyOp", last_exec_ms=2500);
    op3 = Operation(label="LaterOp", last_exec_ms=900);

    doc +>:Owns:+> job;
    job +>:Owns:+> tc;
    tc +>:Owns:+> op1;
    tc +>:Owns:+> op2;
    tc +>:Owns:+> op3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = doc spawn BudgetedRecompute(budget_ms=1000);
    }
    out = buf.getvalue();

    assert res.cancelled == True, "expensive op must trigger cancellation";
    assert res.cancelled == True, f"got cancelled={res.cancelled}";
    assert "CANCEL" in out, f"cancel marker missing: {out}";
    assert "PriceyOp" in res.expensive_ops, (
        f"PriceyOp should be recorded as expensive: {res.expensive_ops}"
