"""Behavior Impact Graph demo with provenance-backed traversal and skip auditing."""

node Change {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has risk: str = "normal";
}

node Component {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has provenance: str = "";
}

node Contract {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has critical: bool = False;
    has selected: bool = False;
    has selection_reason: str = "";
    has skip_reason: str = "";
    has evidence: str = "";
}

edge GraphItem { }

edge Catalog { }

edge Impact {
    has provenance: str = "";
    has confidence: float = 1.0;
}

walker ImpactSelector {
    has seen_keys: list[str] = [];
    has path: str = "";

    can start with Root entry {
        print("starting impact traversal");
        visit [->:GraphItem:->] else {
            disengage;
        }
    }

    can inspect with Change | Component entry {
        if here.key in self.seen_keys {
            print(f"cycle guard stopped at {here.title}");
            disengage;
        }

        self.seen_keys.append(here.key);
        self.path = f"{self.path} -> {here.title}";
        print(f"impact path: {self.path}");

        visit [->:Impact:->] else {
            disengage;
        }
    }

    can select with Contract entry {
        if here.key in self.seen_keys {
            disengage;
        }

        self.seen_keys.append(here.key);
        here.selected = True;
        here.selection_reason = f"reachable through {self.path}";
        here.evidence = "typed impact edge with provenance";
        print(f"selected {here.title}: {here.selection_reason}");
    }
}

walker OmissionAuditor {
    can start with Root entry {
        visit [->:Catalog:->] else {
            disengage;
        }
    }

    can audit with Contract entry {
