```jac
"""GHCR reachability-based cleanup: only prune versions unreferenced by any tag.

Models the issue's core constraint: deletion safety is about reachability,
not untaggedness. Multi-arch packages publish a tagged manifest list whose
child manifests are themselves untagged but live. We must keep every
digest reachable from a tag (including platform children) and delete only
those that nothing points to.
"""

node Version {
    has digest: str = "";
    has age_days: int = 0;
    has untagged: bool = True;
    has platform: str = "";
}

node Tag {
    has tag_name: str = "";
}

node ManifestList {
    has media_type: str = "application/vnd.oci.image.index.v1+json";
}

edge TagPointsTo { }      # Tag --> ManifestList
edge ListIncludes { has platform: str = ""; }   # ManifestList --> Version (child descriptor)
edge Reference { }        # Version --> Version (generic reference edge, e.g. cross-manifest)

walker ReachabilityAudit {
    has keep: list[str] = [];
    has cutoff_days: int = 7;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:TagPointsTo:->];
    }

    can walk_tag with Tag entry {
        print(f"[tag] {here.tag_name}");
        visit [->:TagPointsTo:->];
    }

    can walk_list with ManifestList entry {
        visit [->:ListIncludes:->];
    }

    can collect with Version entry {
        # Cycle guard: walkers have no built-in dedup, so track visited digests.
        already = False;
        for d in self.seen {
            if d == here.digest {
                already = True;
            }
        }
        if not already {
            self.seen.append(here.digest);
            self.keep.append(here.digest);
        }
        visit [->:Reference:->];
    }
}

walker UnreferencedPrune {
    has cutoff_days: int = 7;
    has allowlist: list[str] = ["jamovi-ubi9"];
    has keep_digests: list[str] = [];

    can start with Root entry {
        # Two-phase: audit first to learn what to keep, then prune.
        a = ReachabilityAudit(cutoff_days=self.cutoff_days);
        root spawn a;
        self.keep_digests = a.keep;
        print(f"audit retained {len(self.keep_digests)} reachable digests");
        visit [-->] else { disengage; }
    }

    can sweep with Version entry {
        # Least-privilege style gate: only consider packages in the allowlist
        # (modeled here by platform = "amd64"/"arm64" as the package proxy).
        in_allowlist = False;
        for p in self.allowlist {
            if p == here.platform or p == "all" {
                in_allowlist = True;
            }
        }
        if not in_allowlist {
            return;
        }
        # Minimum-age threshold for untagged deletion.
        if here.age_days < self.cutoff_days {
            return;
        }
        # Skip digests retained by the reachability audit.
        retained = False;
        for d in self.keep_digests {
            if d == here.digest {
                retained = True;
            }
        }
        if retained {
            print(f"  keep   {here.digest} (reachable, platform={here.platform})");
        } else {
            print(f"  DELETE {here.digest} (untagged, age={here.age_days}d, "
                  f"unreferenced by any tag)");
            del here;
        }
    }
}

with entry {
    # Wire the demo graph for the jamovi-ubi9 multi-arch scenario.
    amd_child = Version(digest="sha-amd",  age_days=30, untagged=True, platform="amd64");
    arm_child = Version(digest="sha-arm",  age_days=30, untagged=True, platform="arm64");
    orphan   = Version(digest="sha-old",  age_days=40, untagged=True, platform="amd64");
    fresh    = Version(digest="sha-new",  age_days=1,  untagged=True, platform="amd64");

    index = ManifestList();
    root +>:TagPointsTo:+> Tag(tag_name="latest");
    root +>:TagPointsTo:+> Tag(tag_name="1.2.3");
    # Connect tags to the manifest list.
    n_tags = [root -->];
    # Build the list and its child descriptors explicitly.
    list_node = ManifestList();
    root ++> list_node;
    list_node +>:ListIncludes(platform="linux/amd64"):+> amd_child;
    list_node +>:ListIncludes(platform="linux/arm64"):+> arm_child;
    # Orphans hang off root with no incoming reference.
    root ++> orphan;
    root ++> fresh;

    root spawn UnreferencedPrune(cutoff_days=7);
}
