    can sign with Guestbook entry {
        stamp = f"{self.name} says: {self.message}";
        here.entries.append(stamp);
        new_entry = Entry(name=self.name, message=self.message, signed_at=stamp);
        here ++> new_entry;
        report {
            "status": "signed",
            "guestbook": here.title,
            "entry": stamp,
            "total": len(here.entries),
        };
