```jac
"""R0 Tag protection: model the acceptance gate and tag-creation policy as a typed graph.

Core scenario: a Release (R0) gate decides whether an acceptance tag may be
created. If the gate is not accepted OR its outcome is not 'continue', the tag
must NOT be created. A walker walks the dependency chain (the recursive
plumbing the issue complains about) and reports the final verdict.
"""

node Task {
    has task_id: str = "";
    has state: str = "ready";
    has required: bool = False;
}

node R0Gate {
    has gate_id: str = "R0";
    has accepted: bool = False;
    has outcome: str = "halt";
}

node AcceptanceTag {
    has tag_name: str = "";
    has created: bool = False;
}

edge Governs { }
edge DependsOn { }
edge Tags { }

walker DependencyAuditor {
    has seen: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [->:Governs:->];
    }

    can audit_gate with R0Gate entry {
        if here.gate_id in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.gate_id);
        if not here.accepted or here.outcome != "continue" {
            self.blocked = True;
            print(f"  [BLOCK] R0 gate {here.gate_id} rejected: "
                  f"accepted={here.accepted}, outcome={here.outcome}");
            visit [-->];
            return;
        }
        print(f"  [PASS]  R0 gate {here.gate_id} cleared");
        visit [->:DependsOn:->];
    }

    can audit_task with Task entry {
        if here.task_id in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.task_id);
        if here.required and here.state != "done" {
            self.blocked = True;
            print(f"  [BLOCK] required task {here.task_id} not done "
                  f"(state={here.state})");
        } else {
            print(f"  [OK]    task {here.task_id} state={here.state}");
        }
        visit [->:DependsOn:->];
    }
}

walker TagEnforcer {
    can start with Root entry {
        gate = [root -->][?:R0Gate];
        tags = [root -->][?:AcceptanceTag];
        if not gate or not tags {
            print("  [ERROR] missing R0Gate or AcceptanceTag in graph");
            disengage;
        }
        g = gate[0];
        t = tags[0];
        auditor = DependencyAuditor();
        g spawn auditor;
        verdict = "ALLOW" if not auditor.blocked else "DENY";
        print(f"\nFinal R0 verdict: {verdict}");
        if verdict == "ALLOW" {
            t.created = True;
            print(f"  -> acceptance tag '{t.tag_name}' CREATED");
        } else {
            print(f"  -> acceptance tag '{t.tag_name}' NOT created "
                  f"(AC-2 enforced)");
        }
        report {"verdict": verdict, "tag": t.tag_name, "created": t.created};
    }
}

with entry {
    print("=== Scenario A: clean path ===");
