"""Weather sweep walker across a chain of weather stations.

Each station carries a location label and a Celsius reading. A walker
traverses the chain of stations, accumulates every reading it visits,
and prints the full sweep along with the min/max once it disengages.
"""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        print("Weather sweep readings (in traversal order):");
        visit [-->];
    }

    can read with Station entry {
        self.readings.append(here.celsius);
        print(f"  {here.location}: {here.celsius} C");
        visit [-->] else {
            lo = min(self.readings);
            hi = max(self.readings);
            print("");
            print(f"All readings: {self.readings}");
            print(f"Min: {lo} C, Max: {hi} C");
            disengage;
        }
    }
}

with entry {
    root ++> Station(location="North Ridge", celsius=18.5)
        ++> Station(location="River Valley", celsius=22.0)
        ++> Station(location="Coastal Pier", celsius=15.25)
        ++> Station(location="Desert Mesa", celsius=33.0)
        ++> Station(location="Mountain Peak", celsius=4.75);

    sweeper = WeatherSweep();
    root spawn sweeper;
}
