```jac
"""IncludeNames tree builder: models JSON:API include path resolution and
the prototype-pollution guard that fixes it.

Entities are nodes (Resources and the IncludePath chain), the path segments
are walked by a typed-edge walker, and unsafe segments (__proto__,
constructor, prototype) are rejected at the traversal boundary. A second
walker compares the unsafe (vulnerable) and safe (patched) behavior.
"""

node Resource {
    has name: str = "";
    has kind: str = "";
    has attrs: dict = {};
}

node IncludeNode {
    has segment: str = "";
    has safe: bool = True;
    has depth: int = 0;
}

# Typed edge: a step inside an include-path chain (segment -> next).
edge SegmentStep { }

# Typed edge: a resource reachable through an include-name.
edge Includes { }

walker PathBuilder {
    has max_depth: int = 8;
    has visited: list = [];
    has blocked: list = [];
    has unsafe_segments: list = ["__proto__", "constructor", "prototype"];

    can start with Root entry {
        print(f"PathBuilder starting (max_depth={self.max_depth})");
        visit [->:SegmentStep:->];
    }

    can step with IncludeNode entry {
        seg = here.segment;
        depth = here.depth;
        here.safe = not (seg in self.unsafe_segments);
        if not here.safe {
            self.blocked.append(seg);
            print(f"  [BLOCKED] segment={seg} depth={depth}");
        } else {
            label = "safe" if here.safe else "unsafe";
            print(f"  [OK] segment={seg} depth={depth} ({label})");
        }
        if depth >= self.max_depth {
            print(f"  [STOP] max_depth reached at segment={seg}");
            disengage;
        }
        visit [->:SegmentStep:->];
    }
}

walker PollutionProbe {
    can start with Root entry {
        print("PollutionProbe: scanning reachable IncludeNodes");
        visit [->:SegmentStep:->];
    }

    can scan with IncludeNode entry {
        seg = here.segment;
        verdict = "REJECTED" if not here.safe else "ACCEPTED";
        print(f"  segment={seg} verdict={verdict} depth={here.depth}");
    }
}

with entry {
    # Build a small include-path chain that contains a dangerous segment.
    n0 = IncludeNode(segment="categories", depth=0);
    n1 = IncludeNode(segment="town", depth=1);
    n2 = IncludeNode(segment="country", depth=2);
    n3 = IncludeNode(segment="__proto__", depth=3);
    n4 = IncludeNode(segment="pp", depth=4);
    n5 = IncludeNode(segment="constructor", depth=5);
    n6 = IncludeNode(segment="prototype", depth=6);

    root +>:SegmentStep:+> n0;
    n0 +>:SegmentStep:+> n1;
    n1 +>:SegmentStep:+> n2;
    n2 +>:SegmentStep:+> n3;
    n3 +>:SegmentStep:+> n4;
    n4 +>:SegmentStep:+> n5;
    n5 +>:SegmentStep:+> n6;

    # A couple of resources reachable through the safe prefix.
    article = Resource(name="stuff", kind="article", attrs={"id": "1", "title": "Hello"});
    categories = Resource(name="categories", kind="relation", attrs={});
    town = Resource(name="town", kind="relation", attrs={});

    root +>:Includes:+> article;
    article +>:Includes:+> categories;
    categories +>:Includes:+> town;

    print("== Building include-name tree (safe mode) ==");
    builder = PathBuilder(max_depth=6);
    root spawn builder;

    print(f"\nblocked segments: {builder.blocked}");
    print(f"all segments accepted? {len(builder.blocked) == 0}");

    print("\n== PollutionProbe: re-walk to confirm rejection ==");
    probe = PollutionProbe();
    root spawn probe;
}
