    root ++> intake;
    intake +>:DependsOn(rationale="brief precedes planning"):+> planning;
    planning +>:DependsOn(rationale="planning precedes implementation"):+> implementation;
    implementation +>:DependsOn(rationale="implementation precedes review"):+> review;
    review +>:DependsOn(rationale="intentional cycle for audit"):+> planning;
    implementation +>:AssignedTo(role="primary implementer"):+> builder;

    root spawn DependencyAuditor();
}
