"""Tests for the polymorphic checkout routine."""

import io;
import from contextlib { redirect_stdout }

test "paper book shipping uses weight formula" {
    root ++> PaperBook(name="Book A", price=10.00, weight_lb=2.0);
    book = [root -->][?:PaperBook][0];
    # 0.99 + 0.75 * 2.0 = 2.49
    assert book.shipping_cost() == 2.49, f"got {book.shipping_cost()}";
    assert book.kind_label() == "PaperBook", f"got {book.kind_label()}";
}

test "digital book shipping is free" {
    root ++> DigitalBook(name="Ebook", price=15.00, drm="drm-free");
    book = [root -->][?:DigitalBook][0];
    assert book.shipping_cost() == 0.0, f"got {book.shipping_cost()}";
    assert book.kind_label() == "DigitalBook", f"got {book.kind_label()}";
}

test "electronics shipping adds fragile surcharge when fragile=True" {
    root ++> Electronics(name="Hub", price=50.00, warranty_months=24, fragile=True);
    frag = [root -->][?:Electronics][0];
    # base 7.50 + 3.25 fragile = 10.75
    assert frag.shipping_cost() == 10.75, f"got {frag.shipping_cost()}";

    root ++> Electronics(name="Cable", price=5.00, warranty_months=12, fragile=False);
    sturdy = [root -->][?:Electronics][1];
    # base 7.50 only
    assert sturdy.shipping_cost() == 7.5, f"got {sturdy.shipping_cost()}";
    assert sturdy.kind_label() == "Electronics", f"got {sturdy.kind_label()}";
}

test "clothing shipping is flat rate" {
    root ++> Clothing(name="Hoodie", price=40.00, size="L");
    shirt = [root -->][?:Clothing][0];
    assert shirt.shipping_cost() == 4.25, f"got {shirt.shipping_cost()}";
    assert shirt.kind_label() == "Clothing", f"got {shirt.kind_label()}";
}

test "checkout prints itemized receipt with correct totals" {
    root ++> Cart(label="Test Cart")
        ++> PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4)
        ++> DigitalBook(name="Refactoring (eBook)", price=24.00, drm="drm-free")
        ++> Electronics(name="USB-C Hub", price=49.99, warranty_months=24, fragile=True)
        ++> Clothing(name="Logo Hoodie", price=55.00, size="L")
        ++> PaperBook(name="Crafting Interpreters", price=32.50, weight_lb=2.1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    # Header
    assert "=== Receipt for Test Cart ===" in out, f"missing header: {out}";

    # Every product line appears, tagged with its concrete kind
    assert "[PaperBook] The Pragmatic Programmer:" in out, f"missing paper1: {out}";
    assert "[DigitalBook] Refactoring (eBook):" in out, f"missing digital: {out}";
    assert "[Electronics] USB-C Hub:" in out, f"missing electronics: {out}";
    assert "[Clothing] Logo Hoodie:" in out, f"missing clothing: {out}";
    assert "[PaperBook] Crafting Interpreters:" in out, f"missing paper2: {out}";

    # Subtotal: 29.95 + 24.00 + 49.99 + 55.00 + 32.50 = 191.44
    # Shipping: paper1=0.99+0.75*1.4=2.04; digital=0.00; elec=10.75;
    #          clothing=4.25; paper2=0.99+0.75*2.1=2.565 -> total 19.605
    assert abs(res.subtotal - 191.44) < 1e-6, f"subtotal got {res.subtotal}";
    assert abs(res.shipping - 19.605) < 1e-6, f"shipping got {res.shipping}";

    # Walker recorded one line per item, in traversal order
    assert len(res.lines) == 5, f"line count got {len(res.lines)}";
    kinds = [l[0] for l in res.lines];
    assert kinds == ["PaperBook", "DigitalBook", "Electronics", "Clothing", "PaperBook"], f"kinds got {kinds}";

    # DigitalBook line total = price only (no shipping)
    digital_line = res.lines[1];
    assert digital_line[2] == 24.00, f"digital price got {digital_line[2]}";
    assert digital_line[3] == 0.0, f"digital ship got {digital_line[3]}";
    assert digital_line[4] == 24.00, f"digital total got {digital_line[4]}";

    # Electronics fragile line: 49.99 + 10.75 = 60.74
    elec_line = res.lines[2];
    assert abs(elec_line[3] - 10.75) < 1e-6, f"elec ship got {elec_line[3]}";
    assert abs(elec_line[4] - 60.74) < 1e-6, f"elec total got {elec_line[4]}";

    # Printed line total for the fragile electronics must include surcharge
    assert "$10.75 ship" in out, f"missing fragile ship in print: {out}";
    assert "$60.74" in out, f"missing elec line total in print: {out}";
}

test "non-fragile electronics print base shipping only" {
    root ++> Cart(label="Simple")
        ++> Electronics(name="Mouse", price=20.00, warranty_months=12, fragile=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    # 7.50 only, no fragile surcharge
    assert abs(res.shipping - 7.5) < 1e-6, f"ship got {res.shipping}";
    assert "$7.50 ship" in out, f"missing base ship: {out}";
    assert "Electronics" in out, f"missing kind tag: {out}";
}

