```jac
"""Audit trail for agent tool calls.

Models the issue: MCP tool calls bypass the audit producer that records
``tool.action.started`` and ``tool.action.finished``, so they never appear
in the ledger even though they execute correctly.

The demo builds an agent run, registers a built-in tool and an MCP tool,
runs both through a single walker, and then an auditor walker checks the
ledger.  The built-in tool produces two audit records; the MCP tool
produces zero -- mirroring the actual bug.
"""

node Tool {
    has name: str = "";
    has kind: str = "";       # "builtin" or "mcp"
    has result: str = "";
    has audited: bool = False;
}

edge Catalog { }              # Tool is in the agent's tool catalog
edge Calls {                  # Agent run invokes a tool
    has run_id: str = "";
}

walker Agent {
    has run_id: str = "";
    has tool_calls: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can execute_tool with Tool entry {
        self.tool_calls.append(here.name);
        # Bug surface: MCP tools skip the audit branch below.
        if here.kind == "builtin" {
            here.audited = True;
        }
        visit [-->];
    }
}

walker Auditor {
    has report: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can inspect with Tool entry {
        key = here.kind + ":" + here.name;
        prior = self.report.get(key, 0);
        self.report[key] = prior + (1 if here.audited else 0);
        visit [-->];
    }
}

with entry {
    # Catalog: one built-in tool and one MCP tool.
    builtin = Tool(name="exec", kind="builtin", result="OK");
    mcp_tool = Tool(name="fixture__echo_constant", kind="mcp",
                    result="AUDIT-FIXTURE-8F3A");
    root ++> builtin ++> mcp_tool;

    # Agent run wires both tools in via the same catalog edge.
    agent = Agent(run_id="repro-mcp");
    root spawn agent;

    # Audit pass: count how many tool actions actually landed.
    auditor = Auditor();
    root spawn auditor;

    # Show the divergence.
    print(f"tool calls executed: {agent.tool_calls}");
    print(f"audit record counts: {auditor.report}");
}
