    root_acct +>:HasChild(created_on="2025-01-01"):+> beta;
    alpha +>:HasChild(created_on="2025-02-01"):+> alpha1;
    beta +>:HasChild(created_on="2025-02-01"):+> beta1;

    judge = Authority(target_id="alpha1");
    alpha spawn judge;
    assert judge.allowed, f"alpha denied its descendant: {judge.reason}";

    judge = Authority(target_id="root");
    alpha spawn judge;
    assert judge.allowed == False, f"alpha reached parent: {judge.reason}";

    judge = Authority(target_id="beta");
    alpha spawn judge;
    assert judge.allowed == False, f"alpha reached sibling: {judge.reason}";

