    root_acct +>:HasChild(created_on="2025-01-01"):+> branch;
    branch +>:HasChild(created_on="2025-02-01"):+> archived;
    archived +>:HasChild(created_on="2025-03-01"):+> hidden;

    judge = Authority(target_id="branch");
    root_acct spawn judge;
    assert judge.allowed, f"root denied active branch: {judge.reason}";

    judge = Authority(target_id="archived");
    root_acct spawn judge;
    assert judge.allowed == False, f"root reached archived account: {judge.reason}";

    judge = Authority(target_id="hidden");
    root_acct spawn judge;
    assert judge.allowed == False, f"root reached account below archive: {judge.reason}";

    judge = Authority(target_id="archived");
    archived spawn judge;
    assert judge.allowed == False, f"archived actor acted as itself: {judge.reason}";
}

