"""Gallery security console.

Every visitor entering a room is logged generically, but a curator
triggers an additional official inspection under the curator's name
and increments the count of rooms they inspected. We run one tourist
and one curator through two rooms and show the difference.
"""

node Room {
    has label: str = "";
    has general_log: list[str] = [];
    has inspections: list[str] = [];
}

# Tourist walker: generic room-logging for anyone who walks in.
walker Tourist {
    has name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can visit_room with Room entry {
        here.general_log.append(f"{self.name} entered {here.label}");
        visit [-->];
    }
}

# Curator walker: also records an official inspection and counts rooms.
walker Curator {
    has name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_room with Room entry {
        here.general_log.append(f"{self.name} entered {here.label}");
        here.inspections.append(f"inspected by {self.name}");
        self.rooms_inspected += 1;
        visit [-->];
    }
}

with entry {
    room_a = Room(label="Gallery A");
    room_b = Room(label="Gallery B");
    root ++> room_a ++> room_b;

    t = Tourist(name="Tourist Tom");
    c = Curator(name="Curator Carla");

    root spawn t;
    root spawn c;

    print("--- Tourist Tom recorded: general_log only (no inspections) ---");

    print("--- Room A general log ---");
    for entry_text in room_a.general_log {
        print(entry_text);
    }

    print("--- Room B general log ---");
    for entry_text in room_b.general_log {
        print(entry_text);
    }

    print("--- Room A inspections ---");
    for entry_text in room_a.inspections {
        print(entry_text);
    }

    print("--- Room B inspections ---");
    for entry_text in room_b.inspections {
        print(entry_text);
    }

    print(f"Curator Carla inspected {c.rooms_inspected} rooms "
          f"(vs Tourist Tom, who inspected 0).");
}
