"""Audit compliance across OpenAI API integration touchpoints.

Models an OpenAI best-practice audit: the maintainer wants to walk every
integration point (API call, config, workflow) and check whether it adheres
to OpenAI guidelines. Some touchpoints are compliant, others are not; a
walker fans out across the dependency graph, performs an audit at each
node, and reports the non-compliant ones with the corrective action.
"""

node TouchPoint {
    has name: str = "";
    has compliant: bool = True;
    has remediation: str = "";

    def is_compliant() -> bool;
    def remediation_for() -> str;
}

edge DependsOn {
    has criticality: str = "normal";
}

node ApiCall(TouchPoint) {
    has model: str = "";
    has temperature: float = 1.0;

    override def is_compliant() -> bool {
        # Best practice: temperature kept at default for chat completions.
        return self.temperature == 1.0;
    }

    override def remediation_for() -> str {
        return f"reset temperature to 1.0 for {self.model}";
    }
}

node ConfigFile(TouchPoint) {
    has max_tokens: int = 0;

    override def is_compliant() -> bool {
        # Best practice: explicit max_tokens cap on every request.
        return self.max_tokens > 0;
    }

    override def remediation_for() -> str {
        return f"set max_tokens cap in {self.name}";
    }
}

node Workflow(TouchPoint) {
    has retries: int = 0;

    override def is_compliant() -> bool {
        # Best practice: bounded retries with exponential backoff.
        return self.retries > 0 and self.retries <= 5;
    }

    override def remediation_for() -> str {
        return f"bound retries (1-5) with exponential backoff in {self.name}";
    }
}

walker ComplianceAuditor {
    has findings: list[str] = [];
    has seen: list[str] = [];

    can begin with Root entry {
        print("Starting OpenAI best-practice audit...");
        visit [->:DependsOn:->];
    }

    can audit with TouchPoint entry {
        if here.name in self.seen {
            visit [->:DependsOn:->] else { disengage; }
        }
        self.seen.append(here.name);
        if here.is_compliant() {
            print(f"  [OK]   {here.name}");
        } else {
            finding = f"  [FAIL] {here.name}: {here.remediation_for()}";
            self.findings.append(finding);
            print(finding);
        }
        visit [->:DependsOn:->];
    }

    def summarize() -> str {
        if self.findings == [] {
            return "All touchpoints compliant.";
        }
        header = f"Audit found {len(self.findings)} non-compliant touchpoint(s):";
        body = "\n".join(self.findings);
        return f"{header}\n{body}";
    }
}

with entry {
    api1 = ApiCall(name="chat_completion", model="gpt-4o", temperature=1.0);
    api2 = ApiCall(name="legacy_call",   model="gpt-3.5", temperature=0.2);
    cfg1 = ConfigFile(name="openai.toml", max_tokens=512);
    cfg2 = ConfigFile(name="defaults.env", max_tokens=0);
    wf1  = Workflow(name="retry_loop",     retries=3);
    wf2  = Workflow(name="infinite_retry", retries=999);

    # Dependency graph: root -> workflows -> configs -> api calls
    root +>:DependsOn(criticality="high"):+> wf1;
    root +>:DependsOn(criticality="high"):+> wf2;
    wf1 +>:DependsOn(criticality="normal"):+> cfg1;
    wf2 +>:DependsOn(criticality="normal"):+> cfg2;
    cfg1 +>:DependsOn(criticality="critical"):+> api1;
    cfg2 +>:DependsOn(criticality="critical"):+> api2;

    auditor = ComplianceAuditor();
    root spawn auditor;

    print("");
    print(auditor.summarize());
}
