        self.stop_count += 1;
        print(f"Stop #{self.stop_count}: {here.label}");
        if self.stop_count >= self.target_stops {
            print(f"Trek complete: passed {self.stop_count} waypoints");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Waypoint(label="Trailhead Bridge")
        ++> Waypoint(label="Pine Ridge")
        ++> Waypoint(label="Creek Crossing")
        ++> Waypoint(label="Granite Ledge")
        ++> Waypoint(label="Wildflower Meadow")
        ++> Waypoint(label="False Summit")
        ++> Waypoint(label="Summit Cairn");
    root spawn Hiker();
}
