"""Tests for the Quiz Grader walker.

Verifies:
- Grader.report is strictly typed as list[int] (compile-time guarantee).
- Spawning Grader over a chain of Quiz nodes collects every score in order.
- Spawning Grader on Root walks via Root's outgoing edges.
- Computed average matches expected mean.
- A graph with no quizzes yields an empty report (no scores, NaN-safe length).
"""

import io;
import from contextlib { redirect_stdout }


# ---------------------------------------------------------------------------
# 1. Standard 4-quiz chain — collection order & completeness
# ---------------------------------------------------------------------------
test "grader collects every quiz score in traversal order" {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bashir", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dax", score=61);

    g = Grader();
    root spawn g;

    assert len(g.report) == 4, f"expected 4 scores, got {len(g.report)}";
    assert g.report[0] == 92, f"first score should be 92, got {g.report[0]}";
    assert g.report[1] == 78, f"second score should be 78, got {g.report[1]}";
    assert g.report[2] == 85, f"third score should be 85, got {g.report[2]}";
    assert g.report[3] == 61, f"fourth score should be 61, got {g.report[3]}";

    # All elements must be int — the strict typing promise.
    for (i, v) in enumerate(g.report) {
        assert isinstance(v, int), f"report[{i}] is {type(v).__name__}, not int";
    }
}


# ---------------------------------------------------------------------------
# 2. Average calculation matches the program's expected output
# ---------------------------------------------------------------------------
test "class average matches arithmetic mean of collected scores" {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bashir", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dax", score=61);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        g = Grader();
        root spawn g;
        scores = g.report;
        print(f"Collected scores: {scores}");
        avg = sum(scores) / len(scores);
        print(f"Class average: {avg}");
    }
    out = buf.getvalue();

    expected_avg = (92 + 78 + 85 + 61) / 4;   # 79.0
    assert g.report is not None, "report should exist after spawn";
    assert sum(g.report) == 316, f"sum of scores should be 316, got {sum(g.report)}";

    assert "Collected scores:" in out, f"missing collected-scores line: {out!r}";
    assert "Class average:" in out, f"missing average line: {out!r}";
    assert "92" in out and "78" in out and "85" in out and "61" in out,
        f"not every score appeared in output: {out!r}";
    assert f"{expected_avg}" in out, f"expected avg {expected_avg} not in output: {out!r}";
}


# ---------------------------------------------------------------------------
