"""Regression tests for Dancer2 canonical route references walker behavior."""

import io;
import from contextlib { redirect_stdout }

# --- Helpers -----------------------------------------------------------------

def _audit_route(target_route, name_to_audit: str) -> tuple {
    buf = io.StringIO();
    auditor = RouteRenameAuditor(route_name=name_to_audit);
    with redirect_stdout(buf) {
        target_route spawn auditor;
    }
    return (auditor.allow_rename, auditor.refusal_reason, buf.getvalue());
}

# --- Tests -------------------------------------------------------------------

test "complete denominator admits rename" {
    # Single named route with handler, refs, and params must allow rename.
    app_a = App(app_name="web", root_id="R1");
    route_a = RouteFact(route_name="user_show", path="/user/:id", generation=1);
    handler_a = HandlerAnchor(anchor_kind="coderef", label="&user_show_cb",
        is_canonical=True);
    ref_site = RouteFact(route_name="user_show_ref", path="", generation=1);
    param_id = RouteParam(param_key="id");

    root ++> app_a;
    app_a +>:DeclaredInApp:+> route_a;
    route_a +>:InlineHandler(is_coderef=True):+> handler_a;
    route_a +>:RefersTo(generation=1):+> ref_site;
    route_a +>:UsesParam:+> param_id;

    (allowed, reason, out) = _audit_route(route_a, "user_show");
    assert allowed is True, f"expected allow, got refusal: {reason!r} out={out!r}";
    assert reason == "", f"expected empty refusal reason, got {reason!r}";
    assert "route user_show" in out, f"missing summary line: {out!r}";
    assert "refs=1" in out, f"expected refs=1 in summary: {out!r}";
}

test "missing handler anchor refuses rename" {
    # A RouteFact with no InlineHandler edge must be refused.
    app_a = App(app_name="web", root_id="R1");
    route_a = RouteFact(route_name="orphan", path="/orphan", generation=1);
    ref_site = RouteFact(route_name="orphan_ref", path="", generation=1);

    root ++> app_a;
    app_a +>:DeclaredInApp:+> route_a;
    route_a +>:RefersTo(generation=1):+> ref_site;

    (allowed, reason, out) = _audit_route(route_a, "orphan");
    assert allowed is False, f"expected refusal, got allow; out={out!r}";
    assert reason == "no inline handler anchor", f"got reason: {reason!r}";
}

test "missing references refuse rename" {
    # Handler present yet zero RefersTo edges must refuse (no admitted refs).
    app_a = App(app_name="web", root_id="R1");
    route_a = RouteFact(route_name="lonely", path="/lonely", generation=1);
    handler_a = HandlerAnchor(anchor_kind="coderef", label="&lonely_cb",
        is_canonical=True);
    param_x = RouteParam(param_key="x");

    root ++> app_a;
    app_a +>:DeclaredInApp:+> route_a;
    route_a +>:InlineHandler(is_coderef=True):+> handler_a;
    route_a +>:UsesParam:+> param_x;

    (allowed, reason, out) = _audit_route(route_a, "lonely");
    assert allowed is False, f"expected refusal, got allow; out={out!r}";
    assert reason == "no admitted references", f"got reason: {reason!r}";
}

test "same name in another root is distinct target" {
    # Two apps, same route_name in different roots: auditing one route node
    # must not cross into the other root's same-named route.
    app_a = App(app_name="web", root_id="R1");
    route_a = RouteFact(route_name="user_show", path="/user/:id", generation=1);
    handler_a = HandlerAnchor(anchor_kind="coderef", label="&a_cb",
        is_canonical=True);
    ref_a = RouteFact(route_name="user_show_ref", path="", generation=1);
    param_a = RouteParam(param_key="id");

    app_b = App(app_name="admin", root_id="R2");
    route_b = RouteFact(route_name="user_show", path="/admin/user/:id",
        generation=1);
    handler_b = HandlerAnchor(anchor_kind="coderef", label="&b_cb",
        is_canonical=True);
    ref_b = RouteFact(route_name="admin_user_show_ref", path="", generation=1);
    param_b = RouteParam(param_key="id");

    root ++> app_a;
    root ++> app_b;
    app_a +>:DeclaredInApp:+> route_a;
    route_a +>:InlineHandler(is_coderef=True):+> handler_a;
    route_a +>:RefersTo(generation=1):+> ref_a;
    route_a +>:UsesParam:+> param_a;

    app_b +>:DeclaredInApp:+> route_b;
    route_b +>:InlineHandler(is_coderef=True):+> handler_b;
    route_b +>:RefersTo(generation=1):+> ref_b;
    route_b +>:UsesParam:+> param_b;

    # Auditing app_a's user_show must see exactly its own reference set,
