    assert allowed is True, f"app_a audit refused: {reason!r} out={out!r}";
    assert "refs=1" in out, f"app_a should see only its own ref: {out!r}";
    assert "admin_user_show_ref" not in out, (
        f"app_a audit leaked into app_b: {out!r}"
    );
}

test "cascade invalidator drops the app node" {
    # CascadeInvalidate should print the invalidation line and remove the
