    buf = io.StringIO();
    with redirect_stdout(buf) {
        app_b spawn CascadeInvalidate();
    }
    out = buf.getvalue();
    assert "invalidating app admin root=R2" in out, (
        f"missing invalidation line: {out!r}"
    );
}

