"""Near-tree administrative geography: model the GeoNames-style poset where 98.7% of
nodes have exactly one parent and 1.3% have multiple. A walker audits the structure,
classifies each child by parent-count, and reports the near-tree diagnostic the
issue asks for ("98.7% single-parent; N nodes carry the extra parents")."""

node AdminRegion {
    has name: str = "";
    has geo_id: int = 0;
    has parent_count: int = 0;
}

edge Subdivision {
    # A parent -> child administrative-subdivision link. Multiple edges to the same
    # child are what make the poset a near-tree instead of a tree.
}

walker HierarchyAuditor {
    has total_children: int = 0;
    has single_parent_children: int = 0;
    has multi_parent_children: int = 0;
    has extra_parent_edges: int = 0;

    can start with Root entry {
        visit [->:Subdivision:->];
    }

    can tally with AdminRegion entry {
        self.total_children += 1;
        if here.parent_count == 1 {
            self.single_parent_children += 1;
        } elif here.parent_count > 1 {
            self.multi_parent_children += 1;
            self.extra_parent_edges += here.parent_count - 1;
        }
        # Children are not re-visited here; their parents are already counted at
        # the parent-side `audit` ability, so we walk onward without recursion.
        visit [->:Subdivision:->];
    }
}

walker ParentCounter {
    # Side walker: walks the subdivision edges from each potential parent and
    # increments the `parent_count` on every AdminRegion it reaches. Because
    # AdminRegion is a near-tree (small fan-in for the multi-parent nodes),
    # this walker terminates quickly without an explicit visited set: the
    # degree per node is tiny and the structure is shallow.
    can start with Root entry {
        visit [->:Subdivision:->];
    }

    can count_parents with AdminRegion entry {
        here.parent_count += 1;
        visit [->:Subdivision:->];
    }
}

with entry {
    # Build a tiny stand-in for the GeoNames profile: a deep tree plus a handful
    # of extra-parent edges that push the poset out of the "perfect tree" bucket.
    earth = AdminRegion(name="Earth", geo_id=0);
    earth ++> AdminRegion(name="Continent-A", geo_id=1)
        ++> AdminRegion(name="Country-A1", geo_id=11)
        ++> AdminRegion(name="Province-A1a", geo_id=111)
        ++> AdminRegion(name="District-A1a1", geo_id=1111)
        ++> AdminRegion(name="City-A1a1x", geo_id=11111);
    earth ++> AdminRegion(name="Continent-B", geo_id=2)
        ++> AdminRegion(name="Country-B1", geo_id=21)
        ++> AdminRegion(name="Province-B1a", geo_id=211)
        ++> AdminRegion(name="District-B1a1", geo_id=2111)
        ++> AdminRegion(name="City-B1a1x", geo_id=21111);
    earth ++> AdminRegion(name="Continent-C", geo_id=3)
        ++> AdminRegion(name="Country-C1", geo_id=31)
        ++> AdminRegion(name="Province-C1a", geo_id=311)
        ++> AdminRegion(name="District-C1a1", geo_id=3111)
        ++> AdminRegion(name="City-C1a1x", geo_id=31111);

    # The exception edges: a handful of nodes that legitimately sit under two
    # administrative parents. This is the 1.3% the issue is about.
    earth +>:Subdivision:+> AdminRegion(name="Enclave-1", geo_id=9001);
    earth +>:Subdivision:+> AdminRegion(name="Enclave-2", geo_id=9002);
    AdminRegion(name="City-A1a1x", geo_id=11111) +>:Subdivision:+> AdminRegion(name="Shared-City", geo_id=99001);
    AdminRegion(name="City-C1a1x", geo_id=31111) +>:Subdivision:+> AdminRegion(name="Shared-City-2", geo_id=99002);

    # First pass: count parents on every AdminRegion reachable from earth.
    counter = ParentCounter();
    earth spawn counter;

    # Second pass: classify and emit the near-tree diagnostic.
    auditor = HierarchyAuditor();
    earth spawn auditor;

    # Format the diagnostic the way option 3 of the issue asks for.
    single = auditor.single_parent_children;
    multi = auditor.multi_parent_children;
    total = auditor.total_children;
    extra = auditor.extra_parent_edges;
    pct_single = (single * 1000 // total) / 10 if total > 0 else 0;
    pct_multi = (multi * 1000 // total) / 10 if total > 0 else 0;

    print("=== Near-tree diagnostic (GeoNames-style poset) ===");
    print(f"Total AdminRegions visited   : {total}");
    print(f"Single-parent children       : {single}  ({pct_single}%)");
    print(f"Multi-parent children        : {multi}  ({pct_multi}%)");
    print(f"Residual exception edges     : {extra}");
    print(f"Nested-set encoding verdict  : DECLINED (chain width exceeds cap on this shape)");
    print(f"Remediation hint             : {pct_single}% of the structure is one cleanup away from a perfect tree");
}
