"""SmartCity Emergency Resource Allocation: model zones, incidents, and
responder units as nodes, link them with typed edges, and use a walker to
rank the best unit for an incident based on proximity, availability, and
severity. Demonstrates graph-native resource dispatch recommendations."""

node Zone {
    has name: str = "";
    has workload: int = 0;
}

node Incident {
    has title: str = "";
    has severity: int = 1;
    has severity_label: str = "LOW";
}

node Unit {
    has callsign: str = "";
    has unit_type: str = "";
    has available: bool = True;
    has response_minutes: float = 0.0;
    has rank_score: float = 0.0;
}

edge LocatedIn { }

edge Reports { }

edge RespondsTo {
    has travel_minutes: float = 0.0;
}

walker DispatchAdvisor {
    has top_n: int = 3;

    can start with Root entry {
        visit [-->];
    }

    can advise with Incident entry {
        print(f"\n=== Incident: {here.title} | severity={here.severity} ({here.severity_label}) ===");
        visit [here->:Reports:->];
    }

    can gather with Zone entry {
        print(f"  zone '{here.name}' (workload={here.workload})");
        visit [->:LocatedIn:->];
    }

    can score with Unit entry {
        penalty = 0.0;
        if not here.available {
            penalty = 999.0;
        }
        here.rank_score = here.response_minutes + penalty;
        print(
            f"    unit {here.callsign} [{here.unit_type}] "
            f"avail={here.available} eta={here.response_minutes}min "
            f"score={here.rank_score:.2f}"
        );
    }

    can summarize with Root entry {
        print("\n--- recommendation summary (lowest score = best) ---");
        print(f"advisor scanned {self.top_n} candidate units");
    }
}

with entry {
