```jac
"""Tool-process lifecycle model.

When a Claude-like parent moves on to newer work, still-running
tool children should be detected, reaped, and the supersession
recorded. This demo models that scenario with explicit graph
traversal so the lifecycle stays observable.
"""

node ToolChild {
    has name: str = "";
    has command: str = "";
    has cpu_seconds: float = 0.0;
    has superseded: bool = False;
    has reaped: bool = False;
}

node Worktree {
    has path: str = "";
    has has_node_modules: bool = False;
}

node ClaudeParent {
    has label: str = "";
    has active_action: str = "";
    has stale_children: int = 0;
}

edge Spawned {
    has started_at: str = "";
}

edge Scans {
    has recursive: bool = True;
}

walker ProcessAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_parent with ClaudeParent entry {
        print(f"parent {here.label} active on: {here.active_action}");
        visit [-->];
    }

    can tally_stale with ToolChild entry {
        if here.superseded and not here.reaped {
            here.reaped = True;
            print(f"  reaping stale child: {here.command}");
            parent = here;
            # No further forward traversal — a reaped child has no
            # alive process tree worth auditing.
            disengage;
        }
        visit [-->];
    }

    can inspect_worktree with Worktree entry {
        marker = "with" if here.has_node_modules else "without";
        print(f"  worktree {here.path} ({marker} node_modules)");
        visit [-->];
    }
}

walker StaleScanner {
    can start with Root entry {
        visit [-->];
    }

    can sweep with ClaudeParent entry {
        # Follow spawned edges to find still-running tool children.
        visit [->:Spawned:->];
    }

    can scan_worktree with Worktree entry {
        # Follow Scans edges into child processes from this worktree.
        visit [->:Scans:->];
    }

    can reap_stale with ToolChild entry {
        if here.superseded and not here.reaped {
            here.reaped = True;
            here.cpu_seconds = 0.0;
            print(f"reaped superseded child {here.name}");
        }
        visit [-->];
    }
}

with entry {
    # Two worktrees, one heavy with node_modules.
    wt_main = Worktree(path="scripts", has_node_modules=False);
    wt_claude = Worktree(path=".claude/worktrees", has_node_modules=True);

    # An active parent with a current action label.
    parent = ClaudeParent(label="claude.exe", active_action="review PR #482");
    root ++> parent;

    # Two stale PowerShell children still recursively scanning.
    stale_a = ToolChild(
        name="pwsh.exe#1",
        command="Get-ChildItem -Recurse -File -Path scripts,.claude -Include *.mjs,*.js",
        cpu_seconds=5.72,
        superseded=True,
    );
    stale_b = ToolChild(
        name="pwsh.exe#2",
        command="Get-ChildItem -Recurse -File -Path .claude,scripts",
        cpu_seconds=1.66,
        superseded=True,
    );

    # A fresh child the parent spawned for newer work.
    fresh = ToolChild(
        name="pwsh.exe#3",
        command="git status --porcelain",
        cpu_seconds=0.02,
        superseded=False,
    );

    # Parent -> worktrees (via Spawned edges, lifecycle-meaningful).
    parent +>:Spawned(started_at="T0"):+> wt_main;
    parent +>:Spawned(started_at="T0"):+> wt_claude;

    # Worktrees -> tool children that scan them (Scans typed edges).
    wt_main +>:Scans:+> stale_a;
    wt_claude +>:Scans:+> stale_b;
    wt_main +>:Scans:+> fresh;

    # Walk 1: auditor reports state, reaping any superseded child it hits.
    print("--- ProcessAuditor walk ---");
    auditor = ProcessAuditor();
    parent spawn auditor;

    # Walk 2: dedicated stale-scanner from the parent.
    print("--- StaleScanner walk ---");
    scanner = StaleScanner();
    parent spawn scanner;

    remaining = 0;
    for c in [stale_a, stale_b, fresh] {
        if c.superseded and not c.reaped {
            remaining += 1;
        }
    }
    parent.stale_children = remaining;
    print(f"stale children remaining: {parent.stale_children}");
}
