# --- ProcessAuditor: reaps a stale child and disengages ---------------------
test "ProcessAuditor reaps stale child and disengages" {
    # Build a minimal graph: parent -> worktree -> one stale child, one fresh.
    rt = root ++> Worktree(path="scripts", has_node_modules=False);
    parent = root ++> ClaudeParent(label="claude.exe", active_action="edit file");
