    # Disengagement means the worktree's child was reaped before worktree print
    # was necessarily reached via that branch — auditor output for the fresh
    # child should also be absent because disengage happens at stale.
    assert "git status" not in out, f"auditor should disengage after reaping stale; got: {out}";
