"""Reports access control: published reports are world-readable, drafts fall back to per-instance grants.

A report archetype exposes an `access_level` hook that returns READ when the
report is published and None otherwise, so unpublished drafts stay closable
while owners can still attach selective grants. The `Publish` walker flips
the `published` flag and removes the now-redundant default grant.
"""

node Grant {
    has level: str = "NONE";
}

node Report {
    has title: str = "";
    has published: bool = False;
    has default_grant: Grant | None = None;

    def access_level() -> str | None {
        if self.published {
            return "READ";
        }
        return None;
    }

    def attach_grant(g: Grant) -> None {
        self.default_grant = g;
    }
}

walker Publish {
    has new_title: str = "";

    can start with Root entry {
        visit [-->];
    }

    can publish with Report entry {
        # Flip the flag first; access_level() now resolves to READ.
        here.published = True;
        # Drop the now-redundant per-instance grant, if any.
        if here.default_grant is not None {
            del here.default_grant;
            here.default_grant = None;
        }
        # Keep going in case the demo chains more reports off root.
        visit [-->];
    }
}

walker Inspector {
    can start with Root entry {
        visit [-->];
    }

    can inspect with Report entry {
        level = here.access_level();
        label = "PUBLISHED/READ" if level is not None else "DRAFT/no public access";
        grant = here.default_grant;
        grant_label = "with grant" if grant is not None else "no grant";
        print(f"{here.title}: {label} ({grant_label})");
        visit [-->];
    }
}

with entry {
    draft = Report(title="Q4 Roadmap");
    draft.attach_grant(Grant(level="NONE"));
    root ++> draft;

    internal = Report(title="Hiring Plan");
    internal.attach_grant(Grant(level="NONE"));
    root ++> internal;

    public_brief = Report(title="Mission Statement", published=True);
    public_brief.attach_grant(Grant(level="NONE"));
    root ++> public_brief;

    print("=== Before publish ===");
    root spawn Inspector();

    print("=== Publishing Q4 Roadmap ===");
    root spawn Publish();

    print("=== After publish ===");
    root spawn Inspector();
}
