```jac
"""Quiz grader walker with strictly integer reports.

The ``Grader`` walker collects per-quiz scores into an ``int`` accumulator,
so a stray string score would fail at compile / load time. We spawn it
across a handful of ``Quiz`` nodes and print the individual results
together with the class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    # Strictly typed report: only integers can be appended.
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.scores.append(here.score);
        visit [-->];
    }

    # Final tally once traversal completes.
    can summarize with Root exit {
        if len(self.scores) == 0 {
            print("No quizzes graded.");
        } else {
            total = 0;
            for s in self.scores {
                total += s;
            }
            average = total / len(self.scores);
            print(f"Scores: {self.scores}");
            print(f"Class average: {average:.2f}");
        }
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carla", score=95)
        ++> Quiz(student="Dan", score=61)
        ++> Quiz(student="Eve", score=82);
    root spawn Grader();
}
