Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""Module-top-level call graph: lost edges from IIFEs, callbacks, bare calls, initialisers.

Models the JS/TS issue: a file with named functions records their internal call
edges, but calls made by top-level bootstrap code (IIFEs, callbacks, bare
calls, initialiser RHS) belong to no extracted unit and are lost. A walker
walks the emitted-function units via typed edges and reports which edges to
the sink are recorded; the lost bootstrap edges are computed separately to
show the gap, then a synthetic module-scope walker visits the masked-off
top-level statements via a typed edge and recovers them.
"""

# ---------- Entity archetypes ----------

node FunctionUnit {
    has unit_name: str = "";
    has body_text: str = "";
    has line_start: int = 0;
    has line_end: int = 0;
}

# A top-level bootstrap statement (IIFE, callback, bare call, initialiser)
# that is NOT contained in any FunctionUnit's line range. Models a
# statement-level node that should become its own unit.
node TopLevelStatement {
    has stmt_text: str = "";
    has line: int = 0;
}

# A sink function reachable from both control code and bootstrap code.
node Sink {
    has sink_name: str = "";
}

# ---------- Typed edges ----------

# A call from an emitting unit (FunctionUnit OR TopLevelStatement) to a Sink.
edge Calls { }

# A "covers lines" relationship from a FunctionUnit to the bootstrap statement
# its body contains. Used to demonstrate that whole-statement containment
# fabrication is wrong: a class member line range lives INSIDE a top-level
# statement, but its body is NOT a top-level call.
edge CoversLines { }

# ---------- Walkers ----------

# Walks emitted FunctionUnits and reports their recorded call edges to Sinks.
walker CallGraphAuditor {
    has recorded: list = [];

    can start with Root entry {
        # Jump to the file-level root that owns the units. In this demo the
        # units are direct children of root via a typed edge.
        visit [->:Calls:->];
    }

    can audit_unit with FunctionUnit entry {
        # For each unit, record its outgoing Calls edges to Sinks. This
        # mirrors `_extractCalls(funcData.code, funcId)` in the issue.
        self.recorded.append(here.unit_name);
        visit [here->:Calls:->];
    }

    can record_sink with Sink entry {
        self.recorded.append(here.sink_name);
    }
}

# Walks ONLY the top-level bootstrap statements (those whose line is NOT
# masked off by any FunctionUnit's line range). Models the fix: line-range
# exclusion instead of statement containment, so class members / object-literal
# methods do NOT leak into the synthetic module unit.
walker BootstrapEdgeRecoverer {
    has recovered: list = [];
    has masked_ranges: list = [];

    can start with Root entry {
        # First pass: collect line ranges covered by emitted FunctionUnits.
        visit [->:Calls:->];
    }

    can collect_masks with FunctionUnit entry {
        if here.line_end >= here.line_start {
            self.masked_ranges.append((here.line_start, here.line_end));
        }
        visit [here->:Calls:->];
    }

    # A TopLevelStatement fires for every bootstrap line; we then check
    # whether its line falls inside any FunctionUnit's range. If it does,
    # the statement is body code, not a top-level call, and we skip it.
    can recover_edge with TopLevelStatement entry {
        line = here.line;
        inside_unit = False;
        for (lo, hi) in self.masked_ranges {
            if line >= lo and line <= hi {
                inside_unit = True;
                break;
            }
        }
        if not inside_unit {
            # Walk the Calls edges from this bootstrap statement to Sinks.
            visit [here->:Calls:->];
        }
    }

    can record_recovered with Sink entry {
        self.recovered.append((here.sink_name, "via top-level bootstrap"));
    }
}

# ---------- Demonstration ----------

with entry {
    # The control function: emits a unit with a recorded Calls edge to sink.
    control = FunctionUnit(
        unit_name="realFn",
        body_text="sink();",
        line_start=2,
        line_end=2
    );

    # The sink.
    sink = Sink(sink_name="sink");

    # Top-level bootstrap statements. Each is a separate node, NOT contained
    # in any FunctionUnit's line range.
    iife_stmt = TopLevelStatement(stmt_text="(function boot(){ sink(); })();", line=3);
    cb_stmt = TopLevelStatement(stmt_text="[1].forEach(function(){ sink(); });", line=4);
    bare_stmt = TopLevelStatement(stmt_text="main();", line=5);
    init_stmt = TopLevelStatement(stmt_text="const initv = sink();", line=7);

    # Class member + object-literal method whose body lines ARE inside
    # top-level statements (line 9 is inside the class declaration on line 8,
    # line 13 is inside the const handlers = {...} on line 12). These must
    # NOT be reported as top-level calls.
    class_member = FunctionUnit(
        unit_name="K.method",
        body_text="classOnlyHelper();",
        line_start=9,
        line_end=9
    );
    objlit_method = FunctionUnit(
        unit_name="handlers.handle",
        body_text="objLitHelper();",
        line_start=13,
        line_end=13
    );

    # Wire recorded call edges (what the buggy build_call_graph sees).
    control +>:Calls:+> sink;

    # Wire the bootstrap -> sink edges (what the buggy build misses).
    iife_stmt +>:Calls:+> sink;
    cb_stmt +>:Calls:+> sink;
    bare_stmt +>:Calls:+> sink;
    init_stmt +>:Calls:+> sink;

    # Connect everything to root. Top-level statements sit alongside the
    # control unit so the auditor can see them; the recoverer uses line
    # masking to pick only the bootstrap ones.
    root ++> control ++> iife_stmt ++> cb_stmt ++> bare_stmt ++> init_stmt
          ++> class_member ++> objlit_method
          ++> sink;

    # --- Run 1: buggy auditor (mirrors the issue) ---
    auditor = CallGraphAuditor();
    root spawn auditor;
    print("Recorded units visited by auditor:");
    for name in auditor.recorded {
        print(f"  - {name}");
    }
    print("");

    # --- Run 2: line-range-aware bootstrap recoverer ---
    recoverer = BootstrapEdgeRecoverer();
    root spawn recoverer;
    print("Recovered bootstrap -> sink edges (line-range masking):");
