```jac
"""Modernization gap: declared Rust/dependency/API/workflow contract vs. proven evidence.

The maintainer's complaint is that hand-rolled adjacency (manifest + lockfile +
docs + workflows + CI rows) is walked by ad-hoc scripts, leaving drift between
what the repo *claims* and what it *proves*. Here we model the core entities as
node archetypes, the relationship between a declared contract claim and its
evidence as typed edges, and use a walker to traverse the claim -> evidence
graph to flag claims that lack proof, have stale evidence, or are
policy-adjacent.
"""

# ---- Entity archetypes ----------------------------------------------------

node Claim {
    has title: str = "";
    has lane: str = "";
    has claim_id: str = "";
}

node Evidence {
    has title: str = "";
    has source: str = "";
    has deterministic: bool = False;
}

node Policy {
    has title: str = "";
    has strict: bool = True;
}

node ReviewNote {
    has message: str = "";
}

# ---- Typed edges ----------------------------------------------------------

# A Claim is backed by zero or more Evidence nodes.
edge BackedBy {
    has observed_at: str = "";
    has stale: bool = False;
}

# A Claim is governed by a Policy.
edge GovernedBy { }

# A ReviewNote annotates a Claim with a free-text observation.
edge AnnotatedBy { }

# ---- Walker: traverse claim graph, classify evidence posture --------------

walker ClaimAuditor {
    has proven: list[str] = [];
    has unsupported: list[str] = [];
    has stale_claims: list[str] = [];
    has policy_adjacent: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Claim entry {
        evidence_nodes = [here->:BackedBy:->];
        policy_nodes = [here->:GovernedBy:->];
        note_nodes = [here->:AnnotatedBy:->];

        ev_count = len(evidence_nodes);
        if ev_count == 0 {
            self.unsupported.append(here.title);
            print(f"[UNSUPPORTED] {here.claim_id} {here.title} (lane={here.lane})");
        } else {
            any_deterministic = False;
            any_stale = False;
            for ev in evidence_nodes {
                if ev.deterministic {
                    any_deterministic = True;
                }
            }
            for ev in evidence_nodes {
                if not ev.deterministic {
                    any_stale = True;
                }
            }

            if any_stale {
                self.stale_claims.append(here.title);
                print(f"[STALE] {here.claim_id} {here.title} - evidence exists but marked stale");
            } elif any_deterministic {
                self.proven.append(here.title);
                print(f"[PROVEN] {here.claim_id} {here.title} - deterministic evidence present");
            } else {
                self.unsupported.append(here.title);
                print(f"[UNSUPPORTED] {here.claim_id} {here.title} - non-deterministic evidence");
            }
        }

        if len(policy_nodes) > 0 {
            self.policy_adjacent.append(here.title);
        }
        if len(note_nodes) > 0 {
            for nt in note_nodes {
                print(f"  note: {nt.message}");
            }
        }

        visit [-->];
    }
}

# ---- Demonstration wiring -------------------------------------------------

with entry {
    premise_claim = Claim(
        title="exact issue/source/external-state premise receipt",
        lane="current-main",
        claim_id="#3918"
    );
    dep_floors = Claim(
        title="selected direct-minimum-version requests and receipts",
        lane="dependency",
        claim_id="#3903"
    );
    graph_delta = Claim(
        title="deterministic manifest/lockfile base-head graph movement",
        lane="dependency",
        claim_id="#3920"
    );
    lint_authority = Claim(
        title="inherited Rust/Clippy policy with explicit exceptions",
        lane="workspace",
        claim_id="#3904"
    );

    deterministic_evidence = Evidence(
        title="base-head lockfile diff receipt",
        source="scripts/graph_targets/probe_walker_cycle.jac",
        deterministic=True
    );
    stale_evidence = Evidence(
        title="moving stable toolchain observation",
        source="ci rows using stable + *-latest",
        deterministic=False
    );
    nondeterministic_evidence = Evidence(
        title="hand-fixture parser coverage",
        source="tests/fixtures",
        deterministic=False
    );

    strict_policy = Policy(title="API support tiers govern compatibility reports", strict=True);
    advisory_policy = Policy(title="small source/repository hygiene improvements", strict=False);

    note_stale = ReviewNote(message="evidence exists but stale flag set");
    note_no_evidence = ReviewNote(message="no backing evidence attached");

    root ++> premise_claim;
    root ++> dep_floors;
    root ++> graph_delta;
    root ++> lint_authority;

    premise_claim +>:BackedBy(observed_at="2024-W14", stale=False):+> deterministic_evidence;
    premise_claim +>:AnnotatedBy:+> note_no_evidence;

    dep_floors +>:BackedBy(observed_at="2024-W10", stale=True):+> stale_evidence;
    dep_floors +>:GovernedBy:+> strict_policy;

    graph_delta +>:BackedBy(observed_at="2024-W14", stale=False):+> deterministic_evidence;
    graph_delta +>:GovernedBy:+> strict_policy;
    graph_delta +>:AnnotatedBy:+> note_stale;

    lint_authority +>:AnnotatedBy:+> note_no_evidence;
    lint_authority +>:GovernedBy:+> advisory_policy;

    auditor = ClaimAuditor();
    root spawn auditor;

    print("--- summary ---");
    print(f"proven: {auditor.proven}");
    print(f"unsupported: {auditor.unsupported}");
    print(f"stale_claims: {auditor.stale_claims}");
