"""Docker doctor scenario graph: model diagnostic stacks and walk verdicts.

Models a small Docker/MCP scenario corpus: stacks, services, diagnostics, and
scenarios connected by typed edges. A walker descends the graph, collecting
verdicts for each scenario and reporting any blocking findings so reviewers can
see whether a fixture is healthy or intentionally broken.
"""

node Service {
    has name: str = "";
    has image: str = "";
    has healthy: bool = True;
    has has_stale_fatal: bool = False;
}

node Diagnostic {
    has tool_name: str = "";
    has verdict: str = "unknown";
    has severity: str = "info";
    has blocked: bool = False;
}

node Scenario {
    has title: str = "";
    has expected_root_cause: str = "";
    has synthetic_secret: str = "";
}

node Stack {
    has name: str = "";
    has network_mode: str = "bridge";
}

edge BelongsTo { }
edge Reports { has severity: str = "info"; }
edge Covers { }

walker Verifier {
    has findings: list = [];
    has secret_leaks: list = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_stack with Stack entry {
        print(f"[stack] {here.name} (network_mode={here.network_mode})");
        visit [-->];
    }

    can inspect_service with Service entry {
        flag = "healthy" if here.healthy else "degraded";
        print(f"  [service] {here.name} -> {flag}");
        if here.has_stale_fatal {
            note = f"stale fatal in logs for {here.name}";
            self.findings.append(note);
            print(f"    ! {note}");
        }
        visit [-->];
    }

    can check_diagnostic with Diagnostic entry {
        blocker = "BLOCKING" if here.blocked else "ok";
        print(f"    [diag:{here.tool_name}] verdict={here.verdict} "
              f"severity={here.severity} ({blocker})");
        if here.blocked {
            self.findings.append(
                f"{here.tool_name} on scenario flagged {here.verdict}"
            );
        }
        visit [-->];
    }

    can audit_scenario with Scenario entry {
        leak = "SUSPECT" if here.synthetic_secret else "clean";
        print(f"  [scenario] {here.title} ({leak})");
        if here.synthetic_secret {
            self.secret_leaks.append(here.title);
        }
        visit [-->];
    }
}

walker RegressionRunner {
    can start with Root entry {
        visit [-->];
    }

    can traverse with Stack | Service | Diagnostic | Scenario entry {
        if isinstance(here, Stack) {
            print(f"walking stack {here.name}");
        } elif isinstance(here, Scenario) {
            print(f"verifying scenario '{here.title}' expects: "
                  f"{here.expected_root_cause}");
        }
        visit [-->];
    }
}

with entry {
    # Healthy bridge-network stack
    bridge = Stack(name="web-bridge", network_mode="bridge");
    bridge ++> Service(name="web", image="nginx:1.27", healthy=True);
    bridge++> Diagnostic(tool_name="smoke", verdict="pass", severity="info");

    # Healthy host-network stack
    host = Stack(name="agent-host", network_mode="host");
    host ++> Service(name="agent", image="agent:2.0", healthy=True);
    host ++> Diagnostic(tool_name="smoke", verdict="pass", severity="info");

    # Restart loop stack
    restart = Stack(name="db-restart", network_mode="bridge");
    restart ++> Service(name="db", image="postgres:16", healthy=False);
    restart ++> Diagnostic(
        tool_name="restart_loop",
        verdict="CrashLoopBackOff",
        severity="critical",
        blocked=True,
    );

