"""Orphaned skill detector.

Models a docs/skills project where one skill describes an architecture that
no longer matches the live commands, and a command points at a path that
does not exist. A walker audits the documentation graph, detects orphaned
skills, detects stale architecture descriptions, and detects dangling
references — the three classes of rot described in the issue.
"""

# ---------- entities ----------

node DocFile {
    has path: str = "";
    has exists_on_disk: bool = False;
    has references: list[str] = [];
    has describes_arch: str = "";
    has actual_arch: str = "";
}

node Skill {
    has name: str = "";
    has archived: bool = False;
}

node Command {
    has name: str = "";
    has dispatches: list[str] = [];
}

# ---------- relationships (typed edges) ----------

edge DescribesArch {
    has arch_version: str = "";
}

edge Dispatches {
    has stage: str = "";
}

edge PointsAtSkill {
    # marker edge: command -> skill (only if skill actually exists)
}

# ---------- audit walker ----------

walker DocAuditor {
    has orphans: list[str] = [];
    has stale_skills: list[str] = [];
    has dangling_refs: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        print("=== Doc audit: walking the documentation graph ===");
        visit [-->];
    }

    can audit_doc with DocFile entry {
        # whole-record elimination: scan every DocFile node we land on
        path_id = here.path;
        if path_id in self.visited {
            # cycle guard: explicit, because visit has no dedupe
            visit [-->] else { disengage; }
        }
        self.visited.append(path_id);

        # orphan detection: doc does not exist on disk and nothing refs it
        if not here.exists_on_disk {
            nothing_refs = True;
            for ref in here.references {
                if ref != "" {
                    nothing_refs = False;
                    break;
                }
            }
            if nothing_refs {
                self.orphans.append(path_id);
                print(f"  [ORPHAN] {path_id} — not on disk, no inbound refs");
            }
        }

        # stale architecture detection: described vs actual arch mismatch
        if here.describes_arch != "" and here.describes_arch != here.actual_arch {
            stale_label = (
                f"{path_id}: describes v{here.describes_arch}"
                f" but live pipeline is v{here.actual_arch}"
            );
            self.stale_skills.append(stale_label);
            print(f"  [STALE]  {stale_label}");
        }

        visit [-->] else { disengage; }
    }

    can inspect_command with Command entry {
        # dangling reference: command points at a skill path that does not exist
        for target in here.dispatches {
            self.dangling_refs.append(f"{here.name} -> {target}");
            print(f"  [DANGLING] command {here.name} points at missing {target}");
        }
        visit [-->] else { disengage; };
    }

    can audit_skill with Skill entry {
        # skills that are archived but still described as live are also rot
        if here.archived {
            self.stale_skills.append(f"archived skill still present: {here.name}");
            print(f"  [ARCHIVED] skill {here.name} is archived");
        }
        visit [-->] else { disengage; };
    }

    can finish with Root entry {
        print("");
        print(f"summary: {len(self.orphans)} orphan(s), "
              f"{len(self.stale_skills)} stale entry(ies), "
              f"{len(self.dangling_refs)} dangling reference(s)");
    }
}

# ---------- demonstration graph ----------

with entry {
    # The orphaned skill: exists as a DocFile node, not on disk, nothing refs it.
    verification_engine = DocFile(
        path="skills/verification-engine/SKILL.md",
        exists_on_disk=False,
        references=[],
        describes_arch="6",
        actual_arch="8",
    );

    # The live skill: on disk, accurate description, referenced by a command.
    handoff_verify_skill = Skill(name="skills/handoff-verify/", archived=False);
    handoff_verify_doc = DocFile(
        path="skills/handoff-verify/SKILL.md",
        exists_on_disk=False,  # the issue says this path is missing too
        references=["commands/handoff-verify.md"],
        describes_arch="8",
        actual_arch="8",
    );

    # The command that dispatches reviewers and points at the missing skill.
    handoff_verify_cmd = Command(
        name="commands/handoff-verify.md",
        dispatches=["skills/handoff-verify/", "verify-agent", "security-reviewer"],
    );

    # Another live doc that matches reality.
    auto_cmd_doc = DocFile(
        path="commands/auto.md",
        exists_on_disk=True,
        references=[],
        describes_arch="8",
        actual_arch="8",
    );

    # Wire the documentation graph with typed edges.
    root ++> verification_engine;
    root +>:DescribesArch(arch_version="6"):+> verification_engine;

    root ++> handoff_verify_doc;
    handoff_verify_cmd +>:PointsAtSkill:+> handoff_verify_skill;
    handoff_verify_cmd +>:Dispatches(stage="verify"):+> handoff_verify_doc;

    root ++> auto_cmd_doc;
    auto_cmd_doc +>:Dispatches(stage="security-scan"):+> handoff_verify_doc;

    root ++> handoff_verify_cmd;
    root ++> handoff_verify_skill;

    # Run the audit.
    root spawn DocAuditor();
}
```

"""Regression tests for the orphaned-skill DocAuditor demo.

The program PRINTS its findings; we capture stdout and also reach into the
walker's `has` fields on the spawned instance to assert structural outcomes
(orphans list, stale list, dangling list). Each test builds its own graph
from scratch — the harness runs them in isolated workers.
"""

import io;
import from contextlib { redirect_stdout }


# ---------- helpers ----------

def run_auditor(buf: io.StringIO, root_node) -> object {
    with redirect_stdout(buf) {
        res = root_node spawn DocAuditor();
    }
    return res;
}


# ---------- tests ----------

test "demo graph: verifier engine is the canonical orphan" {
    verification_engine = DocFile(
        path="skills/verification-engine/SKILL.md",
        exists_on_disk=False,
        references=[],
        describes_arch="6",
        actual_arch="8",
    );
    live_doc = DocFile(
        path="commands/auto.md",
        exists_on_disk=True,
        references=[],
        describes_arch="8",
        actual_arch="8",
    );
    root ++> verification_engine;
    root ++> live_doc;
    root +>:DescribesArch(arch_version="6"):+> verification_engine;

    buf = io.StringIO();
    res = run_auditor(buf, root);
    out = buf.getvalue();

    # exactly the one orphan
    assert res.orphans == ["skills/verification-engine/SKILL.md"], (
        f"orphans not as expected: {res.orphans}"
    );
    # it is reported as ORPHAN in stdout and is also flagged STALE (arch v6 vs v8)
    assert "[ORPHAN] skills/verification-engine/SKILL.md" in out, (
        f"missing ORPHAN line in output: {out}"
    );
    assert any(
        "skills/verification-engine/SKILL.md" in s and "v6" in s and "v8" in s
        for s in res.stale_skills
    ), f"stale label missing v6/v8: {res.stale_skills}";
    # live doc with matching arch produces no stale entry
    assert not any(
        "commands/auto.md" in s for s in res.stale_skills
    ), f"live doc wrongly marked stale: {res.stale_skills}";
    # summary line printed
    assert "summary:" in out, f"missing summary line: {out}";
}


test "command with three dispatches produces three dangling refs in order" {
    cmd = Command(
        name="commands/handoff-verify.md",
        dispatches=["skills/handoff-verify/", "verify-agent", "security-reviewer"],
    );
    # a skill node so the audit walker has somewhere to walk
    skill = Skill(name="skills/anything/", archived=False);
    root ++> cmd;
    cmd +>:PointsAtSkill:+> skill;

    buf = io.StringIO();
    res = run_auditor(buf, root);
    out = buf.getvalue();

    # three dangling refs, one per dispatch, in dispatch order
    assert len(res.dangling_refs) == 3, (
        f"expected 3 dangling refs, got {len(res.dangling_refs)}: {res.dangling_refs}"
    );
    assert res.dangling_refs == [
        "commands/handoff-verify.md -> skills/handoff-verify/",
        "commands/handoff-verify.md -> verify-agent",
        "commands/handoff-verify.md -> security-reviewer",
    ], f"dangling list order/contents wrong: {res.dangling_refs}";

    # each named target appears in stdout under [DANGLING]
    for target in ["skills/handoff-verify/", "verify-agent", "security-reviewer"] {
        assert f"[DANGLING] command commands/handoff-verify.md points at missing {target}" in out, (
            f"missing DANGLING line for {target} in: {out}"
        );
    }
    # command never produces an orphan or stale entry on its own
    assert res.orphans == [], f"command unexpectedly in orphans: {res.orphans}";
    assert res.stale_skills == [], (
        f"command unexpectedly in stale: {res.stale_skills}"
    );
}


test "archived skill is flagged as stale rot" {
    legacy = Skill(name="skills/legacy-cron/", archived=True);
    doc = DocFile(
        path="skills/legacy-cron/SKILL.md",
        exists_on_disk=True,
        references=["commands/cron.md"],
        describes_arch="",
        actual_arch="",
    );
    cmd = Command(name="commands/cron.md", dispatches=[]);
    root ++> legacy;
    root ++> doc;
    root ++> cmd;

    buf = io.StringIO();
    res = run_auditor(buf, root);
    out = buf.getvalue();

    # the archived skill is reported in stale_skills
    assert any(
        "skills/legacy-cron/" in s for s in res.stale_skills
    ), f"archived skill not in stale list: {res.stale_skills}";
    assert "[ARCHIVED] skill skills/legacy-cron/" in out, (
        f"missing ARCHIVED marker in output: {out}"
    );
    # an on-disk, well-referenced doc is NOT an orphan
    assert res.orphans == [], f"live doc wrongly orphaned: {res.orphans}";
}


test "cycle guard: shared doc referenced twice is visited once, no duplicate reports" {
    shared = DocFile(
        path="commands/shared.md",
        exists_on_disk=False,  # would normally be an orphan
        references=["commands/a.md", "commands/b.md"],  # but two inbound refs
        describes_arch="",
        actual_arch="",
    );
    # Two doc nodes that both point to the shared one via DescribesArch —
    # walker's `visited` list guards against double-counting the orphan.
    a = DocFile(
        path="commands/a.md",
        exists_on_disk=True,
        references=["commands/shared.md"],
        describes_arch="",
        actual_arch="",
    );
    b = DocFile(
        path="commands/b.md",
        exists_on_disk=True,
        references=["commands/shared.md"],
        describes_arch="",
        actual_arch="",
    );
    root ++> a;
    root ++> b;
    a +>:DescribesArch(arch_version="8"):+> shared;
    b +>:DescribesArch(arch_version="8"):+> shared;

    buf = io.StringIO();
    res = run_auditor(buf, root);
    out = buf.getvalue();

    # shared is NOT orphan because references list is non-empty (has inbound refs)
    assert "commands/shared.md" not in res.orphans, (
        f"shared wrongly orphaned (it has inbound refs): {res.orphans}"
    );
    # shared was visited exactly once — [ORPHAN] line for it never appears
    assert "[ORPHAN] commands/shared.md" not in out, (
        f"unexpected ORPHAN line for shared: {out}"
    );
    # both a and b show up in visited but no duplicate stale/orphan entries
    orphan_lines = [ln for ln in out.splitlines() if ln.startswith("  [ORPHAN]")];
    assert len(orphan_lines) == 0, (
        f"unexpected orphan lines for well-referenced docs: {orphan_lines}"
    );
}


test "clean graph: nothing flagged" {
    live_doc = DocFile(
        path="commands/auto.md",
        exists_on_disk=True,
        references=[],
        describes_arch="8",
        actual_arch="8",
    );
    live_skill = Skill(name="skills/handoff-verify/", archived=False);
    live_cmd = Command(name="commands/auto.md", dispatches=["verify-agent"]);
    root ++> live_doc;
    root ++> live_skill;
    root ++> live_cmd;
    live_cmd +>:PointsAtSkill:+> live_skill;
    live_cmd +>:Dispatches(stage="security-scan"):+> live_doc;

    buf = io.StringIO();
    res = run_auditor(buf, root);
    out = buf.getvalue();

    # clean graph: no orphans, no stale, no dangling
    assert res.orphans == [], f"clean graph produced orphans: {res.orphans}";
    assert res.stale_skills == [], (
        f"clean graph produced stale entries: {res.stale_skills}"
    );
    # "verify-agent" is not a path the auditor treats as a dangling skill ref —
