"""Membership integrity across soft-deleted teams.

Models the NextSpark-js/nextspark #88 gap: MembershipService.get(userId,
teamId) returns an active role for a member whose team has been soft-deleted,
because the membership-row lookup never checks teams.deletedAt. The walker
demonstrates the fix: traverse memberships through a typed HasMembership edge
that requires the parent Team to be alive (not soft-deleted). A soft-deleted
team prunes its membership edges, so walkers over HasMembership no longer
reach any member.
"""

node Team {
    has name: str = "";
    has deleted_at: str = "";
}

node User {
    has name: str = "";
    has role: str = "";
    has hierarchy: int = 0;
}

edge HasMembership {
    has permissions: str = "";
}

walker MembershipResolver {
    has target_user: str = "";
    has target_team: str = "";
    has found_role: str = "";
    has found_perms: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan_teams with Team entry {
        if here.deleted_at == "" {
            visit [->:HasMembership:->];
        }
    }

    can resolve with User entry {
        if here.name == self.target_user and self.found_role == "" {
            self.found_role = here.role;
            self.found_perms = "--resolved-via-active-team--";
        }
    }
}

walker IntegrityAudit {
    has active_hits: int = 0;
    has pruned_hits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Team entry {
        if here.deleted_at == "" {
            self.active_hits += 1;
        } else {
            self.pruned_hits += 1;
        }
        visit [->:HasMembership:->];
    }

    can tally with User entry {
        # Membership rows still exist on disk for soft-deleted teams; the
        # walker just never reaches them because HasMembership edges are
        # pruned when the parent team is deleted (see with entry).
        visit [-->];
    }
}

walker ShowBug {
    has alive_team: str = "";
    has dead_team: str = "";
    has alive_role: str = "";
    has dead_role: str = "";

    can start with Root entry {
        visit [-->];
    }

    can show with Team entry {
        if here.deleted_at == "" {
            self.alive_team = here.name;
        } else {
            self.dead_team = here.name;
