Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""VfW codec registry integrity walker.

Models the essential scenario from the Lagarith/VirtualDub2 issue: a host
application (VirtualDub2 build 2.5.3.1197) interacts with the system-wide
Video for Windows driver registry for both 32-bit and 64-bit codecs.
A buggy installer/launch path overwrites the global drivers32 mappings
and breaks every other VfW consumer.

The graph below models that scenario natively:
  - ``RegistryView`` nodes represent the two registry views (32-bit WOW6432Node
    and 64-bit native) plus a third party-app registry view to model collateral
    damage on MSI Afterburner / classic VirtualDub.
  - ``VfWCodec`` nodes represent installed codecs (Lagarith, x264vfw, etc.).
  - The typed ``MapsTo`` edge carries the FOURCC four-character code that
    binds a driver path under a specific registry view.
  - ``HostsBuild`` edges connect the VirtualDub2 build node to the registry
    view it should not touch.
  - ``DependsOn`` edges let the walker trace transitive dependencies
    (e.g. MeGUI -> AVISource -> Lagarith).

A walker ``CodecAuditor`` walks the registry view, records each codec, then
walks the dependency edges to report every consumer that would break if a
codec is wiped. A second walker ``HostInstaller`` demonstrates the buggy
behavior: it traverses a registry view and deletes every ``MapsTo`` edge
hosted there -- exactly the kind of cascade that wipes vidc.lags globally.
"""

node RegistryView {
    has view_name: str = "";
    has architecture: str = "";
}

node VfWCodec {
    has codec_name: str = "";
    has fourcc: str = "";
    has driver_path: str = "";
    has available: bool = True;
}

node HostBuild {
    has build_label: str = "";
    has version: str = "";
}

node AppConsumer {
    has app_name: str = "";
    has role: str = "";
}

edge MapsTo {
    has fourcc_code: str = "";
    has driver_path: str = "";
}

edge HostsBuild { }

edge DependsOn { }

walker CodecAuditor {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with RegistryView entry {
        self.report_lines.append(f"[AUDIT] {here.view_name} ({here.architecture})");
        visit [->:MapsTo:->];
    }

    can record with VfWCodec entry {
        status = "OK" if here.available else "MISSING";
        self.report_lines.append(
            f"  [{status}] fourcc={here.fourcc} name={here.codec_name}"
        );
        visit [->:DependsOn:->];
    }

    can impact with AppConsumer entry {
        self.report_lines.append(
            f"  -> breaks {here.app_name} ({here.role}) via Lagarith dependency"
        );
    }
}

walker HostInstaller {
    has build_label: str = "";
    has removed: list[str] = [];
    has visited_views: list[str] = [];

    can start with Root entry {
        visit [->:HostsBuild:->];
    }

    can target with HostBuild entry {
        visit [-->];
    }

    can wipe with RegistryView entry {
        self.visited_views.append(here.view_name);
        # The buggy behavior: traverse every codec mapping hosted under this
        # registry view and disconnect it. This is the cascade that nukes
        # vidc.lags globally for both 32-bit and 64-bit VfW consumers.
        kids = [->:MapsTo:->];
        for n in kids {
            here del ->:MapsTo:-> n;
            n.available = False;
            self.removed.append(n.fourcc);
        }
    }
}

with entry {
    # Two system-wide registry views (the ones the issue names) plus a third
    # party-app registry view that demonstrates collateral damage.
    sys32 = RegistryView(
        view_name="HKLM\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\Drivers32",
        architecture="32-bit",
    );
    sys64 = RegistryView(
        view_name="HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Drivers32",
        architecture="64-bit",
    );
    thirdparty = RegistryView(
        view_name="MSI Afterburner\\VfW",
        architecture="32-bit",
    );

    # Codecs installed system-wide (the ones that must survive).
    lagarith = VfWCodec(
        codec_name="Lagarith Lossless Codec",
        fourcc="LAGS",
        driver_path="C:\\Windows\\SysWOW64\\lagarith.dll",
    );
    lagarith64 = VfWCodec(
        codec_name="Lagarith Lossless Codec (x64)",
        fourcc="LAGS",
        driver_path="C:\\Windows\\System32\\lagarith64.dll",
    );
    x264vfw = VfWCodec(
        codec_name="x264vfw",
        fourcc="H264",
        driver_path="C:\\Windows\\System32\\x264vfw64.dll",
    );

    # Apps that depend on Lagarith being present.
    megui = AppConsumer(app_name="MeGUI", role="encoder via AviSynth AVISource()");
    afterburner = AppConsumer(app_name="MSI Afterburner", role="video capture");
    classic_vdub = AppConsumer(app_name="VirtualDub 1.x", role="legacy editor");

    # Wire the registry views onto root.
    root ++> sys32;
    root ++> sys64;
    root ++> thirdparty;

    # Bind each codec to the registry view it lives under, via typed edges
    # that carry the FOURCC and driver path -- exactly the registry payload
    # the issue says gets wiped.
    sys32 +>:MapsTo(fourcc_code="vidc.LAGS", driver_path=lagarith.driver_path):+> lagarith;
    sys64 +>:MapsTo(fourcc_code="vidc.LAGS", driver_path=lagarith64.driver_path):+> lagarith64;
    thirdparty +>:MapsTo(fourcc_code="vidc.H264", driver_path=x264vfw.driver_path):+> x264vfw;

    # Codec -> consumer dependencies.
    lagarith +>:DependsOn:+> megui;
    lagarith +>:DependsOn:+> afterburner;
    lagarith64 +>:DependsOn:+> megui;
    lagarith64 +>:DependsOn:+> classic_vdub;

    # Host build -> registry views it should not touch.
    vd2 = HostBuild(build_label="VirtualDub2", version="2.5.3.1197");
    root ++> vd2;
    vd2 +>:HostsBuild:+> sys32;
    vd2 +>:HostsBuild:+> sys64;

    # -------- Phase 1: audit the registry before the buggy build touches it.
    print("=== Phase 1: CodecAuditor walks the registry ===");
    auditor = CodecAuditor();
    root spawn auditor;
    for line in auditor.report_lines {
        print(line);
    }

    # -------- Phase 2: the buggy installer cascade-deletes every mapping.
    print("\n=== Phase 2: HostInstaller (buggy VirtualDub2 2.5.3.1197) ===");
    installer = HostInstaller(build_label="VirtualDub2");
    root spawn installer;
    print(f"installer scanned views: {installer.visited_views}");
    print(f"install mappings removed (fourcc codes): {installer.removed}");
    print(
        f"lagarith available now? {lagarith.available}; "
        f"lagarith64 available now? {lagarith64.available}; "
        f"x264vfw available now? {x264vfw.available}"
    );

    # -------- Phase 3: re-audit. Lagarith is gone from both system views,
    # so every dependent app is now broken.
    print("\n=== Phase 3: CodecAuditor re-audit after the buggy install ===");
    auditor2 = CodecAuditor();
    root spawn auditor2;
    for line in auditor2.report_lines {
        print(line);
    }
}
