Retirement semantics are modelled with `canon_status`:
    "active"     -- normal authoring surface
    "deprecated" -- retired; excluded from active list/outline/context
                    but reachable through explicit history access

A walker walks the chapter subtree and reports which descendants are
active vs deprecated, which is exactly the question the issue raises
about `episode_list` leaking retired rows.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Chapter {
    has title: str = "";
    has canon_status: str = "active";
    has active_position: int = 0;
}

node Episode {
    has title: str = "";
    has canon_status: str = "active";
    has active_position: int = 0;
}

node Scene {
    has title: str = "";
    has canon_status: str = "active";
    has active_position: int = 0;
}

# ---------------------------------------------------------------------------
# Typed edges -- the relationship carries meaning, so it deserves a name.
# ---------------------------------------------------------------------------

edge ContainsEpisode { }
edge ContainsScene { }

# ---------------------------------------------------------------------------
# Walker: traverse the hierarchy and report what is active vs retired.
#
# This is the "episode_list leak" the issue describes: without a canon_status
# filter, every row shows up regardless of whether it has been retired.
# ---------------------------------------------------------------------------

walker OutlineAuditor {
    has include_retired: bool = False;
    has active_episode_count: int = 0;
    has deprecated_episode_count: int = 0;
    has leaked: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_chapter with Chapter entry {
        label = f"[Chapter] {here.title} status={here.canon_status}";
        if here.canon_status == "active" {
            print(label);
            visit [->:ContainsEpisode:->];
        } elif self.include_retired {
            print(f"{label} (history view)");
            visit [->:ContainsEpisode:->];
        } else {
            print(f"{label} -- skipped (retired, default view)");
        }
    }

    can audit_episode with Episode entry {
        if here.canon_status == "active" {
            self.active_episode_count += 1;
            print(f"  active ep pos={here.active_position}: {here.title}");
            visit [->:ContainsScene:->];
        } elif self.include_retired {
            self.deprecated_episode_count += 1;
            print(f"  [history] deprecated ep: {here.title}");
            visit [->:ContainsScene:->];
        } else {
            self.deprecated_episode_count += 1;
            self.leaked.append(here.title) if here.title not in self.leaked else None;
            print(f"  -- excluded retired ep: {here.title}");
        }
    }

    can audit_scene with Scene entry {
        if here.canon_status == "active" {
            print(f"    active scene pos={here.active_position}: {here.title}");
        } elif self.include_retired {
            print(f"    [history] deprecated scene: {here.title}");
        } else {
            print(f"    -- excluded retired scene: {here.title}");
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: rewrite a chapter's structure by retiring a contiguous tail of
# episodes and renumbering the remaining active siblings to a contiguous
# 1..N range. This is the "safe shrink" semantic the issue asks for.
# ---------------------------------------------------------------------------

walker RetireTail {
    has retire_count: int = 0;
    has new_active_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can retire with Chapter entry {
        if here.canon_status != "active" {
            print(f"chapter {here.title} already retired; nothing to do");
            disengage;
        }
        # Walk the chapter's episode children in declaration order, retire
        # the tail, and renumber active survivors.
        kept: list[Episode] = [];
        retired: list[Episode] = [];
        for ep in [->:ContainsEpisode:->] {
            if ep.canon_status == "active" {
                kept.append(ep);
            } else {
                retired.append(ep);
            }
        }
        # The last `retire_count` active episodes become deprecated.
        cut = max(0, len(kept) - self.retire_count);
        survivors = kept[:cut];
        for ep in kept[cut:] {
            ep.canon_status = "deprecated";
            retired.append(ep);
        }
        # Renumber active positions to be contiguous 1..N.
        new_pos = 1;
        for ep in survivors {
            ep.active_position = new_pos;
            new_pos += 1;
        }
        self.new_active_count = len(survivors);
        print(
            f"retired {len(kept) - len(survivors)} episodes from '{here.title}'; "
            f"{self.new_active_count} active remain, renumbered 1..{self.new_active_count}"
        );
        disengage;
    }
}

# ---------------------------------------------------------------------------
# Demo: build Chapter 1 with 10 episodes, retire the last 2, audit twice
# (default active view, then history view including retired).
# ---------------------------------------------------------------------------

with entry {
    chapter = Chapter(title="Chapter 1: The Door Opens");
    root ++> chapter;

    # 10 episodes at positions 1..10
    for i in range(1, 11) {
        title = f"Episode {i}";
        chapter +>:ContainsEpisode:+> Episode(title=title, active_position=i);
    }

    print("=== BEFORE retirement: 10 episodes planned ===");
    pre = OutlineAuditor();
    root spawn pre;
    print(f"active={pre.active_episode_count} deprecated={pre.deprecated_episode_count}");

    print("\n=== Retire the tail (episodes 9 and 10) ===");
    chapter spawn RetireTail(retire_count=2);

    print("\n=== AFTER retirement: default (active-only) view ===");
    post = OutlineAuditor();
    root spawn post;
    print(f"active={post.active_episode_count} deprecated={post.deprecated_episode_count}");
    print(f"retired titles leaked into default view: {post.leaked}");

    print("\n=== AFTER retirement: history view (include retired) ===");
    history = OutlineAuditor(include_retired=True);
    root spawn history;
    print(f"active={history.active_episode_count} deprecated={history.deprecated_episode_count}");
}
```

import io;
import from contextlib { redirect_stdout }

test "default audit lists ten active episodes before shrink" {
    chapter = Chapter(title="Chapter 1: The Door Opens");
    root ++> chapter;
    for i in range(1, 11) {
        chapter +>:ContainsEpisode:+> Episode(title=f"Episode {i}", active_position=i);
    }
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OutlineAuditor();
    }
    out = buf.getvalue();
    assert res.active_episode_count == 10, f"expected 10 active episodes, got {res.active_episode_count}";
    assert res.deprecated_episode_count == 0, f"expected 0 deprecated, got {res.deprecated_episode_count}";
    assert len(res.leaked) == 0, f"unexpected leaked titles before shrink: {res.leaked}";
    assert "active ep pos=1" in out, f"missing first active episode: {out}";
    assert "active ep pos=10" in out, f"missing last active episode: {out}";
}

test "retire tail shrinks chapter to eight contiguous active positions" {
    chapter = Chapter(title="Chapter 1");
    root ++> chapter;
    for i in range(1, 11) {
        chapter +>:ContainsEpisode:+> Episode(title=f"Episode {i}", active_position=i);
    }
    retire_res = chapter spawn RetireTail(retire_count=2);
    assert retire_res.new_active_count == 8, f"expected 8 survivors, got {retire_res.new_active_count}";
    active_count = 0;
    deprecated_count = 0;
    expected_pos = 1;
    for ep in [chapter ->:ContainsEpisode:->] {
        if ep.canon_status == "active" {
            active_count += 1;
            assert ep.active_position == expected_pos, f"expected position {expected_pos}, got {ep.active_position} for {ep.title}";
            expected_pos += 1;
        } elif ep.canon_status == "deprecated" {
            deprecated_count += 1;
        }
    }
    assert active_count == 8, f"expected 8 active episode nodes, got {active_count}";
    assert deprecated_count == 2, f"expected 2 deprecated episode nodes, got {deprecated_count}";
    assert expected_pos == 9, f"expected positions 1..8, stopped at {expected_pos - 1}";
    ep9_found = False;
    ep10_found = False;
    for ep in [chapter ->:ContainsEpisode:->] {
        if ep.title == "Episode 9" {
            assert ep.canon_status == "deprecated", f"Episode 9 should be deprecated, got {ep.canon_status}";
            ep9_found = True;
        }
        if ep.title == "Episode 10" {
            assert ep.canon_status == "deprecated", f"Episode 10 should be deprecated, got {ep.canon_status}";
            ep10_found = True;
        }
    }
    assert ep9_found and ep10_found, f"missing retired tail episodes (ep9={ep9_found}, ep10={ep10_found})";
}

test "default outline excludes retired episodes from active listing" {
    chapter = Chapter(title="Chapter 1");
    root ++> chapter;
    for i in range(1, 11) {
        ep = Episode(title=f"Episode {i}", active_position=i);
        chapter +>:ContainsEpisode:+> ep;
        if i >= 9 {
            ep +>:ContainsScene:+> Scene(title=f"Scene in ep {i}", active_position=1);
        }
    }
    chapter spawn RetireTail(retire_count=2);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OutlineAuditor();
    }
    out = buf.getvalue();
    assert res.active_episode_count == 8, f"default view should list 8 active episodes, got {res.active_episode_count}";
    assert res.deprecated_episode_count == 2, f"expected 2 excluded deprecated episodes, got {res.deprecated_episode_count}";
    assert "active ep pos=8" in out, f"missing last surviving active episode: {out}";
    assert "active ep pos=9" not in out, f"retired episode 9 leaked as active: {out}";
    assert "active ep pos=10" not in out, f"retired episode 10 leaked as active: {out}";
    assert "Scene in ep 9" not in out, f"scene under retired episode 9 leaked: {out}";
    assert "Scene in ep 10" not in out, f"scene under retired episode 10 leaked: {out}";
    assert "Episode 9" in res.leaked, f"Episode 9 should be tracked as excluded: {res.leaked}";
    assert "Episode 10" in res.leaked, f"Episode 10 should be tracked as excluded: {res.leaked}";
}

test "history view surfaces deprecated tail episodes" {
    chapter = Chapter(title="Chapter 1");
    root ++> chapter;
    for i in range(1, 11) {
        chapter +>:ContainsEpisode:+> Episode(title=f"Episode {i}", active_position=i);
    }
    chapter spawn RetireTail(retire_count=2);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OutlineAuditor(include_retired=True);
    }
    out = buf.getvalue();
    assert res.active_episode_count == 8, f"history view should still count 8 active, got {res.active_episode_count}";
    assert res.deprecated_episode_count == 2, f"history view should count 2 deprecated, got {res.deprecated_episode_count}";
    assert "[history] deprecated ep" in out, f"missing history markers for deprecated episodes: {out}";
    assert "Episode 9" in out, f"Episode 9 missing from history output: {out}";
    assert "Episode 10" in out, f"Episode 10 missing from history output: {out}";
    assert len(res.leaked) == 0, f"history view should not populate leaked list: {res.leaked}";
}

test "retired chapter skipped in default audit" {
    chapter = Chapter(title="Retired Chapter", canon_status="deprecated");
    root ++> chapter;
    chapter +>:ContainsEpisode:+> Episode(title="Orphan Episode", active_position=1, canon_status="active");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OutlineAuditor();
    }
    out = buf.getvalue();
    assert res.active_episode_count == 0, f"retired chapter should yield 0 active episodes, got {res.active_episode_count}";
    assert "skipped (retired, default view)" in out, f"retired chapter not skipped in default view: {out}";
    assert "active ep" not in out, f"child episodes leaked through retired chapter: {out}";
}

