test "two distinct systems same operation count as two assets" {
    # Bug repro: both endpoints carry operation="EthernetInterfaces" but
    # point to different physical systems. Naive last-segment logic would
    # collapse these to one. The walker must report 2 unique assets.
    rt = root;
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
