    rt ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes(note="binding"):+> sys_a;
    ep_b +>:Exposes(note="binding"):+> sys_b;

    auditor = BlastAuditor();
    wf spawn auditor;

    assert auditor.unique_count == 2, (
        f"expected 2 unique assets, got {auditor.unique_count}; "
        f"seen={auditor.seen}"
