import io;
import from contextlib { redirect_stdout }

# ---------- shared graph builder ----------
def build_tree {
    shared_shape = Shape(kind="circle");
    r = DisplayObject(name="root", shape=shared_shape);
    child_a = DisplayObject(name="btnA");
    child_b = DisplayObject(name="btnB", disposed=True);
    leaf = DisplayObject(name="leaf", shape=Shape(kind="rect"));

    r +>:Child:+> child_a;
    r +>:Child:+> child_b;
    child_a +>:Child:+> leaf;

    rt = Root();
    rt ++> r;
    return [rt, r, child_a, child_b, leaf];
}

# ---------- test 1: cold walk tessellates + prunes ----------
test "cold walk tessellates and prunes disposed" {
    (rt, r_node, child_a, child_b, leaf) = build_tree();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Refresher();
    }
    out = buf.getvalue();

    # Two shapes exist (root's circle, leaf's rect) and neither was pre-tessellated.
    assert res.tessellated_count == 2, f"expected 2 shapes tessellated, got {res.tessellated_count}";

    # Exactly one node was disposed (btnB) -> pruned_count == 1.
    assert res.pruned_count == 1, f"expected 1 pruned child, got {res.pruned_count}";

    # The two shapes should appear in the output (lazy load happened for each).
    assert "circle" in out, f"missing circle tessellation in output: {out}";
    assert "rect" in out, f"missing rect tessellation in output: {out}";

    # Walker's own seen set should contain every visited DisplayObject (root, btnA, leaf).
    # btnB is encountered then disengaged before append; not counted.
    assert len(res.seen) == 3, f"expected 3 visited nodes, got {len(res.seen)}";

    # After cascade invalidation, only alive children remain linked from r_node.
    survivors = [r_node ->:Child:->];
    assert child_a in survivors, "btnA should survive the prune";
    assert child_b not in survivors, "btnB should be pruned";
    assert len(survivors) == 1, f"expected exactly 1 surviving child, got {len(survivors)}";

    # Shape state actually mutated on the shared Shape instance.
    assert r_node.shape is not None and r_node.shape.tessellated, "shared circle should be marked tessellated";
    assert leaf.shape is not None and leaf.shape.tessellated, "leaf rect should be marked tessellated";
}

# ---------- test 2: warm walk reuses tessellated shapes ----------
test "warm walk reuses tessellated shapes" {
    (rt, r_node, _, _, _) = build_tree();

    # First pass: warms the shapes.
    r1 = rt spawn Refresher();
    assert r1.tessellated_count == 2, "first pass must tessellate both shapes";
    assert r1.pruned_count == 1, "first pass must prune btnB";

    # Second pass: both shapes already tessellated, no nodes newly disposed.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        r2 = rt spawn Refresher();
    }
    out = buf.getvalue();

    # No new tessellations on a re-walk; the second pass hits the cached branch.
    assert r2.tessellated_count == 0, f"expected 0 new tessellations, got {r2.tessellated_count}";

    # The "skipped (cached)" marker must appear for warm nodes.
    assert "(cached)" in out, f"expected cached-skip marker in output: {out}";

    # Prune count: nothing newly disposed between the two walks.
    assert r2.pruned_count == 0, f"expected 0 pruned on warm walk, got {r2.pruned_count}";
}

# ---------- test 3: cycle-safe traversal (no infinite loop on shared shape) ----------
test "walker is cycle-safe via seen-set guard" {
    # Build a cycle in the display tree. The walker must not loop forever
    # or over-tessellate. We measure via seen-set length and tessellation count.
    rt = Root();
    a = DisplayObject(name="a");
    b = DisplayObject(name="b");
    a +>:Child:+> b;
    b +>:Child:+> a;  # cycle
    rt ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Refresher();
    }

    # Both visited exactly once despite the cycle.
    assert len(res.seen) == 2, f"cycle caused over-visit: seen={len(res.seen)}";
    # Neither node has a shape, so no tessellations.
    assert res.tessellated_count == 0, f"unexpected tessellations: {res.tessellated_count}";
    # Neither node is disposed, so no prunes.
    assert res.pruned_count == 0, f"unexpected prunes: {res.pruned_count}";
}

# ---------- test 4: cascade pruning removes the disposed branch ----------
test "pruned children are no longer reachable from parent" {
    (rt, r_node, child_a, child_b, leaf) = build_tree();

    # Sanity: before the walk, r_node has two children.
    assert len([r_node ->:Child:->]) == 2, "precondition: r_node should have 2 children";

    _ = rt spawn Refresher();

    # After the walk, btnB has no incoming Child edge from r_node anymore.
    assert child_b not in [r_node ->:Child:->], "disposed child must be pruned";

    # btnA and its descendant leaf are still reachable from r_node.
    assert child_a in [r_node ->:Child:->], "alive child must survive";
    assert leaf in [child_a ->:Child:->], "alive grandchild must survive";
}

