"""Runtime ops: webhook dispatch lifecycle with HMAC signing, SSRF allowlist,
failure-rate trend tracking, and signed-reachability diagnostics.

Models the MCK (Mission Control Kit) runtime-operations workstream as a graph
of runtimes, webhook endpoints, dispatch attempts, and a signed-lifecycle audit.
The HealthAudit walker performs the very traversal the issue describes:
cascade invalidation of unsigned webhooks (no auto-dispatch), HMAC-gated dry-run
preview, per-runtime failure-rate aggregation, and signed vs. reachable
reporting -- all without hand-rolled adjacency maps or recursion plumbing.
"""

# ---- Node archetypes -------------------------------------------------------

node Runtime {
    has name: str = "";
    has failure_count: int = 0;
    has dispatch_count: int = 0;
}

node Webhook {
    has url: str = "";
    has secret_env: str = "";
    has auto_dispatch: bool = False;
    has reachable: bool = False;
    has verified: bool = False;
}

node DispatchAttempt {
    has outcome: str = "";
    has timestamp: str = "";
}

node AuditEntry {
    has action: str = "";
    has detail: str = "";
    has timestamp: str = "";
}

# ---- Typed edges (the relationships that carry meaning) -------------------

edge Owns { }            # Runtime -- Owns --> Webhook
edge Attempted { }       # Webhook -- Attempted --> DispatchAttempt
edge Logged { }          # Webhook -- Logged --> AuditEntry
edge Recorded { }        # Runtime -- Recorded --> AuditEntry

# ---- Walker: HealthAudit --------------------------------------------------

walker HealthAudit {
    has dry_run: bool = True;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Walk owned webhooks out of a runtime; the runtime's own failure-rate
    # aggregation is computed from the AuditEntry spine attached to it.
    can probe_runtime with Runtime entry {
        # Record this visit so cycle-safe traversal is preserved on the
        # Runtime <-> Webhook <-> AuditEntry graph.
        self.visited.append(here.name);

        # Aggregate failure rate from any DispatchAttempts attached via
        # AuditEntry spines reachable through Owned webhooks.
        total = 0;
        failures = 0;
        for wh in [->:Owns:->] {
            for att in [wh->:Attempted:->] {
                total += 1;
                if att.outcome != "ok" {
                    failures += 1;
                }
            }
        }
        if total > 0 {
            print(f"[runtime] {here.name}: {failures}/{total} failures "
                  f"({(failures * 100) // total}% failure rate)");
        } else {
            print(f"[runtime] {here.name}: no dispatch history");
        }
        visit [-->];
    }

    # The sign-and-route step: reachable != verified, signed live + dry-run
    # require a non-empty HMAC secret env; unsigned 2xx still proves transport.
    can audit_webhook with Webhook entry {
        signable = here.secret_env != "";
        label_reachable = "reachable" if here.reachable else "unreachable";
        label_verified = "verified" if here.verified else "unverified";

        if not signable {
            # Fail-closed: no auto-dispatch without a signing secret.
            here.auto_dispatch = False;
            print(f"[webhook] {here.url}: {label_reachable}, {label_verified}, "
                  f"auto-dispatch DISABLED (no HMAC secret)");
            visit [-->];
            return;
        }

        if here.verified {
            here.auto_dispatch = True;
            mode = "DRY-RUN" if self.dry_run else "LIVE";
            print(f"[webhook] {here.url}: {label_reachable}, {label_verified}, "
                  f"auto-dispatch ENABLED, {mode} dispatch armed");
        } else {
            here.auto_dispatch = False;
            print(f"[webhook] {here.url}: {label_reachable}, {label_verified}, "
                  f"auto-dispatch DISABLED (signature unverified)");
        }
        visit [-->];
    }

    can record with AuditEntry entry {
        print(f"[audit]   {here.action}: {here.detail}");
        visit [-->];
    }

    can record_attempt with DispatchAttempt entry {
        # Failure-rate accounting: a failed attempt counts toward the parent
        # runtime's failure_count via a follow-up Recorded edge would, but to
        # keep this demo self-contained we just log the outcome.
        print(f"[attempt] {here.timestamp} -> {here.outcome}");
        visit [-->];
    }
}

# ---- Demo wiring ----------------------------------------------------------

with entry {
    # Two runtimes, each owning webhooks with varying HMAC posture.
    hermes = Runtime(name="hermes");
    codex = Runtime(name="codex");

    wh_signed = Webhook(url="http://127.0.0.1:3021/hook/hermes",
                        secret_env="HERMES_HMAC_SECRET",
                        reachable=True, verified=True);
    wh_unsigned_reachable = Webhook(url="http://127.0.0.1:3021/hook/codex",
                                    secret_env="",
                                    reachable=True, verified=False);
    wh_signed_pending = Webhook(url="http://127.0.0.1:3021/hook/codex-2",
                                secret_env="CODEX_HMAC_SECRET",
                                reachable=False, verified=False);

    # Dispatch history: hermes has 1 failure out of 3 attempts; codex is clean.
    a1 = DispatchAttempt(outcome="ok", timestamp="2026-07-19T10:00:00Z");
    a2 = DispatchAttempt(outcome="fail", timestamp="2026-07-19T10:05:00Z");
    a3 = DispatchAttempt(outcome="ok", timestamp="2026-07-19T10:10:00Z");

    # Audit spine: webhook lifecycle entries.
    e1 = AuditEntry(action="add_webhook_signature_secret",
                    detail="HERMES_HMAC_SECRET set (no agent mutation)",
                    timestamp="2026-07-19T09:55:00Z");
    e2 = AuditEntry(action="ssrf_allowlist_check",
                    detail="127.0.0.1 permitted",
                    timestamp="2026-07-19T09:56:00Z");

    # Build the graph.
    root ++> hermes ++> codex;
    hermes +>:Owns:+> wh_signed;
    codex +>:Owns:+> wh_unsigned_reachable;
    codex +>:Owns:+> wh_signed_pending;

    wh_signed +>:Attempted:+> a1;
    wh_signed +>:Attempted:+> a2;
    wh_signed +>:Attempted:+> a3;
    wh_signed +>:Logged:+> e1;
    wh_unsigned_reachable +>:Logged:+> e2;

    # Run the audit.  dry_run=True matches the "dry-run preview" path.
    root spawn HealthAudit(dry_run=True);
}
