"""BananaMoon-QuantumTrust-Review incident model.

Models the scenario where Markdown body text was accidentally entered
as a Git path: a GitTree holds TreeEntry nodes whose name fields are
Markdown fragments (with embedded '/' separators and '#' headings),
which Git interprets as a deep directory tree.

A walker walks the tree and reports the suspicious paths so the
operator can decide which ones to invalidate without rewriting history.
"""

node TreeEntry {
    has name: str = "";
    has is_blob: bool = False;
    has is_markdown_text: bool = False;
    has body_preview: str = "";
}

node GitTree {
    has label: str = "";
}

edge Child {
    has depth: int = 0;
}

walker PathAuditor {
    has suspicious: list = [];
    has max_path_length: int = 80;

    can start with Root entry {
        visit [-->];
    }

    can enter_tree with GitTree entry {
        print(f"scanning tree: {here.label}");
        visit [->:Child:->];
    }

    can inspect_entry with TreeEntry entry {
        slash_count = here.name.count("/");
        looks_like_md = (
            here.name.startswith("#")
            or "### " in here.name
            or here.name.startswith(" ")
        );
        too_long = len(here.name) > self.max_path_length;

        if slash_count > 0 or looks_like_md or too_long {
            severity = "HIGH" if (slash_count > 0 and looks_like_md) else "WARN";
            self.suspicious.append({
                "path": here.name,
                "slashes": slash_count,
                "md": looks_like_md,
                "long": too_long,
                "level": severity,
            });
            print(f"  [{severity}] path with {slash_count} slashes, "
                  f"md={looks_like_md}, len={len(here.name)}");
        }
        visit [->:Child:->];
    }
}

walker CascadeInvalidator {
    has target_path: str = "";

    can start with Root entry {
        visit [-->];
    }

    can descend with GitTree entry {
        visit [->:Child:->];
    }

    can invalidate with TreeEntry entry {
        if here.name == self.target_path or self.target_path in here.name {
            here.is_blob = False;
            here.body_preview = "[INVALIDATED]";
            print(f"invalidated entry carrying path: {here.name[:60]}...");
        }
        visit [->:Child:->];
    }
}

walker AuditSummary {
    has auditor: PathAuditor = PathAuditor();

    can start with Root entry {
        print(f"audit complete: {len(self.auditor.suspicious)} suspicious paths");
    }
}

with entry {
    t1 = GitTree(label="root-tree");
    t2 = GitTree(label="subdir-from-slash");
    t3 = GitTree(label="deep-notion-tree");
    root ++> t1 ++> t2 ++> t3;

    t1 +>:Child(depth=0):+> TreeEntry(name="README.md", is_blob=True);
    t1 +>:Child(depth=0):+> TreeEntry(
        name="src/main.py", is_blob=True
    );

    t2 +>:Child(depth=1):+> TreeEntry(
        name="# BananaMoon Quantum NFT",
        is_blob=True,
        is_markdown_text=True,
        body_preview="### Title\n### Subtitle\n### Overview",
    );

    t3 +>:Child(depth=2):+> TreeEntry(
        name="### Subtitle",
        is_blob=True,
        is_markdown_text=True,
    );
    t3 +>:Child(depth=2):+> TreeEntry(
        name="### Overview\nThis is the body that leaked into the path",
        is_blob=True,
        is_markdown_text=True,
    );
    t3 +>:Child(depth=2):+> TreeEntry(
        name=" ",
        is_blob=True,
        is_markdown_text=True,
    );

    auditor = PathAuditor(max_path_length=80);
    root spawn auditor;

    bad_path = "### Overview\nThis is the body that leaked into the path";
    root spawn CascadeInvalidator(target_path=bad_path);

    root spawn AuditSummary(auditor=auditor);
}
