"""Beta hardening tracker: model issues, waves, and dependencies as a typed graph.

The original issue hand-rolled ownership, ordering, and dependency tracking
as flat lists. Here we lift that machinery into typed edges and a walker that
audits the release readiness by traversing dependencies.
"""

node Issue {
    has id: int = 0;
    has title: str = "";
    has priority: str = "P2";
    has resolved: bool = False;
    has risk_accepted: bool = False;
}

node Wave {
    has label: str = "";
    has order: int = 0;
}

edge WaveOf {
    has slot: int = 0;
}

edge DependsOn {
    has hard: bool = True;
}

edge OwnedBy {
    has owner: str = "";
}

walker BetaAuditor {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_wave with Wave entry {
        self.report.append(f"=== Wave {here.order}: {here.label} ===");
        visit [->:WaveOf:->];
    }

    can audit_issue with Issue entry {
        status = "DONE" if here.resolved else "OPEN";
        if not here.resolved and here.priority == "P0" and not here.risk_accepted {
            self.report.append(
                f"[BLOCKER] #{here.id} {here.title} ({here.priority}) — no risk acceptance"
            );
        } else {
            self.report.append(f"[{status}] #{here.id} {here.title} ({here.priority})");
        }
        visit [->:DependsOn:->];
    }

    can audit_dep with Issue entry {
        mark = "!" if here.priority == "P0" and not here.resolved else " ";
        self.report.append(f"   {mark}-> dep #{here.id} {here.title}");
        visit [->:DependsOn:->];
    }
}

with entry {
