```jac
"""Frame-time scratch-buffer thrash: reserve() and shrink() fight each other.

Models the issue's hot path natively:
- Per-frame scratch buffers for draw batches (reserve on wrong quantity,
  shrink on the right quantity) and for sibling scratches (working set
  matches reserve) for comparison.
- A walker audits each scratch buffer every "frame" and reports whether
  the reserve/shrink pair thrashes (realloc each frame) or amortizes.
"""

node Scratch {
    has name: str = "";
    has reserve_qty: int = 0;
    has working_set: int = 0;
    has floor: int = 512;
    has capacity_after_shrink: int = 0;
    has thrashes: bool = False;
}

node Frame {
    has frame_index: int = 0;
    has draw_commands_len: int = 0;
    has batch_count: int = 0;
}

edge HoldsScratch {}
edge HoldsFrame {}

walker AuditOne {
    can start with Root entry {
        visit [->:HoldsScratch:->];
    }

    can audit with Scratch entry {
        # Mirrors draw.rs: reserve(reserve_qty) then shrink target
        # = 2 * max(working_set, floor).
        effective_working = here.working_set if here.working_set > here.floor else here.floor;
        target = 2 * effective_working;
        # Reserve happens before shrink: capacity grows to >= reserve_qty,
        # then shrink_to(target) drops it if reserve_qty > target.
        capacity_post_reserve = here.reserve_qty;
        post = capacity_post_reserve if capacity_post_reserve <= target else target;
        here.capacity_after_shrink = post;
        # Thrashes if next frame's reserve() would grow again after the shrink.
        here.thrashes = here.reserve_qty > target;
    }
}

walker RunFrames {
    can start with Root entry {
        visit [->:HoldsFrame:->];
    }

    can step with Frame entry {
        root spawn AuditOne();
        visit [->:HoldsFrame:->];
    }
}

with entry {
    # Five baseline cells from the issue, projected into the model.
    cells = [
        ("batches_scratch@fo4-InstituteBioScience", 3949, 296),
        ("batches_scratch@fnv",                     2110, 280),
        ("batches_scratch@fo3",                     1581, 240),
        ("batches_scratch@skyrim",                  2342, 310),
        ("batches_scratch@oblivion",                 325, 305),
        ("gpu_instances_scratch@fo4",               3949, 3949),
        ("previous_models_scratch@fo4",             3949, 3949),
    ];

    for (label, draw_cmds, batch_cnt) in cells {
        root +>:HoldsScratch:+> Scratch(
            name=label,
            reserve_qty=draw_cmds,
            working_set=batch_cnt,
        );
    }

    # Three audit frames, like a short playback window.
    root +>:HoldsFrame:+> Frame(frame_index=0, draw_commands_len=3949, batch_count=296);
    root +>:HoldsFrame:+> Frame(frame_index=1, draw_commands_len=3949, batch_count=296);
    root +>:HoldsFrame:+> Frame(frame_index=2, draw_commands_len=3949, batch_count=296);

    root spawn RunFrames();

    # Final report: which scratches thrash vs. amortize.
    thrash_count = 0;
    sibling_count = 0;
    for s in [root->:HoldsScratch:->] {
        eff = s.working_set if s.working_set > s.floor else s.floor;
        target = 2 * eff;
        if s.thrashes {
            thrash_count += 1;
            print(f"[THRASH] {s.name}: reserve={s.reserve_qty}, "
                  f"working={s.working_set}, shrink_target={target}, "
                  f"cap_after_shrink={s.capacity_after_shrink}");
        } else {
            sibling_count += 1;
            print(f"[OK]     {s.name}: reserve={s.reserve_qty}, "
                  f"working={s.working_set}, "
                  f"cap_after_shrink={s.capacity_after_shrink}");
        }
    }
    print(f"\n{thrash_count} scratch(es) thrash per frame; {sibling_count} amortize.");
}
