    has external_authority: bool = False;
}

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has dbt_name: str = "";
    has source_path: str = "";
}

node Model {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has dbt_name: str = "";
    has model_path: str = "";
    has round_trip_safe: bool = True;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has semantic_sha: str = "";
    has render_profile: str = "";
    has read_only: bool = True;
}

edge Contains {
    has role: str = "";
}

edge DependsOn {
    has logical_reason: str = "";
}

edge Generates {
    has profile: str = "";
}

walker AuthorityAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        print("Auditing one shared Canvas");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_project with Project entry {
        authority = "external dbt" if here.external_authority else "DVT-native";
        print(f"Project {here.title}: {authority}");
