            mode = "round-trip" if here.round_trip_safe else "authority transition required";
            print(f"Model {here.title}: {mode}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_artifact with Artifact entry {
        print(f"Read-only projection {here.title}, profile {here.render_profile}");
    }
}

