test "three tracks chained inline off root" {
    root ++> Track(title="Highway Sun", runtime_min=4)
        ++> Track(title="Desert Wind", runtime_min=5)
        ++> Track(title="Coastline Cruise", runtime_min=6);

    # Root should have exactly one outgoing edge (to the first track).
    assert len([root-->]) == 1, f"root should link to exactly one first track, got {len([root-->])}";

    # Walk the chain forward and confirm titles + runtimes in order.
    titles = [];
    runtimes = [];
    cur = [root-->][0];
    while cur is not None {
        titles.append(cur.title);
        runtimes.append(cur.runtime_min);
        nxt = [cur-->];
        cur = nxt[0] if len(nxt) > 0 else None;
    }

    assert len(titles) == 3, f"expected 3 chained tracks, got {len(titles)}: {titles}";
    assert titles == ["Highway Sun", "Desert Wind", "Coastline Cruise"], f"order wrong: {titles}";
    assert runtimes == [4, 5, 6], f"runtimes wrong: {runtimes}";

    # Chain tail: last track must have no outgoing edges.
    last = [root-->][0];
    while len([last-->]) > 0 {
        last = [last-->][0];
    }
    assert len([last-->]) == 0, "tail track should have no outgoing edges";
