"""SQL knowledge base modeled as a graph: questions belong to sections,
sections belong to categories, and a walker computes a topical index by
traversing typed edges — replacing what would be recursive joins / CTEs
in SQL with native OSP traversal."""

node Question {
    has number: int = 0;
    has prompt: str = "";
    has difficulty: str = "";
    has answer: str = "";
}

node Section {
    has title: str = "";
}

node Category {
    has name: str = "";
}

# A question lives inside a section.
edge HasQuestion {
    has ordinal: int = 0;
}

# A section belongs to a category.
edge BelongsTo {
}

walker IndexBuilder {
    has total_questions: int = 0;
    has sections_seen: list[str] = [];
    has max_per_section: int = 0;

    can start with Root entry {
        # Begin traversal from the categories hanging off root.
        visit [-->];
    }

    can descend with Category entry {
        print(f"=== Category: {here.name} ===");
        # Walk into the sections of this category.
        visit [->:BelongsTo:->];
    }

    can tally with Section entry {
        # Collect every question in this section, in declaration order.
        here_qs: list = [q for q in [-->](?:Question)];
        self.total_questions += len(here_qs);
        self.sections_seen.append(here.title);
        if len(here_qs) > self.max_per_section {
            self.max_per_section = len(here_qs);
        }
        print(f"  Section '{here.title}' -> {len(here_qs)} question(s):");
        for q in here_qs {
            print(f"    Q{q.number} [{q.difficulty}] {q.prompt}");
        }
        # Continue onward to any further sections/categories.
        visit [-->];
    }
}

