# ---------- Edge archetypes (relationship shape carries meaning) ----------

edge Publishes {
    has receipt: str = "";
    has fingerprint: str = "";
}

edge Derives {
    has step_index: int = 0;
}

edge Resolves {
    has candidate_index: int = 0;
    has winner: bool = False;
}

edge Stores {
    has object_key: str = "";
    has availability: str = "available";
}

# ---------- Node archetypes ----------

node Publication {
    has title: str = "";
    has year: int = 0;
    has registry_version: str = "";
    has registry_digest: str = "";
    has received: str = "";
}

node Chart {
    has title: str = "";
    has stable_id: str = "";
    has resolution_status: str = "unknown";
}

node DerivationStep {
    has ordinal: int = 0;
    has rule: str = "";
}

node Artifact {
    has object_key: str = "";
    has availability: str = "available";
    has locator: str = "";
