"""City tourism model: stations connect to hotels and rated attractions.

A walker walks the city graph from the root, but only shortlists
attractions that meet a 4-star minimum. Hotels are silently ignored
because no ability fires for them.
"""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

walker Sightseer {
    has itinerary: list[str] = [];

