        print("Planning city itinerary (4 stars or higher)...");
        visit [-->];
    }

    can hop with Station entry {
        print(f"Arrived at station: {here.name}");
        visit [-->];
    }

    can review with Attraction entry {
        if here.stars >= 4 {
            self.itinerary.append(f"{here.name} ({here.stars} stars)");
        }
        visit [-->];
    }

    can finish with Root entry {
        print("Final itinerary:");
        for stop in self.itinerary {
            print(f"  - {stop}");
        }
    }
}

