"""Data center clearance: each room has a required clearance level; technicians
walk the corridor and are admitted or denied per room. A denied technician
ends the walkthrough immediately (no deeper rooms visited). Report rooms reached."""

node ServerRoom {
    has name: str = "";
    has required_clearance: int = 0;
}

walker Technician {
    has badge: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk with ServerRoom entry {
        if here.required_clearance <= self.clearance {
            self.rooms_reached += 1;
            print(f"{self.badge} (clearance {self.clearance}) ENTERED {here.name} [req {here.required_clearance}]");
            visit [-->];
        } else {
            print(f"{self.badge} (clearance {self.clearance}) DENIED at {here.name} [req {here.required_clearance}] — walkthrough ends");
            disengage;
        }
    }
}

with entry {
    rack_a = ServerRoom(name="Rack A", required_clearance=1);
    rack_b = ServerRoom(name="Rack B", required_clearance=2);
    vault   = ServerRoom(name="Crypto Vault", required_clearance=5);
    rack_c  = ServerRoom(name="Rack C", required_clearance=3);

    root ++> rack_a ++> rack_b ++> vault ++> rack_c;

    # Trainee — cleared for rack_a only; should stop after one room.
    root spawn Technician(badge="Trainee-Alice", clearance=1);

    # Senior — cleared up to rack_c; should skip the vault.
    root spawn Technician(badge="Senior-Bob", clearance=3);

    # Admin — top clearance; reaches every room.
    root spawn Technician(badge="Admin-Cara", clearance=5);

    print("Walkthrough summary: see room-reached counts reported above per technician.");
}
