```jac
"""Spawn tool with permission inheritance and typed async HITL suspension.

Models the essential agentscope-java scenario natively:
- Parent session owns a working directory plus ALLOW/DENY/ASK rules.
- A spawn tool creates a child session that should inherit the parent's
  working directory and (per `inheritParentPermissions`) the parent's rules.
- A child execution can be paused with a typed non-terminal status
  `WAITING_FOR_APPROVAL` (HITL suspension) and later resumed with APPROVE
  or DENY; a CANCEL while waiting tears the child down without orphans.
"""

node Session {
    has session_id: str = "";
    has working_dir: str = "";
}

node Rule {
    has rule_id: str = "";
    has effect: str = "ALLOW";
    has pattern: str = "";
}

node PermissionContext {
    has context_id: str = "";
    has working_dir: str = "";
    has mode: str = "ALLOW";
}

node SpawnedChild {
    has task_id: str = "";
    has status: str = "RUNNING";
    has pending_decision: str = "";
    has last_result: str = "";
}

edge OwnsContext {}
edge HoldsRule {}
edge SpawnedBy {}
edge WaitsForApproval {}
edge ResumedAs {}

walker InheritPermissions {
    has merged_dir: str = "";
    has merged_mode: str = "ALLOW";
    has merged_count: int = 0;
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inherit with Session entry {
        self.merged_dir = here.working_dir;
        line = f"parent working_dir={here.working_dir}";
        self.report.append(line);
        visit [-->];
    }

    can collect with PermissionContext entry {
        here.working_dir = self.merged_dir;
        here.mode = self.merged_mode;
        applied = f"applied working_dir={self.merged_dir} mode={self.merged_mode} to ctx={here.context_id}";
        self.report.append(applied);
        visit [-->];
    }

    can take_rule with Rule entry {
        self.merged_count = self.merged_count + 1;
        entry_line = f"inherited {here.effect} {here.rule_id} -> {here.pattern}";
        self.report.append(entry_line);
        visit [-->];
    }

    can flag_child with SpawnedChild entry {
        here.status = "READY";
        ready_line = f"child task={here.task_id} now READY";
        self.report.append(ready_line);
        visit [-->];
    }
}

walker ApprovalFlow {
    has decision: str = "PENDING";
    has verdict_line: str = "";

    can start with Root entry {
        visit [-->];
    }

    can find_pending with SpawnedChild entry {
        if here.status == "WAITING_FOR_APPROVAL" {
            self.decision = here.pending_decision;
            here.status = "RESUMED";
            resumed_line = f"resume task={here.task_id} with decision={self.decision}";
            self.report_append(resumed_line);
        }
        visit [-->];
    }

    can record with Session entry {
        if self.decision == "APPROVE" {
            self.verdict_line = f"approve -> resumed session={here.session_id} at {here.working_dir}";
        } elif self.decision == "DENY" {
            self.verdict_line = f"deny -> terminal session={here.session_id}";
        } else {
            self.verdict_line = f"cancel -> no orphan for session={here.session_id}";
        }
        visit [-->];
    }

    def report_append(line: str) -> None {
        print(line);
    }
}

with entry {
    parent_rules = [
        Rule(rule_id="R1", effect="ALLOW", pattern="/data/**"),
        Rule(rule_id="R2", effect="DENY", pattern="/secret/**"),
        Rule(rule_id="R3", effect="ASK", pattern="/admin/**"),
    ];
    parent_session = Session(session_id="parent-1", working_dir="/work/parent");
    parent_ctx = PermissionContext(context_id="ctx-parent", working_dir="/work/parent", mode="ALLOW");
    parent_session +>:OwnsContext:+> parent_ctx;
    parent_session +>:HoldsRule:+> parent_rules[0];
    parent_session +>:HoldsRule:+> parent_rules[1];
    parent_session +>:HoldsRule:+> parent_rules[2];

    child_session = Session(session_id="child-1", working_dir="/work/child");
    child_ctx = PermissionContext(context_id="ctx-child", working_dir="", mode="DENY");
    child_rule = Rule(rule_id="C1", effect="ALLOW", pattern="/child/private/**");
    child_session +>:OwnsContext:+> child_ctx;
    child_ctx +>:HoldsRule:+> child_rule;

    spawned = SpawnedChild(task_id="task-1", status="PENDING_INHERIT");
    child_session +>:SpawnedBy:+> spawned;

    inherit = InheritPermissions();
    parent_session spawn inherit;

    print("=== inheritance ===");
    for line in inherit.report {
        print(line);
    }
    print(f"merged rules count={inherit.merged_count}");
    print(f"child ctx working_dir={child_ctx.working_dir} mode={child_ctx.mode}");
    print(f"spawned.status={spawned.status}");

    spawned.status = "RUNNING";
    spawned.pending_decision = "PENDING";
    ask_rule_id = "R3";
    ask_rule = parent_rules[2];
    approval_triggered = False;
    if ask_rule.effect == "ASK" {
        spawned.status = "WAITING_FOR_APPROVAL";
        spawned +>:WaitsForApproval:+> ask_rule;
        approval_triggered = True;
    }
    print(f"ask detected={approval_triggered} -> spawned.status={spawned.status}");

    decide = ApprovalFlow();
    if approval_triggered {
        decide.decision = "APPROVE";
        spawned.pending_decision = "APPROVE";
    } else {
        decide.decision = "DENY";
        spawned.pending_decision = "DENY";
    }
    child_session spawn decide;
    print("=== approval ===");
    print(decide.verdict_line);
    print(f"final spawned.status={spawned.status} last_result={spawned.last_result}");

    spawned +>:ResumedAs:+> child_session;
    print(f"edges: OwnsContext={1}, HoldsRule(parent)={3}, "
          f"HoldsRule(child)={1}, SpawnedBy={1}, "
          f"WaitsForApproval={1}, ResumedAs={1}");
}
