"""G-buffer VRAM audit walker.

Models the docs/engine/memory-budget.md under-count row: a G-buffer is a
chain of attachments (HDR colour, depth, depth_history, plus the FSR
masks). A walker walks the attachment chain using a typed ``Sized``
relationship, totals the live attachment VRAM at each resolution, and
reports whether the row understates the live set. A cycle guard
prevents infinite traversal on cyclic attachment graphs.
"""

node Attachment {
    has name: str = "";
    has bytes_per_pixel: float = 0.0;
    has frames_in_flight: int = 0;
}

node GBufferDocRow {
    has label: str = "";
    has claimed_mb_1080p: float = 0.0;
    has claimed_mb_4k: float = 0.0;
}

edge Sized { }

walker VramAuditor {
    has pixels_1080p: int = 1920 * 1080;
    has pixels_4k: int = 3840 * 2160;
    has audited_total_mb_1080p: float = 0.0;
    has audited_total_mb_4k: float = 0.0;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can tally with GBufferDocRow entry {
        print(f"Auditing doc row: {here.label}");
        print(f"  claimed: ~{here.claimed_mb_1080p:.1f} MB @ 1080p, "
              f"~{here.claimed_mb_4k:.1f} MB @ 4K");
        visit [->:Sized:->];
    }

    can sum_attachment with Attachment entry {
        # Cycle guard: attachment chains must be acyclic.
        if here.name in self.visited {
            print(f"  [CYCLE] revisit {here.name}; stopping walk");
            disengage;
        }
        self.visited.append(here.name);

        bytes_1080p = here.bytes_per_pixel * self.pixels_1080p * here.frames_in_flight;
        bytes_4k = here.bytes_per_pixel * self.pixels_4k * here.frames_in_flight;
        mb_1080p = bytes_1080p / (1024.0 * 1024.0);
        mb_4k = bytes_4k / (1024.0 * 1024.0);
        self.audited_total_mb_1080p += mb_1080p;
        self.audited_total_mb_4k += mb_4k;
        print(f"  + {here.name}: {here.bytes_per_pixel} B/px x "
              f"{here.frames_in_flight} FIF = {mb_1080p:.1f} MB @ 1080p, "
              f"{mb_4k:.1f} MB @ 4K");
        visit [->:Sized:->];
    }
}

with entry {
    hdr = Attachment(name="HDR colour R16G16B16A16_SFLOAT",
                     bytes_per_pixel=8.0, frames_in_flight=2);
    depth = Attachment(name="Depth32F", bytes_per_pixel=4.0,
                        frames_in_flight=2);
    depth_history = Attachment(name="Depth history R32F",
                               bytes_per_pixel=4.0, frames_in_flight=2);
    reactive = Attachment(name="FSR reactive mask R8",
                          bytes_per_pixel=1.0, frames_in_flight=2);
    transparency = Attachment(name="FSR transparency mask R8",
                              bytes_per_pixel=1.0, frames_in_flight=2);
    albedos = Attachment(name="Albedo R8G8B8A8", bytes_per_pixel=4.0,
                         frames_in_flight=2);
    normals = Attachment(name="Normals R8G8B8A8", bytes_per_pixel=4.0,
                         frames_in_flight=2);
    roughness = Attachment(name="Roughness R8", bytes_per_pixel=1.0,
                           frames_in_flight=2);
    metallic = Attachment(name="Metallic R8", bytes_per_pixel=1.0,
                          frames_in_flight=2);

    row = GBufferDocRow(label="G-buffer (8 attachments x 2 FIF)",
                        claimed_mb_1080p=23.0, claimed_mb_4k=47.0);

    hdr +>:Sized:+> depth;
    depth +>:Sized:+> depth_history;
    depth_history +>:Sized:+> reactive;
    reactive +>:Sized:+> transparency;
    transparency +>:Sized:+> albedos;
    albedos +>:Sized:+> normals;
    normals +>:Sized:+> roughness;
    roughness +>:Sized:+> metallic;

    root ++> row;

    auditor = VramAuditor();
    row spawn auditor;

    print("");
    print(f"AUDITED TOTAL: {auditor.audited_total_mb_1080p:.1f} MB @ 1080p, "
          f"{auditor.audited_total_mb_4k:.1f} MB @ 4K");
    print(f"CLAIMED TOTAL:  {row.claimed_mb_1080p:.1f} MB @ 1080p, "
          f"{row.claimed_mb_4k:.1f} MB @ 4K");

    claimed_1080p = row.claimed_mb_1080p;
    claimed_4k = row.claimed_mb_4k;
    audited_1080p = auditor.audited_total_mb_1080p;
    audited_4k = auditor.audited_total_mb_4k;

    factor_1080p = audited_1080p / claimed_1080p if claimed_1080p > 0.0 else 0.0;
    factor_4k = audited_4k / claimed_4k if claimed_4k > 0.0 else 0.0;
    print(f"Row understates live attachment set by {factor_1080p:.1f}x "
          f"at 1080p and {factor_4k:.1f}x at 4K");

    pixel_ratio = 3840 * 2160 / (1920 * 1080);
    total_ratio = audited_4k / audited_1080p if audited_1080p > 0.0 else 0.0;
    print(f"4K/1080p ratio is {total_ratio:.2f}, "
          f"close to the {pixel_ratio}x pixel ratio");
}
