"""Native graph model of download cancellation ownership races."""

node Manga {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Chapter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "QUEUED";
    has generation: int = 0;
    has cancel_requested: bool = False;
    has active: bool = False;
    has pages_written: int = 0;

    def request_cancel() {
        self.cancel_requested = True;
    }

    def cancel_if_requested() -> bool {
        if self.cancel_requested {
            self.state = "CANCELLED";
            self.active = False;
            self.generation += 1;
            return True;
        }
        return False;
    }

    def claim_queued() -> bool {
        if self.state == "QUEUED" and not self.cancel_requested {
            self.state = "RUNNING";
            self.active = True;
            self.generation += 1;
            return True;
        }
        return False;
    }

    def accept_page(worker_generation: int) -> bool {
        if self.state == "RUNNING" and self.active and not self.cancel_requested and self.generation == worker_generation {
            self.pages_written += 1;
            return True;
        }
        return False;
    }

    def publish_success(worker_generation: int) -> bool {
        if self.state == "RUNNING" and self.active and not self.cancel_requested and self.generation == worker_generation {
            self.state = "SUCCESS";
            self.active = False;
            return True;
        }
        return False;
    }
}

node DownloadWorker {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has worker_name: str = "";
}

edge Contains {
    has chapter_number: int = 0;
}

edge Owns {
    has generation: int = 0;
}

edge WorkerRoot { }

walker CancellationSweep {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_manga with Manga entry {
        visit [->:Contains:->] else { disengage; }
    }

    can cancel_requested_chapter with Chapter entry {
        if here.cancel_requested {
            changed = here.cancel_if_requested();
            print(f"cancel sweep: {here.title} -> {here.state} (changed={changed})");
        }
    }
}

walker WorkerDrain {
    has worker_generation: int = 0;

    can start with Root entry {
        visit [->:WorkerRoot:->] else { disengage; }
    }

    can follow_ownership with DownloadWorker entry {
        print(f"worker {here.worker_name} follows its ownership edge");
        visit [->:Owns:->] else { disengage; }
    }

    can enforce_ownership with Chapter entry {
        claimed = here.claim_queued();
        if claimed {
            self.worker_generation = here.generation;
            before_cancel = here.accept_page(self.worker_generation);
            here.request_cancel();
            cancelled = here.cancel_if_requested();
            after_cancel = here.accept_page(self.worker_generation);
            completed = here.publish_success(self.worker_generation);
            print(f"worker race: {here.title} claimed={claimed}, page_before_cancel={before_cancel}, cancelled={cancelled}, page_after_cancel={after_cancel}, success={completed}, state={here.state}");
        } else {
            print(f"worker race: {here.title} claim rejected, state={here.state}");
        }
    }
}

with entry {
    manga = Manga(title="Kira Manga", year=2025);
    queued = Chapter(title="queued-cancel-before-claim", year=2025);
    queued.request_cancel();
    active = Chapter(title="active-cancel-after-claim", year=2025);
    worker = DownloadWorker(title="worker", worker_name="W-1");

    root ++> manga;
    manga +>:Contains(chapter_number=1):+> queued;
    manga +>:Contains(chapter_number=2):+> active;
    root +>:WorkerRoot:+> worker;
    worker +>:Owns(generation=0):+> queued;
    worker +>:Owns(generation=0):+> active;

    root spawn CancellationSweep();
    root spawn WorkerDrain();
}
