"""Merge commit report: typed result from the exact preflight/commit plan.

Models the issue's essential complaint: an app-level walker that scans the
committed tree to rebuild a merge framework after the fact, racing against
branch movement and selecting the wrong (inherited) manifest by lexical-first
order. The fix is to keep the typed result the merge owner already produced,
walk the typed edges from the planner instead of scanning the tree, and never
recompute from live branch tips after commit.
"""

node Branch {
    has name: str = "";
    has tip: str = "";
}

node MergeManifest {
    has manifest_id: str = "";
    has ref: str = "";
    has path: str = "";
}

node Claim {
    has claim_id: str = "";
    has path: str = "";
}

node MergeCommit {
    has commit_sha: str = "";
    has target: str = "";
    has semantic_candidate_count: int = 0;
    has manifest: MergeManifest | None = None;
    has claims: list[Claim] = [];
    has parents: list[Branch] = [];
}

edge PinnedAt {
    has pin_sha: str = "";
}

edge Materialized {
    has path: str = "";
}

edge Committed {
    has commit_sha: str = "";
}

edge Merged {
    has role: str = "";
}


walker MergeReport {
    has report: MergeCommit | None = None;

    can start with Root entry {
        visit [-->];
    }

    can audit with MergeCommit entry {
        self.report = here;
        print(f"audit: commit={here.commit_sha} target={here.target} "
              f"candidates={here.semantic_candidate_count}");
        visit [->:Committed:->];
    }

    can read_manifest with MergeManifest entry {
        if self.report is not None and here is not None {
            self.report.manifest = here;
            print(f"manifest: id={here.manifest_id} path={here.path}");
        }
        visit [->:Materialized:->];
    }

    can tally_claim with Claim entry {
        if self.report is not None {
            self.report.claims.append(here);
            print(f"claim: id={here.claim_id} path={here.path}");
        }
        visit [-->];
    }

    can sweep with Branch entry {
        if self.report is not None {
            self.report.parents.append(here);
            print(f"parent: name={here.name} tip={here.tip}");
        }
        visit [-->];
    }
}


with entry {
    target = Branch(name="master", tip="target-tip");
    src_a = Branch(name="feature/a", tip="a-tip");
    src_b = Branch(name="feature/b", tip="b-tip");

    first_manifest = MergeManifest(
        manifest_id="ps:merge:9f41aaaa",
        ref="refs/merges/9f41aaaa",
        path="merge_manifest/ps:merge:9f41aaaa.yaml"
    );
    first_claims = [
        Claim(claim_id="c-1", path="claims/c-1.yaml"),
        Claim(claim_id="c-2", path="claims/c-2.yaml"),
    ];
    first_commit = MergeCommit(
        commit_sha="first-sha",
        target="master",
        semantic_candidate_count=2
    );
    first_commit.manifest = first_manifest;
    first_commit.parents = [src_a, src_b];

    inherited_manifest = MergeManifest(
        manifest_id="ps:merge:63d7bbbb",
        ref="refs/merges/63d7bbbb",
        path="merge_manifest/ps:merge:63d7bbbb.yaml"
    );

    second_manifest = MergeManifest(
        manifest_id="ps:merge:1d4a9873",
        ref="refs/merges/1d4a9873",
        path="merge_manifest/ps:merge:1d4a9873.yaml"
    );
    second_commit = MergeCommit(
        commit_sha="second-sha",
        target="master",
        semantic_candidate_count=0
    );
    second_commit.manifest = second_manifest;
    second_commit.parents = [src_a, src_b];

    root ++> target;
    target +>:PinnedAt(pin_sha="a-tip"):+> src_a;
    target +>:PinnedAt(pin_sha="b-tip"):+> src_b;
    target ++> inherited_manifest;
    inherited_manifest +>:Materialized(path="claims/legacy.yaml"):+> Claim(claim_id="legacy", path="claims/legacy.yaml");

    first_commit +>:Committed(commit_sha="first-sha"):+> first_manifest;
    for c in first_claims {
        first_manifest +>:Materialized(path=c.path):+> c;
    }

    second_commit +>:Committed(commit_sha="second-sha"):+> second_manifest;

    print("=== second merge report ===");
    second_commit spawn MergeReport();

    print("=== first merge report ===");
    first_commit spawn MergeReport();
}
