```jac
"""Family Genealogy Graph: evidence-backed ancestry and kinship research.

Models PERSON, NAME_VARIANT, EVIDENCE, RESEARCH_TASK as node archetypes.
Relationships are typed edges carrying confidence and source backing.
A PedigreeWalker traverses ancestry chains, a ResearchPlanner walks the
graph collecting unresolved candidates and proposes follow-up tasks, and
an InvalidationWalker cascades a disputed flag through evidence chains so
downstream nodes can react. Cycle policy is explicit because Jac 0.36.1
walkers have no built-in once-per-node visit set.
"""

node Person {
    has name: str = "";
    has birth_year: int = 0;
    has death_year: int = 0;
    has is_hypothesis: bool = False;
}

node NameVariant {
    has spelling: str = "";
    has script: str = "latin";
    has language: str = "und";
}

node Evidence {
    has source_kind: str = "manual";
    has confidence: float = 0.5;
    has verified: bool = False;
}

node ResearchTask {
    has title: str = "";
    has priority: int = 1;
    has resolved: bool = False;
}

edge Kinship {
    has kind: str = "unknown";
    has confidence: float = 0.0;
}

edge NamedAs {
}

edge SupportedBy {
}

edge SuggestedBy {
}

walker PedigreeWalker {
    has seen: list[str] = [];
    has max_depth: int = 4;
    has depth: int = 0;
    has chain: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can step with Person entry {
        pid = here.name;
        already = False;
        for s in self.seen {
            if s == pid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(pid);
        self.chain.append(pid);
        print(f"{'  ' * self.depth}[depth {self.depth}] {pid} "
              f"(hyp={here.is_hypothesis})");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth = self.depth + 1;
        visit [->:Kinship:->];
    }

    can pass_through with NameVariant | Evidence | ResearchTask entry {
        visit [-->];
    }
}

walker ResearchPlanner {
    has tasks: list = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with Person entry {
        pid = here.name;
        already = False;
        for s in self.seen {
            if s == pid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(pid);

        if here.is_hypothesis {
            self.tasks.append({
                "title": f"Confirm identity of hypothetical person {pid}",
                "priority": 2
            });
        }

        visit [here->:SupportedBy:->];
    }

    can scan_evidence with Evidence entry {
        if not here.verified and here.confidence < 0.7 {
            self.tasks.append({
                "title": f"Re-verify {here.source_kind} evidence (conf={here.confidence})",
                "priority": 1
            });
        }
        visit [-->];
    }

    can skip_node with NameVariant | ResearchTask entry {
        visit [-->];
    }
}

walker InvalidationWalker {
    has seen: list[str] = [];
    has reason: str = "disputed";

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Person entry {
        pid = here.name;
        already = False;
        for s in self.seen {
            if s == pid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(pid);
        print(f"invalidating person {pid} due to: {self.reason}");
        visit [-->];
    }

    can flag_evidence with Evidence entry {
        if not here.verified {
            here.confidence = 0.0;
            print(f"  evidence ({here.source_kind}) confidence -> 0.0");
        }
        visit [-->];
    }

    can pass_through with NameVariant | ResearchTask entry {
        visit [-->];
    }
}

with entry {
    p_grandfather = Person(name="Ivan Petrov (grandfather)", birth_year=1920, death_year=1995);
    p_grandmother = Person(name="Maria Petrov", birth_year=1925, death_year=2001);
    p_father = Person(name="Sergei Petrov", birth_year=1950);
    p_mother = Person(name="Anna Ivanova", birth_year=1955);
    p_subject = Person(name="Operator (self)", birth_year=1980);
    p_uncle = Person(name="Pavel Petrov", birth_year=1952);
    p_hypothetical = Person(name="Unnamed maternal grandfather", is_hypothesis=True);
    p_cousin = Person(name="Elena Pavlova", birth_year=1982);

    nv_rus = NameVariant(spelling="Иван Петров", script="cyrillic", language="ru");
    nv_lat = NameVariant(spelling="Ivan Petrov", script="latin", language="en");
    p_grandfather +>:NamedAs:+> nv_rus;
    p_grandfather +>:NamedAs:+> nv_lat;

    ev_birth = Evidence(source_kind="birth_certificate", confidence=0.95, verified=True);
    ev_passport = Evidence(source_kind="old_passport", confidence=0.8, verified=False);
    ev_oral = Evidence(source_kind="family_oral_history", confidence=0.4, verified=False);
    p_grandfather +>:SupportedBy:+> ev_birth;
    p_grandfather +>:SupportedBy:+> ev_passport;
    p_hypothetical +>:SupportedBy:+> ev_oral;

    p_grandfather +>:Kinship(kind="parent_of", confidence=0.95):+> p_father;
    p_grandmother +>:Kinship(kind="parent_of", confidence=0.95):+> p_father;
    p_father +>:Kinship(kind="parent_of", confidence=0.9):+> p_subject;
    p_mother +>:Kinship(kind="parent_of", confidence=0.9):+> p_subject;
    p_grandfather +>:Kinship(kind="parent_of", confidence=0.9):+> p_uncle;
    p_uncle +>:Kinship(kind="parent_of", confidence=0.7):+> p_cousin;
    p_hypothetical +>:Kinship(kind="parent_of", confidence=0.3):+> p_mother;

    p_grandfather +>:Kinship(kind="spouse_of", confidence=0.95):+> p_grandmother;
    p_father +>:Kinship(kind="spouse_of", confidence=0.95):+> p_mother;

    t1 = ResearchTask(title="Locate Ivan's immigration manifest", priority=1);
    t2 = ResearchTask(title="Confirm Anna's paternal line", priority=2);
    root +>:SuggestedBy:+> t1;
    root +>:SuggestedBy:+> t2;

    root ++> p_grandfather
        ++> p_grandmother
        ++> p_father
        ++> p_mother
        ++> p_subject
        ++> p_uncle
        ++> p_hypothetical
        ++> p_cousin;

    print("=== PedigreeWalker: walk ancestry from root ===");
    root spawn PedigreeWalker(max_depth=3);

    print("\n=== ResearchPlanner: collect unresolved candidates ===");
    planner = ResearchPlanner();
    root spawn planner;
    for t in planner.tasks {
        print(f"  proposed task: {t}");
    }

    print("\n=== InvalidationWalker: cascade a 'disputed' flag ===");
    root spawn InvalidationWalker(reason="conflicting birth year across sources");
}
