"""Regression tests for the Family Genealogy Graph program."""

import io;
import from contextlib { redirect_stdout }

test "PedigreeWalker visits ancestry chain in depth order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        gf = Person(name="Ivan", birth_year=1920);
        f = Person(name="Sergei", birth_year=1950);
        subj = Person(name="Self", birth_year=1980);
        rt ++> gf ++> f ++> subj;
        gf +>:Kinship(kind="parent_of", confidence=0.9):+> f;
        f +>:Kinship(kind="parent_of", confidence=0.9):+> subj;
        rt spawn PedigreeWalker(max_depth=5);
    }
    out = buf.getvalue();
    assert "[depth 0] Ivan" in out, f"missing Ivan: {out}";
    assert "[depth 1] Sergei" in out, f"missing Sergei: {out}";
    assert "[depth 2] Self" in out, f"missing Self: {out}";
    assert "Ivan" in out and "Sergei" in out and "Self" in out, f"got: {out}";
}

test "PedigreeWalker disengages on cycle so no infinite loop" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        a = Person(name="A");
        b = Person(name="B");
        rt ++> a ++> b;
        a +>:Kinship(kind="parent_of", confidence=0.8):+> b;
        b +>:Kinship(kind="parent_of", confidence=0.3):+> a;
        rt spawn PedigreeWalker(max_depth=10);
    }
    out = buf.getvalue();
    a_count = out.count("[depth");
    assert a_count >= 2 and a_count < 8, f"cycle not bounded, visited {a_count} lines: {out}";
    assert "[depth 0] A" in out, f"missing A: {out}";
    assert "[depth 1] B" in out, f"missing B: {out}";
}

test "ResearchPlanner proposes task for hypothetical person" {
    planner = ResearchPlanner();
    rt = Root();
    hyp = Person(name="Unknown ancestor X", is_hypothesis=True);
    real = Person(name="Known person", is_hypothesis=False);
    ev = Evidence(source_kind="family_oral_history", confidence=0.3, verified=False);
    rt ++> hyp ++> real;
    hyp +>:SupportedBy:+> ev;
    real +>:SupportedBy:+> ev;
    rt spawn planner;
    titles = [t["title"] for t in planner.tasks];
    assert any("Unknown ancestor X" in t for t in titles), f"no hypothesis task: {planner.tasks}";
    assert any("family_oral_history" in t for t in titles), f"no evidence task: {planner.tasks}";
    found_hyp_priority = False;
    for t in planner.tasks {
        if "Unknown ancestor X" in t["title"] {
            found_hyp_priority = t["priority"] == 2;
        }
    }
    assert found_hyp_priority, f"hypothesis task priority wrong: {planner.tasks}";
}

test "ResearchPlanner skips already-verified high-confidence evidence" {
    planner = ResearchPlanner();
    rt = Root();
    p = Person(name="Subject");
    ev_good = Evidence(source_kind="birth_certificate", confidence=0.95, verified=True);
    ev_bad = Evidence(source_kind="family_oral_history", confidence=0.4, verified=False);
    rt ++> p;
    p +>:SupportedBy:+> ev_good;
    p +>:SupportedBy:+> ev_bad;
    rt spawn planner;
    titles = [t["title"] for t in planner.tasks];
    assert not any("birth_certificate" in t for t in titles), f"verified evidence flagged: {planner.tasks}";
    assert any("family_oral_history" in t for t in titles), f"unverified evidence missed: {planner.tasks}";
    for t in planner.tasks {
        if "family_oral_history" in t["title"] {
            assert t["priority"] == 1, f"unverified evidence priority wrong: {t}";
        }
    }
}

test "InvalidationWalker cascades and zeros unverified confidence" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        p = Person(name="Disputed person");
        ev_verified = Evidence(source_kind="court_record", confidence=0.9, verified=True);
        ev_unverified = Evidence(source_kind="family_oral_history", confidence=0.4, verified=False);
        rt ++> p;
        p +>:SupportedBy:+> ev_verified;
        p +>:SupportedBy:+> ev_unverified;
        rt spawn InvalidationWalker(reason="conflicting birth year");
    }
    out = buf.getvalue();
    assert "invalidating person Disputed person" in out, f"no invalidation msg: {out}";
    assert "family_oral_history" in out and "0.0" in out, f"no zero-confidence cascade: {out}";
    assert ev_unverified.confidence == 0.0, f"unverified conf not zeroed: {ev_unverified.confidence}";
    assert ev_verified.confidence == 0.9, f"verified conf wrongly mutated: {ev_verified.confidence}";
}

