test "admin cannot moderate super-admin comment; super-admin can" {
    carol = Author(display_name="carol", role="SuperAdmin");
    super_post = Comment(body="super-only content", created_at="t2", is_deleted=False);
    carol +>:Authored:+> super_post;

    # admin -> super-admin: forbidden, no event, no state change
    forbidden = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="x",
        expected_version=0,
        target_author_role="SuperAdmin"
    );
    super_post spawn forbidden;
    assert forbidden.applied == False, "admin must not moderate super-admin";
    assert forbidden.conflict == "forbidden", f"got {forbidden.conflict!r}";
    assert super_post.is_deleted == False, "comment must remain untouched";
    events = [super_post ->:Moderated:->];
    assert len(events) == 0, "forbidden action must not append any event";

    # super-admin -> super-admin: allowed (highest role)
    allowed = Moderator(
        actor_name="carol",
        actor_role="SuperAdmin",
        action="delete",
        reason="self-moderation",
        expected_version=0,
        target_author_role="SuperAdmin"
    );
    super_post spawn allowed;
    assert allowed.applied, f"super-admin must be able to moderate super-admin, conflict={allowed.conflict}";
    assert super_post.is_deleted == True, "comment must be deleted after super-admin action";
}

test "AuditTrail preserves original body and derives final state from history" {
    (a, c) = fresh_comment_pair();
    # delete then restore -> derived state should end "active"
    d = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    c spawn d;
    assert d.applied, "baseline delete must succeed";

    r = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="restore",
        reason="",
        expected_version=1,
        target_author_role="User"
    );
    c spawn r;
    assert r.applied, "restore must succeed";

    audit = AuditTrail();
    c spawn audit;
    assert audit.comment_body == "Original immutable body.", (
        f"audit must surface ORIGINAL body immutably, got {audit.comment_body!r}"
    );
    assert audit.current_state == "active", (
        f"derived state after delete+restore must be active, got {audit.current_state!r}"
    );
    assert audit.version == 2, f"audit must count 2 events, got {audit.version}";
}

test "deleting a parent never touches its descendants (no cascade)" {
    parent_author = Author(display_name="alice", role="User");
    parent = Comment(body="parent body", created_at="t0", is_deleted=False);
    child  = Comment(body="child body",  created_at="t1", is_deleted=False);
    parent_author +>:Authored:+> parent;
    parent +>:RepliedTo:+> child;

    mod = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    parent spawn mod;
    assert mod.applied, "parent delete must succeed";
    assert parent.is_deleted == True, "parent must be marked deleted";
    assert child.is_deleted == False, "child must NOT cascade-delete";
    # child node must still exist in the graph
    children = [parent ->:RepliedTo:->];
    assert len(children) == 1, "reply edge must be preserved on parent delete";
    assert children[0] == child, "child identity must be preserved";
}

