"""Tests for the ADWF Foundation TraceAuditor walker.

Each test builds its own graph and asserts the fail-closed semantics
the programme specifies: a requirement without `verified=True`, an
intent without `status="LIVE"`, or a decision without `adopted=True`
must flip the audit verdict to FAIL_CLOSED via the cascade walk
(Intent -> Requirement -> Decision and the Invalidates chain).
"""

import io;
import from contextlib { redirect_stdout }

def run_audit(rt) {
    auditor = TraceAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }
    return (auditor, buf.getvalue(), res);
}

test "fully grounded chain yields PASS verdict" {
    rt = root;
    i = Intent(title="LiveIntent", status="LIVE");
    r = Requirement(title="GroundedReq", priority=2, verified=True);
    d = Decision(title="AdoptedDecision", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=3):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == False, f"expected PASS, got findings={auditor.findings}";
    assert "intent 'LiveIntent' status=LIVE" in auditor.findings;
    assert "requirement 'GroundedReq' pri=2 verified=True" in auditor.findings;
    assert "decision 'AdoptedDecision' adopted=True" in auditor.findings;
}

test "unverified requirement trips fail-closed verdict" {
    rt = root;
    i = Intent(title="LiveIntent", status="LIVE");
    r = Requirement(title="UnverifiedReq", priority=1, verified=False);
    d = Decision(title="AdoptedDecision", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=3):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == True, f"expected fail-closed, got findings={auditor.findings}";
    assert "  -> requirement 'UnverifiedReq' not verified" in auditor.findings;
}

test "draft intent propagates failure to dependent requirement" {
    rt = root;
    i = Intent(title="DraftIntent", status="DRAFT");
    r = Requirement(title="DepReq", priority=2, verified=True);
    d = Decision(title="AdoptedDecision", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=2):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == True, f"expected fail-closed, got findings={auditor.findings}";
    assert "intent 'DraftIntent' status=DRAFT" in auditor.findings;
    assert "  -> intent 'DraftIntent' is not LIVE" in auditor.findings;
}

test "unadopted decision is reported via Invalidates chain from adopted one" {
    rt = root;
    d_kept = Decision(title="Adopted", rationale="ok", adopted=True);
    d_killed = Decision(title="SkipGate", rationale="premature", adopted=False);

    rt ++> d_kept ++> d_killed;
    d_kept +>:Invalidates(reason="dethroned"):+> d_killed;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == True, f"expected fail-closed, got findings={auditor.findings}";
    assert "decision 'Adopted' adopted=True" in auditor.findings;
    assert "decision 'SkipGate' adopted=False" in auditor.findings;
    assert "  -> decision 'SkipGate' not adopted" in auditor.findings;
}

test "auditor visits each node exactly once per title tag" {
    rt = root;
    i = Intent(title="LiveIntent", status="LIVE");
    r = Requirement(title="Req", priority=1, verified=True);
    d = Decision(title="Adopted", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=3):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, _res) = run_audit(rt);
    tags = auditor.visited;
    assert len(tags) == 3, f"expected 3 unique tags, got {tags}";
    assert "I[LiveIntent/LIVE]" in tags;
    assert "R[Req]" in tags;
    assert "D[Adopted]" in tags;
}

