"""Delivery route dispatch checker.

Each route from a depot carries a cargo weight in tonnes. A route qualifies
for dispatch only when its load is between 2 and 8 tonnes inclusive on the
same leg. Walk every depot and print which routes qualify.
"""

node Route {
    has title: str = "";
    has weight: float = 0.0;

    def qualifies() -> bool {
        return self.weight >= 2.0 and self.weight <= 8.0;
    }
}

node Depot {
    has name: str = "";
}

walker DispatchAuditor {
    can start with Root entry {
        print("Starting depot audit...");
        visit [-->];
    }

    can at_depot with Depot entry {
        print(f"Depot: {here.name}");
        visit [-->];
    }

    can check_route with Route entry {
        label = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  [{label}] {here.title} ({here.weight}t)");
        visit [-->];
    }
}

with entry {
    root ++> Depot(name="North Depot")
        ++> Route(title="N-1", weight=1.5)
        ++> Route(title="N-2", weight=3.0)
        ++> Route(title="N-3", weight=7.5)
        ++> Depot(name="South Depot")
        ++> Route(title="S-1", weight=9.0)
        ++> Route(title="S-2", weight=2.0)
        ++> Route(title="S-3", weight=8.0)
        ++> Route(title="S-4", weight=0.5);
    root spawn DispatchAuditor();
}
