"""A small text-core kernel with typed document-segment relationships and cycle-safe traversal."""

node TextDocument {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has normalized: bool = False;
}

node TextSegment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has text: str = "";
    has start_byte: int = 0;
    has end_byte: int = 0;
}

edge Contains {
    has ordinal: int = 0;
}

edge DerivedFrom {
    has reason: str = "";
}

walker KernelAuditor {
    has remaining_depth: int = 0;

    can start with Root entry {
        print("auditing canonical text kernel");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_document with TextDocument entry {
        print(f"document: {here.title}, normalized={here.normalized}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_segment with TextSegment entry {
        print(f"segment: {here.title} [{here.start_byte}, {here.end_byte})");

        if self.remaining_depth <= 0 {
            print("cycle/depth limit reached; stopping this branch");
            disengage;
        } else {
            self.remaining_depth -= 1;
            visit [->:DerivedFrom:->] else {
                disengage;
            }
        }
    }
}

with entry {
    document = TextDocument(
        title="Canonical text kernel",
        year=2025,
        normalized=True
    );
    first = TextSegment(
        title="Borrowed introduction",
        text="A small deterministic text value.",
        start_byte=0,
        end_byte=36
    );
    second = TextSegment(
        title="Owned continuation",
        text="Unicode-safe segmentation remains here.",
        start_byte=37,
        end_byte=78
    );

    root ++> document;
    document +>:Contains(ordinal=1):+> first;
    document +>:Contains(ordinal=2):+> second;
    first +>:DerivedFrom(reason="normalization result"):+> second;
    second +>:DerivedFrom(reason="intentional cycle for guard demo"):+> first;

    root spawn KernelAuditor(remaining_depth=4);
}
