    s10 = Checkpoint(title="stateless-h10", horizon=10,
                     cumulative_regret=1.0, violations=1,
                     lineage_id="S-10");
    s20 = Checkpoint(title="stateless-h20", horizon=20,
                     cumulative_regret=6.0, violations=2,
                     lineage_id="S-20");
    s50 = Checkpoint(title="stateless-h50", horizon=50,
                     cumulative_regret=8.0, violations=1,
                     invalidated=True, lineage_id="S-50");

    a10 = Checkpoint(title="aware-h10", horizon=10,
                     cumulative_regret=0.4, violations=0,
