    stat_result = stateless spawn SequenceAuditor();
    aware_result = aware spawn SequenceAuditor();

    assert stat_result.visited_count == 3, f"got {stat_result.visited_count}";
    assert aware_result.visited_count == 3, f"got {aware_result.visited_count}";
    assert stat_result.total_regret == 15.0, f"got {stat_result.total_regret}";
