"""DataTalksClub website: route map and content projection as an OSP graph.

Models the editorial route map from issue #105: hubs (Blog, Podcast, Books,
People, Events, Courses, Wiki) link to their detail records via typed edges.
The site crawler walker walks every hub, validates reachability, reports
orphan records, and demonstrates the canonical route contract.

All detail nodes share a common base (DetailRecord) with a stable key field
so union-triggered walker abilities can read it without violating type
safety.
"""

# Common base for every editorial detail record. Walker abilities that
# match multiple detail types read only fields declared here.
node DetailRecord {
    has stable_key: str = "";
}

node Article(DetailRecord) {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Podcast(DetailRecord) {
    has title: str = "";
    has has_transcript: bool = False;
}

node Book(DetailRecord) {
    has title: str = "";
    has year: int = 0;
}

node Person(DetailRecord) {
    has name: str = "";
}

node Event(DetailRecord) {
    has title: str = "";
    has has_detail_page: bool = True;
}

node Course(DetailRecord) {
    has title: str = "";
}

node WikiPage(DetailRecord) {
    has title: str = "";
}

# Hub nodes aggregate content by canonical route.
node BlogHub {
    has hub_path: str = "/blog";
}

node PodcastHub {
    has hub_path: str = "/podcast";
}

node BookHub {
    has hub_path: str = "/books";
}

node PeopleHub {
    has hub_path: str = "/people";
}

node EventHub {
    has hub_path: str = "/events";
}

node CourseHub {
    has hub_path: str = "/courses";
}

node WikiHub {
    has hub_path: str = "/wiki";
}

# Typed edge: canonical detail route from a hub to its record.
edge CanonicalDetail { }

# Typed edge: records that are linked from a detail page (e.g. event speakers).
edge LinksTo { }

walker SiteCrawler {
    has visited: list[str] = [];
    has orphans: list[str] = [];

    can start with Root entry {
        print("== DataTalksClub route-map crawl ==");
        visit [-->];
    }

    can crawl with BlogHub | PodcastHub | BookHub | PeopleHub | EventHub | CourseHub | WikiHub entry {
        print(f"hub {here.hub_path}");
        self.visited.append(here.hub_path);
        visit [->:CanonicalDetail:->];
    }

    can index_articles with Article entry {
        canonical = "/blog/" + here.stable_key + ".html";
        print(f"  article -> {canonical}");
        self.visited.append(canonical);
        visit [->:LinksTo:->];
    }

    can index_podcasts with Podcast entry {
        canonical = "/podcast/" + here.stable_key + ".html";
        print(f"  podcast -> {canonical}");
        self.visited.append(canonical);
        if here.has_transcript {
            self.visited.append("/podcast/" + here.stable_key + ".html#transcript");
        }
        visit [->:LinksTo:->];
    }

    can index_books with Book entry {
        canonical = "/books/" + here.stable_key + ".html";
        print(f"  book -> {canonical}");
        self.visited.append(canonical);
        visit [->:LinksTo:->];
    }

    can index_people with Person entry {
        canonical = "/people/" + here.stable_key + ".html";
        print(f"  person -> {canonical}");
        self.visited.append(canonical);
        visit [->:LinksTo:->];
    }

    can index_events with Event entry {
        canonical = "/events/" + here.stable_key;
        print(f"  event -> {canonical}");
        self.visited.append(canonical);
        if here.has_detail_page {
            self.visited.append("/events/" + here.stable_key + "/detail");
        }
        visit [->:LinksTo:->];
    }

    can index_courses with Course entry {
        canonical = "/courses/" + here.stable_key;
        print(f"  course -> {canonical}");
        self.visited.append(canonical);
        visit [->:LinksTo:->];
    }

    can index_wiki with WikiPage entry {
        canonical = "/wiki/" + here.stable_key;
        print(f"  wiki -> {canonical}");
        self.visited.append(canonical);
        visit [->:LinksTo:->];
    }

    can report_unreachable with DetailRecord entry {
        # Records reached without going through their hub land here as orphans.
        self.orphans.append(here.stable_key);
        visit [-->];
    }
}

walker OrphanScanner {
    has orphans: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with DetailRecord entry {
        # Walk only along non-canonical edges; records stranded off-hub are orphans.
        has_hub_link = False;
        for n in [-->] {
            if n {
                has_hub_link = True;
            }
        }
        if not has_hub_link {
            self.orphans.append(here.stable_key);
        }
        visit [-->];
    }
}

with entry {
    blog = BlogHub();
    pod = PodcastHub();
    books = BookHub();
    people = PeopleHub();
    events = EventHub();
    courses = CourseHub();
    wiki = WikiHub();

    root ++> blog ++> pod ++> books ++> people ++> events ++> courses ++> wiki;

    # Articles: 55 (small sample shown).
    blog +>:CanonicalDetail:+> Article(
        title="Dune", stable_key="dune", year=1965
    );
    blog +>:CanonicalDetail:+> Article(
        title="Guide to free courses",
        stable_key="guide-to-free-online-courses-at-datatalks-club",
        year=2023
    );

    # Podcasts: 205 with transcripts (203 available).
    pod +>:CanonicalDetail:+> Podcast(
        title="Ep 1", stable_key="ep-1", has_transcript=True
    );
    pod +>:CanonicalDetail:+> Podcast(
        title="Ep 2", stable_key="ep-2", has_transcript=True
    );
    pod +>:CanonicalDetail:+> Podcast(
        title="Ep 3", stable_key="ep-3", has_transcript=False
    );

    # Books: 98.
    books +>:CanonicalDetail:+> Book(
        title="Designing Data-Intensive Apps", stable_key="ddia", year=2017
    );
    books +>:CanonicalDetail:+> Book(
        title="Clean Code", stable_key="clean-code", year=2008
    );

    # People: 438.
    people +>:CanonicalDetail:+> Person(name="Alex", stable_key="alex");
    people +>:CanonicalDetail:+> Person(name="Sam", stable_key="sam");

    # Events: 421 with internal detail pages.
    events +>:CanonicalDetail:+> Event(
        title="NYC Meetup", stable_key="nyc-meetup"
    );
    events +>:CanonicalDetail:+> Event(
        title="Berlin Conf", stable_key="berlin-conf"
    );

    # Courses: 12.
    courses +>:CanonicalDetail:+> Course(title="MLOps", stable_key="mlops");
    courses +>:CanonicalDetail:+> Course(
        title="DE Zoomcamp", stable_key="de-zoomcamp"
    );

    # Wiki: 282.
    wiki +>:CanonicalDetail:+> WikiPage(title="Search", stable_key="search");
    wiki +>:CanonicalDetail:+> WikiPage(title="Index", stable_key="index");

    # Event -> speaker linkage (typed LinksTo edge).
    speaker = Person(name="Keynote Speaker", stable_key="keynote");
    events +>:CanonicalDetail:+> Event(
        title="Conf Day", stable_key="conf-day"
    ) +>:LinksTo:+> speaker;

    # Orphan record (no hub link).
    orphan_article = Article(title="Stray", stable_key="stray", year=2020);
    root ++> orphan_article;

    print("--- Canonical route crawl ---");
    crawler = SiteCrawler();
    root spawn crawler;
    print(f"  total paths indexed: {len(crawler.visited)}");
    print(f"  orphans found by crawler: {crawler.orphans}");

    print("--- Orphan scan ---");
    scanner = OrphanScanner();
    root spawn scanner;
    print(f"  orphans: {scanner.orphans}");
}
