"""Co-authorship contact suggester: find second-degree collaborators.

Models researchers as nodes connected by CoAuthored edges. A walker
descends each edge, accumulates direct co-authors, then proposes contacts
exactly two links away that aren't the researcher themselves and aren't
already a direct co-author.
"""

node Researcher {
    has name: str = "";
    has field: str = "";
}

edge CoAuthored {
    has paper: str = "";
}

walker SuggestContacts {
    has direct: list = [];
    has suggestions: list = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Researcher entry {
        self.direct = [];
        self.suggestions = [];
        # First hop: record every direct co-author by name.
        for coauthor in [->:CoAuthored:->] {
            self.direct.append(coauthor.name);
        }
        # Second hop: visit co-authors' co-authors and propose non-self,
        # non-direct contacts.
        for coauthor in [->:CoAuthored:->] {
            for fof in [coauthor->:CoAuthored:->] {
                if fof.name != here.name and fof.name not in self.direct
                        and fof.name not in self.suggestions {
                    self.suggestions.append(fof.name);
                }
            }
        }
        print(f"{here.name} ({here.field}) -> suggestions: {self.suggestions}");
        visit [-->];
    }
}

