```jac
"""Tenant RBAC reconciliation: versioned templates, role instantiation, and recovery-authority safeguard.

Models the core scenario from elsa-workflows/elsa-foundation issue #831:
  - Versioned TenantRoleTemplate nodes (e.g. Workflow Viewer, Tenant Administrator)
  - TenantRole instances created from a template at a point in time
  - PermissionSet nodes carrying flattened permission keys, attached to roles
  - TenantRecoveryConfig marking the permission set required for tenant recovery
  - Reconcile walker walks the typed `IngestedFrom` edge to compare template vs role
  - Removal walker attempts to remove a role and refuses if the recovery authority
    would be lost (effective-permission check, not template-name check)
  - Reconciler walker applies an explicit accept/decline
"""

node PermissionSet {
    has name: str = "";
    has keys: list[str] = [];
}

node TenantRoleTemplate {
    has name: str = "";
    has version: int = 0;
    has permission_keys: list[str] = [];
}

node TenantRole {
    has name: str = "";
    has template_name: str = "";
    has template_version: int = 0;
    has permission_keys: list[str] = [];
    has dirty: bool = False;
}

node TenantRecoveryConfig {
    has required_keys: list[str] = [];
}

# Typed edges: the relationship carries meaning.
edge IngestedFrom {
    has at: str = "";
}

edge Grants {
}

edge Protects {
}

walker Reconcile {
    has newer_version: int = 0;
    has added: list[str] = [];
    has removed: list[str] = [];
    has accepted: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan_templates with TenantRoleTemplate entry {
        # For each role that was ingested from this template lineage,
        # compute the permission delta against the newer template version.
        for role in [-->](?:TenantRole) {
            if role.template_name != here.name {
                continue;
            }
            if role.template_version >= here.version {
                continue;
            }
            old_keys = set(role.permission_keys);
            new_keys = set(here.permission_keys);
            added = list(new_keys - old_keys);
            removed = list(old_keys - new_keys);
            print(
                f"[delta] role={role.name} v{role.template_version}->v{here.version} "
                f"+{added} -{removed}"
            );
            self.added = added;
            self.removed = removed;
            # Accept reconciliation: copy new keys, mark provenance.
            role.permission_keys = list(new_keys);
            role.template_version = here.version;
            role.dirty = False;
            self.accepted = True;
            print(f"[accept] {role.name} now at v{here.version}");
        }
        visit [-->];
    }
}

walker RemovalAttempt {
    has block_reason: str = "";

    can start with Root entry {
        # Walk every role; attempt to remove. If a role is the last source of
        # tenant-recovery authority (effective-permission check), refuse.
        cfg = [-->](?:TenantRecoveryConfig);
        if len(cfg) == 0 {
            print("[removal] no recovery config; removals allowed");
            visit [-->];
            return;
        }
        recovery = cfg[0];
        required = set(recovery.required_keys);

        for role in [-->](?:TenantRole) {
            role_keys = set(role.permission_keys);
            other_keys: set[str] = set();
            for other in [-->](?:TenantRole) {
                if other.name == role.name {
                    continue;
                }
                other_keys = other_keys | set(other.permission_keys);
            }
            would_lose_all = required.issubset(role_keys) and not required.issubset(other_keys);
            if would_lose_all {
                self.block_reason = (
                    f"refusing to remove {role.name}: last source of "
                    f"recovery permissions {list(required)}"
                );
                print(f"[conflict] {self.block_reason}");
                continue;
            }
            print(f"[removed] {role.name}");
            del role;
        }
    }
}

with entry {
    # Recovery configuration: tenant recovery requires audit.read + tenants.manage.
    recovery = TenantRecoveryConfig(
        required_keys=["audit.read", "tenants.manage"],
    );
    root ++> recovery;

    # Versioned template lineage: Tenant Administrator template has bumped from v1 to v2.
    admin_v1 = TenantRoleTemplate(
        name="Tenant Administrator",
        version=1,
        permission_keys=["audit.read", "tenants.manage", "users.invite"],
    );
    admin_v2 = TenantRoleTemplate(
        name="Tenant Administrator",
        version=2,
        permission_keys=["audit.read", "tenants.manage", "users.invite", "billing.read"],
    );
    viewer_v1 = TenantRoleTemplate(
        name="Workflow Viewer",
        version=1,
        permission_keys=["workflows.view"],
    );
    root ++> admin_v1 ++> admin_v2 ++> viewer_v1;

    # Two tenant-local roles instantiated from earlier template versions.
    admin_role = TenantRole(
        name="acme-admin",
        template_name="Tenant Administrator",
        template_version=1,
        permission_keys=["audit.read", "tenants.manage", "users.invite"],
    );
    viewer_role = TenantRole(
        name="acme-viewer",
        template_name="Workflow Viewer",
        template_version=1,
        permission_keys=["workflows.view"],
    );
    admin_role +>:IngestedFrom(at="2024-01-15"):+> admin_v1;
    viewer_role +>:IngestedFrom(at="2024-01-15"):+> viewer_v1;
    root ++> admin_role ++> viewer_role;

    print("--- Reconcile: compare roles against newer templates ---");
    Reconcile() spawn root;

    print("\n--- RemovalAttempt: refuse if last recovery authority ---");
    RemovalAttempt() spawn root;

    print(
        f"\nfinal admin_role keys={admin_role.permission_keys} "
        f"v{admin_role.template_version} dirty={admin_role.dirty}"
    );
}
