"""Tests for the Genealogist walker family-tree traversal."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the same family graph as the demo and capture stdout
def run_genealogist(focus_name: str) -> str {
    nana = Person(name="Ruth", generation=1);
    papa = Person(name="Arthur", generation=1);
    morgan = Person(name="Morgan", generation=2);
    kid1 = Person(name="Iris", generation=3);
    kid2 = Person(name="Felix", generation=3);

    root ++> nana;
    nana +>: ParentOf() :+> morgan;
    papa +>: ParentOf() :+> morgan;
    morgan +>: ParentOf() :+> kid1;
    morgan +>: ParentOf() :+> kid2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Genealogist(focus=focus_name);
    }
    return buf.getvalue();
}

test "focused middle-generation person reports self then parents" {
    out = run_genealogist("Morgan");
    # Self must be reported first, with its generation.
    assert "Studying Morgan (generation 2)" in out, f"missing self line: {out}";
    # [<--] must walk incoming ParentOf edges to both parents.
    assert "  parent: Ruth" in out, f"missing parent Ruth: {out}";
    assert "  parent: Arthur" in out, f"missing parent Arthur: {out}";
    # Children must NOT appear under "parent:" — they are outgoing only.
    assert "  parent: Iris" not in out, f"child leaked as parent: {out}";
    assert "  parent: Felix" not in out, f"child leaked as parent: {out}";
}

test "directly linked list reaches everyone adjacent in either direction" {
    out = run_genealogist("Morgan");
    # [<-->] on Morgan must include both parents and both children.
    line = "";
    for ln in out.split("\n") {
        if "all directly linked" in ln {
            line = ln;
        }
    }
    assert line != "", f"missing adjacency line: {out}";
    for who in ["Ruth", "Arthur", "Iris", "Felix"] {
        assert who in line, f"{who} missing from adjacency: {line}";
    }
    # Four distinct directly-linked people, no duplicates.
    assert line.count("'Ruth'") == 1, f"duplicate Ruth: {line}";
    assert line.count("'Arthur'") == 1, f"duplicate Arthur: {line}";
    assert line.count("'Iris'") == 1, f"duplicate Iris: {line}";
    assert line.count("'Felix'") == 1, f"duplicate Felix: {line}";
}

test "engages through Root child exactly once and disengages on focus" {
    out = run_genealogist("Morgan");
    # Walker enters Root, visits [-->] to its children (only nana is linked
    # from root, not Morgan directly). The study ability on nana won't match
    # focus=Morgan, so it visits [-->] to Morgan, which matches and disengages.
    # Net: exactly one "Studying" line.
    assert out.count("Studying") == 1, f"expected one study, got: {out}";
    # Siblings/grandparents that aren't directly linked must not appear.
    assert "  parent: Morgan" not in out, f"self echoed as parent: {out}";
    # No extra parent lines beyond the two real ones.
    assert out.count("  parent:") == 2, f"wrong parent line count: {out}";
}

test "non-focus focus name prints nothing" {
    # With a focus that isn't in the graph, the study ability never matches,
    # so nothing should be printed at all.
    out = run_genealogist("Nobody");
    assert out.strip() == "", f"expected silence, got: {out!r}";
}

