    out = buf.getvalue();

    assert len(res.installed_cache["worker-A"]) == 2, f"got {res.installed_cache}";
    assert "mcp" in res.installed_cache["worker-A"], f"got {res.installed_cache}";
    assert "container-002" in out, f"replacement was not visited: {out}";
