"""Order auditor: skip invalid orders, halt the walk on fraud flags."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
