        ++> Order(amount=0, valid=False, fraud=False)
        ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=500, valid=True, fraud=True)
        ++> Order(amount=15, valid=True, fraud=False);
    root spawn OrderAuditor();
}
