node Observation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has domain: str = "";
    has residual: str = "";
}

node Interpretation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has explanation: str = "";
    has alternatives_examined: str = "";
}

node Diagnosis {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has signal: str = "stable_adequacy";
    has manifestation: str = "";
    has regime: str = "undetermined";
}

node Assessment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has qualification: str = "";
    has uncertainty: str = "";
    has transition_warranted: bool = False;
}

edge InterpretedAs {
    has basis: str = "";
}

edge AssessedBy {
    has gate: str = "";
}

edge RecursAt {
    has reason: str = "";
}

walker VigilanceMonitor {
    has hops: int = 0;
    has max_hops: int = 8;

    can begin with Root entry {
        print("VER episode traversal started");
        visit [-->] else {
            disengage;
        }
    }

    can observe with Observation entry {
        if self.hops >= self.max_hops {
            print("cycle guard reached before interpretation");
            disengage;
        } else {
            self.hops += 1;
            print(f"observed domain={here.domain}, residual={here.residual}");
            visit [->:InterpretedAs:->] else {
                disengage;
            }
        }
    }

    can interpret with Interpretation entry {
        if self.hops >= self.max_hops {
            print("cycle guard reached before diagnosis");
            disengage;
        } else {
            self.hops += 1;
            print(f"interpretation={here.explanation}");
            print(f"alternatives examined={here.alternatives_examined}");
            visit [->:AssessedBy:->] else {
                disengage;
            }
        }
    }

    can diagnose with Diagnosis entry {
        if self.hops >= self.max_hops {
            print("cycle guard reached during recursive diagnosis");
            disengage;
        } else {
            self.hops += 1;
            print(f"signal={here.signal}, manifestation={here.manifestation}");
            print(f"regime hypothesis={here.regime}");
            visit [->:AssessedBy:->] else {
                disengage;
            }
        }
    }

    can assess with Assessment entry {
        if self.hops >= self.max_hops {
            print("cycle guard stopped recursive monitoring");
            disengage;
        } else {
            self.hops += 1;
            print(f"qualification={here.qualification}");
            print(f"uncertainty={here.uncertainty}");
            print(f"transition warranted={here.transition_warranted}");
            visit [->:RecursAt:->] else {
                disengage;
            }
        }
    }
}

