```jac
"""Session lifecycle, replay, and side-effect boundaries.

Models the core invariant from the issue: a Pi Session transcript owns
identity, persistence, branch selection, resume, fork, and compaction.
OpenPI Workflow execution artifacts sit alongside as branch-scoped
custom entries, but never become a second Session store. A walker audits
each Workflow artifact to decide whether it is safe to reuse (replay),
must be re-executed, or crosses a forbidden boundary.
"""

node Session {
    has session_id: str = "";
    has leaf_entry_id: str = "";
}

node TranscriptEntry {
    has entry_id: str = "";
    has parent_id: str = "";
    has kind: str = "message";
    has readonly_child: bool = False;
}

node WorkflowArtifact {
    has artifact_id: str = "";
    has invocation_kind: str = "side_effecting";
    has cached_result: str = "";
    has branch_scope: str = "";
}

node CustomEntry {
    has entry_id: str = "";
    has parent_id: str = "";
    has payload_kind: str = "projection";
}

edge OwnsTranscript {
    has role: str = "canonical";
}

edge OwnsArtifact {
    has scope: str = "branch";
}

edge ScopedTo {
    has branch_id: str = "";
}

walker LifecycleAuditor {
    has visited_ids: list[str] = [];
    has replayable: list[str] = [];
    has forbidden: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_session with Session entry {
        print(f"[session] id={here.session_id} leaf={here.leaf_entry_id}");
        self.visited_ids.append(here.session_id);
        visit [-->];
    }

    can audit_transcript with TranscriptEntry entry {
        if here.entry_id in self.visited_ids {
            print(f"[cycle] transcript loop at {here.entry_id}; halting descent");
            disengage;
        }
        self.visited_ids.append(here.entry_id);
        label = "READONLY" if here.readonly_child else "MUTATING";
        print(f"[transcript] {here.entry_id} kind={here.kind} mode={label}");
        visit [-->];
    }

    can audit_artifact with WorkflowArtifact entry {
        if here.invocation_kind == "side_effecting" {
            print(f"[forbidden] artifact {here.artifact_id} cannot be replayed (side-effecting)");
            self.forbidden.append(here.artifact_id);
        } elif here.cached_result == "" {
            print(f"[reexec] artifact {here.artifact_id} has no cached result; must re-execute");
        } else {
            print(f"[replay] artifact {here.artifact_id} cached; safe to reuse");
            self.replayable.append(here.artifact_id);
        }
        visit [-->];
    }

    can audit_custom with CustomEntry entry {
        if here.parent_id in self.visited_ids {
            print(f"[ok] custom {here.entry_id} extends transcript");
        } else {
            print(f"[warn] custom {here.entry_id} detached from transcript");
        }
        visit [-->];
    }
}

with entry {
    session = Session(session_id="sess-001", leaf_entry_id="e3");
    e1 = TranscriptEntry(entry_id="e1", parent_id="root", kind="message");
    e2 = TranscriptEntry(entry_id="e2", parent_id="e1", kind="message");
    e3 = TranscriptEntry(entry_id="e3", parent_id="e2", kind="message", readonly_child=True);

    readonly_child = WorkflowArtifact(
        artifact_id="wf-readonly-1",
        invocation_kind="readonly",
        cached_result="result-payload-A",
        branch_scope="br-1"
    );
    side_effect = WorkflowArtifact(
        artifact_id="wf-side-1",
        invocation_kind="side_effecting",
        cached_result="result-payload-B",
        branch_scope="br-1"
    );
    uncached = WorkflowArtifact(
        artifact_id="wf-uncached-1",
        invocation_kind="readonly",
        cached_result="",
        branch_scope="br-1"
    );

    custom = CustomEntry(entry_id="c1", parent_id="e3", payload_kind="projection");

    session +>:OwnsTranscript(role="canonical"):+> e1
        +>:OwnsTranscript:+> e2
        +>:OwnsTranscript:+> e3
        +>:OwnsTranscript:+> custom;

    e3 +>:ScopedTo(branch_id="br-1"):+> readonly_child
        +>:ScopedTo(branch_id="br-1"):+> side_effect
        +>:ScopedTo(branch_id="br-1"):+> uncached;

    auditor = LifecycleAuditor();
    root spawn auditor;

    print(f"replayable={auditor.replayable}");
    print(f"forbidden={auditor.forbidden}");
}
