"""Tracing model: Activity spans, listeners, propagators, and exception records.

Models the ATYA-069 scenario: an Activity (span) holds tags, baggage, and a
parent link. Listeners attach to Activities to react to lifecycle events.
Propagation moves a trace context across a boundary via a Propagator.
Exception recording copies redacted text into a snapshot.

The walker `Auditor` traverses the parent chain from a span back to the root,
detects cycles in parent links (no built-in visited set in jac 0.36.1), and
reports whether the chain is well-formed, malformed (unknown format), or
contains redaction leaks.
"""

node Activity {
    has name: str = "";
    has trace_id: str = "";
    has parent_id: str = "";
    has has_listeners: bool = False;
    has tags_allocated: bool = False;
    has service_name: str = "";
    has exception_text: str = "";
    has redacted: bool = True;
}

node Listener {
    has kind: str = "noop";
}

node Propagator {
    has format: str = "w3c";
    has allow_w3c: bool = True;
    has bounded: bool = True;
}

edge Parent {
    has depth: int = 0;
}

edge Attached {
    has since: str = "";
}

walker Auditor {
    has start_id: str = "";
    has findings: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can audit with Activity entry {
        # Fast path: no listeners means we must NOT have allocated tags yet.
        if not here.has_listeners and here.tags_allocated {
            self.findings.append(f"LEAK: tags allocated on '{here.name}' without listener");
        }

        # Per-span service identity is supposed to be dropped — flag it.
        if here.service_name != "" {
            self.findings.append(f"PER-SPAN SERVICE: '{here.name}' carries '{here.service_name}'");
        }

        # Redaction check: exception text must be empty unless explicitly kept.
        if here.exception_text != "" and here.redacted {
            self.findings.append(f"REDACTED: '{here.name}' exception text was copied");
        }

        # Walk the parent chain via typed edge. Cycle-safe by guard set.
        visit [->:Parent:->];
    }

    can walk with Activity entry {
        # Detached node reached via typed edge — record and continue if
        # not yet visited. (No built-in dedupe, so we guard explicitly.)
        if here.trace_id in ["", "unknown"] {
            self.findings.append(f"MALFORMED: parent link is '{here.parent_id}'");
            disengage;
        }
        if here.name == self.start_id {
            # Back to the start — chain complete.
            disengage;
        }
        visit [->:Parent:->];
    }
}

walker PropagationCheck {
    can begin with Root entry {
        visit [-->];
    }

    can check with Activity entry {
        # Walk attached listeners — typed edge.
        visit [->:Attached:->];
    }

    can inspect with Listener entry {
        if here.kind == "noop" and here != None {
            # Listener present but inactive — still an attachment, fine.
        }
    }

    can examine with Propagator entry {
        if here.format == "w3c" and not here.allow_w3c {
            print(f"PROPAGATOR REJECTED: w3c disabled on {here.format}");
        }
        if here.format != "w3c" and here.bounded {
            print(f"PROPAGATOR OK: non-w3c '{here.format}' is bounded");
        }
    }
}

with entry {
    # Build a small activity graph: a -> b -> c -> d (parent chain).
    a = Activity(name="server.receive", trace_id="abc123");
    b = Activity(name="server.process", trace_id="abc123", parent_id="server.receive");
    c = Activity(name="db.query", trace_id="abc123", parent_id="server.process");
    d = Activity(name="client.send", trace_id="abc123", parent_id="server.receive");

    # Wire the parent chain with typed edges.
    b +>:Parent(depth=1):+> a;
    c +>:Parent(depth=2):+> b;
    d +>:Parent(depth=1):+> a;

    root ++> a ++> b ++> c ++> d;

    # Attach a listener to one activity; leave another listener-less
    # but with tags already allocated (the leak scenario).
    b +>:Attached(since="start"):+> Listener(kind="metrics");

    leak = Activity(name="leak.span", trace_id="", tags_allocated=True);
    root ++> leak;

    # A redacted-exception snapshot.
    err = Activity(name="err.span", trace_id="zz", exception_text="NullReferenceException at line 42");
    root ++> err;

    # A propagator with non-w3c bounded format.
    p = Propagator(format="b3", bounded=True);
    root ++> p;

    # Run the auditor on the leaf of the chain.
    auditor = Auditor(start_id="d");
    d spawn auditor;
    print("AUDIT REPORT:");
    for line in auditor.findings {
        print(f"  - {line}");
    }

    # Run the propagation check.
    checker = PropagationCheck();
    root spawn checker;
}
```

"""Tests for the ATYA-069 tracing model: leak detection, redaction, and
propagator validation through the Auditor and PropagationCheck walkers.

Each test builds its own graph from scratch and spawns the appropriate
walker to verify the scenario the issue specifies.
"""

import io;
import from contextlib { redirect_stdout }

test "auditor detects tag allocation leak on listener-less span" {
    r = Root();
    leak = Activity(name="leak.span", trace_id="t1", tags_allocated=True);
    r ++> leak;
    a = Auditor(start_id="leak.span");
    res = leak spawn a;
    assert any("LEAK" in f for f in res.findings), f"expected LEAK finding, got {res.findings}";
}

test "auditor detects per-span service identity" {
    r = Root();
    s = Activity(name="svc.span", trace_id="t2", service_name="api-gateway");
    r ++> s;
    a = Auditor(start_id="svc.span");
    res = s spawn a;
    assert any("PER-SPAN SERVICE" in f for f in res.findings), f"expected PER-SPAN SERVICE finding, got {res.findings}";
}

test "auditor detects exception text leakage on redacted snapshot" {
    r = Root();
    e = Activity(name="err.span", trace_id="zz", exception_text="NullReferenceException", redacted=True);
    r ++> e;
    a = Auditor(start_id="err.span");
    res = e spawn a;
    assert any("REDACTED" in f for f in res.findings), f"expected REDACTED finding, got {res.findings}";
}

test "auditor reports no findings on a clean span" {
    r = Root();
    clean = Activity(name="clean.span", trace_id="ok");
    r ++> clean;
    a = Auditor(start_id="clean.span");
    res = clean spawn a;
    assert len(res.findings) == 0, f"clean span should have no findings, got {res.findings}";
}

test "propagator walker accepts bounded non-w3c format" {
    r = Root();
    p = Propagator(format="b3", bounded=True);
    r ++> p;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        checker = PropagationCheck();
        r spawn checker;
    }
    out = buf.getvalue();
    assert "PROPAGATOR OK" in out, f"expected PROPAGATOR OK marker, got {out!r}";
    assert "PROPAGATOR REJECTED" not in out, f"unexpected rejection: {out!r}";
}

test "propagator walker rejects w3c when disabled" {
    r = Root();
    bad = Propagator(format="w3c", allow_w3c=False, bounded=True);
    r ++> bad;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        checker = PropagationCheck();
        r spawn checker;
    }
    out = buf.getvalue();
    assert "PROPAGATOR REJECTED" in out, f"expected PROPAGATOR REJECTED, got {out!r}";
}

