"""Toll plaza G-4: collect fares from cars, trucks, and motorcycles, then report revenue."""

node Vehicle {
    has kind: str = "";
    has axles: int = 0;
    has weight_tons: float = 0.0;
}

walker TollCollector {
    has revenue: float = 0.0;
    has cars: int = 0;
    has trucks: int = 0;
    has bikes: int = 0;

    can open_lane with Root entry {
        print("Gate G-4 opening for the sweep...");
        visit [-->];
    }

    can collect with Vehicle entry {
        fare = 0.0;
        label = here.kind;
        if here.kind == "car" {
            fare = 2.50;
            self.cars += 1;
        } elif here.kind == "truck" {
            fare = 2.50 + 0.50 * here.weight_tons;
            self.trucks += 1;
        } elif here.kind == "motorcycle" {
            fare = 1.00;
            self.bikes += 1;
        }
        self.revenue += fare;
        line = f"{label:>11} axles={here.axles:<2} paid ${fare:0.2f}";
        print(line);
        visit [-->];
    }
}

with entry {
    root ++> Vehicle(kind="car", axles=2)
        ++> Vehicle(kind="truck", axles=5, weight_tons=12.0)
        ++> Vehicle(kind="motorcycle", axles=2)
        ++> Vehicle(kind="car", axles=2)
        ++> Vehicle(kind="truck", axles=3, weight_tons=6.5)
        ++> Vehicle(kind="motorcycle", axles=2)
        ++> Vehicle(kind="car", axles=2, weight_tons=1.8);

    collector = TollCollector();
    root spawn collector;

    print(f"G-4 sweep done: cars={collector.cars}, "
          f"trucks={collector.trucks}, motorcycles={collector.bikes}");
    print(f"Total revenue collected: ${collector.revenue:0.2f}");
}
