"""Order auditor: skip invalid orders and halt immediately on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: begin audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged on order amount={here.amount}");
            disengage;
        } elif not here.valid {
            print(f"[SKIP] invalid order amount={here.amount}");
            visit [-->];
        } else {
            print(f"[AUDIT] approved order amount={here.amount}");
            visit [-->];
        }
    }
}

with entry {
    root ++> Order(amount=100)
        ++> Order(amount=50, valid=False)
        ++> Order(amount=200)
        ++> Order(amount=999, fraud=True)
        ++> Order(amount=10);
    root spawn OrderAuditor();
}
