"""Tests for OrderAuditor — skip on invalid, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

test "valid orders are audited in order" {
    root ++> Order(amount=10)
        ++> Order(amount=20)
        ++> Order(amount=30);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=10" in out, f"missing 10: {out}";
    assert "[AUDIT] approved order amount=20" in out, f"missing 20: {out}";
    assert "[AUDIT] approved order amount=30" in out, f"missing 30: {out}";
    assert "[SKIP]" not in out, f"unexpected skip: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";
    assert out.count("[AUDIT]") == 3, f"expected 3 audits, got: {out}";
    i10 = out.index("amount=10");
    i20 = out.index("amount=20");
    i30 = out.index("amount=30");
    assert i10 < i20 < i30, f"audit order wrong: {i10} {i20} {i30}";
}

test "invalid orders are skipped, audit continues" {
    root ++> Order(amount=10)
        ++> Order(amount=50, valid=False)
        ++> Order(amount=20);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[SKIP] invalid order amount=50" in out, f"missing skip: {out}";
    assert "[AUDIT] approved order amount=10" in out, f"missing 10: {out}";
    assert "[AUDIT] approved order amount=20" in out, f"missing 20: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";
    i10 = out.index("amount=10");
    i50 = out.index("amount=50");
    i20 = out.index("amount=20");
    assert i10 < i50 < i20, f"order wrong: {i10} {i50} {i20}";
    assert out.count("[SKIP]") == 1, f"expected 1 skip, got: {out}";
    assert out.count("[AUDIT]") == 2, f"expected 2 audits, got: {out}";
}

test "fraud order halts the entire walk" {
    root ++> Order(amount=10)
        ++> Order(amount=200)
        ++> Order(amount=999, fraud=True)
        ++> Order(amount=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=10" in out, f"missing first audit: {out}";
    assert "[AUDIT] approved order amount=200" in out, f"missing second audit: {out}";
    assert "[HALT] fraud flagged on order amount=999" in out, f"missing halt: {out}";
    # The fourth order must NOT appear — halt terminates the walk.
    assert "amount=10" in out, "amount=10 should appear (first occurrence)";
    assert out.count("amount=10") == 1, f"second order amount=10 must be skipped due to halt: {out}";
    assert out.count("[HALT]") == 1, f"expected 1 halt, got: {out}";
    # Audit must come before halt.
    ihalt = out.index("[HALT]");
    i200 = out.index("amount=200");
    assert i200 < ihalt, f"audit should precede halt: {i200} {ihalt}";
}

test "fraud as the very first order halts before any audit" {
    root ++> Order(amount=500, fraud=True)
        ++> Order(amount=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[HALT] fraud flagged on order amount=500" in out, f"missing halt: {out}";
    assert "[AUDIT]" not in out, f"no audit should occur before halt: {out}";
    assert "amount=10" not in out, f"second order must never be reached: {out}";
}

test "invalid followed by fraud: skip then halt" {
    root ++> Order(amount=10)
