    assert "[AUDIT] approved order amount=10" in out, f"missing 10: {out}";
    assert "[SKIP] invalid order amount=40" in out, f"missing skip 40: {out}";
    assert "[HALT] fraud flagged on order amount=70" in out, f"missing halt 70: {out}";
    assert "amount=5" not in out, f"final order must not be reached after halt: {out}";
    assert out.count("[HALT]") == 1, f"expected exactly 1 halt: {out}";
    assert out.count("[SKIP]") == 1, f"expected exactly 1 skip: {out}";
}

