"""Dungeon crawler: chain of rooms with one treasure vault.

A Hunter walker advances through the dungeon one room at a time,
counting how many rooms it has inspected. The moment it steps into
the treasure room it announces the find and disengages, so no room
after the vault is ever visited.
"""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        if here.is_treasure {
            print(f"Found treasure in '{here.name}' after {self.rooms_seen} rooms!");
            disengage;
        } else {
            print(f"Inspected '{here.name}' ({self.rooms_seen} so far)");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Hidden Passage")
        ++> Room(name="Dragon's Den");

    root spawn Hunter();
}
