        print("Auditing observation provenance");
        visit [->:CatalogEntry:->] else {
            disengage;
        }
    }

    can inspect_file with FileAsset entry {
        self.records_seen += 1;
        print(f"[FILE] {here.title}: {here.original_filename}");
