```jac
"""Deletion Vector index recovery.

Models the Iceberg scan-planning recovery for a snapshot containing
multiple deletion vectors (DVs) that point at the same data file.
The walker mirrors the read-side ``DeleteFileIndex.Builder.build()``
post-pass: byte-identical duplicates are deduplicated, and genuinely
different DVs are unioned instead of being silently dropped. The
table never throws the ``Can't index multiple DVs`` ValidationException
once this recovery walker has indexed the snapshot.
"""

# --- Puffin blob: opaque payload carried by a deletion vector. ---
node PuffinBlob {
    has offset: int = 0;
    has size: int = 0;
    has location: str = "";
    has positions: list[int] = [];
}

# --- Deletion vector: a single Puffin blob keyed to one data file. ---
node DeletionVector {
    has dv_id: str = "";
    has referenced_data_file: str = "";
    has blob: PuffinBlob = PuffinBlob();
}

# --- Data file: the file whose rows are being deleted from. ---
node DataFile {
    has path: str = "";
    has record_count: int = 0;
}

# --- Snapshot: the live delete-manifest entries of one Iceberg snapshot. ---
node Snapshot {
    has snapshot_id: int = 0;
}

# Typed edges -- declared at module level so the visit/connect syntax compiles.
edge ManifestEntry {}     # Snapshot --holds--> DeletionVector | DataFile
edge Targets {}           # DeletionVector --targets--> DataFile
edge IndexedDeletes {}    # Snapshot --indexed--> DeletionVector (post-recovery)

walker IndexRecovery {
    # Per-data-file accumulator of candidate DVs seen in the manifest.
    has dv_by_path: dict[str, list[DeletionVector]] = {};
    # Final, deduplicated / merged DVs per data file.
    has indexed: dict[str, DeletionVector] = {};
    # Track which data files have been seen in this snapshot (one entry per file).
    has seen_files: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can enter_snapshot with Snapshot entry {
        # Clear walker state so a re-spawn is idempotent.
        self.dv_by_path = {};
        self.indexed = {};
        self.seen_files = {};
        visit [->:ManifestEntry:->];
    }

    can collect_dv with DeletionVector entry {
        target = here.referenced_data_file;
        bucket = self.dv_by_path.get(target, []);
        bucket.append(here);
        self.dv_by_path[target] = bucket;
        visit [-->];
    }

    can note_file with DataFile entry {
        self.seen_files[here.path] = True;
        visit [-->];
    }

    def finish_snapshot() -> None {
        # Post-pass: the equivalent of ``Builder.build()`` in Iceberg.
        # We cannot trigger this from a Snapshot exit ability in a way that
        # sees ``here`` reliably across spawn, so we run it directly below
        # after traversal completes; the walker report still carries state.
        for (path, candidates) in self.dv_by_path.items() {
            survivor = self.merge_or_dedup(candidates);
            self.indexed[path] = survivor;
            if len(candidates) > 1 {
                all_same = True;
                first_key = IndexRecovery.blob_key(candidates[0].blob);
                for dv in candidates[1:] {
                    if IndexRecovery.blob_key(dv.blob) != first_key {
                        all_same = False;
                        break;
                    }
                }
                verdict_label = "byte-identical duplicate" if all_same else "merged union";
                print(f"[WARN] {len(candidates)} DVs for {path} -> {verdict_label} ({survivor.blob.positions})");
            }
        }
        report self.indexed;
    }

    # ---- helpers (plain defs, not walker abilities) ----

    static def blob_key(b: PuffinBlob) -> str {
        return f"{b.location}|{b.offset}|{b.size}";
    }

    def merge_or_dedup(candidates: list[DeletionVector]) -> DeletionVector {
        # Case 1: single DV -- nothing to do.
        if len(candidates) == 1 {
            return candidates[0];
        }
        # Case 2: every DV is byte-identical -- keep the first, drop the rest.
        first_key = IndexRecovery.blob_key(candidates[0].blob);
        all_same = True;
        for dv in candidates[1:] {
            if IndexRecovery.blob_key(dv.blob) != first_key {
                all_same = False;
                break;
            }
        }
        if all_same {
            return candidates[0];
        }
        # Case 3: genuinely different DVs -- union the position bitmaps.
        merged: list[int] = [];
        for dv in candidates {
            for p in dv.blob.positions {
                if p not in merged {
                    merged.append(p);
                }
            }
        }
        merged.sort();
        survivor = DeletionVector(
            dv_id=f"merged({candidates[0].dv_id},{candidates[1].dv_id})",
            referenced_data_file=candidates[0].referenced_data_file,
            blob=PuffinBlob(
                offset=0,
                size=sum(d.blob.size for d in candidates),
                location=candidates[0].blob.location,
                positions=merged,
            ),
        );
        return survivor;
    }
}

with entry {
    # --- graph wiring ---------------------------------------------------
    snap = Snapshot(snapshot_id=42);
    root ++> snap;

    df = DataFile(path="s3://warehouse/data/part-00000.parquet", record_count=1000);

    # Manifest entry #1: a "real" DV that deletes rows [10, 20, 30].
    dv_real = DeletionVector(
        dv_id="dv-A",
        referenced_data_file=df.path,
        blob=PuffinBlob(offset=0, size=128, location="s3://warehouse/dv/dv-A.puffin", positions=[10, 20, 30]),
    );
    # Manifest entry #2: byte-identical duplicate (manifest-rewrite race).
    dv_dup = DeletionVector(
        dv_id="dv-A-copy",
        referenced_data_file=df.path,
        blob=PuffinBlob(offset=0, size=128, location="s3://warehouse/dv/dv-A.puffin", positions=[10, 20, 30]),
    );
    # Manifest entry #3: genuinely different DV that deletes [40, 50]
    # -- the spec violation that previously bricked the table.
    dv_other = DeletionVector(
        dv_id="dv-B",
        referenced_data_file=df.path,
        blob=PuffinBlob(offset=0, size=128, location="s3://warehouse/dv/dv-B.puffin", positions=[40, 50]),
    );
    snap +>:ManifestEntry:+> dv_real;
    snap +>:ManifestEntry:+> dv_dup;
    snap +>:ManifestEntry:+> dv_other;

    for d in [dv_real, dv_dup, dv_other] {
        d +>:Targets:+> df;
    }

    # --- run the recovery walker -----------------------------------
    print(f"Before recovery: snapshot {snap.snapshot_id} has 3 DV manifest entries for {df.path}");
    w = IndexRecovery();
    result = root spawn w;
    # Run the post-pass finalize step (mirrors Builder.build()'s final loop).
    w.finish_snapshot();
    print(f"After  recovery: {len(result.indexed)} DV indexed for {df.path}");
    final_dv = result.indexed[df.path];
    print(f"Final DV id={final_dv.dv_id} positions={final_dv.blob.positions} "
          f"(union of all DVs -- no deletes dropped)");
}
