        w.finish_snapshot();
    }
    out = buf.getvalue();
    assert "[WARN]" in out, f"expected recovery warning, got: {out}";
    assert len(res.indexed) == 1, f"expected one recovered index entry, got {len(res.indexed)}";
    final_positions = res.indexed[df.path].blob.positions;
    assert final_positions == [10, 20, 30, 40, 50], f"union dropped deletes: {final_positions}";
}

