"""Apex log lifecycle: refresh an org connection, materialize a log file under a canonical path, and route the raw log to a text editor. Models the essential graph the issue describes: Org -> LogRecord -> LocalFile -> Editor, with traversal that classifies authentication, fetch, and persistence outcomes without leaking tokens."""

node OrgConnection {
    has alias: str = "";
    has authenticated: bool = False;
    has auth_token: str = "REDACTED";
}

node ApexLogRecord {
    has log_id: str = "";
    has duration_ms: int = 0;
    has status: str = "Pending";
    has operation: str = "Fetch";
}

node LocalLogFile {
    has log_id: str = "";
    has canonical_path: str = "";
    has materialized: bool = False;
    has safe: bool = True;
}

node EditorTab {
    has editor_name: str = "IntelliJ";
    has opened_path: str = "";
}

edge Routes {
    has stage: str = "";
}

edge DependsOn {
    has order: int = 0;
}

walker LogPipeline {
    has completed: list[str] = [];
    has failures: list[str] = [];

    can begin with Root entry {
        print("=== Apex Log Lifecycle Pipeline ===");
        visit [->:Routes:->];
    }

    can refresh_org with OrgConnection entry {
        here.authenticated = True;
        here.auth_token = "REDACTED";
        self.completed.append(f"refresh:{here.alias}");
        print(f"[OK] refresh org {here.alias}");
        visit [->:Routes:->];
    }

    can fetch_log with ApexLogRecord entry {
        if here.operation == "Fetch" {
            here.status = "Fetched";
            self.completed.append(f"fetch:{here.log_id}");
            print(f"[OK] fetch log {here.log_id} ({here.duration_ms}ms)");
        }
        visit [->:Routes:->];
    }

    can materialize_file with LocalLogFile entry {
        path_safe = here.log_id != "" and here.canonical_path != "";
        here.safe = path_safe;
        if path_safe {
            here.materialized = True;
            self.completed.append(f"materialize:{here.log_id}");
            print(f"[OK] materialize {here.canonical_path}");
        } else {
            here.materialized = False;
            self.failures.append(f"materialize:{here.log_id}:unsafe-path");
            print(f"[FAIL] materialize rejected unsafe path for {here.log_id}");
        }
        visit [->:Routes:->];
    }

    can open_in_editor with EditorTab entry {
        here.opened_path = "REDACTED";
        self.completed.append(f"open:{here.editor_name}");
        print(f"[OK] open in {here.editor_name} editor");
        visit [->:Routes:->];
    }
}

walker ClassifyOutcome {
    has classification: str = "";

    can start with Root entry {
        visit [->:Routes:->];
    }

    can classify_org with OrgConnection entry {
        cls = "AUTH_OK" if here.authenticated else "AUTH_REQUIRED";
        print(f"  classify Org({here.alias}) -> {cls}");
    }

    can classify_log with ApexLogRecord entry {
        cls = "FETCH_OK" if here.status == "Fetched" else "FETCH_PENDING";
        print(f"  classify ApexLog({here.log_id}) -> {cls}");
    }

    can classify_file with LocalLogFile entry {
        cls = "FILE_OK" if here.materialized else ("FILE_UNSAFE" if not here.safe else "FILE_MISSING");
        print(f"  classify LocalFile({here.log_id}) -> {cls}");
    }

    can classify_editor with EditorTab entry {
        cls = "EDITOR_OK" if here.opened_path != "" else "EDITOR_NO_PATH";
        print(f"  classify EditorTab -> {cls}");
    }
}

with entry {
    org = OrgConnection(alias="MyDevOrg");
    log_rec = ApexLogRecord(log_id="07Lxx0000000001", duration_ms=1234);
    file = LocalLogFile(log_id="07Lxx0000000001", canonical_path="/logs/MyDevOrg/07Lxx0000000001.log");
    editor = EditorTab(editor_name="IntelliJ");

    org +>:Routes(stage="refresh"):+> log_rec;
    log_rec +>:Routes(stage="fetch"):+> file;
    file +>:Routes(stage="open"):+> editor;

    org +>:DependsOn(order=1):+> file;
    log_rec +>:DependsOn(order=2):+> editor;

    root spawn LogPipeline();
    print("--- outcome classification ---");
    root spawn ClassifyOutcome();
    print("pipeline done");
}
