"""Knowledge graph of DSA concepts: nodes + prerequisite edges, walked by an auditor.

Models the VoxMentor backend knowledge graph in idiomatic Jac. Concept nodes
hold the curriculum metadata; typed ``Prereq`` edges carry the prerequisite
relationship. The ``PrerequisiteAuditor`` walker traverses the typed edges
to report reachability and counts the seeded population, replacing the
hand-rolled recursive CTE machinery from the original backend.
"""

node Concept {
    has name: str = "";
    has topic: str = "";
    has difficulty: int = 0;
    has tier: str = "";
}

edge Prereq {
    has weight: float = 1.0;
}

walker PrerequisiteAuditor {
    has target: str = "";
    has visited: list[str] = [];
    has path: list[str] = [];
    has hit: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with Concept entry {
        # Cycle safety: walkers do not dedupe nodes on cyclic graphs.
        if here.name in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.name);
            self.path.append(here.name);
            if here.name == self.target {
                self.hit = True;
                print(f"REACHED '{self.target}' via path: {self.path}");
                visit [-->];
            } else {
                # Report current node, then traverse only prerequisite edges.
                print(f"  visit {here.name} ({here.topic}, tier={here.tier})");
                visit [->:Prereq:->];
            }
        }
    }
}

walker ConceptCounter {
    has counts: int = 0;
    has difficulties: int = 0;
    has tier_filter: str = "";

    can start with Root entry {
        visit [-->];
    }

    can count with Concept entry {
        if self.tier_filter == "" or here.tier == self.tier_filter {
            self.counts += 1;
            self.difficulties += here.difficulty;
        }
        visit [-->];
    }
}

with entry {
    # --- Seed the knowledge graph (a slice of the 50-concept curriculum) ---
    arrays = Concept(name="Arrays", topic="DSA", difficulty=1, tier="foundations");
    strings = Concept(name="Strings", topic="DSA", difficulty=1, tier="foundations");
    sorting = Concept(name="Sorting", topic="DSA", difficulty=2, tier="foundations");
    hashing = Concept(name="Hashing", topic="DSA", difficulty=2, tier="foundations");
    recursion = Concept(name="Recursion", topic="DSA", difficulty=2, tier="foundations");
    trees_b = Concept(name="BinaryTrees", topic="DSA", difficulty=3, tier="trees");
    bst = Concept(name="BST", topic="DSA", difficulty=3, tier="trees");
    heaps = Concept(name="Heaps", topic="DSA", difficulty=3, tier="trees");
    graphs_b = Concept(name="GraphBasics", topic="DSA", difficulty=3, tier="graphs");
    bfs = Concept(name="BFS", topic="DSA", difficulty=4, tier="graphs");
    dfs = Concept(name="DFS", topic="DSA", difficulty=4, tier="graphs");
    dp = Concept(name="DP", topic="DSA", difficulty=5, tier="advanced");
    backtracking = Concept(name="Backtracking", topic="DSA", difficulty=5, tier="advanced");
    greedy = Concept(name="Greedy", topic="DSA", difficulty=4, tier="advanced");
    trie = Concept(name="Trie", topic="DSA", difficulty=4, tier="trees");
    sysdesign = Concept(name="SystemDesign", topic="BE", difficulty=6, tier="capstone");

    # --- Wire prerequisite edges (typed, payload carries weight) ---
    arrays +>:Prereq(weight=1.0):+> sorting;
    arrays +>:Prereq(weight=1.0):+> hashing;
    sorting +>:Prereq(weight=1.0):+> recursion;
    hashing +>:Prereq(weight=1.0):+> recursion;
    recursion +>:Prereq(weight=1.0):+> trees_b;
    trees_b +>:Prereq(weight=1.0):+> bst;
    trees_b +>:Prereq(weight=1.0):+> heaps;
    trees_b +>:Prereq(weight=1.0):+> trie;
    trees_b +>:Prereq(weight=1.0):+> graphs_b;
    graphs_b +>:Prereq(weight=1.0):+> bfs;
    graphs_b +>:Prereq(weight=1.0):+> dfs;
    bfs +>:Prereq(weight=1.0):+> dp;
    dfs +>:Prereq(weight=1.0):+> dp;
    dp +>:Prereq(weight=1.0):+> backtracking;
    dp +>:Prereq(weight=1.0):+> greedy;
    hashing +>:Prereq(weight=1.0):+> trie;
    arrays +>:Prereq(weight=1.0):+> sysdesign;
    hashing +>:Prereq(weight=1.0):+> sysdesign;

    # Root owns the seed frontier.
    root ++> arrays ++> strings ++> sorting ++> hashing ++> recursion
        ++> trees_b ++> bst ++> heaps ++> graphs_b ++> bfs ++> dfs
        ++> dp ++> backtracking ++> greedy ++> trie ++> sysdesign;

    # --- Demo 1: walk prerequisites to a target (replaces recursive CTE) ---
    print("=== Prerequisite traversal: Arrays -> DP ===");
    auditor = PrerequisiteAuditor(target="DP");
    root spawn auditor;
    print(f"auditor.hit = {auditor.hit}");

    # --- Demo 2: count and aggregate seeded concepts ---
    print("\n=== Concept population count ===");
    counter = ConceptCounter();
    root spawn counter;
    print(f"seeded concepts = {counter.counts}, "
        f"sum of difficulties = {counter.difficulties}");

    # --- Demo 3: tier breakdown via typed-edge fan-in ---
    print("\n=== Tier breakdown ===");
    advanced = ConceptCounter(tier_filter="advanced");
    root spawn advanced;
    print(f"advanced concepts = {advanced.counts}, "
        f"sum of difficulties = {advanced.difficulties}");
}
