"""Health-inspect a restaurant kitchen line: check station temperatures and log visits."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
    has violation_flagged: bool = False;
    has visit_count: int = 0;
}

walker Inspector {
    can start with Root entry {
