        print(f"LOG: Inspector visited {here.name} (total visits: {here.visit_count})");
    }
}

with entry {
    grill = Station(name="Grill", temperature=85.0);
    fryer = Station(name="Fryer", temperature=180.0);
    cold_prep = Station(name="Cold Prep", temperature=4.0);

    root ++> grill;
    root ++> fryer;
    root ++> cold_prep;

    root spawn Inspector();
}
