import io;
import from contextlib { redirect_stdout }


test "snapper only modifies the target road and adds a TruncatedFrom edge to a new VirtualAnchor" {
    rt = Root();
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
    );
    victim = Road(
        road_id=1,
        placements=[(699, 63, -689), (740, 64, -700), (780, 65, -710)],
        bridges=[],
        tunnels=[],
    );
    rt ++> donor;
    rt ++> victim;
    donor +>:Anchors(role="head"):+> VirtualAnchor(
        x=666, y=69, z=-669, donor_road_id=0
    );

    snapper = RoadSnapper(donor_anchor=(666, 69, -669), donor_id=0);
    rt spawn snapper;

    # Victim road must now have exactly one outgoing TruncatedFrom edge.
    truncated_edges = [victim ->:TruncatedFrom:->];
    assert len(truncated_edges) == 1, f"expected 1 TruncatedFrom edge, got {len(truncated_edges)}";

    anchor = truncated_edges[0];
    assert isinstance(anchor, VirtualAnchor), f"expected VirtualAnchor, got {type(anchor)}";
    assert anchor.donor_road_id == 0, f"donor_road_id should be 0, got {anchor.donor_road_id}";
    assert (anchor.x, anchor.y, anchor.z) == (666, 69, -669), f"anchor pos wrong: {(anchor.x, anchor.y, anchor.z)}";

    # Donor's original VirtualAnchor edge must be untouched.
    donor_anchors = [donor ->:Anchors:->];
    assert len(donor_anchors) == 1, f"donor should still have its Anchors edge: got {len(donor_anchors)}";
    assert isinstance(donor_anchors[0], VirtualAnchor), "donor anchor must remain a VirtualAnchor";

    # Donor road must NOT have gained a TruncatedFrom edge.
    donor_trunc = [donor ->:TruncatedFrom:->];
    assert len(donor_trunc) == 0, f"donor must not be truncated: got {len(donor_trunc)} edges";
}


