"""Tests for issue #32: reconciliation, repair, reassessment of a changed subject."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test: record-only reconciliation when subject is unchanged ----------
test "record_only_reconciliation_no_material_change" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        quiet = Subject(subject_id="S-002", material_change=False, evidence_intact=True);
        rt +>:Triggers(condition="interruption"):+> quiet;

