    }
    out = buf.getvalue();
    assert "RECONCILE_RECORD_ONLY" in out, f"expected record-only path, got: {out}";
    assert "REPAIR_REQUIRED" not in out, f"must not enter repair path, got: {out}";
}

# ---------- Test: definition/policy/capability repair re-enters Draft -> Release -> Binding -> Reassessment ----------
test "definition_repair_reentry_path" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        changed = Subject(subject_id="S-A", material_change=True, evidence_intact=True);
        rt +>:Triggers(condition="failed_evaluation"):+> changed;

        d = Draft(draft_id="D-1", rationale="def repair", residual_uncertainty="low");
        changed ++> d;

        rel = Release(release_id="R-1.1", version=2, predecessor_evidence="R-1.0 failed");
        d +>:ProducedBy(attempt=1):+> rel;

        b = Binding(binding_id="B-1", scope="prod", environment="prod-east");
        rel +>:Binds(consequence_class="high"):+> b;

        ra = Reassessment(assessment_id="A-1", preregistered=True, result="PENDING", rationale="r1");
        b +>:Reenters(directive="reassess"):+> ra;

        officer = ReconciliationOfficer();
        rt spawn officer;
    }
    out = buf.getvalue();
    assert "REPAIR_REQUIRED" in out, f"must classify as repair, got: {out}";
    assert "repair lineage: Draft D-1" in out, f"missing draft repair line, got: {out}";
    assert "new Release v2 (R-1.1)" in out, f"missing release line, got: {out}";
    assert "re-binding B-1" in out, f"missing binding line, got: {out}";
    assert "PASS_BOUNDED_CLAIM" in out, f"expected bounded-claim pass, got: {out}";
}

# ---------- Test: binding/environment repair re-enters Binding -> Reassessment ----------
test "binding_repair_reentry" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        changed = Subject(subject_id="S-B", material_change=True, evidence_intact=True);
        rt +>:Triggers(condition="binding_drift"):+> changed;

        d = Draft(draft_id="D-2", rationale="env swap", residual_uncertainty="none");
        changed ++> d;

        rel = Release(release_id="R-2.1", version=3, predecessor_evidence="R-2.0 ok");
        d +>:ProducedBy(attempt=1):+> rel;

        b = Binding(binding_id="B-env-prod", scope="production", environment="prod-west");
        rel +>:Binds(consequence_class="high"):+> b;

        ra = Reassessment(assessment_id="A-2", preregistered=True, result="PENDING", rationale="r2");
        b +>:Reenters(directive="reassess_after_repair"):+> ra;

        officer = ReconciliationOfficer();
        rt spawn officer;
    }
    out = buf.getvalue();
    assert "REPAIR_REQUIRED" in out, f"expected repair, got: {out}";
    assert "re-binding B-env-prod" in out, f"missing rebind line, got: {out}";
    assert "PASS_BOUNDED_CLAIM" in out, f"expected pass, got: {out}";
}

# ---------- Test: reassessment fails on missing evidence (no silent pass) ----------
test "reassessment_fails_on_missing_evidence" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        changed = Subject(subject_id="S-M", material_change=True, evidence_intact=False);
        rt +>:Triggers(condition="contradictory_state"):+> changed;

        # No Draft/Release/Binding downstream -> outcome dict stays empty,
        # so reassessment (if present) must fail as missing subject.
        ra = Reassessment(assessment_id="A-M", preregistered=True, result="PENDING", rationale="rM");
        changed ++> ra;

        officer = ReconciliationOfficer();
        rt spawn officer;
    }
    out = buf.getvalue();
    assert "REPAIR_REQUIRED" in out, f"expected repair, got: {out}";
    # The Reassessment is reached as a plain [-->] sibling (not via Binds),
