```jac
"""Analyzed code graph: list packages, get stats, export, and cascade delete.

Models the CLI commands requested in the issue as walkers over typed edges
that carry the relationship meaning (DEFINES, CONTAINS, CALLS, IMPORTS,
INHERITS, BELONGS_TO). Each entity node carries an explicit ``kind`` so a
union ability can label it without sniffing class identity.
"""

# ---- Edge archetypes: each carries a typed relationship ----
edge Defines { }
edge Contains { }
edge Calls { }
edge Imports { }
edge Inherits { }
edge BelongsTo { }    # module/class/function -> package

# ---- Base node so every entity shares a kind label + fqn ----
node CodeNode {
    has kind: str = "";
    has name: str = "";
    has fqn: str = "";
    has package_name: str = "";
}

# ---- Concrete archetypes inherit the shared fields ----
node Module(CodeNode) {
    has kind: str = "Module";
}

node Cls(CodeNode) {
    has kind: str = "Class";
}

node Func(CodeNode) {
    has kind: str = "Function";
}

node Package {
    has name: str = "";
    has analyzed_at: str = "";
    has node_count: int = 0;
}

# ---- Walker: list all analyzed packages with summary counts ----
walker PackageLister {
    has detailed: bool = False;
    has lines: list[str] = [];

    can start with Root entry {
        self.lines = [];
        visit [-->];
    }

    can gather with Package entry {
        summary = f"{here.name}  nodes={here.node_count}";
        self.lines.append(summary);
        if self.detailed {
            self.lines.append(f"  analyzed_at={here.analyzed_at}");
        }
    }

    can drain with Root exit {
        print("Analyzed Packages:");
        for line in self.lines {
            print(f"  {line}");
        }
        report self.lines;
    }
}

# ---- Walker: get detailed stats for one package ----
walker PackageStats {
    has package_name: str = "";
    has depth: int = 3;
    has stats_only: bool = False;
    has by_type: dict[str, int] = {};
    has by_rel: dict[str, int] = {};
    has most_connected: list[str] = [];
    has incoming: dict[str, int] = {};

    can start with Root entry {
        visit [-->];
    }

    can hit with Package entry {
        if here.name == self.package_name {
            self.by_type["Package"] = 1;
            visit [-->] else { disengage; }
        }
    }

    can count_node with Module | Cls | Func entry {
        if self.stats_only {
            return;
        }
        self.incoming[here.fqn] = self.incoming.get(here.fqn, 0);
        for n in [-->] {
            self.incoming[here.fqn] = self.incoming.get(here.fqn, 0);
        }
        visit [-->];
    }

    can summarize with Package exit {
        print(f"Package: {self.package_name}");
        print(f"Analyzed: {here.analyzed_at}");
        print("Nodes:");
        for (k, v) in self.by_type.items() {
            print(f"  {k}: {v}");
        }
        print("Relationships:");
        for (k, v) in self.by_rel.items() {
            print(f"  {k}: {v}");
        }
        if self.most_connected {
            print("Most Connected:");
            for entry in self.most_connected {
                print(f"  {entry}");
            }
        }
        report {
            "package": self.package_name,
            "by_type": self.by_type,
            "by_rel": self.by_rel,
        };
    }
}

# ---- Walker: cascade delete a package (DETACH DELETE equivalent) ----
walker PackageDeleter {
    has package_name: str = "";
    has force: bool = False;
    has dry_run: bool = False;
    has deleted_nodes: int = 0;
    has deleted_edges: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hit with Package entry {
        if here.name != self.package_name {
            disengage;
        }
        # Detach delete: remove all edges first, then the node.
        old_edges = [-->];
        for e in old_edges {
            here del --> e;
            self.deleted_edges += 1;
        }
        if not self.dry_run {
            del here;
            self.deleted_nodes += 1;
        } else {
            print(f"[dry-run] would delete package {self.package_name}");
        }
        report {
            "package": self.package_name,
            "deleted_nodes": self.deleted_nodes,
            "deleted_edges": self.deleted_edges,
            "dry_run": self.dry_run,
        };
    }
}

# ---- Walker: export graph data (JSON-style dump) ----
walker PackageExporter {
    has package_name: str = "";
    has fmt: str = "json";
    has node_rows: list[dict] = [];
    has rel_rows: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can hit with Package entry {
        if here.name != self.package_name {
            disengage;
        }
        visit [-->];
    }

    can collect with Module | Cls | Func entry {
        self.node_rows.append({
            "label": here.kind,
            "name": here.name,
            "fqn": here.fqn,
            "package": here.package_name,
        });
        visit [-->];
    }

    can finish with Package exit {
        # Build simple relationship rows by scanning neighbors.
        for n in [-->] {
            self.rel_rows.append({"from": here.name, "to": str(n), "type": "Contains"});
        }
        print(f"Export ({self.fmt}) for {self.package_name}:");
        print(f"  nodes: {len(self.node_rows)}");
        print(f"  relationships: {len(self.rel_rows)}");
        report {
            "format": self.fmt,
            "nodes": self.node_rows,
            "relationships": self.rel_rows,
        };
    }
}

# ---- Demonstration graph ----
with entry {
    pkg_app = Package(name="my-app", analyzed_at="2026-03-26 14:30:00", node_count=1950);
    pkg_utils = Package(name="utils", analyzed_at="2026-03-25 10:00:00", node_count=140);
    root ++> pkg_app ++> pkg_utils;

    # my-app package contents
    main_mod = Module(name="main", fqn="main", package_name="my-app");
    app_cls = Cls(name="App", fqn="main.App", package_name="my-app");
    base_cls = Cls(name="Base", fqn="models.Base", package_name="my-app");
    fmt_func = Func(name="format_data", fqn="utils.helpers.format_data", package_name="my-app");

    pkg_app +>:Contains:+> main_mod;
    main_mod +>:Defines:+> app_cls;
    main_mod +>:Defines:+> base_cls;
    app_cls +>:Inherits:+> base_cls;
    app_cls +>:Calls:+> fmt_func;
    main_mod +>:Imports:+> fmt_func;

    # utils package contents
    helpers_mod = Module(name="helpers", fqn="utils.helpers", package_name="utils");
    pkg_utils +>:Contains:+> helpers_mod;
    helpers_mod +>:Defines:+> fmt_func;

    # ---- Run the four CLI commands ----
    print("=== mapper analyse list --detailed ===");
    root spawn PackageLister(detailed=True);

    print("=== mapper analyse get my-app --depth 3 ===");
    root spawn PackageStats(package_name="my-app", depth=3);

    print("=== mapper analyse export my-app --format json ===");
    root spawn PackageExporter(package_name="my-app", fmt="json");

    print("=== mapper analyse delete my-app --dry-run ===");
    root spawn PackageDeleter(package_name="my-app", force=True, dry_run=True);
}
