"""Taxonomy normalization demo.

Models NCBI lineage records as a graph of rank nodes connected by a
typed 'descends_from' edge. A maintainer walker descends each lineage
and resolves the top cellular rank, preferring superkingdom when
present, otherwise falling back to domain — exactly the policy the
Hoodini issue #81 demands. Records with a valid top cellular rank are
no longer mislabeled unclassified.
"""

node TaxRecord {
    has taxid: int = 0;
    has name: str = "";
    has rank: str = "";
    has top_cellular: str = "";
    has classified: bool = True;
}

edge DescendsFrom { }

walker Taxonomist {
    has seen_taxids: list[int] = [];
    has prefer_superkingdom: bool = True;

    can begin with Root entry {
        print("Walking lineage forest to normalize top cellular rank");
        visit [-->];
    }

    can descend with TaxRecord entry {
        if here.taxid in self.seen_taxids {
            disengage;
        }
        self.seen_taxids.append(here.taxid);

        if here.rank == "superkingdom" and self.prefer_superkingdom {
            here.top_cellular = here.name;
            here.classified = True;
            print(f"[SK-DOMINANT] superkingdom wins for taxid {here.taxid}: {here.name}");
        } elif here.rank == "domain" {
            if here.top_cellular == "" {
                here.top_cellular = here.name;
                here.classified = True;
                print(f"[DOMAIN-FILL] domain recorded for taxid {here.taxid}: {here.name}");
            }
        } elif here.rank == "acellular root" {
            here.top_cellular = "";
            here.classified = False;
            print(f"[ACELLULAR] taxid {here.taxid} is acellular -> unclassified");
        }

        visit [-->];
    }
}

walker Reporter {
    can report with Root entry {
        visit [-->];
    }

    can report_record with TaxRecord entry {
        label = "classified" if here.classified else "unclassified";
        top = here.top_cellular if here.top_cellular != "" else "n/a";
        print(f"taxid={here.taxid} name={here.name} rank={here.rank} top_cellular={top} -> {label}");
        visit [-->];
    }
}

with entry {
    bacteria = TaxRecord(taxid=2, name="Bacteria", rank="domain");
    cellular_root = TaxRecord(taxid=1, name="cellular root", rank="cellular root");
    acellular_root = TaxRecord(taxid=0, name="acellular root", rank="acellular root");
    viridae = TaxRecord(taxid=10239, name="Viridae", rank="domain");

    archaea = TaxRecord(taxid=2157, name="Archaea", rank="domain");

    sk_bacteria = TaxRecord(taxid=2, name="Bacteria", rank="superkingdom");

    root ++> cellular_root +>:DescendsFrom:+> bacteria;
    cellular_root +>:DescendsFrom:+> archaea;
    root +>:DescendsFrom:+> acellular_root +>:DescendsFrom:+> viridae;

    root spawn Taxonomist(prefer_superkingdom=True);

    root ++> sk_bacteria;

    root spawn Taxonomist(prefer_superkingdom=True);

    root spawn Reporter();
}
