"""Regression tests for HIER benchmark model (issue #353).

Tests:
  1. HierarchyInspector post-order traversal via Parent edges
  2. ReachabilityChecker path discovery
  3. CascadeInvalidator subtree invalidation
  4. Cycle detection on a graph with a back-edge
  5. Two-hop index fanout counting
"""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: HierarchyInspector traversal over narrow deep tree ----------
test "HierarchyInspector traverses a deep Parent chain" {
    a = OntologyClass(name="a");
    b = OntologyClass(name="b");
    d = OntologyClass(name="d");
    e = OntologyClass(name="e");
    root ++> a +>:Parent:+> b +>:Parent:+> d +>:Parent:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HierarchyInspector();
    }
    out = buf.getvalue();

    assert "[CYCLE]" not in out, f"unexpected cycle: {out}";
    assert res.cycle_detected is False, f"cycle_detected should be False: {out}";
    assert res.visited == ["a", "b", "d", "e"], (
        f"expected order [a,b,d,e], got {res.visited}"
    );
    assert res.order == ["a", "b", "d", "e"], (
        f"expected order list [a,b,d,e], got {res.order}"
    );
    assert "visit a (depth 0" in out, f"missing a visit line: {out}";
    assert "visit e (depth 3" in out, f"missing e visit line: {out}";
}

# ---------- Test 2: ReachabilityChecker finds target via Parent walk ----------
test "ReachabilityChecker reaches target through Parent chain" {
    p1 = OntologyClass(name="P1");
    p2 = OntologyClass(name="P2");
    p3 = OntologyClass(name="P3");
    p4 = OntologyClass(name="P4");
    root ++> p1 +>:Parent:+> p2 +>:Parent:+> p3 +>:Parent:+> p4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReachabilityChecker(target="P4");
    }
    out = buf.getvalue();

    assert res.reached is True, f"P4 should be reachable, got {res.reached}";
    assert "P4" in res.path, f"path missing P4: {res.path}";
    assert res.path[0] == "P1", f"path should start at P1: {res.path}";
    assert res.path[-1] == "P4", f"path should end at P4: {res.path}";
    assert "REACHED P4" in out, f"missing REACHED line: {out}";
}

test "ReachabilityChecker misses unreachable target" {
    u1 = OntologyClass(name="U1");
    u2 = OntologyClass(name="U2");
