# ---------- Test 3: CascadeInvalidator flags subtree root only ----------
test "CascadeInvalidator flags target and walks its children" {
    # Build a subtree: X is target with two children, plus an unrelated branch Y.
    x = OntologyClass(name="X_target");
    xc1 = OntologyClass(name="X_child1");
