"""Tests for the OrderAuditor walker: skip-vs-halt semantics."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helper: run the auditor on a freshly built graph and return captured stdout.
# ---------------------------------------------------------------------------
def run_auditor(orders: list) -> tuple {
    buf = io.StringIO();
    auditor = OrderAuditor();
    root ++> orders[0];
    current = orders[0];
    for i in range(1, len(orders)) {
        current +>:Order:+> orders[i] if False else None;
        # The above guard is never taken; we chain with ++> instead.
    }
    # Rebuild chain explicitly with ++> for clarity.
    # (The block above is unused; construct fresh chain below.)
    with redirect_stdout(buf) {
        # Build a new linear chain from scratch inside the redirect.
        r2 = root;
        for ord in orders {
            r2 ++> ord;
            r2 = ord;
        }
        a = OrderAuditor();
        root spawn a;
    }
    return (buf.getvalue(), a);
}

test "happy path: every valid, non-fraud order is audited" {
    buf = io.StringIO();
    root ++> Order(title="A", amount=10.0, valid=True, fraud=False)
        ++> Order(title="B", amount=20.0, valid=True, fraud=False)
        ++> Order(title="C", amount=30.0, valid=True, fraud=False);
    auditor = OrderAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "[AUDIT] A ($10.0)" in out, f"missing A audit line: {out}";
    assert "[AUDIT] B ($20.0)" in out, f"missing B audit line: {out}";
    assert "[AUDIT] C ($30.0)" in out, f"missing C audit line: {out}";
    assert "[SKIP]" not in out, f"unexpected SKIP line: {out}";
    assert "[HALT]" not in out, f"unexpected HALT line: {out}";
    assert auditor.audited == 3, f"expected 3 audited, got {auditor.audited}";
}

test "invalid orders are skipped, walk continues to later orders" {
    buf = io.StringIO();
    root ++> Order(title="Good-1", amount=50.0, valid=True, fraud=False)
        ++> Order(title="Bad-1", amount=40.0, valid=False, fraud=False)
        ++> Order(title="Good-2", amount=60.0, valid=True, fraud=False);
    auditor = OrderAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "[SKIP] invalid order Bad-1 ($40.0)" in out, f"missing skip line: {out}";
    assert "[AUDIT] Good-1 ($50.0)" in out, f"missing Good-1 audit: {out}";
    assert "[AUDIT] Good-2 ($60.0)" in out, f"missing Good-2 audit (walk should continue past invalid): {out}";
    assert "[HALT]" not in out, f"unexpected HALT: {out}";
    assert auditor.audited == 2, f"expected 2 audited (invalid skipped), got {auditor.audited}";
}

test "fraud flag halts the walk immediately, later orders not audited" {
    buf = io.StringIO();
    root ++> Order(title="Pre", amount=10.0, valid=True, fraud=False)
        ++> Order(title="Fraudster", amount=9999.0, valid=True, fraud=True)
        ++> Order(title="NeverSeen", amount=20.0, valid=True, fraud=False);
    auditor = OrderAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "[HALT] fraud flag on Fraudster ($9999.0)" in out, f"missing HALT line: {out}";
    assert "[AUDIT] NeverSeen ($20.0)" not in out, f"walk must halt, but NeverSeen was audited: {out}";
    # Only Pre was successfully counted before the fraud hit.
    assert auditor.audited == 1, f"expected 1 audited before halt, got {auditor.audited}";
}

test "invalid order before fraud still gets skipped, then fraud halts" {
    buf = io.StringIO();
    root ++> Order(title="First", amount=10.0, valid=True, fraud=False)
        ++> Order(title="SkipMe", amount=20.0, valid=False, fraud=False)
        ++> Order(title="BadFraud", amount=30.0, valid=False, fraud=True)
        ++> Order(title="After", amount=40.0, valid=True, fraud=False);
    auditor = OrderAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "[SKIP] invalid order SkipMe ($20.0)" in out, f"missing skip: {out}";
    assert "[HALT] fraud flag on BadFraud ($30.0)" in out, f"missing halt on fraud: {out}";
    # Fraud check runs even on invalid orders -> the HALT wins over SKIP.
    assert "[AUDIT] After ($40.0)" not in out, f"walk must halt on fraud: {out}";
    assert auditor.audited == 1, f"only First should be counted, got {auditor.audited}";
}

test "empty root: auditor prints start line and disengages gracefully" {
    buf = io.StringIO();
    auditor = OrderAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "OrderAuditor starting walk" in out, f"missing start line: {out}";
    assert "[AUDIT]" not in out, f"no orders to audit: {out}";
    assert "[SKIP]" not in out, f"no orders to skip: {out}";
    assert "[HALT]" not in out, f"no orders to halt: {out}";
    assert auditor.audited == 0, f"expected 0 audited on empty graph, got {auditor.audited}";
}

