"""Agent harness: model bounded coding subagents and walk their lineage.

Entities: Workspace, Principal, Agent (parent/child), TaskLineage.
Traversal: cascade cancel from a parent agent through its whole task tree,
budget invalidation, and a reachability audit across principals/workspaces.
"""

node Principal {
    has name: str = "";
    has role: str = "user";
}

node Workspace {
    has ws_name: str = "";
    has network_isolated: bool = True;
}

node TaskLineage {
    has lineage_id: str = "";
    has created_at: str = "2026-01-01T00:00:00Z";
}

node Agent {
    has agent_id: str = "";
    has title: str = "";
    has status: str = "running";
    has ttl_seconds: int = 600;
    has token_budget: int = 0;
    has tokens_used: int = 0;
    has idempotency_key: str = "";
    has tool_policy: str = "default";
    has provider: str = "default";
    has model: str = "default";
}

edge OwnedBy { has granted_at: str = "2026-01-01T00:00:00Z"; }
edge MemberOf { has joined_at: str = "2026-01-01T00:00:00Z"; }
edge SpawnedIn { has bound_at: str = "2026-01-01T00:00:00Z"; }
edge ChildOf { has depth: int = 1; }
edge ImplementsTask { has order: int = 0; }

walker CascadeCancel {
    has cancelled_count: int = 0;
    has seen: list[str] = [];
    has depth_cap: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can enter_workspace with Workspace entry {
        visit [-->];
    }

    can enter_lineage with TaskLineage entry {
        visit [-->];
    }

    can cancel_agent with Agent entry {
        already = False;
        for tag in self.seen {
            if tag == here.agent_id {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(here.agent_id);
        if here.status != "cancelled" {
            here.status = "cancelled";
            self.cancelled_count += 1;
            print(f"[CANCEL] {here.agent_id} ({here.title}) ttl={here.ttl_seconds}s tokens={here.tokens_used}/{here.token_budget}");
        }
        if len(self.seen) >= self.depth_cap {
            disengage;
        }
        visit [->:ChildOf:->];
    }

    can audit_principal with Principal entry {
        print(f"[AUDIT] principal={here.name} role={here.role}");
        visit [-->];
    }

    can audit_workspace with Workspace entry {
        print(f"[AUDIT] workspace={here.ws_name} network_isolated={here.network_isolated}");
        visit [-->];
    }
}

walker BudgetInvalidator {
    has threshold: int = 0;
    has evicted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can check_agent with Agent entry {
        over_budget = False;
        if here.token_budget > 0 {
            if here.tokens_used > here.token_budget {
                over_budget = True;
            }
        }
        if over_budget {
            here.status = "invalidated";
            self.evicted += 1;
            print(f"[INVALIDATE] {here.agent_id} tokens={here.tokens_used} budget={here.token_budget}");
        }
        visit [-->];
    }
}

walker ReachabilityAuditor {
    has target_ws: str = "";
    has target_principal: str = "";
    has leaks: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_agent with Agent entry {
        ws_name = "";
        principal_name = "";
        bad = False;
        for neighbour in [-->] {
            if isinstance(neighbour, Workspace) {
                ws_name = neighbour.ws_name;
                if self.target_ws != "" and ws_name != self.target_ws {
                    bad = True;
                    note = f"agent {here.agent_id} leaked into workspace {ws_name}";
                    self.leaks.append(note);
                }
            }
            if isinstance(neighbour, Principal) {
                principal_name = neighbour.name;
                if self.target_principal != "" and principal_name != self.target_principal {
                    bad = True;
                    note = f"agent {here.agent_id} reachable from principal {principal_name}";
                    self.leaks.append(note);
                }
            }
        }
        if bad {
            print(f"[LEAK] {here.agent_id} -> ws={ws_name} principal={principal_name}");
        }
        visit [-->];
    }
}

with entry {
    alice = Principal(name="alice", role="owner");
    bob = Principal(name="bob", role="owner");
    mallory = Principal(name="mallory", role="guest");

