```jac
"""License audit on transitive dependencies.

Models a NuGet-style package graph and a walker that performs the
hand-rolled traversal the issue complains about: enumerating every
transitive dependency, recording its declared license, and flagging any
license that is not on the allowlist (or is explicitly forbidden) so
the build can fail.

Entities are typed nodes (Package, DependencyRoot, LicenseNotice);
relationships are typed edges (DependsOn, Declares, Produces). A
``LicenseAuditor`` walker walks the typed ``DependsOn`` edges with an
explicit cycle guard (jac walkers do not dedupe by themselves) and
accumulates findings on typed ``has`` fields, reporting once at exit.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
}

edge DependsOn {
    has depth: int = 0;
}

edge Declares { }

edge Produces { }

node DependencyRoot {
    has project_name: str = "";

    def allowlist -> list[str] {
        return ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"];
    }

    def forbidden -> list[str] {
        return ["GPL-3.0", "AGPL-3.0", "OSL-3.0", "BUSL-1.1"];
    }

    def classify(license: str) -> str {
        if license in self.forbidden() {
            return "FORBIDDEN";
        }
        if license in self.allowlist() {
            return "ALLOWED";
        }
        return "REVIEW";
    }
}

node LicenseNotice {
    has entry: str = "";
}

walker LicenseAuditor {
    has seen: list[str] = [];
    has findings: list[dict] = [];

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with Package entry {
        key = f"{here.name}@{here.version}";
        if key in self.seen {
            report here;
            return;
        }
        self.seen.append(key);
        # Find the parent DependencyRoot via the Declares edge.
        root_node = [here ->:Declares:->][0] if [->:Declares:->] else None;
        verdict = root_node.classify(here.license) if root_node is not None else "REVIEW";
        if verdict != "ALLOWED" {
            self.findings.append({
                "package": here.name,
                "version": here.version,
                "license": here.license,
                "verdict": verdict,
            });
        }
        visit [->:DependsOn:->];
    }

    can finish with DependencyRoot entry {
        visit [->:DependsOn:->];
    }

    can summarize with DependencyRoot exit {
        report {
            "project": here.project_name,
            "scanned": len(self.seen),
            "findings": self.findings,
        };
        disengage;
    }
}

with entry {
    proj = DependencyRoot(project_name="IComparable.Extensions");
    root ++> proj;

    # Direct dependencies
    p_newtonsoft = Package(name="Newtonsoft.Json", version="13.0.3", license="MIT");
    p_serilog = Package(name="Serilog", version="4.0.0", license="Apache-2.0");
    proj +>:Declares:+> p_newtonsoft;
    proj +>:Declares:+> p_serilog;

    # Transitive chain (some allowed, some not)
    p_json_net = Package(name="Json.NET", version="13.0.3", license="MIT");
    p_serilog_core = Package(name="Serilog.Core", version="4.0.0", license="Apache-2.0");
    p_gpl_transitive = Package(name="SomeGplLib", version="1.0.0", license="GPL-3.0");
    p_unknown = Package(name="MysteryLib", version="0.1.0", license="UNKNOWN");

    p_newtonsoft +>:DependsOn(depth=1):+> p_json_net;
    p_serilog +>:DependsOn(depth=1):+> p_serilog_core;
    p_serilog_core +>:DependsOn(depth=2):+> p_gpl_transitive;
