"""Set-operation provenance: cross-branch agreement fold over resolved output schema.

Models the issue's core scenario natively: positional-union wrappers (UNION /
CTE / recursive CTE) where the read-type intent at column `i` must be computed
from the agreement of every branch at `i`, not borrowed from the first leaf.

Entities are node archetypes, branches are connected via typed edges, and a
walker performs the agreement-fold traversal that the hand-rolled machinery
replaces.
"""

# --- Column metadata model ---------------------------------------------------

node Column {
    has name: str = "";
    has js_type: str = "raw";  # "raw" | "bigint" | "number"
}

# --- Branch archetypes --------------------------------------------------------

node LeafSelect {
    has label: str = "";
    has output_columns: list = [];
}

node SetOperation {
    has label: str = "";
}

node CteWrap {
    has label: str = "";
}

node RecursiveCte {
    has label: str = "";
}

# --- Typed edges -------------------------------------------------------------

edge BranchesTo {
    has position: int = 0;
}

edge OuterWraps {
    # CTE / recursive CTE wrapping an inner select
}

# --- Walker: cross-branch agreement fold -------------------------------------

walker ProvenanceFolder {
    has output_columns: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Simple CTE: passthrough of inner select's metadata (single source).
    can fold_simple_cte with CteWrap entry {
        inner_targets = [here ->:OuterWraps:->];
        if inner_targets {
            inner = inner_targets[0];
            self.output_columns = inner.output_columns;
            print(f"[CteWrap] {here.label} -> single-source passthrough");
            for col in self.output_columns {
                marker = "convert" if col.js_type != "raw" else "abstain";
                print(f"  pos {col.name}: {col.js_type} ({marker})");
            }
        }
    }

    # Set operation: fold over agreement of every branch at each position.
    can fold_setop with SetOperation entry {
        branches = [here ->:BranchesTo:->];
        first_cols = branches[0].output_columns;
        n = len(first_cols);
        agreed: list = [];
        for i in range(0, n) {
            candidate = first_cols[i].js_type;
            all_match = True;
            for b in branches {
                b_cols = b.output_columns;
                if i >= len(b_cols) {
                    all_match = False;
                    break;
                }
                if b_cols[i].js_type != candidate {
                    all_match = False;
                    break;
                }
            }
            resolved = candidate if all_match else "raw";
            col = Column(name=first_cols[i].name, js_type=resolved);
            agreed.append(col);
        }
        self.output_columns = agreed;
        print(f"[SetOperation] {here.label} -> agreement fold over "
              f"{len(branches)} branches:");
        for col in agreed {
            marker = "convert" if col.js_type != "raw" else "abstain";
            print(f"  pos {col.name}: {col.js_type} ({marker})");
        }
    }

    # Recursive CTE: base + step at the same positions; same fold as set-op.
    can fold_recursive with RecursiveCte entry {
        branches = [here ->:BranchesTo:->];
        first_cols = branches[0].output_columns;
        n = len(first_cols);
        agreed: list = [];
        for i in range(0, n) {
            candidate = first_cols[i].js_type;
            all_match = True;
            for b in branches {
                b_cols = b.output_columns;
                if i >= len(b_cols) {
                    all_match = False;
                    break;
                }
                if b_cols[i].js_type != candidate {
                    all_match = False;
                    break;
                }
            }
            resolved = candidate if all_match else "raw";
            col = Column(name=first_cols[i].name, js_type=resolved);
            agreed.append(col);
        }
        self.output_columns = agreed;
        print(f"[RecursiveCte] {here.label} -> agreement fold over "
              f"{len(branches)} branches:");
        for col in agreed {
            marker = "convert" if col.js_type != "raw" else "abstain";
            print(f"  pos {col.name}: {col.js_type} ({marker})");
        }
    }

    can record_leaf with LeafSelect entry {
        self.output_columns = here.output_columns;
        print(f"[LeafSelect] {here.label}: "
              f"{[c.js_type for c in here.output_columns]}");
    }
}

