```jac
"""Recursive repr over self-containing Containers.

Models pyochain-style containers where a Container may hold itself
directly or transitively. A walker descends the containment graph via a
typed `Holds` edge, tracking every node it has entered so it can stop
recursion cleanly and surface the cycle that the original repr would
have recursed on forever.
"""

node Container {
    has name: str = "";
    has payload: str = "";
    has visited: bool = False;
}

edge Holds {
    has order: int = 0;
}

walker ReprWalker {
    has indent: int = 0;
    has depth_limit: int = 16;
    has cycle_detected: bool = False;
    has self_ref_name: str = "";

    can start with Root entry {
        print("ReprWalker: descending containment graph");
        visit [->:Holds:->];
    }

    can render with Container entry {
        pad = "  " * self.indent;
        marker = " [SELF]" if here.payload == "self" else "";
        print(f"{pad}- {here.name}{marker}");
        if here.visited {
            self.cycle_detected = True;
            if here.payload == "self" {
                self.self_ref_name = here.name;
            }
            print(f"{pad}  (already entered, stopping recursion)");
            return;
        }
        if self.indent >= self.depth_limit {
            print(f"{pad}  (depth limit reached)");
            disengage;
        }
        here.visited = True;
        self.indent += 1;
        visit [->:Holds:->];
    }
}

with entry {
    outer = Container(name="outer", payload="box");
    inner = Container(name="inner", payload="crate");
    leaf = Container(name="leaf", payload="widget");
    recursive = Container(name="recursive", payload="self");

    root +>:Holds(order=0):+> outer;
    outer +>:Holds(order=1):+> inner;
    inner +>:Holds(order=2):+> leaf;
    inner +>:Holds(order=3):+> recursive;
    recursive +>:Holds(order=0):+> recursive;

    w = ReprWalker();
    root spawn w;

    print("");
    if w.cycle_detected {
        print(f"Cycle detected at '{w.self_ref_name}' "
              f"({w.indent} indents deep) -- repr would have recursed forever");
    } else {
        print("No cycle detected.");
    }
}
