"""Regression tests for the expert runtime substrate demo.

Covers the core behaviors promised by issue #10:
  - idempotent ingest (duplicate event_id is rejected, not overwritten)
  - validation (missing req_hash is flagged bad)
  - Prolog fixture proof reaches both observation and assertion
  - provenance traversal is cycle-guarded and counts unique nodes
"""

import io;
import from contextlib { redirect_stdout }

# Helpers -------------------------------------------------------------
# Build a fresh graph per test; root is escaped because `root` is reserved.

def make_observation(
    event_id: str,
    transport: str = "http",
    provider: str = "openai",
    model: str = "gpt-4o",
    req_hash: str = "h1",
    resp_hash: str = "h2",
    kb_revision: str = "r1"
) {
    return Observation(
        event_id=event_id,
        provider=provider,
        model=model,
        transport=transport,
        req_hash=req_hash,
        resp_hash=resp_hash,
        kb_revision=kb_revision
    );
}

def make_assertion(
    rule: str = "event_transport",
    rule_version: str = "v1",
    kb_revision: str = "r1",
    derivation: str = "fixture",
    value: str = "sse"
) {
    return Assertion(
        rule=rule,
        rule_version=rule_version,
        kb_revision=kb_revision,
        derivation=derivation,
        value=value
    );
}

# ----------------------------- Tests ---------------------------------

test "ingestor rejects bad observation with empty req_hash" {
    `root = Root();
    bad = make_observation(event_id="evt-bad", transport="http", req_hash="");
    `root ++> bad;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = `root spawn Ingestor();
    }
    out = buf.getvalue();

    assert "[BAD] ingested evt-bad via http" in out, f"missing BAD marker: {out!r}";
    # Bad ingest must not be marked as seen/OK.
    assert "[OK] ingested evt-bad" not in out, f"bad obs wrongly marked OK: {out!r}";
    assert "evt-bad" in res.seen, f"event_id should still be recorded: {res.seen}";
}

test "ingestor is idempotent on duplicate event_id" {
    `root = Root();
    first = make_observation(event_id="evt-dup", transport="sse", req_hash="a");
    second = make_observation(event_id="evt-dup", transport="http", req_hash="b");
    `root ++> first;
    `root ++> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = `root spawn Ingestor();
    }
    out = buf.getvalue();

    # First ingest is OK, the duplicate is a CONFLICT and is NOT overwritten.
    assert "[OK] ingested evt-dup via sse" in out, f"missing first OK: {out!r}";
    assert "[CONFLICT] duplicate evt-dup; no overwrite" in out, f"missing conflict: {out!r}";
    # The duplicate must not produce a second OK line that would imply overwrite.
    assert out.count("[OK] ingested evt-dup") == 1, f"duplicate produced overwrite: {out!r}";
    # The walker still recorded the event_id exactly once.
    assert res.seen.count("evt-dup") == 1, f"seen list duplicated: {res.seen}";
}

test "ingestor accepts two distinct observations on same root" {
    `root = Root();
    a = make_observation(event_id="evt-a", transport="http", req_hash="ha");
    c = make_observation(event_id="evt-c", transport="websocket", req_hash="hc");
    `root ++> a;
    `root ++> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = `root spawn Ingestor();
    }
    out = buf.getvalue();

    assert "[OK] ingested evt-a via http" in out, f"missing evt-a: {out!r}";
    assert "[OK] ingested evt-c via websocket" in out, f"missing evt-c: {out!r}";
    assert "CONFLICT" not in out, f"unexpected conflict: {out!r}";
    assert len(res.seen) == 2, f"expected 2 unique events, got {res.seen}";
}

test "prolog fixture reaches observation and assertion" {
    `root = Root();
    obs = make_observation(event_id="evt-fix", transport="websocket", req_hash="h");
    assertion = make_assertion(rule="event_transport", rule_version="v1", value="websocket");
    `root ++> obs;
    `root ++> assertion;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = `root spawn PrologFixture();
    }
    out = buf.getvalue();

    # Fixture derivation must reference the observation's id+transport.
    assert "[PROVEN] Prolog: event_transport(evt-fix, websocket)" in out, f"missing proven: {out!r}";
    # Typed assertion emission must mark TYPED with rule@version -> value.
    assert "[TYPED] event_transport@v1 -> websocket" in out, f"missing typed: {out!r}";
    # Empty assertions (no rule) must never be reported as TYPED.
    assert "[EMPTY]" not in out, f"unexpected empty assertion: {out!r}";
}

test "provenance traversal is cycle-guarded and counts unique nodes" {
    `root = Root();
    obs = make_observation(event_id="evt-cycle", transport="sse", req_hash="h");
    ev = Evidence(evidence_id="ev-cycle", kind="raw_capture", payload="p");
    t = Task(task_id="tsk-cycle", session_id="s1", kind="classify");
    a = make_assertion(rule="event_transport", rule_version="v1", value="sse");

    `root ++> obs ++> ev ++> t ++> a;

