    assert res.visited.count("ev-cycle") == 1, f"evidence visited twice: {res.visited}";
    assert res.visited.count("tsk-cycle") == 1, f"task visited twice: {res.visited}";
    # Assertion key is rule@rule_version.
    assert res.visited.count("event_transport@v1") == 1, f"assertion visited twice: {res.visited}";
    # The guard message must have fired for the cycle back into evt-cycle.
    assert "[GUARDED]" in out, f"cycle guard did not fire: {out!r}";
    assert "[GUARDED] cycle hit at evt-cycle" in out, f"expected guard at evt-cycle: {out!r}";
