"""Test annex for the hiking trail program."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helper: build a fresh trail of `n` plain Waypoint nodes chained off root.
# ---------------------------------------------------------------------------
def build_trail(n: int) -> object {
    prev = root;
    for i in range(n) {
        wp = Waypoint();
        prev ++> wp;
        prev = wp;
    }
    return root;
}

# ---------------------------------------------------------------------------
# Test 1: default target (3) — Hiker should print three "Stop #N" lines
# and a completion line, then stop before visiting remaining waypoints.
# ---------------------------------------------------------------------------
test "default target prints three stops and summit, then stops" {
    build_trail(5);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    assert "Stop #1" in out, f"missing first stop in: {out!r}";
    assert "Stop #2" in out, f"missing second stop in: {out!r}";
    assert "Stop #3" in out, f"missing third stop in: {out!r}";
    # Exactly three stops printed (default target == 3).
    assert out.count("Stop #") == 3, f"expected 3 stops, got {out.count('Stop #')} in: {out!r}";
    assert "Summit reached!" in out, f"missing summit line in: {out!r}";
