"""V2 recursive science hierarchy: L0 episodes, L1 metabolism, L2 transfer, L3 concepts.

Models the umbrella closure issue: episodes feed knowledge metabolism, which feeds
transfer discovery, which feeds concept evolution. A Reviewer walker performs the
sceptical-review gate by traversing the hierarchy depth-first with a cycle guard
(no built-in dedupe in jac 0.36.1).
"""

# ---------- L0: scientific episode ----------
node Episode {
    has title: str = "";
    has field: str = "";
    has outcome: str = "OPEN";
    has rigour_passed: bool = False;
}

# ---------- L1: knowledge metabolism ----------
node KnowledgeUnit {
    has title: str = "";
    has kind: str = "";
    has provenance: str = "";
    has confidence: float = 0.0;
}

# ---------- L2: transfer candidate ----------
node TransferCandidate {
    has source_field: str = "";
    has target_field: str = "";
    has structural_desc: str = "";
    has native_recovered: bool = False;
}

# ---------- L3: concept (versioned state, not a label) ----------
node Concept {
    has name: str = "";
    has state: str = "DRAFT";
    has version: int = 0;
}

# ---------- typed edges ----------
edge Governs { has rule: str = ""; }
edge Produced { has weight: float = 0.0; }
edge Metabolizes { has step: int = 0; }
edge Transfers { has score: float = 0.0; }
edge Evolves { has transition: str = ""; }

# ---------- walker: sceptical reviewer (recursive depth-first traversal) ----------
walker Reviewer {
    has depth_cap: int = 6;
    has visited: list = [];
    has report: list = [];

    can start with Root entry {
        visit [->:Governs:->];
    }

    can review with Episode entry {
        if self.depth_cap <= 0 {
            self.report.append(f"[CAP] gave up at {here.title}");
            disengage;
        }
        if here in self.visited {
            self.report.append(f"[CYCLE] revisit blocked at {here.title}");
            disengage;
        }
        self.visited.append(here);
        verdict = "PASS" if here.rigour_passed else "FAIL";
        self.report.append(
            f"[L0 {verdict}] {here.title} :: {here.field} :: {here.outcome}"
        );
        self.depth_cap -= 1;
        visit [->:Produced:->];
    }

    can audit with KnowledgeUnit entry {
        if here in self.visited {
            self.report.append(f"[CYCLE] ku-revisit blocked at {here.title}");
            disengage;
        }
        self.visited.append(here);
        self.report.append(
            f"[L1] {here.kind}:{here.title} prov={here.provenance} "
            f"conf={here.confidence:.2f}"
        );
        visit [->:Metabolizes:->];
    }

    can assess with TransferCandidate entry {
        if here in self.visited {
            self.report.append(f"[CYCLE] xfer-revisit blocked at {here.structural_desc}");
            disengage;
        }
        self.visited.append(here);
        recovered = "OK" if here.native_recovered else "LOST";
        self.report.append(
            f"[L2] {here.source_field}->{here.target_field} "
            f"via '{here.structural_desc}' native={recovered}"
        );
        visit [->:Evolves:->];
    }

    can review_concept with Concept entry {
        if here in self.visited {
            self.report.append(f"[CYCLE] concept-revisit blocked at {here.name}");
            disengage;
        }
        self.visited.append(here);
        self.report.append(
            f"[L3 v{here.version}] {here.name} state={here.state}"
        );
        visit [->:Evolves:->];
    }
}

# ---------- demo wiring ----------
with entry {
    ep_a = Episode(title="wave6-contraction", field="physics", outcome="PARTIAL", rigour_passed=True);
    ep_b = Episode(title="transfer-probe-7", field="biology", outcome="OPEN", rigour_passed=False);
    ep_c = Episode(title="closure-meta-50", field="metascience", outcome="OPEN", rigour_passed=True);

    ku1 = KnowledgeUnit(title="contraction lemma", kind="lemma", provenance="ep_a", confidence=0.72);
    ku2 = KnowledgeUnit(title="counterexample set", kind="counterexample", provenance="ep_b", confidence=0.31);
    ku3 = KnowledgeUnit(title="reopen condition", kind="reopen", provenance="ep_c", confidence=0.55);

    xfer1 = TransferCandidate(
        source_field="math",
        target_field="biology",
        structural_desc="contraction-mapping-as-homeostasis",
        native_recovered=True,
    );
    xfer2 = TransferCandidate(
        source_field="biology",
        target_field="physics",
        structural_desc="negative-feedback-loop",
        native_recovered=False,
    );

    concept_force = Concept(name="force", state="REVISED", version=3);
    concept_field = Concept(name="field", state="GENERALIZED", version=2);

    # L0 spine
    root +>:Governs:+> ep_a;
    ep_a +>:Produced:+> ku1;
    ku1 +>:Metabolizes:+> ku2;
    ku1 +>:Metabolizes:+> ku3;

    # L2 transfer branching off metabolized knowledge
    ku1 +>:Metabolizes:+> xfer1;
    ku2 +>:Metabolizes:+> xfer2;

    # L3 concept evolution fed by transfer candidates
    xfer1 +>:Evolves:+> concept_force;
    xfer2 +>:Evolves:+> concept_field;

    # cross-link (intentional cycle bait so the guard fires)
    concept_force +>:Evolves:+> concept_field;
    concept_field +>:Evolves:+> concept_force;

    rev = Reviewer();
    root spawn rev;

    print("=== Reviewer report ===");
    for line in rev.report {
        print(line);
    }
    print(f"=== total stops: {len(rev.report)} ===");
}
