"""Source Replaces Containment: typed Source edges, cascade walk, cycle-safe traversal."""

node SourceItem {
    has kind: str = "";
    has label: str = "";
    has status: str = "draft";
    has children_count: int = 0;
}

edge Source {
    has path_segment: str = "";
}

walker CascadeWalker {
    has visited_ids: list[str] = [];
    has cascade_order: list[str] = [];
    has dead_ends: int = 0;
    has cycle_blocked: int = 0;

    def _key(item: SourceItem) -> str {
        return f"{item.kind}:{id(item)}";
    }

    can start with Root entry {
        print("Beginning Source cascade from root");
        visit [->:Source:->];
    }

    can cascade with SourceItem entry {
        key = self._key(here);
        if key in self.visited_ids {
            self.cycle_blocked += 1;
            print(f"[cycle blocked] revisiting {here.kind} '{here.label}'");
            disengage;
        }
        self.visited_ids.append(key);
        self.cascade_order.append(f"{here.kind}:{here.label}");
        status = "PROPAGATED" if here.status != "archived" else "SKIPPED";
        print(f"[{status}] {here.kind} '{here.label}' (status={here.status}, children={here.children_count})");
        if here.children_count == 0 {
            self.dead_ends += 1;
            disengage;
        }
        visit [->:Source:->] else {
            self.dead_ends += 1;
            disengage;
        }
    }
}

walker SubtreeCollector {
    has target_label: str = "";
    has collected: list[str] = [];

    can start with Root entry {
        print(f"\nSubtreeCollector: locating subtree rooted at '{self.target_label}'");
        visit [->:Source:->];
    }

    can collect with SourceItem entry {
        self.collected.append(f"{here.kind}:{here.label}");
        if here.children_count == 0 {
            disengage;
        }
        visit [->:Source:->] else {
            disengage;
        }
    }
}

walker SourceChainReporter {
    has chain: list[str] = [];
    has steps: int = 0;

    def report() -> dict {
        return {"chain": self.chain, "steps": self.steps};
    }

    can start with Root entry {
        visit [->:Source:->];
    }

    can follow with SourceItem entry {
        self.chain.append(f"{here.kind}:{here.label}");
        self.steps += 1;
        visit [->:Source:->] else {
            disengage;
        }
    }
}

with entry {
    project = SourceItem(kind="Project", label="Helix Research", status="active", children_count=0);
    folder_a = SourceItem(kind="Folder", label="Experiments", status="active", children_count=0);
    folder_b = SourceItem(kind="Folder", label="Archive", status="active", children_count=0);
    entry_1 = SourceItem(kind="NotebookEntry", label="Synthesis Run 042", status="active", children_count=0);
    entry_2 = SourceItem(kind="NotebookEntry", label="Analysis Run 043", status="active", children_count=0);
    entity_1 = SourceItem(kind="Entity", label="Compound XYZ-12", status="active", children_count=0);
    entity_2 = SourceItem(kind="Entity", label="Sample S-7", status="active", children_count=0);
    result_1 = SourceItem(kind="Result", label="Spectrum #1", status="active", children_count=0);
