"""Tiny dungeon crawler: a chain of rooms, one vault room holds the treasure, a Hunter walker counts rooms and disengages the moment it finds the vault so rooms past it are never visited."""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can search with Room entry {
        self.rooms_seen += 1;
        if here.is_vault {
            print(f"Found the treasure in '{here.name}' after checking {self.rooms_seen} room(s).");
            disengage;
        } else {
            print(f"Checked '{here.name}' — empty.");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    root ++> Room(name="Foyer")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Chamber")
        ++> Room(name="Dragon's Lair");
    root spawn Hunter();
}
```

"""Tests for the dungeon crawler: hunter terminates the moment it finds the vault."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: Hunter stops at vault, never visits rooms past it ----------
test "hunter stops at vault and never visits rooms past it" {
    root ++> Room(name="Foyer")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Chamber")
        ++> Room(name="Dragon's Lair");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # The vault must have been reached.
    assert "Found the treasure" in out, f"missing treasure-found message: {out}";
    # Rooms past the vault must NEVER be visited/printed.
    assert "Forbidden Chamber" not in out, f"visited a room past the vault: {out}";
    assert "Dragon's Lair" not in out, f"visited a room past the vault: {out}";
    # The pre-vault rooms were checked on the way.
    assert "Foyer" in out, f"expected Foyer to be checked: {out}";
    assert "Antechamber" in out, f"expected Antechamber to be checked: {out}";
    assert "Hall of Echoes" in out, f"expected Hall of Echoes to be checked: {out}";
    # Counter must reflect exactly 4 rooms examined (3 empty + vault).
    assert "after checking 4 room(s)" in out, f"expected exactly 4 rooms seen: {out}";
    assert res.rooms_seen == 4, f"walker field says {res.rooms_seen} rooms seen";
}

# ---------- Test 2: Hunter counts every empty room before the vault ----------
test "hunter counts all empty rooms it traverses" {
    root ++> Room(name="Entry")
        ++> Room(name="Corridor A")
        ++> Room(name="Corridor B")
        ++> Room(name="Vault", is_vault=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Checked 'Entry' — empty." in out, f"missing Entry log: {out}";
    assert "Checked 'Corridor A' — empty." in out, f"missing Corridor A log: {out}";
    assert "Checked 'Corridor B' — empty." in out, f"missing Corridor B log: {out}";
    assert "Found the treasure in 'Vault' after checking 4 room(s)." in out, f"wrong count/room: {out}";
    assert res.rooms_seen == 4, f"rooms_seen = {res.rooms_seen}";
}

# ---------- Test 3: Vault as the very first room — terminates immediately ----------
test "hunter terminates immediately when first room is the vault" {
    root ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Beyond A")
        ++> Room(name="Beyond B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Found the treasure in 'Vault'" in out, f"vault message missing: {out}";
    assert "after checking 1 room(s)" in out, f"should have checked exactly 1 room: {out}";
    assert res.rooms_seen == 1, f"rooms_seen = {res.rooms_seen}";
    assert "Beyond A" not in out, f"traversed past the vault: {out}";
    assert "Beyond B" not in out, f"traversed past the vault: {out}";
}

# ---------- Test 4: Graph shape sanity — chain order is preserved ----------
test "graph is a single forward chain from root" {
    rt = root ++> Room(name="A")
        ++> Room(name="B")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Past");

    children = [root-->];
    assert len(children) == 1, f"root should have exactly 1 child, got {len(children)}";
    first = children[0];
    assert first.name == "A", f"first room name = {first.name}";
    second = [first-->][0];
    assert second.name == "B", f"second room name = {second.name}";
    third = [second-->][0];
    assert third.name == "Vault", f"third room name = {third.name}";
    assert third.is_vault, "third room must be flagged is_vault";
    fourth = [third-->][0];
    assert fourth.name == "Past", f"fourth room name = {fourth.name}";
}

# ---------- Test 5: Hunter on a dead-end branch (no children) disengages ----------
test "hunter disengages cleanly when chain has no vault room" {
    root ++> Room(name="Only Room");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # Only the one room should be checked; no treasure found, no crash.
    assert "Checked 'Only Room' — empty." in out, f"missing empty log: {out}";
    assert "Found the treasure" not in out, f"should not announce a find: {out}";
    assert res.rooms_seen == 1, f"rooms_seen = {res.rooms_seen}";
}

