"""Orchard irrigation tour: a maintenance crew services pumps and sprinklers, logging each device, idle hours, and resetting counters."""

node Device {
    has name: str = "";
    has idle_hours: int = 0;
}

node Pump(Device) {
    has pressure_psi: float = 0.0;

    def reset_idle() -> int {
        used = self.idle_hours;
        self.idle_hours = 0;
        return used;
    }

    override def kind() -> str {
        return "Pump";
    }
}

node Sprinkler(Device) {
    has radius_m: float = 0.0;

    def reset_idle() -> int {
        used = self.idle_hours;
        self.idle_hours = 0;
        return used;
    }

    override def kind() -> str {
        return "Sprinkler";
    }
}

walker MaintenanceCrew {
    has serviced: int = 0;

    can start with Root entry {
        print("Maintenance crew entering the grove");
        visit [-->];
    }

    can tour with Grove entry {
        print(f"-- Touring grove: {here.grove_name} --");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        previous = here.reset_idle();
        print(f"[{here.kind()}] {here.name} idle {previous}h -> reset to 0h");
        self.serviced += 1;
    }
}

node Grove {
    has grove_name: str = "";
}

with entry {
    north = Grove(grove_name="North");
    south = Grove(grove_name="South");

    north ++> Pump(name="Pump-A", idle_hours=14, pressure_psi=45.0)
        ++> Pump(name="Pump-B", idle_hours=7, pressure_psi=38.5)
        ++> Sprinkler(name="Sprinkler-1", idle_hours=22, radius_m=4.5);

    south ++> Sprinkler(name="Sprinkler-2", idle_hours=10, radius_m=3.2)
        ++> Pump(name="Pump-C", idle_hours=0, pressure_psi=50.0)
        ++> Sprinkler(name="Sprinkler-3", idle_hours=5, radius_m=6.0);

    root ++> north ++> south;

    crew = MaintenanceCrew();
    root spawn crew;

    print(f"Total devices serviced: {crew.serviced}");
}
