"""Hiking trail: a chain of plain waypoints walked by a hiker who counts stops."""

# Plain waypoints — no fields needed; the node archetype exists just to
# give the chain graph identity and to be the trigger type for the hiker.
node Waypoint;

walker Hiker {
    has target: int = 3;
    has stops: int = 0;

    can start with Root entry {
        print("Hiker sets off from the trailhead");
        visit [-->] else { disengage; }
    }

    can trek with Waypoint entry {
        self.stops += 1;
        print(f"Stop #{self.stops} reached");
        if self.stops >= self.target {
            print(f"Trip complete after {self.stops} waypoints");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # A straight chain of plain waypoints from trailhead to summit.
    # Each ++> creates one Waypoint node; no payload required.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    hiker = Hiker(target=4);
    root spawn hiker;
}
