```jac
"""Canonical shape authoring: model nested, reusable shapes and placement
relationships that cannot override shape constraints.

Scenario distilled from IndependentImpact/standard2shape issue #17:

  - A CanonicalShape declares its own constraints (datatype, cardinality,
    value range, path, nested-node shape). These are INVARIANT.
  - A Placement points to a CanonicalShape and adds *context* (where the
    shape is used in a document). A placement may NEVER widen, narrow, or
    otherwise alter the canonical constraints.
  - A Specialization is an explicit, separately-named CanonicalShape that
    a placement references when its constraints legitimately differ.
    Specializations are themselves canonical shapes — they can be reused.

The traversal the issue complains about is the cascade-invalidate walk:
when a canonical shape changes, every placement that references it must
be re-validated, and every nested shape referenced through `Requires`
must also be re-checked. In a hand-rolled graph this is recursive
parent_id walking; here it is a single walker over typed edges with an
explicit cycle guard.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node CanonicalShape {
    has name: str = "";
    has datatype: str = "xsd:string";
    has min_count: int = 0;
    has max_count: int = -1;       # -1 == unbounded
    has value_constraint: str = ""; # e.g. an allowed-values regex/IRI
    has path_iri: str = "";
    has nested_ref: str = "";       # name of nested canonical shape, if any
    has version: int = 1;           # bumped on canonical edit
}

node Placement {
    has location: str = "";        # e.g. "Bundle/header/section-3"
    has override_attempt: str = "";# "" means none; non-empty means rejected
}

node Specialization {
    has name: str = "";
    has reason: str = "";
}

# Typed edges: the relationship carries meaning, so each is a real archetype.

edge References {
    has since_version: int = 0;
}

edge SpecializedFrom {
    has reason: str = "";
}

edge Requires {
    has kind: str = "nested";      # "nested" or "value"
}

# ---------------------------------------------------------------------------
# Walker: cascade re-validation across all placements and nested shapes
# ---------------------------------------------------------------------------

walker InvalidationCascade {
    has touched_count: int = 0;
    has rejected_count: int = 0;
    has specialized_count: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can descend with Placement entry {
        # 1. Reject any placement that tried to override canonical constraints.
        if here.override_attempt != "" {
            print(
                f"[REJECT] placement at {here.location} tried to override: "
                f"{here.override_attempt}"
            );
            self.rejected_count += 1;
        }

        # 2. Walk every References edge to the canonical shape(s) it points at.
        visit [->:References:->];
    }

    can cascade with CanonicalShape entry {
        self.touched_count += 1;
        print(
            f"[CHECK] canonical '{here.name}' v{here.version} "
            f"(datatype={here.datatype}, min={here.min_count}, "
            f"max={here.max_count}, path={here.path_iri})"
        );

        # 3. If this shape nests another canonical shape, keep cascading.
        if here.nested_ref != "" {
            visit [->:Requires:->];
        }

        # 4. Otherwise, dead-end walk completes cleanly.
    }
}

# ---------------------------------------------------------------------------
# Walker: dependency-aware specialization audit
# ---------------------------------------------------------------------------

walker SpecializationAuditor {
    has spec_count: int = 0;
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can audit with Specialization entry {
        self.spec_count += 1;
        print(
            f"[SPEC] '{here.name}' specialization "
            f"(reason: {here.reason})"
        );
        # Walk back along the parent-of relationship.
        visit [<-:SpecializedFrom:<-];
    }
}

# ---------------------------------------------------------------------------
# Demonstration graph
# ---------------------------------------------------------------------------

with entry {
    # Three canonical shapes. `PersonShape` nests `IdentifierShape`.
    id_shape = CanonicalShape(
        name="IdentifierShape",
        datatype="xsd:string",
        min_count=1,
        max_count=1,
        value_constraint="regex:^ID-[0-9]+$",
        path_iri="ex:identifier"
    );

    person_shape = CanonicalShape(
        name="PersonShape",
        datatype="xsd:string",
        min_count=1,
        max_count=1,
        value_constraint="",
        path_iri="ex:fullName",
        nested_ref="IdentifierShape",
        version=2
    );

    # An explicit specialization — used only when a placement truly needs
    # constraints that differ from the canonical.
    person_strict = Specialization(
        name="PersonShapeStrict",
        reason="Legal-name placements require non-empty + regex constraint"
    );

    # Placements: two reuse the same canonical, one tries to override.
    p_a = Placement(location="Bundle/header/personA");
    p_b = Placement(location="Bundle/footer/personB");
    p_bad = Placement(
        location="Bundle/footer/personC",
        override_attempt="datatype=xsd:integer"
    );

    # Build the graph.
    root ++> id_shape;
    root ++> person_shape;
    root ++> person_strict;

    p_a +>:References(since_version=1):+> person_shape;
    p_b +>:References(since_version=2):+> person_shape;
    p_bad +>:References(since_version=2):+> person_shape;

    person_shape +>:Requires(kind="nested"):+> id_shape;

    person_strict +>:SpecializedFrom(reason="distinct constraints"):+> person_shape;

    # Spawn the cascade-invalidation walker from root.
    cascade = InvalidationCascade();
    root spawn cascade;
    print(
        f"cascade touched {cascade.touched_count} canonical shape(s), "
        f"rejected {cascade.rejected_count} placement override(s)"
    );

    # Spawn the specialization auditor from root.
    auditor = SpecializationAuditor();
    root spawn auditor;
    print(
        f"auditor found {auditor.spec_count} explicit specialization(s)"
    );
}
