        algorithm="silver-mean",
        source_version="src-1.1",
        fingerprint="v1|eng-0.6|silver-mean|src-1.1",
        stale=True,
    );

    auditor = CacheAuditor();
    print("--- CacheAuditor pass ---");
    root spawn auditor;
    print(f"stale entries observed: {auditor.stale_seen}");

    invalidator = Invalidator();
    print("--- Invalidator pass ---");
    root spawn invalidator;
    print(f"entries revalidated: {invalidator.purged}");
