"""Displayed-month budget recalculation over a typed category graph."""

node Category {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has category_id: int = 0;
    has expanded: bool = False;
}

node Operation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has amount: float = 0.0;
    has month: int = 0;
}

node Plan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has displayed_month: int = 0;
    has actual_total: float = 0.0;
    has invalidated: bool = False;
}

edge HasRootCategory { }
edge ChildCategory { }
edge ContainsOperation { }

walker PlanRecalculator {
    has category_count: int = 0;
    has operation_total: float = 0.0;
    has target_month: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can recalculate with Plan entry {
        self.target_month = here.displayed_month;
        self.operation_total = 0.0;
        here.actual_total = 0.0;
        here.invalidated = False;
        print(f"recompute displayed month {self.target_month}: {here.title}");
        visit [->:HasRootCategory:->] else { disengage; }
    }

    can finish with Plan exit {
        here.actual_total = self.operation_total;
        print(f"one plan result: {here.actual_total}");
        print(f"expanded {self.category_count} categories with one guarded walk");
    }

    can expand with Category entry {
        if here.expanded {
            print(f"cycle guard skipped {here.title}");
            skip;
        } else {
            here.expanded = True;
            self.category_count += 1;
            print(f"category {here.title}");
            visit [->:ContainsOperation:->] else { }
            visit [->:ChildCategory:->] else { }
        }
    }

    can total with Operation entry {
        if here.month == self.target_month {
            self.operation_total += here.amount;
            print(f"include {here.title}: {here.amount}");
        }
    }
}

with entry {
    plan = Plan(title="March essentials", displayed_month=3, invalidated=True);
    root_category = Category(title="Essentials", category_id=1);
    food = Category(title="Food", category_id=2);
    dining = Category(title="Dining", category_id=3);
    groceries = Category(title="Groceries", category_id=4);
    coffee = Operation(title="Coffee", amount=6.5, month=3);
    rent = Operation(title="Rent", amount=1200.0, month=3);
    old_bill = Operation(title="Old bill", amount=40.0, month=2);

    root ++> plan;
    plan +>:HasRootCategory:+> root_category;
    root_category +>:ChildCategory:+> food;
    food +>:ChildCategory:+> dining;
    dining +>:ChildCategory:+> groceries;
    groceries +>:ChildCategory:+> root_category;
    dining +>:ContainsOperation:+> coffee;
    root_category +>:ContainsOperation:+> rent;
    food +>:ContainsOperation:+> old_bill;

    root spawn PlanRecalculator();
}
