"""Stack layout for ordered split children.

Models the refine flow's split output: a parent ticket produces child
tickets, some dependent on each other (an ordered split) and some
fully independent (a parallel split). A walker walks the children,
records the base branch each dependent child should stack on, and
leaves independent children pointing at `main`. Independent children
are never stacked — stacking them would serialize work that is
already parallel.
"""

node Ticket {
    has title: str = "";
    has kind: str = "code";  # "design" or "code"
    has base: str = "main";  # the branch this ticket should build on
    has order: int = 0;       # layer index within the ordered split
}

edge DependsOn {
    has note: str = "";
}

edge Produces {
    has layer: int = 0;
}

walker StackPlanner {
    has parent_title: str = "";
    has stack_capable: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can plan with Ticket entry {
        here.base = self.compute_base(here);
        self.report(f"{here.title} -> {here.base}");
        visit [-->];
    }

    def compute_base(t: Ticket) -> str {
        if not self.stack_capable {
            return "main";
        }
        if t.kind == "design" {
            # Design-only tickets produce a spec, not a PR; nothing
            # can target their branch, so they never form a layer.
            return "main";
        }
        if t.order <= 0 {
            return "main";
        }
        # Ordered (dependent) child: base on the preceding layer's branch.
        return f"layer-{t.order - 1}";
    }

    def report(line: str) -> None {
        print(line);
    }
}

with entry {
    parent = Ticket(title="parent: refine ordered split");
    root ++> parent;

    # --- Ordered split: a design spec, then three code layers ---
    parent ++> Ticket(title="design spec", kind="design", order=0);
    parent ++> Ticket(title="layer-1 code", kind="code", order=1);
    parent ++> Ticket(title="layer-2 code", kind="code", order=2);
    parent ++> Ticket(title="layer-3 code", kind="code", order=3);

    # --- Parallel (independent) split children, never stacked ---
    parent ++> Ticket(title="parallel-A", kind="code", order=0);
    parent ++> Ticket(title="parallel-B", kind="code", order=0);

    # Wire a typed dependency so the ordered children form a real chain.
    layer1 = [c for c in [parent-->] if c.title == "layer-1 code"][0];
    layer2 = [c for c in [parent-->] if c.title == "layer-2 code"][0];
    layer3 = [c for c in [parent-->] if c.title == "layer-3 code"][0];
    layer1 +>:DependsOn(note="blocked by"):+> layer2;
    layer2 +>:DependsOn(note="blocked by"):+> layer3;

    # Confirmation gate preview, then commit.
    print("=== Stack layout (proposed) ===");
    root spawn StackPlanner(parent_title="refine ordered split");
}
