walker Auditor {
    has next_id: int = 1;
    has log: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Item entry {
        if here.item_id == 0 {
            here.item_id = self.next_id;
            self.next_id = self.next_id + 1;
        }
        if not here.persisted {
            print(f"[PERSIST] id={here.item_id} sku={here.sku} title={here.title} stock={here.stock}");
            here.persisted = True;
        }
        self.log = self.log + [here.item_id];
        visit [-->];
    }
}

walker Dumper {
    can start with Root entry {
        kids = [-->];
        self.dump_node("root", 0, kids);
    }

    can dump with Item entry {
        kids = [-->];
        self.dump_node(here.title, 1, [here]);
        self.dump_node("child", 2, kids);
        visit [-->];
    }

    def dump_node(label: str, depth: int, frontier: list) -> None {
        indent = "  " * depth;
        prefix = f"{indent}- {label}";
        if len(frontier) == 0 {
            print(f"{prefix}: (none)");
            return;
        }
        for node in frontier {
            print(f"{prefix}: item_id={node.item_id} sku={node.sku} stock={node.stock}");
        }
    }
}

