"""Tests for the hiking trail walker."""

import io;
import from contextlib { redirect_stdout }

test "hiker visits every waypoint in order and prints each stop" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Trailhead(name="Pine Ridge")
            ++> Waypoint()
            ++> Waypoint()
            ++> Waypoint()
            ++> Summit(name="Eagle");
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    # Stop numbering is 1, 2, 3 — one per Waypoint, in walk order.
    assert "Stop 1" in out, f"expected 'Stop 1' in: {out!r}";
    assert "Stop 2" in out, f"expected 'Stop 2' in: {out!r}";
    assert "Stop 3" in out, f"expected 'Stop 3' in: {out!r}";
    # Stop 1 must precede Stop 2, which must precede Stop 3.
    s1 = out.index("Stop 1");
    s2 = out.index("Stop 2");
    s3 = out.index("Stop 3");
    assert s1 < s2 < s3, f"stops out of order: {s1}, {s2}, {s3}";
    # No phantom fourth stop.
    assert out.count("Stop ") == 3, f"unexpected stop count in: {out!r}";
    # Final completion line reflects the actual number of waypoints passed.
    assert "Summit reached — passed 3 waypoints." in out, f"missing completion line: {out!r}";
}

