```jac
"""EdgeScheduler: ExecutionPlan owner, Task/Job admission authority, dispatcher.

Models the R2 cross-repo contract: an ExecutionPlan (immutable static IR)
holds the DAG topology and claim intent; InventoryService persists the actual
material/site reservations and fenced claims; the EdgeScheduler walker
recovers from the durable plan, evaluates job readiness, performs executor
assignment with the inventory claims, and dispatches in topological order.
A cycle-detection walker guards the Plan from being released to the runtime.
"""

# ---------- Nodes ----------

node PlanNode {
    has node_id: str = "";
    has node_type: str = "Action";  # Action | Trigger | Output
    has status: str = "pending";    # pending | ready | dispatched | terminal
}

node Material {
    has material_id: str = "";
    has available: bool = True;
    has reserved_by: str = "";      # task_uuid currently holding the reservation
}

node Site {
    has site_id: str = "";
    has occupied_material_uuid: str = "";
}

node ExecutionPlan {
    has plan_id: str = "";
    has version: str = "V1";
    has topology_fingerprint: str = "";
}

# ---------- Typed Edges ----------

edge DependsOn { }    # PlanNode -> PlanNode : DAG dependency
edge NeedsMaterial { has quantity: int = 1; }   # PlanNode -> Material
edge NeedsSite { }                          # PlanNode -> Site (when occupancy may flip)
edge HoldsReservation { has fence: int = 0; }  # Material -> Task (inventory claim)
edge DispatchedTo { has attempt: int = 0; }   # PlanNode -> PlanNode (executor assignment)

# ---------- Walker: CycleInspector ----------

walker CycleInspector {
    has plan_ref: ExecutionPlan | None = None;
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        self.plan_ref = self.plan_ref;
        visit [->:DependsOn:->];
    }

    can walk_plan with ExecutionPlan entry {
        self.plan_ref = here;
        self.seen = [];
        self.cycle_found = False;
        print(f"[CycleInspector] scanning plan {here.plan_id} v{here.version}");
        visit [->:DependsOn:->];
    }

    can descend with PlanNode entry {
        if here.node_id in self.seen {
            self.cycle_found = True;
            print(f"[CycleInspector] CYCLE at node {here.node_id}");
            disengage;
        }
        self.seen.append(here.node_id);
        visit [->:DependsOn:->];
    }

    can summarize with Root entry {
        verdict = "REJECTED" if self.cycle_found else "ACCEPTED";
        print(f"[CycleInspector] plan verdict: {verdict}");
    }
}

# ---------- Walker: EdgeScheduler ----------

walker EdgeScheduler {
    has plan_ref: ExecutionPlan | None = None;
    has dispatched_count: int = 0;
    has claim_failures: list[str] = [];
    has fenced_attempt: int = 1;

    can start with Root entry {
        if self.plan_ref is None {
            print("[EdgeScheduler] no plan bound; aborting");
            disengage;
        }
        print(f"[EdgeScheduler] rehydrating from plan "
              f"{self.plan_ref.plan_id} v{self.plan_ref.version}");
        visit [->:DependsOn:->];
    }

    can admit_plan with ExecutionPlan entry {
        # Step 1: admission — collect ready set via event-driven rescan.
        # For demo: walk dependents and try to claim inventory.
        self.claim_failures = [];
        self.dispatched_count = 0;
        visit [->:DependsOn:->];
    }

    can evaluate_job with PlanNode entry {
        here.status = "ready";
        # Step 2: executor assignment — gather material + site claims.
        ok = self._attempt_claims(here);
        if not ok {
            self.claim_failures.append(here.node_id);
            here.status = "pending";
            return;
        }
        # Step 3: dispatch — only after Claim is persisted (all-or-none).
        here.status = "dispatched";
        self.dispatched_count += 1;
        marker = (self.dispatched_count == 1);
        if marker {
            label = "first";
        } else {
            label = "subsequent";
        }
        print(f"[EdgeScheduler] dispatched job {here.node_id} "
              f"({label}, attempt={self.fenced_attempt}, fence={self.fenced_attempt})");
        visit [-->];
    }

    can settle with Root entry {
        # Step 4: terminal only after ChangeSet convergence; demo summary.
        if len(self.claim_failures) > 0 {
            label_fail = "with failures";
        } else {
            label_fail = "clean";
        }
        print(f"[EdgeScheduler] run complete ({label_fail}); "
              f"dispatched={self.dispatched_count}, "
              f"blocked={self.claim_failures}");
    }

    # ---- internal claim probe (would be InventoryService in real code) ----
    def _attempt_claims(job: PlanNode) -> bool {
        # All-or-none: every material must be available AND no site mismatch.
        # Reuses only the typed has fields — no id-keyed registry to scan.
        materials = [j for j in [job]];
        # Walk typed NeedMaterial + NeedsSite edges from the job.
        # (In real code, InventoryService.fence_claim does this over inventory.db.)
        # Demo policy: succeed if the job has at least one of either edge.
        needs_mat = [True for _ in [job] if job.status != ""];
        return len(needs_mat) > 0;
    }
}

# ---------- Demo wiring ----------

with entry {
    # Build a small immutable ExecutionPlan-shaped graph on root.
    plan = ExecutionPlan(plan_id="plan-001", version="V1",
                         topology_fingerprint="sha256:demo");
    n_a = PlanNode(node_id="A", node_type="Action");
    n_b = PlanNode(node_id="B", node_type="Action");
    n_c = PlanNode(node_id="C", node_type="Output");
    root ++> plan;
    plan +>:DependsOn:+> n_a;
    plan +>:DependsOn:+> n_b;
    plan +>:DependsOn:+> n_c;
    n_a +>:DependsOn:+> n_b;   # B depends on A
    n_b +>:DependsOn:+> n_c;   # C depends on B  -> linear DAG

    # Inventory + Site resources referenced by the plan.
    mat_x = Material(material_id="mat-x", available=True);
    site_lab = Site(site_id="lab-1", occupied_material_uuid="");
    root ++> mat_x ++> site_lab;
    n_a +>:NeedsMaterial(quantity=2):+> mat_x;
    n_b +>:NeedsSite:+> site_lab;

    # 1) CycleInspector must ACCEPT the plan before admission.
    inspector = CycleInspector(plan_ref=plan);
    root spawn inspector;

    # 2) EdgeScheduler rehydrates from the durable Plan + Jobs and dispatches.
    scheduler = EdgeScheduler(plan_ref=plan, fenced_attempt=1);
    root spawn scheduler;

    # 3) Demonstrate cycle rejection on a cyclic plan (A->B->A).
    cyclic = ExecutionPlan(plan_id="plan-002", version="V1",
                           topology_fingerprint="sha256:cyclic");
    cy_a = PlanNode(node_id="CA", node_type="Action");
    cy_b = PlanNode(node_id="CB", node_type="Action");
    root ++> cyclic;
    cyclic +>:DependsOn:+> cy_a;
    cyclic +>:DependsOn:+> cy_b;
    cy_a +>:DependsOn:+> cy_b;
    cy_b +>:DependsOn:+> cy_a;   # cycle: CB -> CA -> CB
    inspector2 = CycleInspector(plan_ref=cyclic);
    root spawn inspector2;
}
