import io;
import from contextlib { redirect_stdout }

test "accepts an acyclic execution plan" {
    plan = ExecutionPlan(plan_id="plan-acyclic", version="V1",
                         topology_fingerprint="sha256:acyclic");
    node_a = PlanNode(node_id="A", node_type="Action");
    node_b = PlanNode(node_id="B", node_type="Action");
    node_c = PlanNode(node_id="C", node_type="Output");

    root ++> plan;
    plan +>:DependsOn:+> node_a;
    node_a +>:DependsOn:+> node_b;
    node_b +>:DependsOn:+> node_c;

    inspector = CycleInspector(plan_ref=plan);
