        res = plan spawn inspector;
    }

    assert res.cycle_found == False, f"unexpected cycle: {res.seen}";
    assert len(res.seen) == 3, f"visited nodes: {res.seen}";
    assert "[CycleInspector] scanning plan plan-acyclic vV1" in buf.getvalue(), f"output: {buf.getvalue()}";
}

test "rejects a cyclic execution plan" {
