    node_b = PlanNode(node_id="B", node_type="Action");

    root ++> plan;
    plan +>:DependsOn:+> node_a;
    node_a +>:DependsOn:+> node_b;
    node_b +>:DependsOn:+> node_a;

    inspector = CycleInspector(plan_ref=plan);
    buf = io.StringIO();
