"""Recover workflow jobs whose worker lease expired."""

node WorkflowJob {
    has job_id: str = "";
    has status: str = "PENDING";
    has lease_owner: str = "";
    has lease_expires_at: int = 0;
    has retry_count: int = 0;
    has current_stage: str = "";
    has last_error: str = "";
}

node Worker {
    has worker_id: str = "";
    has alive: bool = True;
}

edge Owns {
    has acquired_at: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker LeaseReaper {
    has now_tick: int = 0;
    has max_hops: int = 8;
    has hops: int = 0;
    has reclaimed_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_worker with Worker entry {
        if here.alive {
            print(f"worker {here.worker_id} is alive; checking its leases");
        } else {
            print(f"worker {here.worker_id} is gone; expired leases are reclaimable");
        }
        visit [->:Owns:->] else { disengage; }
    }

    can inspect_job with WorkflowJob entry {
        if here.status == "PROCESSING" and here.lease_expires_at < self.now_tick {
            here.status = "PENDING";
            here.retry_count += 1;
            here.lease_owner = "";
            here.last_error = "";
            self.reclaimed_count += 1;
            print(f"reclaimed {here.job_id} at stage {here.current_stage}; retry {here.retry_count}");
        } else {
            print(f"left {here.job_id} unchanged ({here.status})");
        }

        if self.hops < self.max_hops {
            self.hops += 1;
            visit [->:DependsOn:->] else { disengage; }
        } else {
            print("dependency traversal depth cap reached");
            disengage;
        }
    }
}

with entry {
    worker = Worker(worker_id="worker-7", alive=False);
    stranded = WorkflowJob(
        job_id="review-1830",
        status="PROCESSING",
        lease_owner="worker-7",
        lease_expires_at=90,
        retry_count=1,
        current_stage="llm_review",
        last_error="Waiting for a BYOK concurrency slot..."
    );
    dependency = WorkflowJob(
        job_id="context-42",
        status="COMPLETED",
        current_stage="context_ready"
    );

    root ++> worker;
    worker +>:Owns(acquired_at=0):+> stranded;
    stranded +>:DependsOn(reason="review context"):+> dependency;

    root spawn LeaseReaper(now_tick=180, max_hops=8);
}
```

