```jac
"""Order auditor: invalid orders are skipped, fraud orders halt the walk.

Demonstrates the two flavors of early return used together:
- A guard ``return`` from the ability skips the current order without
  aborting traversal of later ones (the walker simply does not ``visit``
  forward from it).
- ``disengage`` halts the walker immediately so no further orders
  are visited.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;

    can start with Root entry {
        print("Starting order audit...");
        visit [-->] else { disengage; }
    }

    can review with Order entry {
        # Fraud: halt the entire walk right here.
        if here.fraud {
            print(f"[HALT] fraud flagged on '{here.title}' -- audit aborted");
            disengage;
        }

        # Invalid: skip this order, but keep walking later ones.
        if not here.valid {
            print(f"[SKIP] '{here.title}' is invalid -- continuing audit");
            visit [-->] else { disengage; };
            return;
        }

        # Valid order: record it and keep walking.
        self.audited += 1;
        print(f"[OK]   '{here.title}' amount={here.amount:.2f} audited=#{self.audited}");
        visit [-->] else { disengage; };
    }
}

