    t2_cycle_count +>:Blocks(tier=2):+> t2_resolver;
    t2_resolver +>:Blocks(tier=2):+> t2_natural_key;
    t2_natural_key +>:Blocks(tier=2):+> t2_merge_cycle;

    # Shared root-cause groupings.
    t1_dialog_wipe +>:SharesRootCause(note="post-overwrite reporting hazard"):+> t1_restore_swap;
    t2_resolver +>:SharesRootCause(note="natural-key family"):+> t2_natural_key;

    # Mount the backlog under root so the walkers can be spawned on it.
    root ++> t1_destructive ++> t2_cycle_count;

    # Run the tiered triage walker for each tier.
    Triage(current_tier=1) spawn root;
    Triage(current_tier=2) spawn root;

    # Walk the blocking chain from the highest-severity Tier-1 issue.
