"""Gallery security console.

Visitors of any kind are logged as generic entries when they enter a room.
When a Curator enters, the room additionally records an official inspection
attributed to the curator, and the curator's running inspection count
goes up by one. A tourist triggers only the generic log; a curator
triggers both.
"""

node Room {
    has name: str = "";
    has visitor_log: str = "";
    has inspections: str = "";
}

walker Visitor {
    has kind: str = "visitor";
    has label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        if here.visitor_log == "" {
            here.visitor_log = f"{self.label} ({self.kind})";
        } else {
            here.visitor_log = here.visitor_log + f", {self.label} ({self.kind})";
        }
        visit [-->];
    }
}

walker Tourist {
    has label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can tour with Room entry {
        if here.visitor_log == "" {
            here.visitor_log = f"{self.label} (tourist)";
        } else {
            here.visitor_log = here.visitor_log + f", {self.label} (tourist)";
        }
        visit [-->];
    }
}

walker Curator {
    has label: str = "";
    has inspection_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Room entry {
        # Generic visitor log entry
        if here.visitor_log == "" {
            here.visitor_log = f"{self.label} (curator)";
        } else {
            here.visitor_log = here.visitor_log + f", {self.label} (curator)";
        }
        # Official inspection record
        stamp = f"Inspected by {self.label}";
        if here.inspections == "" {
            here.inspections = stamp;
        } else {
            here.inspections = here.inspections + f"; {stamp}";
        }
        self.inspection_count += 1;
        visit [-->];
    }
}

with entry {
    rotunda = Room(name="Rotunda");
    east_wing = Room(name="East Wing");
    root ++> rotunda ++> east_wing;

    print("=== Run 1: tourist only ===");
    root spawn Tourist(label="Tess");
    print("Rotunda log     : " + (rotunda.visitor_log if rotunda.visitor_log != "" else "(none)"));
    print("Rotunda inspect : " + (rotunda.inspections if rotunda.inspections != "" else "(none)"));
    print("East Wing log   : " + (east_wing.visitor_log if east_wing.visitor_log != "" else "(none)"));
    print("East Wing inspect: " + (east_wing.inspections if east_wing.inspections != "" else "(none)"));

    print("=== Run 2: curator only ===");
    curator = Curator(label="Dr. Hale");
    root spawn curator;
    print("Rotunda log     : " + (rotunda.visitor_log if rotunda.visitor_log != "" else "(none)"));
    print("Rotunda inspect : " + (rotunda.inspections if rotunda.inspections != "" else "(none)"));
    print("East Wing log   : " + (east_wing.visitor_log if east_wing.visitor_log != "" else "(none)"));
    print("East Wing inspect: " + (east_wing.inspections if east_wing.inspections != "" else "(none)"));
    print(f"Curator '{curator.label}' inspected {curator.inspection_count} rooms");
}
