            self.violations.append(note);
            print(note);
        } else {
            print(f"OK at {here.name}: {here.temperature} C");
        }

        # Check 2: visit log. Every station visit is recorded separately.
        self.station_log.append(here.name);
        print(f"LOG: visited {here.name}");

        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", temperature=180.0);
    fryer = Station(name="Fryer", temperature=175.0);
    cold_prep = Station(name="Cold Prep", temperature=4.0);

    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print("--- Summary ---");
    print(f"Stations visited: {inspector.station_log}");
    print(f"Violations found: {len(inspector.violations)}");
    for v in inspector.violations {
        print(v);
    }
}
