"""Tests for the kitchen line health-inspection walker.

Each test builds its own small kitchen graph and spawns the Inspector,
capturing stdout to verify the two checks fire at every station.
"""

import io;
import from contextlib { redirect_stdout }

test "high temperature station is flagged as a violation" {
    root ++> Station(name="Grill", temperature=180.0)
        ++> Station(name="Fryer", temperature=175.0)
        ++> Station(name="Cold Prep", temperature=4.0);

    buf = io.StringIO();
    inspector = Inspector();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }
    out = buf.getvalue();

    assert "VIOLATION at Grill: 180.0 C exceeds 40 C" in out, f"missing grill violation: {out}";
    assert "VIOLATION at Fryer: 175.0 C exceeds 40 C" in out, f"missing fryer violation: {out}";
    assert "OK at Cold Prep: 4.0 C" in out, f"cold prep should be OK: {out}";
    assert len(inspector.violations) == 2, f"expected 2 violations, got {len(inspector.violations)}";
    assert "Grill" in inspector.violations[0], f"first violation should reference Grill: {inspector.violations[0]}";
    assert "Fryer" in inspector.violations[1], f"second violation should reference Fryer: {inspector.violations[1]}";
}

test "every station is logged regardless of temperature" {
    root ++> Station(name="Grill", temperature=180.0)
        ++> Station(name="Fryer", temperature=175.0)
        ++> Station(name="Cold Prep", temperature=4.0);

    buf = io.StringIO();
    inspector = Inspector();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }
    out = buf.getvalue();

    # Check 2 must run at every station: a LOG line per visit, and the
    # station_log list must contain all three station names in order.
    assert out.count("LOG: visited ") == 3, f"expected 3 LOG lines, got {out.count('LOG: visited ')} in {out}";
    assert "LOG: visited Grill" in out, f"missing Grill log: {out}";
    assert "LOG: visited Fryer" in out, f"missing Fryer log: {out}";
    assert "LOG: visited Cold Prep" in out, f"missing Cold Prep log: {out}";
    assert inspector.station_log == ["Grill", "Fryer", "Cold Prep"], f"station_log order wrong: {inspector.station_log}";
}

test "both checks fire together at the same station" {
    # A station hot enough to violate must ALSO be logged (and vice versa).
    root ++> Station(name="Hot Line", temperature=95.0)
        ++> Station(name="Salad Bar", temperature=6.0);

    buf = io.StringIO();
    inspector = Inspector();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }
    out = buf.getvalue();

    # Hot Line: violation + log interleaved in the same visit.
    hot_idx_v = out.find("VIOLATION at Hot Line");
    hot_idx_l = out.find("LOG: visited Hot Line");
    assert hot_idx_v != -1, f"Hot Line violation missing: {out}";
    assert hot_idx_l != -1, f"Hot Line log missing: {out}";
    assert hot_idx_l != hot_idx_v, f"LOG line for Hot Line not printed: {out}";

    # Salad Bar: ok + log together, no violation.
    cold_idx_o = out.find("OK at Salad Bar");
    cold_idx_l = out.find("LOG: visited Salad Bar");
    assert cold_idx_o != -1, f"Salad Bar OK line missing: {out}";
    assert cold_idx_l != -1, f"Salad Bar log missing: {out}";
    assert cold_idx_l > cold_idx_o, f"Salad Bar log should come after OK line: {out}";
    assert "VIOLATION at Salad Bar" not in out, f"Salad Bar must not be a violation: {out}";

    assert len(inspector.violations) == 1, f"expected 1 violation, got {len(inspector.violations)}";
    assert inspector.station_log == ["Hot Line", "Salad Bar"], f"station_log wrong: {inspector.station_log}";
}

test "boundary temperature at exactly 40 C is not a violation" {
    # Threshold is strict '>'; exactly 40 C must pass as OK.
    root ++> Station(name="Edge", temperature=40.0)
        ++> Station(name="Just Over", temperature=40.1);

    buf = io.StringIO();
    inspector = Inspector();
    with redirect_stdout(buf) {
