    }
    out = buf.getvalue();

    assert "OK at Edge: 40.0 C" in out, f"40.0 C should be OK, got: {out}";
    assert "VIOLATION at Edge" not in out, f"40.0 C must not violate: {out}";
    assert "VIOLATION at Just Over: 40.1 C exceeds 40 C" in out, f"40.1 C should violate: {out}";
    assert len(inspector.violations) == 1, f"expected exactly 1 violation, got {len(inspector.violations)}";
    assert inspector.station_log == ["Edge", "Just Over"], f"station_log wrong: {inspector.station_log}";
}

