"""Regression tests for static-reachability walker (Perry #9196).

The bug: a subpath resolving back to an ancestor caused unbounded recursion
(stack overflow). The fix is a visited-set that short-circuits cycles and
counts them instead of recursing forever.
"""

import io;
import from contextlib { redirect_stdout }

test "trusted package without route entry is AOT promoted" {
    rt = Root();
    entry_node = JsPackage(name="app-entry", trusted=False, has_route_entry=True);
    trusted_lib = JsPackage(name="@vendor/trusted-lib", trusted=True, has_route_entry=False);

    rt ++> entry_node;
    entry_node +>:Imports(specifier="./trusted-lib"):+> trusted_lib;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        collector = rt spawn StaticReachabilityCollector();
    }

    assert trusted_lib.aot_compiled, "trusted package w/o route entry must be AOT promoted";
    assert "@vendor/trusted-lib" in collector.aot_promoted, f"aot_promoted={collector.aot_promoted}";
    assert collector.cycles_blocked == 0, f"no cycle here, got {collector.cycles_blocked}";
    out = buf.getvalue();
    assert "AOT-promote: @vendor/trusted-lib" in out, f"missing promotion log: {out}";
}

test "trusted package with route entry is NOT AOT promoted" {
    rt = Root();
    entry_node = JsPackage(name="app-entry", trusted=False, has_route_entry=True);
    trusted_with_route = JsPackage(name="@vendor/routed", trusted=True, has_route_entry=True);

    rt ++> entry_node;
    entry_node +>:Imports(specifier="./routed"):+> trusted_with_route;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        collector = rt spawn StaticReachabilityCollector();
    }

    assert not trusted_with_route.aot_compiled, "trusted + route_entry must NOT be AOT promoted";
    assert "@vendor/routed" not in collector.aot_promoted, f"unexpectedly promoted: {collector.aot_promoted}";
    out = buf.getvalue();
    assert "AOT-promote" not in out, f"must not log promotion: {out}";
}

test "untrusted leaf is reached but not promoted" {
    rt = Root();
    entry_node = JsPackage(name="app-entry", trusted=False, has_route_entry=True);
    leaf = JsPackage(name="leaf", trusted=False, has_route_entry=False);

    rt ++> entry_node;
    entry_node +>:Imports(specifier="./leaf"):+> leaf;

    collector = rt spawn StaticReachabilityCollector();

    assert "leaf" in collector.reachable, f"reachable={collector.reachable}";
    assert not leaf.aot_compiled, "untrusted package must not be AOT promoted";
    assert "leaf" not in collector.aot_promoted, f"aot_promoted={collector.aot_promoted}";
}

test "subpath cycle is blocked and does not overflow" {
    rt = Root();
    entry_node = JsPackage(name="app-entry", trusted=False, has_route_entry=True);
    trusted_lib = JsPackage(name="@vendor/trusted-lib", trusted=True, has_route_entry=False);
    utils = JsPackage(name="@vendor/utils", trusted=True, has_route_entry=False);

    rt ++> entry_node;
    entry_node +>:Imports(specifier="./trusted-lib"):+> trusted_lib;
    trusted_lib +>:Imports(specifier="./utils"):+> utils;
    utils +>:SubpathResolvesTo(subpath="trusted-lib/index"):+> trusted_lib;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        collector = rt spawn StaticReachabilityCollector();
    }

    assert collector.cycles_blocked >= 1, f"cycle must be blocked, got {collector.cycles_blocked}";
    assert "@vendor/trusted-lib" in collector.aot_promoted, "first visit of trusted_lib must still promote";
    out = buf.getvalue();
    assert "[GUARD]" in out, f"guard log missing: {out}";
    assert "stack" not in out.lower() or "[GUARD]" in out, "must short-circuit, not recurse";
}

