"""Employee hierarchy walker: recursive parent_id traversal as typed edges.

Models the sqlc issue #4094 scenario: an employee table has a parent_id
self-reference, and a WITH RECURSIVE CTE walks up/down that hierarchy.
We lift the parent_id machinery into a typed Edge (ReportsTo) and let a
walker traverse it, replicating the recursive descent and surfacing the
"id is ambiguous" trap the issue describes when a join mixes ancestor
and descendant ids in the same scope.
"""

node Employee {
    has id: int = 0;
    has name: str = "";
    has deleted: bool = False;
    # Track ids we've already seen on the current recursive step —
    # mirrors the cycle guard a real WITH RECURSIVE planner needs,
    # since walkers in jac 0.36.1 have no built-in visited set.
    has seen_ids: list[int] = [];
}

edge ReportsTo {
    has since: str = "";
}

walker HierarchyAudit {
    has target_id: int = 0;
    has seed_id: int = 0;
    has depth: int = 0;
    has max_depth: int = 10;
    has ambiguous_hits: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Employee entry {
        # Seed the "seen" scope on the very first employee we land on.
        if self.depth == 0 {
            self.seed_id = here.id;
            here.seen_ids = [here.id];
            print(f"seed -> id={here.id} name={here.name}");
        }
        self.depth += 1;
        # Cycle / runaway guard: if we've exceeded the depth cap, stop.
        if self.depth > self.max_depth {
            print(f"depth cap {self.max_depth} hit, disengaging");
            disengage;
        }
        # Visit every direct report (typed edge traversal).
        visit [->:ReportsTo:->];
    }

    can audit with Employee entry {
        # This is the recursive step. The original SQL bug surfaces
        # when the outer SELECT and the inner JOIN both expose `id`
        # in the same projection — the engine can't tell them apart.
        # We model that ambiguity by checking whether `here.id` is
        # both a seed reference AND a join column reference at once.
        ambiguous = False;
        if here.id == self.seed_id and self.depth > 1 {
            ambiguous = True;
            note = f"AMBIGUOUS id={here.id} at depth={self.depth} (seed={self.seed_id})";
            self.ambiguous_hits.append(note);
        }
        status = "AMBIG" if ambiguous else "OK";
        print(f"  [{status}] id={here.id} name={here.name} depth={self.depth}");
        # Continue walking down the hierarchy.
        visit [->:ReportsTo:->];
    }

    can finish with Root entry {
        print(f"audit done: {len(self.ambiguous_hits)} ambiguous id reference(s)");
        for hit in self.ambiguous_hits {
            print(f"  - {hit}");
        }
    }
}

walker SoftDelete {
    # Cascade-soft-delete walker: traverses reports-to edges and marks
    # every reachable descendant as deleted, modeling the recursive
    # invalidation logic that the WITH RECURSIVE query depends on.
    has guard: list[int] = [];
    has cleared: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Employee entry {
        if here.id in self.guard {
            disengage;
        }
        self.guard.append(here.id);
        if not here.deleted {
            here.deleted = True;
            self.cleared += 1;
            print(f"soft-deleted id={here.id} name={here.name}");
        }
        visit [->:ReportsTo:->];
    }

    can report with Root entry {
        print(f"cascade invalidation cleared {self.cleared} employee(s)");
    }
}

with entry {
    # Build the org chart: alice -> bob -> carol -> dave, plus an
    # unrelated eve branch. The "id is ambiguous" pattern shows up
    # when the recursive CTE re-emits the seed row alongside its
    # children in the same projection.
    alice = Employee(id=1, name="Alice");
    bob = Employee(id=2, name="Bob");
    carol = Employee(id=3, name="Carol");
    dave = Employee(id=4, name="Dave");
    eve = Employee(id=5, name="Eve");

    root ++> alice
        +>:ReportsTo(since="2019"):+> bob
        +>:ReportsTo(since="2020"):+> carol
        +>:ReportsTo(since="2022"):+> dave;
    root ++> eve;

    print("=== HierarchyAudit from seed id=1 ===");
    root spawn HierarchyAudit(target_id=1, max_depth=6);

    print("");
    print("=== SoftDelete cascade from alice ===");
    root spawn SoftDelete();
}
