"""Fork replay boundary handshake: model the duplicate-history problem.

A session replay walker walks the commit history once and emits a boundary
handshake at each snapshot fork so the renderer does not replay the same
history twice. The buggy behaviour (no handshake) is shown by spawning the
walker on a fork-shaped graph and counting how many times the tip commit is
rendered.
"""

node Commit {
    has title: str = "";
    has seq: int = 0;
    has rendered: bool = False;
}

edge Parent { }

node ForkPoint {
    has label: str = "";
}

walker HistoryReplay {
    has render_count: int = 0;
    has handshakes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk_history with Commit entry {
        if not here.rendered {
            here.rendered = True;
            self.render_count += 1;
        }
        visit [->:Parent:->];
    }

    can meet_fork with ForkPoint entry {
        # Snapshot-boundary handshake: announce the fork so the renderer
        # knows the upcoming branch is a NEW replay, not a duplicate of
        # the one we just rendered.
        self.handshakes += 1;
        print(f"[handshake] fork at {here.label}");
        visit [->:Parent:->];
    }
}

with entry {
    # Main line: root -> c1 -> c2 -> c3 (the history we render exactly once).
    root +>:Parent:+> Commit(title="c1", seq=1)
        +>:Parent:+> Commit(title="c2", seq=2)
        +>:Parent:+> Commit(title="c3", seq=3);

    # Fork point off c2 -> fp -> c2b -> c3b. Without a boundary handshake
    # the renderer would replay c2 again on the branch side, so we plant
    # a ForkPoint node that the walker visits FIRST and uses to signal
    # "fresh history starts here".
    fp = ForkPoint(label="at-c2");
    Commit(seq=2) +>:Parent:+> fp
        +>:Parent:+> Commit(title="c2b", seq=21)
        +>:Parent:+> Commit(title="c3b", seq=31);

    w = HistoryReplay();
    root spawn w;

    print(f"renders={w.render_count} handshakes={w.handshakes}");
}
