```jac
"""Premium ALB target group cleanup: model rule-less orphaned TGs and their invalidation.

Two cleanup scenarios from the issue:
  1. A rule-driven orphan scan misses premium-<id>-tg groups whose listener
     rule is already gone. A walker that traverses by registered rules
     would never reach them, so we model the fix: a second pass that walks
     the target groups directly, applies the three-condition guard
     (no rule, no targets, no DB row) plus a minimum-age gate.
  2. verify_stripe_session is a zero-caller helper that the webhook path
     has made obsolete; we model its deletion alongside the cleanup so
     the demo reads as one bundled PR.
"""

node TargetGroup {
    has tg_id: str = "";
    has age_cycles: int = 0;
    has has_rule: bool = False;
    has has_targets: bool = False;
    has has_db_row: bool = False;
}

node UserAssignment {
    has user_id: str = "";
    has tg_id: str = "";
}

# A stub checkout session that knows the verify_stripe_session helper is gone.
node CheckoutSession {
    has session_id: str = "";
    has verify_stripe_session_removed: bool = True;
}

edge RegisteredRule {
    has rule_arn: str = "";
}

edge RegisteredTarget {
    has target_id: str = "";
}

# Typed edge carrying the user_id -> tg assignment row from the DB.
edge AssignsTo {
    has user_id: str = "";
}

walker OrphanCollector {
    # First pass mimics the bug: walking only via RegisteredRule edges
    # means rule-less TGs are invisible.
    can start with Root entry {
        print("[pass-1] rule-driven sweep (the buggy path):");
        visit [->:RegisteredRule:->];
    }

    can rule_driven_visit with TargetGroup entry {
        print(f"  reached {here.tg_id} via a registered rule");
        visit [->:RegisteredRule:->];
    }

    can dead_end with TargetGroup entry {
        # Fallback so walkers that enter a TargetGroup with no outgoing
        # rule edge don't hang.
        visit [->:RegisteredRule:->] else { disengage; };
    }
}

walker CleanupPass {
    # Second pass: walk all TargetGroups directly (no rule required),
    # apply the three-condition guard + minimum-age gate, and delete
    # those that qualify. Tracks the deltas on the walker itself.
    has deleted: list[str] = [];
    has spared: list[str] = [];

    can start with Root entry {
        print("[pass-2] direct sweep with three-condition guard + age gate:");
        visit [-->];
    }

    can sweep with TargetGroup entry {
        too_young = here.age_cycles < 1;
        rule_gone = not here.has_rule;
        targets_gone = not here.has_targets;
        row_gone = not here.has_db_row;
        qualifies = rule_gone and targets_gone and row_gone and not too_young;

        if qualifies {
            label = f"DELETE {here.tg_id}";
            self.deleted.append(here.tg_id);
            print(f"  {label} (no rule, no targets, no row, age={here.age_cycles})");
        } else {
            reason = "young" if too_young else ("has rule" if here.has_rule else ("has targets" if here.has_targets else "has DB row"));
            self.spared.append(here.tg_id);
            print(f"  KEEP   {here.tg_id} ({reason})");
        }
        visit [-->];
    }
}

walker DeadCodeReaper {
    # Walks the checkout-session subgraph and confirms the helper is gone
    # everywhere it used to be referenced. Models the second item of the PR.
    has remaining_refs: int = 0;

    can start with Root entry {
        print("[dead-code] verify_stripe_session reaper:");
        visit [-->];
    }

    can audit with CheckoutSession entry {
        if here.verify_stripe_session_removed {
            print(f"  {here.session_id}: helper already absent (zero callers)");
        } else {
            self.remaining_refs += 1;
            print(f"  {here.session_id}: helper still wired (would need migration)");
        }
        visit [-->];
    }
}

with entry {
    # --- Build the ALB-ish graph ------------------------------------------------
    # premium-100162-tg: stranded (no rule, no targets, no row, old) -> delete
    stranded = TargetGroup(tg_id="premium-100162-tg", age_cycles=3);
    # premium-7172-tg: stranded (no rule, no targets, no row, old) -> delete
    stranded_b = TargetGroup(tg_id="premium-7172-tg", age_cycles=2);
    # young TG: race window, must be spared even though rule/targets/row are gone
    young = TargetGroup(tg_id="premium-young-tg", age_cycles=0);
    # healthy TG: has a registered rule, must be spared
    healthy = TargetGroup(tg_id="premium-healthy-tg", age_cycles=4, has_rule=True, has_targets=True);
    # assigned TG: no rule/targets but a user_assignments row exists -> spared
    assigned = TargetGroup(tg_id="premium-assigned-tg", age_cycles=5);

    # The only RegisteredRule edge in the graph goes to the healthy TG, so
    # the buggy rule-driven pass can ONLY reach it. The other TGs are
    # invisible to it -- exactly the bug from #814 / issue #819.
    root +>:RegisteredRule(rule_arn="arn:rule:healthy"):+> healthy;

    root ++> stranded ++> stranded_b ++> young ++> healthy ++> assigned;

    # DB row for the assigned TG (modeled as a UserAssignment node + edge).
    ua_row = UserAssignment(user_id="u-42", tg_id="premium-assigned-tg");
    root ++> ua_row;
    ua_row +>:AssignsTo(user_id="u-42"):+> assigned;

    # --- Wire the checkout-session subgraph for the dead-code item -------------
    cs1 = CheckoutSession(session_id="cs_live_a");
    cs2 = CheckoutSession(session_id="cs_live_b");
    root ++> cs1 ++> cs2;

    # --- Run the demo ----------------------------------------------------------
    print("=== issue #819: premium cleanup + dead verify_stripe_session ===");

    # Pass 1 demonstrates the bug: it can only reach TGs via a registered
    # rule, so the stranded groups are invisible.
    root spawn OrphanCollector();

    # Pass 2 is the fix: walks all TGs directly and applies the guard.
    collector = CleanupPass();
    root spawn collector;
    print(f"  summary pass-2: deleted={collector.deleted} spared={collector.spared}");

    # Dead-code reaper confirms verify_stripe_session is gone everywhere.
    reaper = DeadCodeReaper();
    root spawn reaper;
    print(f"  verify_stripe_session remaining refs across sessions: {reaper.remaining_refs}");

    # Apply the deletions to the graph (cascade: del node purges its edges).
    del stranded;
    del stranded_b;
    print("[apply] stranded TGs removed; remaining premium-* nodes: "
          "premium-young-tg, premium-healthy-tg, premium-assigned-tg");
}
