node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has active: bool = True;
    has durable_ack: bool = False;
}

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "error";
    has observed_generation: int = 0;
}

node Lane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has lane_name: str = "";
    has complete: bool = False;
}

edge Owns { }
edge HasSession { }
edge Publishes { }
edge HasLane { }

walker RecorderAudit {
    has committed_sessions: int = 0;

    can start with Root entry {
        visit [->:Owns:->] else {
            disengage;
        }
