    can inspect_snapshot with Snapshot entry {
        print(f"snapshot generation={here.observed_generation}, state={here.state}");
        visit [->:HasLane:->] else {
            disengage;
        }
    }

    can inspect_lane with Lane entry {
        if here.complete {
            print(f"lane {here.lane_name}: complete");
        } else {
            self.failed_lanes += 1;
            print(f"lane {here.lane_name}: failed; snapshot stays error");
        }
    }
}

