import io;
import from contextlib { redirect_stdout }

# ---------- helper: run auditor on a freshly built graph ----------
def run_auditor_on(orders: list) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        # Build a linear chain root -> o1 -> o2 -> ...
        prev = rt;
        for (i, o) in enumerate(orders) {
            prev ++> o;
            prev = o;
        }
        auditor = OrderAuditor();
        res = rt spawn auditor;
    }
    return (buf.getvalue(), res);
}

test "all-valid chain audits every order and does not halt" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        o1 = Order(label="A", amount=10.00);
        o2 = Order(label="B", amount=20.00);
        o3 = Order(label="C", amount=30.00);
        root ++> o1 ++> o2 ++> o3;
        auditor = OrderAuditor();
        res = root spawn auditor;
    }
    out = buf.getvalue();
    # Every order should be [OK]
    assert "[OK]   A amount=$10.00" in out, f"missing A OK line: {out}";
    assert "[OK]   B amount=$20.00" in out, f"missing B OK line: {out}";
    assert "[OK]   C amount=$30.00" in out, f"missing C OK line: {out}";
    # No skip or halt should appear
    assert "[SKIP]" not in out, f"unexpected SKIP: {out}";
    assert "[HALT]" not in out, f"unexpected HALT: {out}";
    # Final state: all 3 audited, not halted
    assert res.audited == 3, f"expected audited=3, got {res.audited}";
    assert res.halted == False, f"expected halted=False, got {res.halted}";
}

test "invalid orders are skipped but audit continues to later valid orders" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Order(label="OK-1", amount=50.00)
            ++> Order(label="BAD", amount=0.00, valid=False)
            ++> Order(label="OK-2", amount=75.00)
            ++> Order(label="BAD2", amount=1.00, valid=False)
            ++> Order(label="OK-3", amount=99.99);
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    # Bad orders printed as SKIP, audit continued past them
    assert "[SKIP] BAD invalid ($0.00) -- moving on" in out, f"missing BAD skip: {out}";
    assert "[SKIP] BAD2 invalid ($1.00) -- moving on" in out, f"missing BAD2 skip: {out}";
    # Good orders after a skip still printed as OK -- this is the core
    # "skip but keep going" behavior
    assert "[OK]   OK-1 amount=$50.00" in out, f"missing OK-1: {out}";
    assert "[OK]   OK-2 amount=$75.00" in out, f"missing OK-2 (after skip): {out}";
    assert "[OK]   OK-3 amount=$99.99" in out, f"missing OK-3 (after skip): {out}";
    # No halt
    assert "[HALT]" not in out, f"unexpected halt on invalid-only graph: {out}";
    # Only valid orders counted: 3
    assert res.audited == 3, f"expected audited=3 (skips not counted), got {res.audited}";
    assert res.halted == False, f"expected halted=False, got {res.halted}";
}

test "fraud order halts entire walk -- nothing after it is visited" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Order(label="BEFORE", amount=100.00)
            ++> Order(label="FRAUD", amount=9999.00, fraud=True)
            ++> Order(label="NEVER", amount=50.00);
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    # BEFORE is visited first and audited
    assert "[OK]   BEFORE amount=$100.00" in out, f"missing BEFORE: {out}";
    # HALT line printed for fraud
    assert "[HALT] FRAUD flagged for fraud ($9999.00) -- stopping the whole walk" in out, f"missing HALT: {out}";
    # NEVER must NOT appear -- that's the whole point of break-style halt
    assert "NEVER" not in out, f"walk continued past fraud halt, output: {out}";
    # SKIP must not appear (no invalid orders)
    assert "[SKIP]" not in out, f"unexpected SKIP: {out}";
    # State: halted=True, only BEFORE counted
    assert res.halted == True, f"expected halted=True, got {res.halted}";
    assert res.audited == 1, f"expected audited=1 (only BEFORE), got {res.audited}";
}

test "fraud takes precedence over invalid -- fraud halts even on invalid order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Order(label="OK", amount=10.00)
            ++> Order(label="BADFRAUD", amount=5.00, valid=False, fraud=True)
            ++> Order(label="AFTER", amount=20.00);
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    # OK audited
    assert "[OK]   OK amount=$10.00" in out, f"missing OK: {out}";
    # Fraud wins over invalid: HALT fires, not SKIP
    assert "[HALT] BADFRAUD" in out, f"fraud should halt, output: {out}";
    assert "[SKIP] BADFRAUD" not in out, f"invalid should NOT skip when fraud also set: {out}";
    # AFTER unreachable
    assert "AFTER" not in out, f"walk continued past fraud: {out}";
    assert res.halted == True, f"expected halted=True, got {res.halted}";
    assert res.audited == 1, f"expected audited=1, got {res.audited}";
}

test "fraud as first order halts immediately with no audits" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Order(label="FRAUDFIRST", amount=1.00, fraud=True)
            ++> Order(label="X", amount=2.00)
            ++> Order(label="Y", amount=3.00);
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[HALT] FRAUDFIRST" in out, f"missing first-order halt: {out}";
    assert "amount=$2.00" not in out and "amount=$3.00" not in out, f"later orders visited: {out}";
    assert res.halted == True, f"expected halted=True, got {res.halted}";
    assert res.audited == 0, f"expected audited=0, got {res.audited}";
}

