```jac
"""ZipHelper-style guard: refuse to clobber a destination directory before writing.

Models the issue scenario — a destination check that is type-blind and silently
deletes a whole tree — as a native Jac graph. A `FileNode` is either a file or
a directory, and the `safe_write` walker descends to the proposed destination,
refuses if it is one (or lives inside one), and otherwise proceeds.
"""

node FileNode {
    has name: str = "";
    has kind: str = "file";   # "file" or "directory"
}

edge Contains { }              # parent directory -> child file/directory
edge WritesTo { }              # source archive -> destination path

walker SafeWrite {
    has destination_is_dir: bool = False;
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with FileNode entry {
        if here.kind == "directory" {
            self.destination_is_dir = True;
            self.blocked = True;
            print(f"REFUSED: destination '{here.name}' is a directory — would recursively delete its contents");
            disengage;
        }
        visit [-->];
    }
}

# Same walker, reverse direction: walk parent links and refuse if any is a dir.
walker CheckAncestors {
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can ascend with FileNode entry {
        if here.kind == "directory" {
            self.blocked = True;
            print(f"REFUSED: an ancestor '{here.name}' is a directory");
            disengage;
        }
        visit [<--];
    }
}

# Demonstrates the bad case: destination already exists as a directory.
# Demonstrates the good case: destination does not exist, write proceeds.
walker ZipHelper {
    has src: str = "";
    has dest_name: str = "";
    has wrote: bool = False;

    can start with Root entry {
        # Pick the archive source (a file) and its destination candidate.
        archive = FileNode(name=self.src, kind="file");
        root +>:WritesTo:+> (dest := FileNode(name=self.dest_name, kind="file"));
        root ++> archive;

        # First: descend into destination to see if it is itself a directory.
        here_safe = False;
        for d in [-->] {
            if d.name == self.dest_name {
                probe = SafeWrite();
                probe spawn d;
                if not probe.blocked {
                    here_safe = True;
                }
                break;
            }
        }

        # Also walk parents of the destination — refuse if any is a directory.
        if here_safe {
            for d in [-->] {
                if d.name == self.dest_name {
                    up = CheckAncestors();
                    up spawn d;
                    if up.blocked {
                        here_safe = False;
                    }
                    break;
                }
            }
        }

        if here_safe {
            self.wrote = True;
            print(f"WROTE zip '{self.src}' -> '{self.dest_name}' (file path is clear)");
        } else {
            print(f"ABORTED: refused to write '{self.src}' over '{self.dest_name}'");
        }
    }
}

with entry {
    # Build a small tree: an existing directory that holds a couple of files.
    existing_dir = FileNode(name="out", kind="directory");
    kept_a = FileNode(name="keep-me.txt", kind="file");
    kept_b = FileNode(name="also-keep.txt", kind="file");
    root ++> existing_dir ++> kept_a;
    existing_dir ++> kept_b;

    # Case A: destination points AT the directory — must refuse.
    print("--- Case A: destination is an existing directory ---");
    root spawn ZipHelper(src="payload.zip", dest_name="out");

    # Case B: destination is a brand-new file path inside a directory ancestor.
    # Walking ancestors still hits the directory, so it must also refuse.
    print("--- Case B: destination is a new file inside an existing directory ---");
    nested_target = FileNode(name="fresh.txt", kind="file");
    existing_dir ++> nested_target;
    root spawn ZipHelper(src="payload.zip", dest_name="fresh.txt");

    # Case C: destination is a new file with no directory ancestor — proceeds.
    print("--- Case C: destination is a brand-new file path ---");
    root spawn ZipHelper(src="payload.zip", dest_name="brand-new.zip");
}
```

