    assert sess.refreshed_at_ms == now_ms + 1000, f"refresh time: {sess.refreshed_at_ms}";
    assert sess.expires_at_ms == first_deadline, f"first deadline: {sess.expires_at_ms}";

    second_time = first_deadline - 1;
