import from contextlib { redirect_stdout }

test "skips invalid order and continues" {
    root ++> Order(amount=120.0, valid=True, fraud=False)
        ++> Order(amount=0.0, valid=False, fraud=False)
        ++> Order(amount=50.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=120.0" in out, f"missing first audit: {out}";
    assert "[SKIP] invalid order amount=0.0" in out, f"missing skip: {out}";
    assert "[AUDIT] approved order amount=50.0" in out, f"walk did not continue past skip: {out}";
}

test "halts immediately on fraud" {
    root ++> Order(amount=120.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=50.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=120.0" in out, f"missing first audit: {out}";
    assert "[HALT] fraud flagged on order amount=999.0" in out, f"missing halt on fraud: {out}";
    assert "[AUDIT] approved order amount=50.0" not in out, f"walk continued past fraud halt: {out}";
}

test "fraud as the first order halts right away" {
    root ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=50.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[HALT] fraud flagged on order amount=999.0" in out, f"missing halt: {out}";
    assert "[AUDIT] approved order amount=50.0" not in out, f"walk continued: {out}";
}

test "all valid non-fraud orders all get audited" {
    root ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=True, fraud=False)
        ++> Order(amount=30.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=10.0" in out, f"missing 10.0: {out}";
    assert "[AUDIT] approved order amount=20.0" in out, f"missing 20.0: {out}";
    assert "[AUDIT] approved order amount=30.0" in out, f"missing 30.0: {out}";
    assert "[SKIP]" not in out, f"unexpected skip printed: {out}";
    assert "[HALT]" not in out, f"unexpected halt printed: {out}";
}
