"""Tiny dungeon crawler: rooms chained as nodes, a Hunter walker counts
rooms until it reaches the vault (treasure room), then disengages so
rooms past the vault are never visited."""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon");
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        self.rooms_checked += 1;
        if here.is_vault {
            print(f"Treasure found in {here.name} after {self.rooms_checked} rooms");
            disengage;
        }
        print(f"Checked {here.name} ({self.rooms_checked} so far)");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Whispers")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Alcove")
        ++> Room(name="Hidden Crypt");

    hunter = Hunter();
    root spawn hunter;
    print(f"Total rooms checked: {hunter.rooms_checked}");
}
