```jac
"""Hiking trail: a chain of plain waypoints between trailhead and summit.

The waypoints are anonymous nodes (no fields needed) — what matters is the
chain itself. A hiker walker traverses the chain, counts each waypoint,
prints a stop line at each one, and finishes with a completion line once
it has passed enough waypoints.
"""

node Waypoint {
    has marker: int = 0;
}

walker Hiker {
    has stops_made: int = 0;
    has target_stops: int = 5;

    can start with Root entry {
        print("Hiker begins the ascent from the trailhead");
        visit [-->] else { disengage; }
    }

    can trek with Waypoint entry {
        self.stops_made += 1;
        print(f"Stop #{self.stops_made}: passed waypoint {here.marker}");
        if self.stops_made >= self.target_stops {
            print(f"Trail complete after {self.stops_made} waypoints!");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Build a chain of waypoints from the trailhead up to the summit.
    root ++> Waypoint(marker=1)
        ++> Waypoint(marker=2)
        ++> Waypoint(marker=3)
        ++> Waypoint(marker=4)
        ++> Waypoint(marker=5)
        ++> Waypoint(marker=6)
        ++> Waypoint(marker=7);

    # Target 5 stops so the hiker disengages before reaching the summit.
    Hiker(target_stops=5) spawn root;
}
```

"""Tests for the hiking trail: Hiker walker traversing a chain of Waypoint nodes."""

import io;
import from contextlib { redirect_stdout }

test "hiker traverses the chain and prints stop lines" {
    # Build a chain of 7 waypoints from the trailhead up to the summit.
    root ++> Waypoint(marker=1)
        ++> Waypoint(marker=2)
        ++> Waypoint(marker=3)
        ++> Waypoint(marker=4)
        ++> Waypoint(marker=5)
        ++> Waypoint(marker=6)
        ++> Waypoint(marker=7);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_stops=5);
    }
    out = buf.getvalue();

    # Entry banner printed from Root ability.
    assert "Hiker begins the ascent from the trailhead" in out, f"missing start banner: {out}";

    # Five consecutive stop lines, each numbered sequentially and using
    # the waypoint marker values along the chain (1..5).
    assert "Stop #1: passed waypoint 1" in out, f"missing stop #1: {out}";
    assert "Stop #2: passed waypoint 2" in out, f"missing stop #2: {out}";
    assert "Stop #3: passed waypoint 3" in out, f"missing stop #3: {out}";
    assert "Stop #4: passed waypoint 4" in out, f"missing stop #4: {out}";
    assert "Stop #5: passed waypoint 5" in out, f"missing stop #5: {out}";

    # Completion line fires exactly once the target is reached.
    assert "Trail complete after 5 waypoints!" in out, f"missing completion: {out}";

    # Walker record reflects the stop count at disengagement.
    assert res.stops_made == 5, f"expected stops_made=5, got {res.stops_made}";
    assert res.target_stops == 5, f"expected target_stops=5, got {res.target_stops}";
}

test "hiker disengages at target_stops and does not pass later waypoints" {
    # Longer chain; with default target of 5 the hiker must stop at stop #5,
    # so waypoints 6 and 7 (and the summit) are never visited.
    root ++> Waypoint(marker=1)
        ++> Waypoint(marker=2)
        ++> Waypoint(marker=3)
        ++> Waypoint(marker=4)
        ++> Waypoint(marker=5)
        ++> Waypoint(marker=6)
        ++> Waypoint(marker=7);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Stops beyond the target must not appear in the output.
    assert "Stop #6" not in out, f"hiker should disengage before stop 6: {out}";
    assert "Stop #7" not in out, f"hiker should disengage before stop 7: {out}";
    assert "waypoint 6" not in out, f"waypoint 6 should not be visited: {out}";
    assert "waypoint 7" not in out, f"waypoint 7 should not be visited: {out}";

    # Exactly one completion line at the 5th waypoint.
    assert "Trail complete after 5 waypoints!" in out, f"missing completion: {out}";
    assert res.stops_made == 5, f"expected stops_made=5, got {res.stops_made}";
}

test "hiker hits completion line exactly once" {
    # A shorter chain (4 waypoints) with target_stops=4 must complete after
    # every waypoint has been visited; the completion line should appear
    # exactly once.
    root ++> Waypoint(marker=1)
        ++> Waypoint(marker=2)
        ++> Waypoint(marker=3)
        ++> Waypoint(marker=4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_stops=4);
    }
    out = buf.getvalue();

    # All four waypoints are visited.
    assert "Stop #1: passed waypoint 1" in out, f"missing stop 1: {out}";
    assert "Stop #2: passed waypoint 2" in out, f"missing stop 2: {out}";
    assert "Stop #3: passed waypoint 3" in out, f"missing stop 3: {out}";
    assert "Stop #4: passed waypoint 4" in out, f"missing stop 4: {out}";

    # Exactly one completion line — once the target is reached the walker
    # disengages and does not print it again.
    assert out.count("Trail complete after 4 waypoints!") == 1, f"completion printed wrong number of times: {out}";
    assert res.stops_made == 4, f"expected stops_made=4, got {res.stops_made}";
}

test "hiker with target_stops=1 completes immediately on first waypoint" {
    # With target_stops=1 the hiker should reach completion after stop #1
    # and not visit any subsequent waypoint.
    root ++> Waypoint(marker=1)
        ++> Waypoint(marker=2)
        ++> Waypoint(marker=3)
        ++> Waypoint(marker=4)
        ++> Waypoint(marker=5);

    buf = io.StringIO();
