"""Call graph explorer: model a code navigation graph where symbols are nodes
and call edges connect them. A librarian walker expands neighbors from a
selected symbol, mirroring the "graph build + neighbors + HTML explorer"
behavior described in the issue."""

node Symbol {
    has title: str = "";
    has kind: str = "function";
    has file_path: str = "";
    has start_line: int = 0;
    has end_line: int = 0;
    has exported: bool = False;
    has resolved: bool = True;
    has visit_count: int = 0;
}

edge Calls {
    has call_type: str = "function";
    has lines: list[int] = [];
    has resolution: str = "resolved";
}

walker CallExplorer {
    has target_name: str = "";
    has depth_limit: int = 2;
    has outgoing_calls: list[str] = [];
    has incoming_callers: list[str] = [];
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can find_target with Symbol entry {
        if here.title == self.target_name {
            self.found = True;
            here.visit_count += 1;
            print(f"[target] {here.title} ({here.kind}) at {here.file_path}:{here.start_line}");
            visit [->:Calls:->];
        } else {
            visit [-->];
        }
    }

    can expand_calls with Symbol entry {
        if self.depth_limit <= 0 {
            disengage;
        }
        here.visit_count += 1;
        label = f"{here.title} ({here.kind}) at {here.file_path or 'synthetic'}";
        self.outgoing_calls.append(label);
        print(f"  -> {label}");
        self.depth_limit -= 1;
        visit [->:Calls:->];
        self.depth_limit += 1;
        disengage;
    }

    can report with Root entry {
        print(f"\nSummary for {self.target_name}:");
        print(f"  outgoing calls: {len(self.outgoing_calls)}");
        for c in self.outgoing_calls {
            print(f"    {c}");
        }
        print(f"  found: {self.found}");
    }
}

walker CallAuditor {
    has unresolved: list[str] = [];
    has external: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can tally with Symbol entry {
        if not here.resolved and here.kind == "unresolved_call" {
            self.unresolved.append(here.title);
        }
        if here.kind == "external_call" {
            self.external.append(here.title);
        }
        visit [-->];
    }

    can report with Root entry {
        print(f"\n=== CallAuditor totals ===");
        print(f"  unresolved: {len(self.unresolved)}");
        for u in self.unresolved {
            print(f"    ? {u}");
        }
        print(f"  external:   {len(self.external)}");
        for e in self.external {
            print(f"    ~ {e}");
        }
    }
}

walker CallerFinder {
    has target_name: str = "";
    has callers: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Symbol entry {
        for callee in [->:Calls:->] {
            if callee.title == self.target_name {
                self.callers.append(here.title);
            }
        }
        visit [-->];
    }

    can report with Root entry {
        print(f"\ncallers of {self.target_name}: {self.callers}");
    }
}

with entry {
    create_handler = Symbol(title="createHandler", kind="function", file_path="src/lambda/handler.ts", start_line=120, end_line=140, exported=True);
    poll_agreements = Symbol(title="pollAgreements", kind="function", file_path="src/service/pollAgreements.ts", start_line=19, end_line=130, exported=True);
    fetch_batch = Symbol(title="fetchBatch", kind="function", file_path="src/service/pollAgreements.ts", start_line=40, end_line=80);
    store_agreement = Symbol(title="storeAgreement", kind="method", file_path="src/service/pollAgreements.ts", start_line=90, end_line=110);
    s3_ctor = Symbol(title="S3FileStore", kind="constructor", file_path="src/adapters/S3FileStore.ts", start_line=10, end_line=30);

    unresolved_put = Symbol(title="deps.fileStore.put", kind="unresolved_call", resolved=False);
    external_log = Symbol(title="console.log", kind="external_call", resolved=False);

    root ++> create_handler;
    create_handler +>:Calls(call_type="function", lines=[126], resolution="resolved"):+> poll_agreements;
    create_handler +>:Calls(call_type="function", lines=[131], resolution="external"):+> external_log;
    poll_agreements +>:Calls(call_type="function", lines=[55], resolution="resolved"):+> fetch_batch;
    poll_agreements +>:Calls(call_type="method", lines=[95], resolution="unresolved"):+> unresolved_put;
    poll_agreements +>:Calls(call_type="constructor", lines=[105], resolution="resolved"):+> s3_ctor;
    fetch_batch +>:Calls(call_type="method", lines=[70], resolution="resolved"):+> store_agreement;

    print("=== CallExplorer: forward from pollAgreements (depth=2) ===");
    explorer = CallExplorer(target_name="pollAgreements", depth_limit=2);
