"""Tests for the hiking trail program."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts and prints every waypoint stop" {
    root ++> Trailhead(title="Start")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(title="Top");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Stop 1" in out, f"missing Stop 1: {out}";
    assert "Stop 2" in out, f"missing Stop 2: {out}";
    assert "Stop 3" in out, f"missing Stop 3: {out}";
    assert "Trail complete: passed 3 waypoints." in out, f"missing completion line: {out}";
}

test "hiker disengages at summit and reports exact count" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    h = Hiker();
    with redirect_stdout(buf) {
        res = root spawn h;
    }
    out = buf.getvalue();

    assert res.stop_count == 5, f"expected 5 waypoints passed, got {res.stop_count}";
    assert "Trail complete: passed 5 waypoints." in out, f"missing completion: {out}";
}

test "chain shape links trailhead to summit via plain waypoints" {
    root ++> Trailhead(title="A")
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(title="Z");

    th = [root -->][0];
    assert len([th -->]) == 1, "trailhead should have exactly one outgoing edge";

    cur = th;
    waypoint_count = 0;
    while len([cur -->]) > 0 {
        cur = [cur -->][0];
        if isinstance(cur, Waypoint) {
            waypoint_count += 1;
        }
    }
    assert waypoint_count == 2, f"expected 2 waypoints between trailhead and summit, got {waypoint_count}";
    assert isinstance(cur, Summit), f"chain should terminate at Summit, got {type(cur)}";
}

test "trail with zero waypoints still completes" {
    root ++> Trailhead()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Stop 1" not in out, f"should not print any Stop lines when no waypoints exist: {out}";
    assert "Trail complete: passed 0 waypoints." in out, f"missing completion with zero count: {out}";
}

