# ---------------------------------------------------------------------------
# 1. Treasure at the very first room: Hunter should inspect exactly one room
#    and never step into any successor.
# ---------------------------------------------------------------------------
test "hunter stops immediately when first room is the vault" {
    root ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Hallway")
        ++> Room(name="Armory");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

