    assert res.seen == 1, f"expected exactly 1 room inspected, got {res.seen}";
    assert "Treasure found in 'Vault'" in out, f"missing vault announcement: {out}";
    assert "Inspected 'Hallway'" not in out, f"hunter must not enter Hallway: {out}";
    assert "Inspected 'Armory'" not in out, f"hunter must not enter Armory: {out}";
}

# ---------------------------------------------------------------------------
# 2. Treasure in the middle: Hunter visits the treasure room plus all rooms
#    strictly before it, but MUST NOT visit any room after the vault.
# ---------------------------------------------------------------------------
test "hunter never visits rooms past the vault" {
