    assert "Inspected 'Entrance'" in out, f"should inspect Entrance: {out}";
    assert "Inspected 'Hallway'" in out, f"should inspect Hallway: {out}";
    assert "Treasure found in 'Vault'" in out, f"missing vault announcement: {out}";
    # Hard guarantee from the spec: rooms past the vault must never be visited.
    assert "Throne Room" not in out, f"hunter must never reach Throne Room: {out}";
    assert "Dungeon Pit" not in out, f"hunter must never reach Dungeon Pit: {out}";
}

# ---------------------------------------------------------------------------
