```jac
"""Systemd-analyze CI verification: walk systemd unit files and enforce
strict verification, surfacing unknown keys in slices/services/timers.

Models the fleet-ops#92 scenario: a CI job iterates over unit files in a
`systemd/` directory tree. Default `systemd-analyze verify` silently
ignores unknown keys; adding `--recursive-errors=no` promotes those
warnings into hard failures. Walkers traverse the file graph and flag
malformed units the way the patched CI loop would.
"""

node Unit {
    has name: str = "";
    has kind: str = "";
    has unknown_keys: list[str] = [];
    has strict_passes: bool = True;

    def describe() -> str {
        return f"{self.kind} {self.name}";
    }
}

node Slice(Unit) {
    has memory_max: str = "";
    has cpu_weight: int = 100;

    def describe() -> str {
        return f"slice {self.name}";
    }
}

node Service(Unit) {
    has exec_start: str = "";
    has user: str = "";

    def describe() -> str {
        return f"service {self.name}";
    }
}

node Timer(Unit) {
    has on_calendar: str = "";
    has unit_ref: str = "";

    def describe() -> str {
        return f"timer {self.name}";
    }
}

edge ContainsFile {}
edge DependsOn {}

walker VerifyUnits {
    has failures: list[str] = [];
    has strict: bool = True;
    has visited: list[str] = [];

    can start with Root entry {
        print("== systemd-analyze verify (strict) ==");
        visit [->:ContainsFile:->];
    }

    can check with Unit entry {
        # Cycle / re-entry guard: walkers have no built-in dedupe in
        # jac 0.36.1, so the walker tracks visited names explicitly.
        already = False;
        for seen in self.visited {
            if seen == here.name {
                already = True;
            }
        }
        if already {
            visit [->:DependsOn:->];
        }
        self.visited.append(here.name);

        strict_label = "strict" if self.strict else "lenient";
        if here.unknown_keys {
            here.strict_passes = False;
            self.failures.append(here.describe());
            for k in here.unknown_keys {
                print(f"  [FAIL:{strict_label}] {here.describe()} -> Unknown key name {k} ignoring.");
            }
        } else {
            print(f"  [OK:{strict_label}] {here.describe()}");
        }

        visit [->:DependsOn:->];
    }
}

with entry {
    # Build a small systemd-style unit graph: one root slice, two
    # dependent slices, one service, one timer. One slice carries a
    # bogus key to model the malformed-unit case the CI patch catches.
    oomd = Slice(name="oomd-drill.slice", memory_max="512M", unknown_keys=[]);
    app = Slice(name="app.slice", cpu_weight=200, unknown_keys=["NotARealKey=1"]);
    api_svc = Service(name="api.service", exec_start="/usr/bin/api", user="nobody");
    boot_timer = Timer(name="boot.timer", on_calendar="daily", unit_ref="boot.service");

    root +>:ContainsFile:+> oomd;
    root +>:ContainsFile:+> api_svc;
    root +>:ContainsFile:+> boot_timer;
    oomd +>:DependsOn:+> app;
    app +>:DependsOn:+> api_svc;

    # Strict run (the patched CI loop with --recursive-errors=no).
    strict_runner = VerifyUnits(strict=True);
    root spawn strict_runner;
    print(f"\nStrict failures: {strict_runner.failures}");

    # Lenient baseline: default verify ignores unknown keys.
    lenient_runner = VerifyUnits(strict=False);
    root spawn lenient_runner;
    print(f"Lenient failures: {lenient_runner.failures}");
}
