```jac
"""Workflow execution hardening: dependency-ordered traversal, durable node claims with leases, and crash recovery for stuck side-effect nodes."""

node WorkflowNode {
    has title: str = "";
    has action: str = "";
    has year: int = 0;
    has available: bool = True;
    has completed: bool = False;
    has claim_status: str = "pending";
    has idempotency_key: str = "";
    has lease_expires_at: int = 0;
    has worker_id: str = "";
}

node WorkflowRun {
    has run_id: str = "";
    has clock: int = 0;
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }

walker LeaseSweeper {
    has clock: int = 0;
    has recovered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with WorkflowRun entry {
        self.clock = here.clock;
        print(f"Sweeping stuck claims for {here.run_id} at t={self.clock}");
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can revive with WorkflowNode entry {
        if here.claim_status == "running" and here.lease_expires_at < self.clock {
            print(
                f"  RECOVER {here.title}: expired lease "
                f"(worker={here.worker_id}, key={here.idempotency_key})"
            );
            here.claim_status = "pending";
            here.worker_id = "";
            self.recovered += 1;
        }
        visit [->:DependsOn:->] else {
            visit [-->];
        };
    }
}

walker DependencyExecutor {
    has run_clock: int = 0;
    has executed: int = 0;
    has side_effects: int = 0;
    has skipped_stuck: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with WorkflowRun entry {
        self.run_clock = here.clock;
        print(f"Executing workflow {here.run_id} at t={self.run_clock}");
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can run_node with WorkflowNode entry {
        if here.claim_status == "running" {
            print(f"  BLOCKED {here.title}: claim still held (worker={here.worker_id})");
            self.skipped_stuck += 1;
            visit [->:DependsOn:->] else {
                visit [-->];
            };
        } else {
            if here.completed {
                print(f"  SKIP {here.title}: already done (key={here.idempotency_key})");
                visit [->:DependsOn:->] else {
                    visit [-->];
                };
            } else {
                is_side = (
                    here.action == "send_email"
                    or here.action == "post_reply"
                    or here.action == "send_dm"
                );
                here.claim_status = "running";
                here.worker_id = "worker-live";
                here.lease_expires_at = self.run_clock + 30;
                kind = "SIDE-EFFECT" if is_side else "pure";
                print(
                    f"  RUN [{kind}] {here.title} "
                    f"(action={here.action}, key={here.idempotency_key})"
                );
                here.claim_status = "completed";
                here.completed = True;
                self.executed += 1;
                if is_side {
                    self.side_effects += 1;
                }
                visit [->:DependsOn:->] else {
                    visit [-->];
                };
            }
        }
    }
}

walker CycleGuard {
    has stack: list[str] = [];
    has seen: list[str] = [];
    has found_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan with WorkflowRun entry {
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can probe with WorkflowNode entry {
        label = here.title;
        if label in self.stack {
            self.found_cycle = True;
            print(f"  CYCLE detected at node {label}");
            disengage;
        }
        if label not in self.seen {
            self.stack.append(label);
            visit [->:DependsOn:->] else {
                self.stack.pop();
            };
            self.seen.append(label);
        }
        visit [-->];
    }
}

with entry {
    run = WorkflowRun(run_id="exec-4113", clock=100);

    ingest = WorkflowNode(
        title="Ingest Data",
        action="ingest",
        idempotency_key="exec-4113:ingest"
    );
    validate = WorkflowNode(
        title="Validate Payload",
        action="validate",
        idempotency_key="exec-4113:validate"
    );
    send_email = WorkflowNode(
        title="Send Email",
        action="send_email",
        claim_status="running",
        lease_expires_at=50,
        worker_id="worker-crashed",
        idempotency_key="exec-4113:send_email"
    );
    post_reply = WorkflowNode(
        title="Post Reply",
        action="post_reply",
        idempotency_key="exec-4113:post_reply"
    );

    root ++> run;
    run +>:DependsOn:+> ingest;
    ingest +>:DependsOn:+> validate;
    validate +>:DependsOn:+> send_email;
    send_email +>:DependsOn:+> post_reply;

    print("=== Phase 1: recover crash-stuck running claims ===");
    sweeper = LeaseSweeper();
    root spawn sweeper;

