        if here.flagged_fraud {
            print(f"[HALT] Fraud flag on '{here.title}' (${here.amount:.2f}) — stopping walk");
            disengage;
        }

        action = "SKIPPED" if not here.valid else "AUDITED";
        print(f"[{action}] '{here.title}' amount=${here.amount:.2f}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(title="PO-1001", amount=250.00, valid=True)
        ++> Order(title="PO-1002", amount=89.50, valid=False)
        ++> Order(title="PO-1003", amount=1200.00, valid=True, flagged_fraud=True)
        ++> Order(title="PO-1004", amount=42.00, valid=True);

    root spawn OrderAuditor();
}
