"""Regression tests for the typst #8066 recursive matrix show rule demo."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helper: capture stdout for a single walker spawn.
# ---------------------------------------------------------------------------

def run_walker(spawn_target, walker_cls, **kwargs) -> tuple {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = spawn_target spawn walker_cls(**kwargs);
    }
    return (res, buf.getvalue());
}

# ---------------------------------------------------------------------------
# The unmitigated walker mirrors the reported OOM: it grows
# rendered_bytes by ~1 MiB per step and disengages only when the
# explicit cap is hit.
# ---------------------------------------------------------------------------

test "unguarded walker grows rendered_bytes until cap" {
    m = Matrix(name="leaky", rows=1);
    m +>:MatShow(rule="math.mat(it.rows)"):+> m;
    rt = root;
    rt ++> m;

    (res, out) = run_walker(rt, UnguardedShowWalker);

    assert res.steps == res.max_steps, f"expected to hit cap, got steps={res.steps}";
    assert res.max_steps == 50, f"cap should default to 50, got {res.max_steps}";
    assert res.depth == 0, f"depth stays at 0 (unused), got {res.depth}";
    assert m.rendered_bytes == 50 * 1024 * 1024, f"rendered_bytes should be 50 MiB, got {m.rendered_bytes}";
    assert "[unguarded]" in out, f"missing unguarded tag in output: {out!r}";
    assert "OOM-equivalent" in out, f"missing OOM marker in output: {out!r}";
    assert "rendered_bytes=" in out, f"missing byte count in output: {out!r}";
}

# ---------------------------------------------------------------------------
# MatShow edges must be followed specifically — other outgoing edges
# are NOT traversed by the show rule walker.
# ---------------------------------------------------------------------------

test "unguarded walker traverses MatShow edges, not arbitrary children" {
    target = Matrix(name="target", rows=2);
    decoy = Matrix(name="decoy", rows=99);
    # Typeless link to decoy — should be ignored by [->:MatShow:->]
    target ++> decoy;
    # Typed MatShow loop back to target itself
    target +>:MatShow(rule="expand"):+> target;
    rt = root;
    rt ++> target;

    (res, out) = run_walker(rt, UnguardedShowWalker, max_steps=5);

    assert res.steps == 5, f"should run 5 steps, got {res.steps}";
    # Only the target's rendered_bytes grows — the decoy is never visited.
    assert target.rendered_bytes == 5 * 1024 * 1024, f"target bytes wrong: {target.rendered_bytes}";
    assert decoy.rendered_bytes == 0, f"decoy should be untouched, got {decoy.rendered_bytes}";
}

# ---------------------------------------------------------------------------
# The guarded walker (the user's proposed base case) must disengage
# as soon as it re-enters a Matrix it has already seen.
# ---------------------------------------------------------------------------

test "guarded walker disengages on self-loop cycle" {
    m = Matrix(name="selfloop", rows=1);
    m +>:MatShow(rule="math.mat(it.rows)"):+> m;
    rt = root;
    rt ++> m;

    (res, out) = run_walker(rt, CyclicShowWalker);

    assert res.steps == 1, f"first entry is the only real step, got {res.steps}";
    assert "selfloop" in res.visited, f"visited should record name, got {res.visited}";
    assert len(res.visited) == 1, f"visited should not double-record, got {res.visited}";
    assert m.rendered_bytes == 256, f"bounded allocation, got {m.rendered_bytes}";
    assert "[guarded]" in out, f"missing guarded tag: {out!r}";
    assert "cycle detected" in out, f"missing cycle marker: {out!r}";
    assert "selfloop" in out, f"missing node name in output: {out!r}";
}

# ---------------------------------------------------------------------------
# The guarded walker must traverse legitimate MatShow chains in order,
# recording each new node in visited, and only disengage when a node
# repeats.
# ---------------------------------------------------------------------------

test "guarded walker walks a chain and only stops on actual cycle" {
    a = Matrix(name="a", rows=1);
    b = Matrix(name="b", rows=2);
    c = Matrix(name="c", rows=4);
    a +>:MatShow(rule="step1"):+> b;
    b +>:MatShow(rule="step2"):+> c;
    # No self-loop on c — the walker should not disengage here.
    rt = root;
    rt ++> a;

    (res, out) = run_walker(rt, CyclicShowWalker);

    assert res.steps == 3, f"should step through a,b,c: {res.steps}";
    assert res.visited == ["a", "b", "c"], f"visit order wrong: {res.visited}";
    # c is visited once but its MatShow leads nowhere — no disengage message.
    assert "cycle detected" not in out, f"should not report cycle on a chain: {out!r}";
    assert a.rendered_bytes == 256, f"a bytes: {a.rendered_bytes}";
    assert b.rendered_bytes == 256, f"b bytes: {b.rendered_bytes}";
    assert c.rendered_bytes == 256, f"c bytes: {c.rendered_bytes}";
}

# ---------------------------------------------------------------------------
# Cycle that is NOT a self-loop: a -> b -> a. The guard must catch the
# revisit of "a" after the second hop.
# ---------------------------------------------------------------------------

test "guarded walker catches two-node cycle on second visit" {
    a = Matrix(name="A", rows=1);
    b = Matrix(name="B", rows=1);
    a +>:MatShow(rule="toB"):+> b;
    b +>:MatShow(rule="toA"):+> a;
    rt = root;
    rt ++> a;

    (res, out) = run_walker(rt, CyclicShowWalker);

    assert res.steps == 2, f"two real steps before revisit, got {res.steps}";
    assert res.visited == ["A", "B"], f"visit order: {res.visited}";
    assert "'A'" in out or "A" in out, f"should report revisit of A: {out!r}";
    assert "cycle detected" in out, f"missing cycle marker: {out!r}";
}
