    assert "Stop 2" in out, f"missing Stop 2 in: {out!r}";
    assert "Stop 3" in out, f"missing Stop 3 in: {out!r}";
    assert "Stop 4" in out, f"missing Stop 4 in: {out!r}";

    # Completion line should fire exactly once, on the 4th stop.
    assert "Summit reached after 4 stops!" in out, f"missing completion line in: {out!r}";
    assert out.count("Summit reached") == 1, f"completion line printed multiple times: {out!r}";

    # After reaching the target the walker must disengage, so the 5th
    # waypoint should NOT be announced.
    assert "Stop 5" not in out, f"hiker did not disengage after target, got: {out!r}";

    # Walker count must reflect the number of waypoints actually visited.
    assert res.count == 4, f"expected count=4, got {res.count}";
