"""Order auditor with side-by-side early-return flavors.

Skips invalid orders (audit continues) but halts the walk on fraud
flagged orders. Each fired action prints a line.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"HALT on fraud: order amount={here.amount}");
            disengage;
        }
        if not here.valid {
            print(f"SKIP invalid: order amount={here.amount}");
            visit [-->];
        }
        print(f"AUDIT ok: order amount={here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(amount=120.0)
        ++> Order(amount=80.0, valid=False)
        ++> Order(amount=300.0)
        ++> Order(amount=50.0, fraud=True)
        ++> Order(amount=200.0);
    root spawn OrderAuditor();
}
