test "parent prefix mutations do not change fork snapshot" {
    m1 = Message(content="hello");
    m2 = Message(content="world");
    m3 = Message(content="foo");
    m4 = Message(content="bar");
    m1 +>:Append(order=0):+> m2;
    m2 +>:Append(order=1):+> m3;
    m3 +>:Append(order=2):+> m4;

    fork_edge = Fork(
        offset=2,
        inherited_snapshot=["hello", "world"],
        sealed=True
    );
    m2 +>:fork_edge:+> m3;

    before = m2 spawn TranscriptAuditor();
    assert len(before.visited) == 3, f"got {len(before.visited)} visited messages";
    assert m1 not in before.visited, f"parent prefix was traversed: {before.visited}";
    assert m3 in [m2 ->:Append:->], f"missing child continuation edge";

    m1.content = "HELLO-MUTATED";
    m1.edited = True;
    m1.deleted = True;
    m2.content = "WORLD-MUTATED";
    m2.excluded = True;
    [m2 ->:Append:->][0].order = 99;

    after = m2 spawn TranscriptAuditor();
    assert fork_edge.inherited_snapshot == ["hello", "world"], f"got {fork_edge.inherited_snapshot}";
    assert len(fork_edge.inherited_snapshot) == fork_edge.offset, f"got {len(fork_edge.inherited_snapshot)} for offset {fork_edge.offset}";
    assert len(after.visited) == 3, f"got {len(after.visited)} visited messages";
    assert m1 not in after.visited, f"mutated parent prefix was traversed: {after.visited}";
}

test "unrelated parent append does not extend inherited prefix" {
    m1 = Message(content="one");
    m2 = Message(content="two");
    m3 = Message(content="three");
    m4 = Message(content="four");
    m1 +>:Append(order=0):+> m2;
    m2 +>:Append(order=1):+> m3;
    m3 +>:Append(order=2):+> m4;

    fork_edge = Fork(
        offset=2,
        inherited_snapshot=["one", "two"],
        sealed=True
    );
    m2 +>:fork_edge:+> m3;

    m5 = Message(content="later-parent-work");
    m4 +>:Append(order=3):+> m5;

    res = m2 spawn TranscriptAuditor();
    assert fork_edge.sealed == True, f"fork is not sealed: {fork_edge.sealed}";
    assert fork_edge.inherited_snapshot == ["one", "two"], f"got {fork_edge.inherited_snapshot}";
    assert len(fork_edge.inherited_snapshot) == 2, f"got {len(fork_edge.inherited_snapshot)}";
    assert len(res.visited) == 4, f"got {len(res.visited)} continuation messages";
    assert m5 in res.visited, f"later continuation was not traversed: {res.visited}";
}

test "child continuation mutations leave inherited messages unchanged" {
    m1 = Message(content="keep-a");
    m2 = Message(content="keep-b");
    m3 = Message(content="child-a");
    m4 = Message(content="child-b");
    m1 +>:Append(order=0):+> m2;
    m2 +>:Append(order=1):+> m3;
    m3 +>:Append(order=2):+> m4;

    fork_edge = Fork(
        offset=2,
        inherited_snapshot=["keep-a", "keep-b"],
        sealed=True
    );
    m2 +>:fork_edge:+> m3;

    m3.content = "child-a-edited";
    m3.edited = True;
    m4.deleted = True;
    m4.excluded = True;
    res = m2 spawn TranscriptAuditor();

    assert fork_edge.inherited_snapshot[0] == "keep-a", f"got {fork_edge.inherited_snapshot[0]}";
    assert fork_edge.inherited_snapshot[1] == "keep-b", f"got {fork_edge.inherited_snapshot[1]}";
    assert m3 in res.visited, f"child continuation was not visited: {res.visited}";
    assert m4 in res.visited, f"child continuation tail was not visited: {res.visited}";
    assert len(fork_edge.inherited_snapshot) == 2, f"got {len(fork_edge.inherited_snapshot)}";
}
