"""Build performance audit: model crates, features, and duplicate versions as a graph.

Walk the dependency graph to surface the slowest compilation units and the
duplicate-version offenders — the traversal pattern the issue reporter
hand-rolled with adjacency maps and recursive walks.
"""

node Crate {
    has name: str = "";
    has total_time_s: float = 0.0;
    has frontend_s: float = 0.0;
    has codegen_s: float = 0.0;
    has dirty: bool = True;
}

node FeatureSet {
    has name: str = "";
    has backend: str = "";
}

node BuildScript {
    has name: str = "";
    has c_compile_s: float = 0.0;
}

edge DependsOn { has via_kind: str = ""; }
edge CompilesWith { has role: str = ""; }
edge DuplicateVersionOf { has reason: str = ""; }

walker BuildAuditor {
    has slow_threshold: float = 20.0;
    has slow: list = [];
    has dupes: list = [];

    can start with Root entry {
        print("=== Build Performance Audit (2026-07-20) ===");
        visit [-->];
    }

    can sweep with Crate | FeatureSet | BuildScript entry {
        visit [-->];
    }

    can rank with Crate entry {
        verdict = "SLOW" if here.total_time_s >= self.slow_threshold else "ok";
        if here.total_time_s >= self.slow_threshold {
            self.slow.append([here.name, here.total_time_s, verdict]);
            print(f"[{verdict}] {here.name}: {here.total_time_s:.1f}s");
        }
        visit [->:DependsOn:->];
    }

    can version_seed with Crate entry {
        self.dupes.append([here.name, 1]);
        visit [->:DuplicateVersionOf:->] else {
            disengage;
        }
    }

    can version_count with Crate entry {
        last = self.dupes[-1];
        last[1] = last[1] + 1;
        visit [->:DuplicateVersionOf:->];
    }
}

walker CascadeDelete {
    can start with Root entry {
        visit [-->];
    }

    can drop with Crate entry {
        victim = here;
        print(f"pruning {victim.name} ({victim.total_time_s:.1f}s)");
        del victim;
        visit [-->];
    }
}

with entry {
    aws_lc_sys = Crate(name="aws-lc-sys", total_time_s=85.7, frontend_s=0.0, codegen_s=85.7);
    libgit2_sys = BuildScript(name="libgit2-sys", c_compile_s=71.9);
    syn_v2 = Crate(name="syn", total_time_s=28.1, frontend_s=4.0, codegen_s=24.1);
    rustls = Crate(name="rustls", total_time_s=23.4, frontend_s=3.7, codegen_s=19.7);
    rustls_ring = FeatureSet(name="rustls-ring", backend="ring");
    rustls_aws = FeatureSet(name="rustls-aws-lc", backend="aws-lc-rs");
    jsonschema = Crate(name="jsonschema", total_time_s=22.7, frontend_s=2.8, codegen_s=19.9);

    jsonschema +>:DependsOn(via_kind="reqwest"):+> rustls;
    rustls +>:CompilesWith(role="backend"):+> rustls_ring;
    rustls +>:CompilesWith(role="backend"):+> rustls_aws;
    rustls_aws +>:DependsOn:+> aws_lc_sys;

    libgit2_sys +>:DependsOn(via_kind="https"):+> rustls;

    getrandom_v2 = Crate(name="getrandom-0.2", total_time_s=0.5);
    getrandom_v3 = Crate(name="getrandom-0.3", total_time_s=0.5);
    getrandom_v4 = Crate(name="getrandom-0.4", total_time_s=0.5);
    getrandom_v2 +>:DuplicateVersionOf(reason="legacy crate"):+> getrandom_v3;
    getrandom_v3 +>:DuplicateVersionOf(reason="new major"):+> getrandom_v4;

    root ++> aws_lc_sys ++> libgit2_sys ++> syn_v2 ++> rustls ++> rustls_ring ++> rustls_aws ++> jsonschema ++> getrandom_v2 ++> getrandom_v3 ++> getrandom_v4;

    auditor = BuildAuditor(slow_threshold=20.0);
    root spawn auditor;

    print("");
    print("=== Slow compilation units ===");
    for item in auditor.slow {
        print(f"  {item[0]}: {item[1]:.1f}s [{item[2]}]");
    }

    print("");
    print("=== getrandom version lineage ===");
    for item in auditor.dupes {
        print(f"  {item[0]} -> count {item[1]}");
    }
}
