```jac
"""Repo LSP inventory: keep zero-edge symbol nodes out of the structural
traversal projection while preserving exact search across them.

Models the scenario from RNA #844 in miniature: a repository has both
structural source files (with real LSP edges such as imports and calls)
and large zero-edge symbol inventories (e.g. gettext translation keys,
plaintext cohort entries) that are useful for exact lookup but should
NOT be hydrated during a code-graph traversal.
"""

node Repo {
    has name: str = "";
}

node SourceFile {
    has path: str = "";
    has language: str = "";
}

node Symbol {
    # A structural LSP symbol with real graph relationships (definitions,
    # references, imports). Lives on the traversal graph.
    has name: str = "";
    has kind: str = "";
}

node VirtualSymbol {
    # A zero-edge LSP "virtual" node (translation key, plaintext entry).
    # Searchable by exact name; carries no structural edges.
    has key: str = "";
    has provenance: str = "";
}

node TraversalRoot {
    # The single anchor exact-node graph traversal starts from. Marked
    # so walker's typed-edge filter ignores VirtualSymbol inventories.
    has label: str = "";
}

edge Owns {}
edge Imports {}
edge Calls {}
edge Holds {}

walker ExactLookup {
    # An exact-name search across the whole repo. Walks every node type
    # so search-only inventories stay reachable for queries.
    has query: str = "";
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can search_repo with Repo entry {
        visit [-->];
    }

    can search_file with SourceFile entry {
        visit [-->];
    }

    can search_symbol with Symbol entry {
        if here.name == self.query {
            self.matches.append(f"Symbol:{here.name}");
        }
        visit [-->];
    }

    can search_virtual with VirtualSymbol entry {
        if here.key == self.query {
            self.matches.append(f"VirtualSymbol:{here.key}");
        }
        visit [-->];
    }

    can search_index with TraversalRoot entry {
        visit [-->];
    }
}

walker CodeGraphTraversal {
    # Exact-node graph traversal. Follows ONLY structural edges
    # (Owns / Imports / Calls). Never hydrates VirtualSymbol
    # inventories; virtual nodes have no structural edges at all in
    # the projection defined by the fix in #844.
    has visited_symbols: list[str] = [];
    has hydrated_virtual_count: int = 0;

    can start with TraversalRoot entry {
        print(f"Starting structural traversal from {here.label}");
        visit [->:Owns:->];
    }

    can walk_files with SourceFile entry {
        print(f"  file: {here.path} [{here.language}]");
        visit [->:Imports:->];
    }

    can walk_symbols with Symbol entry {
        self.visited_symbols.append(here.name);
        print(f"  symbol: {here.name} ({here.kind})");
        visit [->:Calls:->];
    }

    # Defensive ability: if a VirtualSymbol somehow ended up adjacent
    # on a typed structural edge the walker would land here. The fix
    # in #844 is to NOT add Holds edges from code-graph nodes to
    # virtual inventories, so this path is only reachable through a
    # regression. We assert the invariant and disengage.
    can reject with VirtualSymbol entry {
        self.hydrated_virtual_count += 1;
        print(f"  [WARN] hydrated virtual node {here.key}; traversal should skip");
        disengage;
    }
}

with entry {
    repo = Repo(name="django");

    # One structural file with a real import edge and a couple of symbols.
    auth = SourceFile(path="src/auth.py", language="python");
    user_model = Symbol(name="User", kind="class");
    login_fn = Symbol(name="login", kind="function");

    # A zero-edge virtual inventory: gettext translation keys. These are
    # searchable but must not be on the structural traversal graph.
    tx_root = VirtualSymbol(
        key="auth.login.button",
        provenance="gettext/babel-lsp"
    );
    tx_welcome = VirtualSymbol(
        key="auth.welcome.message",
        provenance="gettext/babel-lsp"
    );

    root +>:Owns:+> repo;
    repo +>:Owns:+> auth;
    auth +>:Imports:+> Symbol(name="hashlib", kind="module");
    auth +>:Calls:+> user_model;
    auth +>:Calls:+> login_fn;

    # A dedicated search-only index for zero-edge virtual inventories.
    # Virtual symbols live here, NOT under any structural code node,
    # so the structural walker never even considers them.
    search_index = TraversalRoot(label="search-index");
    root +>:Holds:+> search_index;
    search_index +>:Holds:+> tx_root;
    search_index +>:Holds:+> tx_welcome;

    # 1) Exact lookup still finds the translation key, walking through
    #    both the structural code-graph AND the search-only inventory.
    lookup = ExactLookup(query="auth.login.button");
    repo spawn lookup;
    print(f"exact matches for 'auth.login.button': {lookup.matches}");

    # 2) Code-graph traversal starts from a structural root and must
    #    not hydrate virtual inventories.
    code_root = TraversalRoot(label="auth.py");
    root +>:Owns:+> code_root;
    code_root +>:Owns:+> auth;

    code_walker = CodeGraphTraversal();
    code_root spawn code_walker;
    print(
        f"visited symbols: {code_walker.visited_symbols}; "
        f"hydrated virtual nodes: {code_walker.hydrated_virtual_count}"
    );
}
