    assert len(collector.result) == len(collector.seen), f"dupes: {collector.result} vs {collector.seen}";
    assert collector.result.count("did:b") == 1, f"b duplicated: {collector.result}";
    assert collector.result.count("did:c") == 1, f"c duplicated: {collector.result}";
    assert collector.result.count("did:a") == 1, f"a duplicated: {collector.result}";
    assert "did:b" in collector.result, f"missing b: {collector.result}";
    assert "did:c" in collector.result, f"missing c: {collector.result}";
