```jac
"""Kitchen line health inspection: grill, fryer, cold prep stations.

A health inspector walker sweeps the kitchen line, checking every
station's temperature (flagging anything above 40 C as a violation)
and logging each station visit. Both checks run at every station
via two union-triggered abilities on the same walker.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

walker HealthInspector {
    has log: list[str] = [];
    has violations: list[str] = [];

    can start with Root entry {
        print(f"Inspector beginning sweep");
        visit [-->];
    }

    can sweep with Station entry {
        # Log every visit regardless of temperature status.
        self.log.append(f"Visited {here.name} at {here.temperature} C");

        # Flag any station above 40 C as a violation.
        violation = "yes" if here.temperature > 40.0 else "no";
        if violation == "yes" {
            self.violations.append(
                f"{here.name} ({here.temperature} C exceeds 40 C)"
            );
        }

        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", temperature=180.0);
    fryer = Station(name="Fryer", temperature=175.0);
    cold_prep = Station(name="ColdPrep", temperature=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = HealthInspector();
    root spawn inspector;

    print(f"Visit log: {inspector.log}");
    print(f"Violations: {inspector.violations}");
}
