```jac
"""Performance budget enforcement: model initial dependency graphs per tier,
then have a walker traverse and audit the graph for budget violations and
untyped remote escapes that the historical check missed.
"""

# --- Entity archetypes ---

node Dependency {
    has label: str = "";
    has kind: str = "js";          # js | css | inline_js | inline_css | remote_js
    has bytes: int = 0;            # raw bytes
    has gzip_bytes: int = 0;       # transferred gzipped size
    has query_versioned: bool = False;
    has render_critical: bool = True;
    has interactive: bool = False; # whether primary content/controls are ready
    has tier_name: str = "";       # tier label, populated on attach
    has js_budget_kb: int = 75;
    has css_budget_kb: int = 35;
}

node Tier {
    has name: str = "";
    has js_budget_kb: int = 75;
    has css_budget_kb: int = 35;
}

# Typed edges: what relationship each dependency has to its tier / page
edge BelongsTo { has weight: float = 1.0; }
edge BlocksRender { has critical: bool = True; }

# --- Walker: BudgetAuditor ---

walker BudgetAuditor {
    has violations: list[str] = [];

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can audit_tier with Tier entry {
        print(f"\n=== Auditing tier: {here.name} ===");
        visit [->:BelongsTo:->];
    }

    # Union trigger: one routine handles every dependency variant.
    # All inspected fields are declared on Dependency.
    can inspect with Dependency entry {
        if here.kind == "remote_js" and here.render_critical {
            self.violations.append(f"render-critical remote JS: {here.label}");
        }
        if here.query_versioned and here.gzip_bytes > 20 * 1024 {
            self.violations.append(f"query-versioned oversized: {here.label}");
        }
        if here.interactive and here.gzip_bytes > 40 * 1024 {
            self.violations.append(f"hidden WebGL/init cost: {here.label}");
        }
        if here.kind == "js" and here.gzip_bytes > here.js_budget_kb * 1024 {
            self.violations.append(
                f"JS over tier budget [{here.tier_name}]: {here.label}"
            );
        }
        if here.kind == "css" and here.gzip_bytes > here.css_budget_kb * 1024 {
            self.violations.append(
                f"CSS over tier budget [{here.tier_name}]: {here.label}"
            );
        }
        visit [-->];
    }

    def summary -> str {
        if not self.violations {
            return "OK: all initial deps within budget";
        }
        return "FAIL:\n  - " + "\n  - ".join(self.violations);
    }
}

# --- Demo wiring ---

with entry {
    static_tier = Tier(name="static", js_budget_kb=75, css_budget_kb=35);
    enhanced_tier = Tier(name="enhanced", js_budget_kb=75, css_budget_kb=35);

    static_tier +>:BelongsTo(weight=1.0):+> Dependency(
        label="app.js", kind="js", gzip_bytes=68 * 1024,
        render_critical=True, interactive=False,
        tier_name="static"
    );
    static_tier +>:BelongsTo:+> Dependency(
        label="theme.css", kind="css", gzip_bytes=30 * 1024,
        render_critical=True,
        tier_name="static"
    );
    static_tier +>:BelongsTo:+> Dependency(
        label="hero-poster.webp", kind="inline_js", bytes=0,
        gzip_bytes=0, render_critical=False,
        tier_name="static"
    );

    enhanced_tier +>:BelongsTo:+> Dependency(
        label="webgl-scene.wasm", kind="js", gzip_bytes=120 * 1024,
        render_critical=True, interactive=False,
        tier_name="enhanced"
    );
    enhanced_tier +>:BelongsTo:+> Dependency(
        label="enhance.css", kind="css", gzip_bytes=28 * 1024,
        render_critical=True,
        tier_name="enhanced"
    );

    enhanced_tier +>:BelongsTo:+> Dependency(
        label="analytics?v=4", kind="js", gzip_bytes=25 * 1024,
        query_versioned=True, render_critical=True,
        tier_name="enhanced"
    );

    enhanced_tier +>:BelongsTo:+> Dependency(
        label="https://cdn.example.com/sdk.js",
        kind="remote_js", gzip_bytes=18 * 1024,
        render_critical=True,
        tier_name="enhanced"
    );

    root ++> static_tier ++> enhanced_tier;

    auditor = BudgetAuditor();
    root spawn auditor;

    print("\n--- BUDGET REPORT ---");
    print(auditor.summary());
}
