```jac
"""Provider-native session binding to governed runtime executions.

Models issue #1889: a provider-native session (Codex, Claude, ...) is bound to
one governed RuntimeExecution epoch via an opaque reference, with explicit
host-vs-guest enforcement coverage and lifecycle re-evaluation. A stale binding
must fail closed.
"""

node RuntimeExecution {
    has name: str = "";
    has snapshot: str = "";
    has lease: str = "";
    has evidence: str = "";
    has revoked: bool = False;

    def is_authority_valid() -> bool {
        return not self.revoked;
    }
}

node ProviderBinding {
    has provider: str = "";
    has adapter_version: str = "";
    has opaque_ref: str = "";
    has coverage: str = "host-only";
}

node ToolEgress {
    has surface: str = "";
    has degraded: bool = False;
}

edge BoundTo {
    has epoch: int = 0;
}

edge HostsEgress {
    has side: str = "";
}

walker BindingAuditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_execution with RuntimeExecution entry {
        if not here.is_authority_valid() {
            self.findings.append(f"[FAIL-CLOSED] {here.name}: stale or revoked authority");
            disengage;
        }
        self.findings.append(f"[OK] execution={here.name} lease={here.lease}");
        visit [->:BoundTo:->];
    }

    can audit_binding with ProviderBinding entry {
        status = "experimental" if here.coverage == "experimental" else "supported";
        self.findings.append(
            f"[{status}] provider={here.provider} v{here.adapter_version} ref={here.opaque_ref}"
        );
        visit [->:HostsEgress:->];
    }

    can audit_egress with ToolEgress entry {
        flag = "DEGRADED" if here.degraded else "OK";
        self.findings.append(f"[{flag}] egress surface={here.surface}");
        visit [-->];
    }
}

walker StaleInvalidator {
    has target_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can find with RuntimeExecution entry {
        if here.name == self.target_name {
            here.revoked = True;
            print(f"revoked execution {here.name}; any binding fails closed");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    exec_a = RuntimeExecution(
        name="exec-A",
        snapshot="snap-001",
        lease="lease-A",
        evidence="ev-A"
    );
    exec_b = RuntimeExecution(
        name="exec-B",
        snapshot="snap-002",
        lease="lease-B",
        evidence="ev-B",
        revoked=True
    );

    codex_bind = ProviderBinding(
        provider="codex",
        adapter_version="0.149.0",
        opaque_ref="thread/opaque-xyz",
        coverage="guest"
    );
    claude_bind = ProviderBinding(
        provider="claude",
        adapter_version="0.12.0",
        opaque_ref="session/opaque-abc",
        coverage="experimental"
    );

    host_tools = ToolEgress(surface="host-app-server");
    guest_shell = ToolEgress(surface="guest-shell", degraded=True);

    exec_a +>:BoundTo(epoch=1):+> codex_bind;
    exec_b +>:BoundTo(epoch=2):+> claude_bind;
    codex_bind +>:HostsEgress(side="guest"):+> guest_shell;
    claude_bind +>:HostsEgress(side="host"):+> host_tools;

    auditor = BindingAuditor();
    root spawn auditor;
    for line in auditor.findings {
        print(line);
    }

    print("--- stale-binding scenario ---");
    root spawn StaleInvalidator(target_name="exec-A");
    auditor2 = BindingAuditor();
    root spawn auditor2;
    for line in auditor2.findings {
        print(line);
    }
}
