```jac
"""Lua backend module graph: model .lua source files and their require
dependencies, then walk the dependency closure with a walker that mirrors
the hand-rolled traversal described in issue #21 of repo-view.

The original code maintains module identity through a string-keyed dict
and recurses through a list of dependency names. Here the relationships
become typed edges and the traversal is a walker over them. Cycle policy
is preserved explicitly (jac 0.36.1 walkers do not dedupe on cyclic
graphs), as is a depth cap and a max-children cap that bound recovery
when generated or malformed sources produce runaway includes.
"""

# ---- Node archetypes --------------------------------------------------------

node LuaSource {
    has path: str = "";
    has long_string_count: int = 0;
    has malformed: bool = False;

    def label() -> str;
}

node LuaModule(LuaSource) {
    has name: str = "";
    has kind: str = "script";
    has defines: list[str] = [];
    has exports: list[str] = [];
    has doc_blocks: int = 0;

    override def label() -> str {
        return f"module:{self.name}";
    }
}

node LuaFile(LuaSource) {
    has bytes: int = 0;

    override def label() -> str {
        return f"file:{self.path}";
    }
}

# ---- Edge archetypes --------------------------------------------------------

edge Requires {
    has dep_name: str = "";
    has literal: bool = True;
}

edge PartOf {
    has role: str = "discovered";
}

# ---- Walker: dependency closure --------------------------------------------

walker DepAudit {
    has max_depth: int = 32;
    has max_kids: int = 64;
    has seen: list[str] = [];
    has order: list[str] = [];
    has cycles: list[str] = [];
    has unresolved: list[str] = [];

    def _mark_seen(name: str) -> bool {
        for n in self.seen {
            if n == name {
                self.cycles.append(name);
                return False;
            }
        }
        self.seen.append(name);
        return True;
    }

    def _too_deep() -> bool {
        return len(self.seen) > self.max_depth;
    }

    def _report_module(m: LuaModule) -> None {
        if m.malformed {
            print(f"[WARN] malformed module: {m.name}");
        }
        status = "OK" if m.doc_blocks > 0 else "UNDOC";
        print(f"[{status}] {m.name} kind={m.kind} "
              f"defs={len(m.defines)} exports={len(m.exports)} "
              f"docs={m.doc_blocks} longstr={m.long_string_count}");
        for d in m.defines {
            print(f"   def: {d}");
        }
        for e in m.exports {
            print(f"   exp: {e}");
        }
    }

    can start with Root entry {
        visit [->:Requires:->];
    }

    can audit with LuaModule entry {
        if not self._mark_seen(here.name) {
            return;
        }
        if self._too_deep() {
            return;
        }
        self.order.append(here.name);
        self._report_module(here);
        kids = [->:Requires:->];
        kids_count = len(kids);
        if kids_count > self.max_kids {
            self.cycles.append(f"{here.name}:fanout>{self.max_kids}");
            return;
        }
        visit [->:Requires:->];
    }

    can file_pass with LuaFile entry {
        if here.malformed {
            self.cycles.append(f"file:{here.path}:malformed");
        }
        visit [-->];
    }
}

# ---- Walker: cascade invalidation of a removed module -----------------------

walker Invalidate {
    has removed: str = "";
    has purged: list[str] = [];

    can start with Root entry {
        visit [->:Requires:->];
    }

    can drop with LuaModule entry {
        if here.name == self.removed {
            self.purged.append(here.name);
            del here;
            disengage;
        }
        visit [->:Requires:->];
    }
}

# ---- Demo graph -------------------------------------------------------------

with entry {
    init   = LuaModule(name="init",   kind="script",
                       defines=["run", "main"],
                       exports=["run"],
                       doc_blocks=2,
                       long_string_count=1);
    config = LuaModule(name="config", kind="module",
                       defines=["load", "save"],
                       exports=["load", "save"],
                       doc_blocks=1);
    logger = LuaModule(name="logger", kind="module",
                       defines=["info", "warn", "error"],
                       exports=["info", "warn"],
                       doc_blocks=3,
                       long_string_count=4);
    util   = LuaModule(name="util",   kind="module",
                       defines=["map", "reduce", "filter"],
                       exports=["map", "filter"],
                       doc_blocks=0);
    bad    = LuaModule(name="bad",    kind="module",
                       defines=[],
                       exports=[],
                       doc_blocks=0,
                       malformed=True);

    f_init   = LuaFile(path="src/init.lua",   bytes=812,  long_string_count=1);
    f_config = LuaFile(path="src/config.lua", bytes=540,  long_string_count=0);
    f_logger = LuaFile(path="src/logger.lua", bytes=2030, long_string_count=4);

    init   +>:PartOf(role="discovered"):+> f_init;
    config +>:PartOf(role="discovered"):+> f_config;
    logger +>:PartOf(role="discovered"):+> f_logger;

    root +>:Requires(dep_name="init",   literal=True):+> init;
    init +>:Requires(dep_name="config", literal=True):+> config;
    config +>:Requires(dep_name="logger", literal=True):+> logger;
    config +>:Requires(dep_name="util",  literal=True):+> util;
    util  +>:Requires(dep_name="config", literal=True):+> config;
    logger +>:Requires(dep_name="bad",  literal=False):+> bad;

    auditor = DepAudit(max_depth=8, max_kids=8);
    root spawn auditor;
    print("--- audit summary ---");
    print(f"order   : {auditor.order}");
    print(f"cycles  : {auditor.cycles}");
    print(f"unres   : {auditor.unresolved}");

    print("--- invalidate 'config' ---");
    invalidator = Invalidate(removed="config");
    root spawn invalidator;
    print(f"purged  : {invalidator.purged}");
}
