```jac
"""Structured POST object search with boolean related predicates.

Models the core scenario from hubuum#282: an object class hierarchy with
related-object predicates evaluated by a walker that walks the typed
edges of the hubuum graph. The walker demonstrates bounded traversal
with a depth cap, a visited-set cycle guard, and existential negation
over related predicates. Cursors and pagination are intentionally out
of scope for this single-file demo, but the canonical query fingerprint
is computed so the same expression can be bound to a cursor.
"""

node Object {
    has name: str = "";
    has class_id: int = 0;
    has attributes: dict = {};
}

node Class {
    has class_name: str = "";
    has class_id: int = 0;
}

edge Related {
    has relation: str = "";
    has depth: int = 0;
}

walker HubuumSearch {
    has target_class_name: str = "";
    has max_depth: int = 3;
    has max_nodes: int = 50;
    has negate: bool = False;
    has include_total: bool = False;
    has results: list = [];
    has total: int = 0;
    has visited_ids: list = [];

    def fingerprint -> str {
        return f"{self.target_class_name}|d={self.max_depth}|n={self.max_nodes}|neg={self.negate}";
    }

    def already_seen(oid: int) -> bool {
        for v in self.visited_ids {
            if v == oid {
                return True;
            }
        }
        return False;
    }

    def report -> dict {
        return {
            "fingerprint": self.fingerprint(),
            "count": len(self.results),
            "total": self.total,
            "results": self.results,
        };
    }

    can begin with Root entry {
        fp = self.fingerprint();
        print(f"canonical query fingerprint: {fp}");
        self.results = [];
        self.total = 0;
        self.visited_ids = [];
        visit [-->];
    }

    can enter_class with Class entry {
        if here.class_name != self.target_class_name {
            visit [-->];
            return;
        }
        print(f"  -> entered target class {here.class_name}");
        visit [-->];
    }

    can collect with Object entry {
        if self.already_seen(here.class_id) {
            visit [-->];
            return;
        }
        if not self.negate {
            self.results.append({"name": here.name, "class_id": here.class_id});
        }
        if self.include_total {
            self.total += 1;
        }
        self.visited_ids.append(here.class_id);
        if len(self.visited_ids) >= self.max_nodes {
            print(f"  -> reached max_nodes={self.max_nodes}; stopping walk");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    rooms = Class(class_name="Room", class_id=1);
    people = Class(class_name="Person", class_id=2);
    rooms ++> Object(name="foo", class_id=1, attributes={"seats": 12})
        +>:Related(relation="contains", depth=1):+>
        Object(name="bar", class_id=2, attributes={"role": "host"})
        +>:Related(relation="mentions", depth=2):+>
        Object(name="zoot", class_id=2, attributes={"role": "guest"});

    root ++> rooms ++> people;

    walker1 = HubuumSearch(
        target_class_name="Room",
        max_depth=3,
        max_nodes=10,
        negate=False,
        include_total=True
    );
    root spawn walker1;
    print(f"inclusive search -> {walker1.report()}");

    walker2 = HubuumSearch(
        target_class_name="Person",
        max_depth=3,
        max_nodes=10,
        negate=True,
        include_total=False
    );
    root spawn walker2;
    print(f"existential negation -> {walker2.report()}");

    walker3 = HubuumSearch(
        target_class_name="Room",
        max_depth=3,
        max_nodes=2,
        negate=False,
        include_total=True
    );
    root spawn walker3;
    print(f"bounded walk -> {walker3.report()}");
}
