    root +>:Dependency:+> first;

    assert len([root ->:Dependency:->]) == 1, "root edge count is wrong";
    assert second in [first ->:Dependency:->], "dependency edge is missing";

    res = root spawn KahnSorter();

    assert len(res.order) == 2, f"order={res.order}";
    assert res.order[0] == 10, f"first task={res.order[0]}";
