"""Journal share-link toggle: arm and revoke a READ grant on a note."""

node Note {
    has title: str = "";
    has owner: str = "";
    has shared: bool = False;
}

walker ArmShare {
    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        if not here.shared {
            here.shared = True;
            print(f"[ARMED]  '{here.title}' (owner={here.owner}) is now shared for reading");
        } else {
            print(f"[ARMED]  '{here.title}' already shared -- no change");
        }
        visit [-->];
    }
}

walker RevokeShare {
    can start with Root entry {
        visit [-->];
    }

    can revoke with Note entry {
        if here.shared {
            here.shared = False;
            print(f"[REVOKED] '{here.title}' (owner={here.owner}) returned to owner-only");
        } else {
            print(f"[REVOKED] '{here.title}' already owner-only -- no change");
        }
        visit [-->];
    }
}

with entry {
    root ++> Note(title="Morning Pages", owner="ada")
        ++> Note(title="Build Log", owner="ada", shared=True)
        ++> Note(title="Grocery List", owner="ada");

    print("--- arming ---");
    root spawn ArmShare();
    print("--- revoking ---");
    root spawn RevokeShare();
}
