"""Test annex for the dungeon crawler: Hunter must stop at the treasure."""

import io;
import from contextlib { redirect_stdout }

# Test 1: Hunter stops immediately at the treasure room and never visits
# rooms past it (Forbidden Crypt / Dragon's Lair must not appear in output).
test "hunter stops at treasure and skips rooms past it" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Lair");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # Rooms before and including the vault must be inspected.
    assert "Inspecting room #1: Entrance" in out, f"missing Entrance: {out}";
    assert "Inspecting room #2: Antechamber" in out, f"missing Antechamber: {out}";
    assert "Inspecting room #3: Hall of Echoes" in out, f"missing Hall of Echoes: {out}";
    assert "Inspecting room #4: Vault" in out, f"missing Vault: {out}";

    # Rooms AFTER the treasure must NEVER be visited.
    assert "Forbidden Crypt" not in out, f"visited past vault (Forbidden Crypt): {out}";
    assert "Dragon's Lair" not in out, f"visited past vault (Dragon's Lair): {out}";

    # Treasure-found banner must be printed.
    assert "Treasure found" in out, f"no treasure banner: {out}";
    assert "Search ends after 4 rooms" in out, f"wrong room count in banner: {out}";

    # rooms_seen must equal exactly the number of rooms visited (4).
    assert res.rooms_seen == 4, f"got rooms_seen={res.rooms_seen}";
}

# Test 2: When the treasure is the very first room, Hunter disengages
# after inspecting only that one room and never walks the chain.
test "hunter disengages immediately when treasure is first room" {
    root ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Inspecting room #1: Vault" in out, f"missing Vault inspect: {out}";
    assert "Treasure found" in out, f"missing treasure banner: {out}";
    assert "Antechamber" not in out, f"visited past vault: {out}";
    assert "Hall of Echoes" not in out, f"visited past vault: {out}";
    assert res.rooms_seen == 1, f"got rooms_seen={res.rooms_seen}";
}

# Test 3: When the treasure is the LAST room in the chain, every prior
# room is inspected and the search still terminates cleanly after it.
test "hunter walks entire chain when treasure is last room" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Vault", is_treasure=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Inspecting room #1: Entrance" in out, f"missing Entrance: {out}";
    assert "Inspecting room #2: Antechamber" in out, f"missing Antechamber: {out}";
    assert "Inspecting room #3: Vault" in out, f"missing Vault: {out}";
    assert "Treasure found in 'Vault'! Search ends after 3 rooms." in out, f"bad banner: {out}";
    assert res.rooms_seen == 3, f"got rooms_seen={res.rooms_seen}";
}

# Test 4: Chain shape itself — the program builds a 6-room chain off root.
test "root has a six room chain ending at the vault" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Lair");

    chain = [root -->];
    assert len(chain) == 1, f"root should have one first child, got {len(chain)}";

    # Walk the chain and collect names in order.
    names = [];
    cur = chain[0];
    while cur is not None {
        names.append(cur.name);
        nxt = [cur -->];
        cur = nxt[0] if len(nxt) > 0 else None;
    }

    assert names == ["Entrance", "Antechamber", "Hall of Echoes", "Vault", "Forbidden Crypt", "Dragon's Lair"], f"unexpected chain order: {names}";

    # The vault must be flagged as treasure and it must NOT be the tail.
    vault = None;
    for n in [root -->] {
        cur = n;
        while cur is not None {
            if cur.name == "Vault" { vault = cur; break; }
            nxt = [cur -->];
            cur = nxt[0] if len(nxt) > 0 else None;
        }
    }
    assert vault is not None, "Vault not found in chain";
    assert vault.is_treasure is True, "Vault.is_treasure must be True";
    assert len([vault -->]) > 0, "Vault must not be the last room (would defeat the bug class)";
}

# Test 5: Fail-closed semantics — a chain with NO treasure must still
# terminate (visit [...] else { disengage }) and report every room.
test "hunter walks full chain when no treasure exists" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Inspecting room #1: Entrance" in out, f"missing Entrance: {out}";
    assert "Inspecting room #2: Antechamber" in out, f"missing Antechamber: {out}";
    assert "Inspecting room #3: Hall of Echoes" in out, f"missing Hall of Echoes: {out}";
    assert "Treasure found" not in out, f"should not print treasure banner: {out}";
    assert res.rooms_seen == 3, f"got rooms_seen={res.rooms_seen}";
}

