    # waiting for owner authorization. External knowledge (world rules) is
    # linked by provenance to the canonical rule it was promoted from.
    open_1nt = CanonRule(
        title="Open 1NT after 1m",
        body="Rebid 1NT (15-17) over partner's 1m response with balanced min.",
        approved=True,
        version=1,
        source_ref="BEN/BBA reconstructed"
    );

    jacoby_2nt = CanonRule(
