    );

    stayman = CanonRule(
        title="Stayman",
        body="2C over 1NT asks for a 4-card major.",
        approved=False,
        version=0,
        source_ref="World textbook"
    );

    ben_world = WorldRule(
        title="ben: open 1NT 15-17",
        body="Sampler recommends balanced min over 1m response.",
        origin="BEN",
        provenance_class="learned"
    );

    pons_world = WorldRule(
        title="pons: jacoby 2NT",
        body="Constraint DSL fires jacoby 2NT over 1H-2H.",
        origin="Pons",
        provenance_class="heuristic"
    );

    bridgit_world = WorldRule(
        title="bridgit: stayman",
        body="Convention card lists 2C as stayman over 1NT.",
        origin="Bridgit",
