```jac
"""Share-link access control for journal notes.

A walker arms a READ grant on a note and another walker revokes it,
returning the note to owner-only. A ``share_enabled`` flag on the note
itself reflects the transition in the output.
"""

node Note {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has share_enabled: bool = False;
}

walker GrantShare {
    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        here.share_enabled = True;
        label = "OPEN" if here.share_enabled else "CLOSED";
        print(f"[{label}] {here.title} ({here.year}) share granted");
        visit [-->];
    }
}

walker RevokeShare {
    can start with Root entry {
        visit [-->];
    }

    can disarm with Note entry {
        here.share_enabled = False;
        label = "OPEN" if here.share_enabled else "CLOSED";
        print(f"[{label}] {here.title} ({here.year}) share revoked");
        visit [-->];
    }
}

walker Inspector {
    has found_open: bool = False;
    has found_closed: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can examine with Note entry {
        if here.share_enabled {
            self.found_open = True;
        } else {
            self.found_closed += 1;
        }
        visit [-->];
    }
}

with entry {
    draft = Note(title="Field Notes", year=2024);
    private = Note(title="Private Memo", year=2023);
    root ++> draft ++> private;

    root spawn GrantShare();
    root spawn RevokeShare();
    audit = Inspector();
    root spawn audit;
    print(f"final: open_share={audit.found_open}, owner_only_count={audit.found_closed}");
}
