"""Tests for the vending machine FSM controller."""

import io;
import from contextlib { redirect_stdout }

# Build a fresh FSM graph and return the starting idle node plus the table.
def build_fsm() {
    idle = State(name="idle");
    waiting = State(name="waiting");
    vend = State(name="vend");
    idle +>: InsertCoin() :+> waiting;
    waiting +>: InsertCoin() :+> waiting;
    waiting +>: PressButton() :+> vend;
    vend +>: Reset() :+> idle;
    table = {
        "coin": InsertCoin,
        "button": PressButton,
        "reset": Reset,
    };
    return [idle, waiting, vend, table];
}

test "trail records state names in order" {
    [idle, waiting, vend, table] = build_fsm();
    runner = MachineRunner(
        machine_name="m1",
        inputs=["coin", "coin", "button"],
    );
    runner.transition_table = table;
    idle spawn runner;

    # Trail must contain every visited state, in order, including the
    # starting idle and the final vend state.
    assert runner.trail == ["idle", "waiting", "waiting", "vend"], (
        f"trail mismatch, got {runner.trail}"
    );
    assert runner.step_idx == 3, (
        f"step_idx should be 3 after consuming all inputs, got {runner.step_idx}"
    );
}

test "trail ends at vend after coin then button" {
    [idle, waiting, vend, table] = build_fsm();
    runner = MachineRunner(
        machine_name="m2",
        inputs=["coin", "button"],
    );
    runner.transition_table = table;
    idle spawn runner;

    assert runner.trail[-1] == "vend", (
        f"final state should be 'vend', got {runner.trail[-1]!r}"
    );
    assert runner.trail == ["idle", "waiting", "vend"], (
        f"expected idle -> waiting -> vend, got {runner.trail}"
    );
}

test "full cycle returns to idle via reset" {
    [idle, waiting, vend, table] = build_fsm();
    runner = MachineRunner(
        machine_name="m3",
        inputs=["coin", "button", "reset"],
    );
    runner.transition_table = table;
    idle spawn runner;

    # Reset is only valid from vend; it must return us to idle.
    assert runner.trail[-1] == "idle", (
        f"final state should be 'idle' after reset, got {runner.trail[-1]!r}"
    );
    assert runner.trail == ["idle", "waiting", "vend", "idle"], (
        f"expected full cycle trail, got {runner.trail}"
    );
}

test "runner prints the trail on disengage" {
    [idle, waiting, vend, table] = build_fsm();
    runner = MachineRunner(
        machine_name="printtest",
        inputs=["coin", "button"],
    );
    runner.transition_table = table;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        idle spawn runner;
    }
    out = buf.getvalue();

    # The print happens when the runner disengages (inputs exhausted).
    assert "printtest run:" in out, (
        f"missing machine_name prefix in output: {out!r}"
    );
    assert "idle -> waiting -> vend" in out, (
        f"trail not in printed output: {out!r}"
    );
}

test "graph shape reflects the transition table" {
    [idle, waiting, vend, table] = build_fsm();

    # idle: exactly one outgoing edge, InsertCoin, to waiting.
