"""Tetragon execve_map cascade failure model.

Models the chain described in cilium/tetragon issue #4883: a partial
procfs snapshot drops ancestors from execve_map, so the hereditary
``parent must already be in execve_map`` invariant permanently excludes
descendants. Downstream process_kprobe events then fall back to a
probe-only path that emits empty fields.

Four node archetypes model the entities, two typed edges capture the
relationships, and a walker performs the same parent-walk + cascade
invalidation the BPF code does.
"""

node ProcEntry {
    has pid: int = 0;
    has binary: str = "";
    has exec_id: str = "";
    has flags: str = "";
    has pod: str = "";
    has in_execve_map: bool = False;
    has probed: bool = False;
}

node Snapshot {
    has source: str = "";
    has filled: int = 0;
    has total: int = 0;
}

node KernelInvariant {
    has name: str = "";
    has description: str = "";
}

walker CascadeLoss {
    has dropped_count: int = 0;
    has neutralised: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can seed with Snapshot entry {
        print(f"[seed] {here.source}: {here.filled}/{here.total} filled");
        visit [-->];
    }

    can enforce with KernelInvariant entry {
        print(f"[invariant] {here.name} -> {here.description}");
        visit [-->];
    }

    can walk_and_emit with ProcEntry entry {
        if not here.probed {
            visit [-->];
            return;
        }
        if here.in_execve_map {
            label = "FULL";
        } else {
            label = "EMPTY";
        }
        line = f"[kprobe] pid={here.pid} {label} binary='{here.binary}' "
               f"exec_id='{here.exec_id}' flags='{here.flags}' pod='{here.pod}'";
        print(line);
        self.log.append(line);
        if label == "EMPTY" {
            self.neutralised += 1;
        }
        visit [-->];
    }
}

