"""QA gate parity model: slow semantic_dup check vs fast ambient check, walked by a GateAuditor.

Models the gate check machinery as nodes (Checks) connected to a Project by a typed
Gate edge. The GateAuditor walker traverses every check, recording elapsed ticks
analogous to wall-clock seconds; cycle policy mirrors the real gate: once a check
has been audited it is never re-entered (explicit guard set, since Jac 0.36.1
walkers have no built-in once-per-node visitation).
"""

node Check {
    has name: str = "";
    has timeout_s: float = 0.0;
    has elapsed_s: float = 0.0;
    has status: str = "pending";
}

node Project {
    has name: str = "";
    has mode: str = "";
}

edge Gate {
    has slow: bool = False;
}

walker GateAuditor {
    has audited: list[str] = [];
    has log: list[str] = [];
    has total_elapsed: float = 0.0;

    can start with Root entry {
        self.log.append("GateAuditor starting in mode=pre-pr");
        visit [-->];
    }

    can audit_project with Project entry {
        self.log.append(f"Project={here.name} mode={here.mode}");
        visit [-->];
    }

    can audit_check with Check entry {
        # Cycle / re-entry policy: explicit guard set (no built-in dedup in jac 0.36.1).
        if here.name in self.audited {
            return;
        }
        self.audited.append(here.name);

        # Simulate the slow-vs-fast interpreter disparity from the issue.
        # The parity venv case is ~9x slower (1m26s ambient -> 12m54s parity = ~9.0x).
        ambient_s = 86.0;
        if here.name == "semantic_dup" {
            here.elapsed_s = 12.0 * 60.0 + 54.0;
        } else {
            here.elapsed_s = ambient_s;
        }
        self.total_elapsed = self.total_elapsed + here.elapsed_s;

        # Reproduce the gate's hardcoded 600s subprocess timeout.
        if here.elapsed_s > here.timeout_s {
            here.status = "unknown/TimeoutExpired";
            self.log.append(
                f"[FAIL] {here.name}: {here.elapsed_s:.0f}s > timeout {here.timeout_s:.0f}s -> {here.status}"
            );
        } else {
            here.status = "pass";
            self.log.append(
                f"[OK]   {here.name}: {here.elapsed_s:.0f}s within {here.timeout_s:.0f}s"
            );
        }

        visit [-->];
    }
}

