        print(f"OrderAuditor beginning sweep");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALTED";
            self.halted = True;
        } elif not here.valid {
            action = "SKIPPED";
        } else {
            action = "OK";
            self.audited += 1;
        }
        print(f"[{action}] {here.title} amount={here.amount} valid={here.valid} fraud={here.fraud}");
        if here.fraud {
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

