"""Epic execution order and dependency walker for WorkflowTools project planning.

Models the epics described in issue #10 as nodes, their dependencies as typed
edges, and walks the dependency chain in execution order while guarding against
cycles (a real risk when epics cross-reference each other).
"""

node Epic {
    has title: str = "";
    has phase: int = 0;
    has issue_id: int = 0;
    has completed: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

walker EpicPlanner {
    has visited: list[Epic] = [];
    has order: list[Epic] = [];

    can start with Root entry {
        visit [-->];
    }

    can plan with Epic entry {
        # Cycle guard: a walker in jac 0.36.1 has no built-in once-per-node
        # visitation, so we keep an explicit visited list and disengage
        # from cyclic walks.
        already_seen = False;
        for prior in self.visited {
            if prior == here {
                already_seen = True;
                break;
            }
        }
        if already_seen {
            disengage;
        }
        self.visited.append(here);

        status = "DONE" if here.completed else "PENDING";
        print(f"Phase {here.phase}: [{status}] Epic #{here.issue_id} - {here.title}");
        self.order.append(here);

        # Recurse into dependencies. Dependents must finish first.
        visit [here->:DependsOn:->];
    }
}

walker CycleProbe {
    has markers: list[Epic] = [];

    can start with Root entry {
        visit [-->];
    }

    can probe with Epic entry {
        is_cycle = False;
        for prior in self.markers {
            if prior == here {
                is_cycle = True;
                break;
            }
        }
        label = "CYCLE-DETECTED" if is_cycle else "ok";
        print(f"{here.title}: {label}");
        self.markers.append(here);
        visit [here->:DependsOn:->];
    }
}

with entry {
    anchor = Epic(title="Anchor Project Template", phase=0, issue_id=18, completed=True);
    shared_lib = Epic(title="Create Shared Library", phase=0, issue_id=19, completed=True);
    test_inf = Epic(title="Test Infrastructure & Safety", phase=1, issue_id=2, completed=False);
    logging = Epic(title="Logging & Analytics Foundation", phase=1, issue_id=6, completed=False);
    local_val = Epic(title="Local-First Validation Infrastructure", phase=2, issue_id=7, completed=False);
    policies = Epic(title="Configurable Workflow Policies", phase=2, issue_id=8, completed=False);
    tdd = Epic(title="TDD Enforcement System", phase=3, issue_id=3, completed=False);
    bdd = Epic(title="BDD-Driven Feature Development", phase=3, issue_id=17, completed=False);
    ai_review = Epic(title="AI Agent Self-Review System", phase=4, issue_id=9, completed=False);

    root ++> anchor
        ++> shared_lib
        ++> test_inf
        ++> logging
        ++> local_val
        ++> policies
        ++> tdd
        ++> bdd
        ++> ai_review;

    # Dependency chain: anchor -> shared_lib -> test_inf -> logging
    # -> local_val -> tdd, bdd -> ai_review.
    anchor +>:DependsOn(reason="structural template"):+> shared_lib;
    shared_lib +>:DependsOn(reason="common components"):+> test_inf;
    test_inf +>:DependsOn(reason="debugging needs logs"):+> logging;
    logging +>:DependsOn(reason="needs local infra"):+> local_val;
    local_val +>:DependsOn(reason="policy depends on local"):+> policies;
    logging +>:DependsOn(reason="TDD after logging"):+> tdd;
    tdd +>:DependsOn(reason="BDD complements TDD"):+> bdd;
    bdd +>:DependsOn(reason="AI review after BDD"):+> ai_review;

    planner = EpicPlanner();
    root spawn planner;

    print("");
    print(f"Execution order produced: {len(planner.order)} epics");
    print(f"Visited guard set size: {len(planner.visited)}");

    print("");
    print("--- Cycle probe (independent walk) ---");
    prober = CycleProbe();
    root spawn prober;
}
