"""Depot dispatch checker.

Each delivery route from a depot carries a cargo weight in tonnes. A
truck may only be dispatched when its load is at least 2 tonnes and at
most 8 tonnes on the same leg. A walker visits every depot and reports
which routes qualify for dispatch.
"""

node Route {
    has name: str = "";
    has weight: float = 0.0;
}

edge Delivers {
    has leg_label: str = "";
}

node Depot {
    has depot_name: str = "";

    def qualifies(r: Route) -> bool {
        return r.weight >= 2.0 and r.weight <= 8.0;
    }
}

walker DispatchAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Depot entry {
        print(f"Depot: {here.depot_name}");
        outgoing = [here->:Delivers:->];
        for r in outgoing {
            if here.qualifies(r) {
                print(f"  DISPATCH OK -> {r.name} ({r.weight}t)");
            } else {
                print(f"  SKIP       -> {r.name} ({r.weight}t)");
            }
        }
        visit [-->];
    }
}

with entry {
    north = Depot(depot_name="North");
    south = Depot(depot_name="South");

    root +>:Delivers(leg_label="L1"):+> north;
    root +>:Delivers(leg_label="L2"):+> south;

    north +>:Delivers(leg_label="N-A"):+> Route(name="North-Central", weight=5.5);
    north +>:Delivers(leg_label="N-B"):+> Route(name="North-Coast", weight=1.0);
    north +>:Delivers(leg_label="N-C"):+> Route(name="North-Mountain", weight=8.0);

    south +>:Delivers(leg_label="S-A"):+> Route(name="South-Port", weight=9.5);
    south +>:Delivers(leg_label="S-B"):+> Route(name="South-Inland", weight=2.0);
    south +>:Delivers(leg_label="S-C"):+> Route(name="South-Border", weight=7.25);

    root spawn DispatchAuditor();
}
