    root spawn sweep;

    temps = [r[1] for r in sweep.readings];
    min_t = min(temps);
    max_t = max(temps);

    print("");
    print("All readings:");
    for (loc, t) in sweep.readings {
        print(f"  {loc}: {t} C");
    }
    print(f"Min: {min_t} C");
