"""Agents Live span correlation: nested run phases, outcome vs observation, export sensitivity."""

node Run {
    has run_id: str = "";
    has title: str = "";
}

node Span {
    has span_id: str = "";
    has phase: str = "";
    has status: str = "";
    has duration_ms: int = 0;
    has sensitivity: str = "operational";
    has paired: bool = True;

    def is_health_signal() -> bool {
        return False;
    }

    def is_exportable() -> bool {
        return self.sensitivity == "operational";
    }
}

node RunOutcome(Span) {
    override def is_health_signal() -> bool {
        return self.phase == "done" and self.status == "error";
    }
}

node Observation(Span) {
    override def is_health_signal() -> bool {
        return False;
    }
}

edge InRun { }
edge ChildSpan { has ordinal: int = 0; }

walker TimelineRenderer {
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can show_run with Run entry {
        print(f"=== Run {here.run_id}: {here.title} ===");
        visit [->:InRun:->];
    }

    can show_span with Span entry {
        pad = "  " * self.depth;
        dur_label = f"{here.duration_ms}ms" if here.duration_ms > 0 else "open";
        pair_tag = "paired" if here.paired else "UNPAIRED";
        print(f"{pad}|-- {here.phase} [{here.status}] {dur_label} ({pair_tag}, {here.span_id})");
        self.depth += 1;
        visit [->:ChildSpan:->] else { }
        self.depth -= 1;
    }
}

walker ExportProjector {
    has exported: int = 0;
    has suppressed: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan_run with Run entry {
        print(f"Export scan for run {here.run_id}:");
        visit [->:InRun:->];
    }

    can project with Span entry {
        if here.is_exportable() {
            print(f"  ALLOW  id={here.span_id} phase={here.phase} status={here.status} dur={here.duration_ms}");
            self.exported += 1;
        } else {
            print(f"  DENY   id={here.span_id} phase={here.phase} (sensitivity={here.sensitivity})");
            self.suppressed += 1;
        }
        visit [->:ChildSpan:->] else { }
    }
}

walker HealthStreak {
    has consecutive_failures: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan_run with Run entry {
        visit [->:InRun:->];
    }

    can tally with RunOutcome | Observation entry {
        if here.is_health_signal() {
            self.consecutive_failures += 1;
        }
        visit [->:ChildSpan:->] else { }
    }
}

walker SpanValidator {
    has seen_ids: list[str] = [];
    has issues: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_run with Run entry {
        self.seen_ids = [];
        visit [->:InRun:->];
    }

    can audit_span with Span entry {
        if here.span_id in self.seen_ids {
            self.issues.append(f"cycle or duplicate span_id={here.span_id}");
            disengage;
        }
        self.seen_ids.append(here.span_id);
        if not here.paired {
            self.issues.append(f"missing start/end pair for span_id={here.span_id} phase={here.phase}");
        }
        visit [->:ChildSpan:->] else { }
    }
}

with entry {
    run = Run(run_id="run-7f3a", title="watcher debounce retry tree");
    root ++> run;

    trigger = Span(span_id="s1", phase="trigger", status="ok", duration_ms=12, paired=True);
    run +>:InRun:+> trigger;

    debounce = Span(span_id="s2", phase="debounce", status="ok", duration_ms=450, paired=True);
    trigger +>:ChildSpan(ordinal=1):+> debounce;

    quiet = Span(span_id="s3", phase="quiet_window", status="ok", duration_ms=200, paired=True);
    debounce +>:ChildSpan(ordinal=1):+> quiet;

    dispatch = Span(span_id="s4", phase="dispatch", status="ok", duration_ms=5, paired=True);
    debounce +>:ChildSpan(ordinal=2):+> dispatch;

    attempt1 = Span(
        span_id="s5",
