    # Total quantity across reported shelves is the sum of all stock.
    total = sum([r.quantity for r in res.reports]);
    assert total == 14, f"expected total 14, got {total}";

    # Smallest shelf count is min of reported quantities.
    smallest = min([r.quantity for r in res.reports]);
