"""Data center clearance walk: technicians are admitted or denied per server room,
and any denial ends their walkthrough immediately. Report rooms reached per technician."""

node Room {
    has name: str = "";
    has required_level: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_visited: int = 0;
    has denied: bool = False;

    can start with Root entry {
        print(f"Technician {self.name} (clearance {self.clearance}) entering corridor");
        visit [-->] else { disengage; }
    }

    can try_room with Room entry {
        if self.denied {
            disengage;
            visit [-->];
        }
        granted = self.clearance >= here.required_level;
        status = "GRANTED" if granted else "DENIED";
        print(f"[{status}] {self.name} at {here.name} (needs {here.required_level})");
        if granted {
            self.rooms_visited += 1;
            visit [-->] else { disengage; }
        } else {
            self.denied = True;
            disengage;
            visit [-->];
        }
    }
}

with entry {
    # Build the corridor: deeper rooms require higher clearance.
    root ++> Room(name="Lobby", required_level=0)
        ++> Room(name="Storage", required_level=1)
        ++> Room(name="App Servers", required_level=2)
        ++> Room(name="Database Tier", required_level=3)
        ++> Room(name="Crypto Vault", required_level=5);

    # Junior tech: gets bounced at the database tier.
    junior = Technician(name="Alex", clearance=2);
    root spawn junior;

    # Senior tech: clears every room.
    senior = Technician(name="Morgan", clearance=5);
    root spawn senior;

    # Intern: denied right at storage.
    intern = Technician(name="Sam", clearance=0);
    root spawn intern;

    # Audit: how many rooms did each technician actually reach?
    print("--- Audit ---");
    print(f"{junior.name} reached {junior.rooms_visited} rooms "
          f"(denied={junior.denied})");
    print(f"{senior.name} reached {senior.rooms_visited} rooms "
          f"(denied={senior.denied})");
    print(f"{intern.name} reached {intern.rooms_visited} rooms "
          f"(denied={intern.denied})");
}
