    s1 +>:AssessedBy:+> a2;
    s2 +>:AssessedBy:+> a3;

    res = root spawn Invalidator();

    assert res.invalidated_count == 3, f"invalidated {res.invalidated_count}";
    assert a1.cached == False, f"a1.cached = {a1.cached}";
    assert a2.cached == False, f"a2.cached = {a2.cached}";
    assert a3.cached == False, f"a3.cached = {a3.cached}";
