test "re-analysis bypasses the assessment cache" {
    s1 = Subject(label="alpha");
    root ++> s1;

    old = Assessment(score=0.42, cached=True);
    s1 +>:AssessedBy:+> old;

    assert old.cached == True, f"old.cached = {old.cached}";
    res = root spawn ReAnalyze(subject_label="alpha", fresh_score=0.99);

    assessments = [s1 ->:AssessedBy:->];
    fresh = assessments[1];
    assert old.cached == False, f"old.cached after re-analysis = {old.cached}";
    assert len(assessments) == 2, f"assessment count = {len(assessments)}";
    assert fresh.score == 0.99, f"fresh.score = {fresh.score}";
    assert fresh.cached == False, f"fresh.cached = {fresh.cached}";
}

