"""Tiny dungeon crawler: chained room nodes, one vault, a hunter walker.

The hunter walks the chain of rooms one by one, counting how many it has
visited. The instant it steps into the vault (the treasure room), the
hunter disengages: rooms past the vault are never reached.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_visited: int = 0;
    has found_treasure: bool = False;
    has treasure_room: str = "";

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_visited += 1;
        if here.is_vault {
            self.found_treasure = True;
            self.treasure_room = here.name;
            print(f"Found the treasure in '{here.name}'! Hunter halts immediately.");
            disengage;
        }
        print(f"Searched '{here.name}'... empty.");
        visit [-->] else { disengage; }
    }
}

with entry {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", is_vault=True);
    forbidden = Room(name="Forbidden Alcove");

    root ++> entrance
        ++> hallway
        ++> armory
        ++> vault
        ++> forbidden;

    root spawn Hunter();
}
