"""Combined depot sweep: anchor a single query at the depot list, walk every store once, and flag any whose stock has fallen below 20."""

node Store {
    has title: str = "";
    has stock: int = 0;

    def is_low() -> bool {
        return self.stock < 20;
    }
}

node Depot {
    has title: str = "";
}

node Serves {
    has since: str = "";
}

walker DepotAuditor {
    has low_count: int = 0;
    has visited: list[Store] = [];

    can start with Root entry {
        # Anchor one query on every depot reachable from root.
        visit [-->];
    }

    can at_depot with Depot entry {
        # From each depot, walk every store it serves.
        visit [-->];
    }

    can inspect with Store entry {
        # Cycle policy: a store might be reachable from two depots;
        # record each visit only once so we never double-flag it.
        if here not in self.visited {
            self.visited.append(here);
            if here.is_low() {
                self.low_count += 1;
                print(f"[LOW] {here.title} (stock={here.stock})");
            } else {
                print(f"[ok ] {here.title} (stock={here.stock})");
            }
        }
    }
}

with entry {
    d_north = Depot(title="North");
    d_south = Depot(title="South");

    # One combined query anchor: root leads to the depot list, depots lead to stores.
    root ++> d_north ++> d_south;
    d_north ++> Store(title="Corner Market", stock=45);
    d_north ++> Store(title="Riverside Shop", stock=12);
    d_south ++> Store(title="Hilltop Grocer", stock=8);
    d_south ++> Store(title="Bayside Mart", stock=33);
    # A store shared by both depots to demonstrate the dedup policy.
    d_north ++> Store(title="Junction Store", stock=15);
    d_south ++> Store(title="Junction Store", stock=15);

    auditor = DepotAuditor();
    root spawn auditor;

    print(f"\nStores below 20 units: {auditor.low_count}");
}
