```jac
"""GEDCOM-style typed record graph: lazy pointer resolution + safety net for unknown substructures.

Models the essential shape of the magicsunday/gedcom-parser full-typed-model goal:
- Records (individual, source) as node archetypes with typed `has` fields.
- Pointer references between records as typed edges carrying the xref payload.
- Substructure containers as edges with optional payload, plus a safety-net
  `RawSubstructure` edge to preserve unmodeled tags (the issue's
  "$unknown" requirement) so nothing is silently lost.
- A walker that traverses the record graph following pointer edges, walking
  the same chain the issue describes
  (`$document->individuals[i]->bapm[0]->plac->sour[0]->source($document)->…`)
  and accumulates visited records into a single typed `report`, with an
  explicit cycle guard (jac 0.36.1 walkers have no built-in dedup).
"""

# --- Value objects: hand-written leaf payloads (DATE / PLAC / AGE analog) ---
node DateValue { has raw: str = ""; }
node PlaceValue { has raw: str = ""; }
node AgeValue { has years: int = 0; }

# --- Record archetypes: full-typed model classes (generated in the real repo) ---
node Individual {
    has name: str = "";
    has sex: str = "";
    has bapm_place: str = "";
    has bapm_date: str = "";
}

node SourceRecord {
    has title: str = "";
    has author: str = "";
}

# --- Pointer payload: lazy resolution keeps the xref, never cycles ---
edge Pointer {
    has xref: str = "";
}

# --- Substructure container edges (one per GEDCOM substructure) ---
edge BapmEvent { }            # baptism event substructure
edge Citation { has page: str = ""; }   # sour citation under plac
edge RawSubstructure {       # safety net: any tag the typed model does not consume
    has tag: str = "";
    has payload: str = "";
}

# --- Base record node so the union-trigger walker can touch a shared field ---
node Record {
    has xref: str = "";
    def label() -> str {
        return self.xref;
    }
}

# Make the two concrete records inherit the shared base (override label).
node IndividualRecord(Record) {
    has given: str = "";
    has surname: str = "";
    override def label() -> str {
        return f"Indi({self.xref} {self.given} {self.surname})";
    }
}
node SourceRecordNode(Record) {
    has title: str = "";
    override def label() -> str {
        return f"Sour({self.xref} {self.title})";
    }
}

# --- Walker: resolves pointer chain from an individual through place/source ---
walker PointerResolver {
    has visited: list[str] = [];
    has report: list[str] = [];

    can start with Root entry {
        # Begin traversal into the document graph
        visit [-->];
    }

    # Union ability: same routine walks both record kinds via the shared base
    can resolve with IndividualRecord | SourceRecordNode entry {
        if here.xref in self.visited {
            # Cycle guard: explicit because jac 0.36.1 walkers do not dedup
            disengage;
        }
        self.visited.append(here.xref);
        self.report.append(here.label());
        # Follow outgoing pointer edges only
        visit [->:Pointer:->];
    }

    # Dead-end handler: a pointer target may not exist in a small demo
    can dead_end with Pointer entry {
        # Nothing to do; explicit disengage to be loud about the boundary
        disengage;
    }
}

with entry {
    # Build a tiny document: one individual, one place value, one source
    indi = IndividualRecord(xref="@I1@", given="Jane", surname="Doe");
    sour = SourceRecordNode(xref="@S1@", title="Birth Certificate");

    # Typed pointer edge from the individual record to the source record
    indi +>:Pointer(xref="@S1@"):+> sour;

    # Substructure chain: individual --BapmEvent--> place value --Citation--> source pointer
    plac = PlaceValue(raw="Springfield");
    indi +>:BapmEvent:+> plac;
    plac +>:Citation(page="p.12"):+> sour;

    # Safety-net edge: an extension tag the typed model doesn't consume
    indi +>:RawSubstructure(tag="_CUSTOM", payload="preserved"):+> plac;

    root ++> indi ++> sour;

    # Spawn the resolver walker on the document root
    resolver = PointerResolver();
    root spawn resolver;

    print("Resolved chain:");
    for entry_label in resolver.report {
        print(f"  - {entry_label}");
    }
    print(f"Visited xrefs: {resolver.visited}");
}
