    assert len(citation_edges) == 1, f"citation edges: {len(citation_edges)}";
    assert citation_edges[0].page == "p.12", f"citation page: {citation_edges[0].page}";
    assert len(raw_edges) == 1, f"raw edges: {len(raw_edges)}";
    assert raw_edges[0].tag == "_CUSTOM", f"raw tag: {raw_edges[0].tag}";
    assert raw_edges[0].payload == "preserved", f"raw payload: {raw_edges[0].payload}";
