import io;
import from contextlib { redirect_stdout }

test "renders dependency graph with live task status" {
    spec = Spec(title="Terraform module", phase="Tasks");
    scaffold = Task(title="scaffold", lane=0, status="done");
    core = Task(title="core", lane=1, status="running");
