    root ++> spec;
    spec +>:BelongsTo:+> scaffold;
    spec +>:BelongsTo:+> core;
    spec +>:BelongsTo:+> validate;
    scaffold +>:Blocks(reason="core needs scaffold"):+> core;
    core +>:Blocks(reason="validation needs code"):+> validate;

