    assert "[   done] lane 0: scaffold" in out, f"missing scaffold status: {out}";
    assert "[running] lane 1: core" in out, f"missing core status: {out}";
    assert "blocks -> core(running)" in out, f"missing dependency edge: {out}";
    assert "validate" in out, f"missing downstream task: {out}";
