"""Tests for the Hiking trail program: chain of Waypoints walked by a Hiker."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts all waypoints and disengages at summit" {
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(min_stops=4);
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing Stop #1: {out!r}";
    assert "Stop #2" in out, f"missing Stop #2: {out!r}";
    assert "Stop #3" in out, f"missing Stop #3: {out!r}";
    assert "Stop #4" in out, f"missing Stop #4: {out!r}";
    assert "Summit reached — trail complete!" in out, f"missing completion line: {out!r}";

    # The completion message must come after the final stop print.
    last_stop_idx = out.rfind("Stop #4");
    completion_idx = out.rfind("Summit reached");
    assert completion_idx > last_stop_idx, (
        f"completion should follow final stop; out={out!r}"
    );

    # Exactly four stops printed, then completion — nothing past the summit.
    stops_printed = out.count("Stop #");
    assert stops_printed == 4, f"expected 4 stops printed, got {stops_printed}: {out!r}";
}

test "hiker disengages early when min_stops is reached before the end" {
    # min_stops=2 means the hiker should stop after printing Stop #2.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(min_stops=2);
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing Stop #1: {out!r}";
    assert "Stop #2" in out, f"missing Stop #2: {out!r}";
    assert "Stop #3" not in out, f"should not have reached Stop #3: {out!r}";
    assert "Stop #4" not in out, f"should not have reached Stop #4: {out!r}";
    assert "Summit reached — trail complete!" in out, f"missing completion: {out!r}";

    # Disengagement check: the stop that meets the threshold prints first,
    # then the completion message immediately after (no further waypoints).
    assert out.strip().endswith("Summit reached — trail complete!"), (
        f"trail should end with completion line; out={out!r}"
    );
}

