"""Maze level modeling the difficulty-spike scenario from the arcade issue.

Entities are modeled as nodes (Level, Maze, Cell, Goal) connected by typed
edges that carry the relationships the issue talks about: maze generation,
shortest-path discovery via a walker traversal, and the time-vs-budget
mismatch that becomes pathological at level 6+. A walker performs the
BFS-style reachability walk the maintainer hand-rolled in their analysis.
"""

node Level {
    has number: int = 0;
    has size: int = 0;
    has time_budget: float = 0.0;
    has vision_radius: float = 0.0;

    def shortest_path_estimate() -> float {
        # Approximate shortest-path length for a fully-grown blind maze:
        # grows with size until the cap at level 6, then plateaus.
        cap = 19;
        cells = self.size * self.size;
        return 0.30 * cells + 12.0 if self.size >= cap else 0.55 * cells;
    }

    def pressure() -> str {
        # The maintainer's complaint: at level 6+ the path grows while the
        # budget keeps shrinking. Encode the regime as a label.
        est = self.shortest_path_estimate();
        ratio = est / self.time_budget;
        if ratio > 2.0 {
            return "BRUTAL";
        }
        if ratio > 1.3 {
            return "TIGHT";
        }
        return "FAIR";
    }
}

node Maze {
    has label: str = "";
}

node Cell {
    has row: int = 0;
    has col: int = 0;
    has passable: bool = True;
}

node Goal {
    has label: str = "";
}

edge Generates {
    has seed: int = 0;
}

edge Links {
    has weight: int = 1;
}

edge LeadsTo {
}

walker Pathfinder {
    has visited_count: int = 0;
    has path_length: int = 0;
    has reached_goal: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can pick_level with Level entry {
        print(f"Level {here.number}: {here.size}x{here.size}, "
              f"budget={here.time_budget}s, "
              f"vision={here.vision_radius}, "
              f"est_path={here.shortest_path_estimate():.1f} "
              f"-> {here.pressure()}");
        visit [-->];
    }

    can enter_maze with Maze entry {
        print(f"  exploring maze '{here.label}'");
        visit [->:Generates:->];
    }

    can walk_cells with Cell entry {
        self.visited_count += 1;
        # Continue BFS-style along passable links; guards against cycles.
        if self.visited_count > 200 {
            print("  [guard] bailing: traversal exceeded safety cap");
            disengage;
        }
        visit [->:Links:->];
    }

    can finish with Goal entry {
        self.path_length = self.visited_count;
        self.reached_goal = True;
        print(f"  reached goal '{here.label}' after {self.path_length} cells");
        disengage;
    }
}

with entry {
    # Build three levels that mirror the maintainer's table.
    lvl1 = Level(number=1, size=9, time_budget=42.0, vision_radius=2.60);
    lvl6 = Level(number=6, size=19, time_budget=29.5, vision_radius=2.25);
    lvl14 = Level(number=14, size=19, time_budget=16.0, vision_radius=1.69);

    # Three small mazes; cell counts roughly track the size field.
    maze1 = Maze(label="starter-9x9");
