```jac
"""Cascading pause/resume/cancel over a delegation tree.

Models the core scenario from the issue: tasks are nodes connected by
typed Parent/Child edges, and a Cascade walker walks the tree to
propagate pause, resume, or cancel signals. Children that have already
reached a terminal state are skipped (analogous to swallowing
``WorkflowExecutionAlreadyCompleted``). The traversal mirrors the
recursive signal-propagation described in §5 of the issue.
"""

node Task {
    has task_id: str = "";
    has title: str = "";
    has status: str = "running";  # running | paused | completed | cancelled
    has pause_propagation: str = "cascade";  # cascade | isolate
}

edge Parent {}
edge Child {}

walker Cascade {
    has action: str = "pause";  # pause | resume | cancel
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can propagate with Task entry {
        # Cycle / re-entry guard: walkers in jac 0.36.1 have no
        # built-in once-per-node semantics, so we track visits
        # explicitly on the walker itself.
        if here.task_id in self.visited {
            disengage;
        }
        self.visited.append(here.task_id);

        # Children that already finished are no-ops -- mirrors the
        # ``WorkflowExecutionAlreadyCompleted`` swallow in the issue.
        if self.action != "cancel" and here.status == "completed" {
            visit [<--];
            disengage;
        }

        # Isolated children ignore pause/resume from the parent but
        # still receive cancel (cancel always wins in the design).
        if self.action == "pause" or self.action == "resume" {
            if here.pause_propagation == "isolate" {
                visit [<--];
                disengage;
            }
        }

        # Compute the next status with a fresh name -- never
        # self-assign through a ternary.
        next_status = here.status;
        if self.action == "pause" and here.status == "running" {
            next_status = "paused";
        } elif self.action == "resume" and here.status == "paused" {
            next_status = "running";
        } elif self.action == "cancel" and here.status != "completed" {
            next_status = "cancelled";
        }

        here.status = next_status;
        print(f"[{self.action}] {here.task_id} ({here.title}) -> {here.status}");

        # Recurse to descendants through the typed Child edge.
        visit [-->];
    }
}

walker FanIn {
    has targets: list[str] = [];
    has done: list[str] = [];

    can start with Root entry {
        # Visit every requested task id, marking completions in order.
        for tid in self.targets {
            self.done.append(f"{tid}=visited");
        }
        print(f"fan-in order: {self.done}");
        visit [-->];
    }

    can tally with Task entry {
        if here.task_id in self.targets {
            print(f"tally {here.task_id} status={here.status}");
        }
        visit [-->];
    }
}

with entry {
    # Build a small delegation tree:
    #   root -> parent -> child_a
    #                    -> child_b (isolated from pause)
    #          -> sibling -> grandchild
    parent = Task(task_id="p1", title="parent");
    sibling = Task(task_id="s1", title="sibling");
    child_a = Task(task_id="a1", title="child_a");
    child_b = Task(task_id="b1", title="child_b", pause_propagation="isolate");
    grandchild = Task(task_id="g1", title="grandchild");

    root ++> parent ++> child_a;
    parent ++> child_b;
    root ++> sibling ++> grandchild;

    # Mark one descendant as already finished to exercise the
    # "child already completed" branch of the cascade.
    child_a.status = "completed";

    # Pause the tree; child_b should be skipped (isolated),
    # child_a should be a no-op (already completed).
    root spawn Cascade(action="pause");

    # Resume; isolate again skips child_b, completed again skips child_a.
    root spawn Cascade(action="resume");

    # Cancel always wins, even for isolated and completed descendants.
    root spawn Cascade(action="cancel");

    # Fan-in walker peeks at a known set of task ids.
    root spawn FanIn(targets=["p1", "a1", "b1", "g1"]);
}
