    #        link_db -> link_common (diamond converges)
    #        bundle_app (also direct)
    #        test_suite (stale)
    rt = root;
    compile_core = Task(title="compile_core", minutes=10);
    link_ui = Task(title="link_ui", minutes=6);
    link_db = Task(title="link_db", minutes=6);
