"""Versioned ordering tokens for naming disambiguation.

Models the issue's central scenario: ranking siblings that share a parent set
via an ordering token stamped with a version. A walker migrates legacy
unversioned tokens to the current version on load, preserving disambiguation
semantics without hand-rolled adjacency maps or recursion plumbing.
"""

node OrderedItem {
    has label: str = "";
    has coord: tuple[float, float, float] = (0.0, 0.0, 0.0);
    has rank_token: str = "";
    has rank_version: int = 0;
}

node SiblingSet {
    has title: str = "";
    has ordering_version: int = 0;
}

edge Grouped {
    has rank_hint: int = 0;
}

edge RanksWith {
    has token: str = "";
    has version: int = 0;
}

node MigrationLog {
    has count: int = 0;
    has target_version: int = 0;
}

walker RankMigrator {
    has target_version: int = 2;
    has migrated: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_set with SiblingSet entry {
        outdated = [item for item in [-->] if isinstance(item, OrderedItem) and item.rank_version < self.target_version];
        for item in outdated {
            stamped = f"v{self.target_version}#{item.coord[0]:.3f},{item.coord[1]:.3f},{item.coord[2]:.3f}";
            item.rank_token = stamped;
            item.rank_version = self.target_version;
            self.migrated += 1;
        }
        if outdated {
            print(f"[migrator] set '{here.title}': rewrote {len(outdated)} token(s) to v{self.target_version}");
        }
        visit [-->];
    }

    can finalize with MigrationLog entry {
        here.count = self.migrated;
        here.target_version = self.target_version;
        print(f"[migrator] wrote MigrationLog: count={here.count}, target_version={here.target_version}");
        disengage;
    }
}

walker NamingAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with SiblingSet entry {
        items = [item for item in [-->] if isinstance(item, OrderedItem)];
        items_sorted = sorted(items, key=lambda (it: OrderedItem) -> str: it.rank_token);
        for it in items_sorted {
            verdict = "ok" if it.rank_version == 2 else "STALE";
            print(f"  [{verdict}] {it.label} token={it.rank_token}");
        }
        visit [-->];
    }

    can done with MigrationLog entry {
        disengage;
    }
}

with entry {
    # A sibling set with three items, two of which carry the legacy
    # unversioned lex-by-coordinate token and one already stamped v1.
    set_a = SiblingSet(title="Edges-of-Face-A", ordering_version=2);

    item1 = OrderedItem(label="edge-1", coord=(0.5, 0.5, 0.0), rank_token="0.500,0.500,0.000", rank_version=0);
    item2 = OrderedItem(label="edge-2", coord=(0.5, 0.5, 0.0), rank_token="v1#0.500,0.500,0.000", rank_version=1);
    item3 = OrderedItem(label="edge-3", coord=(0.7, 0.3, 0.0), rank_token="v1#0.700,0.300,0.000", rank_version=1);

    root ++> set_a;
    set_a +>:Grouped:+> item1;
    set_a +>:Grouped:+> item2;
    set_a +>:Grouped:+> item3;

    log = MigrationLog(count=0, target_version=0);
    set_a +>:Grouped:+> log;

    print("== before migration ==");
    root spawn NamingAuditor();

    print("== running migrator ==");
    root spawn RankMigrator(target_version=2);

    print("== after migration ==");
    root spawn NamingAuditor();
}
