"""LMCache Q3 Roadmap tracker: sections, work items, and accelerator dependencies
modeled as graph nodes traversed by a planner walker that performs dependency
ordering, reachability, and invalidation natively in Jac."""

# --- Node archetypes ---------------------------------------------------------

node Roadmap {
    has title: str = "";
    has quarter: str = "";
}

node Section {
    has title: str = "";
    has objective: str = "";
    has order_index: int = 0;
}

node WorkItem {
    has title: str = "";
    has done: bool = False;
    has ref_issue: str = "";
}

node Accelerator {
    has name: str = "";
    has vendor: str = "";
}

# --- Edge archetypes ---------------------------------------------------------

edge BelongsTo { }     # WorkItem -> Section, Section -> Roadmap
edge NeedsAccel { }   # WorkItem -> Accelerator (integration step depends on platform)
edge DependsOn { }    # WorkItem -> WorkItem (ordering constraint)

# --- Planner walker: traverses Section graph, invalidates stale items --------

walker Planner {
    has log_lines: list[str] = [];
    has invalidated: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can overview with Roadmap entry {
        self.log_lines.append(f"ROADMAP: {here.title} ({here.quarter})");
        visit [-->];
    }

    can list_sections with Section entry {
        self.log_lines.append(
            f"  Section[{here.order_index}] {here.title} :: {here.objective}"
        );
        visit [-->];
    }

    can audit_items with WorkItem entry {
        state = "DONE" if here.done else "OPEN";
        ref = f" ({here.ref_issue})" if here.ref_issue != "" else "";
        self.log_lines.append(f"    - [{state}] {here.title}{ref}");

        # Cascade invalidation: if the item links to an accelerator
        # integration and is not done yet, count and flag the invalidation.
        accel_targets = [here ->:NeedsAccel:->];
        has_accel = False;
        for _node in accel_targets {
            has_accel = True;
        }
        if has_accel and not here.done {
            self.invalidated += 1;
            self.log_lines.append(
                f"      ! invalidated (needs accelerator integration)"
            );
        }
        visit [-->];
    }

    can note_accel with Accelerator entry {
        self.log_lines.append(f"      accel: {here.name} ({here.vendor})");
        visit [-->];
    }
}

# --- Demonstration wiring ----------------------------------------------------

with entry {
