    );
    w_maca = WorkItem(
        title="New accelerator: MACA",
        done=False,
        ref_issue="#3856",
    );
    w_ascend = WorkItem(
        title="New accelerator: Ascend",
        done=False,
        ref_issue="#3968",
    );
    w_compress = WorkItem(
        title="More KV cache compression algorithms",
        done=True,
        ref_issue="",
    );

    a_maca = Accelerator(name="MACA", vendor="MetaX");
    a_ascend = Accelerator(name="Ascend", vendor="Huawei");

    # Roadmap -> Sections (ordered by traversal from root)
    root ++> rm;
    rm ++> s1;
