    # Spawn the planner on root and print the accumulated log.
    planner = Planner();
    root spawn planner;

    for line in planner.log_lines {
        print(line);
    }
    print(f"\nTotal items invalidated by missing accel integration: "
          f"{planner.invalidated}");
}
