"""Compiler-profile current-generation join: model coherent generations that
bind editor-intelligence and product-health consumers to the exact compiler
status member they depend on, with no cross-area substitution."""

# --- Entity archetypes ----------------------------------------------------

node Generation {
    has label: str = "";
    has current: bool = True;
}

node CompilerStatus {
    has machine_id: str = "";
    has state: str = "absent";
    has profile: str = "";
    has candidate: str = "";
}

node EditorJoin {
    has packet_id: str = "";
    has substrate: str = "";
    has feature_plane: str = "";
    has provider_plane: str = "";
    has edit_plane: str = "";
    has client_plane: str = "";
    has blocked: bool = False;
}

node ProductRail {
    has packet_id: str = "";
    has area: str = "compiler";
    has profile: str = "";
    has blocked: bool = False;
}

# --- Edge archetypes ------------------------------------------------------

edge BelongsTo { }       # member -> generation
edge DependsOn { }        # consumer -> compiler status source

# --- Walker: read a coherent current generation ---------------------------

walker CurrentView {
    has generation_label: str = "";
    has rows: list = [];

    can begin with Root entry {
        visit [-->];
    }

    can select with Generation entry {
        if here.label != self.generation_label or not here.current {
            visit [-->];
        }
        visit [-->];
    }

    can observe_compiler with CompilerStatus entry {
        if here.state in ["absent", "stale", "invalid", "conflicting", "not_proven"] {
            self.rows.append(("compiler_blocked", here.machine_id, here.state));
        } else {
            self.rows.append(("compiler_ok", here.machine_id, here.state));
        }
    }

    can observe_editor with EditorJoin entry {
        bound = "bound" if not here.blocked else "blocked_by_compiler";
        self.rows.append(("editor_join", here.packet_id, bound));
    }

    can observe_rail with ProductRail entry {
        # Rails are independent named surfaces; lower profile may not satisfy
        # stronger, and compiler rails cannot satisfy non-compiler areas.
        valid = not here.blocked;
        self.rows.append(("rail", here.packet_id, here.area, "ok" if valid else "blocked"));
    }

    can report with Root entry {
        print(f"Current generation view: {self.generation_label}");
        for row in self.rows {
            print(f"  - {row}");
        }
        report self.rows;
    }
}

# --- Walker: invalidate a generation when status moves without member ---

walker StatusMovement {
    has status_changed: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can check with Generation entry {
        if here.current and self.status_changed {
            here.current = False;
            print(f"Generation {here.label} marked non-current (status moved without new member)");
        }
        visit [-->];
    }
}

# --- Demonstration wiring -------------------------------------------------

with entry {
    gen_a = Generation(label="2025-Q1");
    gen_b = Generation(label="2024-Q4", current=False);

    # one compiler machine-status member
    machine = CompilerStatus(machine_id="M-7460", state="passing", profile="core", candidate="release");

    # editor-intelligence join packet member (#12200) — bound to that compiler member
    edi_join = EditorJoin(
        packet_id="edi-12200",
        substrate="core",
        feature_plane="providers",
        provider_plane="provider-pass",
        edit_plane="edit-auth",
        client_plane="client-behavior",
        blocked=False,
    );

    # product-health rail packet member (#12201) — compiler rail only
    compiler_rail = ProductRail(packet_id="rail-12201-c", area="compiler", profile="core", blocked=False);

    # an invalid rail: tries to use a compiler rail to satisfy parser area
    parser_rail_blocked = ProductRail(packet_id="rail-12201-p", area="parser", profile="core", blocked=True);

    # historical packet member that must NOT satisfy current consumers
    historical_join = EditorJoin(packet_id="edi-12200-old", substrate="core", blocked=False);

    root ++> gen_a ++> gen_b;
    gen_a +>:BelongsTo:+> machine;
    gen_a +>:BelongsTo:+> edi_join;
    gen_a +>:BelongsTo:+> compiler_rail;
    gen_a +>:BelongsTo:+> parser_rail_blocked;
    gen_b +>:BelongsTo:+> historical_join;

    edi_join +>:DependsOn:+> machine;
    compiler_rail +>:DependsOn:+> machine;

    # 1. Read the coherent current generation
    root spawn CurrentView(generation_label="2025-Q1");

    # 2. Simulate a status movement without a new member -> generation invalid
    root spawn StatusMovement(status_changed=True);
}
