```jac
"""Trust-model demo: artifacts with typed integrity/staleness attributes
linked by resolution dependencies; a walker audits the dependency graph
for cycles and reports a PACELC position per artifact.

Models the essential scenario from the AIKR CG kroftrust issue:
  - Artifacts carry {integrity, staleness_bound} as typed attributes.
  - Resolution dependency is a typed edge carrying PACELC + governance.
  - A walker performs dependency traversal (cycle-safe), gathers typed
    attributes, and reports a per-artifact resolution profile.
"""

# ---------- Edge archetypes ----------

# Resolution dependency: the source artifact depends on the target's
# resolution authority. Carries the PACELC position (PC/EC axes) and a
# governance/control label so technical and governance concerns are not
# conflated (issue §2).
edge Resolves {
    has pacelc: str = "PC/EC";        # "PC/EC" | "PA/EL" | "PC/EL" | "PA/EC"
    has governance: str = "self";      # "self" | "publisher" | "registry"
}

# Revision / supersession edge: artifact a is superseded by artifact b
# within a bounded-staleness window. Carries the staleness bound T.
edge Supersedes {
    has staleness_bound: str = "T";    # e.g. "24h", "7d"
}

# ---------- Node archetypes ----------

node Artifact {
    has name: str = "";
    has integrity: str = "content-addressed";  # "content-addressed" | "location-bound"
    has staleness_bound: str = "T";
    has pacelc: str = "";
    has governance: str = "";
}

# ---------- Walker ----------

walker DependencyAuditor {
    has seen: list[str] = [];
    has cycles: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can audit with Artifact entry {
        # Resolve this artifact's effective PACELC + governance: if it
        # has explicit fields use those, otherwise fall back to the
        # dependency-edge values carried by its first incoming edge.
        effective_pc = here.pacelc if here.pacelc != "" else "PC/EC";
        effective_gov = here.governance if here.governance != "" else "self";
        here.pacelc = effective_pc;
        here.governance = effective_gov;

        # Cycle policy: explicit guard set (jac 0.36.1 has no built-in
        # once-per-node visitation, so we maintain one on the walker).
        if here.name in self.seen {
            cycle_label = f"cycle at {here.name}";
            self.cycles.append(cycle_label);
            disengage;
        }
        self.seen.append(here.name);

        # Domain rule: depth cap preserved from source.
        if self.depth >= self.max_depth {
            disengage;
        }

        print(
            f"[{here.name}] integrity={here.integrity} "
            f"staleness<={here.staleness_bound} "
            f"pacelc={effective_pc} gov={effective_gov} "
            f"depth={self.depth}"
        );

        self.depth += 1;
        visit [->:Resolves:->];
    }
}

# ---------- Demonstration graph ----------

with entry {
    # Three artifacts forming a resolution chain.
    root_doc = Artifact(
        name="identity",
        integrity="content-addressed",
        staleness_bound="1h",
    );
    policy_doc = Artifact(
        name="policy",
        integrity="location-bound",
        staleness_bound="24h",
    );
    revocation_doc = Artifact(
        name="revocation",
        integrity="content-addressed",
        staleness_bound="7d",
    );

    # Resolution dependencies (typed, carrying PACELC + governance).
    root_doc +>:Resolves(pacelc="PC/EL", governance="self"):+> policy_doc;
    policy_doc +>:Resolves(pacelc="PA/EC", governance="publisher"):+> revocation_doc;

    # Supersession edge (bounded staleness): policy is superseded by
    # a newer policy within 24h of the swap.
    policy_doc +>:Supersedes(staleness_bound="24h"):+> revocation_doc;

    # Wire to root and spawn the auditor.
    root ++> root_doc ++> policy_doc ++> revocation_doc;
    root spawn DependencyAuditor();

    print(f"cycles detected: {DependencyAuditor().cycles}");
}
