test "audits typed artifact profiles in dependency order" {
    identity = Artifact(
        name="identity",
        integrity="content-addressed",
        staleness_bound="1h",
        pacelc="PC/EL",
        governance="self",
    );
    policy = Artifact(
        name="policy",
        integrity="location-bound",
        staleness_bound="24h",
        pacelc="PA/EC",
        governance="publisher",
    );
    revocation = Artifact(
        name="revocation",
        integrity="content-addressed",
        staleness_bound="7d",
        pacelc="PC/EC",
        governance="registry",
    );

    root ++> identity;
    identity +>:Resolves(pacelc="PC/EL", governance="self"):+> policy;
    policy +>:Resolves(pacelc="PA/EC", governance="publisher"):+> revocation;

    assert len([root-->]) == 1, f"unexpected root children: {len([root-->])}";
    assert len([identity ->:Resolves:->]) == 1, "identity dependency edge missing";
    assert len([policy ->:Resolves:->]) == 1, "policy dependency edge missing";

    buf = io.StringIO();
