    out = buf.getvalue();

    assert len(res.seen) == 3, f"unexpected visited artifacts: {res.seen}";
    assert "[identity] integrity=content-addressed staleness<=1h pacelc=PC/EL gov=self depth=0" in out, f"identity audit missing: {out}";
    assert "[policy] integrity=location-bound staleness<=24h pacelc=PA/EC gov=publisher depth=1" in out, f"policy audit missing: {out}";
    assert "[revocation] integrity=content-addressed staleness<=7d pacelc=PC/EC gov=registry depth=2" in out, f"revocation audit missing: {out}";
}

