"""Diamond dependency audit: each task is counted once even when multiple paths reach it."""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker Auditor {
    has total_minutes: int = 0;
    has visited_titles: list[str] = [];

