"""Tests for the diamond dependency audit walker."""

import io;
import from contextlib { redirect_stdout }

# Helper to build the standard diamond graph and run Auditor, returning captured stdout.
def run_audit {
    compile = Task(title="compile", minutes=10);
    link_tests = Task(title="link_tests", minutes=5);
    link_app = Task(title="link_app", minutes=5);
    bundle_lib = Task(title="bundle_lib", minutes=3);

    root ++> compile ++> link_tests;
    root ++> link_tests ++> bundle_lib;
    root ++> link_app;
    root ++> link_app ++> bundle_lib;

    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    return (buf.getvalue(), auditor, res);
}

test "diamond deduplicates shared library minutes" {
    (out, auditor, res) = run_audit();

    # Expected unique audit minutes: 10 + 5 + 5 + 3 = 23 (no double-counting of bundle_lib).
    assert auditor.total_minutes == 23, f"expected 23 total minutes, got {auditor.total_minutes}";
    # The walker still reports a single visit order list with no duplicates.
    assert len(auditor.visited_titles) == 4, f"expected 4 unique audits, got {auditor.visited_titles}";
    # bundle_lib must appear exactly once in the visit list.
    assert auditor.visited_titles.count("bundle_lib") == 1, f"bundle_lib double-counted: {auditor.visited_titles}";
