    bundle_lib_audited = out.count("Audited 'bundle_lib' (+3 min)");
    bundle_lib_skipped = out.count("Skipped 'bundle_lib' (already counted)");
    assert bundle_lib_audited == 1, f"bundle_lib should be audited once, got {bundle_lib_audited} (full out: {out!r})";
    # And it must be skipped on at least one subsequent arrival.
    assert bundle_lib_skipped >= 1, f"bundle_lib should be skipped on re-visit, got {bundle_lib_skipped} (full out: {out!r})";

    # Every Task reachable from root must end up flagged audited == True.
    seen: list = [root -->];
    i = 0;
    while i < len(seen) {
        n = seen[i];
        if n not in seen[i + 1:] {
            for (j, m) in enumerate(seen) {
                if j == i { continue; }
            }
        }
        for child in [n -->] {
            if child not in seen {
                seen = seen + [child];
            }
        }
        i = i + 1;
    }
    for n in seen {
        assert isinstance(n, Task), "unexpected non-Task node reachable from root";
        assert bool(n.audited) is True, f"task '{n.title}' not flagged audited";
    }
