"""Project every ancestor collection into a document's transitive collection field."""

node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has field_name: str = "collection";
    has transitive: bool = True;
    has projected_collections: list[str] = [];
}

node Collection {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

edge PartOf {
    has predicate: str = "schema:isPartOf";
}

walker AncestorProjector {
    has seen: list[Collection] = [];
    has active_document: Document | None = None;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can project with Document entry {
        here.projected_collections = [];
        self.seen = [];
        self.active_document = here;
        print(f"Projecting {here.title} through {here.field_name}+");

        if here.transitive {
            visit [->:PartOf:->] else {
                disengage;
            }
        }
    }

    can collect with Collection entry {
        if here in self.seen {
            print(f"Cycle detected at {here.title}; stopping this branch");
            disengage;
        } else {
            self.seen.append(here);

            if self.active_document is not None {
