}

test "fraud order halts the walk and orders after it are not visited" {
    root ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=True, fraud=False)
        ++> Order(amount=30.0, valid=True, fraud=True)
        ++> Order(amount=40.0, valid=True, fraud=False);

