    assert "OK   order $10.0" in out, f"first OK not printed: {out}";
    assert "OK   order $20.0" in out, f"second OK not printed: {out}";
    assert "HALT on order $30.0: fraud flag raised" in out, f"halt line missing: {out}";
    assert "OK   order $40.0" not in out, f"traversal must stop at fraud order: {out}";
