test "invalid orders are skipped and audit continues to later orders" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=200.0, valid=False, fraud=False)
        ++> Order(amount=300.0, valid=True, fraud=False)
        ++> Order(amount=400.0, valid=False, fraud=False)
        ++> Order(amount=500.0, valid=True, fraud=False);

