    assert "SKIP order $200.0: invalid" in out, f"first SKIP missing: {out}";
    assert "OK   order $300.0" in out, f"second OK missing - skip should not break traversal: {out}";
    assert "SKIP order $400.0: invalid" in out, f"second SKIP missing: {out}";
    assert "OK   order $500.0" in out, f"final OK missing - traversal must continue past skips: {out}";
    assert "HALT" not in out, f"no halt expected on skipped orders: {out}";
    assert auditor.halted is False, f"skip path must not set halted, got {auditor.halted}";
}

test "clean chain (no fraud, all valid) reports completion" {
    root ++> Order(amount=11.0, valid=True, fraud=False)
        ++> Order(amount=22.0, valid=True, fraud=False)
