"""Flight network: priced legs as typed edges, scout reports peak fare, legs normalize against it."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has ticket_price: float = 0.0;
    has origin_code: str = "";
    has dest_code: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.ticket_price / peak;
    }
}

walker Scout {
    has peak_fare: float = 0.0;
    has fare_report: list[float] = [];
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can sweep with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.fare_report.append(leg.ticket_price);
            if leg.ticket_price > self.peak_fare {
                self.peak_fare = leg.ticket_price;
            }
        }
        visit [-->] else { disengage; };
    }
}

