"""Tests for the flight-network scout program."""

import io;
import from contextlib { redirect_stdout }

test "scout walks every flight leg and records the peak fare" {
    root ++> Airport(code="JFK");
    jfk = [root -->][?:Airport][0];
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");

    jfk +>:FlightLeg(ticket_price=450.0, origin_code="JFK", dest_code="LAX"):+> lax;
    lax +>:FlightLeg(ticket_price=320.0, origin_code="LAX", dest_code="ORD"):+> ord;
    ord +>:FlightLeg(ticket_price=580.0, origin_code="ORD", dest_code="JFK"):+> jfk;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
    }
    out = buf.getvalue();

    assert "[OUT]" not in out, f"Scout should not print, got: {out}";
    assert len(res.fare_report) == 3, f"expected 3 legs, got {len(res.fare_report)}";
    assert 450.0 in res.fare_report, f"JFK->LAX missing: {res.fare_report}";
    assert 320.0 in res.fare_report, f"LAX->ORD missing: {res.fare_report}";
    assert 580.0 in res.fare_report, f"ORD->JFK missing: {res.fare_report}";
    assert res.peak_fare == 580.0, f"peak should be 580.0, got {res.peak_fare}";
}

test "fare_fraction returns correct share of the peak fare" {
    root ++> Airport(code="A");
    a = [root -->][?:Airport][0];
    b = Airport(code="B");
    leg = FlightLeg(ticket_price=450.0, origin_code="A", dest_code="B");
    a +>:leg:+> b;

    peak = 580.0;
    share = leg.fare_fraction(peak);
    expected = 450.0 / 580.0;
    assert abs(share - expected) < 1e-9, f"expected {expected}, got {share}";

    top_leg = FlightLeg(ticket_price=580.0, origin_code="X", dest_code="Y");
    assert top_leg.fare_fraction(580.0) == 1.0, "peak-priced leg should be 100%";
}

test "fare_fraction returns zero when peak is non-positive (fail-closed)" {
    leg = FlightLeg(ticket_price=450.0, origin_code="A", dest_code="B");
    assert leg.fare_fraction(0.0) == 0.0, "peak=0 must yield 0.0, not divide-by-zero";
    assert leg.fare_fraction(-10.0) == 0.0, "negative peak must yield 0.0";
}

test "main block prints peak fare line and a percentage line for every leg" {
    root ++> Airport(code="JFK");
    jfk = [root -->][?:Airport][0];
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");

    leg_jfk_lax = FlightLeg(ticket_price=450.0, origin_code="JFK", dest_code="LAX");
    leg_lax_ord = FlightLeg(ticket_price=320.0, origin_code="LAX", dest_code="ORD");
    leg_ord_jfk = FlightLeg(ticket_price=580.0, origin_code="ORD", dest_code="JFK");

    jfk +>:leg_jfk_lax:+> lax;
    lax +>:leg_lax_ord:+> ord;
    ord +>:leg_ord_jfk:+> jfk;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
        peak = res.peak_fare;
        print(f"Scout peak fare: ${peak} (reported {len(res.fare_report)} legs)");

        legs = [leg_jfk_lax, leg_lax_ord, leg_ord_jfk];
        for leg in legs {
            share = leg.fare_fraction(peak);
            print(
                f"{leg.origin_code}->{leg.dest_code} "
                f"${leg.ticket_price} is {share:.2%} of top fare"
            );
        }
    }
    out = buf.getvalue();

    assert "Scout peak fare: $580.0 (reported 3 legs)" in out, f"missing peak line: {out}";
    assert "JFK->LAX $450.0 is 77.59% of top fare" in out, f"missing JFK->LAX line: {out}";
    assert "LAX->ORD $320.0 is 55.17% of top fare" in out, f"missing LAX->ORD line: {out}";
    assert "ORD->JFK $580.0 is 100.00% of top fare" in out, f"missing ORD->JFK line: {out}";

    leg_lines = [
        ln for ln in out.splitlines()
        if "->" in ln and "of top fare" in ln
    ];
    assert len(leg_lines) == 3, f"expected 3 per-leg lines, got {len(leg_lines)}: {leg_lines}";
}

