"""Order auditor demonstrating both flavors of early return.

Invalid orders are skipped (the walk continues to the next order),
while fraud-flagged orders halt the whole walk immediately via
``disengage;``. A line is printed per order showing which action fired.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;

    can start with Root entry {
        print("Audit begin");
        visit [-->];
    }

    can audit with Order entry {
        self.audited += 1;

        if here.fraud {
            print(f"[HALT-FRAUD] {here.label} amount={here.amount} -> disengaging");
            disengage;
        }

        if not here.valid {
            print(f"[SKIP-INVALID] {here.label} amount={here.amount}");
            visit [-->];
            return;
        }

        print(f"[AUDIT-OK] {here.label} amount={here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="O-1001", amount=120.50)
        ++> Order(label="O-1002", amount=0.00, valid=False)
        ++> Order(label="O-1003", amount=9999.99, fraud=True)
        ++> Order(label="O-1004", amount=42.00);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"audited count (fraud case truncated): {auditor.audited}");

    # Second run, no fraud anywhere, to show the skip-then-continue flow.
    auditor2 = OrderAuditor();
    root ++> Order(label="O-2001", amount=15.00)
        ++> Order(label="O-2002", amount=0.00, valid=False)
        ++> Order(label="O-2003", amount=77.77)
        ++> Order(label="O-2004", amount=33.33);
    root spawn auditor2;
    print(f"audited count (clean run): {auditor2.audited}");
}
