"""Widget composition core: Plugin → System → Blueprint → Document → Runtime.

Models the canonical Widget composition core architecture from issue #10.
A WidgetPlugin is composed into a WidgetSystem, which compiles a source into
an immutable Blueprint. A WidgetDocument holds the accepted authored source
snapshot and applies low-level SourcePatch operations atomically. A
WidgetSystemRuntime is only created from a valid Blueprint and is NOT
persisted. A DocumentInspector walker traverses the patch history of a
document to report applied operations, exercising typed-edge traversal.
"""

node WidgetPlugin {
    has name: str = "";
    has version: int = 0;
    has interfaces: str = "";
}

node WidgetSystem {
    has name: str = "";
    has plugin_count: int = 0;
}

node WidgetSource {
    has path: str = "";
    has kind: str = "nested";
}

node WidgetSystemBlueprint {
    has blueprint_id: str = "";
    has valid: bool = True;
    has compiled_from: str = "";
}

node WidgetDocument {
    has doc_id: str = "";
    has source_path: str = "";
    has commit_count: int = 0;
}

node WidgetSystemRuntime {
    has runtime_id: str = "";
    has derived_from: str = "";
}

edge Composes {
    has slot: str = "default";
}

edge CompilesTo {
    has at_step: int = 0;
}

edge HoldsSnapshot {
    has accepted_at: str = "";
}

edge AppliesPatch {
    has op_index: int = 0;
    has operation: str = "";
    has target_path: str = "";
}

edge DerivesRuntime {
    has valid_at: str = "";
}

walker BlueprintCompiler {
    can start with Root entry {
        print("BlueprintCompiler: starting at root");
        visit [->:Composes:->];
    }

    can collect_plugins with WidgetSystem entry {
        for p in [->:Composes:->] {
            print(f"  composing plugin: {p.name} v{p.version} "
                  f"(slot={self})");
        }
        visit [->:CompilesTo:->];
    }

    can emit_blueprint with WidgetSystemBlueprint entry {
        print(f"Blueprint {here.blueprint_id} compiled "
              f"from '{here.compiled_from}', valid={here.valid}");
        visit [->:DerivesRuntime:->];
    }

    can note_runtime with WidgetSystemRuntime entry {
        print(f"Runtime {here.runtime_id} derived from "
              f"'{here.derived_from}' (transient, not persisted)");
        disengage;
    }
}

walker DocumentInspector {
    can start with Root entry {
        print("DocumentInspector: starting at root");
        visit [->:HoldsSnapshot:->];
    }

    can open_doc with WidgetDocument entry {
        print(f"Document {here.doc_id} holds source "
              f"'{here.source_path}', commits={here.commit_count}");
        visit [->:AppliesPatch:->];
    }

    can describe_patch with WidgetDocument entry {
        print(f"  patch op#{here.commit_count} {here.commit_count}"
              f" -> path='{here.source_path}'");
        visit [-->];
    }
}

walker PatchApplier {
    has pending_ops: list[str] = [];
    has target_path: str = "";
    has applied_count: int = 0;

    can start with Root entry {
        print("PatchApplier: applying RFC6902 ops atomically");
        visit [->:HoldsSnapshot:->];
    }

    can apply with WidgetDocument entry {
        print(f"  targeting document {here.doc_id} at '{here.source_path}'");
        for op in self.pending_ops {
            here.commit_count += 1;
            self.applied_count += 1;
            print(f"    [{here.commit_count}] {op} -> "
                  f"{self.target_path}");
        }
        print(f"  atomic commit complete: {self.applied_count} op(s) "
              f"applied in one Document transition");
        disengage;
    }
}

with entry {
    sys = WidgetSystem(name="dashboard", plugin_count=2);
    p1 = WidgetPlugin(name="Counter", version=1, interfaces="state");
    p2 = WidgetPlugin(name="Chart", version=2, interfaces="props");

    bp = WidgetSystemBlueprint(
        blueprint_id="bp-001",
        valid=True,
        compiled_from="nested"
    );
    src = WidgetSource(path="source.nested", kind="nested");
    rt = WidgetSystemRuntime(
        runtime_id="rt-001",
        derived_from="bp-001"
    );

    doc = WidgetDocument(
        doc_id="doc-001",
        source_path="source.nested",
        commit_count=0
    );

    sys +>:Composes(slot="primary"):+> p1;
    sys +>:Composes(slot="secondary"):+> p2;
    sys +>:CompilesTo(at_step=1):+> bp;
    bp +>:DerivesRuntime(valid_at="compile"):+> rt;
    doc +>:HoldsSnapshot(accepted_at="init"):+> src;

    root ++> sys ++> bp ++> rt;
    root ++> doc ++> src;

    print("=== Blueprint compilation traversal ===");
    root spawn BlueprintCompiler();

    print("\n=== Document patch application ===");
    applier = PatchApplier(
        pending_ops=["replace", "add", "remove"],
        target_path="/widgets/0"
    );
    root spawn applier;

    print("\n=== Document patch history traversal ===");
    root spawn DocumentInspector();
}
