"""Quiz grader walker with strictly typed integer reports.

The grader visits each ``Quiz`` node in turn, collects the integer score
on its ``report`` accumulator, and prints the per-quiz scores together
with the class average. The walker explicitly disconnects each visited
quiz from the root once graded, leaving the graph clean after the walk.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has report: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can grade with Quiz entry {
        self.report.append(here.score);
        print(f"{here.student}: {here.score}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carla", score=95)
        ++> Quiz(student="Dani", score=61);

    grader = Grader();
    root spawn grader;

    total = 0;
    for score in grader.report {
        total = total + score;
    }
    average = total / len(grader.report) if len(grader.report) > 0 else 0;
    print(f"Scores: {grader.report}");
    print(f"Class average: {average}");
}
