"""Orchard maintenance crew: one shared routine services pumps and sprinklers,
logs each device, resets its idle counter, and tracks the total serviced."""

node Device {
    has label: str = "";
    has idle_hours: int = 0;

    # Every concrete device knows how to identify itself by kind.
    def kind() -> str {
        return "Device";
    }

    # Concrete devices override this to record their type during servicing.
    def service() -> None {
        self.idle_hours = 0;
    }
}

node Pump(Device) {
    override def kind() -> str {
        return "Pump";
    }
}

node Sprinkler(Device) {
    override def kind() -> str {
        return "Sprinkler";
    }
}

walker Crew {
    has serviced: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Crew entering the orchard...");
        visit [-->];
    }

    # One shared union routine handles every device kind.
    can service_device with Pump | Sprinkler entry {
        kind_name = here.kind();
        entry = f"{kind_name} '{here.label}' idle {here.idle_hours}h -> serviced";
        self.log.append(entry);
        here.service();
        self.serviced += 1;
        visit [-->];
    }
}

with entry {
    grove_a = Pump(label="A-1", idle_hours=14);
    grove_b = Sprinkler(label="B-2", idle_hours=6);
    grove_c = Pump(label="C-3", idle_hours=22);
    grove_d = Sprinkler(label="D-4", idle_hours=3);

    root ++> grove_a ++> grove_b ++> grove_c ++> grove_d;

    crew = Crew();
    root spawn crew;

    print("--- service log ---");
    for entry in crew.log {
        print(entry);
    }
    print(f"Total devices serviced: {crew.serviced}");
    print(f"Pump A-1 idle hours after service: {grove_a.idle_hours}");
    print(f"Sprinkler B-2 idle hours after service: {grove_b.idle_hours}");
}
