    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }

    assert res.violations == 3, f"expected 3 violations, got {res.violations}";
    assert "[VIOLATION]" in buf.getvalue(), "missing VIOLATION marker";
    assert "[OK]" not in buf.getvalue(), "no station should be OK";

    # All three stations must still be logged (both checks fire at every station).
    assert len(res.visits) == 3, f"expected 3 visits, got {len(res.visits)}";
    assert "Char-broiler (grill)" in res.visits, f"grill missing from visits: {res.visits}";
    assert "Deep fryer (fryer)" in res.visits, f"fryer missing from visits: {res.visits}";
