"""Weather sweep: stations report temperature readings as a walker sweeps them."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker Sweep {
    has readings: list[tuple[str, str, float]] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        self.recordings_add(here);
        print(f"[{here.location}] {here.name}: {here.celsius} C");
        visit [-->];
    }

