        self.readings.append((s.name, s.location, s.celsius));
    }
}

with entry {
    root ++> Station(name="North", location="Ridge", celsius=18.5)
        ++> Station(name="South", location="Valley", celsius=24.0)
        ++> Station(name="East", location="Coast", celsius=21.3)
