    sweeper = Sweep();
    root spawn sweeper;

    print("--- summary ---");
    for (n, loc, t) in sweeper.readings {
        print(f"{n} @ {loc} -> {t} C");
    }
    temps = [t for (n, loc, t) in sweeper.readings];
    print(f"min: {min(temps)} C, max: {max(temps)} C");
}
