test "chain creates three tracks off root in one statement" {
    root ++> Track(title="Highway Sun", artist="Open Road", runtime_sec=215)
        ++> Track(title="Desert Wind", artist="Cactus Choir", runtime_sec=198)
        ++> Track(title="Coastal Stars", artist="Night Drift", runtime_sec=247);

    # root should have exactly one direct child (start of the chain).
    assert len([root-->]) == 1, f"expected 1 direct child, got {len([root-->])}";

    # Walk the chain and collect tracks in order.
    chain = [];
    cur = [root-->][0];
    chain.append(cur);
    while len([cur-->]) > 0 {
        cur = [cur-->][0];
        chain.append(cur);
    }

    assert len(chain) == 3, f"expected 3 tracks in chain, got {len(chain)}";

    first = chain[0];
    assert first.title == "Highway Sun", f"got {first.title}";
    assert first.artist == "Open Road", f"got {first.artist}";
    assert first.runtime_sec == 215, f"got {first.runtime_sec}";

    second = chain[1];
    assert second.title == "Desert Wind", f"got {second.title}";
    assert second.artist == "Cactus Choir", f"got {second.artist}";
    assert second.runtime_sec == 198, f"got {second.runtime_sec}";

    third = chain[2];
    assert third.title == "Coastal Stars", f"got {third.title}";
    assert third.artist == "Night Drift", f"got {third.artist}";
    assert third.runtime_sec == 247, f"got {third.runtime_sec}";
}

test "player walker prints all three legs in order" {
    root ++> Track(title="Highway Sun", artist="Open Road", runtime_sec=215)
        ++> Track(title="Desert Wind", artist="Cactus Choir", runtime_sec=198)
        ++> Track(title="Coastal Stars", artist="Night Drift", runtime_sec=247);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # Header printed on Root entry.
    assert "=== Road Trip Playlist ===" in out, f"missing header: {out}";

    # Each leg line for each track, in the right order.
    leg1_pos = out.find("Leg 1:");
    leg2_pos = out.find("Leg 2:");
    leg3_pos = out.find("Leg 3:");
    assert leg1_pos != -1, f"missing Leg 1: {out}";
    assert leg2_pos != -1, f"missing Leg 2: {out}";
    assert leg3_pos != -1, f"missing Leg 3: {out}";
    assert leg1_pos < leg2_pos < leg3_pos, f"legs not in order: {out}";

    # All three tracks get played.
    assert "Highway Sun" in out, f"missing Highway Sun: {out}";
    assert "Open Road" in out, f"missing Open Road: {out}";
    assert "Desert Wind" in out, f"missing Desert Wind: {out}";
    assert "Cactus Choir" in out, f"missing Cactus Choir: {out}";
    assert "Coastal Stars" in out, f"missing Coastal Stars: {out}";
    assert "Night Drift" in out, f"missing Night Drift: {out}";
}

test "running total runtime accumulates across legs" {
    root ++> Track(title="Highway Sun", artist="Open Road", runtime_sec=215)
        ++> Track(title="Desert Wind", artist="Cactus Choir", runtime_sec=198)
        ++> Track(title="Coastal Stars", artist="Night Drift", runtime_sec=247);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # 215s -> 3m 35s running total after leg 1.
    assert "total 3m 35s" in out, f"missing total 3m 35s after leg 1: {out}";

    # 215 + 198 = 413s -> 6m 53s running total after leg 2.
    assert "total 6m 53s" in out, f"missing total 6m 53s after leg 2: {out}";

    # 215 + 198 + 247 = 660s -> 11m 00s running total after leg 3.
    assert "total 11m 00s" in out, f"missing total 11m 00s after leg 3: {out}";

    # Walker's accumulated total matches the sum of all three runtimes.
    assert res.total_sec == 660, f"expected total 660s, got {res.total_sec}";
    assert res.leg == 3, f"expected leg 3, got {res.leg}";

    # Per-leg minute/second formatting for the first track (215s -> 3m 35s).
    assert "(3m 35s)" in out, f"missing (3m 35s) for Highway Sun: {out}";

    # Per-leg minute/second formatting for the third track (247s -> 4m 07s).
    assert "(4m 07s)" in out, f"missing (4m 07s) for Coastal Stars: {out}";
}

