"""Governance policy layers, typed relationships, and cycle-safe resolution."""

node Policy {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Layer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scope: str = "";
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has digest: str = "";
}

edge Contains { }
edge Extends { has priority: int = 0; }
edge Produces { has target: str = ""; }

walker GovernanceAuditor {
    has seen_layers: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("audit: start at policy graph");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_policy with Policy entry {
        print(f"policy: {here.title} ({here.year})");
        visit [->:Contains:->] else { disengage; }
    }

    can resolve_layer with Layer entry {
        if here.title in self.seen_layers {
            self.cycle_found = True;
            print(f"cycle detected at layer {here.title}; resolution stopped");
            disengage;
        } else {
            self.seen_layers.append(here.title);
            print(f"layer: {here.title}, scope={here.scope}");
            visit [->:Extends:->] else { disengage; }
        }
    }
}

walker ArtifactChecker {
    can start with Root entry {
        visit [->:Produces:->] else { disengage; }
    }

    can inspect with Artifact entry {
        print(f"artifact: {here.title}, digest={here.digest}");
        visit [-->] else { disengage; }
    }
}

with entry {
    policy = Policy(title="Organization Governance", year=2024);
    base = Layer(title="base", scope="global");
    overlay = Layer(title="production-overlay", scope="aws");
    artifact = Artifact(title="AWS edge policy", digest="sha256:demo");

    root +>:Contains:+> policy;
    policy +>:Contains:+> base;
    base +>:Extends(priority=1):+> overlay;
    overlay +>:Extends(priority=2):+> base;
    root +>:Produces(target="AWS"):+> artifact;

    root spawn GovernanceAuditor();
    root spawn ArtifactChecker();
}
