    base_url = Secret(key="LLM_BASE_URL", redacted=True);

    aisuite_imp = ImportRef(module_name="aisuite", used=False);

    hostname_only = Validator(name="reject_interaction", checks_path=False, checks_hostname=True);
    strict_validator = Validator(name="strict_url_check", checks_path=True, checks_hostname=True);

