"""Tests for the hiking trail: a chain of waypoints with a Hiker walker that counts stops."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts and prints each stop in order" {
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4)
        ++> Waypoint(stop_number=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_stops=5);
    }
    out = buf.getvalue();

    # Stops must be printed in order, one per waypoint visited.
    assert "Stop #1: waypoint 1" in out, f"missing first stop line: {out}";
    assert "Stop #2: waypoint 2" in out, f"missing second stop line: {out}";
    assert "Stop #3: waypoint 3" in out, f"missing third stop line: {out}";
    assert "Stop #4: waypoint 4" in out, f"missing fourth stop line: {out}";
    assert "Stop #5: waypoint 5" in out, f"missing fifth stop line: {out}";

    # And the walker must have recorded each stop it passed through.
    assert res.stops_passed == 5, f"expected 5 stops_passed, got {res.stops_passed}";
}

test "hiker disengages once target_stops is reached" {
    # Only need 4 waypoints beyond the trailhead to satisfy target_stops=4,
    # but the trail has 5 waypoints — the walker should NOT visit the last one.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4)
        ++> Waypoint(stop_number=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_stops=4);
    }
    out = buf.getvalue();

    # The completion line should appear exactly once, with the target count.
    assert "Trail complete! Passed 4 waypoints." in out, f"missing completion line: {out}";
    assert out.count("Trail complete!") == 1, f"completion printed more than once: {out}";

    # The 5th waypoint must NOT have been visited (fail-closed: disengage before over-counting).
    assert "Stop #5" not in out, f"walker kept going past target: {out}";
    assert "waypoint 5" not in out, f"walker kept going past target: {out}";
    assert res.stops_passed == 4, f"expected 4 stops_passed, got {res.stops_passed}";
}

test "hiker does not disengage while still under target_stops" {
    # A long trail but a low target — walker should keep moving and not
    # print the completion line early.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4)
        ++> Waypoint(stop_number=5)
        ++> Waypoint(stop_number=6);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_stops=3);
    }
    out = buf.getvalue();

    assert "Trail complete!" in out, f"completion line never printed: {out}";
    # Completion should reflect the target, not the full trail length.
    assert "Passed 3 waypoints." in out, f"completion count wrong: {out}";
    # Walker must not have run past the third waypoint.
    assert "waypoint 4" not in out, f"walker over-shot target: {out}";
    assert "waypoint 5" not in out, f"walker over-shot target: {out}";
    assert "waypoint 6" not in out, f"walker over-shot target: {out}";
    assert res.stops_passed == 3, f"expected 3 stops_passed, got {res.stops_passed}";
}

test "waypoints form a chain from trailhead to summit" {
    # The program promises a chain of plain waypoints between trailhead and summit.
    # Verify the graph shape: each waypoint links forward by exactly one edge.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4)
        ++> Waypoint(stop_number=5);

    # Five edges leave the trailhead/waypoints toward the next stop.
    forward_edges = [root -->];
    assert len(forward_edges) == 1, f"expected 1 child of root, got {len(forward_edges)}";

    # Walk the chain by hand and confirm stop_number increases by 1 each step.
    current = forward_edges[0];
    seen_numbers = [current.stop_number];
    while len([current -->]) > 0 {
        current = [current -->][0];
        seen_numbers.append(current.stop_number);
    }

    assert seen_numbers == [1, 2, 3, 4, 5], f"chain order wrong: {seen_numbers}";
    # Final waypoint is the summit — no further neighbors.
    assert len([current -->]) == 0, "summit should have no outgoing waypoints";
}

