"""Control Tower review queue: append-only exact-head tickets, pending resolution, and fail-closed head verification."""

node QueueEntry {
    has pr: int = 0;
    has seq: int = 0;

    def ticket_key() -> str {
        return "";
    }

    def is_result() -> bool {
        return False;
    }
}

node ControlTower {
    has title: str = "ISSUE-453 Independent Review Queue";
}

node PullRequest {
    has pr: int = 0;
    has current_head: str = "";
    has title: str = "";
}

node ReviewRequest(QueueEntry) {
    has exact_head: str = "";
    has priority: int = 1;

    override def ticket_key() -> str {
        return f"{self.pr}:{self.exact_head}";
    }
}

node ReviewResult(QueueEntry) {
    has reviewed_head: str = "";
    has verdict: str = "";
    has review_channel: str = "EXACT_HEAD_COMMENT_ATTESTATION";

    override def ticket_key() -> str {
        return f"{self.pr}:{self.reviewed_head}";
    }

    override def is_result() -> bool {
        return True;
    }
}

edge Appended {
    has seq: int = 0;
}

edge ForPR { }

walker QueueAuditor {
    has pending_keys: list[str] = [];
    has resolved_keys: list[str] = [];
    has seen_seq: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with ControlTower entry {
        print(f"Scanning {here.title}");
        visit [->:Appended:->] else { disengage; };
    }

    can scan with ReviewRequest | ReviewResult entry {
        if here.seq in self.seen_seq {
            print(f"CYCLE blocked at seq={here.seq}");
            disengage;
        }
        self.seen_seq.append(here.seq);
        key = here.ticket_key();
        if here.is_result() {
            if key not in self.resolved_keys {
                self.resolved_keys.append(key);
            }
            new_pending: list[str] = [];
            for ticket_key in self.pending_keys {
                if ticket_key != key {
                    new_pending.append(ticket_key);
                }
            }
            self.pending_keys = new_pending;
        } else {
            if key not in self.resolved_keys and key not in self.pending_keys {
                self.pending_keys.append(key);
            }
        }
        visit [->:Appended:->] else { disengage; };
    }

    can summarize with ControlTower exit {
        print(f"Resolved tickets: {len(self.resolved_keys)}; pending: {len(self.pending_keys)}");
        for ticket_key in self.pending_keys {
            print(f"  PENDING {ticket_key}");
        }
    }
}

walker HeadVerifier {
    has ticket_head: str = "";
    has ticket_pr: int = 0;
    has ticket_seq: int = 0;
    has verified: int = 0;
    has blocked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with ControlTower entry {
        print("Verifying exact-head bindings (fail-closed on stale heads)");
        visit [->:Appended:->] else { disengage; };
    }

    can verify_request with ReviewRequest entry {
        self.ticket_head = here.exact_head;
        self.ticket_pr = here.pr;
        self.ticket_seq = here.seq;
        visit [->:ForPR:->] else {
            print(f"FAIL-CLOSED: REVIEW_REQUEST/v1 seq={here.seq} has no PR binding");
            self.blocked += 1;
        };
        visit [->:Appended:->] else { disengage; };
    }

    can bind_head with PullRequest entry {
        if here.pr != self.ticket_pr {
            disengage;
        }
        if here.current_head != self.ticket_head {
            print(
                f"FAIL-CLOSED: PR #{self.ticket_pr} seq={self.ticket_seq} "
                f"wants {self.ticket_head} but current_head is {here.current_head}"
            );
            self.blocked += 1;
        } else {
            print(
