                f"exact_head {self.ticket_head} matches current_head"
            );
            self.verified += 1;
        }
    }

    can record_result with ReviewResult entry {
        channel_note = "attestation" if here.review_channel == "EXACT_HEAD_COMMENT_ATTESTATION" else here.review_channel;
        print(
            f"RESULT: PR #{here.pr} {here.reviewed_head} -> {here.verdict} "
            f"via {channel_note}"
        );
        visit [->:Appended:->] else { disengage; };
    }

    can report with ControlTower exit {
        print(f"HeadVerifier: verified={self.verified}, blocked={self.blocked}");
    }
}

