```jac
"""Test annex for JSON Schema external $ref chain collector.

Verifies the property the issue demands: an iterative cross-file traversal
must succeed for an arbitrarily long chain, while a naive recursive
simulator fails by overflowing a bounded call stack.
"""

import io;
import from contextlib { redirect_stdout }

# ---------- helper: build a fresh chain graph of given length ----------
def build_chain(n: int) {
    files = [];
    for i in range(n) {
        typ = "string" if i == n - 1 else "ref";
        files.append(SchemaFile(
            filename=f"f{i}.json",
            schema_type=typ,
            fragment_name="def"
        ));
    }
    for i in range(n - 1) {
        nxt = i + 1;
        files[i] +>:ExternalRef(
            ref_path=f"f{nxt}.json",
            fragment="#/def"
        ):+> files[nxt];
    }
    root +>:ExternalRef(ref_path="f0.json", fragment="#/def"):+> files[0];
    return files;
}

# ---------- helper: run a walker, return captured stdout ----------
def run_walker(w) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn w;
    }
    return (res, buf.getvalue());
}


test "iterative collector visits every file in a long chain" {
    n = 50;
    files = build_chain(n);
    (res, out) = run_walker(RefCollector());
    assert res.files_parsed == n, f"expected {n} files parsed, got {res.files_parsed}";
    assert len(res.collected) == n, f"collected list length {len(res.collected)} != {n}";
    # last file is the leaf (schema_type == "string")
    assert res.collected[-1] == f"f{n - 1}.json", f"tail was {res.collected[-1]}";
    # first file is the head
    assert res.collected[0] == "f0.json", f"head was {res.collected[0]}";
    # all filenames must be present, in order
    expected = [f"f{i}.json" for i in range(n)];
    assert res.collected == expected, f"order mismatch: {res.collected}";
    # and it must NOT have overflowed (this walker has no ceiling)
    assert "[OUT]" not in out, f"unexpected OUT marker: {out}";
}


test "iterative collector handles a 3000-file chain (the issue scenario)" {
    # The original bug report uses N=3000. Keep it; the iterative
    # walker must not depend on JVM/Java call-stack depth.
    n = 3000;
    files = build_chain(n);
    (res, _out) = run_walker(RefCollector());
    assert res.files_parsed == n, f"long-chain parse failed: only {res.files_parsed}/{n}";
    assert res.collected[-1] == f"f{n - 1}.json", "did not reach terminal file";
    assert res.collected[0] == "f0.json", "did not start at head";
    # no overflow field on the iterative walker -> just ensure no exception path
    assert res.files_parsed == len(res.collected), "files_parsed != collected length";
}


test "recursive simulator overflows once the chain exceeds the call-stack ceiling" {
    # ceiling=8: a 10-hop chain must trip the StackOverflowError branch.
    n = 10;
    files = build_chain(n);
    (res, out) = run_walker(RecursiveParser(stack_ceiling=8));
    assert res.overflowed is True, f"recursive walker should have overflowed, flags={res.overflowed}";
    assert res.call_depth > 8, f"depth {res.call_depth} did not exceed ceiling 8";
    assert "StackOverflowError" in out, f"no SOE marker in output: {out}";
    # and it must have stopped BEFORE completing the chain
    assert res.call_depth < n, f"recursive walker walked {res.call_depth} hops of {n} (should bail earlier)";
}


test "chain is well-formed: edges link each file to the next exactly once" {
    n = 12;
    files = build_chain(n);
    # every non-leaf file should have exactly one outgoing ExternalRef
    for i in range(n - 1) {
        outs = [files[i] ->:ExternalRef:->];
        assert len(outs) == 1, f"file {i} has {len(outs)} outgoing refs, want 1";
        nxt = outs[0];
        assert nxt.filename == f"f{i + 1}.json", f"file {i} -> {nxt.filename}";
    }
    # the leaf has no outgoing ExternalRef
    leaf_outs = [files[n - 1] ->:ExternalRef:->];
    assert len(leaf_outs) == 0, f"leaf has {len(leaf_outs)} outgoing refs, want 0";
    # root has exactly one outgoing ExternalRef, pointing at f0
    root_outs = [root ->:ExternalRef:->];
    assert len(root_outs) == 1, f"root has {len(root_outs)} outgoing refs, want 1";
    assert root_outs[0].filename == "f0.json", f"root -> {root_outs[0].filename}";
}


test "iterative collector and recursive simulator disagree on long chains" {
    # The whole point of the issue: iterative must succeed, recursive must fail.
    n = 20;
    files = build_chain(n);

    (iter_res, _i_out) = run_walker(RefCollector());
    (rec_res, _r_out) = run_walker(RecursiveParser(stack_ceiling=8));

    assert iter_res.files_parsed == n, f"iterative only parsed {iter_res.files_parsed}/{n}";
    assert rec_res.overflowed is True, "recursive should have overflowed on n=20, ceiling=8";

    # specifically: the iterative path reaches files the recursive path never can
    assert iter_res.files_parsed > rec_res.call_depth, (
        f"iterative parsed {iter_res.files_parsed} but recursive only reached depth "
        f"{rec_res.call_depth} -- iterative is not actually doing better"
    );
}
