```jac
"""Vorta Research mode: governed investigation with tiered evidence sources.

Models the core scenario from VOR-075 as a typed graph:
investigation -> question -> evidence (tier 1/2/3) and finding -> citation,
with a walker that enforces the source policy and traverses citations.
"""

# ---- Entity archetypes -----------------------------------------------------

node Investigation {
    has title: str = "";
    has question: str = "";
    has status: str = "open";
    has confidence: str = "low";
}

node Question {
    has text: str = "";
    has needs_research: bool = False;
}

node Evidence {
    has tier: int = 0;
    has source_org: str = "";
    has doc_title: str = "";
    has canonical_url: str = "";
    has retrieved_on: str = "";
    has is_authoritative: bool = False;
}

node Finding {
    has summary: str = "";
    has recommendation: str = "";
    has conflicts: str = "";
}

# ---- Edge archetypes (relationships carry meaning) -------------------------

edge RaisedFor {}    # Investigation -> Question
edge Supports {}     # Evidence -> Finding (one piece supports a finding)
edge Conflicts {}   # Evidence -> Finding (one piece conflicts a finding)
edge Cites {}       # Finding -> Evidence (finding cites its evidence)
edge FollowsUp {}   # Question -> Question (later question follows up)

# ---- Walker: enforces source policy and traverses the investigation --------

walker ResearchAuditor {
    can start with Root entry {
        print("Research mode: governed investigation begins");
        visit [-->];
    }

    can open_investigation with Investigation entry {
        print(f"[INVESTIGATION] {here.title}");
        print(f"  status={here.status} confidence={here.confidence}");
        visit [-->];
    }

    # Union ability: one routine handles two question types so the walker
    # doesn't fork per node class — the base field is shared.
    can review_question with Question entry {
        marker = "RESEARCH" if here.needs_research else "OPERATIONAL";
        print(f"  [{marker}] Q: {here.text}");
        visit [-->];
    }

    # Typed-edge traversal over citations to enforce the source hierarchy.
    can audit_evidence with Finding entry {
        print(f"  [FINDING] {here.summary}");
        if here.recommendation != "" {
            print(f"    -> rec: {here.recommendation}");
        }
        visit [->:Cites:->];
    }

    # Source-policy gate. Evidence with is_authoritative=False is denied,
    # and tier must be 1..3 — there is no general-public-web tier.
    can check_evidence with Evidence entry {
        verdict = "ACCEPT";
        if not here.is_authoritative {
            verdict = "DENY (not authoritative)";
        } elif here.tier < 1 or here.tier > 3 {
            verdict = "DENY (tier out of policy)";
        }
        print(
            f"    [{verdict}] T{here.tier} {here.source_org} :: "
            f"{here.doc_title}"
        );
        if here.canonical_url != "" {
            print(f"      url={here.canonical_url}");
        }
        visit [-->];
    }
}

# ---- Demo graph ------------------------------------------------------------

with entry {
    inv = Investigation(
        title="Recurring pump failure root cause",
        question="Why has pump P-204 tripped 3x this month?",
        status="in_progress",
        confidence="medium"
    );
    q1 = Question(
        text="Has P-204 been obsolesced by the OEM?",
        needs_research=True
    );
    q2 = Question(
        text="What is the next scheduled PM?",
        needs_research=False
    );

    # Findings + cited evidence
    f_obsolete = Finding(
        summary="OEM end-of-life notice issued 2024-Q2",
        recommendation="Begin spares optimisation",
        conflicts=""
    );
    f_healthy = Finding(
        summary="Recent vibration trend nominal",
        recommendation="",
        conflicts=""
    );

    # Tier 1: site evidence (authoritative internal record)
    e_t1 = Evidence(
        tier=1,
        source_org="Vorta/site",
        doc_title="SAP work order history P-204",
        canonical_url="sap://site/WO-P204",
        retrieved_on="2025-01-15",
        is_authoritative=True
    );
    # Tier 2: verified OEM
    e_t2 = Evidence(
        tier=2,
        source_org="OEM-AcmePumps",
        doc_title="Service Bulletin SB-2024-07 (EoL notice)",
        canonical_url="https://oem.example/docs/SB-2024-07.pdf",
        retrieved_on="2025-01-15",
        is_authoritative=True
    );
    # Tier 3: standards body
    e_t3 = Evidence(
        tier=3,
        source_org="ISO",
        doc_title="ISO 13373-9 condition monitoring",
        canonical_url="https://iso.example/13373-9",
        retrieved_on="2025-01-15",
        is_authoritative=True
    );
    # Denied: a forum/blog source (not authoritative, no tier)
    e_denied = Evidence(
        tier=0,
        source_org="reddit-maintenance",
        doc_title="Random thread about P-204",
        canonical_url="https://reddit.example/r/maintenance/x",
        retrieved_on="2025-01-15",
        is_authoritative=False
    );

    # Wire the graph with typed edges
    root ++> inv;
    inv +>:RaisedFor:+> q1;
    inv +>:RaisedFor:+> q2;
    q1 +>:FollowsUp:+> q2;

    inv +>:Supports:+> f_obsolete;
    inv +>:Supports:+> f_healthy;

    f_obsolete +>:Cites:+> e_t2;
    f_obsolete +>:Cites:+> e_t1;
    f_healthy +>:Cites:+> e_t3;
    f_healthy +>:Cites:+> e_denied;  # will be denied by policy gate

    # Spawn the governed research walker
    root spawn ResearchAuditor();
}
