"""Regression tests for the deletion-collector cascade hazard.

Models the behavior promised in issue #459:
- The collector must not iterate over insertions made mid-traversal.
- A visited guard closes the double-visit half of the hazard.
- A wide cascade (enough nodes to force rehash mid-iteration) collects
  every target exactly once.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "deletion collector never double-visits" {
    rt = Root();
    a = Model(name="a");
    b = Model(name="b");
    k1 = Model(name="k1");
    rt +>:CascadesTo:+> a;
    rt +>:CascadesTo:+> b;
    a +>:CascadesTo:+> k1;
    # The cross-link is what caused double-visits in the pre-fix Julia code.
    b +>:CascadesTo:+> k1;

    collector = DeletionCollector();
    rt spawn collector;

    # Every model should appear at most once in the processed list.
    names = collector.processed;
    assert len(names) == len(set(names)), f"duplicate visit detected: {names}";

