# ---------------------------------------------------------------------------
test "wide cascade collects every target exactly once" {
    # Builds a fan-out wide enough that any mutating-during-iteration bug
    # would show as either a duplicate or a missing entry. 16 children
    # beneath a single parent crosses Dict rehash thresholds and forces
    # the issue's documented failure path.
    rt = Root();
    parent = Model(name="parent");
    rt +>:CascadesTo:+> parent;

    leaf_names: list = [];
    leaves: list = [];
    for i in range(16) {
        nm = f"leaf_{i}";
        leaf_names.append(nm);
        lf = Model(name=nm);
        leaves.append(lf);
        parent +>:CascadesTo:+> lf;
    }
    # An extra cross-link between two leaves to stress the visited guard.
    leaves[0] +>:CascadesTo:+> leaves[1];

    collector = DeletionCollector();
    rt spawn collector;

    names = collector.processed;
    assert "parent" in names, f"parent missing: {names}";
    for nm in leaf_names {
        assert nm in names, f"{nm} missing from processed list: {names}";
    }
    # No node visited twice.
    for nm in (["parent"] + leaf_names) {
        assert names.count(nm) == 1, f"{nm} visited {names.count(nm)} times: {names}";
    }
    # visit_count on every node is exactly 1.
    assert parent.visit_count == 1, f"parent.visit_count={parent.visit_count}";
    for lf in leaves {
        assert lf.visit_count == 1, f"{lf.name}.visit_count={lf.visit_count}";
    }
}

# ---------------------------------------------------------------------------
test "no late additions leak into the collector's processed list" {
    # In the original bug, items appended to the work list mid-traversal
    # could leak into the iteration set. With the snapshot fix, the
    # walker's `pending` list is drained in order and the visited flag
    # blocks revisits, so a hand-added late edge from an already-processed
    # node must not re-fire collection on its target.
    rt = Root();
    a = Model(name="a");
    b = Model(name="b");
    rt +>:CascadesTo:+> a;
    a +>:CascadesTo:+> b;

    collector = DeletionCollector();
    rt spawn collector;

    initial_len = len(collector.processed);
    initial_names = list(collector.processed);
    assert "a" in initial_names, f"a missing: {initial_names}";
    assert "b" in initial_names, f"b missing: {initial_names}";
    assert b.visit_count == 1, f"b.visit_count={b.visit_count}";

    # If a late edge is now added (simulating mid-traversal mutation),
    # a fresh collector spawned on the SAME graph should still produce a
    # deterministic, no-double-visit result.
    late = Model(name="late");
    a +>:CascadesTo:+> late;

    collector2 = DeletionCollector();
    rt spawn collector2;
    names2 = collector2.processed;
    assert "late" in names2, f"late missing after re-spawn: {names2}";
    assert names2.count("late") == 1, f"late visited {names2.count('late')} times: {names2}";
    assert late.visit_count == 1, f"late.visit_count={late.visit_count}";
    # Old b must still only be visited once.
    assert b.visit_count == 1, f"b.visit_count after re-spawn={b.visit_count}";
}

