"""Regression tests for the diamond dependency-graph auditor."""

import io;
import from contextlib { redirect_stdout }

test "diamond graph audits each shared task exactly once" {
    core = Task(name="core-lib", minutes=30);
    http = Task(name="http-client", minutes=45);
    json = Task(name="json-parser", minutes=25);
    app = Task(name="app", minutes=60);

    root ++> core ++> http ++> app;
    root ++> core ++> json ++> app;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    # Every task reached, but each counted once: 30 + 45 + 25 + 60 = 160.
    assert res.total_minutes == 160, f"got {res.total_minutes}";
    # visited_names length must equal number of unique tasks, not visits.
    assert len(res.visited_names) == 4, f"got {res.visited_names}";
    # core-lib must appear exactly once in the visited list even though it is
    # reachable by two distinct paths in the graph.
    assert res.visited_names.count("core-lib") == 1, f"got {res.visited_names}";
    # Audited flag flipped exactly once per task.
    assert core.audited and http.audited and json.audited and app.audited,
        "every task must be marked audited";
    # A second spawn on the same graph must add nothing — fail-closed dedup.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        res2 = root spawn BuildAuditor();
    }
    assert res2.total_minutes == 0, f"got {res2.total_minutes}";
    assert "skipping core-lib" in buf2.getvalue(), f"missing skip line: {buf2.getvalue()}";
}

test "audit prints skipping line for revisits on the same run" {
    a = Task(name="alpha", minutes=10);
    b = Task(name="beta", minutes=20);
    c = Task(name="gamma", minutes=30);
    # Two roots both funnel into gamma so gamma is hit twice in one walk.
    r1 = root;
    r2 = root;
    r1 ++> a ++> c;
    r2 ++> b ++> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    assert res.total_minutes == 60, f"got {res.total_minutes}";
    assert "skipping gamma" in out, f"expected skip line for gamma, got: {out}";
    assert res.visited_names.count("gamma") == 1, f"got {res.visited_names}";
}

test "linear chain totals correctly with no duplication" {
    n1 = Task(name="step1", minutes=5);
    n2 = Task(name="step2", minutes=7);
    n3 = Task(name="step3", minutes=9);

    root ++> n1 ++> n2 ++> n3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    assert res.total_minutes == 21, f"got {res.total_minutes}";
    assert res.visited_names == ["step1", "step2", "step3"],
        f"got {res.visited_names}";
    # No skip lines on a simple chain — every visit is the first visit.
    assert "skipping" not in out, f"unexpected skip line in linear chain: {out}";
}

test "pre-audited tasks contribute zero and report skip" {
    already = Task(name="cached", minutes=999, audited=True);
    fresh = Task(name="fresh", minutes=12);

    root ++> already;
    root ++> fresh;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    # Cached task is skipped because its audited flag is already True.
    assert res.total_minutes == 12, f"got {res.total_minutes}";
    assert "skipping cached" in out, f"missing skip line: {out}";
    assert "cached" not in res.visited_names, f"got {res.visited_names}";
}

