```jac
"""DSC resource dependency resolver: Kahn-style topological sort walker.

Models the PowerShell `Sort-DependsOn` problem from issue #23. Resource
nodes carry a `depends_on` list (resource names they wait on). A typed
`Requires` edge carries the actual dependency relationship; the walker
performs Kahn's algorithm over the typed edges, emitting a topological
order, and reports a cycle by naming the unresolvable resources.
"""

node Resource {
    has name: str = "";
    has depends_on: list[str] = [];
}

edge Requires { }

walker DependencyResolver {
    has order: list[str] = [];
    has remaining: list[Resource] = [];
    has known_names: list[str] = [];
    has cycle_members: list[str] = [];

    def validate_references -> None {
        for r in self.remaining {
            missing = [n for n in r.depends_on if n not in self.known_names];
            if missing {
                missing_str = ", ".join(missing);
                print(
                    f"ERROR: Resource {r.name} depends on unknown resource(s): {missing_str}"
                );
            }
        }
    }

    def process_round -> None {
        next_remaining: list[Resource] = [];
        for r in self.remaining {
            pending = [n for n in r.depends_on if n not in self.order];
            if pending {
                next_remaining.append(r);
            } else {
                self.order.append(r.name);
            }
        }
        self.remaining = next_remaining;
    }

    def topological_order -> list[str] {
        round_idx = 0;
        while self.remaining {
            round_idx += 1;
            before = len(self.order);
            self.process_round();
            if len(self.order) == before {
                self.cycle_members = [r.name for r in self.remaining];
                break;
            }
        }
        return self.order;
    }

    can start with Root entry {
        self.known_names = [r.name for r in self.remaining];
        self.validate_references();
        self.topological_order();
        if self.cycle_members {
            cycle_str = ", ".join(self.cycle_members);
            print(f"ERROR: Dependency cycle among resources: {cycle_str}");
        } else {
            print(f"topo order: {self.order}");
        }
        visit [->:Requires:->] else { disengage; }
    }

    can resolve with Resource entry {
        visit [->:Requires:->] else { disengage; }
    }
}

with entry {
    print("=== linear chain ===");
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    d = Resource(name="D", depends_on=["C"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> d;
    root spawn DependencyResolver(remaining=[a, b, c, d]);

    print("\n=== diamond ===");
    a2 = Resource(name="A");
    b2 = Resource(name="B", depends_on=["A"]);
    c2 = Resource(name="C", depends_on=["A"]);
    d2 = Resource(name="D", depends_on=["B", "C"]);
    a2 +>:Requires:+> b2;
    a2 +>:Requires:+> c2;
    b2 +>:Requires:+> d2;
    c2 +>:Requires:+> d2;
    root spawn DependencyResolver(remaining=[a2, b2, c2, d2]);

    print("\n=== wide fan-in ===");
    leaves = [Resource(name=f"L{i}") for i in range(5)];
    mid = Resource(name="Mid", depends_on=["L0", "L1", "L2", "L3", "L4"]);
    sink = Resource(name="Sink", depends_on=["Mid"]);
    for leaf in leaves {
        leaf +>:Requires:+> mid;
    }
    mid +>:Requires:+> sink;
    root spawn DependencyResolver(remaining=leaves + [mid, sink]);

    print("\n=== cycle ===");
    a3 = Resource(name="A", depends_on=["C"]);
    b3 = Resource(name="B", depends_on=["A"]);
    c3 = Resource(name="C", depends_on=["B"]);
    a3 +>:Requires:+> b3;
    b3 +>:Requires:+> c3;
    c3 +>:Requires:+> a3;
    root spawn DependencyResolver(remaining=[a3, b3, c3]);

    print("\n=== missing reference ===");
    a4 = Resource(name="A");
    b4 = Resource(name="B", depends_on=["Ghost"]);
    a4 +>:Requires:+> b4;
    root spawn DependencyResolver(remaining=[a4, b4]);
}
```

"""Test annex for the DSC resource dependency resolver (issue #23).

Verifies the Kahn-style topological sort walker over a typed Requires edge
graph: linear chain ordering, diamond ordering, fan-in ordering, cycle
detection (with cycle members named), and missing-reference detection.
"""
import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------

def build_chain() -> tuple {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    d = Resource(name="D", depends_on=["C"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> d;
    return (a, b, c, d);
}

def build_diamond() -> tuple {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["A"]);
    d = Resource(name="D", depends_on=["B", "C"]);
    a +>:Requires:+> b;
    a +>:Requires:+> c;
    b +>:Requires:+> d;
    c +>:Requires:+> d;
    return (a, b, c, d);
}

def build_fan_in() -> list {
    leaves = [Resource(name=f"L{i}") for i in range(5)];
    mid = Resource(name="Mid", depends_on=["L0", "L1", "L2", "L3", "L4"]);
    sink = Resource(name="Sink", depends_on=["Mid"]);
    for leaf in leaves {
        leaf +>:Requires:+> mid;
    }
    mid +>:Requires:+> sink;
    return leaves + [mid, sink];
}

def build_cycle() -> tuple {
    a = Resource(name="A", depends_on=["C"]);
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> a;
    return (a, b, c);
}

def build_missing() -> tuple {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["Ghost"]);
    a +>:Requires:+> b;
    return (a, b);
}

# ---------- tests ----------

test "linear chain emits topological order A B C D" {
    (a, b, c, d) = build_chain();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b, c, d]);
    }
    out = buf.getvalue();
    assert "topo order:" in out, f"expected success line, got: {out}";
    assert "ERROR" not in out, f"unexpected error in linear chain: {out}";
    assert res.order == ["A", "B", "C", "D"], f"got order {res.order}";
    assert res.cycle_members == [], f"got cycle_members {res.cycle_members}";
    assert res.known_names == ["A", "B", "C", "D"], f"got known {res.known_names}";
}

test "diamond: A before B and C, both before D" {
    (a, b, c, d) = build_diamond();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b, c, d]);
    }
    out = buf.getvalue();
    assert "topo order:" in out, f"expected success line, got: {out}";
    assert "ERROR" not in out, f"unexpected error in diamond: {out}";
    o = res.order;
    assert len(o) == 4, f"expected 4 resources ordered, got {o}";
    assert o[0] == "A", f"A must be first, got {o[0]}";
    assert o[-1] == "D", f"D must be last, got {o[-1]}";
    assert "B" in o and "C" in o, f"B and C missing from {o}";
    a_idx = o.index("A");
    b_idx = o.index("B");
    c_idx = o.index("C");
    d_idx = o.index("D");
    assert a_idx < b_idx, f"A must precede B: {o}";
    assert a_idx < c_idx, f"A must precede C: {o}";
    assert b_idx < d_idx, f"B must precede D: {o}";
    assert c_idx < d_idx, f"C must precede D: {o}";
    assert res.cycle_members == [], f"got cycle_members {res.cycle_members}";
}

test "wide fan-in: all leaves before Mid, Mid before Sink" {
    nodes = build_fan_in();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=nodes);
    }
    out = buf.getvalue();
    assert "topo order:" in out, f"expected success line, got: {out}";
    assert "ERROR" not in out, f"unexpected error in fan-in: {out}";
    o = res.order;
    assert len(o) == 7, f"expected 7 ordered, got {o}";
    mid_idx = o.index("Mid");
    sink_idx = o.index("Sink");
    for i in range(5) {
        leaf_name = f"L{i}";
        assert leaf_name in o, f"leaf {leaf_name} missing from {o}";
        assert o.index(leaf_name) < mid_idx, f"{leaf_name} must precede Mid: {o}";
    }
    assert mid_idx < sink_idx, f"Mid must precede Sink: {o}";
    assert res.cycle_members == [], f"got cycle_members {res.cycle_members}";
}

test "cycle: names the resources caught in the loop" {
    (a, b, c) = build_cycle();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b, c]);
    }
    out = buf.getvalue();
    assert "ERROR: Dependency cycle" in out, f"expected cycle error, got: {out}";
    assert "topo order:" not in out, f"unexpected success line in cycle case: {out}";
    assert len(res.cycle_members) == 3, f"expected 3 cycle members, got {res.cycle_members}";
    assert "A" in res.cycle_members, f"A missing from cycle members {res.cycle_members}";
    assert "B" in res.cycle_members, f"B missing from cycle members {res.cycle_members}";
    assert "C" in res.cycle_members, f"C missing from cycle members {res.cycle_members}";
    assert len(res.order) < 3, f"cycle case should not fully resolve, got {res.order}";
}

test "missing reference: names the unknown dependency" {
    (a, b) = build_missing();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b]);
    }
    out = buf.getvalue();
    assert "unknown resource" in out, f"expected missing-ref error, got: {out}";
    assert "Ghost" in out, f"unknown name 'Ghost' not reported: {out}";
    assert "B" in out, f"dependent resource 'B' not named: {out}";
}

