```jac
"""Order auditor walker demonstrating both early-return flavors.

`skip` skips a single order and continues the audit to later orders;
`disengage` halts the whole walk the moment a fraud-flagged order
appears. Both behaviors are exercised on the same chain so the
difference is observable in the printed trace.
"""

node Order {
    has label: str = "";
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Audit begins");
        visit [-->];
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALT";
        } elif not here.valid {
            action = "SKIP";
        } else {
            action = "OK";
        }
        print(f"[{action}] {here.label} amount={here.amount}");
        if here.fraud {
            disengage;
        }
        if not here.valid {
            # skip just this order; keep walking the rest of the chain
            visit [-->] else { disengage; }
        }
        visit [-->];
    }
}

with entry {
    root ++> Order(label="O-001", amount=120, valid=True)
        ++> Order(label="O-002", amount=80, valid=False)
        ++> Order(label="O-003", amount=250, valid=True)
        ++> Order(label="O-004", amount=999, valid=True, fraud=True)
        ++> Order(label="O-005", amount=60, valid=True);
    root spawn OrderAuditor();
}
