```jac
"""HAVE_* contract: declare the supported surface, drop the dead flags, audit both directions.

Models the dotgibson/dotfiles-core scenario: 43 globals exported, 9 with no consumer,
5 genuinely depended on downstream, none documented. The walker below performs the
'both-directions' audit the issue proposes.
"""

# --- Entity archetypes ---

node Tool {
    has name: str = "";
    has binary_present: bool = False;
    has documented: bool = False;
    has downstream_consumers: int = 0;
}

node Flag {
    has name: str = "";
    has supported: bool = False;
}

# --- Relationships (typed edges) ---

edge DeclaredIn {
    has as_of: str = "v5.0.0";
}

edge ConsumedBy {
    has consumer: str = "";
}

# --- Auditors ---

walker SupportAudit {
    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Tool entry {
        # Rule 1: a flag with zero downstream consumers and no documentation
        # is dead weight. Rule 2: a flag with consumers must be declared.
        if here.downstream_consumers == 0 and not here.documented {
            self.violations.append(
                f"DEAD: {here.name} has no consumers and no docs"
            );
        }
        if here.downstream_consumers > 0 and not here.documented {
            self.violations.append(
                f"UNDECLARED: {here.name} has {here.downstream_consumers} "
                f"consumer(s) but is not in PORTABILITY.md"
            );
        }
        visit [-->];
    }

    can scan_flag with Flag entry {
        visit [-->];
    }
}

walker ContractSurface {
    has declared: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Flag entry {
        if here.supported {
            self.declared.append(here.name);
        }
        visit [-->];
    }
}

# --- Demo graph ---

with entry {
    # Three categories of flags from the issue:
    # (A) dead flags: many consumers in grep, zero downstream
    # (B) live flags: consumed by OS/role layers, must be declared
    # (C) declared supported surface in PORTABILITY.md

    # Dead group (9 in the issue; we model 3 representative ones).
    delta = Tool(name="HAVE_DELTA", binary_present=True, documented=False, downstream_consumers=0);
    direnv = Tool(name="HAVE_DIRENV", binary_present=True, documented=False, downstream_consumers=0);
    mise = Tool(name="HAVE_MISE", binary_present=True, documented=False, downstream_consumers=0);

    # Live group (5 in the issue; modeled in full).
    astgrep = Tool(name="HAVE_ASTGREP", binary_present=True, documented=False, downstream_consumers=2);
    atuin = Tool(name="HAVE_ATUIN", binary_present=True, documented=False, downstream_consumers=3);
    jnv = Tool(name="HAVE_JNV", binary_present=True, documented=False, downstream_consumers=1);
    jq = Tool(name="HAVE_JQ", binary_present=True, documented=False, downstream_consumers=5);
    shellcheck = Tool(name="HAVE_SHELLCHECK", binary_present=True, documented=False, downstream_consumers=2);

    # The declared surface — only jq and shellcheck survive the narrowing
    # proposed in the issue's "decision worth making explicitly" section.
    f_jq = Flag(name="HAVE_JQ", supported=True);
    f_shellcheck = Flag(name="HAVE_SHELLCHECK", supported=True);

    # Wire the graph. Tools hang off root; declared flags hang off root too.
    # Each live tool connects to the flag(s) that back it via a ConsumedBy edge
    # whose payload names the OS-repo consumer (the "both-directions" audit).
    root ++> delta ++> direnv ++> mise;
    root ++> astgrep ++> atuin ++> jnv ++> jq ++> shellcheck;
    root ++> f_jq ++> f_shellcheck;

    jq +>:ConsumedBy(consumer="os-mint"):+> f_jq;
    jq +>:ConsumedBy(consumer="role-sre"):+> f_jq;
    atuin +>:ConsumedBy(consumer="os-mint"):+> f_jq;  # NOT declared — should fail
    shellcheck +>:ConsumedBy(consumer="role-review"):+> f_shellcheck;

    # Attach a DeclaredIn edge from root to each supported flag with the
    # PORTABILITY.md version marker (semantics of "the contract exists").
    root +>:DeclaredIn(as_of="v5.0.0"):+> f_jq;
    root +>:DeclaredIn(as_of="v5.0.0"):+> f_shellcheck;

    # Run the audit.
    auditor = SupportAudit();
    root spawn auditor;
    print("--- audit violations ---");
    for v in auditor.violations {
        print(v);
    }
    print(f"total: {len(auditor.violations)}");

    # Run the contract-surface collector to show the declared set.
    surface = ContractSurface();
    root spawn surface;
    print("--- declared surface ---");
    for d in surface.declared {
        print(d);
    }
}
