```jac
"""LOD-coverage & terrain-seam diagnostics: gate recomputes on residency epoch.

Models the issue: `reconcile_lod_rings` used to call `update_lod_coverage`
and `update_terrain_seam_stats` unconditionally every frame, including frames
where the resident key set did not change. The fix bumps a residency-epoch
counter on every residency mutation and skips the expensive O(n^2) overlap
scans when the epoch is unchanged since the last sample.

Entities (nodes):
  - TerrainBlock: a streamed terrain LOD cell (key, lod_level)
  - ObjectBlock:  a streamed object LOD block
  - FullCell:     a fully-loaded (highest-detail) cell, used to compute coverage
  - Landscape:    an immutable landscape data set that adjacent terrain pairs
                  are compared against for seam integrity

Relationships (typed edges):
  - ResidentIn:  a block lives in the world's residency set
  - AdjacentTo:  two terrain blocks are spatially adjacent (seam candidates)
  - HasFull:     a full-detail cell exists for a given key (coverage witness)

Walkers:
  - ReconcileFrame: walks the world every frame, runs coverage + seam
                   diagnostics but only recomputes when the residency epoch
                   has advanced since the last sample.
  - ResidencyChange: bumps the epoch when streamed inserts/removes happen,
                     simulating `stream_lod_blocks` / `stream_object_lod_blocks`
                     and the `state.loaded` insert/remove sites.
  - CoverageAuditor: an explicit O(n^2) all-pairs scan, gated by the epoch
                     skip — the expensive diagnostic that the issue targets.
  - SeamAuditor: a per-pair seam verdict walker, also gated by the epoch.

The expensive work is hoisted behind the epoch gate, mirroring the
suggested fix in the issue.
"""

# A residency-epoch tracker node carries the worldspace's current epoch
# counter. The ReconcileFrame walker reads it; ResidencyChange mutates it.
node ResidencyEpoch {
    has epoch: int = 0;
}

node TerrainBlock {
    has key: str = "";
    has lod_level: int = 0;
    has available: bool = True;
}

node ObjectBlock {
    has key: str = "";
    has lod_level: int = 0;
    has available: bool = True;
}

node FullCell {
    has key: str = "";
    has lod_level: int = 0;
}

node Landscape {
    has immutable: bool = True;
    has name: str = "";
}

edge ResidentIn {
    has since: str = "";
}

edge AdjacentTo {
    has seam_label: str = "";
}

edge HasFull {
    has at_level: int = 0;
}

walker ResidencyChange {
    has site: str = "";

    can start with Root entry {
        visit [->:ResidentIn:->];
    }

    can bump with ResidencyEpoch entry {
        here.epoch += 1;
        print(f"[residency] bump epoch -> {here.epoch} via {self.site}");
        visit [->:ResidentIn:->];
    }
}

walker ReconcileFrame {
    has frame: int = 0;
    has last_residency_epoch: int = -1;
    has last_coverage: str = "unset";
    has last_seam: str = "unset";
    has recomputed: bool = False;

    can start with Root entry {
        # Step into the world's residency-epoch tracker first.
        visit [->:ResidentIn:->];
    }

    can gate with ResidencyEpoch entry {
        current_epoch = here.epoch;
        if current_epoch != self.last_residency_epoch {
            print(f"[frame {self.frame}] residency epoch advanced "
                  f"({self.last_residency_epoch} -> {current_epoch}): "
                  f"recomputing coverage + seam");
            self.last_residency_epoch = current_epoch;
            self.last_coverage = "computed";
            self.last_seam = "computed";
            self.recomputed = True;
            visit [-->];
        } else {
            print(f"[frame {self.frame}] epoch unchanged "
                  f"({current_epoch}): SKIP coverage + seam recompute");
            self.last_coverage = "unchanged";
            self.last_seam = "unchanged";
            self.recomputed = False;
            disengage;
        }
    }
}

walker CoverageAuditor {
    has pairs_scanned: int = 0;

    can start with Root entry {
        print(f"[coverage] running find_overlaps (all-pairs)");
        visit [-->];
    }

    can scan with TerrainBlock entry {
        # Count every typed AdjacentTo edge as a candidate overlap pair.
        n_adjacent = [-->];
        self.pairs_scanned += len(n_adjacent);
        visit [-->];
    }
}

walker SeamAuditor {
    has pairs_checked: int = 0;
    has verdicts: list[str] = [];

    can start with Root entry {
        print(f"[seam] running check_seam per adjacent pair");
        visit [-->];
    }

    can inspect with Landscape entry {
        # The landscape is immutable for the worldspace's lifetime,
        # so verdicts are stable until the resident set changes.
        verdict = "OK";
        self.verdicts.append(verdict);
        visit [->:AdjacentTo:->];
    }

    can compare with TerrainBlock entry {
        self.pairs_checked += 1;
        seam_state = "seam-clean" if here.available else "seam-broken";
        self.verdicts.append(seam_state);
        visit [-->];
    }
}

with entry {
    # Build the streamed world.
    epoch_node = ResidencyEpoch(epoch=0);
    landscape = Landscape(immutable=True, name="world");
    root +>:ResidentIn(since="init"):+> epoch_node;
    root +>:ResidentIn(since="init"):+> landscape;

    # Three terrain blocks at decreasing LOD, two object blocks.
    t1 = TerrainBlock(key="T(0,0,4)", lod_level=4);
    t2 = TerrainBlock(key="T(1,0,8)", lod_level=8);
    t3 = TerrainBlock(key="T(0,1,16)", lod_level=16, available=False);
    o1 = ObjectBlock(key="O(0,0,16)", lod_level=16);
    o2 = ObjectBlock(key="O(1,1,32)", lod_level=32);

    landscape +>:AdjacentTo(seam_label="T0-T1"):+> t1;
    landscape +>:AdjacentTo(seam_label="T0-T2"):+> t2;
    landscape +>:AdjacentTo(seam_label="T1-T2"):+> t3;
    landscape +>:ResidentIn(since="frame=0"):+> o1;
    landscape +>:ResidentIn(since="frame=0"):+> o2;

    # A full-detail cell witness for one terrain block.
    t1 +>:HasFull(at_level=32):+> FullCell(key="T(0,0,32)", lod_level=32);

    # Frame 0: epoch = 0 (initial). Coverage + seam should be recomputed.
    print("--- frame 0 (initial residency, epoch=0) ---");
    f0 = ReconcileFrame(frame=0, last_residency_epoch=-1);
    f0 spawn root;
    if f0.recomputed {
        CoverageAuditor() spawn root;
        SeamAuditor() spawn root;
    }

    # Frame 1: no residency mutation. Epoch unchanged -> SKIP the work.
    print("--- frame 1 (no residency change, epoch still 0) ---");
    f1 = ReconcileFrame(frame=1, last_residency_epoch=f0.last_residency_epoch);
    f1 spawn root;

    # Simulate `stream_lod_blocks` insert: bump epoch.
    print("--- residency mutation: insert t3 ---");
    bump = ResidencyChange(site="stream_lod_blocks/insert");
    bump spawn root;

    # Frame 2: epoch advanced -> recompute.
    print("--- frame 2 (epoch advanced -> recompute) ---");
    f2 = ReconcileFrame(frame=2, last_residency_epoch=f1.last_residency_epoch);
    f2 spawn root;
    if f2.recomputed {
        CoverageAuditor() spawn root;
        SeamAuditor() spawn root;
    }

    # Summary of what was avoided.
    print("---");
    print(f"f1 (no-change frame) skipped: coverage={f1.last_coverage}, "
          f"seam={f1.last_seam}");
    print(f"f2 (changed frame) recomputed: coverage={f2.last_coverage}, "
          f"seam={f2.last_seam}");
    print(f"final residency epoch = {epoch_node.epoch}");
}
```

