```jac
"""Hiking trail: a chain of waypoints between trailhead and summit.

The waypoints themselves are pure graph nodes — no domain data needed.
A hiker walker traverses the chain, printing each stop number and
finishing with a completion line once it has passed enough waypoints.
"""

node Waypoint;

walker Hiker {
    has goal: int = 5;
    has count: int = 0;
    has done: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can hike with Waypoint entry {
        self.count += 1;
        print(f"Stop #{self.count}");
        if self.count >= self.goal {
            self.done = True;
            print(f"Completed trail after {self.count} stops");
            disengage;
        }
        visit [-->] else {
            if not self.done {
                print(f"Completed trail after {self.count} stops");
            }
            disengage;
        }
    }
}

with entry {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();
    root spawn Hiker(goal=5);
}
