test "hiker prints each stop and finishes exactly at goal" {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing first stop: {out}";
    assert "Stop #2" in out, f"missing second stop: {out}";
    assert "Stop #3" in out, f"missing third stop: {out}";
    assert "Stop #4" in out, f"missing fourth stop: {out}";
    assert "Stop #5" in out, f"missing fifth stop: {out}";
    assert "Completed trail after 5 stops" in out, f"missing completion: {out}";

    # Stop numbers appear in order, one per line
    lines = [l for l in out.splitlines() if l.startswith("Stop #")];
    assert len(lines) == 5, f"expected 5 stop lines, got {len(lines)}: {lines}";
    assert lines[0] == "Stop #1", f"first line wrong: {lines[0]}";
    assert lines[4] == "Stop #5", f"fifth line wrong: {lines[4]}";

    # Walker records the final state
    assert res.count == 5, f"expected count=5, got {res.count}";
    assert res.done is True, f"expected done=True, got {res.done}";
}

test "hiker disengages when chain runs out before goal" {
    # Only 2 waypoints, goal defaults to 5 → must finish via the `else` branch
    root ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing Stop #1: {out}";
    assert "Stop #2" in out, f"missing Stop #2: {out}";
    assert "Stop #3" not in out, f"should not have visited a third stop: {out}";
    assert "Completed trail after 2 stops" in out, f"missing completion: {out}";

    # No spurious extra completion line
    completions = [l for l in out.splitlines() if l.startswith("Completed")];
    assert len(completions) == 1, f"expected 1 completion line, got {len(completions)}: {completions}";

    assert res.count == 2, f"expected count=2, got {res.count}";
    assert res.done is False, f"expected done=False (goal not reached), got {res.done}";
}

test "custom goal counts only up to the threshold" {
