    with redirect_stdout(buf) {
        root spawn sp;
    }
    assert sp.rejected, f"expected rejected, got rejected={sp.rejected}";
    assert "self" in sp.reject_reason.lower() or "cycle" in sp.reject_reason.lower(), f"reason={sp.reject_reason}";
