    h = Tag(name="homelab", tag_id=1, parent_id=2);
    sh = Tag(name="self-hosted", tag_id=3, parent_id=1);
    root ++> z;
    z +>:ParentOf:+> h;
    h +>:ParentOf:+> sh;

