test "SetParent refuses the exact move MergeTags performs (asymmetry)" {
    p = Tag(name="parent", tag_id=5, parent_id=-1);
    ch = Tag(name="child", tag_id=6, parent_id=5);
    root ++> p;
    p +>:ParentOf:+> ch;

    buf = io.StringIO();
    sp = SetParent(target_id=6, new_parent_id=6);
    with redirect_stdout(buf) {
        root spawn sp;
    }
    assert sp.rejected, f"SetParent should reject self-cycle, got rejected={sp.rejected}";
    assert ch.parent_id == 5, f"SetParent should not have mutated parent_id, got {ch.parent_id}";

    mt = MergeTags(source_id=5, target_id=6);
    with redirect_stdout(buf) {
        root spawn mt;
    }
    assert ch.parent_id == ch.tag_id, f"MergeTags should have created self-cycle, got parent_id={ch.parent_id}";

    audit = CycleAudit();
    with redirect_stdout(buf) {
        root spawn audit;
    }
    assert "child" in audit.violations, f"asymmetry: set_parent guarded but merge unguarded, violations={audit.violations}";
