"""Kizuki control-plane demo: revoke a source and invalidate its derived knowledge."""

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revoked: bool = False;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_note: str = "";
}

node WorkingModel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has rebuild_required: bool = False;
}

node Canon {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner_approved: bool = False;
}

edge Contains { }
edge Produces {
    has channel: str = "";
}
edge FeedsWorking {
    has relation: str = "";
}
edge PublishesCanon {
    has owner_gate: bool = False;
}
edge ReferencesSource { }

walker InvalidationAudit {
    has depth: int = 0;
    has max_depth: int = 5;
    has source_revoked: bool = False;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_source with Source entry {
        if self.depth >= self.max_depth {
            print(f"cycle/depth guard stopped at source: {here.title}");
            disengage;
        } else {
            self.source_revoked = here.revoked;
            print(f"source: {here.title}, revoked={here.revoked}");
            self.depth += 1;
            visit [->:Produces:->] else {
                disengage;
            }
        }
    }

    can inspect_evidence with Evidence entry {
        if self.source_revoked {
            here.available = False;
        }
        print(f"evidence: {here.title}, available={here.available}");
        self.depth += 1;
        visit [->:FeedsWorking:->] else {
            disengage;
        }
    }

    can inspect_working with WorkingModel entry {
        if self.source_revoked {
            here.available = False;
            here.rebuild_required = True;
        }
        print(f"working model: {here.title}, rebuild={here.rebuild_required}");
        self.depth += 1;
        visit [->:PublishesCanon:->] else {
            disengage;
        }
    }

    can inspect_canon with Canon entry {
        if self.source_revoked {
            here.available = False;
            here.owner_approved = False;
        }
        print(f"canon: {here.title}, available={here.available}, "
              f"approved={here.owner_approved}");
        self.depth += 1;
        visit [->:ReferencesSource:->] else {
            disengage;
        }
    }
}

with entry {
    source = Source(
        title="local journal export",
        year=2026,
        revoked=True
    );
    evidence = Evidence(
        title="meeting evidence",
        year=2026,
        source_note="journal export"
    );
    working = WorkingModel(
        title="reversible working model",
        year=2026
    );
    canon = Canon(
        title="owner-approved canon",
        year=2026,
        owner_approved=True
    );

    root +>:Contains:+> source;
