"""Mortgage FX Impact Analysis: USD vs AED for Non-Resident Buyers.

Models the core scenario from issue #1337 — a non-resident buyer takes a
mortgage, and we need to traverse the FX exposure chain (loan → currency
→ conversion path) to assess impact. Hand-rolled recursion over parent
currency references is replaced with a typed-edge walker that walks the
currency graph, accumulating the effective AED exposure and flagging any
cycles that would make the conversion ambiguous.
"""

node Currency {
    has code: str = "";
    has rate_to_aed: float = 1.0;
    has name: str = "";
}

node Mortgage {
    has title: str = "";
    has principal: float = 0.0;
    has buyer_residency: str = "non-resident";
    has available: bool = True;
}

node Buyer {
    has title: str = "";
    has residency: str = "non-resident";
    has annual_income_usd: float = 0.0;
}

edge DenominatedIn {
    has since: str = "2024-01";
}

edge Bridges {
    has spread_bps: float = 0.0;
}

walker FxImpactAnalyst {
    has visited: list[str] = [];
    has total_aed_exposure: float = 0.0;
    has cycle_detected: bool = False;
    has residency: str = "non-resident";

    can start with Root entry {
        visit [-->];
    }

    can pick_mortgage with Mortgage entry {
        if here.buyer_residency != self.residency {
            print(f"Skipping {here.title}: residency mismatch");
            visit [-->];
        }
        print(f"Analyzing mortgage: {here.title} (principal={here.principal})");
        visit [-->];
    }

    can pick_buyer with Buyer entry {
        if here.residency != self.residency {
            print(f"Skipping buyer {here.title}: not a {self.residency}");
            visit [-->];
        }
        visit [-->];
    }

    can walk_currency with Currency entry {
        code = here.code;
        if code in self.visited {
            self.cycle_detected = True;
            print(f"[CYCLE] revisiting {code} — ambiguous conversion path");
            disengage;
        }
        self.visited.append(code);
        contribution = here.rate_to_aed;
        self.total_aed_exposure = self.total_aed_exposure + contribution;
        print(f"  currency {code} (rate_to_aed={here.rate_to_aed}) contributes {contribution}");
        visit [->:Bridges:->];
    }
}

