"""Delivery route dispatch checker: walk each depot and print which routes qualify."""

node Route {
    has origin: str = "";
    has destination: str = "";
    has cargo_weight: float = 0.0;
}

node Depot {
    has name: str = "";
}

walker Dispatcher {
    has min_load: float = 2.0;
    has max_load: float = 8.0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Depot entry {
        print(f"Depot: {here.name}");
        visit [-->];
    }

    can inspect with Route entry {
        qualifies = here.cargo_weight >= self.min_load
                    and here.cargo_weight <= self.max_load;
        status = "QUALIFIES" if qualifies else "REJECTED";
        print(f"  [{status}] {here.origin} -> {here.destination}: {here.cargo_weight}t");
        visit [-->];
    }
}

with entry {
    north = Depot(name="North");
    south = Depot(name="South");

    north ++> Route(origin="North", destination="East", cargo_weight=3.5)
        ++> Route(origin="North", destination="West", cargo_weight=7.0)
        ++> Route(origin="North", destination="South", cargo_weight=1.0);

    south ++> Route(origin="South", destination="East", cargo_weight=8.0)
        ++> Route(origin="South", destination="West", cargo_weight=9.5)
        ++> Route(origin="South", destination="North", cargo_weight=5.5);

    root ++> north ++> south;

    root spawn Dispatcher();
}
