"""Dependency-aware watch mode demo for lwpt build/test.

Models the core scenario: Pascal units, tests, build entries, and a
manifest with their typed dependency relationships. A Watcher walker
performs a content-style cycle over the graph, marks affected scope,
and falls back to the full selected set when impact is uncertain.
"""

# ----- Entity archetypes ----------------------------------------------------

node PascalUnit {
    has name: str = "";
    has source: str = "";
    has last_seen: int = 0;
}

node UnitTest {
    has name: str = "";
    has selector: str = "";
    has last_seen: int = 0;
    has passed: bool = True;
}

node BuildEntry {
    has name: str = "";
    has last_seen: int = 0;
}

node Manifest {
    has version: str = "1.0";
    has last_seen: int = 0;
}

# ----- Typed relationships --------------------------------------------------

edge DependsOn { has weight: int = 1; }
edge Tests { }
edge Selects { }

# ----- Watcher walker -------------------------------------------------------

walker Watcher {
    has tick: int = 1;
    has changed: str = "";
    has rebuild: list = [];
    has retest: list = [];
    has rerun_all: bool = False;

    can begin with Root entry {
        print(f"--- watch cycle {self.tick} (initial full run) ---");
        self.rerun_all = True;
        visit [-->];
    }

    can survey with Manifest entry {
        # A manifest change always escalates to full scope (fail-open).
        self.rerun_all = True;
        if here.last_seen < self.tick {
            here.last_seen = self.tick;
        }
        visit [-->];
    }

    can survey_entry with BuildEntry entry {
        # A build-entry change always escalates to full scope.
        self.rerun_all = True;
        if here.last_seen < self.tick {
            here.last_seen = self.tick;
        }
        visit [-->];
    }

    can decide with PascalUnit entry {
        # Cycle guard: jac 0.36 has no built-in visited set.
        if here.last_seen >= self.tick {
            visit [-->];
        }
        here.last_seen = self.tick;
        if self.changed == here.name {
            self.rebuild.append(here.name);
            # Propagate to downstream build entries that depend on it.
            for d in [-->](?:BuildEntry) {
                self.rebuild.append(d.name);
            }
        }
        visit [-->];
    }

    can test_decide with UnitTest entry {
        if here.last_seen >= self.tick {
            visit [-->];
        }
        here.last_seen = self.tick;
        if self.changed == here.name {
            self.retest.append(here.name);
        }
        visit [-->];
    }
}

# ----- Demonstration --------------------------------------------------------

with entry {
    # Manifest + two build entries.
    manifest = Manifest(version="1.0", last_seen=1);
    be_app = BuildEntry(name="app", last_seen=1);
    be_lib = BuildEntry(name="lib", last_seen=1);
    root ++> manifest ++> be_app ++> be_lib;

    # Pascal units with dependencies: math -> utils, app depends on math.
    math_u = PascalUnit(name="math", source="u math", last_seen=1);
    utils_u = PascalUnit(name="utils", source="u utils", last_seen=1);
    app_u = PascalUnit(name="app", source="u app", last_seen=1);
    math_u +>:DependsOn:+> utils_u;
    app_u +>:DependsOn:+> math_u;
    be_lib +>:DependsOn:+> utils_u;
    be_app +>:DependsOn:+> app_u;

    # Tests selecting units (selector-driven eligibility).
    t_math = UnitTest(name="t_math", selector="math", last_seen=1);
    t_app = UnitTest(name="t_app", selector="app", last_seen=1);
    t_utils = UnitTest(name="t_utils", selector="utils", last_seen=1);
    t_math +>:Tests:+> math_u;
    t_app +>:Tests:+> app_u;
    t_utils +>:Tests:+> utils_u;
    root ++> t_math ++> t_app ++> t_utils;

    # ----- Initial full cycle -----
    w0 = Watcher(tick=1, changed="");
    root spawn w0;
    print(f"cycle 1 (initial): rebuild={w0.rebuild} retest={w0.retest} "
          f"rerun_all={w0.rerun_all}");

    # ----- Cycle 2: a single Pascal unit changed -> selective rebuild -----
    w1 = Watcher(tick=2, changed="utils");
    root spawn w1;
    print(f"cycle 2 (utils changed): rebuild={w1.rebuild} "
          f"retest={w1.retest} rerun_all={w1.rerun_all}");

    # ----- Cycle 3: manifest change -> fail-open to full scope -----
    manifest.last_seen = 2;
    w2 = Watcher(tick=3, changed="anything");
    root spawn w2;
    print(f"cycle 3 (manifest change): rebuild={w2.rebuild} "
          f"retest={w2.retest} rerun_all={w2.rerun_all}");
}
