```jac
"""Critical-path causality demo: parallel branches and loop retries in a workflow DAG.

Models two competing evidence sources for the critical path:
  - Timing edges: inferred from observed node completion order.
  - Structural edges: inferred from n8n workflow connections.
A `CriticalPath` walker traverses both, marking the dependency
edges it considers trustworthy and reporting the longest weighted
path that survives the cycle-safe topological walk.
"""

# ---------- Edge archetypes ----------
edge TimingDep {
    has weight: float = 1.0;
    has observed: bool = True;
}

edge StructuralDep {
    has weight: float = 1.0;
    has parallel_group: str = "";
}

edge Branch {
    has name: str = "";
}

# ---------- Node archetypes ----------
node Workflow {
    has name: str = "signalflow";
}

node TaskNode {
    has label: str = "";
    has duration: float = 1.0;
    has is_retry: bool = False;
    has invalidated: bool = False;
}

node RetryBranch {
    has label: str = "";
    has attempt: int = 0;
}

# ---------- Walkers ----------
walker CriticalPath {
    has path: list[str] = [];
    has path_weight: float = 0.0;
    has visited: list[str] = [];

    can start with Root entry {
        self.path = [];
        self.path_weight = 0.0;
        self.visited = [];
        visit [-->];
    }

    can traverse with Workflow entry {
        print(f"Workflow: {here.name}");
        visit [-->];
    }

    can score with TaskNode entry {
        if here.invalidated {
            print(f"  skipped {here.label}: invalidated");
            return;
        }
        here.invalidated = True;
        self.path.append(here.label);
        self.path_weight += here.duration;
        print(f"  visit {here.label} (dur={here.duration}, retry={here.is_retry})");
        if self.visited.count(here.label) < 1 {
            self.visited.append(here.label);
            visit [->:TimingDep:->];
        }
    }

    can fold with RetryBranch entry {
        print(f"  retry loop attempt={here.attempt} -> continuing structurally");
        visit [->:StructuralDep:->];
    }
}

walker ParallelAuditor {
    has trusted: int = 0;
    has suspect: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        visit [-->];
    }

    can check with TaskNode entry {
        timing_outs = [->:TimingDep:->];
        struct_outs = [->:StructuralDep:->];
        verdict = "TRUSTED" if len(struct_outs) > 1 else "SUSPECT";
        if verdict == "TRUSTED" {
            self.trusted += 1;
        } else {
            self.suspect += 1;
        }
        print(f"  {here.label}: timing_outs={len(timing_outs)} "
              f"struct_outs={len(struct_outs)} -> {verdict}");
    }
}

# ---------- Demo graph ----------
with entry {
    wf = Workflow(name="order-pipeline");
    root ++> wf;

    fan_in = TaskNode(label="Join");
    parallel_a = TaskNode(label="ValidateAddress", duration=2.0);
    parallel_b = TaskNode(label="ChargeCard", duration=3.0);
    dispatch = TaskNode(label="Dispatch", duration=1.0);
    retry = RetryBranch(label="RetryCharge", attempt=1);

    wf ++> parallel_a;
    wf ++> parallel_b;
    wf ++> retry;

    # Structural edges (workflow JSON says these are siblings).
    parallel_a +>:StructuralDep(parallel_group="G1"):+> fan_in;
    parallel_b +>:StructuralDep(parallel_group="G1"):+> fan_in;

    # Timing edges — the timing-only DAG mistakenly chains A then B
    # then Join, even though they ran concurrently.
    parallel_a +>:TimingDep(weight=2.0):+> parallel_b;
    parallel_b +>:TimingDep(weight=3.0):+> fan_in;

    # Dispatch follows Join, retry loops back to charge.
    fan_in ++> dispatch;
    retry +>:StructuralDep:+> parallel_b;

    print("--- CriticalPath (timing-only DAG) ---");
    root spawn CriticalPath();

    print("\n--- ParallelAuditor: structural vs timing edges ---");
    root spawn ParallelAuditor();
}
