```jac
"""Audit current draw on power grid lines two different ways.

Grid lines meter electricity in a `can` ability on the Line edge. An
inspector walks the grid once with plain node visits -- the meters
stay silent because node visits cross edges without waking them -- and
then once more visiting the edges themselves, which trips every meter
before continuing to the next substation.
"""

node Substation {
    has name: str;
}

edge Line {
    has amps: float;

    can meter with Inspector entry {
        visitor.metered += 1;
        print(f"  meter on a {self.amps} A line: recording {self.amps} A");
    }
}

walker Inspector {
    has mode: str;
    has metered: int = 0;

    can start with Root entry {
        print(f"-- Pass: {self.mode} --");
        visit [-->];
    }

    can inspect with Substation entry {
        print(f"At {here.name}");
        if self.mode == "edges" {
            # Visiting edges wakes their abilities, then auto-continues
            visit [edge -->];
        } else {
            # Plain node visit crosses lines silently
            visit [-->];
        }
    }

    can done with Root exit {
        print(f"{self.mode} pass tripped {self.metered} meter(s)");
    }
}

with entry {
    plant = Substation(name="Plant");
    junction = Substation(name="Junction");
    town_a = Substation(name="TownA");
    town_b = Substation(name="TownB");

    root ++> plant;
    plant +>: Line(amps=41.0) :+> junction;
    junction +>: Line(amps=17.5) :+> town_a;
    junction +>: Line(amps=23.5) :+> town_b;

    quiet = Inspector(mode="nodes-only");
    root spawn quiet;

    loud = Inspector(mode="edges");
    root spawn loud;
}
```

"""Tests for the power grid meter audit program.

We exercise the program's two-pass behavior: a `nodes-only` inspector pass
that crosses Lines silently, and an `edges` inspector pass that steps onto
each Line and trips its meter. We verify both the count of metered lines
and that the meters' printed amps match the Line's amps field.
"""

import io;
import from contextlib { redirect_stdout }

test "nodes-only pass trips zero meters" {
    root ++> Substation(name="Plant")
        +>: Line(amps=41.0) :+> Substation(name="Junction")
        +>: Line(amps=17.5) :+> Substation(name="TownA");
    root ++> Substation(name="Plant2")
        +>: Line(amps=23.5) :+> Substation(name="TownB");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector(mode="nodes-only");
    }
    out = buf.getvalue();

    assert res.metered == 0, f"nodes-only pass should trip 0 meters, got {res.metered}";
    assert "meter on" not in out, f"no meter prints expected, got: {out}";
    assert "0 meter(s)" in out, f"missing summary line: {out}";
}

test "edges pass trips every meter on the grid" {
    # Three Lines total so the summary must read exactly 3 meter(s).
    root ++> Substation(name="Plant")
        +>: Line(amps=41.0) :+> Substation(name="Junction")
        +>: Line(amps=17.5) :+> Substation(name="TownA");
    root ++> Substation(name="Plant2")
        +>: Line(amps=23.5) :+> Substation(name="TownB");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector(mode="edges");
    }
    out = buf.getvalue();

    assert res.metered == 3, f"edges pass should trip exactly 3 meters, got {res.metered}";
    assert "3 meter(s)" in out, f"missing 3-meter summary: {out}";
}

test "edges pass prints each line's amps" {
    # Each Line's amps field must appear in the captured output, proving
    # the meter ran on that specific edge (not just a generic counter).
    root ++> Substation(name="Plant")
        +>: Line(amps=41.0) :+> Substation(name="Junction")
        +>: Line(amps=17.5) :+> Substation(name="TownA");
    root ++> Substation(name="Plant2")
        +>: Line(amps=23.5) :+> Substation(name="TownB");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector(mode="edges");
    }
    out = buf.getvalue();

    assert "41.0 A" in out, f"missing 41.0 A meter print: {out}";
    assert "17.5 A" in out, f"missing 17.5 A meter print: {out}";
    assert "23.5 A" in out, f"missing 23.5 A meter print: {out}";
    # And the meter prints must be in the loud (edges) pass header.
    assert "Pass: edges" in out, f"missing edges pass header: {out}";
}

test "two passes on the same grid show meters only in edges mode" {
    # Build the grid once; run both passes against independent copies
    # of the walker (meters are state on the walker, not the graph).
    root ++> Substation(name="Plant")
        +>: Line(amps=41.0) :+> Substation(name="Junction")
        +>: Line(amps=17.5) :+> Substation(name="TownA");
    root ++> Substation(name="Plant2")
        +>: Line(amps=23.5) :+> Substation(name="TownB");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        quiet_res = root spawn Inspector(mode="nodes-only");
        loud_res = root spawn Inspector(mode="edges");
    }
    out = buf.getvalue();

    assert quiet_res.metered == 0, f"nodes-only must trip 0 meters, got {quiet_res.metered}";
    assert loud_res.metered == 3, f"edges pass should trip 3 meters, got {loud_res.metered}";
    assert loud_res.metered > quiet_res.metered, "edges pass must trip more meters than nodes-only";

    # The quiet pass section must contain no "meter on" prints; the loud
    # pass section must contain them.
    quiet_section = out.split("Pass: nodes-only", 1)[1].split("Pass: edges", 1)[0];
    loud_section = out.split("Pass: edges", 1)[1];
    assert "meter on" not in quiet_section, f"quiet pass should print no meters: {quiet_section!r}";
    assert "meter on" in loud_section, f"loud pass should print meter lines: {loud_section!r}";
}

test "single-line grid trips exactly one meter in edges mode" {
    # Minimal case: one Line must record exactly once.
    root ++> Substation(name="A")
        +>: Line(amps=10.0) :+> Substation(name="B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector(mode="edges");
    }
    out = buf.getvalue();

    assert res.metered == 1, f"one line should trip 1 meter, got {res.metered}";
    assert "10.0 A" in out, f"missing 10.0 A print: {out}";
    assert out.count("meter on a") == 1, f"expected exactly 1 meter print, got {out.count('meter on a')}";
}

