```jac
"""SysML impact analysis: descend into the queried element's own subtree
(CONTAINS, downward only) while still collecting sibling-level relations
(CONNECTS_TO) so querying a parent surfaces its own ports' connections."""

# Edge archetypes — typed so the walker only follows downward containment.
edge Contains { }   # parent owns child (downward)
edge ConnectsTo { } # port-to-port wiring (lateral)

node Element {
    has name: str = "";
}

node Block(Element) {
    has kind: str = "block";
}

node Port(Element) {
    has kind: str = "port";
}

# The walker. It first visits the queried Block, then descends ONLY
# downward through :Contains: edges (so siblings of the query target
# are never pulled in), and at every visited node it collects any
# lateral :ConnectsTo: edges that originate there.
walker ImpactAnalyzer {
    has query_name: str = "";
    has findings: list[str] = [];

    can start with Root entry {
        # Walk only the downward containment edges from root into
        # the tree; the empty-else stops cleanly when nothing more
        # to visit (e.g. when root has no children at all).
        visit [->:Contains:->] else { disengage; }
    }

    # Same ability shape used for both Block and Port so the walker
    # can land on either kind of element while descending.
    can inspect with Block | Port entry {
        # Record the query target the first time we encounter it.
        if self.findings == [] and self.query_name != "" {
            self.findings.append(f"query: {self.query_name}");
        }
        here_name = here.name;

        # Collect lateral ConnectsTo edges that originate at this
        # node. These are the port-to-port wirings the original
        # impact_analysis surfaced.
        neighbors = [->:ConnectsTo:->];
        for nbr in neighbors {
            self.findings.append(f"connects: {here_name} -> {nbr.name}");
        }

        # Continue descending ONLY downward through Contains edges,
        # so siblings of the query target are not pulled in.
        visit [->:Contains:->];
    }
}

with entry {
    # Build a small model:
    #   FuelPump
    #     - inPort (Port)
    #         -- connects to --> Engine.outPort
    #     - outPort (Port)
    #         -- connects to --> Tank.inPort
    #   Engine
    #     - outPort (Port)        (sibling of FuelPump — must NOT show up
    #                               when querying FuelPump directly)
    #   Tank
    #     - inPort (Port)
    fuel_pump = Block(name="FuelPump", kind="block");
    engine    = Block(name="Engine",    kind="block");
    tank      = Block(name="Tank",      kind="block");

    fuel_in  = Port(name="FuelPump.inPort",  kind="port");
    fuel_out = Port(name="FuelPump.outPort", kind="port");
    eng_out  = Port(name="Engine.outPort",   kind="port");
    tank_in  = Port(name="Tank.inPort",      kind="port");

    # Downward ownership — typed Contains edges.
    root +>:Contains:+> fuel_pump;
    root +>:Contains:+> engine;
    root +>:Contains:+> tank;
    fuel_pump +>:Contains:+> fuel_in;
    fuel_pump +>:Contains:+> fuel_out;
    engine    +>:Contains:+> eng_out;
    tank      +>:Contains:+> tank_in;

    # Lateral wiring — typed ConnectsTo edges between ports.
    fuel_in  +>:ConnectsTo:+> eng_out;
    fuel_out +>:ConnectsTo:+> tank_in;

    # Query "FuelPump" directly. The walker descends into FuelPump's
    # own subtree (its two ports) via :Contains: only — sibling
    # Engine and its port are NOT visited.
    analyzer = ImpactAnalyzer(query_name="FuelPump");
    root spawn analyzer;

    for line in analyzer.findings {
        print(line);
    }

    print("---");
    print("note: Engine.outPort never appeared above because the");
    print("walker followed Contains (downward) only, not parent links.");
}
