```jac
"""Kanban dispatcher: model orphaned claim locks on non-running cards.

Demonstrates the gap where a card in ready/todo/blocked that still carries
a stale claim_lock/claim_expires is invisible to the dispatcher. A
``Dispatcher`` walker traverses ready cards via a typed ``Claim`` edge and
runs a ``ReclaimSweep`` walker that clears only truly orphaned claims,
using a grace window so a second ticker cannot nuke a freshly claimed card.
"""

node Worker {
    has worker_id: str = "";
    has pid: int = 0;
}

node Card {
    has title: str = "";
    has status: str = "ready";
    has claim_lock: str | None = None;
    has claim_expires: str | None = None;
}

node WorkerRoster {
    has alive_ids: list[str] = [];
}

edge Claim {
    has claimed_by: str = "";
    has expires_at: str = "";
}

edge Rostered { }

# --- Dispatcher: walks ready cards and reports those it can/can't see ----
walker Dispatcher {
    has dispatched: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Card entry {
        if here.status in ["ready", "todo", "blocked"] {
            if here.claim_lock is None {
                self.dispatched.append(here.title);
                print(f"[DISPATCH] {here.title} (status={here.status})");
            } else {
                print(f"[SKIP]    {here.title} holds stale claim '{here.claim_lock}'");
            }
        }
        visit [-->];
    }
}

# --- Reclaim sweep: clear only orphaned claims (dead PID + expired/grace) -
walker ReclaimSweep {
    has grace_seconds: int = 30;
    has now_epoch: int = 100000;
    has cleared: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Card entry {
        if here.status in ["ready", "todo", "blocked"] and here.claim_lock is not None {
            # Simulate PID-alive lookup: only worker "alive-worker" is considered alive.
            worker_alive = here.claim_lock == "alive-worker";
            claim_expired_or_graced = (here.claim_expires is not None)
                and ((self.now_epoch - int(here.claim_expires)) >= self.grace_seconds);

            if (not worker_alive) and claim_expired_or_graced {
                victim = here.title;
                here.claim_lock = None;
                here.claim_expires = None;
                self.cleared.append(victim);
                print(f"[RECLAIM] {victim} -> claim cleared");
            }
        }
        visit [-->];
    }
}

with entry {
    # Build the graph: root -> roster + a chain of cards.
    roster = WorkerRoster(alive_ids=["alive-worker"]);
    root ++> roster;

    # Card A: clean, dispatchable.
    a = Card(title="A-clean");
    # Card B: claimed by a worker whose PID is dead and claim is expired -> orphan.
    b = Card(title="B-orphan", claim_lock="dead-worker", claim_expires="99900");
    # Card C: claimed by a still-alive worker; must NOT be reclaimed.
    c = Card(title="C-fresh", claim_lock="alive-worker", claim_expires="99990");
    # Card D: claimed by dead worker but claim is within grace window -> keep.
    d = Card(title="D-just-claimed", claim_lock="dead-worker", claim_expires="99985");

    # Typed Claim edges express the relationship between card and claimer.
    a +>:Claim(claimed_by="", expires_at=""):+> Worker(worker_id="none");
    b +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-9");
    c +>:Claim(claimed_by="alive-worker", expires_at="99990"):+> Worker(worker_id="W-1");
    d +>:Claim(claimed_by="dead-worker", expires_at="99985"):+> Worker(worker_id="W-7");

    root ++> a ++> b ++> c ++> d;

    print("--- Before sweep: dispatcher sees ---");
    disp = Dispatcher();
    root spawn disp;

    print("--- Running reclaim sweep ---");
    sweep = ReclaimSweep(grace_seconds=30, now_epoch=100000);
    root spawn sweep;

    print("--- After sweep: dispatcher sees ---");
    disp2 = Dispatcher();
    root spawn disp2;

    print(f"cleared cards: {sweep.cleared}");
    print(f"dispatched cards: {disp2.dispatched}");
}
