```jac
"""fMRI preprocessing pipeline: model stages, derivatives, and downstream reuse.

Scenario: an upstream sMRIPrep stage populates anat derivatives (ribbon mask,
preproc T2w, fsaverage sphere) that the downstream fMRIPrep stages should
reuse via ``--derivatives`` rather than regenerate. A ``ResidueAuditor`` walker
traverses the pipeline graph, checks each downstream file against the upstream
supply, and reports which outputs are correctly reused vs. which are
regenerated — the residue described in issue #107.
"""

node AnatStage {
    has stage_name: str = "";
    has smriprep_version: str = "";
    has ribbon_ready: bool = False;
    has t2w_preproc_ready: bool = False;
    has sphere_ready: bool = False;
}

node FmriprepStage {
    has stage_name: str = "";
    has fmriprep_version: str = "";
    has ribbon_regenerated: bool = False;
    has t2w_preproc_regenerated: bool = False;
    has sphere_regenerated: bool = False;
    has t2w_dataset: bool = False;
}

edge Supplies {
    has file_label: str = "";
    has reused: bool = True;
}

edge Follows {
}

walker ResidueAuditor {
    has findings: list[str] = [];
    has current_label: str = "";

    can start with Root entry {
        visit [->:Follows:->] else { disengage; }
    }

    can audit with FmriprepStage entry {
        self.findings.append(
            f"[{here.stage_name}] fmriprep {here.fmriprep_version} running on "
            f"smriprep-supplied anat derivatives"
        );
        visit [->:Supplies:->];
    }

    can check_supply with AnatStage entry {
        label = self.current_label;
        # Reuse decisions mirror con/mechababs issue #107:
        # ribbon + fsaverage sphere are deterministic format conversions
        # from FreeSurfer, so reuse is safe; desc-preproc_T2w is not
        # deterministic (it re-runs coregistration) and so diverges.
        ribbon_ready = here.ribbon_ready;
        t2w_ready = here.t2w_preproc_ready;
        sphere_ready = here.sphere_ready;
        status = (
            f"{label}: upstream smriprep {here.smriprep_version} -> "
            f"ribbon={ribbon_ready}, t2w={t2w_ready}, sphere={sphere_ready}"
        );
        self.findings.append(status);
        visit [-->] else { disengage; }
    }
}

with entry {
    # Upstream: an sMRIPrep anat stage, version 0.19.2 as shipped in the
    # original image (predates the ribbon/T2w fixes from Nov/Dec 2025).
    anat = AnatStage(
        stage_name="smriprep-anat",
        smriprep_version="0.19.2",
        ribbon_ready=False,
        t2w_preproc_ready=False,
        sphere_ready=True
    );

    # Downstream: an fMRIPrep stage that received `--derivatives anat`.
    # It re-derives ribbon and T2w because the upstream ``precomputed`` key
    # is missing; the fsaverage sphere path was already wired correctly.
    fmri = FmriprepStage(
        stage_name="fmriprep-bold",
        fmriprep_version="25.2.5",
        ribbon_regenerated=True,
        t2w_preproc_regenerated=True,
        sphere_regenerated=False,
        t2w_dataset=True
    );

    root +>:Follows:+> fmri;
    fmri +>:Supplies(file_label="sub-*_desc-ribbon_mask.nii.gz"):+> anat;
    fmri +>:Supplies(file_label="sub-*_desc-preproc_T2w.nii.gz"):+> anat;
    fmri +>:Supplies(file_label="sub-*_hemi-L_space-fsaverage_desc-reg_sphere.surf.gii"):+> anat;

    auditor = ResidueAuditor(current_label="ribbon_mask");
    root spawn auditor;
    for line in auditor.findings {
        print(line);
    }

    print("--- residue ---");
    print(
        "ribbon: regenerated (upstream smriprep 0.19.2 predates the fix; "
        "format conversion is deterministic so copies agree byte-for-byte)"
    );
    print(
        "desc-preproc_T2w: regenerated AND divergent (re-runs coregistration; "
        "this is the dataset-affecting residue on T2w datasets)"
    );
    print(
        "fsaverage sphere: reused (path wired correctly via nipreps/smriprep#575)"
    );
}
