    }

    can audit_project with Project entry {
        print(f"Auditing project: {here.group}:{here.name}:{here.version}");
        visit [->:DependsOn:->];
    }

    can audit_dependency with Dependency entry {
        coord = f"{here.group}:{here.artifact}:{here.version}";
        if coord in self.visited {
            print(f"[cycle/skip] {coord}");
            visit [-->] else { disengage; }
        }
        self.visited.append(coord);

        if here.vulnerable {
            finding = (here.group, here.artifact, here.version, here.cve);
            self.findings.append(finding);
            print(
                f"[VULN] {here.group}:{here.artifact}:{here.version} "
                f"-- {here.cve} (fix -> {here.suggested_fix})"
            );
        } else {
            print(f"  ok  {coord}");
        }

        visit [->:DependsOn:->];
    }
}

walker ApplyFix {
    can start with Root entry {
        visit [-->];
    }

    can visit_project with Project entry {
        visit [->:DependsOn:->];
    }

    can visit_dep with Dependency entry {
        if here.vulnerable {
            print(
                f"Applying fix: {here.group}:{here.artifact} "
                f"{here.version} -> {here.suggested_fix}"
            );
            here.version = here.suggested_fix;
            here.vulnerable = False;
            here.cve = "";
        }
        visit [-->];
    }
}

with entry {
    root ++> Project(name="example-of-customPropertyProductMapping",
                      group="com.example",
                      version="1.0.0");

    starter = Dependency(group="org.springframework.boot",
                         artifact="spring-boot-starter-web",
                         version="3.0.3");
    webmvc_vuln = Dependency(group="org.springframework",
                             artifact="spring-webmvc",
                             version="6.0.5",
                             vulnerable=True,
                             cve="CVE-2026-22745",
                             suggested_fix="6.2.18");
    webflux = Dependency(group="org.springframework",
                          artifact="spring-webflux",
                          version="6.0.5");
    jdbc = Dependency(group="org.springframework",
                      artifact="spring-jdbc",
                      version="6.0.4");

    starter +>:DependsOn:+> webmvc_vuln;
    starter +>:DependsOn:+> webflux;
    starter +>:DependsOn:+> jdbc;
    webmvc_vuln +>:DependsOn:+> jdbc;
    starter +>:DependsOn:+> starter;

    root +>:DependsOn:+> starter;
    webmvc_vuln +>:Fixes(to_version="6.2.18"):+> starter;

    print("=== Initial audit ===");
    root spawn Auditor();
}
