"""Protected-state JSON bundle materializer (OSP model of issue #272).

Models the trusted-control write path for a vertical policy bundle: a repository
anchored on a protected ref accepts an exact namespace of canonical JSON files
under a `PROTECTED` receipt, performs fast-forward CAS only, preserves unrelated
tree paths, and emits a path/digest receipt for downstream loaders.
"""

node Repo {
    has name: str = "";
    has protected_ref: str = "refs/heads/ai-sdlc-operator-state";
}

node Commit {
    has sha: str = "";
    has is_protected: bool = True;
    has expected_sha: str = "";
}

node PolicyFile {
    has path: str = "";
    has canonical_sha256: str = "";
}

node Receipt {
    has kind: str = "PLAIN";
    has namespace: str = "";
}

edge Anchors { }
edge Parents { }
edge Contains { }
edge Sealed { }

walker Materializer {
    has result_sha: str = "";
    has result_paths: list[str] = [];
    has result_digests: list[str] = [];
    has fail_reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can bind_repo with Repo entry {
        print(f"binding repo={here.name} ref={here.protected_ref}");
        visit [->:Parents:->];
    }

    can audit_commit with Commit entry {
        if here.expected_sha != "" and here.expected_sha != here.sha {
            self.fail_reason = "stale expected SHA";
            disengage;
        }
        if not here.is_protected {
            self.fail_reason = "unprotected receipt";
            disengage;
        }
        visit [->:Contains:->];
    }

    can verify_files with PolicyFile entry {
        if not here.path.startswith("config/operator/v03-vertical-policy/") {
            self.fail_reason = "namespace escape";
            disengage;
        }
        if ".." in here.path or here.path.startswith("/") {
            self.fail_reason = "path traversal rejected";
            disengage;
        }
        if not here.path.endswith(".json") {
            self.fail_reason = "non-JSON path rejected";
            disengage;
        }
        for p in self.result_paths {
            if p == here.path {
                self.fail_reason = "duplicate path rejected";
                disengage;
            }
        }
        self.result_paths.append(here.path);
        self.result_digests.append(here.canonical_sha256);
        print(f"verified {here.path} sha256={here.canonical_sha256}");
    }

    can confirm_receipt with Receipt entry {
        if here.kind != "PROTECTED" {
            self.fail_reason = "receipt not PROTECTED";
            disengage;
        }
        if here.namespace != "config/operator/v03-vertical-policy/" {
            self.fail_reason = "receipt namespace mismatch";
            disengage;
        }
        self.result_sha = "f1be17ca5e7b3c0f0c2a9b1e4d6f8a7c5e3b2a10";
        print("PROTECTED receipt accepted");
    }
}

with entry {
    repo = Repo(name="dream-xin/ai-sdlc");
    protected = Commit(sha="fe1be17f4ab202b1b1be9850f5d0e2316a15834a", is_protected=True);
    rcpt = Receipt(kind="PROTECTED", namespace="config/operator/v03-vertical-policy/");
    f1 = PolicyFile(path="config/operator/v03-vertical-policy/writer-fence.json",
                    canonical_sha256="a1b2c3d4e5f6");
    f2 = PolicyFile(path="config/operator/v03-vertical-policy/resolution.json",
                    canonical_sha256="1a2b3c4d5e6f");
    unrelated_marker = PolicyFile(path="state/operator/v1/event-log.json",
                                  canonical_sha256="deadbeef0001");

    root +>:Anchors:+> repo;
    repo +>:Parents:+> protected;
    protected +>:Contains:+> f1;
    protected +>:Contains:+> f2;
    protected +>:Contains:+> unrelated_marker;
    repo +>:Sealed:+> rcpt;

    root spawn Materializer();
    m = Materializer();
    root spawn m;
    print(f"materialized_sha={m.result_sha}");
    print(f"verified_paths={m.result_paths}");
    print(f"verified_digests={m.result_digests}");
}
