"""NORA-style architecture publishing: principles, building blocks, and standards
linked by typed relationships, traversed by walkers that handle parent/child
nesting, dependency ordering, mapping lookups, and cycle-safe walks.
"""

node Principle {
    has title: str = "";
    has code: str = "";
    has description: str = "";
    has depth: int = 0;
}

node BuildingBlock {
    has title: str = "";
    has code: str = "";
    has description: str = "";
    has kind: str = "service";
}

node Standard {
    has title: str = "";
    has code: str = "";
    has compliance_status: str = "toegepast";
    has compliance_reasoning: str = "";
}

edge AdoptsFrom { }
edge ComposedOf { }
edge ProfilesOf { }
edge HasChild { }

walker TreePrinter {
    can start with Root entry {
        visit [-->];
    }

    can walk_principle with Principle entry {
        indent = "  " * here.depth;
        print(f"{indent}{here.title} ({here.code})");
        visit [->:HasChild:->];
    }
}

walker DependencyOrderer {
    has visited: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with BuildingBlock entry {
        key = here.code;
        if key not in self.visited {
            self.visited.append(key);
            self.order.append(key);
            print(f"ordered: {here.title}");
            visit [->:ComposedOf:->];
        } else {
            visit [->:ComposedOf:->];
        }
    }
}

walker ComplianceAuditor {
    has issues: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_standard with Standard entry {
        if here.compliance_status == "niet-toegepast" and here.compliance_reasoning == "" {
            note = f"missing reasoning for {here.code}";
            self.issues.append(note);
            print(f"[WARN] {note}");
        } else {
            print(f"[OK] {here.code}: {here.compliance_status}");
