"""Restaurant kitchen health inspection.

Walks the kitchen line (grill, fryer, cold prep) and at each station runs
two separate checks: a temperature violation scan (anything above 40 C is
flagged) and a station-visit log. Both abilities fire at every station.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Inspector {
    has log: list[str] = [];

