    can check_temp with Grill | Fryer | ColdPrep entry {
        if here.celsius > 40.0 {
            print(f"[VIOLATION] {here.name} is {here.celsius} C (> 40 C)");
        } else {
            print(f"[OK] {here.name} is {here.celsius} C");
        }
    }

    can log_visit with Grill | Fryer | ColdPrep entry {
        label = f"visited {here.name} at {here.celsius} C";
        self.log.append(label);
        print(f"[LOG] {label}");
    }
}

with entry {
    grill = Grill(name="Grill", celsius=180.0);
    fryer = Fryer(name="Fryer", celsius=165.0);
    cold = ColdPrep(name="Cold Prep", celsius=4.0);

    root ++> grill ++> fryer ++> cold;

    inspector = Inspector();
    root spawn inspector;

    print("--- visit log ---");
    for entry in inspector.log {
        print(entry);
    }
}
