"""Metric dependency graph with invalidation, materialization, and cycle rejection."""

node Metric {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_value: float = 0.0;
    has offset: float = 0.0;
    has value: float = 0.0;
    has dependency_count: int = 0;
    has dirty: bool = True;
    has materialized: bool = False;
    has cycle_rejected: bool = False;
    has revision: int = 0;
}

node MaterializationJob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has queued: bool = True;
    has completed: bool = False;
}

edge DependsOn {
    has lag: int = 0;
}

edge Schedules { }

walker AsyncMaterializer {
    has active: list[str] = [];
    has rejected: list[str] = [];
    has totals: list[float] = [];

    can start with Root entry {
        print("starting asynchronous materialization");
        visit [-->] else { disengage; }
    }

    can begin with MaterializationJob entry {
        here.queued = False;
        print(f"running job {here.title}");
        visit [->:Schedules:->] else { disengage; }
    }

    can resolve with Metric entry {
        if (here.title in self.active) {
            here.cycle_rejected = True;
            self.rejected.append(here.title);
            print(f"rejected circular dependency at {here.title}");
            disengage;
        } else {
            self.active.append(here.title);
            self.totals.append(0.0);
            if (here.dependency_count > 0) {
                visit [->:DependsOn:->] else { disengage; }
            }
        }
    }

    can finish with MaterializationJob exit {
        here.completed = True;
        print(f"completed job {here.title}");
    }

    can commit with Metric exit {
        if (here.title in self.rejected) {
            if (self.totals != []) {
                self.totals.pop();
            }
        } else {
            child_total = self.totals.pop();
            computed = here.source_value + here.offset + child_total;
            here.value = computed;
            here.materialized = True;
            here.dirty = False;
            here.revision += 1;

            if (self.totals != []) {
                parent_total = self.totals.pop();
                parent_total += computed;
                self.totals.append(parent_total);
            }

            print(f"materialized {here.title} = {here.value}");
        }

        if (here.title in self.active) {
            self.active.remove(here.title);
        }
    }
}

walker InvalidationPropagator {
    has seen: list[str] = [];

    can invalidate with Metric entry {
        if (here.title in self.seen) {
            disengage;
        } else {
            self.seen.append(here.title);
            here.dirty = True;
            here.materialized = False;
            visit [<--] else { disengage; }
        }
    }
}

walker CycleAuditor {
    has trail: list[str] = [];
    has rejected: bool = False;

    can inspect with Metric entry {
        if (here.title in self.trail) {
            self.rejected = True;
            here.cycle_rejected = True;
            print(f"rejected circular dependency at {here.title}");
            disengage;
        } else {
            self.trail.append(here.title);
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

with entry {
    revenue = Metric(
        title="Revenue",
        year=2025,
        source_value=100.0
    );
    margin = Metric(
        title="Margin",
        year=2025,
        offset=10.0,
        dependency_count=1
    );
    growth = Metric(
        title="Growth",
        year=2025,
        offset=5.0,
        dependency_count=1
    );

    cycle_a = Metric(
        title="Cycle A",
        year=2025,
        dependency_count=1
    );
    cycle_b = Metric(
        title="Cycle B",
        year=2025,
        dependency_count=1
    );

    margin +>:DependsOn:+> revenue;
    growth +>:DependsOn:+> margin;
    cycle_a +>:DependsOn:+> cycle_b;
    cycle_b +>:DependsOn:+> cycle_a;

    job = MaterializationJob(
        title="Rebuild derived metrics",
        year=2025
    );
    root ++> job;
    job +>:Schedules:+> growth;

    root spawn AsyncMaterializer();

    revenue.source_value = 120.0;
    revenue.dirty = True;
    revenue.materialized = False;
    revenue spawn InvalidationPropagator();

    root spawn AsyncMaterializer();
    cycle_a spawn CycleAuditor();
}
