import io;
import from contextlib { redirect_stdout }

test "materializes an acyclic dependency chain" {
    revenue = Metric(title="Revenue", year=2025, source_value=100.0);
    margin = Metric(title="Margin", year=2025, offset=10.0, dependency_count=1);
    growth = Metric(title="Growth", year=2025, offset=5.0, dependency_count=1);

    margin +>:DependsOn:+> revenue;
    growth +>:DependsOn:+> margin;

    job = MaterializationJob(title="Rebuild", year=2025);
    root ++> job;
    job +>:Schedules:+> growth;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AsyncMaterializer();
    }
    out = buf.getvalue();

    assert "materialized Growth" in out, f"missing materialization output: {out}";
    assert revenue.value == 100.0, f"got {revenue.value}";
    assert margin.value == 110.0, f"got {margin.value}";
    assert growth.value == 115.0, f"got {growth.value}";
    assert revenue.materialized == True, f"revenue materialized={revenue.materialized}";
    assert growth.dirty == False, f"growth dirty={growth.dirty}";
    assert res.active == [], f"active metrics remain: {res.active}";
}

test "invalidates and rematerializes downstream metrics" {
    revenue = Metric(title="Revenue", year=2025, source_value=100.0);
    margin = Metric(title="Margin", year=2025, offset=10.0, dependency_count=1);
    growth = Metric(title="Growth", year=2025, offset=5.0, dependency_count=1);

    margin +>:DependsOn:+> revenue;
    growth +>:DependsOn:+> margin;

    job = MaterializationJob(title="Rebuild", year=2025);
    root ++> job;
    job +>:Schedules:+> growth;

    root spawn AsyncMaterializer();

    revenue.source_value = 125.0;
    revenue spawn InvalidationPropagator();

    assert revenue.dirty == True, f"revenue dirty={revenue.dirty}";
    assert margin.dirty == True, f"margin dirty={margin.dirty}";
    assert growth.dirty == True, f"growth dirty={growth.dirty}";
    assert growth.materialized == False, f"growth materialized={growth.materialized}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AsyncMaterializer();
    }
    out = buf.getvalue();

    assert "materialized Growth" in out, f"missing rematerialization output: {out}";
    assert margin.value == 135.0, f"got {margin.value}";
    assert growth.value == 140.0, f"got {growth.value}";
    assert revenue.revision == 2, f"revenue revision={revenue.revision}";
    assert growth.revision == 2, f"growth revision={growth.revision}";
    assert growth.dirty == False, f"growth dirty={growth.dirty}";
    assert res.active == [], f"active metrics remain: {res.active}";
}

test "rejects circular metric dependencies" {
    cycle_a = Metric(title="Cycle A", year=2025, dependency_count=1);
    cycle_b = Metric(title="Cycle B", year=2025, dependency_count=1);

    cycle_a +>:DependsOn:+> cycle_b;
    cycle_b +>:DependsOn:+> cycle_a;

    res = cycle_a spawn CycleAuditor();

    assert res.rejected == True, f"rejected={res.rejected}";
    assert cycle_a.cycle_rejected == True, f"cycle_a rejected={cycle_a.cycle_rejected}";
}
