```jac
"""Memory commit/search integrity gap modeled as a typed graph + integrity walker.

The original bug was that a writer could push a Revision whose envelope claimed
a hash, predecessor, and projection that did not line up with the authoritative
manifest. We model the protocol objects as node archetypes, the revisions that
extend a memory as a typed edge chain, and let a single ``MemoryAuditor`` walker
walk the chain and reject revisions whose entry text, declared hash, or
declared predecessor disagree with the manifest that was actually committed.

The walker fires its integrity ability on the union of node types the chain
might land on, then forwards over the typed ``RevisionOf`` edge. A second
``BadMemoryWriter`` walker commits a deliberately malformed revision through
the same seam, so the demonstration shows the auditor catching what the loose
backend used to let through.
"""

# Base capability shared by every node the auditor may visit. Keeping a base
# archetype lets one union ability handle heterogeneous nodes. Every concrete
# node below inherits from Auditable and overrides ``audit_label``.
node Auditable {
    def audit_label() -> str {
        return "";
    }
}

node Memory(Auditable) {
    has artifact_id: str = "";
    has revision: int = 0;
    has manifest_hash: str = "";

    override def audit_label() -> str {
        return f"Memory(artifact={self.artifact_id}, rev={self.revision})";
    }
}

node MemoryEntryVersion(Auditable) {
    has entry_id: str = "";
    has entry_version_id: str = "";
    has version: int = 0;
    has previous_version_id: str = "";
    has text: str = "";
    has entry_content_hash: str = "";
    has kind: str = "fact";
    has state: str = "active";
    has searchable_text: str = "";

    override def audit_label() -> str {
        return f"EntryVersion({self.entry_version_id})";
    }
}

node MemoryManifestEntry(Auditable) {
    has entry_id: str = "";
    has entry_version_id: str = "";
    has entry_content_hash: str = "";
    has state: str = "active";

    override def audit_label() -> str {
        return f"ManifestEntry({self.entry_id}->{self.entry_version_id})";
    }
}

node MemoryProjection(Auditable) {
    has entry_id: str = "";
    has version_id: str = "";
    has searchable_text: str = "";

    override def audit_label() -> str {
        return f"Projection({self.entry_id}@{self.version_id})";
    }
}

# Typed edge: the revision that an entry version belongs to. Carries the
# committed manifest hash so traversal can detect manifest/body drift.
edge RevisionOf {
    has manifest_hash: str = "";
    has committed_revision: int = 0;
}

# Typed edge: a manifest entry points at the entry version it authoritatively
# binds. Empty payload — the binding itself is the relationship.
edge BindsEntry { }

# Typed edge: a projection is bound to a specific entry version.
edge BindsProjection { }

walker MemoryAuditor {
    has expected_manifest_hash: str = "";
    has canonical_text: str = "";
    has known_predecessor: str = "";
    has violations: int = 0;
    has inspected: int = 0;

    can start with Root entry {
        print(f"auditor: starting walk, expected manifest_hash={self.expected_manifest_hash}");
        visit [-->];
    }

    can audit with Memory | MemoryEntryVersion | MemoryManifestEntry | MemoryProjection entry {
        self.inspected += 1;
        label = here.audit_label();
        ok = self.check_node(here);
        status = "OK" if ok else "VIOLATION";
        print(f"auditor: [{status}] {label}");
        if not ok {
            self.violations += 1;
        }
        visit [-->];
    }

    def check_node(n: Auditable) -> bool {
        if isinstance(n, Memory) {
            return n.manifest_hash == self.expected_manifest_hash;
        }
        if isinstance(n, MemoryEntryVersion) {
            # The declared hash must match the canonical text and the
            # predecessor must point at a known-good revision.
            text_matches_canonical = n.text == self.canonical_text;
            declared_hash_matches = (n.entry_content_hash == self.expected_manifest_hash);
            predecessor_ok = (
                n.previous_version_id == self.known_predecessor
                or n.version == 1
            );
            # A body that disagrees with the declared hash is a violation;
            # only the canonical body is allowed to carry the canonical hash.
            body_integrity_ok = (text_matches_canonical == declared_hash_matches);
            return predecessor_ok and body_integrity_ok;
        }
        if isinstance(n, MemoryManifestEntry) {
            return n.entry_content_hash == self.expected_manifest_hash;
        }
        if isinstance(n, MemoryProjection) {
            return n.searchable_text == self.canonical_text;
        }
        return True;
    }
}

walker BadMemoryWriter {
    has target_artifact_id: str = "";

    can start with Root entry {
        # Find the memory we want to corrupt.
        visit [-->];
    }

    can corrupt with Memory entry {
        # Drop a tampered searchable body onto the memory while keeping
        # the originally declared hash. The loose backend used to let
        # this through; the auditor will catch it on its next sweep.
        print(f"writer: injecting tampered projection under {here.artifact_id}");
        visit [-->];
    }
}

with entry {
    # Canonical, known-good state.
    canonical = "User prefers black tea.";
    canonical_hash = "h-canonical-black-tea";
    predecessor = "pref-tea-v0";

    # Wire the demonstration graph: one memory, the entry version it commits,
    # the manifest entry that authoritatively binds them, and the projection
    # that downstream search returns.
    m = Memory(artifact_id="memory", revision=1, manifest_hash=canonical_hash);
    v1 = MemoryEntryVersion(
        entry_id="pref-tea",
        entry_version_id="pref-tea-v1",
        version=1,
        previous_version_id=predecessor,
        text=canonical,
        entry_content_hash=canonical_hash,
    );
    manifest_entry = MemoryManifestEntry(
        entry_id="pref-tea",
        entry_version_id="pref-tea-v1",
        entry_content_hash=canonical_hash,
    );
    projection = MemoryProjection(
        entry_id="pref-tea",
        version_id="pref-tea-v1",
        searchable_text=canonical,
    );

    root +>:RevisionOf(manifest_hash=canonical_hash, committed_revision=1):+> m;
    m +>:RevisionOf(manifest_hash=canonical_hash, committed_revision=1):+> v1;
    m +>:BindsEntry:+> manifest_entry;
    manifest_entry +>:BindsEntry:+> v1;
    m +>:BindsProjection:+> projection;
    projection +>:BindsProjection:+> v1;

    # First sweep: the auditor walks the chain and confirms every node
    # agrees with the canonical hash/text/predecessor.
    print("=== sweep 1: clean state ===");
    auditor1 = MemoryAuditor(
        expected_manifest_hash=canonical_hash,
        canonical_text=canonical,
        known_predecessor=predecessor,
    );
    root spawn auditor1;
    print(f"auditor1 inspected={auditor1.inspected} violations={auditor1.violations}");

    # Now simulate the seam: a writer bypasses MemoryService and pushes a
    # revision whose envelope claims the canonical hash but whose body and
    # searchable text disagree with the manifest.
    print("=== injecting malformed revision ===");
    bad = MemoryEntryVersion(
        entry_id="pref-tea",
        entry_version_id="pref-tea-v1",
        version=1,
        previous_version_id="does-not-exist",
        text="tampered searchable body.",
        entry_content_hash=canonical_hash,
    );
    bad_proj = MemoryProjection(
        entry_id="pref-tea",
        version_id="pref-tea-v1",
        searchable_text="tampered searchable body.",
    );
    root +>:RevisionOf(manifest_hash=canonical_hash, committed_revision=1):+> bad;
    bad +>:BindsProjection:+> bad_proj;
    root spawn BadMemoryWriter(target_artifact_id="memory");

    # Second sweep: the auditor walks the same chain, now including the
    # tampered node, and rejects it.
    print("=== sweep 2: after seam write ===");
    auditor2 = MemoryAuditor(
        expected_manifest_hash=canonical_hash,
        canonical_text=canonical,
        known_predecessor=predecessor,
    );
    root spawn auditor2;
    print(f"auditor2 inspected={auditor2.inspected} violations={auditor2.violations}");
}
