"""Tests for OrderAuditor: skip-vs-halt semantics."""

import io;
import from contextlib { redirect_stdout }

def _build_chain {
    root ++> Order(amount=49.99, valid=True, fraud=False)
        ++> Order(amount=12.00, valid=False, fraud=False)
        ++> Order(amount=200.00, valid=True, fraud=True)
        ++> Order(amount=5.50, valid=True, fraud=False);
}

test "default chain: audits, skips invalid, halts on fraud" {
    root ++> Order(amount=49.99, valid=True, fraud=False)
        ++> Order(amount=12.00, valid=False, fraud=False)
        ++> Order(amount=200.00, valid=True, fraud=True)
        ++> Order(amount=5.50, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=49.99" in out, f"missing audit line: {out}";
    assert "[SKIP] invalid order amount=12.0" in out, f"missing skip line: {out}";
    assert "[HALT] fraud flagged order amount=200.0" in out, f"missing halt line: {out}";
    # The post-fraud order must NOT be audited.
    assert "amount=5.5" not in out, f"walk did not halt on fraud: {out}";
}

test "all valid no-fraud: every order is audited, no halt" {
    root ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=True, fraud=False)
        ++> Order(amount=30.0, valid=True, fraud=False);
