    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=10.0" in out, f"missing 10: {out}";
    assert "[AUDIT] approved order amount=20.0" in out, f"missing 20: {out}";
    assert "[AUDIT] approved order amount=30.0" in out, f"missing 30: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";
    assert "[SKIP]" not in out, f"unexpected skip: {out}";
}

