    root ++> Order(amount=99.99, valid=True, fraud=True)
        ++> Order(amount=1.0, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
