```jac
"""Desktop dependency graph: model vulnerable crates, traverse paths, and
flag advisory reachability through a typed dependency walker.

The issue (cryptnetworks/NexaChat #210) describes a graph of direct and
transitive Rust dependencies where a medium-severity advisory on `glib`
0.18.5 is reachable through the Tauri -> gtk -> glib path, and several
unmaintained crate chains must be inventoried.  This demo lifts the
"parent_id"-style dependency walk to native Jac: Crates are nodes, the
relationship `depends on` is a typed edge, and an auditor walker walks
the graph accumulating advisory findings.
"""

node Crate {
    has name: str = "";
    has version: str = "";
    has vulnerable: bool = False;
    has unmaintained: bool = False;
}

edge DependsOn {
    has dep_kind: str = "transitive";
}

walker Auditor {
    has findings: list = [];
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Crate entry {
        # Cycle / re-visit guard: walkers in Jac 0.36.1 do not dedupe
        # automatically, so we enforce single-entry per crate name.
        already = False;
        for v in self.visited {
            if v == here.name {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited.append(here.name);

        if here.vulnerable {
            note = f"VULN {here.name}@{here.version} reachable";
            self.findings.append(note);
            print(note);
        }
        if here.unmaintained {
            note = f"UNMAINTAINED {here.name}@{here.version} reachable";
            self.findings.append(note);
            print(note);
        }

        visit [->:DependsOn:->];
    }
}

walker ReachabilityProbe {
    has target: str = "glib";
    has found: bool = False;
    has path: list = [];

    can start with Root entry {
        visit [-->];
    }

    can probe with Crate entry {
        if here.name == self.target {
            self.found = True;
            self.path.append(here.name);
            disengage;
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    # Build the desktop crate graph.  Tauri is the root of the
    # desktop binary's native dependency tree.
    tauri = Crate(name="nexa-desktop", version="2.11.5");
    gtk = Crate(name="gtk", version="0.18.2", unmaintained=True);
    glib = Crate(
        name="glib",
        version="0.18.5",
        vulnerable=True,
    );
    gtk_fixed = Crate(name="gtk", version="0.20.0");
    glib_fixed = Crate(name="glib", version="0.20.0");
    tauri_runtime = Crate(name="tauri-runtime-wry", version="2.11.5");
    wry = Crate(name="wry", version="2.11.5");
    tao = Crate(name="tao", version="2.11.5");
    webkit2gtk = Crate(name="webkit2gtk", version="2.11.5", unmaintained=True);
    tauri_utils = Crate(name="tauri-utils", version="2.11.5");
    urlpattern = Crate(name="urlpattern", version="0.3.0", unmaintained=True);
    unic = Crate(name="unic", version="1.4.0", unmaintained=True);
    proc_macro_error = Crate(name="proc-macro-error", version="1.0.0", unmaintained=True);

    # Wire the graph: root -> desktop, then typed `DependsOn` edges
    # for every direct or transitive pull-in.
    root ++> tauri;
    tauri +>:DependsOn(dep_kind="direct"):+> gtk;
    gtk +>:DependsOn:+> glib;
    tauri +>:DependsOn:+> tauri_runtime;
    tauri_runtime +>:DependsOn:+> wry;
    wry +>:DependsOn:+> tao;
    tao +>:DependsOn:+> webkit2gtk;
    tauri +>:DependsOn:+> tauri_utils;
    tauri_utils +>:DependsOn:+> urlpattern;
    urlpattern +>:DependsOn:+> unic;
    tauri +>:DependsOn:+> proc_macro_error;

    # Reachable from the upgraded gtk (0.20.0) which pulls glib 0.20.0.
    root ++> gtk_fixed;
    gtk_fixed +>:DependsOn:+> glib_fixed;

    print("== reachability probe for glib ==");
    probe = ReachabilityProbe(target="glib");
    root spawn probe;
    print(f"glib reachable from desktop root: {probe.found}");

    print("== full audit walk ==");
    auditor = Auditor();
    root spawn auditor;
    print(f"auditor findings: {auditor.findings}");
}
