"""Flight network: ticket prices on typed leg edges; a scout reports fares and each leg prints its share of the peak."""

node Airport {
    has name: str = "";
}

edge FlightLeg {
    has price: float = 0.0;

    def fraction_of(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.price / peak;
    }
}

walker Scout {
    has max_fare: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Airport entry {
        for leg in [edge here ->:FlightLeg:->] {
            report leg.price;
            if leg.price > self.max_fare {
                self.max_fare = leg.price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    nyc = Airport(name="NYC");
    ord_a = Airport(name="ORD");
    lax = Airport(name="LAX");
    sfo = Airport(name="SFO");

    root ++> nyc ++> ord_a ++> lax ++> sfo;
    nyc +>:FlightLeg(price=450.0):+> ord_a;
    ord_a +>:FlightLeg(price=320.0):+> lax;
    lax +>:FlightLeg(price=120.0):+> sfo;

    scout = root spawn Scout();
    peak = scout.max_fare;
    hubs = [nyc, ord_a, lax, sfo];

    for ap in hubs {
        for leg in [edge ap ->:FlightLeg:->] {
            for dst in [ap ->:FlightLeg:->] {
                share = leg.fraction_of(peak);
                print(f"{ap.name}->{dst.name}: {share:.2f} of peak ${peak:.0f} "
                      f"(${leg.price:.0f})");
            }
        }
    }
}
