    }
    out = buf.getvalue();

    assert res.rebalances == 1, f"got {res.rebalances}";
    assert res.splits == 1, f"got {res.splits}";
    assert len(res.visited) == 1, f"got {res.visited}";
    assert "cluster=C-retry size=10 -> SPLIT" in out, f"got {out}";
}
