"""Vet-clinic round: visit pets, give vaccines to those that need one today."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet starting the round");
        visit [-->];
    }

    can examine with Pet entry {
        label = f"{here.name} ({here.species})";
        self.patients.append(label);
        if here.needs_vaccine {
            print(f"  vaccinating {here.name} the {here.species}");
            self.shots_given += 1;
            here.needs_vaccine = False;
        } else {
            print(f"  {here.name} is up to date");
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=False)
        ++> Pet(name="Kiwi", species="parrot", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="rabbit", needs_vaccine=False);

    vet = Vet();
    root spawn vet;

    print(f"--- Round summary ---");
    print(f"Patients seen: {len(vet.patients)}");
    print(f"Shots given: {vet.shots_given}");
    print(f"List: {vet.patients}");
}
