Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""Plan-DAG: dependency-driven ordering via typed depends_on edges.

Walkers replace the hand-rolled recursive-DFS machinery: one walker
collects the plan's tasks (explicit visited guard, since jac walkers do
not dedupe), then derives execution order from the graph (Kahn's
algorithm over DependsOn edges) and flags any cycle — the moral
equivalent of graphlib's TopologicalSorter raising CycleError.
"""

node Task {
    has name: str = "";
    has done: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

walker Planner {
    has tasks: list[Task] = [];
    has seen: dict = {};
    has ordered: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can collect with Task entry {
        # jac walkers have no built-in once-per-node visitation:
        # the seen guard IS the cycle policy for collection.
        if here.name in self.seen {
            return;
        }
        self.seen[here.name] = True;
        self.tasks.append(here);
        visit [-->];
    }

    can finish with Root exit {
        # Kahn's algorithm over DependsOn edges: derived-from-graph order.
        indeg = {t.name: len([t->:DependsOn:->]) for t in self.tasks};
        dependents = {t.name: [] for t in self.tasks};
        for t in self.tasks {
            for d in [t->:DependsOn:->] {
                dependents[d.name].append(t.name);
            }
        }
        ready = [t.name for t in self.tasks if indeg[t.name] == 0];
        while len(ready) > 0 {
            current = ready.pop(0);
            self.ordered.append(current);
            for nxt in dependents[current] {
                indeg[nxt] -= 1;
                if indeg[nxt] == 0 {
                    ready.append(nxt);
                }
            }
        }
        if len(self.ordered) < len(self.tasks) {
            self.cycle_found = True;
            stuck = [t.name for t in self.tasks if t.name not in self.ordered];
            print(f"CycleError: tasks stuck in a cycle: {stuck}");
        } else {
            print(f"derived execution order: {self.ordered}");
            for t in self.tasks {
                if t.name in self.ordered {
                    t.done = True;
                    print(f"ran {t.name}");
                }
            }
        }
    }
}

with entry {
    auth = Task(name="auth");
    db = Task(name="db");
    api = Task(name="api");
    ui = Task(name="ui");
    docs = Task(name="docs");
    root ++> auth ++> db ++> api ++> ui ++> docs;
    # declared dependencies: api depends_on auth and db; ui and docs on api.
    # Note: list order above is NOT topological (api precedes its deps),
    # so the derived order differs from authored order — the issue's point.
    api +>:DependsOn(reason="needs tokens"):+> auth;
    api +>:DependsOn(reason="needs schema"):+> db;
    ui +>:DependsOn(reason="needs endpoints"):+> api;
    docs +>:DependsOn(reason="needs behavior"):+> api;
    root spawn Planner();
}
```

"""Tests for Plan-DAG walker — derived ordering, cycle detection, dedupe guard."""

import io;
import from contextlib { redirect_stdout }

test "derived order respects depends_on over list order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        auth = Task(name="auth");
        db = Task(name="db");
        api = Task(name="api");
        ui = Task(name="ui");
        docs = Task(name="docs");
        rt ++> auth ++> db ++> api ++> ui ++> docs;
        api +>:DependsOn(reason="needs tokens"):+> auth;
        api +>:DependsOn(reason="needs schema"):+> db;
        ui +>:DependsOn(reason="needs endpoints"):+> api;
        docs +>:DependsOn(reason="needs behavior"):+> api;
        res = rt spawn Planner();
    }
    out = buf.getvalue();
    # The issue's whole point: derived-from-graph order differs from
    # authored list order when list order is not topological.
    assert "derived execution order" in out, f"no derived-order banner: {out}";
    pos_auth = out.find("ran auth");
    pos_db = out.find("ran db");
    pos_api = out.find("ran api");
    pos_ui = out.find("ran ui");
    pos_docs = out.find("ran docs");
    assert -1 not in (pos_auth, pos_db, pos_api, pos_ui, pos_docs), f"missing ran line: {out}";
    assert pos_auth < pos_api and pos_db < pos_api, f"api ran before its deps auth/db: {out}";
    assert pos_api < pos_ui and pos_api < pos_docs, f"api must precede dependents ui/docs: {out}";
    # The program marks tasks done as part of the run.
    assert auth.done and db.done and api.done and ui.done and docs.done, "not all tasks marked done";
    assert res.cycle_found is False, f"clean DAG reported cycle: {out}";
}

test "cycle is reported and stuck tasks are not ran" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        a = Task(name="a");
        b = Task(name="b");
        c = Task(name="c");
        rt ++> a ++> b ++> c;
        a +>:DependsOn(reason="x"):+> b;
        b +>:DependsOn(reason="y"):+> c;
        c +>:DependsOn(reason="z"):+> a;
        res = rt spawn Planner();
    }
    out = buf.getvalue();
    assert "CycleError" in out, f"no CycleError printed: {out}";
    # All three are stuck in the cycle; none should be marked done.
    assert a.done is False and b.done is False and c.done is False, "cycle tasks should not be marked done";
    # The non-cycled ordering branch must not have fired.
    assert "derived execution order" not in out, f"derived-order branch fired on cycle: {out}";
    assert "ran a" not in out and "ran b" not in out and "ran c" not in out, "no task should have run";
    assert res.cycle_found is True, "cycle_found flag not set";
}

test "seen guard prevents duplicate collection when graph fans back" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        shared = Task(name="shared");
        leaf = Task(name="leaf");
        rt ++> shared ++> leaf;
        # Reverse edge: leaf has a DependsOn edge to shared, AND we add a
        # plain outgoing edge from shared back to leaf so the walker
        # reaches leaf twice via different paths. Without the seen guard
        # leaf would be collected twice.
        leaf +>:DependsOn(reason="leaf waits on shared"):+> shared;
        shared +>:DependsOn(reason="shared waits on leaf"):+> leaf;
        res = rt spawn Planner();
    }
    out = buf.getvalue();
    # CycleError path: collection guard fired, but ordering noticed the cycle.
    assert "CycleError" in out, f"expected CycleError: {out}";
    # The guard means each task appears in self.tasks exactly once — so
    # ordered list length equals task count, never more.
    assert len(res.tasks) == 2, f"expected 2 distinct tasks collected, got {len(res.tasks)}: {[t.name for t in res.tasks]}";
    names = [t.name for t in res.tasks];
    assert "shared" in names and "leaf" in names, f"missing task: {names}";
}

test "acyclic chain yields derived order matching dependency chain" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        first = Task(name="first");
        mid = Task(name="mid");
        last = Task(name="last");
        rt ++> first ++> mid ++> last;
        # Linear chain: first -> mid -> last via DependsOn.
        mid +>:DependsOn(reason="after first"):+> first;
        last +>:DependsOn(reason="after mid"):+> mid;
        res = rt spawn Planner();
    }
    out = buf.getvalue();
    assert "derived execution order" in out, f"no derived-order banner: {out}";
    pos_first = out.find("ran first");
    pos_mid = out.find("ran mid");
    pos_last = out.find("ran last");
    assert -1 not in (pos_first, pos_mid, pos_last), f"missing ran line: {out}";
    assert pos_first < pos_mid < pos_last, f"chain order wrong: first={pos_first} mid={pos_mid} last={pos_last} in {out}";
    assert res.ordered == ["first", "mid", "last"], f"ordered field wrong: {res.ordered}";
    assert res.cycle_found is False, f"linear chain flagged as cycle: {out}";
}

test "diamond dependency produces a valid topological order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        top = Task(name="top");
        left = Task(name="left");
        right = Task(name="right");
        bot = Task(name="bot");
        rt ++> top ++> left ++> right ++> bot;
        left +>:DependsOn(reason="from top"):+> top;
        right +>:DependsOn(reason="from top"):+> top;
        bot +>:DependsOn(reason="from left"):+> left;
        bot +>:DependsOn(reason="from right"):+> right;
        res = rt spawn Planner();
    }
    out = buf.getvalue();
    assert "derived execution order" in out, f"no derived-order banner: {out}";
    ordered = res.ordered;
    assert len(ordered) == 4, f"expected 4 tasks ordered, got {len(ordered)}: {ordered}";
    pos_top = ordered.index("top");
    pos_left = ordered.index("left");
    pos_right = ordered.index("right");
    pos_bot = ordered.index("bot");
    assert pos_top < pos_left and pos_top < pos_right, f"top must precede its dependents: {ordered}";
    assert pos_left < pos_bot and pos_right < pos_bot, f"both branches must precede bot: {ordered}";
    assert res.cycle_found is False, f"clean diamond flagged as cycle: {out}";
    # All four should be marked done since order was derived cleanly.
    assert top.done and left.done and right.done and bot.done, "diamond tasks not all marked done";
}

