"""Tests for BuildAuditor: diamond DAG with shared deps, each task counted once."""

import io;
import from contextlib { redirect_stdout }

test "diamond: total minutes equals sum of unique tasks" {
    core = Task(title="compile-core", minutes=10);
    utils = Task(title="compile-utils", minutes=8);
    compiler = Task(title="build-compiler", minutes=15);
    packager = Task(title="build-packager", minutes=12);

    compiler +>:Dep:+> core;
    compiler +>:Dep:+> utils;
    packager +>:Dep:+> core;
    packager +>:Dep:+> utils;

    root ++> compiler;
    root ++> packager;

    auditor = BuildAuditor();
    root spawn auditor;

    # 10 + 8 + 15 + 12 = 45, each counted exactly once.
    assert auditor.total == 45, f"expected 45 total minutes, got {auditor.total}";

    # visited must hold each task title exactly once (no diamond double-count).
    assert len(auditor.visited) == 4, f"expected 4 unique visits, got {len(auditor.visited)}";
    assert sorted(auditor.visited) == sorted(
        ["compile-core", "compile-utils", "build-compiler", "build-packager"]
    ), f"unexpected visited set: {auditor.visited}";
}

test "diamond: shared deps are marked skipped on second reach" {
    core = Task(title="compile-core", minutes=10);
    utils = Task(title="compile-utils", minutes=8);
    compiler = Task(title="build-compiler", minutes=15);
    packager = Task(title="build-packager", minutes=12);

    compiler +>:Dep:+> core;
    compiler +>:Dep:+> utils;
    packager +>:Dep:+> core;
    packager +>:Dep:+> utils;

    root ++> compiler;
    root ++> packager;

    buf = io.StringIO();
    auditor = BuildAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    # Each shared dep appears as audited once and skipped once across the diamond.
    assert "auditing compile-core (+10 min)" in out, f"missing core audit: {out}";
    assert "skipping compile-core (already counted)" in out, f"core never skipped: {out}";
    assert "auditing compile-utils (+8 min)" in out, f"missing utils audit: {out}";
    assert "skipping compile-utils (already counted)" in out, f"utils never skipped: {out}";
}

test "diamond: shared deps reachable from both compiler and packager" {
    core = Task(title="compile-core", minutes=10);
    utils = Task(title="compile-utils", minutes=8);
    compiler = Task(title="build-compiler", minutes=15);
    packager = Task(title="build-packager", minutes=12);

    compiler +>:Dep:+> core;
    compiler +>:Dep:+> utils;
    packager +>:Dep:+> core;
    packager +>:Dep:+> utils;

    root ++> compiler;
    root ++> packager;

    # compiler's deps
    comp_titles = sorted([d.title for d in [compiler ->:Dep:->]]);
    assert comp_titles == ["compile-core", "compile-utils"], f"compiler deps: {comp_titles}";

    # packager's deps
    pkg_titles = sorted([d.title for d in [packager ->:Dep:->]]);
    assert pkg_titles == ["compile-core", "compile-utils"], f"packager deps: {pkg_titles}";

    # core and utils must each be reachable from BOTH compiler and packager
    # (i.e. they are the shared diamond nodes).
    assert core in [compiler ->:Dep:->], "core must be a dep of compiler";
    assert core in [packager ->:Dep:->], "core must be shared dep of packager";
    assert utils in [compiler ->:Dep:->], "utils must be a dep of compiler";
    assert utils in [packager ->:Dep:->], "utils must be shared dep of packager";
}

test "linear chain: every node visited once, total sums correctly" {
    a = Task(title="task-a", minutes=3);
    b = Task(title="task-b", minutes=4);
    c = Task(title="task-c", minutes=5);

    root ++> a ++> b ++> c;

    auditor = BuildAuditor();
    root spawn auditor;

    assert auditor.total == 12, f"expected 12 minutes, got {auditor.total}";
    assert auditor.visited == ["task-a", "task-b", "task-c"], f"visit order: {auditor.visited}";
}

test "repeated titles across chain and branch are deduplicated" {
    # Two independent paths reaching the same node title — still counted once.
    shared = Task(title="shared-lib", minutes=7);
    branch1 = Task(title="branch-1", minutes=2);
    branch2 = Task(title="branch-2", minutes=3);

    # Two separate paths from root both ultimately need `shared`.
    root ++> branch1;
    root ++> branch2;
    branch1 +>:Dep:+> shared;
    branch2 +>:Dep:+> shared;

    auditor = BuildAuditor();
    root spawn auditor;

    # 2 + 3 + 7 = 12; shared must not be double-counted (would give 19).
    assert auditor.total == 12, f"expected 12 (no double count), got {auditor.total}";
    assert auditor.visited.count("shared-lib") == 1, f"shared counted >1: {auditor.visited}";
}

