```jac
"""Jenkins folder security blocks: model the multi-block drop bug and its fix.

The Terraform provider declared ``security`` as a SetNestedBlock with no size
validator, then read only element 0 — silently dropping additional blocks,
half-applying permissions, and breaking apply-time state consistency.

This demo models the same shape natively: each configured ``security`` block
is its own SecurityBlock node, connected to its Folder by a typed ``HasBlock``
edge. A walker that mimics the buggy write path drops everything past the
first block; a validating walker enforces the "exactly one block" contract
up front so apply never sees a mismatch.
"""

node Folder {
    has name: str = "";
}

node SecurityBlock {
    has inheritance_strategy: str = "";
    has permissions: list[str] = [];
}

edge HasBlock {
    has ordinal: int = 0;
}

# ---------------------------------------------------------------------------
# Buggy writer: mirrors the provider's `blocks[0]` read path. Anything past
# the first security block on the folder is silently dropped — exactly the
# behavior the issue is filing against.
# ---------------------------------------------------------------------------
walker BuggyWriter {
    has rendered_count: int = 0;
    has rendered_permissions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can write with Folder entry {
        # Visit the typed-edge children, but only take the first one.
        blocks = [here ->:HasBlock:->];
        if not blocks {
            visit [-->];
            disengage;
        }
        first = blocks[0];
        self.rendered_count = 1;
        self.rendered_permissions = first.permissions;
        # Note: no traversal of siblings, no diagnostic — the bug.
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Validating writer: enforces the "at most one security block" contract up
# front, the way the suggested fix proposes. Apply never sees a mismatched
# block count, so Jenkins state and Terraform state agree.
# ---------------------------------------------------------------------------
walker ValidatingWriter {
    has accepted: bool = False;
    has rendered_count: int = 0;
    has rendered_permissions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can validate with Folder entry {
        blocks = [here ->:HasBlock:->];
        if len(blocks) > 1 {
            print(
                f"[REJECT] folder {here.name} declares "
                f"{len(blocks)} security blocks; only one is allowed"
            );
            visit [-->];
            disengage;
        }
        self.accepted = True;
        if len(blocks) == 1 {
            first = blocks[0];
            self.rendered_count = 1;
            self.rendered_permissions = first.permissions;
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Counter walker: just counts security blocks attached to a folder, to make
# the "plan said 2, apply wrote 1" mismatch visible.
# ---------------------------------------------------------------------------
walker BlockCounter {
    has block_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can count with Folder entry {
        self.block_count = len([here ->:HasBlock:->]);
        visit [-->];
    }
}

with entry {
    # A folder with TWO security blocks — the configuration that triggers the bug.
    example = Folder(name="example");
    devs = SecurityBlock(
        inheritance_strategy="InheritParentStrategy",
        permissions=["hudson.model.Item.Read:devs"],
    );
    ci = SecurityBlock(
        inheritance_strategy="NonInheritingStrategy",
