"""Wheel-vs-source test coverage model.

Models the core scenario from issue #77: a CI job may build and install a
wheel, but tests still resolve the source tree because of a sys.path
insertion, so the *installed* artifact is never exercised. We lift this
into OSP by treating the install root, the source tree, and the test
runner as graph nodes, and walking the dependency chain with a walker
that reports which surface actually gets exercised.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Repo {
    has name: str = "";
    has build_ok: bool = True;
}

# The site-packages install root. `modules` is the set of module names the
# wheel claims to ship. `includes_module` captures whether the wheel's
# include/exclude list actually contains every required module.
node WheelInstall {
    has site_path: str = "";
    has modules: list[str] = [];
    has includes_module: bool = True;
}

# The source tree the dev runs `pytest` from. `prepends_src` mirrors the
# offending conftest behaviour: if True, source wins resolution over the
# installed wheel.
node SourceTree {
    has src_path: str = "";
    has modules: list[str] = [];
    has prepends_src: bool = False;
}

node TestRunner {
    has name: str = "";
    has surfaces_tested: list[str] = [];
}

# The CI job that owns the whole pipeline.
node CIJob {
    has name: str = "";
}

# A single test invocation result, used to report coverage.
node Coverage {
    has surface: str = "";
    has exercised: bool = False;
}

# ---------------------------------------------------------------------------
# Edge archetypes (typed: relationship carries meaning)
# ---------------------------------------------------------------------------

edge Builds {
    has artifact: str = "wheel";
}

edge Resolves {
    has precedence: int = 0;
}

edge Runs {
    has command: str = "pytest";
}

edge Owns {
    # no payload; CI just owns these sub-steps
}

edge Reports {
    has passed: bool = True;
}

# ---------------------------------------------------------------------------
# Walker: CI gate that exercises the installed wheel
# ---------------------------------------------------------------------------

walker CoverageGate {
    has visited: list[str] = [];
    has coverage_proven: bool = False;

    can start with Root entry {
        # CI spawns this walker on the root. Visit the CIJob to begin.
        visit [-->];
    }

    can enter_job with CIJob entry {
        print(f"[CI] job {here.name} beginning");
        self.visited.append(here.name);
        # Go to the things the CI job owns (build, run).
        visit [->:Owns:->];
    }

    can build_wheel with Repo entry {
        print(f"[CI] {here.name}: build_ok={here.build_ok}");
        self.visited.append(here.name);
        if not here.build_ok {
            disengage;
        }
        # Walk the build -> wheel install edge.
        visit [->:Builds:->];
    }

    can install_wheel with WheelInstall entry {
        # If the wheel omits a module, the installed artifact is broken.
        broken = not here.includes_module;
        print(
            f"[CI] wheel installed at {here.site_path}; "
            f"ships modules={here.modules}; "
            f"broken={broken}"
        );
        self.visited.append(here.site_path);
        if broken {
            disengage;
        }
        # Now look at what the source tree does to module resolution.
        visit [->:Resolves:->];
    }

    can check_source with SourceTree entry {
        if here.prepends_src {
            # The bug from #77: source tree shadows the installed wheel.
            print(
                f"[WARN] {here.src_path} prepends src/ to sys.path; "
                f"tests will import source, NOT the installed wheel"
            );
        }
        # Walk to the test runner that this source tree feeds.
        visit [->:Runs:->];
    }

    can run_tests with TestRunner entry {
        # Without the fix, the runner only ever sees the source surface.
        # With the fix (no prepend), the runner resolves the installed wheel.
        surface = "installed-wheel" if self.coverage_proven else "source-tree";
        here.surfaces_tested = [surface];
        print(f"[CI] tests exercised: {surface}");
        # Record coverage as a downstream node.
        cov = Coverage(surface=surface, exercised=True);
        here +>:Reports(passed=True):+> cov;
    }

    can report with Coverage entry {
        if here.exercised {
            self.coverage_proven = (here.surface == "installed-wheel");
        }
        # No further traversal; terminal node.
    }
}

# ---------------------------------------------------------------------------
# Walker: the broken-pinning probe from the QA gate (#72).
# ---------------------------------------------------------------------------

walker BrokenPinProbe {
    # If the build excludes a module, the installed wheel is broken
    # even though `pip install --dry-run` succeeds. We model the
    # fail-on-import behaviour of the QA gate's planted fault.
    has broken: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with WheelInstall entry {
        if not here.includes_module {
            self.broken = True;
            print(
                f"[PROBE] installed wheel at {here.site_path} would "
                f"raise on import: missing modules"
            );
            disengage;
        }
        # Otherwise nothing to probe; end the walk.
        disengage;
    }
}

# ---------------------------------------------------------------------------
# Demonstration graph
# ---------------------------------------------------------------------------

with entry {
    # ---- Scenario A: the BUGGY setup from issue #77 ----
    # Source tree prepending src/ shadows the wheel. Tests pass against
    # source code, the installed wheel is never exercised.
    repo_buggy = Repo(name="ModelTree", build_ok=True);
    wheel_buggy = WheelInstall(
        site_path="site-packages/modeltree",
        modules=["workflow", "graph", "exceptions"],
        includes_module=True,
    );
    src_buggy = SourceTree(
        src_path="tools/updater/src",
        modules=["workflow", "graph", "exceptions"],
        prepends_src=True,
    );
    runner_buggy = TestRunner(name="updater-pytest");
    job_buggy = CIJob(name="updater-tests");

    job_buggy +>:Owns:+> repo_buggy;
    repo_buggy +>:Builds:+> wheel_buggy;
    wheel_buggy +>:Resolves(precedence=10):+> src_buggy;
    src_buggy +>:Runs:+> runner_buggy;
    dummy_a = Coverage(surface="source-tree", exercised=True);
    runner_buggy +>:Reports:+> dummy_a;

    # ---- Scenario B: the FIXED setup ----
    # No sys.path prepend; tests resolve the installed wheel.
    repo_fixed = Repo(name="ModelTree", build_ok=True);
    wheel_fixed = WheelInstall(
        site_path="site-packages/modeltree",
        modules=["workflow", "graph", "exceptions"],
        includes_module=True,
    );
    src_fixed = SourceTree(
        src_path="tools/updater/src",
        modules=["workflow", "graph", "exceptions"],
        prepends_src=False,
    );
    runner_fixed = TestRunner(name="updater-pytest");
    job_fixed = CIJob(name="updater-tests");

    job_fixed +>:Owns:+> repo_fixed;
    repo_fixed +>:Builds:+> wheel_fixed;
    wheel_fixed +>:Resolves(precedence=10):+> src_fixed;
    src_fixed +>:Runs:+> runner_fixed;
    dummy_b = Coverage(surface="installed-wheel", exercised=True);
    runner_fixed +>:Reports:+> dummy_b;

    # ---- Scenario C: the broken-pinning QA probe from #72 ----
    # Wheel excludes a module. `pip install --dry-run` passes, the install
    # proceeds, but importing fails. With prepend fix in place, CI red.
    repo_bad = Repo(name="ModelTree", build_ok=True);
    wheel_bad = WheelInstall(
        site_path="site-packages/modeltree",
        modules=["workflow", "exceptions"],
        includes_module=False,
    );
    job_bad = CIJob(name="updater-tests");
    job_bad +>:Owns:+> repo_bad;
    repo_bad +>:Builds:+> wheel_bad;

    # ---- Run the gate on the BUGGY graph ----
    print("=== Scenario A: buggy conftest (source shadows wheel) ===");
    buggy_walker = CoverageGate();
    root spawn buggy_walker;

    print("\n=== Scenario B: fixed (tests resolve installed wheel) ===");
    fixed_walker = CoverageGate();
    root spawn fixed_walker;

    print("\n=== Scenario C: broken-pin probe (missing module) ===");
    probe = BrokenPinProbe();
    root spawn probe;
    print(f"probe detected broken wheel: {probe.broken}");
}
