"""Dependency audit walker: walks the production dependency graph and flags
advisories. Mirrors `pnpm audit` behavior where vulnerable packages reach
the runtime through transitive parents that Dependabot can't bump directly."""

node Package {
    has name: str = "";
    has version: str = "";
    has available_fix: bool = True;
}

node Advisory {
    has severity: str = "";
    has vulnerable_below: str = "";
    has patched: str = "";
    has path: str = "";
}

edge DependsOn {
    has transitive: bool = False;
}

edge Flagged {
    has reason: str = "";
}

walker Audit {
    has production_only: bool = True;
    has findings: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_deps with Package entry {
        next_versions: list = [v.version for v in [-->]];
        if here.available_fix {
            print(f"ok: {here.name}@{here.version} reachable");
        } else {
            print(f"STUCK: {here.name}@{here.version} no upstream PR");
            self.findings.append({
                "name": here.name,
                "version": here.version,
                "blocked": True
            });
        }
        visit [-->];
    }

    can collect_advisory with Advisory entry {
        flagged = [-->];
        if len(flagged) > 0 {
            print(f"ADVISORY[{here.severity}] {here.path} -> fix {here.patched}");
            self.findings.append({
                "advisory": here.path,
                "severity": here.severity,
                "patched": here.patched
            });
        }
        visit [-->];
    }
}

walker BumpFloor {
    has floor_version: str = "3.3.17";

    can start with Root entry {
        print(f"Raising floor to nanoid@{self.floor_version} via overrides");
        visit [-->];
    }

    can rewrite with Package entry {
        if here.name == "nanoid" and here.available_fix {
            print(f"Override: nanoid {here.version} -> {self.floor_version}");
        }
        visit [-->];
    }
}

with entry {
