```jac
"""Pedigree collapse predictor: incomplete-relation traversal with heuristic scoring.

Models a small family tree where some relation links (parents, spouses, siblings)
are missing, and a walker scans incomplete generational boundaries to rank the
highest-probability pedigree-collapse candidates. The traversal walks parents
up the ancestry and records each person node, accumulating a composite score
from geographic clustering, surname clustering, temporal recency, and record
density. Domain cycle policy: a guard set prevents infinite loops on cyclic
graphs (jac 0.36.1 walkers do not auto-dedupe), and a depth cap mirrors the
``max_depth`` parameter from the original service.
"""

node Place {
    has name: str = "";
    has neighbors: list[str] = [];

    def is_near(other: Place) -> bool {
        if other.name == self.name {
            return True;
        }
        for n in self.neighbors {
            if n == other.name {
                return True;
            }
        }
        return False;
    }
}

node Person {
    has given: str = "";
    has surname: str = "";
    has birth_year: int = 0;
    has occupation: str = "";
    has citations: int = 0;
    has birth_place: Place | None = None;
    has birth_place_inferred: bool = False;
    has missing_relations: list[str] = [];
    has score: float = 0.0;
}

edge ParentLink {
    has role: str = "parent";
}

edge SpouseLink { }

edge SiblingLink { }

walker CollapsePredictor {
    has tree_id: int = 1;
    has max_depth: int = 6;
    has limit: int = 10;
    has seen: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        self.seen = [];
        visit [-->];
    }

    can scan with Person entry {
        key = f"{here.given}|{here.surname}|{here.birth_year}";
        for s in self.seen {
            if s == key {
                visit [-->];
                return;
            }
        }
        self.seen = self.seen + [key];

        if self.depth > self.max_depth {
            visit [-->];
            return;
        }

        s_loc = self.location_score(here);
        s_sur = self.surname_score(here);
        s_tmp = self.temporal_score(here);
        s_rec = self.record_density_score(here);
        composite = s_loc + s_sur + s_tmp + s_rec;
        here.score = composite;

        for rel in here.missing_relations {
            kind = rel;
            label = "incomplete";
            print(
                f"[{label}] person={here.given} {here.surname} "
                f"missing={kind} score={composite:.2f} "
                f"(loc={s_loc:.2f} sur={s_sur:.2f} "
                f"tmp={s_tmp:.2f} rec={s_rec:.2f})"
            );
        }

        self.depth = self.depth + 1;
        visit [->:ParentLink:->];
        visit [->:SiblingLink:->];
    }

    def location_score(p: Person) -> float {
        if p.birth_place is None {
            return 0.0;
        }
        if p.birth_place_inferred {
            return 0.05;
        }
        return 0.25;
    }

    def surname_score(p: Person) -> float {
        score = 0.1;
        if p.surname == "Schmidt" or p.surname == "Mueller" {
            score = 0.2;
        }
        return score;
    }

    def temporal_score(p: Person) -> float {
        if p.birth_year >= 1850 {
            return 0.25;
        }
        if p.birth_year >= 1750 {
            return 0.15;
        }
        return 0.0;
    }

    def record_density_score(p: Person) -> float {
        score = 0.0;
        if p.occupation != "" {
            score = score + 0.05;
        }
        if p.citations >= 2 {
            score = score + 0.05;
        }
        return score;
    }
}

