import io;
import from contextlib { redirect_stdout }

test "passing release audit reports zero failures" {
    # A clean graph: all required gates pass, all artifacts are
    # deterministic with a non-zero size and a SHA-256, all required
    # licenses are bundled.
    root ++> Gate(name="unit-tests", passed=True, required=True);
    root ++> Gate(name="lint", passed=True, required=True);
    root ++> Gate(name="smoke", passed=True, required=True);
