        name="grapher.bundle.js",
        sha256="abc123def456abc123def456abc123def456abc123def456abc123def456abcd",
        byte_size=482310,
        deterministic=True
    );
    root ++> License(name="MIT-license.txt", present=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor();
    }

    assert res.failures == [], f"expected no failures on a clean release, got {res.failures}";
    assert res.artifact_ok == True, f"artifact_ok should be True, got {res.artifact_ok}";
    assert res.license_ok == True, f"license_ok should be True, got {res.license_ok}";
    assert len(res.visited_gates) == 3, f"expected 3 visited gates, got {res.visited_gates}";
    assert "unit-tests" in res.visited_gates, f"unit-tests missing from {res.visited_gates}";
    assert "lint" in res.visited_gates, f"lint missing from {res.visited_gates}";
    assert "smoke" in res.visited_gates, f"smoke missing from {res.visited_gates}";
}

test "failing required gate is recorded as GATE-FAIL" {
    # A required gate that has not passed must surface as a failure
    # and must NOT print the [gate-ok] marker.
    root ++> Gate(name="unit-tests", passed=True, required=True);
    root ++> Gate(name="chromium-smoke", passed=False, required=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor();
    }

    out = buf.getvalue();
    assert "[gate-ok] unit-tests" in out, f"unit-tests should be reported ok: {out}";
    assert "[gate-ok] chromium-smoke" not in out, f"failing gate should not print ok: {out}";
    assert any("GATE-FAIL" in f and "chromium-smoke" in f for f in res.failures), (
        f"expected GATE-FAIL for chromium-smoke, got {res.failures}"
    );
    assert "chromium-smoke" in res.visited_gates, (
        f"failing gate must still be visited (audit must see it), got {res.visited_gates}"
    );
}

test "optional gate that fails is not flagged" {
    # An optional gate (required=False) that fails must NOT be reported
    # as a failure -- it is informational only.
    root ++> Gate(name="nice-to-have", passed=False, required=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor();
    }

    assert res.failures == [], (
        f"optional gate failure must not block release, got {res.failures}"
    );
    assert "nice-to-have" in res.visited_gates, (
        f"optional gate should still be visited, got {res.visited_gates}"
    );
}

test "flaky artifact with missing sha and zero size fails three checks" {
    # An artifact that is non-deterministic AND has an empty sha AND has
    # a non-positive byte size must produce one failure per violated
    # invariant and flip artifact_ok to False.
    root ++> Artifact(name="flaky.artifact", sha256="", byte_size=0, deterministic=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor();
    }

    assert res.artifact_ok == False, (
        f"artifact_ok should be False for flaky artifact, got {res.artifact_ok}"
    );
    assert any("ARTIFACT-FAIL" in f and "flaky.artifact" in f and "byte-deterministic" in f for f in res.failures), (
        f"expected determinism failure, got {res.failures}"
    );
    assert any("ARTIFACT-FAIL" in f and "flaky.artifact" in f and "byte size" in f for f in res.failures), (
        f"expected byte-size failure, got {res.failures}"
    );
    assert any("ARTIFACT-FAIL" in f and "flaky.artifact" in f and "SHA-256" in f for f in res.failures), (
        f"expected sha-256 failure, got {res.failures}"
    );
}

test "missing license produces LICENSE-FAIL and flips license_ok" {
    # A license that is not bundled with the ship must be reported as a
    # license failure and flip license_ok to False.
    root ++> License(name="GPL-notice.txt", present=False);
    root ++> License(name="MIT-license.txt", present=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor();
    }

    out = buf.getvalue();
    assert res.license_ok == False, f"license_ok should be False, got {res.license_ok}";
    assert "[license-ok] MIT-license.txt" in out, f"present license should be ok: {out}";
    assert "[license-ok] GPL-notice.txt" not in out, f"missing license should not print ok: {out}";
    saw_license_fail = False;
    for f in res.failures {
        if "LICENSE-FAIL" in f and "GPL-notice.txt" in f {
            saw_license_fail = True;
        }
    }
    assert saw_license_fail, f"expected LICENSE-FAIL for GPL-notice.txt, got {res.failures}";
}

