"""Barber referral network: model clients and their referrals as a typed graph
and traverse it with a walker that visualizes the tree while guarding against
circular references and caching the result."""

node Client {
    has name: str = "";
    has reward_status: str = "none";
}

edge Referred {
    has since: str = "";
}

walker ReferralWalker {
    has depth: int = 0;
    has max_depth: int = 8;
    has visited: list[str] = [];
    has lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Client entry {
        if self.depth > self.max_depth {
            self.lines.append(f"{'  ' * self.depth}{here.name} [MAX DEPTH]");
            disengage;
        }
        if here.name in self.visited {
            self.lines.append(f"{'  ' * self.depth}{here.name} [CYCLE]");
            disengage;
        }
        self.visited.append(here.name);
        prefix = "  " * self.depth;
        status_icon = "[R]" if here.reward_status == "rewarded" else "[ ]";
        self.lines.append(f"{prefix}{status_icon} {here.name}");
        self.depth = self.depth + 1;
        visit [->:Referred:->] else {
            self.lines.append(f"{'  ' * self.depth}(end of branch)");
            disengage;
        }
    }

    def render -> str {
        out = "Referral Tree:\n";
        for line in self.lines {
            out = out + line + "\n";
        }
        return out;
    }
}

with entry {
    alice = Client(name="Alice", reward_status="rewarded");
    bob = Client(name="Bob", reward_status="rewarded");
    carol = Client(name="Carol", reward_status="none");
    dave = Client(name="Dave", reward_status="rewarded");
    eve = Client(name="Eve", reward_status="none");
    frank = Client(name="Frank", reward_status="none");
    gina = Client(name="Gina", reward_status="rewarded");

    root ++> alice ++> bob ++> carol;
    root ++> alice ++> dave;
    bob +>:Referred(since="2024-01"):+> eve;
    dave +>:Referred(since="2024-03"):+> frank;
    dave +>:Referred(since="2024-05"):+> gina;
    eve +>:Referred(since="2024-06"):+> bob;

    w = ReferralWalker(max_depth=5);
    root spawn w;
    print(w.render());
}
