```jac
"""Hiking trail: a chain of waypoints from trailhead to summit with a hiker walker."""

node Waypoint {
    has label: str = "";
    has elevation: int = 0;
}

node Summit {
    has label: str = "Summit";
    has elevation: int = 1000;
}

walker Hiker {
    has stops_made: int = 0;
    has target_stops: int = 4;

    can start with Root entry {
        print("Hiker begins the ascent from the trailhead.");
        visit [-->];
    }

    can hike with Waypoint entry {
        self.stops_made += 1;
        label = "Stop" if self.stops_made < self.target_stops else "Final";
        print(f"Stop #{self.stops_made}: {here.label} at {here.elevation}m ({label})");
        visit [-->];
    }

    can summit with Summit entry {
        self.stops_made += 1;
        print(f"Stop #{self.stops_made}: reached {here.label} at {here.elevation}m!");
        print(f"Trail complete after {self.stops_made} stops. The hiker made it.");
    }
}

with entry {
    root ++> Waypoint(label="Trailhead Bend", elevation=100)
        ++> Waypoint(label="Creek Crossing", elevation=300)
        ++> Waypoint(label="Pine Ridge", elevation=550)
        ++> Waypoint(label="Rocky Ledge", elevation=750)
        ++> Summit();
    root spawn Hiker();
}
