```jac
"""Reaper fail-open demo: stale workflow roots accumulate when the count path
silently treats a query timeout as "nothing to reap." Two walkers expose the
two composing root causes from issue #22:
  - Reachability walker (A): walks workflow descendants to decide if a root
    has any live descendants; an unreachable frontier must NOT be read as
    "empty."
  - Depth-bounded sweep (B): caps the descendant walk so the cost cannot
    run unbounded against issue + wisp + dependency volume.
The demo shows: (1) a small graph where the walker correctly distinguishes
"no descendants" from "walk timed out / failed," and (2) that the fail-closed
counter never silently collapses a failure into zero.
"""

node Issue {
    has title: str = "";
    has kind: str = "task";
    has live: bool = True;
}

node Wisp {
    has title: str = "";
    has live: bool = True;
}

node WorkflowRoot {
    has title: str = "";
    has stale: bool = True;
}

edge DependsOn { has weight: int = 1; }
edge Spawns { }
edge BelongsTo { }

# Tri-state reachability check: "live", "empty", or "unknown" (fail-closed).
# This is fix-candidate A: a count path that CANNOT collapse a failure into
# zero. The walker treats "unknown" as do-not-conclude-empty.
walker ReachabilityChecker {
    has budget: int = 5;
    has simulate_failure: bool = False;
    has outcome: str = "";

    can begin with WorkflowRoot entry {
        if self.simulate_failure {
            print(f"  walk error: simulated CTE timeout on {here.title}");
            self.outcome = "unknown";
            disengage;
        }
        visited: list = [];
        frontier: list = [here];
        seen: set = {id(here)};
        hops = 0;
        while frontier and hops < self.budget {
            nxt: list = [];
            for n in frontier {
                for c in [n->:DependsOn:->] {
                    if id(c) not in seen {
                        seen.add(id(c));
                        visited.append(c);
                        nxt.append(c);
                    }
                }
                for c in [n->:Spawns:->] {
                    if id(c) not in seen {
                        seen.add(id(c));
                        visited.append(c);
                        nxt.append(c);
                    }
                }
            }
            frontier = nxt;
            hops += 1;
        }
        verdict = "empty";
        for d in visited {
            if d.live {
                verdict = "live";
                break;
            }
        }
        self.outcome = verdict;
    }
}

walker CountReaper {
    has unknown: int = 0;
    has known_empty: int = 0;
    has known_live: int = 0;
    has stale_roots: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Walk all roots and ask: does this root have any live descendants?
    # The decision path uses ReachabilityChecker and respects its
    # tri-state outcome. A failure is "unknown," never "empty."
    can sweep with WorkflowRoot entry {
        checker = ReachabilityChecker(budget=5, simulate_failure=False);
        checker spawn here;
        outcome = checker.outcome;
        if outcome == "unknown" {
            self.unknown += 1;
            print(f"[FAIL-CLOSED] {here.title}: walk incomplete, treating as UNKNOWN (do NOT conclude empty)");
        } elif outcome == "empty" {
            self.known_empty += 1;
            print(f"[KNOWN-EMPTY] {here.title}: no live descendants, reaping");
            self.stale_roots.append(here.title);
        } else {
            self.known_live += 1;
            print(f"[LIVE] {here.title}: has live descendants, skipping");
        }
        visit [-->];
    }
}

walker DepthBoundedSweep {
    has max_depth: int = 4;

    can start with Root entry {
        visit [-->];
    }

    # Bound the descendant walk (fix candidate B). No unbounded recursion;
    # cycle safety via an explicit guard set (jac 0.36.1 walkers have no
    # built-in once-per-node visitation).
    can bounded with WorkflowRoot entry {
        out: list = [];
        frontier: list = [here];
        seen: set = {id(here)};
        depth = 0;
        while frontier and depth < self.max_depth {
            nxt: list = [];
            for n in frontier {
                for c in [n->:DependsOn:->] {
                    if id(c) not in seen {
                        seen.add(id(c));
                        out.append(c);
                        nxt.append(c);
                    }
                }
                for c in [n->:Spawns:->] {
                    if id(c) not in seen {
                        seen.add(id(c));
                        out.append(c);
                        nxt.append(c);
                    }
                }
            }
            frontier = nxt;
            depth += 1;
        }
        print(f"  visited {len(out)} descendant(s) from {here.title} within depth {self.max_depth}:");
        for n in out {
            print(f"    - {n.title} (live={n.live})");
        }
        visit [-->];
    }
}

walker SimulateTimeout {
    has failures_recorded: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # Demonstrates the fail-open BUG: the old wrapper collapsed a failure
    # into a count of zero. Here we show the proper fail-closed behavior.
    can buggy_then_fixed with WorkflowRoot entry {
        checker_old = ReachabilityChecker(budget=5, simulate_failure=True);
        checker_old spawn here;
        # OLD behavior: collapse "unknown" into 0 (bug).
        bogus_count = 0 if checker_old.outcome == "unknown" else 1;
        print(f"  [OLD] {here.title}: query_failed={checker_old.outcome == 'unknown'}, count_read_as={bogus_count}");

        checker_new = ReachabilityChecker(budget=5, simulate_failure=True);
        checker_new spawn here;
        # NEW behavior: keep "unknown" distinct, refuse to conclude empty.
        if checker_new.outcome == "unknown" {
            self.failures_recorded += 1;
            print(f"  [NEW] {here.title}: outcome=UNKNOWN, refusing to reap");
        }
        visit [-->];
    }
}

with entry {
    # Graph: two workflow roots. Root "alpha" has live descendants
    # (issue + wisp). Root "beta" is truly stale (no live descendants).
    # The fail-closed counter must report beta as KNOWN-EMPTY and
    # must NOT silently treat a future timeout as empty.
    alpha = WorkflowRoot(title="alpha");
    beta = WorkflowRoot(title="beta");
    root ++> alpha ++> beta;

    i1 = Issue(title="i1", kind="task", live=True);
    i2 = Issue(title="i2", kind="task", live=False);
    w1 = Wisp(title="w1", live=True);
    alpha +>:Spawns:+> i1;
    alpha +>:DependsOn:+> i2;
    i1 +>:Spawns:+> w1;

    print("=== Reachability sweep (fix A: fail-closed count path) ===");
    r = CountReaper();
    root spawn r;
    print(f"\nreaper totals: known_empty={r.known_empty}, "
          f"known_live={r.known_live}, "
          f"unknown={r.unknown}, stale_roots={r.stale_roots}");

    print("\n=== Depth-bounded descendant sweep (fix B: bound the CTE) ===");
    s = DepthBoundedSweep(max_depth=3);
    root spawn s;

    print("\n=== Fail-open vs fail-closed (old vs new count wrapper) ===");
    t = SimulateTimeout();
    root spawn t;
    print(f"\ntimeout failures recorded (refused to be collapsed): {t.failures_recorded}");

    print("\n=== Key: a count of 0 from 'unknown' is a BUG. ===");
    print("=== The reaper above reports 'unknown' separately and refuses to act. ===");
}
