    checker spawn [rt ->:Spawns:->][?:WorkflowRoot] if False else checker spawn rf;
    out_holder = io.StringIO();
    with redirect_stdout(out_holder) {
        checker2 = ReachabilityChecker(budget=5, simulate_failure=True);
        checker2 spawn rf;
    }
    assert checker2.outcome == "unknown", f"simulated failure must yield 'unknown', got {checker2.outcome}"
        ;
}

test "depth-bounded sweep respects max_depth and lists descendants" {
    rt = Root();
    long_chain = WorkflowRoot(title="long");
    rt ++> long_chain;

    # Build a chain: long -> n1 -> n2 -> n3 -> n4 (4 hops from root)
    n1 = Issue(title="n1", kind="task", live=True);
    n2 = Issue(title="n2", kind="task", live=True);
    n3 = Wisp(title="n3", live=True);
    n4 = Issue(title="n4", kind="task", live=True);
    long_chain +>:Spawns:+> n1;
    n1 +>:DependsOn:+> n2;
    n2 +>:Spawns:+> n3;
    n3 +>:DependsOn:+> n4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        s = DepthBoundedSweep(max_depth=2);
        rt spawn s;
    }
    out = buf.getvalue();

    # At max_depth=2 from `long`, we should see n1 (hop 1) and n2 (hop 2),
    # but NOT n3 or n4 (hops 3-4 cut off by the bound).
    assert "visited" in out and "from long" in out, f"missing depth-bounded header: {out}";
    assert "n1 (live=True)" in out, f"expected n1 inside bound: {out}";
    assert "n2 (live=True)" in out, f"expected n2 inside bound: {out}";
    assert "n3 (live=True)" not in out, f"n3 should be cut off by depth=2: {out}";
    assert "n4 (live=True)" not in out, f"n4 should be cut off by depth=2: {out}";

    # A deeper budget should reach further down the same chain.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        s2 = DepthBoundedSweep(max_depth=4);
        rt spawn s2;
    }
    out2 = buf2.getvalue();
    assert "n3 (live=True)" in out2, f"n3 should be reachable at depth=4: {out2}";
    assert "n4 (live=True)" in out2, f"n4 should be reachable at depth=4: {out2}";
}

test "reachability checker tri-state: live vs empty vs unknown" {
    rt = Root();
    has_live = WorkflowRoot(title="has_live");
    truly_empty = WorkflowRoot(title="truly_empty");
    rt ++> has_live;
    rt ++> truly_empty;

    # has_live: live descendant reachable via Spawns
    live_issue = Issue(title="li", kind="task", live=True);
    dead_issue = Issue(title="di", kind="task", live=False);
    has_live +>:Spawns:+> live_issue;
    has_live +>:DependsOn:+> dead_issue;

    # truly_empty: no descendants at all

    buf = io.StringIO();
    with redirect_stdout(buf) {
        ck1 = ReachabilityChecker(budget=5, simulate_failure=False);
        ck1 spawn has_live;

        ck2 = ReachabilityChecker(budget=5, simulate_failure=False);
        ck2 spawn truly_empty;

        ck3 = ReachabilityChecker(budget=5, simulate_failure=True);
        ck3 spawn has_live;
    }
    out = buf.getvalue();

    assert ck1.outcome == "live", f"has_live must read 'live', got {ck1.outcome}";
    assert ck2.outcome == "empty", f"truly_empty must read 'empty', got {ck2.outcome}";
    assert ck3.outcome == "unknown", f"simulated failure must read 'unknown', got {ck3.outcome}";
    assert "simulated CTE timeout on has_live" in out, f"missing timeout log: {out}";
}

