"""Gallery security console.

Every visitor entering a room is logged generically, but when a curator walks
in, the room additionally records an official inspection under the curator's
name and counts how many rooms they inspected. A tourist visits two rooms
without triggering any inspection record; a curator visits the same two rooms
and the rooms stamp them as inspector.
"""

node Room {
    has name: str = "";
    has log: list[str] = [];
    has inspectors: list[str] = [];
}

walker Tourist {
    has visitor_name: str = "Guest";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.visitor_name}");
        print(f"[log] {self.visitor_name} entered {here.name}");
        visit [-->];
    }
}

walker Curator {
    has visitor_name: str = "Curator";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.visitor_name}");
        here.inspectors.append(self.visitor_name);
        self.rooms_inspected += 1;
        print(f"[log] {self.visitor_name} entered {here.name} (inspection recorded)");
        visit [-->];
    }
}

with entry {
    room_a = Room(name="Modern Hall");
    room_b = Room(name="Sculpture Garden");
    root ++> room_a ++> room_b;

    root spawn Tourist(visitor_name="Alice");
    root spawn Curator(visitor_name="Dr. Bell");

    print(f"\nRoom A log: {room_a.log}");
    print(f"Room A inspectors: {room_a.inspectors}");
    print(f"Room B log: {room_b.log}");
    print(f"Room B inspectors: {room_b.inspectors}");
}
