"""Quiz grader: a walker that collects strictly-typed integer scores across quiz nodes."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.scores.append(here.score);
        visit [-->];
    }

    can summarize with Root exit {
        if len(self.scores) > 0 {
            total = 0;
            for s in self.scores {
                total = total + s;
            }
            average = total / len(self.scores);
            print(f"Scores collected: {self.scores}");
            print(f"Class average: {average}");
        } else {
            print("No quizzes to grade.");
        }
        report self.scores;
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=72)
        ++> Quiz(student="Carla", score=95)
        ++> Quiz(student="Dimitri", score=61)
        ++> Quiz(student="Eve", score=80);
    root spawn Grader();
}
