"""Native graph demo for lineage contamination invalidation and cycle safety."""

node Namespace {
    has title: str = "";
}

node Memory {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has memory_id: int = 0;
    has contaminated: bool = False;
    has walk_epoch: int = 0;
}

edge Contains { }

edge DerivedFrom {
    has instant: int = 0;
}

walker InvalidationSweep {
    has epoch: int = 1;
    has contaminated_count: int = 0;
    has cycle_count: int = 0;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can enter with Namespace entry {
        visit [->:Contains:->] else { disengage; }
    }

    can invalidate with Memory entry {
        if here.walk_epoch == self.epoch {
            self.cycle_count += 1;
            print(f"cycle blocked at memory {here.memory_id}");
        } else {
            here.walk_epoch = self.epoch;
            here.contaminated = True;
            self.contaminated_count += 1;
            print(f"contaminated memory {here.memory_id}: {here.title}");
            visit [->:DerivedFrom:->] else { disengage; }
        }
    }

    can summarize with Root exit {
        print(f"invalidated {self.contaminated_count} memories; blocked {self.cycle_count} cycle edge(s)");
    }
}

with entry {
    catalog = Namespace(title="alphaonedev memory graph");
    origin = Memory(memory_id=1, title="root event", year=2024);
    derived = Memory(memory_id=2, title="derived event", year=2024);
    leaf = Memory(memory_id=3, title="contaminated leaf", year=2024);

    root ++> catalog;
    catalog +>:Contains:+> origin;
    origin +>:DerivedFrom(instant=100):+> derived;
    derived +>:DerivedFrom(instant=101):+> leaf;
    leaf +>:DerivedFrom(instant=102):+> derived;

    root spawn InvalidationSweep(epoch=1);
}
