"""Tests for the Hiking trail Hiker walker."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh trail chain from a list of waypoint titles.
# Returns the root so we can spawn the Hiker on it.
def build_trail(waypoint_titles: list) {
    # First, link the trailhead
    th = TrailHead(title="Trailhead");
    root ++> th;

    cur = th;
    for (title,) in [(t,) for t in waypoint_titles] {
        wp = Waypoint(title=title);
        cur ++> wp;
        cur = wp;
    }
    # Finally, the summit
    sm = Summit(title="Summit");
    cur ++> sm;
    return root;
}

test "hiker counts each waypoint stop and prints stop numbers" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = build_trail(["WP-A", "WP-B", "WP-C"]);
        res = rt spawn Hiker();
    }
    out = buf.getvalue();

    # Stop numbers should be printed in order, one per waypoint.
    assert "Stop 1" in out, f"missing Stop 1 in: {out!r}";
    assert "Stop 2" in out, f"missing Stop 2 in: {out!r}";
    assert "Stop 3" in out, f"missing Stop 3 in: {out!r}";

    # And the walker should record the count of waypoints it passed.
    assert res.stops == 3, f"expected 3 stops recorded, got {res.stops}";
}

test "hiker prints completion line with waypoint count and disengages" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = build_trail(["WP-A", "WP-B"]);
        res = rt spawn Hiker();
    }
    out = buf.getvalue();

    # Completion line uses the live count of waypoints passed.
    assert "Trail complete" in out, f"missing completion line in: {out!r}";
    assert "passed 2 waypoints" in out, f"missing count in completion line: {out!r}";

    # No further stops should be printed after the completion line.
    # The Hiker disengages at Summit, so no extra "Stop" lines beyond #2.
    assert out.count("Stop ") == 2, f"unexpected extra stops printed: {out!r}";
}

test "trail graph shape: trailhead -> waypoints -> summit from root" {
    rt = build_trail(["A", "B", "C", "D"]);

    # From root, the first outgoing node is the TrailHead.
    children = [rt-->];
    assert len(children) == 1, f"root should have 1 child, got {len(children)}";
    th = children[0];
    assert isinstance(th, TrailHead), f"first child should be TrailHead, got {type(th)}";

    # TrailHead has 1 outgoing (first waypoint), and the chain continues.
    th_children = [th-->];
    assert len(th_children) == 1, f"TrailHead should have 1 child, got {len(th_children)}";

    # Walk forward and count waypoints until we hit the Summit.
    cur = th;
    wp_count = 0;
    while True {
        nxt = [cur-->];
        if not nxt {
            assert False, f"chain dead-ended before summit at {cur}";
        }
        nxt_node = nxt[0];
        if isinstance(nxt_node, Summit) {
            break;
        }
        assert isinstance(nxt_node, Waypoint), f"unexpected node type {type(nxt_node)}";
        wp_count += 1;
        cur = nxt_node;
    }
    assert wp_count == 4, f"expected 4 waypoints in chain, counted {wp_count}";
}

test "hiker on empty waypoint trail passes zero waypoints" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        # Trailhead directly to Summit — no waypoints at all.
        th = TrailHead();
        sm = Summit();
        root ++> th ++> sm;
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # No stop markers should appear.
    assert "Stop " not in out, f"unexpected stop marker in: {out!r}";

    # Completion line still runs and reports zero waypoints.
    assert "Trail complete" in out, f"missing completion line in: {out!r}";
    assert "passed 0 waypoints" in out, f"expected 'passed 0 waypoints' in: {out!r}";

    assert res.stops == 0, f"expected 0 stops recorded, got {res.stops}";
}

