    has alive: bool = True;
}

edge Imports {
    has weight: int = 1;
}

walker Auditor {
    has visited: list[str] = [];
    has orphans: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Component entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            kids = [here->:Imports:->];
            if not kids and not here.alive {
                self.orphans.append(here.name);
            }
            visit [->:Imports:->];
        }
    }

    can report with Root entry {
        print(f"Visited {len(self.visited)} components");
        if self.orphans {
            print(f"Orphans ready for removal: {', '.join(self.orphans)}");
        } else {
            print("No orphans detected.");
        }
        print(f"Kept live: Bar.vue, Circle.vue");
    }
}

with entry {
    bar = Component(name="Bar.vue", kind="graph-base", alive=True);
    circle = Component(name="Circle.vue", kind="graph-base", alive=True);
    half_circle = Component(name="HalfCircle.vue", kind="graph-orphan", alive=False);
    line_plot = Component(name="LinePlot.vue", kind="graph-orphan", alive=False);
    progress_arc = Component(name="ProgressArc.vue", kind="graph-orphan", alive=False);
