    root ++> count_gauge +>:Imports:+> circle;

    root ++> half_circle;
    root ++> line_plot;
    root ++> progress_arc;
    root ++> aspect;

    auditor = Auditor();
    root spawn auditor;
    root spawn Auditor();
    print(f"Final report — visited: {auditor.visited}");
}
