"""Order auditor: skip invalid orders but halt the walk immediately on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
            } else {
                print(f"[AUDIT] valid order amount={here.amount}");
            }
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=50, valid=False, fraud=False)
        ++> Order(amount=200, valid=True, fraud=False)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=75, valid=True, fraud=False);
    root spawn OrderAuditor();
}
