import from contextlib { redirect_stdout }

test "chain of three pets records two shots" {
    root ++> Pet(name="Buddy", species="dog", needs_vaccine=True)
        ++> Pet(name="Whiskers", species="cat", needs_vaccine=False)
        ++> Pet(name="Max", species="dog", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    out = buf.getvalue();

    assert "Starting clinic round" in out, f"missing start marker: {out}";
    assert "Vaccinated Buddy (dog)" in out, f"missing Buddy shot line: {out}";
    assert "Checked Whiskers (cat) — no shot needed" in out, f"missing Whiskers check line: {out}";
    assert "Vaccinated Max (dog)" in out, f"missing Max shot line: {out}";

    assert len(res.patient_names) == 3, f"got patients {res.patient_names}";
    assert res.patient_names == ["Buddy", "Whiskers", "Max"], f"got order {res.patient_names}";
    assert res.shots_given == 2, f"got shots {res.shots_given}";
}

test "no pets visited when graph has no pet children" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    out = buf.getvalue();

    assert "Starting clinic round" in out, f"missing start marker: {out}";
    assert len(res.patient_names) == 0, f"got patients {res.patient_names}";
    assert res.shots_given == 0, f"got shots {res.shots_given}";
}

test "all pets needing shots increments count per pet" {
    root ++> Pet(name="A", species="dog", needs_vaccine=True)
        ++> Pet(name="B", species="cat", needs_vaccine=True)
        ++> Pet(name="C", species="dog", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    out = buf.getvalue();

    assert res.shots_given == 3, f"got shots {res.shots_given}";
    assert len(res.patient_names) == 3, f"got patients {res.patient_names}";
    assert out.count("Vaccinated") == 3, f"got output {out}";
}

test "no pets needing shots gives zero vaccines" {
    root ++> Pet(name="A", species="dog", needs_vaccine=False)
        ++> Pet(name="B", species="cat", needs_vaccine=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    out = buf.getvalue();

    assert res.shots_given == 0, f"got shots {res.shots_given}";
    assert len(res.patient_names) == 2, f"got patients {res.patient_names}";
    assert "no shot needed" in out, f"got output {out}";
    assert "Vaccinated" not in out, f"got output {out}";
}

test "direct fan out of pets from root visits each" {
    root ++> Pet(name="X", species="rabbit", needs_vaccine=True);
    root ++> Pet(name="Y", species="bird", needs_vaccine=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }

    assert len(res.patient_names) == 2, f"got patients {res.patient_names}";
    assert res.shots_given == 1, f"got shots {res.shots_given}";
    assert "X" in res.patient_names, f"got {res.patient_names}";
    assert "Y" in res.patient_names, f"got {res.patient_names}";
}

