"""Order auditor with two early-return flavors side by side.

Invalid orders are skipped (audit continues), but a fraud-flagged order
halts the whole walk immediately. A line is printed per visited order
showing which action fired.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud detected on order amount={here.amount}");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] invalid order amount={here.amount}");
            visit [-->];
        }
        print(f"[OK] audited order amount={here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=250.0, valid=False, fraud=False)
        ++> Order(amount=75.0, valid=True, fraud=True)
        ++> Order(amount=300.0, valid=True, fraud=False);
    root spawn OrderAuditor();
}
