"""Tests for OrderAuditor: skip on invalid vs halt on fraud."""

import io;
import from contextlib { redirect_stdout }

test "fraud halts walk immediately" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=250.0, valid=False, fraud=False)
        ++> Order(amount=75.0, valid=True, fraud=True)
        ++> Order(amount=300.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] fraud detected on order amount=75.0" in out, f"missing HALT line: {out}";
    # After halt, later valid order must NOT be audited.
    assert "[OK] audited order amount=300.0" not in out, f"walk did not stop on fraud: {out}";
    # Fraud order itself should not be reported as OK.
    assert "[OK] audited order amount=75.0" not in out, f"fraud order was audited as OK: {out}";
}

test "invalid is skipped but walk continues" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=250.0, valid=False, fraud=False)
        ++> Order(amount=300.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK] audited order amount=100.0" in out, f"missing first OK: {out}";
    assert "[SKIP] invalid order amount=250.0" in out, f"missing SKIP line: {out}";
    assert "[OK] audited order amount=300.0" in out, f"walk did not continue past invalid: {out}";
}

test "all valid no fraud walks all orders" {
    root ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=True, fraud=False)
        ++> Order(amount=30.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK] audited order amount=10.0" in out, f"missing first OK: {out}";
    assert "[OK] audited order amount=20.0" in out, f"missing second OK: {out}";
    assert "[OK] audited order amount=30.0" in out, f"missing third OK: {out}";
    assert "[SKIP]" not in out, f"unexpected skip line: {out}";
    assert "[HALT]" not in out, f"unexpected halt line: {out}";
}

test "fraud as first order halts with no other output" {
    root ++> Order(amount=42.0, valid=True, fraud=True)
        ++> Order(amount=99.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] fraud detected on order amount=42.0" in out, f"missing HALT: {out}";
    assert "[OK] audited order amount=99.0" not in out, f"walk continued after fraud: {out}";
    assert "[SKIP]" not in out, f"unexpected skip: {out}";
}

