"""Persistent world storage demo with bounded traversal and explicit cycle safety."""

node StorageChest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has world_id: str = "";
    has integrity: int = 100;
    has destroyed: bool = False;
