        if (here.container_id in self.seen_ids) {
            print(f"cycle guard: container {here.container_id} already visited");
        } else {
            self.seen_ids.append(here.container_id);
            print(f"canonical container {here.container_id}: {here.occupied_slots}/{here.capacity} slots");
            print(f"access request by {self.actor_id}: {here.access_mode}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_item with ItemStack entry {
        if (here.stack_id in self.seen_ids) {
            print(f"cycle guard: item {here.stack_id} already visited");
        } else {
            self.seen_ids.append(here.stack_id);
            self.item_count += 1;
            print(f"item {here.stack_key} x{here.quantity}: canonical contents retained");
        }
    }
}

