```jac
"""Channel Performance: cascade-invalidate downstream channel reports when a branch's source order data is corrected.

Models the canonical Task 5.6 scenario: recommendations are computed per
(channel x branch) as derived nodes that depend on upstream Order nodes.
When a source order is corrected (availability flipped, total cents
changed), every downstream report depending on it must be invalidated
and recomputed -- a cascade walk along typed DependsOn relationships with
a guard set so cycles cannot hang the walker.
"""

node Branch {
    has name: str = "";
    has city: str = "";
}

node Order {
    has order_id: str = "";
    has channel: str = "dine-in";
    has total_cents: int = 0;
    has is_valid: bool = True;
}

node ChannelReport {
    has channel: str = "";
    has branch_name: str = "";
    has revenue_cents: int = 0;
    has order_count: int = 0;
    has is_stale: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

walker CascadeInvalidator {
    has source_order: str = "";
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Branch entry {
        visit [-->];
    }

    can invalidate with Order entry {
        if here.order_id == self.source_order {
            here.is_valid = False;
            self.invalidated.append("order:" + here.order_id);
        }
        visit [->:DependsOn:->];
    }

    can mark_stale with ChannelReport entry {
        if not here.is_stale {
            here.is_stale = True;
            self.invalidated.append(here.channel + "@" + here.branch_name);
        }
        visit [-->];
    }
}

