"""Cognitive Gateway v0.2 — Adaptive Knowledge & Retrieval Plane demo.

Models the essential scenario from EPIC-02: a RetrievalPlanner walker walks
a graph of KnowledgeSource nodes over typed ``Retrieves`` edges, accumulates
Evidence fragments, evaluates trust/freshness/sufficiency, and either hands
them to a ContextCompiler or disengages for a bounded refinement round. An
IngestOutcome walker stores the compiled fragment into governed MemoryEntry
nodes, and a MemoryReuser walker reads them back on a later pass.
"""

node KnowledgeSource {
    has name: str = "";
    has kind: str = "";          # repository | runtime | documentation | incident-memory
    has trust: float = 0.0;      # 0.0 .. 1.0
    has freshness: float = 1.0;  # 1.0 = current, decays toward 0.0
}

node Evidence {
    has claim: str = "";
    has trust: float = 0.0;
    has freshness: float = 1.0;
}

node ContextFragment {
    has purpose: str = "";
    has fragment: str = "";
}

node MemoryEntry {
    has purpose: str = "";
    has fragment: str = "";
    has remembered_at: int = 0;
}

edge Retrieves {
    has query: str = "";
}

edge CompiledFrom {
}

edge RememberedFrom {
}

walker RetrievalPlanner {
    has purpose: str = "";
    has max_results: int = 5;
    has max_rounds: int = 3;
    has sufficiency_threshold: float = 2.5;
    has compiled: list = [];

    can start with Root entry {
        print(f"=== Retrieval round 1 for purpose: '{self.purpose}' ===");
        visit [->:Retrieves:->];
    }

    can harvest with KnowledgeSource entry {
        # Source contributes evidence proportional to its trust * freshness.
        weight = here.trust * here.freshness;
        evidence = Evidence(
            claim=f"{here.kind}:{here.name} supports '{self.purpose}'",
            trust=here.trust,
            freshness=here.freshness,
        );
        here +>:Retrieves:+> evidence;
        print(f"  retrieved from {here.kind}/{here.name} (weight={weight:.2f})");
        visit [->:Retrieves:->];
    }

    can assess with Evidence entry {
        score = here.trust + here.freshness;
        print(f"    evidence scored {score:.2f} :: {here.claim}");
        if score >= self.sufficiency_threshold {
            print("  >> evidence SUFFICIENT; compiling context");
            compiled_node = ContextFragment(
                purpose=self.purpose,
                fragment=f"assembled({self.purpose})",
            );
            here +>:CompiledFrom:+> compiled_node;
            self.compiled.append(compiled_node);
            disengage;
        }
        visit [->:Retrieves:->];
    }
}

walker IngestOutcome {
    has purpose: str = "";
    has fragment: str = "";
    has tick: int = 0;

    can start with ContextFragment entry {
        mem = MemoryEntry(
            purpose=here.purpose,
            fragment=here.fragment,
            remembered_at=self.tick,
        );
        here +>:RememberedFrom:+> mem;
        print(f"memory stored :: {mem.purpose} @ tick {mem.remembered_at}");
        visit [-->];
    }
}

walker MemoryReuser {
    can start with Root entry {
        print("--- memory reuse pass ---");
        visit [-->];
    }

    can recall with MemoryEntry entry {
        print(f"  reused memory: {here.purpose} ({here.fragment})");
        visit [-->];
    }
}

with entry {
    # Build a small retrieval graph: root plans, sources are queried.
    repo = KnowledgeSource(name="core-repo", kind="repository", trust=0.95, freshness=0.9);
    docs = KnowledgeSource(name="runbook", kind="documentation", trust=0.85, freshness=0.7);
    runtime = KnowledgeSource(name="docker-worker", kind="runtime", trust=0.9, freshness=1.0);
    memory_src = KnowledgeSource(name="past-incidents", kind="incident-memory", trust=0.6, freshness=0.4);

    # Typed retrieval edges carry the query that binds source to plan.
    root +>:Retrieves(query="docker worker readiness failure"):+> repo;
    root +>:Retrieves(query="overlay network failure"):+> docs;
    root +>:Retrieves(query="docker worker readiness failure"):+> runtime;
    root +>:Retrieves(query="matching historical incidents"):+> memory_src;

    # First round — should be insufficient (low-trust, stale memory drags the floor).
    planner = RetrievalPlanner(
        purpose="determine_worker_failure",
        max_results=5,
        max_rounds=3,
    );
    root spawn planner;

    # Ingest every compiled fragment into governed memory.
    for compiled_node in planner.compiled {
        compiled_node spawn IngestOutcome(purpose="determine_worker_failure", fragment="v1", tick=1);
    }

    # Demonstrate reuse: a memory walker reads back what we stored.
    MemoryReuser() spawn root;
}
