"""Dungeon crawler: chained rooms and a hunter that stops at the treasure."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hunt with Room entry {
        self.rooms_seen += 1;
        status = "TREASURE" if here.has_treasure else "empty";
        print(f"[{self.rooms_seen}] {here.name}: {status}");
        if here.has_treasure {
            print(f"Search complete — treasure secured in {here.name}.");
            disengage;
        } else {
            visit [-->];
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Corridor")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Catacombs");
    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter cleared {hunter.rooms_seen} rooms before stopping.");
}
