node Dependency {
    has name: str = "";
    has kind: str = "normal";   # "normal" | "build" | "dev" | "transitive"
    # Depth in the original graph (root crate's deps = 1, their deps = 2, ...).
    has depth: int = 1;
    has license_id: str = "";
}

edge DependsOn {
    has resolved_kind: str = "normal";
}

# ---------------------------------------------------------------------------
# Walker: derives which dependency edges "ship" with a crate, honoring the
# crate's about.toml flags. Replaces the hand-rolled edge_ships policy.
# ---------------------------------------------------------------------------

walker ScopeDeriver {
    # Accumulate license IDs the crate would actually ship.
    has shipped_licenses: list[str] = [];
    # Cycle guard — explicit because Jac 0.36.1 walkers don't dedupe.
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can derive with Crate entry {
        print(f"--- deriving scope for crate '{here.name}' ---");
        print(f"  flags: ignore_dev={here.ignore_dev_dependencies} "
              f"ignore_build={here.ignore_build_dependencies} "
              f"ignore_transitive={here.ignore_transitive_dependencies}");
        # Clear per-crate state, then walk the dependency graph.
        self.shipped_licenses = [];
        self.visited = [];
        visit [->:DependsOn:->];
    }

    can evaluate with Dependency entry {
        # Cycle policy: explicit guard (the issue's domain logic survives).
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);

        # 1. Edge-kind filter: ignore-dev / ignore-build.
        kind_excluded = (here.kind == "dev" and not False)
            if here.kind == "dev" else False;
        # Rebuild as two clean checks so the intent is readable.
        dev_excluded = here.kind == "dev";
        build_excluded = here.kind == "build";
        # Read the crate we just left via the incoming edge's resolved_kind
        # is not directly available here; we re-read `here` for the dep kind.
        # The flag set belongs to the originating crate, carried by the walker.
        flags = self.crate_flags;
        excluded = (dev_excluded and flags[0])
            or (build_excluded and flags[1]);

        # 2. Depth filter: ignore-transitive drops everything past depth 1.
        depth_excluded = here.depth > 1 and flags[2];

        if not excluded and not depth_excluded {
            if here.license_id not in self.shipped_licenses {
                self.shipped_licenses.append(here.license_id);
            }
            print(f"  + ships: {here.name} [{here.kind} d={here.depth}] "
                  f"-> {here.license_id}");
        } else {
            reason = "kind" if excluded else "depth";
            print(f"  - skip : {here.name} [{here.kind} d={here.depth}] "
                  f"({reason})");
        }

        # Recurse only when the depth axis still allows it; otherwise stop.
        if here.depth == 1 and not flags[2] {
            visit [->:DependsOn:->];
        } else {
            disengage;
        }
    }

    # Carried crate config (originating Crate's three flags).
    has crate_flags: list[bool] = [True, False, False];
}

# ---------------------------------------------------------------------------
# Demonstration
# ---------------------------------------------------------------------------

with entry {
    # Crate A uses defaults: only dev-deps excluded (the old hardcoded rule).
    crate_a = Crate(name="crate-a");

    # Crate B opts out of build-deps too (the gap the issue flags).
    crate_b = Crate(
        name="crate-b",
        ignore_dev_dependencies=True,
        ignore_build_dependencies=True,
        ignore_transitive_dependencies=False,
    );

    # Crate C goes further: only direct (depth-1) deps count.
    crate_c = Crate(
        name="crate-c",
        ignore_dev_dependencies=True,
        ignore_build_dependencies=True,
        ignore_transitive_dependencies=True,
    );

    # Build a small dependency graph under crate-a:
    #   normal -> transitive (depth 2)
    #   build  -> transitive (depth 2)
    #   dev    -> transitive (depth 2)
    normal_d = Dependency(name="serde", kind="normal", depth=1, license_id="MIT");
    build_d = Dependency(name="cc", kind="build", depth=1, license_id="Apache-2.0");
    dev_d = Dependency(name="proptest", kind="dev", depth=1, license_id="MIT");

    serde_inner = Dependency(name="serde_derive", kind="normal", depth=2, license_id="MIT");
    cc_inner = Dependency(name="cc-sys", kind="normal", depth=2, license_id="Apache-2.0");
    proptest_inner = Dependency(name="rand", kind="normal", depth=2, license_id="MIT");

    crate_a +>:DependsOn(resolved_kind="normal"):+> normal_d
        +>:DependsOn:+> serde_inner;
    crate_a +>:DependsOn(resolved_kind="build"):+> build_d
        +>:DependsOn:+> cc_inner;
    crate_a +>:DependsOn(resolved_kind="dev"):+> dev_d
        +>:DependsOn:+> proptest_inner;

    root ++> crate_a ++> crate_b ++> crate_c;

    # Spawn one ScopeDeriver per crate, threading each crate's flags.
    flags_a = [
        crate_a.ignore_dev_dependencies,
        crate_a.ignore_build_dependencies,
        crate_a.ignore_transitive_dependencies,
    ];
    flags_b = [
        crate_b.ignore_dev_dependencies,
        crate_b.ignore_build_dependencies,
        crate_b.ignore_transitive_dependencies,
    ];
    flags_c = [
        crate_c.ignore_dev_dependencies,
        crate_c.ignore_build_dependencies,
        crate_c.ignore_transitive_dependencies,
    ];

    w_a = ScopeDeriver(crate_flags=flags_a);
    w_b = ScopeDeriver(crate_flags=flags_b);
    w_c = ScopeDeriver(crate_flags=flags_c);

    crate_a spawn w_a;
    crate_b spawn w_b;
    crate_c spawn w_c;

    print("");
    print(f"crate-a shipped licenses (old hardcoded rule): {w_a.shipped_licenses}");
    print(f"crate-b shipped licenses (ignore-build honored): {w_b.shipped_licenses}");
    print(f"crate-c shipped licenses (transitive dropped): {w_c.shipped_licenses}");
}
