"""CI pipeline walker: model workflow stages as nodes, dependencies as typed edges, and traverse in dependency order."""

node Stage {
    has name: str = "";
    has status: str = "pending";
    has duration_s: int = 0;
}

edge DependsOn {
    has required: bool = True;
}

node Job {
    has name: str = "";
    has runner: str = "ubuntu-latest";
}

walker RunPipeline {
    has visited: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        print("=== CI Pipeline: tally ===");
        print(f"Visited guard initialized ({len(self.visited)} so far)");
        visit [->:DependsOn:->];
    }

    can collect with Job entry {
        print(f"[JOB] {here.name} on {here.runner}");
        visit [->:DependsOn:->];
    }

    can run with Stage entry {
        if here.name in self.visited {
            print(f"[SKIP] {here.name} already done (cycle guard)");
            return;
        }
        self.visited.append(here.name);
        self.order.append(here.name);

        # Simulate the stage doing work.
        here.status = "running";
        print(f"[RUN ] {here.name} (dep ok={not False})");
        here.status = "passed";
        here.duration_s = 7;

        # Cascade-invalidate any stage that declared a dependency on us and is still pending.
        for child in [->:DependsOn:->] {
            if child.status == "pending" {
                child.status = "blocked";
                print(f"[INVD] {child.name} invalidated by upstream {here.name}");
            }
        }

        visit [->:DependsOn:->];
    }
}

walker CycleDetector {
    has path: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can scan with Stage entry {
        if here.name in self.path {
            print(f"[CYCLE] detected at {here.name}; path={self.path + [here.name]}");
            disengage;
        }
        self.path.append(here.name);
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
