    # Stage dependency edges (typed: DependsOn).
    root +>:DependsOn:+> lint;
    lint +>:DependsOn:+> build_stage;
    build_stage +>:DependsOn:+> test_stage;
    test_stage +>:DependsOn:+> publish_stage;
