```jac
"""Mutual friendships in a neighborhood: houses as nodes, bidirectional buddy edges, two greeters that prove the link runs both ways without bouncing forever."""

node House {
    has name: str = "";
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has start_house: str = "";
    has visited_set: list[str] = [];
    has reached: str = "";

    can start with Root entry {
        visit [-->];
    }

    can greet with House entry {
        # Cycle guard: refuse to re-enter a house already in the set.
        # Without this, the walker would bounce forever on a bidirectional edge.
        if here.name in self.visited_set {
            visit [-->] else { disengage; }
            return;
        }
        self.visited_set = self.visited_set + [here.name];
        print(f"[{self.start_house}] greeting {here.name} (visited: {self.visited_set})");
        if here.name != self.start_house {
            self.reached = here.name;
            print(f"[{self.start_house}] reached buddy {here.name} ✓");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Two houses connected by a single typed buddy edge each way:
    # one statement declares both directions of the relationship.
    h1 = House(name="Maple");
    h2 = House(name="Oak");
    h1 <+:Buddy(since="2010"):+> h2;

    # Spawn a fresh greeter at each house so we can prove the link is two-way.
    g1 = Greeter(start_house="Maple");
    h1 spawn g1;

    g2 = Greeter(start_house="Oak");
    h2 spawn g2;

    # Summarize the round trip so the bidirectional proof is unmistakable.
    print(f"Maple reached: {g1.reached}");
    print(f"Oak reached:   {g2.reached}");
}
```

"""Tests for mutual friendship model with two-way Buddy edges and non-bouncing Greeters."""

import io;
import from contextlib { redirect_stdout }

test "buddy edge is bidirectional between two houses" {
    root ++> House(name="Maple");
    root ++> House(name="Oak");
    h1 = [root -->][0];
    h2 = [root -->][1];
    h1 <+:Buddy(since="2010"):+> h2;

    # Both directions must exist (mutual friendship)
    assert h2 in [h1 ->:Buddy:->], "Maple should have Buddy edge to Oak";
    assert h1 in [h2 ->:Buddy:->], "Oak should have Buddy edge to Maple";
    assert len([h1 ->:Buddy:->]) == 1, "exactly one Buddy edge from Maple";
    assert len([h2 ->:Buddy:->]) == 1, "exactly one Buddy edge from Oak";
}

test "greeter at Maple reaches Oak with forward traversal only" {
    root ++> House(name="Maple");
    root ++> House(name="Oak");
    h1 = [root -->][0];
    h2 = [root -->][1];
    h1 <+:Buddy(since="2010"):+> h2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = h1 spawn Greeter(start_house="Maple");
    }
    out = buf.getvalue();

    assert res.reached == "Oak", f"Maple greeter should reach Oak, got {res.reached!r}";
    assert "[Maple] greeting Maple" in out, f"should greet starting house, got {out}";
    assert "[Maple] reached buddy Oak" in out, f"should announce reaching Oak, got {out}";
    # Must disengage, not bounce: Maple is logged exactly once.
    assert out.count("[Maple] greeting Maple") == 1, f"Maple greeted more than once (bounced?): {out}";
    assert out.count("[Maple] greeting Oak") == 1, f"Oak greeted more than once (bounced?): {out}";
}

test "greeter at Oak reaches Maple with forward traversal only" {
    root ++> House(name="Maple");
    root ++> House(name="Oak");
    h1 = [root -->][0];
    h2 = [root -->][1];
    h1 <+:Buddy(since="2010"):+> h2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = h2 spawn Greeter(start_house="Oak");
    }
    out = buf.getvalue();

    assert res.reached == "Maple", f"Oak greeter should reach Maple, got {res.reached!r}";
    assert "[Oak] greeting Oak" in out, f"should greet starting house, got {out}";
    assert "[Oak] reached buddy Maple" in out, f"should announce reaching Maple, got {out}";
    # Cycle guard: each house greeted exactly once, no infinite bounce.
    assert out.count("[Oak] greeting Oak") == 1, f"Oak greeted more than once (bounced?): {out}";
    assert out.count("[Oak] greeting Maple") == 1, f"Maple greeted more than once (bounced?): {out}";
}

test "cycle guard disengages when revisiting a house" {
    # Two houses joined into a buddy ring: Maple <-> Oak <-> Pine <-> Maple.
    # Spawning at Maple, the walker should NOT revisit Maple; it should stop
    # at the first revisit rather than bouncing forever.
    root ++> House(name="Maple");
    root ++> House(name="Oak");
    root ++> House(name="Pine");
    m = [root -->][0];
    o = [root -->][1];
    p = [root -->][2];
    m <+:Buddy(since="2010"):+> o;
    o <+:Buddy(since="2010"):+> p;
    p <+:Buddy(since="2010"):+> m;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = m spawn Greeter(start_house="Maple");
    }
    out = buf.getvalue();

    # Reached must be a buddy, not the starting house.
    assert res.reached in ["Oak", "Pine"], f"expected a buddy, got {res.reached!r}";
    assert res.reached != "Maple", f"should never 'reach' itself: {res.reached!r}";
    # Bounce-proof: starting house appears in greeting log exactly once.
    assert out.count("[Maple] greeting Maple") == 1, f"Maple revisited, walker bounced: {out}";
}

