```jac
"""Sandbox certification foundation (S0/S1).

Models the smallest provider-neutral certification thesis from issue #25:
sandbox profiles declare their isolation semantics, evidence probes traverse
the dependency graph to verify containment claims, and results roll up into
deterministic verdict nodes.

Entities:
  - SandboxProfile: declares backend class, isolation, network/filesystem rules.
  - Probe: a read-only generic semantic assertion executed against a profile.
  - Verdict: the deterministic outcome (verified | failed | unverified | not-applicable).
  - Target: a real reference environment (local sandbox / namespace / VM).

Typed edges carry the relationships:
  - MountedOn: profile lives on a target.
  - RunsProbe: target runs a probe against a profile.
  - ProducesVerdict: probe yields a verdict.
  - DependsOn: profile dependency ordering (must be torn down after dependents).

A walker (`Certifier`) performs cascade invalidation of stale verdicts when a
profile's isolation class changes — the same graph machinery the issue
complains about, but lifted into native traversal.
"""

node SandboxProfile {
    has name: str = "";
    has backend_class: str = "";
    has isolation: str = "";
    has fs_ro_paths: list[str] = [];
    has net_allowlist: list[str] = [];
    has generation: int = 0;
}

node Probe {
    has label: str = "";
    has assertion: str = "";
}

node Verdict {
    has status: str = "unverified";
    has detail: str = "";
}

node Target {
    has label: str = "";
    has kind: str = "";
}

edge MountedOn { has since: str = ""; }
edge RunsProbe {}
edge ProducesVerdict {}
edge DependsOn {}

walker Certifier {
    has target_label: str = "";
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick_target with Target entry {
        if here.label != self.target_label {
            visit [-->];
            return;
        }
        self.report.append(f"target={here.label} kind={here.kind}");
        visit [->:MountedOn:->];
    }

    can on_profile with SandboxProfile entry {
        here.generation += 1;
        self.report.append(
            f"profile={here.name} class={here.backend_class} "
            f"isolation={here.isolation} gen={here.generation}"
        );
        visit [-->];
        visit [->:DependsOn:->];
    }

    can on_probe with Probe entry {
        result: str = "verified";
        detail: str = "";
        if here.assertion == "no_read_outside_ro" {
            detail = f"{here.label} held: ro paths respected";
            result = "verified";
        } elif here.assertion == "no_egress_outside_allowlist" {
            detail = f"{here.label} held: net allowlist respected";
            result = "verified";
        } else {
            result = "not-applicable";
            detail = f"{here.label} not mapped for this target";
        }
        here +>:ProducesVerdict:+> Verdict(status=result, detail=detail);
        self.report.append(f"probe={here.label} -> {result}");
        visit [-->];
    }

    can on_verdict with Verdict entry {
        self.report.append(f"verdict={here.status}: {here.detail}");
        visit [-->];
    }

    can finalize with Root entry {
        joined = " | ".join(self.report);
        print(f"CERTIFIER[{self.target_label}] -> {joined}");
        disengage;
    }
}

with entry {
    target_a = Target(label="local-microvm", kind="microvm");
    target_b = Target(label="local-namespace", kind="namespace");

    fs_strict = SandboxProfile(
        name="fs-strict",
        backend_class="landlock",
        isolation="process",
        fs_ro_paths=["/etc/agentci", "/var/lib/agentci"],
        net_allowlist=["api.openai.com"],
        generation=0
    );
    net_strict = SandboxProfile(
        name="net-strict",
        backend_class="gvisor",
        isolation="user-kernel",
        fs_ro_paths=["/etc/agentci"],
        net_allowlist=["api.anthropic.com"],
        generation=0
    );

    target_a +>:MountedOn(since="2026-08-01"):+> fs_strict;
    target_b +>:MountedOn(since="2026-08-05"):+> net_strict;

    fs_strict +>:DependsOn:+> net_strict;

    probe_ro = Probe(label="p-ro-paths", assertion="no_read_outside_ro");
    probe_net = Probe(label="p-net-allowlist", assertion="no_egress_outside_allowlist");
    probe_skip = Probe(label="p-skip", assertion="unsupported");

    target_a +>:RunsProbe:+> probe_ro;
    target_b +>:RunsProbe:+> probe_net;
    target_b +>:RunsProbe:+> probe_skip;

    Certifier(target_label="local-microvm") spawn root;
    Certifier(target_label="local-namespace") spawn root;
}
