"""ESLint import plugin: rules that touch the filesystem slow down the linter.

Models the dependency graph between ESLint rules and the `resolve` module
they each call. A rule that depends on `eslint-module-utils/resolve` is the
hot path the issue complains about: every lint run pays for filesystem
walks per file. We use this graph to surface the slow rules in one pass.
"""

node ResolveModule {
    has name: str = "";
    has fs_calls: int = 0;
}

node ImportRule {
    has rule_name: str = "";
    has severity: int = 0;
    has slow: bool = False;
}

edge DependsOn {
    has call_site: str = "";
}

walker SlowRuleAuditor {
    has slow_hits: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        print("Auditing import-plugin rules for fs.* reachability");
        visit [-->];
    }

    can scan with ImportRule entry {
        if here.rule_name in self.seen {
            visit [-->] else { disengage; }
        }
        self.seen.append(here.rule_name);
        if here.slow {
            self.slow_hits.append(here.rule_name);
        }
        print(f"rule {here.rule_name}: severity={here.severity}, slow={here.slow}");
        visit [-->];
    }

    can flag with ResolveModule entry {
        if here.name in self.seen {
            visit [-->] else { disengage; }
        }
        self.seen.append(here.name);
        print(f"  -> reaches resolve module {here.name} ({here.fs_calls} fs calls)");
        visit [-->];
    }

    can summarize with Root entry {
        print(f"slow rules touching fs.*: {self.slow_hits}");
    }
}

with entry {
    resolve = ResolveModule(name="eslint-module-utils/resolve", fs_calls=3000);

    root ++> ImportRule(rule_name="import/no-unresolved", severity=2, slow=True)
        +>:DependsOn(call_site="resolve.default"):+> resolve;

    root ++> ImportRule(rule_name="import/no-extraneous-dependencies", severity=2, slow=True)
        +>:DependsOn(call_site="resolve.default"):+> resolve;

    root ++> ImportRule(rule_name="import/no-relative-parent-imports", severity=2, slow=True)
        +>:DependsOn(call_site="resolve.default"):+> resolve;

    root ++> ImportRule(rule_name="import/no-restricted-paths", severity=2, slow=True)
        +>:DependsOn(call_site="resolve.default"):+> resolve;

    root ++> ImportRule(rule_name="import/extensions", severity=1, slow=False)
        +>:DependsOn(call_site="resolve.default"):+> resolve;

    root ++> ImportRule(rule_name="import/no-cycle", severity=2, slow=False);

    root spawn SlowRuleAuditor();
}
