import io;
import from contextlib { redirect_stdout }

test "audits slow rules that reach resolve" {
    resolve = ResolveModule(name="eslint-module-utils/resolve", fs_calls=3000);
    hot = ImportRule(rule_name="import/no-unresolved", severity=2, slow=True);
    ordinary = ImportRule(rule_name="import/no-cycle", severity=2, slow=False);

    root ++> hot;
    hot +>:DependsOn(call_site="resolve.default"):+> resolve;
    root ++> ordinary;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SlowRuleAuditor();
    }
    out = buf.getvalue();

    assert len([root -->]) == 2, f"got {len([root -->])} direct rules";
    assert "rule import/no-unresolved: severity=2, slow=True" in out, f"missing hot rule: {out}";
    assert "rule import/no-cycle: severity=2, slow=False" in out, f"missing ordinary rule: {out}";
    assert "reaches resolve module eslint-module-utils/resolve (3000 fs calls)" in out, f"missing resolve reachability: {out}";
    assert res.slow_hits == ["import/no-unresolved"], f"wrong slow hits: {res.slow_hits}";
}

test "deduplicates a shared resolve module during traversal" {
    resolve = ResolveModule(name="eslint-module-utils/resolve", fs_calls=2);
    first = ImportRule(rule_name="import/extensions", severity=1, slow=False);
    second = ImportRule(rule_name="import/no-duplicates", severity=2, slow=True);

    root ++> first;
    first +>:DependsOn(call_site="resolve.default"):+> resolve;
    root ++> second;
    second +>:DependsOn(call_site="resolve.default"):+> resolve;

    assert len([root -->]) == 2, f"got {len([root -->])} direct rules";
    assert len([first->:DependsOn:->]) == 1, "wrong first dependency count";
    assert resolve in [first->:DependsOn:->], "first rule does not depend on resolve";
    assert resolve in [second->:DependsOn:->], "second rule does not depend on resolve";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SlowRuleAuditor();
    }
    out = buf.getvalue();

    assert out.count("reaches resolve module eslint-module-utils/resolve") == 1, f"resolve was not deduplicated: {out}";
    assert "import/no-duplicates" in out, f"missing second rule: {out}";
}

test "preserves declared defaults for rules and resolve modules" {
    resolve = ResolveModule();
    default_rule = ImportRule(rule_name="import/extensions");

    root ++> default_rule;
    default_rule +>:DependsOn:+> resolve;

    assert default_rule.severity == 0, f"got {default_rule.severity}";
    assert default_rule.slow == False, f"got {default_rule.slow}";
    assert resolve.name == "", f"got {resolve.name}";
    assert resolve.fs_calls == 0, f"got {resolve.fs_calls}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SlowRuleAuditor();
    }
    out = buf.getvalue();

    assert "rule import/extensions: severity=0, slow=False" in out, f"wrong defaults in rule output: {out}";
    assert "reaches resolve module  (0 fs calls)" in out, f"wrong defaults in resolve output: {out}";
    assert res.slow_hits == [], f"default rule was marked slow: {res.slow_hits}";
}

