"""Hiking trail: plain waypoints chained from trailhead to summit; a hiker walker counts each stop."""

node Trailhead {
    has name: str = "";
}

node Waypoint {
    has marker: bool = True;
}

node Summit {
    has name: str = "";
}

walker Hiker {
    has stop_count: int = 0;
    has required_stops: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can depart with Trailhead entry {
        label = here.name if here.name else "trailhead";
        print(f"Leaving {label}");
        visit [-->];
    }

    can mark_stop with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can finish with Summit entry {
        label = here.name if here.name else "summit";
        if self.stop_count >= self.required_stops {
            print(f"Hike complete — passed {self.stop_count} waypoints; arrived at {label}");
        } else {
            print(f"Arrived at {label} after {self.stop_count} waypoints (expected {self.required_stops})");
        }
        disengage;
    }
}

with entry {
    head = Trailhead(name="Pine Ridge Trailhead");
    peak = Summit(name="Eagle Peak");
    root ++> head
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> peak;
    root spawn Hiker(required_stops=3);
}
