"""Vulnerable dependency graph for CVE-2026-22745.

Models a Maven dependency hierarchy where ``spring-boot-starter-web`` transitively
pulls in the vulnerable ``spring-webmvc``. A walker traverses the graph along
``DependsOn`` edges to flag every affected artifact so maintainers can see the
blast radius of the vulnerability.
"""

node Artifact {
    has gav: str = "";
    has version: str = "";
    has vulnerable: bool = False;
}

edge DependsOn {
    has scope: str = "compile";
}

walker VulnerabilityScanner {
    has findings: list = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Artifact entry {
        if here.vulnerable {
            self.findings.append(here);
        }
        visit [->:DependsOn:->];
    }
}

walker DependencyReport {
    has scanned: list = [];

    can start with Root entry {
        visit [-->];
    }

    can tally with Artifact entry {
        marker = "[VULN]" if here.vulnerable else "[ok]  ";
        print(f"{marker} {here.gav}:{here.version}");
        self.scanned.append(here);
        visit [->:DependsOn:->];
    }
}

with entry {
    starter = Artifact(gav="org.springframework.boot:spring-boot-starter-web",
                       version="3.0.3");
    webmvc = Artifact(gav="org.springframework:spring-webmvc",
