    context = Artifact(gav="org.springframework:spring-context",
                       version="6.0.5");
    beans = Artifact(gav="org.springframework:spring-beans",
                     version="6.0.5");

    root +>:DependsOn:+> starter;
    starter +>:DependsOn:+> webmvc;
    webmvc +>:DependsOn:+> context;
    context +>:DependsOn:+> beans;

    print("=== Vulnerability Scanner ===");
    scanner = VulnerabilityScanner();
    root spawn scanner;
    print(f"Affected artifacts: {len(scanner.findings)}");
    for hit in scanner.findings {
        print(f"  -> {hit.gav}:{hit.version}");
    }

    print("\n=== Dependency Report ===");
    reporter = DependencyReport();
    root spawn reporter;
}
