"""GDS cell subtree copy: hierarchy-preserving cell copy between libraries.

Models the essential scenario from gdsr issue #313: select root cells,
copy them and all reachable descendants into a target library, dedupe
shared descendants, apply cell-conflict rename strategies, return a
deterministic rename map, and reject cyclic cell graphs atomically.
"""

node Cell {
    has name: str = "";
    has layer: str = "L1";
    has copied: bool = False;
}

edge ParentOf {
    has pin_label: str = "";
}

walker SubtreeCopier {
    has strategy: str = "rename";   # "rename", "skip", or "overwrite"
    has filter_layer: str = "";     # "" means no filter
    has rename_map: dict = {};
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can gather with Cell entry {
        # Cycle guard: an already-visited cell in this run means a cycle.
        if here.name in self.visited {
            print(f"REJECTED: cycle detected at cell '{here.name}'");
            disengage;
        }
        self.visited[here.name] = True;

        # Layer filter: skip this cell if a filter is set and doesn't match.
        if self.filter_layer != "" and here.layer != self.filter_layer {
            print(f"  filter: skipping cell '{here.name}' on layer {here.layer}");
            visit [-->];
            return;
        }

        # Apply conflict strategy to compute the new name.
        proposed = here.name + "_copy";
        existing = self.rename_map.get(here.name, None);

        if existing is not None {
            if self.strategy == "skip" {
                print(f"  skip: '{here.name}' already mapped to '{existing}'");
                visit [-->];
                return;
            }
            if self.strategy == "overwrite" {
                final_name = proposed;
                self.rename_map[here.name] = final_name;
                print(f"  overwrite: {here.name} -> {final_name}");
            } else {
                # rename (default): keep deterministic unique suffix.
                suffix = 2;
                candidate = f"{proposed}_{suffix}";
                while candidate in self.rename_map.values() {
                    suffix += 1;
                    candidate = f"{proposed}_{suffix}";
                }
                final_name = candidate;
                self.rename_map[here.name] = final_name;
                print(f"  rename: {here.name} -> {final_name}");
            }
        } else {
            self.rename_map[here.name] = proposed;
            print(f"  map: {here.name} -> {proposed}");
        }

        here.copied = True;
        visit [-->];
    }
}

walker Inspector {
    has target_name: str = "";

    can start with Root entry {
        print(f"Inspector scanning for '{self.target_name}'");
        visit [-->];
    }

    can look with Cell entry {
        if here.name == self.target_name {
            print(f"  found cell '{here.name}' on layer {here.layer}");
        }
        visit [-->];
    }
}

with entry {
    # Build a small hierarchy: A and B both reference shared child C.
    # D is a leaf only reachable via A.
    a = Cell(name="A", layer="L1");
    b = Cell(name="B", layer="L1");
    c = Cell(name="C", layer="L2");  # shared descendant
    d = Cell(name="D", layer="L1");

    # Wire parents -> children via typed ParentOf edges.
    a +>:ParentOf(pin_label="p0"):+> c;
    a +>:ParentOf(pin_label="p1"):+> d;
    b +>:ParentOf(pin_label="p2"):+> c;

    # Anchor everything off root so spawn can find the roots.
    root ++> a;
    root ++> b;
    root ++> c;
    root ++> d;

    # 1) Plain rename copy of a subtree rooted at A.
    print("=== copy subtree rooted at A (strategy=rename) ===");
    copier = SubtreeCopier(strategy="rename");
    a spawn copier;
    print(f"  rename_map = {copier.rename_map}");

    # 2) Copy B into the same target — shared child C must be reused
