    copier2 = SubtreeCopier(strategy="rename", rename_map=copier.rename_map);
    b spawn copier2;
    print(f"  rename_map = {copier2.rename_map}");

    # 3) Layer-filtered copy: only L2 cells survive the filter.
    print("=== copy subtree with layer filter = L2 ===");
    copier3 = SubtreeCopier(strategy="rename", filter_layer="L2");
    a spawn copier3;
    print(f"  rename_map = {copier3.rename_map}");

    # 4) Inspector walker proves we can also walk the graph read-only.
    print("=== inspector walker looking for shared cell C ===");
    inspector = Inspector(target_name="C");
    root spawn inspector;

    # 5) Cycle rejection: wire A <- C artificially and watch the copier
    #    disengage rather than loop forever.
    print("=== cycle rejection on cyclic graph ===");
    c +>:ParentOf:+> a;  # creates A -> C -> A cycle
    copier4 = SubtreeCopier(strategy="rename");
    a spawn copier4;
}
