node CacheEntry {
    has contract: str = "";
    has engine: str = "";
    has algorithm: str = "";
    has source_version: str = "";
    has mahadasha: str = "";
    has antardasha: str = "";
    has starting_balance: float = 0.0;
    has stale: bool = False;
}

node Registry {
    has name: str = "";
}

edge KeyedBy {
    has contract: str = "";
    has engine: str = "";
    has algorithm: str = "";
    has source_version: str = "";
}

edge Stale {
}

walker CacheAuditor {
    can start with Root entry {
        visit [-->];
    }

    can enter_registry with Registry entry {
        print(f"Auditing registry: {here.name}");
        visit [-->];
    }

    can audit_entry with CacheEntry entry {
        canonical = self.lookup(here.contract, here.engine, here.algorithm, here.source_version);
        if canonical is None {
            here.stale = True;
            print(f"[STALE] {here.contract}/{here.engine}/{here.algorithm} @ {here.source_version} -> no source");
            visit [-->];
            return;
        }
        if here.mahadasha != canonical.mahadasha or here.antardasha != canonical.antardasha
