            print(f"[STALE] {here.contract}/{here.engine}/{here.algorithm} @ {here.source_version} mismatch");
        } else {
            print(f"[FRESH] {here.contract}/{here.engine}/{here.algorithm} @ {here.source_version}");
        }
        visit [-->];
    }

    def lookup(contract: str, engine: str, algorithm: str, version: str) -> CacheEntry | None {
        return self.canonical.get((contract, engine, algorithm, version));
    }

