"""Bug tracker: file a ticket and capture it inline, then report immediately.

Demonstrates the grouped-creation idiom (`root ++> (t := Ticket(...))`)
so the freshly connected ticket node is available in one expression
without a follow-up lookup query.
"""

node Project {
    has name: str = "";
    has tickets_filed: int = 0;
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
    has filed: bool = False;
}

walker TicketCounter {
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

