        print(f"Project '{here.name}' now holds {here.tickets_filed} ticket(s).");
        visit [-->];
    }
}

with entry {
    orion = Project(name="Orion");
    root ++> orion;

    # File a new ticket and capture the connected node in one expression.
    root ++> (urgent := Ticket(title="Login page 500s", priority="high"));
    urgent.filed = True;

    # File another ticket the same way.
    root ++> (minor := Ticket(title="Typo on dashboard", priority="low"));
    minor.filed = True;

    # Report both immediately — no lookup query required.
    print(f"[NEW] #{urgent.title} priority={urgent.priority} filed={urgent.filed}");
    print(f"[NEW] #{minor.title} priority={minor.priority} filed={minor.filed}");

    # Bump the project's filed-count and walk the tree to report it.
    orion.tickets_filed = orion.tickets_filed + 2;
    root spawn TicketCounter();
}
