    happy_annot = Annotation(
        name="annotate",
        status="ok",
        detail="vep annotated",
        order=3,
        features_annotated=19_500,
        selected_assembly="GRCh38",
    );

    fail_fastq = FastqInput(
        name="fastq_in",
        status="ok",
        detail="reads loaded",
        order=1,
        sample_id="S2",
        read_count=1_800_000,
    );
    fail_align = Alignment(
        name="align",
        status="fail",
        detail="reference mismatch",
        order=2,
        reference_assembly="unknown",
        aligned_reads=0,
    );
    fail_annot = Annotation(
        name="annotate",
        status="pending",
        detail="skipped due to upstream failure",
        order=3,
        features_annotated=0,
        selected_assembly="",
    );

    root +>:DependsOn(verified=True):+> happy_fastq;
    happy_fastq +>:DependsOn(verified=True):+> happy_align;
    happy_align +>:DependsOn(verified=True):+> happy_annot;

    root +>:DependsOn(verified=True):+> fail_fastq;
    fail_fastq +>:DependsOn(verified=True):+> fail_align;
    fail_align +>:DependsOn(verified=True):+> fail_annot;

    print("--- VerifyDAG (integration slice) ---");
