"""Order auditor: skip invalid orders and halt the walk on fraud flags."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited_count: int = 0;

    can start with Root entry {
        print("Starting order audit");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged on order amount {here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount {here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"[AUDIT] reviewing order amount {here.amount}");
                self.audited_count += 1;
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=100, valid=True, fraud=False)
        ++> Order(amount=50, valid=False, fraud=False)
        ++> Order(amount=200, valid=True, fraud=False)
        ++> Order(amount=75, valid=True, fraud=True)
        ++> Order(amount=300, valid=True, fraud=False);
    auditor = OrderAuditor();
    root spawn auditor;
    print(f"Audited {auditor.audited_count} valid orders before stop");
}
