```jac
"""Agent Relay RFC #8 demo: decision authority, mission modes, evidence maturity, and stagnation escalation.

Models four orthogonal semantics as node archetypes with typed edges, and uses walkers to
exercise the protocol-level concerns the RFC raises: traversal of delegated decision authority,
escalation on repeated same-role failure, and evidence-maturity gating.
"""

# --- Mission modes (the "kind of work" axis) ---

node Mission {
    has title: str = "";
    has desired_outcome: str = "";
}

node MissionMode {
    has name: str = "";
    has category: str = "";
}

# --- Decision authority envelope ---

node DecisionClass {
    has label: str = "";
    # Shared field so a union trigger can read a description from any
    # participant in the envelope/mission subgraph.
    has scope: str = "";
}

edge Delegates {
    has actor_role: str = "";
}

edge BelongsTo {
    has mission_title: str = "";
}

# --- Evidence maturity ---

node Evidence {
    has claim: str = "";
    has maturity: str = "unverified";
    has verifiable_signal: bool = False;
}

edge ReliesOn {
    has relying_pass: str = "";
}

# --- Stagnation / escalation ---

node FailureRecord {
    has pass_id: str = "";
    has role: str = "";
    has attempt: int = 0;
}

edge FiledAgainst {
    has target: str = "";
}

edge EscalatesTo {
    has reason: str = "";
}

glob ESCALATION_THRESHOLD: int = 3;

# =====================================================================
# Walkers
# =====================================================================

# AuthorityInspector: traverses the envelope and reports which actor owns
# each DecisionClass. Demonstrates "execution autonomy does not imply
# planning authority" by separating the delegation classes.
walker AuthorityInspector {
    has audit_log: list[str] = [];

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can cross_class with DecisionClass entry {
        for n in [->:Delegates:->] {
            self.audit_log.append(f"{here.label} -> {n.actor_role}");
        }
        visit [->:Delegates:->];
    }

    can record_actor with DecisionClass entry {
        print(f"[AUTH] {here.label} is delegated via scope '{here.scope}'");
        visit [->:BelongsTo:->] else { disengage; };
    }
}

# EscalationWalker: walks the failure trail for a given role and decides
# whether the same-role retry loop should escalate. Models "repeated
# failure should trigger a role/lens change".
walker EscalationWalker {
    has role: str = "";
    has failed: list[str] = [];
    has escalated: bool = False;
    has new_role: str = "";

    can start with Root entry {
        visit [->:FiledAgainst:->];
    }

    can collect with FailureRecord entry {
        if here.role == self.role {
            self.failed.append(here.pass_id);
        }
        visit [->:FiledAgainst:->];
    }

    can decide with FailureRecord entry {
        count = len(self.failed);
        verdict = "OK" if count < ESCALATION_THRESHOLD else "ESCALATE";
        self.escalated = count >= ESCALATION_THRESHOLD;
        if self.escalated {
            self.new_role = "Reviewer" if self.role == "Builder" else "Integrator";
        }
        reason = f"{count} same-role failures for role '{self.role}'";
        suffix = f", escalate to {self.new_role}" if self.escalated else "";
        print(f"[ESCALATION] {reason} -> verdict {verdict}{suffix}");
        visit [->:EscalatesTo:->] else { disengage; };
    }
}

# EvidenceAuditor: walks every Evidence item reachable from root and
# reports the weakest relied-upon evidence. Models "evidence maturity":
# planning authority should not be granted on unverified evidence.
walker EvidenceAuditor {
    has weakest: str = "verified";
    has weakest_claim: str = "";

    can start with Root entry {
        visit [->:ReliesOn:->];
    }

    can audit with Evidence entry {
        rank = 0;
        if here.maturity == "verified" {
            rank = 2;
        } elif here.maturity == "partial" {
            rank = 1;
        } else {
            rank = 0;
        }
        current_rank = 0;
        if self.weakest == "verified" {
            current_rank = 2;
        } elif self.weakest == "partial" {
            current_rank = 1;
        } else {
            current_rank = 0;
        }
        if rank < current_rank {
            self.weakest = here.maturity;
            self.weakest_claim = here.claim;
        }
        visit [->:ReliesOn:->];
    }

    can finalize with Evidence entry {
        safe = self.weakest == "verified";
        verdict = "GRANTED" if safe else "DENIED";
        line = "[EVIDENCE] weakest maturity: " + self.weakest
               + " on claim '" + self.weakest_claim + "'"
               + " -> planning authority " + verdict;
        print(line);
        visit [->:ReliesOn:->] else { disengage; };
    }
}

# =====================================================================
# Demonstration graph
# =====================================================================

with entry {
    # --- Mission + decision classes ---
    mission = Mission(title="Ship agent relay v2",
                       desired_outcome="Protocol extension RFC #8 demo");

    dc_mission = DecisionClass(label="mission / desired outcome", scope="rfc8-demo");
    dc_arch    = DecisionClass(label="architecture / acceptance criteria", scope="rfc8-demo");
    dc_impl    = DecisionClass(label="implementation mechanics", scope="rfc8-demo");
    dc_ready   = DecisionClass(label="readiness / reconciliation", scope="rfc8-demo");

    # Typed-edge wiring with role payloads. Mirrors the RFC: User owns
    # mission, User+Integrator share architecture, Builder owns mechanics,
    # Integrator owns readiness — separating planning from execution.
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_mission;
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_arch;
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_impl;
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_ready;

    mission +>:Delegates(actor_role="User"):+>          dc_mission;
    mission +>:Delegates(actor_role="User+Integrator"):+> dc_arch;
    mission +>:Delegates(actor_role="Builder"):+>        dc_impl;
    mission +>:Delegates(actor_role="Integrator"):+>     dc_ready;

    # Mission-mode annotation (the "kind of work" axis).
    mode = MissionMode(name="pass-7", category="building");
    root ++> mission ++> mode;

    # --- Evidence trail: a relied-upon claim with one weak link ---
    ev_strong = Evidence(claim="git commit present", maturity="verified", verifiable_signal=True);
    ev_weak   = Evidence(claim="user said it works",  maturity="unverified", verifiable_signal=False);
    root +>:ReliesOn(relying_pass="pass-7"):+> ev_strong;
    root +>:ReliesOn(relying_pass="pass-7"):+> ev_weak;

    # --- Stagnation trail: a Builder failing repeatedly ---
    root ++> FailureRecord(pass_id="p1", role="Builder", attempt=1)
        +>:FiledAgainst(target="pass-7"):+> FailureRecord(pass_id="p2", role="Builder", attempt=2)
        +>:FiledAgainst(target="pass-7"):+> FailureRecord(pass_id="p3", role="Builder", attempt=3);

    # --- Spawn the three walkers ---
    AuthorityInspector() spawn root;
    EvidenceAuditor() spawn root;
    EscalationWalker(role="Builder") spawn root;
}
```

