"""Weather sweep: stations report temperature as a walker visits each one."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has lo: float = 0.0;
    has hi: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"[{here.name} @ {here.location}] {here.celsius} C");
        self.readings.append(here.celsius);
        if len(self.readings) == 1 {
            self.lo = here.celsius;
            self.hi = here.celsius;
        } else {
            self.lo = here.celsius if here.celsius < self.lo else self.lo;
            self.hi = here.celsius if here.celsius > self.hi else self.hi;
        }
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North", location="ridge", celsius=18.5)
        ++> Station(name="Valley", location="creek", celsius=24.0)
        ++> Station(name="Coast", location="bay", celsius=21.25)
        ++> Station(name="Summit", location="peak", celsius=12.75);

    sweep = WeatherSweep();
    root spawn sweep;

    print("Readings: " + ", ".join(f"{r} C" for r in sweep.readings));
    print(f"Min: {sweep.lo} C");
    print(f"Max: {sweep.hi} C");
}
