"""Tests for the fighter-advancements N+1 demo program.

These tests build a fresh graph per block, spawn the walkers defined in
the program under test, and assert on the printed output and the graph
shape (typed-edge counts and reachability).
"""

import io;
import from contextlib { redirect_stdout }

# ---- shared graph fixture ---------------------------------------------------

def build_demo_graph() {
    # Content catalogue (the templates fighters are built from).
    cf_champion = ContentFighter(
        name="Champion",
        archetype="Leader",
        house="House Orlock",
    );
    cf_juve = ContentFighter(name="Juve", archetype="Ganger", house="House Goliath");

    # Fighters, each linked to its template via a typed BuiltFrom edge.
    f_champion = Fighter(name="Grim", content="Champion");
    f_juve = Fighter(name="Ratchet", content="Juve");

    f_champion +>:BuiltFrom(since="pre-game"):+> cf_champion;
    f_juve +>:BuiltFrom(since="pre-game"):+> cf_juve;

    # Advancements: one Skill + one CampaignAction per fighter, wired
    # through the typed Lists edge so the auditor can visit them.
    s_iron = Skill(title="Iron Will", xp_cost=6);
    s_nerve = Skill(title="Nerves of Steel", xp_cost=4);
    a_heal = CampaignAction(title="Recover Wounds", description="Heal a fighter.");

    f_champion +>:Lists(slot=1):+> s_iron;
    f_champion +>:Lists(slot=2):+> s_nerve;
    f_champion +>:Lists(slot=3):+> a_heal;

    # Anchor under root so walkers have a starting point.
    root ++> f_champion;
    root ++> f_juve;

    return {
        "cf_champion": cf_champion,
        "cf_juve": cf_juve,
        "f_champion": f_champion,
        "f_juve": f_juve,
        "skills": [s_iron, s_nerve],
        "action": a_heal,
    };
}

# ---- tests ------------------------------------------------------------------

test "AdvancementsAuditor visits every fighter and lists every advancement" {
    build_demo_graph();

    prefetched = {
        "Grim": "Champion (Leader)",
        "Ratchet": "Juve (Ganger)",
    };

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn AdvancementsAuditor(prefetched_content=prefetched);
    }
    out = buf.getvalue();

    # Both fighters should be announced with their pre-fetched content
    # -- this is the "JOIN up front" the issue is asking for.
    assert "fighter=Grim" in out, f"missing Grim in auditor output: {out}";
    assert "content=Champion (Leader)" in out, f"missing prefetched Champion payload: {out}";
    assert "fighter=Ratchet" in out, f"missing Ratchet in auditor output: {out}";
    assert "content=Juve (Ganger)" in out, f"missing prefetched Juve payload: {out}";

    # Every advancement attached via Lists edges must be enumerated.
    assert "advancement: Iron Will" in out, f"missing Iron Will in output: {out}";
    assert "advancement: Nerves of Steel" in out, f"missing Nerves of Steel: {out}";
    assert "advancement: Recover Wounds" in out, f"missing Recover Wounds: {out}";

    # The marker that confirms the fix path (prefetched, no extra query)
    # appears for each fighter visited.
    assert out.count("prefetched, no extra query") == 2, (
        f"expected 2 prefetched markers, got {out.count('prefetched, no extra query')}: {out}"
    );
}

test "ContentPrefetch follows the typed BuiltFrom edge from each fighter" {
    g = build_demo_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ContentPrefetch();
    }
    out = buf.getvalue();

    # The walker should announce both fighters and load both templates.
    assert "at fighter Grim" in out, f"missing Grim hop: {out}";
    assert "at fighter Ratchet" in out, f"missing Ratchet hop: {out}";
    assert "Champion / Leader" in out, f"missing Champion template load: {out}";
    assert "Juve / Ganger" in out, f"missing Juve template load: {out}";

    # And every hop should be routed through the typed BuiltFrom edge --
    # that's the JOIN the issue recommends.
    assert out.count("following BuiltFrom edge") == 2, (
        f"expected 2 BuiltFrom hops, got {out.count('following BuiltFrom edge')}: {out}"
    );
}

test "typed BuiltFrom and Lists edges connect the right nodes" {
    g = build_demo_graph();
    f1 = g["f_champion"];
    f2 = g["f_juve"];
    cf1 = g["cf_champion"];
    cf2 = g["cf_juve"];

    # Exactly one BuiltFrom edge per fighter (the N+1 happens when the
    # template has to chase this FK by hand -- pre-fetch makes it one).
    bf_from_f1 = [f1 ->:BuiltFrom:->];
    bf_from_f2 = [f2 ->:BuiltFrom:->];
    assert len(bf_from_f1) == 1, f"Grim should have 1 BuiltFrom edge, got {len(bf_from_f1)}";
    assert len(bf_from_f2) == 1, f"Ratchet should have 1 BuiltFrom edge, got {len(bf_from_f2)}";
    assert bf_from_f1[0] == cf1, "Grim's BuiltFrom edge should point at the Champion template";
    assert bf_from_f2[0] == cf2, "Ratchet's BuiltFrom edge should point at the Juve template";

    # Each fighter's advancement list is reachable through typed Lists
    # edges from the fighter itself.
    f1_adv = [f1 ->:Lists:->];
    assert len(f1_adv) == 3, f"Grim should list 3 advancements, got {len(f1_adv)}";
    titles = sorted([n.title for n in f1_adv]);
    assert titles == ["Iron Will", "Nerves of Steel", "Recover Wounds"], (
        f"unexpected advancement titles: {titles}"
    );
}

test "AdvancementsAuditor without a prefetched payload still walks cleanly" {
    # Fail-open check: passing an empty dict must not crash the walker.
    # The auditor should fall back to the "<no content>" marker for any
    # fighter that isn't in the prefetch table -- the template render
    # proceeds; it just shows the fallback.
    build_demo_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn AdvancementsAuditor(prefetched_content={});
    }
    out = buf.getvalue();

    assert "<no content>" in out, f"missing fallback marker when no prefetch: {out}";
    # Advancements still enumerated -- the N+1 fix is orthogonal to
    # whether the content lookup happened to be pre-populated.
    assert "advancement: Iron Will" in out, f"advancements should still be visited: {out}";
}

