"""Native knowledge-graph queries for prerequisite eligibility and chains."""

node Concept {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has prerequisite_count: int = 0;
    has mastered_prerequisite_count: int = 0;
}

node Student {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has mastered_count: int = 0;
}

edge CatalogEntry { }
edge Prerequisite {
    has reason: str = "";
}
edge Mastered {
    has completed_at: str = "";
}

walker EligibilityScanner {
    has eligible_count: int = 0;
    has almost_eligible_count: int = 0;
    has locked_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Concept entry {
        if here.prerequisite_count == here.mastered_prerequisite_count {
            self.eligible_count += 1;
            print(f"eligible: {here.title}");
        } elif here.prerequisite_count - here.mastered_prerequisite_count == 1 {
            self.almost_eligible_count += 1;
            print(f"almost eligible: {here.title}");
        } else {
            self.locked_count += 1;
            print(f"locked: {here.title}");
        }
        visit [->:CatalogEntry:->] else {
            disengage;
        }
    }
}

walker PrerequisiteChain {
    has depth: int = 0;
    has max_depth: int = 8;

    can follow with Concept entry {
        if self.depth >= self.max_depth {
            print(f"cycle or depth limit near {here.title}");
            disengage;
        } else {
            self.depth += 1;
            print(f"chain: {here.title}");
            visit [->:Prerequisite:->] else {
                disengage;
            }
        }
    }
}

with entry {
    foundation = Concept(title="Arrays", year=2020, prerequisite_count=0, mastered_prerequisite_count=0);
    arrays = Concept(title="Linked Lists", year=2020, prerequisite_count=1, mastered_prerequisite_count=1);
    graphs = Concept(title="Graphs", year=2021, prerequisite_count=1, mastered_prerequisite_count=0);
    recursion = Concept(title="Recursion", year=2021, prerequisite_count=1, mastered_prerequisite_count=0);
    paths = Concept(title="Shortest Paths", year=2021, prerequisite_count=2, mastered_prerequisite_count=0);
    student = Student(name="Mina", mastered_count=2);

    root ++> foundation;
    foundation +>:CatalogEntry:+> arrays;
    arrays +>:CatalogEntry:+> graphs;
    graphs +>:CatalogEntry:+> recursion;
    recursion +>:CatalogEntry:+> paths;

    arrays +>:Prerequisite(reason="requires arrays"):+> foundation;
    graphs +>:Prerequisite(reason="requires linked lists"):+> arrays;
    recursion +>:Prerequisite(reason="requires graph traversal"):+> graphs;
    paths +>:Prerequisite(reason="requires graph traversal"):+> graphs;
    paths +>:Prerequisite(reason="requires recursion"):+> recursion;
    student +>:Mastered(completed_at="today"):+> foundation;
    student +>:Mastered(completed_at="today"):+> arrays;

    scanner = EligibilityScanner();
    root spawn scanner;
    print(f"totals: {scanner.eligible_count} eligible, {scanner.almost_eligible_count} almost eligible, {scanner.locked_count} locked");

    chain = PrerequisiteChain(max_depth=8);
    paths spawn chain;
}
