"""Restaurant kitchen health inspection.

Two checks run at every station: a temperature check that flags anything
above 40 C as a violation, and a visit-log entry recorded for every station
seen on the line.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker Inspector {
    has violations: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Union trigger fires on every station; both checks run together.
    can inspect with Station entry {
        entry_log = f"visited {here.name} at {here.celsius} C";
        self.log.append(entry_log);
        print(entry_log);

        if here.celsius > 40.0 {
            self.violations += 1;
            print(f"  VIOLATION: {here.name} exceeds 40 C");
        } else {
            print(f"  OK: {here.name} within safe range");
        }

        visit [-->] else { disengage; }
    }
}

with entry {
    grill = Station(name="grill", celsius=180.0);
    fryer = Station(name="fryer", celsius=165.0);
    cold_prep = Station(name="cold prep", celsius=6.0);
    root ++> grill ++> fryer ++> cold_prep;

    root spawn Inspector();
}
