"""Dungeon crawler: chain rooms and hunt for treasure with early termination."""

node Room {
    has name: str = "";
    has holds_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon.");
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        if here.holds_treasure {
            print(
                f"Treasure found in {here.name}! "
                f"Searched {self.rooms_seen} room(s)."
            );
            disengage;
        } else {
            print(f"Checking {here.name}... empty.");
            visit [-->];
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Armory")
        ++> Room(name="Vault", holds_treasure=True)
        ++> Room(name="Secret Chamber");
    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter finished after seeing {hunter.rooms_seen} room(s).");
}
