    print("Per-item counts:");
    total_units = 0;
    smallest = 0;
    is_first = True;
    for item in result.reports {
        print(f"  {item.sku}: {item.quantity}");
        total_units += item.quantity;
        if is_first {
            smallest = item.quantity;
            is_first = False;
        } elif item.quantity < smallest {
