```jac
"""Build-system circular dependency detector.

Each module lists the modules it depends on. A module is buggy when you
can follow its dependencies back to itself; we report the exact cycle
path so the build can be fixed before it loops forever.

Walks outgoing ``DependsOn`` edges with a stack of visited module names so
that re-entering a node already on the path closes a cycle. Depth cap
prevents runaway traversal on dense graphs; ``disengage`` halts as soon
as a cycle is reported.
"""

node Module {
    has name: str = "";
}

edge DependsOn {
    has weight: int = 1;
}

walker CycleFinder {
    has path: list[str] = [];
    has depth_limit: int = 32;
    has reported: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with Module entry {
        if self.reported {
            disengage;
        }
        current_path = self.path + [here.name];
        if here.name in self.path {
            cycle_start = self.path.index(here.name);
            cycle_path = self.path[cycle_start:] + [here.name];
            print(f"CYCLE DETECTED: {' -> '.join(cycle_path)}");
            self.reported = True;
            disengage;
        }
        if current_path.__len__() > self.depth_limit {
            print(f"depth cap {self.depth_limit} hit at {here.name}; aborting");
            disengage;
        }
        self.path = current_path;
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    app = Module(name="app");
    parser = Module(name="parser");
    lexer = Module(name="lexer");
    tokens = Module(name="tokens");

    root ++> app ++> parser ++> lexer ++> tokens;

    app +>:DependsOn:+> parser;
    parser +>:DependsOn:+> lexer;
    lexer +>:DependsOn:+> tokens;
    tokens +>:DependsOn:+> lexer;
    app +>:DependsOn:+> tokens;

    root spawn CycleFinder();
}
