    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = Root() spawn CycleFinder();
    }
    return buf.getvalue();
}

# A -> B -> A is the canonical two-node cycle.
test "two-node cycle in dependency graph is reported" {
    rt = Root();
    a = Module(name="a");
    b = Module(name="b");
    rt ++> a ++> b;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;

    out = io.StringIO();
    with redirect_stdout(out) {
        res = rt spawn CycleFinder();
    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" in captured, f"missing cycle marker: {captured}";
    # Path must include both modules and close back to a.
    assert "a -> b -> a" in captured, f"wrong cycle path: {captured}";
    assert res.reported is True, f"walker.reported should be True, got {res.reported}";
}

# A self-edge on a module: "lone -> lone" is a cycle.
test "self-dependency is detected as a cycle" {
    rt = Root();
