    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" in captured, f"missing cycle marker: {captured}";
    assert "lone -> lone" in captured, f"self-cycle path wrong: {captured}";
    assert res.reported is True, f"walker.reported should be True, got {res.reported}";
}

# A linear chain with no back-edges: nothing should be reported.
test "acyclic dependency graph produces no cycle report" {
    rt = Root();
    a = Module(name="alpha");
    b = Module(name="beta");
    c = Module(name="gamma");
    rt ++> a ++> b ++> c;
    a +>:DependsOn:+> b;
