"""Data center clearance walk: technicians traverse a corridor of server rooms,
are granted or denied based on their clearance level vs the room's required
level, and disengage on first denial. Reports rooms reached per technician."""

node Room {
    has name: str = "";
    has required_level: int = 0;
}

node Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied_at: str = "";
}

walker TechWalker {
    has tech: Technician = Technician();

    can start with Root entry {
        visit [-->];
    }

    can enter with Technician entry {
        self.tech = here;
        self.tech.rooms_reached = 0;
        self.tech.denied_at = "";
        print(f"Technician {self.tech.name} (clearance {self.tech.clearance}) entering corridor");
        visit [-->];
    }

    can audit with Room entry {
        if self.tech.clearance >= here.required_level {
            self.tech.rooms_reached += 1;
            print(f"  GRANTED: {here.name} (needs {here.required_level})");
            visit [-->];
        } else {
            self.tech.denied_at = here.name;
            print(f"  DENIED at {here.name} (needs {here.required_level}, has {self.tech.clearance}); walkthrough ends");
            disengage;
        }
    }
}

with entry {
