"""SQL column-pattern fixture lock-in: LATERAL FLATTEN traversal.

The issue: a maintainer needs to assert that ``LATERAL FLATTEN`` parses to
the expected column list and that a future dependency bump cannot silently
break it. We model the *scenario* natively — a ``dbt`` graph of
``Model -> Column`` dependencies — and a walker that walks those edges to
recover the flattened column list the same way a fixture would.
"""

node Column {
    has name: str = "";
}

node Model {
    has name: str = "";
    has pattern: str = "";
}

edge DependsOn { }

node FlattenFixture {
    has label: str = "";
    has expected_columns: list[str] = [];
}

walker ColumnAuditor {
    has fixture_name: str = "";
    has seen: list[str] = [];
    has order_id_columns: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick_fixture with FlattenFixture entry {
        if here.label == self.fixture_name {
            self.order_id_columns = here.expected_columns;
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can walk_model with Model entry {
        if here.pattern == "LATERAL FLATTEN" {
            print(f"[fixture] {here.pattern} on {here.name}");
            visit [->:DependsOn:->];
        } else {
            visit [-->];
        }
    }

    can collect with Column entry {
        self.seen.append(here.name);
    }
}

with entry {
    root ++> FlattenFixture(
        label="LATERAL FLATTEN",
        expected_columns=["order_id", "item_sku"]
    );

    order_items = Model(name="order_items_flatten", pattern="LATERAL FLATTEN");
    root ++> order_items;

    order_items +>:DependsOn:+> Column(name="order_id");
    order_items +>:DependsOn:+> Column(name="item_sku");

    auditor = ColumnAuditor(fixture_name="LATERAL FLATTEN");
    root spawn auditor;

    matched = sorted(auditor.seen);
    expected = sorted(auditor.order_id_columns);
    verdict = "LOCKED IN" if matched == expected else "DRIFT";
    print(f"expected={expected}");
    print(f"observed={matched}");
    print(f"verdict={verdict}");
}
