"""Order auditor: skip invalid orders while the walk continues, halt on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting order audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"[AUDIT] approved order amount={here.amount}");
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=100, valid=True, fraud=False)
        ++> Order(amount=25, valid=False, fraud=False)
        ++> Order(amount=200, valid=True, fraud=False)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=50, valid=True, fraud=False);
    root spawn OrderAuditor();
}
