"""Test annex for the Cloud Streams subscriber retry policy bypass demo."""

import io;
import from contextlib { redirect_stdout }

# Build a helper to construct a standard failing-subscriber graph.
def build_graph() {
    failing_sub = Subscriber(
        uri="http://localhost:8888/some-endpoint",
        returns_success=False
    );
    sub = Subscription(
        name="all-events",
        subscriber_uri="http://localhost:8888/some-endpoint",
        policy=RetryPolicy(
            max_attempts=3,
            backoff_seconds=3,
            break_after=3,
            break_duration_seconds=5
        )
    );
    attempt = DispatchAttempt(offset=-1, http_status=503);

    root ++> sub;
    sub +>:RetryToDispatch:+> attempt;
    attempt +>:DispatchToRetry:+> sub;
    sub +>:DeliversTo(since_offset=-1):+> failing_sub;
    return sub;
}

test "broken path builds a fresh policy on every recursion" {
    build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn BrokenBroker();
    }
    out = buf.getvalue();
    policy_builds = out.count("RetryDispatch: fresh Polly policy");
    assert policy_builds >= 2, (
        f"expected fresh policy per recursion (counters reset every call); "
        f"got {policy_builds} policy builds in output:\n{out}"
    );
    assert "maxAttempts=3 never reached" in out, (
        f"output should call out that maxAttempts is never honored:\n{out}"
    );
}

test "broken path inflates delivery failures by recursive re-entry" {
    build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn BrokenBroker();
    }
    out = buf.getvalue();
    fail_lines = [ln for ln in out.splitlines() if "[FAIL]" in ln];
    assert len(fail_lines) >= 4, (
        f"recursive re-entry should produce many FAIL dispatches; "
        f"got {len(fail_lines)}:\n{out}"
    );
    total_failures = fail_lines[-1].split("total_failures=")[-1];
    assert int(total_failures) > 3, (
        f"TotalDeliveryFailures should be inflated beyond maxAttempts=3; "
        f"got {total_failures}:\n{out}"
    );
}

test "correct path bounds attempts to max_attempts and stops" {
    build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PolicyBroker();
    }
    out = buf.getvalue();
    attempt_lines = [ln for ln in out.splitlines() if "Polly attempt" in ln];
    assert len(attempt_lines) == 3, (
        f"expected exactly max_attempts=3 real attempts, "
        f"got {len(attempt_lines)}:\n{out}"
    );
    assert "Backoff: waiting 3s before next attempt" in out, (
        f"backoff should be honored between attempts:\n{out}"
    );
    assert "Policy stopped after 3 real attempts" in out, (
        f"policy must stop at max_attempts boundary:\n{out}"
    );
    assert "circuit_open=True" in out, (
        f"circuit should open when consecutive_failures >= break_after:\n{out}"
    );
}

test "circuit breaker pauses delivery when already open" {
    build_graph();
    # Pre-open the circuit on a manually-constructed walker, then re-spawn
    # via a fresh walker on a fresh graph so the program spawns it from root.
    # Easier: just spawn PolicyBroker once; once circuit_open, PolicyBroker
    # reports the break. Verify the open message appears.
    build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PolicyBroker();
    }
    out = buf.getvalue();
    assert "Circuit breaker opened after 3 consecutive failures" in out, (
        f"circuit breaker must open at break_after threshold:\n{out}"
    );
    # And a second spawn on a fresh graph with circuit pre-set would
    # short-circuit — confirm by directly building a pre-opened walker.
    failing_sub = Subscriber(
        uri="http://localhost:8888/some-endpoint",
        returns_success=False
    );
    sub = Subscription(
        name="all-events",
        subscriber_uri="http://localhost:8888/some-endpoint",
        policy=RetryPolicy(
            max_attempts=3,
            backoff_seconds=3,
            break_after=3,
            break_duration_seconds=5
        )
    );
    attempt = DispatchAttempt(offset=-1, http_status=503);
    root ++> sub;
    sub +>:RetryToDispatch:+> attempt;
    attempt +>:DispatchToRetry:+> sub;
    sub +>:DeliversTo(since_offset=-1):+> failing_sub;

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        pre = PolicyBroker();
        pre.circuit_open = True;
        pre spawn root;
    }
    out2 = buf2.getvalue();
    assert "Circuit OPEN" in out2 and "paused" in out2, (
        f"open circuit should pause delivery without attempts:\n{out2}"
    );
}

