"""Delivery dispatch checker: model depots and routes, then audit which loads qualify."""

node Route {
    has name: str = "";
    has cargo_tonnes: float = 0.0;
}

node Depot {
    has title: str = "";
}

walker DispatchAuditor {
    can start with Root entry {
