        visit [-->];
    }

    can audit_depot with Depot entry {
        print(f"Depot: {here.title}");
        visit [-->];
    }

    can audit_route with Route entry {
        qualifies = here.cargo_tonnes >= 2.0 and here.cargo_tonnes <= 8.0;
        status = "DISPATCH" if qualifies else "HOLD";
        print(f"  [{status}] {here.name}: {here.cargo_tonnes} tonnes");
        visit [-->];
    }
}

with entry {
    depot_a = Depot(title="North Hub");
    depot_b = Depot(title="South Hub");

