"""Tests for stable-indexed ordered collection demo.

Verifies the issue's promised behavior: indices are stable across inserts,
and use-sites bound by index remain OK after neighbors are inserted.
"""

import io;
import from contextlib { redirect_stdout }

# Helper: build the canonical 3-instruction basic block graph.
def make_demo_graph {
    bb = BasicBlock(block_name="bb0");
    root +>:OwnsBlock(role="entry"):+> bb;

    i1 = Instruction(opcode="load",  stable_index=1, alive=True);
    i2 = Instruction(opcode="add",   stable_index=2, alive=True);
    i3 = Instruction(opcode="store", stable_index=3, alive=True);
    bb +>:HasInstruction(ordinal=1):+> i1;
    bb +>:HasInstruction(ordinal=2):+> i2;
    bb +>:HasInstruction(ordinal=3):+> i3;

    root ++> UseSite(note="uses load",  bound_index=1)
        +>:References(kind="def-use", ordinal=1):+> i1;
    root ++> UseSite(note="uses add",   bound_index=2)
        +>:References(kind="def-use", ordinal=2):+> i2;
    root ++> UseSite(note="uses store", bound_index=3)
        +>:References(kind="def-use", ordinal=3):+> i3;

    return bb;
}

test "insert appends a new instruction at the end of the block" {
    bb = make_demo_graph();

    pre_count = len([bb-->]);
    assert pre_count == 3, f"expected 3 instructions before insert, got {pre_count}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        Inserter(new_op="ret", block=bb) spawn root;
    }
    out = buf.getvalue();

    post_count = len([bb-->]);
    assert post_count == 4, f"expected 4 instructions after insert, got {post_count}";
    assert "inserted ret at stable_index=4" in out, f"missing insert line: {out}";
}

test "pre-existing stable indices are unchanged after insert" {
    bb = make_demo_graph();

    before = {};
    for insn in [bb-->] {
        before[insn.stable_index] = insn.opcode;
    }
    assert before == {1: "load", 2: "add", 3: "store"}, f"setup wrong: {before}";

    Inserter(new_op="phi", block=bb) spawn root;

    after = {};
    for insn in [bb-->] {
        after[insn.stable_index] = insn.opcode;
    }
    # The original three indices must still map to the same opcodes,
    # because the whole point of stable indices is that inserts don't
    # renumber existing elements.
    assert after[1] == "load", f"index 1 changed: {after}";
    assert after[2] == "add",  f"index 2 changed: {after}";
    assert after[3] == "store", f"index 3 changed: {after}";
    # And the new element got a fresh index that didn't collide.
    assert 4 in after, f"no new instruction placed at index 4: {after}";
    assert after[4] == "phi", f"new instruction not at index 4: {after}";
}

test "use-sites bound to existing instructions all report OK after insert" {
    bb = make_demo_graph();

    Inserter(new_op="ret", block=bb) spawn root;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn UseAudit();
    }
    out = buf.getvalue();

    assert "[OK] use-site 'uses load'"  in out, f"load use-site not OK: {out}";
    assert "[OK] use-site 'uses add'"   in out, f"add use-site not OK: {out}";
    assert "[OK] use-site 'uses store'" in out, f"store use-site not OK: {out}";
    assert "BROKEN" not in out, f"some use-site became BROKEN after insert: {out}";
}

test "invalidator flips exactly the alive instruction at the target index" {
    bb = make_demo_graph();

    # Mark index 1 as already dead; target=2 must still be flipped, but
    # the dead one must NOT be touched or printed as invalidated.
    dead = [bb-->][?opcode == "load"][0];
    dead.alive = False;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        Invalidator(target_index=2) spawn root;
    }
    out = buf.getvalue();

    # Exactly one "invalidated" line, and it names the add at index 2.
    lines = [l for l in out.splitlines() if l.startswith("invalidated")];
    assert len(lines) == 1, f"expected exactly 1 invalidation, got {len(lines)}: {out}";
    assert "index 2" in lines[0] and "add" in lines[0],
        f"wrong instruction invalidated: {lines[0]}";

    # The targeted one is now dead; the pre-dead one stayed dead; the
    # other live ones are still alive.
    for insn in [bb-->] {
        if insn.stable_index == 2 {
            assert insn.alive == False, f"target not invalidated: {insn.alive}";
        } elif insn.opcode == "load" {
            assert insn.alive == False, f"pre-dead instruction was re-touched: {insn.alive}";
        } else {
            assert insn.alive == True, f"unrelated instruction was invalidated: {insn}";
        }
    }
}

test "use-sites bound to an invalidated index report BROKEN" {
    bb = make_demo_graph();

    Invalidator(target_index=2) spawn root;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn UseAudit();
    }
    out = buf.getvalue();

    # bound_index=2 (the add) should now be BROKEN.
    assert "[BROKEN] use-site 'uses add'" in out, f"add use-site not BROKEN: {out}";
    # The other two are still pointing at live instructions.
    assert "[OK] use-site 'uses load'"    in out, f"load use-site should still be OK: {out}";
    assert "[OK] use-site 'uses store'"   in out, f"store use-site should still be OK: {out}";
}

