import io;
import from contextlib { redirect_stdout }

test "pipeline disengages when no Inspects target exists" {
    rt = Root();
    # No Inspects edge at all -> start ability disengages immediately.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn PipelineRunner();
    }
    out = buf.getvalue();
    assert out == "", f"expected no output when no Inspects target, got: {out!r}";
}

test "pipeline traverses preflight then stages with verdicts in order" {
    rt = Root();
    src = SourceUnit(path="main.rs", byte_size=256, token_count=58);
    lex = AdmitStage(name="lex", order=1, ok=True);
    parse = AdmitStage(name="parse", order=2, ok=True);
    admit = AdmitStage(name="subset_admit", order=3, ok=True);
    typechk = AdmitStage(name="typecheck", order=4, ok=False);

    rt +>:Inspects:+> src;
    src +>:FeedsInto(note="lex"):+> lex;
    lex +>:FeedsInto(note="parse"):+> parse;
    parse +>:FeedsInto(note="admit"):+> admit;
    admit +>:FeedsInto(note="typecheck"):+> typechk;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn PipelineRunner();
    }
    out = buf.getvalue();
    assert "preflight main.rs: 256B, 58 tokens" in out, f"missing preflight line: {out}";
    assert "[1] lex: accept" in out, f"missing lex accept: {out}";
    assert "[2] parse: accept" in out, f"missing parse accept: {out}";
    assert "[3] subset_admit: accept" in out, f"missing subset_admit accept: {out}";
    assert "[4] typecheck: reject" in out, f"missing typecheck reject: {out}";
    # Ordering: preflight line before any stage verdict line.
    pf_idx = out.index("preflight main.rs");
    lex_idx = out.index("[1] lex");
    tc_idx = out.index("[4] typecheck");
    assert pf_idx < lex_idx < tc_idx, f"pipeline order wrong: {out}";
    # SourceUnit has exactly one downstream FeedsInto.
    assert len([src->:FeedsInto:->]) == 1, "source unit should feed one stage";
}

test "syntax preorder visits nodes in depth order and respects depth cap" {
    rt = Root();
    file = AstNode(syntax_kind="SourceFile", span_id="sf0", depth=0);
    item = AstNode(syntax_kind="FnItem", span_id="fn1", depth=1);
    body = AstNode(syntax_kind="BlockExpr", span_id="bx2", depth=2);
    call = AstNode(syntax_kind="MacroCall", span_id="mc3", depth=3);

    rt +>:ChildOf:+> file;
    file +>:ChildOf:+> item;
    item +>:ChildOf:+> body;
    body +>:ChildOf:+> call;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn SyntaxPreorder(max_depth=2);
    }
    out = buf.getvalue();
    assert "[0] SourceFile (sf0)" in out, f"missing root visit: {out}";
    assert "[1] FnItem (fn1)" in out, f"missing depth 1 visit: {out}";
    assert "[2] BlockExpr (bx2)" in out, f"missing depth 2 visit: {out}";
    # MacroCall at depth 3 exceeds max_depth=2 -> cap message and no visit body.
    assert "depth cap d=3" in out, f"expected depth cap message: {out}";
    assert "[3] MacroCall" not in out, f"depth 3 should not be printed as visited: {out}";
}

test "syntax preorder cycle guard halts re-entry on a shared span_id" {
    rt = Root();
    a = AstNode(syntax_kind="Item", span_id="x", depth=0);
    b = AstNode(syntax_kind="Item", span_id="y", depth=1);
    c = AstNode(syntax_kind="Item", span_id="x", depth=2);

    rt +>:ChildOf:+> a;
    a +>:ChildOf:+> b;
    b +>:ChildOf:+> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn SyntaxPreorder(max_depth=10);
    }
    out = buf.getvalue();
    # First 'x' (at depth 0) is recorded; second 'x' (at depth 2) trips cycle guard.
    assert "[0] Item (x)" in out, f"first x missing: {out}";
    assert "cycle guard: Item @x" in out, f"cycle guard missing: {out}";
    # 'y' at depth 1 should have been visited before hitting the second x.
    assert "[1] Item (y)" in out, f"missing intermediate y: {out}";
    # The depth-2 node should not print its visit header.
    assert "[2] Item (x)" not in out, f"cyclic node must not be entered: {out}";
}

test "syntax preorder with root holding no ChildOf edges prints nothing" {
