```jac
"""Restaurant kitchen health inspection.

A patrol walker walks each station (grill, fryer, cold prep) and runs
two checks at every stop: a temperature safety audit (anything above 40 C
is a violation) and a visit log. A union ability keeps the inspection
behavior identical across station types.
"""

node Station {
    has name: str = "";
    has temp_c: float = 0.0;
    has station_type: str = "";

    def label() -> str {
        return self.station_type;
    }
}

node Grill(Station) {
    has station_type: str = "grill";
    override def label() -> str {
        return "grill";
    }
}

node Fryer(Station) {
    has station_type: str = "fryer";
    override def label() -> str {
        return "fryer";
    }
}

node ColdPrep(Station) {
    has station_type: str = "cold prep";
    override def label() -> str {
        return "cold prep";
    }
}

edge ServesLine { }

walker HealthInspector {
    has violations: int = 0;
    has stations_checked: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Health inspector beginning kitchen line walk-through");
        visit [-->];
    }

    # Union trigger: every station type gets both checks.
    can inspect with Grill | Fryer | ColdPrep entry {
        self.stations_checked += 1;
        station_kind = here.label();
        self.log.append(f"Visited {here.name} ({station_kind}) at {here.temp_c} C");

        status = "VIOLATION" if here.temp_c > 40.0 else "OK";
        if here.temp_c > 40.0 {
            self.violations += 1;
            print(f"[{status}] {here.name} ({station_kind}): {here.temp_c} C exceeds 40 C");
        } else {
            print(f"[{status}] {here.name} ({station_kind}): {here.temp_c} C");
        }

        visit [-->];
    }
}

with entry {
    grill = Grill(name="Charbroiler #1", temp_c=215.0);
    fryer = Fryer(name="Deep Fryer #2", temp_c=180.0);
    cold_prep = ColdPrep(name="Salad Station", temp_c=4.5);

    root ++> grill ++> fryer ++> cold_prep;

    inspector = HealthInspector();
    root spawn inspector;

    print("---- Inspection summary ----");
    print(f"Stations checked: {inspector.stations_checked}");
    print(f"Violations found: {inspector.violations}");
    for entry_text in inspector.log {
        print(entry_text);
    }
}
