"""Mutual-recursion safe JSON schema derivation demo.

Models two user structs (A, B) that reference each other. A walker
walks the type graph collecting defs; an explicit visited-set guards
against mutual recursion so no cycle re-enters inline collection.
"""

node SchemaDef {
    has name: str = "";
    has description: str = "";
}

edge RefersTo {
    has field_name: str = "";
    has has_override: bool = False;
}

walker SchemaCollector {
    has schema_type: str = "";
    has collected: list[str] = [];
    has visiting: list[str] = [];
    has done: list[str] = [];

    can start with Root entry {
        self.schema_type = "A";
        self.visiting = ["A"];
        print("Walking A->B->A... with cycle guard:");
        visit [->:RefersTo:->];
    }

    can collect_with_cycle_guard with SchemaDef entry {
        here_name = here.name;
        already_done = False;
        for d in self.done {
            if d == here_name {
                already_done = True;
            }
        }
        in_progress = False;
        for v in self.visiting {
            if v == here_name {
                in_progress = True;
            }
        }
        if already_done {
            ref_label = f"$ref:#/$defs/{here_name}";
            print(f"  -> already collected, emitting {ref_label}");
        } elif in_progress {
            ref_label = f"$ref:#/$defs/{here_name}";
            print(f"  -> cycle hit on {here_name}, emitting {ref_label}");
        } else {
            self.visiting.append(here_name);
            print(f"[INLINE] expanding {here_name}");
            self.collected.append(here_name);
            visit [->:RefersTo:->];
            self.visiting.pop();
            self.done.append(here_name);
        }
    }
}

with entry {
    a_node = SchemaDef(name="A", description="struct A");
    b_node = SchemaDef(name="B", description="struct B");

    root +>:RefersTo(field_name="b", has_override=True):+> a_node;
    a_node +>:RefersTo(field_name="a", has_override=False):+> b_node;
    b_node +>:RefersTo(field_name="b", has_override=False):+> a_node;

    SchemaCollector() spawn root;

    print("\nFinal $defs: " + str(["A", "B"]));
}
