    assert b_node in [a_node ->:RefersTo:->], "A does not refer to B";
    assert a_node in [b_node ->:RefersTo:->], "B does not refer to A";
    assert a_node.name == "A", f"got {a_node.name}";
    assert b_node.name == "B", f"got {b_node.name}";
