    b_node +>:RefersTo(field_name="a", has_override=False):+> a_node;
    a_node +>:RefersTo(field_name="b", has_override=False):+> b_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SchemaCollector();
    }
    out = buf.getvalue();

    assert "Walking A->B->A... with cycle guard:" in out, f"missing walk marker: {out}";
    assert "[INLINE] expanding B" in out, f"missing B expansion: {out}";
    assert "cycle hit on A" in out, f"missing cycle marker: {out}";
    assert "$ref:#/$defs/A" in out, f"missing A ref: {out}";
    assert "[INLINE] expanding A" not in out, f"A was expanded recursively: {out}";
    assert res.collected == ["B"], f"got {res.collected}";
    assert res.done == ["B"], f"got {res.done}";
}

