```jac
"""Modular monolith demo: cross-module communication via interfaces and event contracts.

Models the migration from hand-rolled cross-module calls to public synchronous
interfaces and versioned event contracts. Demonstrates:
  - A Sales module exposes a synchronous call contract (public interface).
  - An Inventory module owns stock state and publishes a versioned event when
    stock changes; consumers subscribe through the contract, not a raw topic.
  - A Shipping module reacts to the Inventory event asynchronously, but reads
    shipment state only via Shipping's own public interface.
  - An Orchestrator walker traverses the module graph to detect cycles, prove
    acyclic reachability, and demonstrate both the sync call and async event.
"""

# ---------------------------------------------------------------------------
# Event contract: versioned, owned by Inventory.
# ---------------------------------------------------------------------------
edge EmitsInventoryEvent { }

# ---------------------------------------------------------------------------
# Module nodes — each represents one bounded context in the monolith.
# ---------------------------------------------------------------------------
node Sales {
    has name: str = "";
    has open_orders: int = 0;
}

node Inventory {
    has name: str = "";
    has units_on_hand: int = 0;
}

node Shipping {
    has name: str = "";
    has dispatched: int = 0;
    has received_event_v: int = 0;
}

# Orchestrator lives in its own workflow module — neither Sales nor Inventory
# nor Shipping owns it; it owns the cross-module coordination.
node Orchestrator {
    has name: str = "";
}

# ---------------------------------------------------------------------------
# Public synchronous interfaces — declared as edges so the dependency graph
# is part of the schema and an architecture check can read it.
# A typed edge from caller -> callee means "caller depends on callee".
# ---------------------------------------------------------------------------
edge CallsSync {
    has operation: str = "";
}

edge SubscribesTo {
    has since_version: int = 1;
}

edge OwnsStateOf { }

# ---------------------------------------------------------------------------
# Walker: detect cycles in the synchronous dependency graph and demonstrate
# both a sync call and an async event reaction through the new seams.
# ---------------------------------------------------------------------------
walker AuditModules {
    has visited: list[str] = [];
    has sync_stack: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("=== Module dependency audit ===");
        visit [-->];
    }

    can descend with Orchestrator entry {
        print(f"Entering workflow module: {here.name}");
        visit [->:CallsSync:->];
    }

    # When the walker crosses a sync edge it tracks the path so a cycle
    # would be observable. Cycle policy is domain logic — kept explicit.
    can cross_sync with Sales | Inventory | Shipping entry {
        module_name = here.name;
        if module_name in self.visited {
            self.cycle_detected = True;
            print(f"  cycle: re-entered {module_name}");
            disengage;
        }
        self.visited = self.visited + [module_name];
        self.sync_stack = self.sync_stack + [module_name];
        print(f"  sync-call -> {module_name} (stack: {self.sync_stack})");
        visit [->:CallsSync:->];
    }
}

walker PlaceOrder {
    has order_id: str = "";
    has qty: int = 0;

    can start with Root entry {
        # Orchestrator owns this flow — it coordinates, Sales owns the order.
        print(f"\n=== Orchestrator places order {self.order_id} for qty={self.qty} ===");
        visit [-->];
    }

    can coordinate with Orchestrator entry {
        # 1) Synchronous call contract: Sales.create_order is the public
        #    interface; Sales does not call Inventory directly.
        visit [->:CallsSync:->];
    }

    # SYNC: Sales owns open_orders and exposes it via its public interface.
    can record_with_sales with Sales entry {
        here.open_orders = here.open_orders + self.qty;
        print(f"  [SYNC ] Sales.open_orders now {here.open_orders}");
        # Sales commits -> emits an event owned by Inventory, via the typed
        # subscription edge, not a raw topic string.
        visit [->:EmitsInventoryEvent:->];
    }

    # Inventory owns units_on_hand (its own state) and reacts synchronously
    # to the Sales commit, then publishes a versioned event.
    can adjust_inventory with Inventory entry {
        here.units_on_hand = here.units_on_hand - self.qty;
        print(f"  [SYNC ] Inventory.units_on_hand now {here.units_on_hand}");
    }

    # ASYNC: Shipping subscribes to InventoryEvent (typed edge), receives
    # v1 of the contract, and reacts. It does NOT read Inventory state.
    can ship_async with Shipping entry {
        here.dispatched = here.dispatched + self.qty;
        here.received_event_v = 1;
        print(f"  [ASYNC] Shipping dispatched {here.dispatched} "
              f"(event v{here.received_event_v} consumed via contract)");
        disengage;
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------
with entry {
    sales = Sales(name="Sales");
    inventory = Inventory(name="Inventory");
    shipping = Shipping(name="Shipping");
    orchestrator = Orchestrator(name="OrderWorkflow");

    # Orchestrator depends on Sales synchronously (it needs the immediate
    # "order accepted" decision).
    orchestrator +>:CallsSync(operation="create_order"):+> sales;

    # Sales emits an inventory event when an order is committed.
    sales +>:EmitsInventoryEvent:+> inventory;

    # Shipping subscribes to the inventory event through the contract.
    inventory +>:SubscribesTo(since_version=1):+> shipping;

    # State ownership is declared, not assumed.
    sales +>:OwnsStateOf:+> sales;
    inventory +>:OwnsStateOf:+> inventory;
    shipping +>:OwnsStateOf:+> shipping;

    root ++> orchestrator;

    # 1) Audit: prove the synchronous module graph is acyclic.
    root spawn AuditModules();
    print(f"sync graph cycle detected? {AuditModules().cycle_detected}");

    # 2) End-to-end: one order exercises BOTH the sync call (Sales) and
    #    the async event reaction (Shipping via Inventory contract).
    root spawn PlaceOrder(order_id="PO-42", qty=3);
}
