"""Gallery security console: visitors are logged generically; curators trigger
an official inspection and a per-curator room count."""

node Room {
    has name: str = "";
    has log: list[str] = [];
}

walker Visitor {
    has visitor_name: str = "";
    can start with Root entry {
        visit [-->];
    }
    can enter with Room entry {
        here.log.append(f"visitor: {self.visitor_name}");
        print(f"{self.visitor_name} entered {here.name}: generic log updated");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has rooms_inspected: int = 0;
    can start with Root entry {
        visit [-->];
    }
    can inspect with Room entry {
        # Generic visitor log entry (the room logs everyone).
        here.log.append(f"visitor: {self.curator_name}");
        # Official inspection record on top.
        here.log.append(f"inspection by curator: {self.curator_name}");
        self.rooms_inspected += 1;
        print(f"{self.curator_name} inspected {here.name} "
              f"(rooms inspected so far: {self.rooms_inspected})");
        visit [-->];
    }
}

with entry {
    gallery_a = Room(name="Gallery A");
    gallery_b = Room(name="Gallery B");
    root ++> gallery_a ++> gallery_b;

    tourist = Visitor(visitor_name="Alice");
    root spawn tourist;

    curator = Curator(curator_name="Dr. Bell");
