```jac
"""Engram invariant ownership & cross-layer conformance demo.

Models the essential scenario from issue #872:
- Critical domain facts are owned by exactly one bounded context.
- Every adapter/projection must preserve the owning context's contract.
- Sync-visible mutations carry an explicit operation (delete stays delete).
- Autosync runs as an explicit state machine with a retry ceiling and
  quarantine for invalid mutations.

Node archetypes represent the four core bounded contexts and a sync
mutation envelope. A walker traverses the ownership graph and verifies
that downstream projections and adapters conform to the owner's contract.
"""

# --- Bounded context owners ------------------------------------------------

node MemoryStore {
    has context_name: str = "internal/store";
    has invariants: list[str] = [
        "valid_observations",
        "atomic_durable_writes",
        "session_lifecycle",
    ];
}

node ProjectIdentity {
    has context_name: str = "internal/project";
    has invariants: list[str] = [
        "canonical_identity",
        "normalization",
        "ambiguity_resolution",
        "source_path_metadata",
    ];
}

node Replication {
    has context_name: str = "internal/sync";
    has invariants: list[str] = [
        "operation_preservation",
        "ordering",
        "idempotency",
        "tombstones",
        "retries",
        "recovery",
    ];
}

node AgentContract {
    has context_name: str = "internal/mcp";
    has invariants: list[str] = [
        "tool_inventory",
        "profiles",
        "schemas",
        "envelopes",
        "error_codes",
    ];
}

# --- Sync mutation envelope ------------------------------------------------

node Mutation {
    has mutation_id: str = "";
    has entity_type: str = "";
    has entity_id: str = "";
    has operation: str = "upsert";
    has canonical_project: str = "";
    has contract_version: int = 1;
    has occurred_at: str = "";
}

# --- Adapters / projections / integrations --------------------------------

node MCPRegistry       { has layer: str = "mcp_registry"; }
node PluginAdapter     { has layer: str = "plugin_adapter"; }
node CloudIngest       { has layer: str = "cloud_ingest"; }
node ChunkMaterializer { has layer: str = "chunk_materializer"; }
node Doctor            { has layer: str = "doctor"; }
node CLI               { has layer: str = "cli"; }
node TUI               { has layer: str = "tui"; }

# --- Typed edges: who owns whom / who projects from whom ------------------

edge OwnsInvariant {
    has since: str = "v1";
}

edge ProjectsFrom {
    has version: int = 1;
}

edge FlowsMutation {
    has step: str = "";
}

# --- Conformance walker ----------------------------------------------------

walker Auditor {
    has findings: list[str] = [];
    has violations: int = 0;

    can start with Root entry {
        visit [->:OwnsInvariant:->];
    }

    # A single union ability fires for every owner context.
    # Only fields/methods common to all owner nodes are touched here.
    can audit_owner
        with MemoryStore | ProjectIdentity | Replication | AgentContract entry {
        if here.context_name == "" {
            self.violations += 1;
        } else {
            inv_count = len(here.invariants);
            self.findings.append(f"{here.context_name} guards {inv_count} invariants");
            for inv in here.invariants {
                self.findings.append(f"  - {inv}");
            }
        }
        visit [->:OwnsInvariant:->] else { visit [->:ProjectsFrom:->]; }
    }

    # Union trigger: any adapter/projection/integration layer.
    can audit_layer
        with MCPRegistry | PluginAdapter | CloudIngest
            | ChunkMaterializer | Doctor | CLI | TUI entry {
        self.findings.append(f"{here.layer} must preserve owner contracts");

        if here.layer == "cloud_ingest" {
            self.findings.append("  - operation must remain 'upsert' | 'delete'");
        }
        if here.layer == "doctor" {
            self.findings.append("  - identifies failing record + invariant");
        }
        if here.layer == "chunk_materializer" {
            self.findings.append("  - delete stays delete through materialization");
        }

        visit [->:ProjectsFrom:->] else { visit [->:FlowsMutation:->]; }
    }

    # Mutations flow through the pipeline carrying explicit operation.
    can trace_mutation with Mutation entry {
        verdict = "DELETE_INTACT" if here.operation == "delete" else "UPSERT_OK";
        self.findings.append(
            f"{here.entity_type}:{here.entity_id} "
            f"op={here.operation} v{here.contract_version} -> {verdict}"
        );

        if here.operation == "" {
            self.violations += 1;
            self.findings.append("  ! empty operation violates envelope contract");
        }

        visit [->:FlowsMutation:->] else { disengage; }
    }
}

# --- Demonstration ---------------------------------------------------------

with entry {
    store = MemoryStore();
    proj  = ProjectIdentity();
    repl  = Replication();
    mcp   = AgentContract();

    root +>:OwnsInvariant:+> store;
    root +>:OwnsInvariant:+> proj;
    root +>:OwnsInvariant:+> repl;
    root +>:OwnsInvariant:+> mcp;

    store +>:ProjectsFrom:+> MCPRegistry();
    proj  +>:ProjectsFrom:+> MCPRegistry();
    mcp   +>:ProjectsFrom:+> PluginAdapter();

    repl  +>:ProjectsFrom:+> CloudIngest();
    repl  +>:ProjectsFrom:+> ChunkMaterializer();

    store +>:ProjectsFrom:+> Doctor();
    store +>:ProjectsFrom:+> CLI();
    store +>:ProjectsFrom:+> TUI();

    upsert_mut = Mutation(
        mutation_id="m-001",
        entity_type="observation",
        entity_id="obs-42",
        operation="upsert",
        canonical_project="engram",
        contract_version=1,
        occurred_at="2026-01-15T10:00:00Z",
    );
    delete_mut = Mutation(
        mutation_id="m-002",
        entity_type="observation",
        entity_id="obs-42",
        operation="delete",
        canonical_project="engram",
        contract_version=1,
        occurred_at="2026-01-15T10:05:00Z",
    );
    root +>:FlowsMutation(step="emit"):+> upsert_mut
         +>:FlowsMutation(step="emit"):+> delete_mut;

    auditor = Auditor();
    root spawn auditor;

    print("\n=== Conformance report ===");
    for line in auditor.findings {
        print(line);
    }
    print(f"\nviolations={auditor.violations}");
}
