"""Cave expedition transcript — test annex."""

import io;
import from contextlib { redirect_stdout }

test "single chamber enter then exit" {
    rt = root;
    only = Chamber(label="Solo");
    rt ++> only;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Explorer();
    }
    out = buf.getvalue();

    enter_idx = out.find("ENTER Solo");
    exit_idx = out.find("EXIT  Solo");
    assert enter_idx != -1, f"missing ENTER Solo in: {out!r}";
    assert exit_idx != -1, f"missing EXIT Solo in: {out!r}";
    assert enter_idx < exit_idx, f"ENTER must precede EXIT, got: {out!r}";
    assert res.depth == 1, f"depth after one chamber should be 1, got {res.depth}";
}

test "two chamber expedition reverses on exit" {
    rt = root;
    first = Chamber(label="Entry Hall");
    second = Chamber(label="Inner Room");
    rt ++> first ++> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Explorer();
    }
    out = buf.getvalue();

    enter_first = out.find("ENTER Entry Hall");
    enter_second = out.find("ENTER Inner Room");
    exit_first = out.find("EXIT  Entry Hall");
    exit_second = out.find("EXIT  Inner Room");

    assert enter_first != -1, f"missing ENTER Entry Hall: {out!r}";
    assert enter_second != -1, f"missing ENTER Inner Room: {out!r}";
    assert exit_first != -1, f"missing EXIT Entry Hall: {out!r}";
    assert exit_second != -1, f"missing EXIT Inner Room: {out!r}";

    # Entries arrive in walking order: outer before inner.
    assert enter_first < enter_second, f"outer ENTER must come first: {out!r}";
    # Exits unwind in reverse: inner leaves before outer.
    assert exit_second < exit_first, f"inner EXIT must come before outer EXIT: {out!r}";
    # All entries must precede all exits.
    assert enter_second < exit_second, f"all ENTERs must precede EXITs: {out!r}";
    assert res.depth == 2, f"depth after two chambers should be 2, got {res.depth}";
}

test "three chamber full transcript order" {
    rt = root;
    mouth = Chamber(label="Mouth");
    tunnel = Chamber(label="Tunnel");
    cavern = Chamber(label="Crystal Cavern");
    rt ++> mouth ++> tunnel ++> cavern;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Explorer();
    }
    out = buf.getvalue();

    expected = (
        "ENTER Mouth\n"
        "ENTER Tunnel\n"
        "ENTER Crystal Cavern\n"
        "EXIT  Crystal Cavern\n"
        "EXIT  Tunnel\n"
        "EXIT  Mouth\n"
    );
    assert out == expected, f"transcript mismatch.\nExpected:\n{expected!r}\nGot:\n{out!r}";
    assert res.depth == 3, f"depth after three chambers should be 3, got {res.depth}";
}

test "no chambers yields only root traversal no chamber events" {
    rt = root;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Explorer();
    }
    out = buf.getvalue();

    assert "ENTER" not in out, f"no chambers means no ENTER, got: {out!r}";
    assert "EXIT" not in out, f"no chambers means no EXIT, got: {out!r}";
    assert res.depth == 0, f"depth with no chambers should be 0, got {res.depth}";
}

test "depth equals number of chambers visited" {
    rt = root;
    a = Chamber(label="A");
    b = Chamber(label="B");
    c = Chamber(label="C");
    d = Chamber(label="D");
    rt ++> a ++> b ++> c ++> d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Explorer();
    }
    out = buf.getvalue();

    assert res.depth == 4, f"depth after four chained chambers should be 4, got {res.depth}";

    # Confirm ordering: every ENTER precedes its corresponding EXIT,
    # and exits unwind in reverse.
    labels = ["A", "B", "C", "D"];
    enter_positions = [out.find(f"ENTER {lbl}") for lbl in labels];
    exit_positions = [out.find(f"EXIT  {lbl}") for lbl in labels];
    for p in enter_positions {
        assert p != -1, f"missing ENTER: {out!r}";
    }
    for p in exit_positions {
        assert p != -1, f"missing EXIT: {out!r}";
    }
    # Entries monotone in walking order.
    for i in range(len(labels) - 1) {
        assert enter_positions[i] < enter_positions[i + 1],
            f"ENTER {labels[i]} must precede ENTER {labels[i + 1]}: {out!r}";
    }
    # Exits strictly reverse.
    for i in range(len(labels) - 1) {
        assert exit_positions[i + 1] < exit_positions[i],
            f"EXIT {labels[i + 1]} must precede EXIT {labels[i]}: {out!r}";
    }
}
