"""Recursive schema cycle demo.

Models mutually recursive schema entities (ApiConfiguration-read and
BusinessRegistryConfiguration-read) as nodes connected by typed
``References`` edges, then walks the graph to detect the cycle the
OpenAPI generator issue complains about. Demonstrates an explicit
cycle guard, since walkers in Jac 0.36.1 do not deduplicate revisited
nodes automatically.
"""

node ApiConfig {
    has name: str = "";
}

node BusinessRegistryConfig {
    has name: str = "";
}

# Typed edge whose meaning is "this schema references that schema".
edge References { }

walker CycleDetector {
    has visited_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("starting cycle detection over the schema graph");
        visit [-->];
    }

    # Union trigger: one routine handles both schema node kinds. Each
    # node exposes a ``name`` field, so the ability only touches
    # shared fields. The explicit guard set is the cycle policy --
    # the scaffolding dies but the semantics are preserved.
    can inspect with ApiConfig | BusinessRegistryConfig entry {
        node_id: str = here.name;
        path: str = " -> ".join(self.visited_ids + [node_id]);
        print(f"  visiting {node_id}  (path so far: {path})");

        if node_id in self.visited_ids {
            self.cycle_found = True;
            print(f"  CYCLE detected: {node_id} already seen");
            disengage;
        }
        self.visited_ids.append(node_id);

        # Walk every outgoing ``References`` edge one at a time so
        # we never re-enter a node and never spin forever -- this is
        # the explicit cycle policy that replaces the missing
        # walker-level deduplication in jac 0.36.1.
        next_nodes: list = [->:References:->];
        stepped: bool = False;
        for n in next_nodes {
            stepped = True;
            visit n;
        }
        if not stepped {
            disengage;
        }
    }
}

with entry {
    # Two mutually recursive schemas: each holds a typed-edge
    # reference to the other, exactly like the OpenAPI generator
    # problem the issue describes.
    api = ApiConfig(name="ApiConfigurationRead");
    biz = BusinessRegistryConfig(name="BusinessRegistryConfigurationRead");

    api +>:References:+> biz;
    biz +>:References:+> api;

    # A non-cyclic sibling branch, so the walker has something to
    # walk past too (mirrors the wider spec the user was generating).
    lone = BusinessRegistryConfig(name="LoneConfig");
    biz +>:References:+> lone;

    root ++> api;
    root ++> biz;
    root ++> lone;

    detector = CycleDetector();
    root spawn detector;

    if detector.cycle_found {
        print(f"result: cycle present; "
              f"order traversed = {detector.visited_ids}; "
              f"the generator must wrap back-edges in Schema.suspend");
    } else {
        print("result: no cycle detected");
    }
}
