            self.visited.append(here.name);
            print(f"{self.greeting} from {here.name}, visiting {self.visited}");
        }
        # Forward-only traversal; the visited list keeps us from bouncing
        # forever between two mutually-linked houses.
        next_houses = [h for h in [-->] if h.name not in self.visited];
