```jac
"""Paged KV block allocation model.

Models the sparse-attention compressed-KV scenario: a query row references
two physical KV blocks via ``cmp_sparse_indices``. The bug is that PA_ND
issued a single strided DMA starting from the lower physical address,
so the merged K/V row order depended on which physical block was
allocated first. Logical order from ``cmp_sparse_indices`` must win.

We model this with one walker ability: ``Auditor`` walks the page
table and, for each compressed-KV pair slot, prints the merged row
order under both the *buggy* physical-order rule and the *fixed*
logical-order rule.
"""

# A physical paged KV block. Each block holds ``block_size`` rows of K/V
# data; the row values themselves are intact in either order.
node KvBlock {
    has block_id: int = 0;
    has block_size: int = 0;
    has gm_offset: int = 0;
    has rows: list[int] = [];
}

# A compressed sparse index referencing two physical blocks in the order
# the operator *logically* consumes them.
node SparseIndex {
    has index_id: int = 0;
    has slot: int = 0;
}

# The query row that owns a list of ``SparseIndex`` entries.
node QueryRow {
    has row_id: int = 0;
    has total_pairs: int = 0;
}

edge PhysicalAlloc {
    has allocated_at: int = 0;
}

edge LogicalPair {
    has pair_slot: int = 0;
}

walker Auditor {
    has total_slots: int = 0;
    has current_slot: int = -1;

    can start with Root entry {
        self.total_slots = 0;
        self.current_slot = -1;
        visit [-->];
    }

    can gather with QueryRow entry {
        print(f"QueryRow {here.row_id} references {here.total_pairs} compressed-KV pairs");
        visit [->:LogicalPair:->];
    }

    can pair with SparseIndex entry {
        self.current_slot = here.slot;
        self.total_slots = self.total_slots + 1;
        blocks = [here->:PhysicalAlloc:->];
        if len(blocks) >= 2 {
            b1 = blocks[0];
            b2 = blocks[1];
            # Logical order (FIX): concatenate in cmp_sparse_indices order.
            merged_logical = list(b1.rows) + list(b2.rows);
            # Physical order (BUG): pick the block with the lower gm_offset first.
            if b1.gm_offset <= b2.gm_offset {
                first_block = b1;
                second_block = b2;
            } else {
                first_block = b2;
                second_block = b1;
            }
            merged_physical = list(first_block.rows) + list(second_block.rows);
            print(
                f"  [slot={self.current_slot}] BUG physical-order merged = {merged_physical}"
            );
            print(
                f"  [slot={self.current_slot}] FIX logical-order merged  = {merged_logical}"
            );
        } else {
            print(f"  [slot={self.current_slot}] fewer than 2 physical blocks attached");
        }
        visit [-->];
    }
}

with entry {
    # Three physical paged KV blocks; gm_offset simulates runtime allocator state.
    blk_a = KvBlock(block_id=0, block_size=3, gm_offset=100, rows=[1, 2, 3]);
    blk_b = KvBlock(block_id=1, block_size=3, gm_offset=500, rows=[4, 5, 6]);
    blk_c = KvBlock(block_id=2, block_size=3, gm_offset=900, rows=[7, 8, 9]);
    blk_d = KvBlock(block_id=3, block_size=3, gm_offset=1300, rows=[10, 11, 12]);

    # Two compressed-sparse pairs in the *logical* order given by cmp_sparse_indices.
    idx_0 = SparseIndex(index_id=0, slot=0);
    idx_1 = SparseIndex(index_id=1, slot=1);

    # Query row that owns both indices. total_pairs = 2 per the issue scenario.
    qr = QueryRow(row_id=629, total_pairs=2);

    # Wire the graph: root -> QueryRow -> SparseIndex -LogicalPair-> SparseIndex.
    root ++> qr ++> idx_0 ++> idx_1;

    # Logical pair edges connect indices to their next sibling.
    idx_0 +>:LogicalPair(pair_slot=0):+> idx_1;

    # Physical block allocation. Notice blk_a has a *lower* gm_offset than blk_b,
    # and blk_c has a *lower* gm_offset than blk_d -- exactly the kind of
    # allocation state that permutes the buggy merged row order.
    idx_0 +>:PhysicalAlloc(allocated_at=100):+> blk_a;
    idx_0 +>:PhysicalAlloc(allocated_at=500):+> blk_b;

    idx_1 +>:PhysicalAlloc(allocated_at=900):+> blk_c;
    idx_1 +>:PhysicalAlloc(allocated_at=1300):+> blk_d;

    # A second allocation layout for the same logical indices, demonstrating
    # that flipping the physical addresses is what changes the buggy output.
    alt_blk_x = KvBlock(block_id=10, block_size=3, gm_offset=2500, rows=[1, 2, 3]);
    alt_blk_y = KvBlock(block_id=11, block_size=3, gm_offset=2200, rows=[4, 5, 6]);
    idx_0 +>:PhysicalAlloc(allocated_at=2200):+> alt_blk_y;
    idx_0 +>:PhysicalAlloc(allocated_at=2500):+> alt_blk_x;

    print("=== First allocator layout (blk_a < blk_b by gm_offset) ===");
    root spawn Auditor();

    # Now flip the physical block layout for idx_0 to show the BUG
    # changes while the FIX stays the same.
    idx_0 del --> blk_a;
    idx_0 del --> blk_b;
    idx_0 +>:PhysicalAlloc(allocated_at=800):+> blk_b;
    idx_0 +>:PhysicalAlloc(allocated_at=300):+> blk_a;

    print("=== Second allocator layout (blk_b < blk_a by gm_offset) ===");
    root spawn Auditor();
