"""Tests for OrderAuditor: skip invalid, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

# Build a chain of Order nodes from a list of dicts under `root`,
# then spawn OrderAuditor and return captured stdout.
def run_auditor(orders: list) -> str {
    prev = root;
    for o in orders {
        n = Order(amount=o["amount"], is_valid=o["is_valid"], is_fraud=o.get("is_fraud", False));
        prev ++> n;
        prev = n;
    }
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    return buf.getvalue();
}


test "invalid orders are skipped and walk continues" {
    # No fraud in this chain; the one invalid order must be skipped with [SKIP]
    # and the walk must keep going to later valid orders.
    out = run_auditor([
        {"amount": 100, "is_valid": True},
        {"amount": 50,  "is_valid": False},
        {"amount": 200, "is_valid": True},
        {"amount": 75,  "is_valid": True},
    ]);
    lines = [l for l in out.splitlines() if l.strip()];

    assert "[SKIP] order amount=50" in lines, f"missing SKIP line: {lines}";
    assert "[AUDIT] order amount=100" in lines, f"missing first AUDIT: {lines}";
    assert "[AUDIT] order amount=200" in lines, f"missing AUDIT after SKIP: {lines}";
    assert "[AUDIT] order amount=75"  in lines, f"walk did not continue past SKIP: {lines}";

    # Walk should reach every order — the SKIP path must visit [-->] else.
    assert len(lines) == 4, f"expected 4 audit lines, got {len(lines)}: {lines}";
}

test "fraud order halts the entire walk immediately" {
    # A fraud order appears in the middle; nothing after it should be audited.
    out = run_auditor([
        {"amount": 100, "is_valid": True},
        {"amount": 999, "is_valid": True, "is_fraud": True},
        {"amount": 200, "is_valid": True},
        {"amount": 75,  "is_valid": True},
    ]);
    lines = [l for l in out.splitlines() if l.strip()];

    assert "[AUDIT] order amount=100" in lines, f"missing pre-fraud AUDIT: {lines}";
    assert "[HALT] fraud flagged amount=999" in lines, f"missing HALT line: {lines}";
    assert "[AUDIT] order amount=200" not in lines, f"walk continued after fraud: {lines}";
    assert "[AUDIT] order amount=75"  not in lines, f"walk continued after fraud: {lines}";

    # Exactly one audit before the halt, then the halt itself — nothing after.
    assert len(lines) == 2, f"expected 2 lines (AUDIT+HALT), got {len(lines)}: {lines}";
}

test "fraud on the first order halts before any audit" {
    out = run_auditor([
        {"amount": 999, "is_valid": True, "is_fraud": True},
        {"amount": 100, "is_valid": True},
    ]);
    lines = [l for l in out.splitlines() if l.strip()];

    assert lines == ["[HALT] fraud flagged amount=999"], f"unexpected output: {lines}";
    assert "[AUDIT] order amount=100" not in lines, f"audit ran despite fraud-first: {lines}";
}

test "all invalid orders produce only SKIP lines and walk still progresses" {
    # Several invalid orders in a row — each should print SKIP and the walker
    # must keep moving to the next order instead of disengaging.
    out = run_auditor([
        {"amount": 10, "is_valid": False},
        {"amount": 20, "is_valid": False},
        {"amount": 30, "is_valid": False},
    ]);
    lines = [l for l in out.splitlines() if l.strip()];

    assert "[SKIP] order amount=10" in lines, f"missing SKIP 10: {lines}";
    assert "[SKIP] order amount=20" in lines, f"missing SKIP 20: {lines}";
    assert "[SKIP] order amount=30" in lines, f"missing SKIP 30: {lines}";
    assert not any("[HALT]" in l for l in lines), f"unexpected halt: {lines}";
    assert not any("[AUDIT]" in l for l in lines), f"unexpected audit: {lines}";
    assert len(lines) == 3, f"expected 3 SKIP lines, got {len(lines)}: {lines}";
}

