"""Workflow retirement: model orphaned/authoritative workflows and reconcile authority.

Models a CI workflow catalog where each workflow has an inventory classification,
current callers/consumers, retirement reason, and historical evidence. A walker
walks the graph and reconciles authority by flagging workflows whose live
state contradicts their source-of-truth retirement status.
"""

node Workflow {
    has title: str = "";
    has classification: str = "";   # orphan | expired | obsolete | duplicate | authoritative | specialized
    has retirement_reason: str = "";
    has historical_evidence: str = "";
    has live_state: str = "";       # enabled | disabled | not_proven
    has reconciled: bool = False;
}

edge Calls {
    has consumer: str = "";
    has policy_ref: str = "";
}

edge ReplacedBy {
    has replacement: str = "";
}

walker Auditor {
    has visited: list[str] = [];
    has depth_limit: int = 10;
    has has_cycle: bool = False;

    can start with Root entry {
        self.visited = [];
        visit [-->] else { disengage; }
    }

    can audit with Workflow entry {
        # Explicit cycle guard — walkers do not dedupe automatically.
        if here.title in self.visited {
            self.has_cycle = True;
            print(f"[CYCLE] revisit of '{here.title}' — graph has a loop");
            disengage;
        }
        self.visited = self.visited + [here.title];

        # Reconcile source retirement classification against live state.
        if here.classification in ["orphan", "expired", "obsolete", "duplicate"] {
            if here.live_state == "enabled" {
                here.reconciled = False;
                print(f"[CONFLICT] '{here.title}' marked {here.classification} but still enabled live");
            } elif here.live_state == "not_proven" {
                here.reconciled = False;
                print(f"[UNCERTAIN] '{here.title}' {here.classification}, live state not_proven — must verify");
            } else {
                here.reconciled = True;
                print(f"[OK] '{here.title}' {here.classification} and disabled; evidence: {here.historical_evidence}");
            }
        } elif here.classification == "authoritative" {
            # Authoritative lanes must be untouched unless transition is reviewed.
            here.reconciled = True;
            print(f"[AUTH] '{here.title}' preserved as authoritative");
        } elif here.classification == "specialized" {
            # Specialized workflows are kept even when uncommon.
            here.reconciled = True;
            print(f"[KEEP] '{here.title}' specialized, uncommon but retained");
        }

        if len(self.visited) >= self.depth_limit {
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

