```jac
"""Generic function instantiation graph.

Models the kofun compiler's rank-1 generic function lowering: a source
declaration (``GenericDecl``) yields one ``Instance`` per concrete type
tuple admitted by substitution, and instances are linked back to the
declaration they instantiate plus to every other instance they call
(forming a bounded call-closure). A walker performs the recursive
discovery the issue asks for — bounded by depth, de-duplicated, with
unsupported recursion rejected before any artifact is emitted.
"""

node GenericDecl {
    has name: str = "";
    has arity: int = 0;
}

node Instance {
    has type_tuple: str = "";
    has depth: int = 0;
    has admits: bool = True;
}

edge Declares { }
edge Instantiates { }
edge Calls { }

walker Instantiate {
    has max_depth: int = 3;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:Declares:->];
    }

    can discover with GenericDecl entry {
        print(f"decl {here.name} arity={here.arity}");
        visit [->:Instantiates:->];
    }

    can visit_inst with Instance entry {
        if here.depth > self.max_depth {
            here.admits = False;
            print(f"  reject {here.type_tuple}: depth>{self.max_depth}");
            disengage;
        }
        if here.type_tuple in self.seen {
            print(f"  dedup {here.type_tuple}");
            disengage;
        }
        self.seen.append(here.type_tuple);
        print(f"  admit {here.type_tuple} depth={here.depth}")
            if here.admits
            else print(f"  reject {here.type_tuple} unsupported recursion");
        if not here.admits {
            disengage;
        }
        visit [->:Calls:->];
    }
}

with entry {
    id_decl = GenericDecl(name="identity", arity=1);
    pair_decl = GenericDecl(name="pair", arity=2);
    root +>:Declares:+> id_decl;
    root +>:Declares:+> pair_decl;

    int_inst = Instance(type_tuple="Int", depth=0);
    str_inst = Instance(type_tuple="Str", depth=0);
    id_decl +>:Instantiates:+> int_inst;
    id_decl +>:Instantiates:+> str_inst;

    ii_inst = Instance(type_tuple="Int,Int", depth=0);
    is_inst = Instance(type_tuple="Int,Str", depth=0);
    pair_decl +>:Instantiates:+> ii_inst;
    pair_decl +>:Instantiates:+> is_inst;

    nested = Instance(type_tuple="Int->Int", depth=1);
    int_inst +>:Calls:+> nested;

    cycle = Instance(type_tuple="Int->cycle", depth=2, admits=False);
    nested +>:Calls:+> cycle;

    print("=== identity decl ===");
    root spawn Instantiate(max_depth=3);
}
