import io;
import from contextlib { redirect_stdout }

def spawn_capture(w: object) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = Root();
        rt +>:Declares:+> GenericDecl(name="x", arity=1);
        rt spawn w;
    }
    return buf.getvalue();
}

test "identity_decl_admits_two_concrete_tuples" {
    rt = Root();
    decl = GenericDecl(name="identity", arity=1);
    rt +>:Declares:+> decl;

    int_inst = Instance(type_tuple="Int", depth=0);
    str_inst = Instance(type_tuple="Str", depth=0);
    decl +>:Instantiates:+> int_inst;
    decl +>:Instantiates:+> str_inst;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn Instantiate(max_depth=3);
    }
    out = buf.getvalue();

    assert "decl identity arity=1" in out, f"missing decl header: {out}";
    assert "admit Int depth=0" in out, f"missing Int admission: {out}";
    assert "admit Str depth=0" in out, f"missing Str admission: {out}";
    assert int_inst.admits is True, "Int instance should be admitted";
    assert str_inst.admits is True, "Str instance should be admitted";
}

test "two_param_pair_decl_admits_distinct_tuples" {
    rt = Root();
    decl = GenericDecl(name="pair", arity=2);
    rt +>:Declares:+> decl;

    ii = Instance(type_tuple="Int,Int", depth=0);
    is_inst = Instance(type_tuple="Int,Str", depth=0);
    decl +>:Instantiates:+> ii;
    decl +>:Instantiates:+> is_inst;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn Instantiate(max_depth=3);
    }
    out = buf.getvalue();

    assert "decl pair arity=2" in out, f"missing pair header: {out}";
    assert "admit Int,Int depth=0" in out, f"missing Int,Int admission: {out}";
    assert "admit Int,Str depth=0" in out, f"missing Int,Str admission: {out}";
    assert ii.admits is True, "Int,Int instance should be admitted";
    assert is_inst.admits is True, "Int,Str instance should be admitted";
}

test "nested_call_discovers_closure_deterministically" {
    rt = Root();
    decl = GenericDecl(name="wrap", arity=1);
    rt +>:Declares:+> decl;

    inner = Instance(type_tuple="Int", depth=0);
    decl +>:Instantiates:+> inner;

    nested = Instance(type_tuple="Int->Int", depth=1);
    inner +>:Calls:+> nested;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn Instantiate(max_depth=3);
    }
    out = buf.getvalue();

    assert "admit Int depth=0" in out, f"missing inner admission: {out}";
    assert "admit Int->Int depth=1" in out, f"missing nested closure admission: {out}";
    assert nested.admits is True, "nested closure should be admitted within depth bound";
}

test "depth_limit_rejects_with_no_artifact" {
    rt = Root();
    decl = GenericDecl(name="deep", arity=1);
    rt +>:Declares:+> decl;

    shallow = Instance(type_tuple="A", depth=0);
    deep_inst = Instance(type_tuple="A->A", depth=4);
    decl +>:Instantiates:+> shallow;
    shallow +>:Calls:+> deep_inst;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn Instantiate(max_depth=3);
    }
    out = buf.getvalue();

    assert "admit A depth=0" in out, f"missing shallow admission: {out}";
    assert "reject A->A: depth>3" in out, f"missing depth rejection marker: {out}";
    assert deep_inst.admits is False, "over-depth instance must be flagged not-admitted";
}

test "unsupported_recursion_rejected_and_dedup_happens" {
    rt = Root();
    decl = GenericDecl(name="rec", arity=1);
    rt +>:Declares:+> decl;

    top = Instance(type_tuple="R", depth=0);
    decl +>:Instantiates:+> top;

    recurse = Instance(type_tuple="R->R", depth=1, admits=False);
    top +>:Calls:+> recurse;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn Instantiate(max_depth=3);
    }
    out = buf.getvalue();

    assert "admit R depth=0" in out, f"missing R admission: {out}";
    assert "reject R->R unsupported recursion" in out, f"missing recursion rejection: {out}";
    assert recurse.admits is False, "unsupported recursion must remain not-admitted";
}

