"""Game account moderation sweep.

A walker audits member accounts normally, boosts admin reputation by 5,
and the welcome desk greets every bot no matter which walker triggered it.
"""

node Member {
    has handle: str = "";
    has reputation: int = 0;
    has available: bool = True;
}

node Admin {
    has handle: str = "";
    has reputation: int = 0;
    has available: bool = True;
}

node Bot {
    has serial: str = "";
}

walker Auditor {
    has sweeps_done: int = 0;

    can start with Root entry {
        print("Moderation sweep beginning");
        visit [-->];
    }

    can audit with Member entry {
        if here.available {
            print(f"[OK] member {here.handle} rep={here.reputation}");
        } else {
            print(f"[HOLD] member {here.handle} flagged for review");
        }
        self.sweeps_done += 1;
        visit [-->];
    }

    can boost with Admin entry {
        here.reputation += 5;
        print(f"[BOOST] admin {here.handle} rep={here.reputation}");
        self.sweeps_done += 1;
        visit [-->];
    }

    can greet with Bot entry {
        print(f"Welcome bot {here.serial}!");
    }
}

with entry {
    m1 = Member(handle="player_one", reputation=42);
    m2 = Member(handle="player_two", reputation=17, available=False);
    a1 = Admin(handle="super_user", reputation=99);
    b1 = Bot(serial="B-001");
    b2 = Bot(serial="B-002");

    root ++> m1 ++> a1 ++> b1;
    root ++> m2 ++> b2;

    auditor = Auditor();
    root spawn auditor;

    print(f"Sweep complete: {auditor.sweeps_done} accounts processed");
}
