"""Tests for metro line operations.

We exercise the two-roles behavior promised by the spec:
- Driver walkers announce stations and accumulate track distance when
  traversing edges (via explicit `visit [edge -->]`).
- Inspector walkers check signage but never accumulate distance.
"""

import io;
import from contextlib { redirect_stdout }

test "driver announces every station on a 3-stop line" {
    central = Station(station_name="Central");
    museum = Station(station_name="Museum");
    riverside = Station(station_name="Riverside");
    root ++> central +>: Track(length_km=2.4) :+> museum
                        +>: Track(length_km=1.7) :+> riverside;

    buf = io.StringIO();
    drv = Driver(line="Circle Line");
    with redirect_stdout(buf) {
        root spawn drv;
    }
    out = buf.getvalue();

    assert "[driver] approaching Central" in out, f"missing Central announce: {out}";
    assert "[driver] approaching Museum" in out, f"missing Museum announce: {out}";
    assert "[driver] approaching Riverside" in out, f"missing Riverside announce: {out}";
    assert out.count("[driver] approaching") == 3, f"expected 3 driver announces, got: {out}";

    # 2.4 + 1.7 == 4.1 km of accumulated track distance.
    assert abs(drv.distance_km - 4.1) < 1e-9, f"driver should have 4.1 km, got {drv.distance_km}";
}

test "driver never accumulates when there are no edges to visit" {
    isolated = Station(station_name="Nowhere");
    root ++> isolated;

    drv = Driver(line="Lonely Line");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn drv;
    }
    out = buf.getvalue();

    assert "[driver] approaching Nowhere" in out, f"expected announce: {out}";
    assert abs(drv.distance_km - 0.0) < 1e-9, f"no edges means no distance, got {drv.distance_km}";
}

test "inspector checks signage at every station but covers zero distance" {
    central = Station(station_name="Central");
    museum = Station(station_name="Museum");
    riverside = Station(station_name="Riverside");
    root ++> central +>: Track(length_km=2.4) :+> museum
                        +>: Track(length_km=1.7) :+> riverside;

    insp = Inspector(badge="INSP-9");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn insp;
    }
    out = buf.getvalue();

    assert "[inspector] checking signage at Central" in out, f"missing Central check: {out}";
    assert "[inspector] checking signage at Museum" in out, f"missing Museum check: {out}";
    assert "[inspector] checking signage at Riverside" in out, f"missing Riverside check: {out}";
    assert out.count("[inspector] checking signage") == 3, f"expected 3 inspector checks, got: {out}";

    # Inspector has no `distance_km` field by spec, and the program never
    # gives it one. The track edge abilities are walker-typed to Driver,
    # so even if it hopped edges, no tally would fire. We only assert
    # the observable: no driver announcements were produced.
    assert "[driver]" not in out, f"inspector run should not contain driver output: {out}";

    # And the driver must still accumulate distance in its own run.
    drv = Driver(line="Circle Line");
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        root spawn drv;
    }
    assert abs(drv.distance_km - 4.1) < 1e-9, f"driver distance regressed: {drv.distance_km}";
}

test "walker-type filter means abilities fire only for the matching kind" {
    a = Station(station_name="Alpha");
    b = Station(station_name="Beta");
    root ++> a +>: Track(length_km=5.0) :+> b;

    # Running an inspector on this line: only the Inspector-typed
    # `note` ability on Station should fire; Track.tally is Driver-typed
    # and should NOT fire (and the inspector visits [-->], not edges anyway).
    insp = Inspector(badge="B-1");
    buf_i = io.StringIO();
    with redirect_stdout(buf_i) {
        root spawn insp;
    }
    out_i = buf_i.getvalue();
    assert out_i.count("[inspector] checking signage at Alpha") == 1, f"Alpha check missing: {out_i}";
    assert out_i.count("[inspector] checking signage at Beta") == 1, f"Beta check missing: {out_i}";
    assert "[driver]" not in out_i, f"driver output leaked into inspector run: {out_i}";

    # Now a driver on the same graph: only Driver-typed announcements fire,
    # and tally accumulates 5.0 km because the driver visits edges explicitly.
    drv = Driver(line="Express");
    buf_d = io.StringIO();
    with redirect_stdout(buf_d) {
        root spawn drv;
    }
    out_d = buf_d.getvalue();
