"""Mixin recursion bug: lazy BlockEntity creation in getBlockEntity recurses with Data Anchor.

Models the mutual recursion between Swinging Lanterns' getBlockEntity mixin
(creates a SwingingLanternBlockEntity when getBlockEntity returns null) and
Data Anchor's setBlockEntity mixin (calls getBlockEntity at HEAD), then shows
the re-entrancy guard that breaks the loop.
"""

node BlockEntity {
    has pos_x: int = 0;
    has pos_y: int = 0;
    has pos_z: int = 0;
    has kind: str = "generic";
}

node SwingingLanternBlockEntity {
    has pos_x: int = 0;
    has pos_y: int = 0;
    has pos_z: int = 0;
    has kind: str = "lantern";
}

node DataAnchorRecord {
    has pos_x: int = 0;
    has pos_y: int = 0;
    has pos_z: int = 0;
    has evicted: bool = False;
}

edge HostsEntity {
    has pos_x: int = 0;
    has pos_y: int = 0;
    has pos_z: int = 0;
}

edge Calls {
    has note: str = "";
}

walker ReentrantProbe {
    has depth_limit: int = 8;
    has reentrant_guard: list[str] = [];
    has call_log: list[str] = [];

    can start with Root entry {
        visit [->:HostsEntity:->];
    }

    can hit_cached with SwingingLanternBlockEntity entry {
        tag = f"hit_cached @ ({here.pos_x},{here.pos_y},{here.pos_z})";
        self.call_log.append(tag);
        print(f"[cached] lantern already registered @ ({here.pos_x},{here.pos_y},{here.pos_z})");
        visit [-->];
    }

    can miss_then_create with BlockEntity entry {
        guard_key = f"create@({here.pos_x},{here.pos_y},{here.pos_z})";
        if guard_key in self.reentrant_guard {
            self.call_log.append(f"GUARDED re-entry @ ({here.pos_x},{here.pos_y},{here.pos_z})");
            print(f"[guarded] re-entry blocked while creating lantern @ ({here.pos_x},{here.pos_y},{here.pos_z})");
            disengage;
        }
        self.call_log.append(f"miss @ ({here.pos_x},{here.pos_y},{here.pos_z}) -> creating lantern");
        print(f"[miss] getBlockEntity null @ ({here.pos_x},{here.pos_y},{here.pos_z}), creating SwingingLanternBlockEntity");
        self.reentrant_guard.append(guard_key);
        visit [->:Calls:->];
    }

    can data_anchor_set with DataAnchorRecord entry {
        self.call_log.append(f"data-anchor setBlockEntity @ ({here.pos_x},{here.pos_y},{here.pos_z})");
        print(f"[data-anchor] HEAD of setBlockEntity @ ({here.pos_x},{here.pos_y},{here.pos_z}): asking getBlockEntity again");
        visit [->:HostsEntity:->];
    }
}

with entry {
    lantern_a = SwingingLanternBlockEntity(pos_x=10, pos_y=64, pos_z=-3);
    root +>:HostsEntity(pos_x=10, pos_y=64, pos_z=-3):+> lantern_a;

    empty_spot = BlockEntity(pos_x=10, pos_y=64, pos_z=-4);
    root +>:HostsEntity(pos_x=10, pos_y=64, pos_z=-4):+> empty_spot;
    anchor_record = DataAnchorRecord(pos_x=10, pos_y=64, pos_z=-4, evicted=False);
    empty_spot +>:Calls(note="setBlockEntity HEAD -> getBlockEntity"):+> anchor_record;

    print("=== cached lantern path ===");
    root spawn ReentrantProbe(
        depth_limit=4,
        reentrant_guard=[],
        call_log=[]
    );

    print("=== empty position path (unprotected — model of the bug) ===");
    buggy = ReentrantProbe(
        depth_limit=10,
        reentrant_guard=[],
        call_log=[]
    );
    root spawn buggy;

    print("=== empty position path (guarded — suggested fix) ===");
    guarded_key = "create@(10,64,-4)";
    guarded = ReentrantProbe(
        depth_limit=10,
        reentrant_guard=[guarded_key],
        call_log=[]
    );
    root spawn guarded;

    print(f"buggy trace length: {len(buggy.call_log)} steps: {buggy.call_log}");
    print(f"guarded trace length: {len(guarded.call_log)} steps: {guarded.call_log}");
}
