reached SVG children. The new pipeline keeps SVG nodes as ordinary DOM
nodes with typed relationships (DomNode, StyleCascade, PaintCommand)
and uses walkers to walk the tree once, propagating cascade and paint
state, with explicit cycle guards (no built-in dedupe in jac 0.36.1).
"""

# --- Node archetypes ---------------------------------------------------------

# An SVG node in the DOM tree. Carries geometry (presentation attrs become
# presentational hints at cascade time) and a path-cache slot used by the
# paint walker.
node SvgNode {
    has tag: str = "g";
    has fill: str = "";
    has stroke: str = "";
    has stroke_width: float = 0.0;
    has geometry: str = "";
    has path_cache: str = "";
}

# The <svg> root. Acts as a replaced element for CSS layout; carries
# the viewBox used to build the SVG coordinate transform.
node SvgRoot {
    has view_box: str = "0 0 100 100";
    has intrinsic_w: float = 100.0;
    has intrinsic_h: float = 100.0;
}

# A computed style for an SVG node, produced by Stylo's cascade. Walks
# attach one of these per node as the cascade progresses.
node StyleCascade {
    has resolved_fill: str = "";
    has resolved_stroke: str = "";
    has resolved_opacity: float = 1.0;
}

# A flattened paint instruction emitted into the PaintScene. The paint
# walker accumulates one of these per visible SVG node.
node PaintCommand {
    has kind: str = "fill";
    has path: str = "";
    has style_ref: str = "";
}

# --- Typed edges -------------------------------------------------------------

# Parent-of: the SVG tree's actual containment (replaces what used to be
# flattened into a usvg::Tree by serialize-and-parse).
edge ChildOf { }

# Cascade projection: a StyleCascade node that applies to the linked SVG
# node. One cascade node per SVG node, populated by the Cascade walker.
edge CascadedBy { }

# Paint emission: a PaintCommand node produced by walking an SVG node
# during the paint pass.
edge PaintedAs { }

# --- Walkers -----------------------------------------------------------------

# Walks the SVG tree once, assigning a StyleCascade to every SvgNode and
# every SvgRoot. Carries an explicit cycle guard because the issue calls
# out incremental / mutation-heavy workloads (a mutated document could
# contain cycles while we are mid-rebuild) and jac 0.36.1 has no
# built-in visitation dedupe.
walker Cascade {
    has seen: str = "";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can cascade_svgroot with SvgRoot entry {
        key = f"S{here.view_box}";
        if key in self.seen {
            disengage;
        }
        self.seen = f"{self.seen}|{key}";
        cascade = StyleCascade(
            resolved_fill="black",
            resolved_stroke="none",
            resolved_opacity=1.0
        );
        here +>:CascadedBy:+> cascade;
        print(f"cascade: <svg viewBox='{here.view_box}'> styled");
        visit [->:ChildOf:->];
    }

    can cascade_node with SvgNode entry {
        key = f"N{here.tag}{here.fill}{here.geometry}";
        if key in self.seen {
            disengage;
        }
        self.seen = f"{self.seen}|{key}";
        # Presentation attrs are presentational hints: author CSS
        # would override these, but for the demo we just promote them.
        resolved_fill = here.fill if here.fill != "" else "currentColor";
        resolved_stroke = here.stroke if here.stroke != "" else "none";
        cascade = StyleCascade(
            resolved_fill=resolved_fill,
            resolved_stroke=resolved_stroke,
            resolved_opacity=1.0
        );
        here +>:CascadedBy:+> cascade;
        print(f"cascade: <{here.tag}> fill={resolved_fill} stroke={resolved_stroke}");
        visit [->:ChildOf:->];
    }
}

# Walks the SVG tree a second time, emitting one PaintCommand per visible
# node. Independent cycle guard: this walker is spawned separately after
# the cascade walker finishes, mirroring the two-phase render pipeline
# (style, then paint) that the issue says should replace the old
# serialize-and-reparse path.
walker Paint {
    has seen: str = "";
    has command_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can paint_svgroot with SvgRoot entry {
        key = f"P{here.view_box}";
        if key in self.seen {
            disengage;
        }
        self.seen = f"{self.seen}|{key}";
        cmd = PaintCommand(
            kind="push_viewport",
            path=here.view_box,
            style_ref="root"
        );
        here +>:PaintedAs:+> cmd;
        self.command_count = self.command_count + 1;
        print(f"paint: viewport {here.view_box}");
        visit [->:ChildOf:->];
    }

    can paint_node with SvgNode entry {
        key = f"P{here.tag}{here.geometry}";
        if key in self.seen {
            disengage;
        }
        self.seen = f"{self.seen}|{key}";
        # Geometry from CSS properties participates in the cascade and
        # can be animated; here we just snapshot it.
        kind = "fill" if here.fill != "" else "stroke";
        path = here.geometry if here.geometry != "" else "M0,0";
        cmd = PaintCommand(
            kind=kind,
            path=path,
            style_ref=here.tag
        );
        here +>:PaintedAs:+> cmd;
        self.command_count = self.command_count + 1;
        print(f"paint: <{here.tag}> {kind} {path}");
        visit [->:ChildOf:->];
    }
}

# --- Demo wiring -------------------------------------------------------------

with entry {
    # Build an SVG subtree as ordinary DOM nodes (the architectural
    # decision the issue is pushing for: SVG elements stay real DOM
    # nodes, no SpecialElementData replacement, no usvg round-trip).
    root_svg = SvgRoot(view_box="0 0 200 200", intrinsic_w=200.0, intrinsic_h=200.0);
    rect = SvgNode(tag="rect", fill="tomato", geometry="M10,10 h80 v80 h-80 z");
    circ = SvgNode(tag="circle", fill="steelblue", geometry="M150,50 a40,40 0 1,0 0.001,0");
    text_node = SvgNode(tag="text", fill="black", geometry="M20,180");
    line = SvgNode(tag="line", stroke="black", stroke_width=2.0, geometry="M0,100 L200,100");

    # Containment via typed ChildOf edges. This is what used to be
    # flattened into a usvg::Tree by serialize-and-parse.
    root_svg +>:ChildOf:+> rect;
    root_svg +>:ChildOf:+> circ;
    root_svg +>:ChildOf:+> text_node;
    root_svg +>:ChildOf:+> line;

    root ++> root_svg;

    # Two-phase pipeline: cascade, then paint. Each walker carries its
    # own cycle guard because jac 0.36.1 has no built-in visitation
    # dedupe (verified by probe). The old path would have re-parsed
    # the entire subtree on every mutation; here a single walk handles
    # style and a second walk handles paint.
    cascade = Cascade();
    root spawn cascade;

    paint = Paint();
    root spawn paint;

    print(f"emitted {paint.command_count} paint commands for the SVG subtree");
}
```

"""Regression tests for the blitz SVG pipeline demo.

Exercises the two-phase pipeline (Cascade, then Paint) over a small SVG
subtree attached as ordinary DOM nodes, and verifies that:

- Every SVG node gets one StyleCascade attached (one cascade node per
  SVG node, populated by the Cascade walker).
- Every SVG node gets one PaintCommand attached (one paint emission per
  visible node, including the SvgRoot viewport command).
- Presentation attrs on SVG nodes are promoted into the cascade
  (fill='tomato' must surface as resolved_fill='tomato' on the cascade
  node; defaulting kicks in when an attr is absent: currentColor / none).
- The cycle guard actually fires: a node that is its own ChildOf target
  must not produce more than one cascade / paint emission, i.e. the
  walker disengages on the second visit instead of looping forever.
- A separate Cascade-then-Paint run over a fresh graph yields the
  expected paint command count for a four-node subtree.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: every SVG node gets exactly one StyleCascade, fill is promoted.
# ---------------------------------------------------------------------------
test "cascade attaches one StyleCascade per node and promotes fill" {
    root_svg = SvgRoot(view_box="0 0 100 100");
    rect = SvgNode(tag="rect", fill="tomato", geometry="M0,0 h10 v10 h-10 z");
    circ = SvgNode(tag="circle", fill="steelblue", geometry="M50,50 a10,10 0 1,0 0.001,0");
    root_svg +>:ChildOf:+> rect;
    root_svg +>:ChildOf:+> circ;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }

    cascades_for_rect = [rect ->:CascadedBy:->];
    cascades_for_circ = [circ ->:CascadedBy:->];
    assert len(cascades_for_rect) == 1, f"rect must have exactly one cascade, got {len(cascades_for_rect)}";
    assert len(cascades_for_circ) == 1, f"circle must have exactly one cascade, got {len(cascades_for_circ)}";

    rect_cascade = cascades_for_rect[0];
    circ_cascade = cascades_for_circ[0];
    assert rect_cascade.resolved_fill == "tomato", f"rect fill must be promoted, got {rect_cascade.resolved_fill}";
    assert rect_cascade.resolved_stroke == "none", f"absent stroke defaults to none, got {rect_cascade.resolved_stroke}";
    assert circ_cascade.resolved_fill == "steelblue", f"circle fill must be promoted, got {circ_cascade.resolved_fill}";
}

# ---------------------------------------------------------------------------
# Test 2: defaulting when attrs are absent (currentColor / none).
# ---------------------------------------------------------------------------
test "cascade defaults absent fill to currentColor and stroke to none" {
    root_svg = SvgRoot(view_box="0 0 50 50");
    bare = SvgNode(tag="g", geometry="");
    root_svg +>:ChildOf:+> bare;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }

    cascades = [bare ->:CascadedBy:->];
    assert len(cascades) == 1, f"expected one cascade on bare node, got {len(cascades)}";
    assert cascades[0].resolved_fill == "currentColor", f"absent fill must default to currentColor, got {cascades[0].resolved_fill}";
    assert cascades[0].resolved_stroke == "none", f"absent stroke must default to none, got {cascades[0].resolved_stroke}";
}

# ---------------------------------------------------------------------------
# Test 3: paint walker emits one command per node plus a viewport for root.
# ---------------------------------------------------------------------------
test "paint emits one viewport command for SvgRoot and one per SvgNode" {
    root_svg = SvgRoot(view_box="0 0 200 200", intrinsic_w=200.0, intrinsic_h=200.0);
    rect = SvgNode(tag="rect", fill="tomato", geometry="M10,10 h80 v80 h-80 z");
    circ = SvgNode(tag="circle", fill="steelblue", geometry="M150,50 a40,40 0 1,0 0.001,0");
    text_node = SvgNode(tag="text", fill="black", geometry="M20,180");
    line = SvgNode(tag="line", stroke="black", stroke_width=2.0, geometry="M0,100 L200,100");
    root_svg +>:ChildOf:+> rect;
    root_svg +>:ChildOf:+> circ;
    root_svg +>:ChildOf:+> text_node;
    root_svg +>:ChildOf:+> line;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Paint();
    }

    assert res.command_count == 5, f"expected 5 paint commands (1 viewport + 4 nodes), got {res.command_count}";

    root_cmds = [root_svg ->:PaintedAs:->];
    rect_cmds = [rect ->:PaintedAs:->];
    line_cmds = [line ->:PaintedAs:->];
    assert len(root_cmds) == 1, f"SvgRoot must have exactly one paint command, got {len(root_cmds)}";
    assert root_cmds[0].kind == "push_viewport", f"root cmd must be push_viewport, got {root_cmds[0].kind}";
    assert root_cmds[0].path == "0 0 200 200", f"root cmd path must be viewBox, got {root_cmds[0].path}";
    assert len(rect_cmds) == 1, f"rect must have exactly one paint command, got {len(rect_cmds)}";
    assert len(line_cmds) == 1, f"line must have exactly one paint command, got {len(line_cmds)}";
    # fill-bearing node uses fill kind; stroke-only node uses stroke kind.
    assert rect_cmds[0].kind == "fill", f"rect with fill must emit fill kind, got {rect_cmds[0].kind}";
    assert line_cmds[0].kind == "stroke", f"line with only stroke must emit stroke kind, got {line_cmds[0].kind}";
}

# ---------------------------------------------------------------------------
# Test 4: cycle guard disengages on self-loop (no infinite walk).
# ---------------------------------------------------------------------------
test "cycle guard disengages when an SvgNode is its own ChildOf target" {
    root_svg = SvgRoot(view_box="0 0 100 100");
    looper = SvgNode(tag="g", fill="red", geometry="M0,0 L10,10");
    root_svg +>:ChildOf:+> looper;
    # Self-loop: this is the kind of mutated-mid-rebuild situation the
    # issue calls out, and jac 0.36.1 has no built-in visit dedupe.
    looper +>:ChildOf:+> looper;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }

    cascades = [looper ->:CascadedBy:->];
    assert len(cascades) == 1, f"cycle guard must limit cascade to one node, got {len(cascades)} cascades";

    # Same guard applies to the paint walker.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        pres = root spawn Paint();
    }
    paint_cmds = [looper ->:PaintedAs:->];
    assert len(paint_cmds) == 1, f"cycle guard must limit paint to one command, got {len(paint_cmds)}";
    # The looper itself is one paint emission; the SvgRoot is another.
    # Without the guard both counts would be far higher.
    assert pres.command_count <= 2, f"command_count must stay bounded by cycle guard, got {pres.command_count}";
}

