"""Tests for the Quiz grader walker: strictly typed integer score reports."""

import io;
import from contextlib { redirect_stdout }

test "grader collects strictly typed int scores in traversal order" {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Dave", score=96);

    grader = Grader();
    root spawn grader;

    assert len(grader.report) == 4, f"expected 4 reports, got {len(grader.report)}";
    assert grader.report[0] == 92, f"first score should be 92, got {grader.report[0]}";
    assert grader.report[1] == 85, f"second score should be 85, got {grader.report[1]}";
    assert grader.report[2] == 78, f"third score should be 78, got {grader.report[2]}";
    assert grader.report[3] == 96, f"fourth score should be 96, got {grader.report[3]}";

    # Strict typing: every reported value must be an int (never str/float).
    for s in grader.report {
        assert isinstance(s, int), f"score {s!r} is not int (type {type(s).__name__})";
        assert not isinstance(s, bool), f"score {s!r} is bool, not int";
    }
}

test "grader prints graded lines for each quiz and reports collected scores" {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Dave", score=96);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = Grader();
        root spawn grader;
        print(f"Collected scores: {grader.report}");
    }
    out = buf.getvalue();

    # Each quiz must produce a graded line with its score.
    assert "Graded Alice: 92" in out, f"missing Alice line: {out}";
    assert "Graded Bob: 85" in out, f"missing Bob line: {out}";
    assert "Graded Carol: 78" in out, f"missing Carol line: {out}";
    assert "Graded Dave: 96" in out, f"missing Dave line: {out}";

    # The collected-scores summary must echo the list.
    assert "Collected scores:" in out, f"missing collected-scores line: {out}";
    assert "92" in out and "85" in out and "78" in out and "96" in out,
        f"collected scores not all present: {out}";
}

test "class average over collected scores is computed correctly" {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Dave", score=96);

    grader = Grader();
    root spawn grader;

    total = 0;
    for s in grader.report {
        total += s;
    }
    count = len(grader.report);
    avg = total / count if count > 0 else 0.0;

    # 92 + 85 + 78 + 96 = 351; avg = 351 / 4 = 87.75 -> 87.8
    assert total == 351, f"expected total 351, got {total}";
    assert count == 4, f"expected count 4, got {count}";
    assert avg == 87.75, f"expected avg 87.75, got {avg}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        print(f"Class average: {avg:.1f}");
    }
    out = buf.getvalue();
    assert "Class average: 87.8" in out, f"expected 'Class average: 87.8' in output, got: {out}";
}

test "grader on empty graph disengages immediately with empty reports" {
    # No Quiz children attached to root.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = Grader();
        root spawn grader;
        print(f"Collected scores: {grader.report}");
    }
    out = buf.getvalue();

    assert len(grader.report) == 0, f"expected no reports, got {len(grader.report)}";

    # The list must still be strictly typed int even when empty.
    for s in grader.report {
        assert isinstance(s, int), f"empty-list element {s!r} is not int";
    }

    # No graded lines should appear since there were no quizzes.
    assert "Graded " not in out, f"unexpected graded line on empty graph: {out}";
    assert "Collected scores: []" in out, f"expected empty list in output: {out}";

    # Average computation must be fail-safe (no division by zero).
    total = 0;
    for s in grader.report {
        total += s;
    }
    count = len(grader.report);
    avg = total / count if count > 0 else 0.0;
    assert avg == 0.0, f"expected avg 0.0 on empty set, got {avg}";
}

