"""Snapshot field repair: model the correct/store parity defect.

Scenario: an entity has a list field ``decisions``. The bulk ``store`` tool
records it as a real nested array; the patch-style ``correct`` tool records
the same value as a JSON-encoded string. When a walker gathers fields for
the winning snapshot, stringified values yield garbage to any downstream
consumer that iterates them.
"""

node Entity {
    has entity_type: str = "";
    has entity_id: str = "";
}

node Field {
    has name: str = "";
    has value: str = "";
    has value_type: str = "str";
    has encoded: bool = False;
    has owner_id: str = "";
}

# ``Correct`` is the patch-style repair tool that, in the buggy
# implementation, JSON-stringifies array/object values before persisting.
edge Correct {
    has tool_name: str = "correct";
}

# ``Store`` is the bulk writer that preserves runtime types end-to-end.
edge Store {
    has tool_name: str = "store";
}

walker SnapshotCollector {
    has field_count: int = 0;
    has corrupted: int = 0;
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Entity entry {
        visit [-->];
    }

    can gather with Field entry {
        self.field_count += 1;
        kind = "STRINGIFIED" if here.encoded else "raw";
        line = f"{kind} {here.name}={here.value} ({here.value_type}) on {here.owner_id}";
        self.report.append(line);
        if here.encoded {
            self.corrupted += 1;
        }
        visit [-->];
    }
}

walker BackfillAdvisor {
    has advice: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can advise with Entity entry {
        visit [-->];
    }

    can scan with Field entry {
        if here.encoded {
            msg = (f"backfill: re-write field '{here.name}' on "
                   f"{here.owner_id} via store+target_id");
            self.advice.append(msg);
        }
        visit [-->];
    }
}

walker Reachable {
    has frontier: list[str] = [];
    has max_hops: int = 5;
    has visited: set[str] = set();
    has hops: int = 0;

    can start with Root entry {
        visit [-->];
