```jac
"""Sandbox skill shadow-mount: model read-only vs read-write mounts for
agent self-uninstall. The original issue hand-rolls traversal over the
host/container path graph to decide which mounts must be writable so the
agent can delete its own shadow skills. Here that policy becomes typed
edges and a walker that walks the mount tree, marks the shadow skills
directory as writable, and cascades the invalidation of any skill that
relies on it."""

node Skill {
    has name: str = "";
    has available: bool = True;
}

node HostPath {
    has path: str = "";
}

node ContainerPath {
    has path: str = "";
    has read_only: bool = True;
}

# A persistent skill lives on the host at HostPath and is materialized into
# the sandbox at ContainerPath.
edge MaterializedAt {
    has host_path: str = "";
    has container_path: str = "";
}

# Marks a ContainerPath as part of the sandbox-skills shadow tree.
edge SandboxSkill {}

walker AuditMounts {
    has fixes: list[str] = [];
    has visited: list[ContainerPath] = [];

    can start with Root entry {
        visit [-->];
    }

    # Walk every container mount. If its path is the shadow-skills root,
    # flip read_only to False so the agent can delete its own skills.
    can audit with ContainerPath entry {
        self.visited.append(here);
        is_shadow = "sandbox-skills" in here.path;
        if is_shadow {
            here.read_only = False;
            self.fixes.append(f"made {here.path} writable for autonomous uninstall");
            visit [-->];
        } else {
            visit [-->];
        }
    }

    # When we land on a host path, report its bound shadow mount state.
    can inspect with HostPath entry {
        print(f"host source: {here.path}");
        visit [-->] else { disengage; }
    }

    # When we land on a skill, report whether it is still active.
    can validate with Skill entry {
        status = "ACTIVE" if here.available else "REMOVED";
        print(f"[{status}] skill={here.name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    # The shadow root that the issue calls out: was ro, must become rw.
    shadow_root = ContainerPath(
        path="/workspace/.openclaw/sandbox-skills/skills",
        read_only=True
    );
    # A second, unrelated ro mount to prove we don't flip it.
    config_root = ContainerPath(path="/etc/openclaw", read_only=True);

    # Host sources for two skills; one is autonomous (workspace-private).
    ws_skills_src = HostPath(path="/workspace/skills");
    builtin_src = HostPath(path="/opt/openclaw/skills");

    # Two skill nodes, one workspace-private and one built-in.
    auto_skill = Skill(name="my-skill", available=True);
    builtin_skill = Skill(name="core-linter", available=True);

    # Wire the graph: root -> shadow_root -> auto_skill (typed SandboxSkill)
    # root -> config_root -> builtin_skill (typed MaterializedAt)
    # host sources attach to the shadow/config roots via MaterializedAt.
    root ++> shadow_root +>:SandboxSkill:+> auto_skill;
    root ++> config_root +>:MaterializedAt(
        host_path="/opt/openclaw/skills",
        container_path="/etc/openclaw"
    ):+> builtin_skill;
    ws_skills_src +>:MaterializedAt(
        host_path="/workspace/skills",
        container_path="/workspace/.openclaw/sandbox-skills/skills"
    ):+> shadow_root;
    builtin_src +>:MaterializedAt(
        host_path="/opt/openclaw/skills",
        container_path="/etc/openclaw"
    ):+> config_root;

    print("--- before audit ---");
    print(f"shadow mount read_only={shadow_root.read_only} path={shadow_root.path}");
    print(f"config mount read_only={config_root.read_only} path={config_root.path}");

    AuditMounts() spawn root;

    print("--- after audit ---");
    print(f"shadow mount read_only={shadow_root.read_only} path={shadow_root.path}");
    print(f"config mount read_only={config_root.read_only} path={config_root.path}");
    print(f"auto_skill available={auto_skill.available}");
}
