"""Vet-clinic round: a vet walker visits pets and tallies vaccinations."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = True;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print("Vet starting the clinic round...");
        visit [-->];
    }

    can examine with Pet entry {
        label = "ready" if here.needs_vaccine else "skipped";
        print(f"Examining {here.name} the {here.species} -> {label}");
        if here.needs_vaccine {
            self.patients.append(here.name);
            self.shots_given += 1;
            here.needs_vaccine = False;
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="dog", needs_vaccine=True)
        ++> Pet(name="Pip", species="parrot", needs_vaccine=False)
        ++> Pet(name="Noodle", species="rabbit", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print("--- Round summary ---");
    print(f"Patients vaccinated: {vet.patients}");
    print(f"Shots given: {vet.shots_given}");
}
