"""Restaurant kitchen line health inspection.

Two checks must run at every station (Grill, Fryer, ColdPrep):
  - Temperature check: flag any station whose temperature reading is above 40 C.
  - Visit log: record that the inspector stopped at this station.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Inspector {
    has violations: list[str] = [];
    has stops: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can check with Grill | Fryer | ColdPrep entry {
        self.stops.append(here.name);
        if here.celsius > 40.0 {
            violation = f"VIOLATION: {here.name} at {here.celsius} C";
            self.violations.append(violation);
        }
        visit [-->];
    }
}

with entry {
    grill = Grill(name="Grill", celsius=180.0);
    fryer = Fryer(name="Fryer", celsius=35.0);
    cold = ColdPrep(name="ColdPrep", celsius=8.0);
    root ++> grill ++> fryer ++> cold;

    inspector = Inspector();
    root spawn inspector;

    print("--- Inspection stops ---");
    for stop in inspector.stops {
        print(stop);
    }
    print("--- Violations ---");
    if len(inspector.violations) == 0 {
        print("No violations.");
    } else {
        for v in inspector.violations {
            print(v);
        }
    }
    print(f"Total stops: {len(inspector.stops)} | Total violations: {len(inspector.violations)}");
}
