    );
    brew = PublicSurface(
        channel="homebrew",
        before_hash="",
        after_hash="",
        observer_status="not_applicable"
    );

    root ++> rehearsal;
    rehearsal +>:Calls:+> lint;
    lint +>:Calls:+> build;
    build +>:Calls:+> sbom;
    sbom +>:Calls:+> publish;

