```jac
"""Work package startability resolver: dependency edges, contention edges and an
authority route walked by an Auditor walker that decides whether a work package
is STARTABLE or BLOCKED. Reproduces the FWK-074 / PR-134 byte-dependency case
described in SECB-WP-FWK-075.
"""

# ------------------------------------------------------------------
# Node archetypes
# ------------------------------------------------------------------

node WorkPackage {
    has title: str = "";
    has wp_id: str = "";
    has design_state: str = "DESIGNABLE";
    has implementation_state: str = "BLOCKED_BY_UNKNOWN";
    has execution_state: str = "NOT_STARTED";
    has defined: bool = True;
}

node PullRequest {
    has pr_id: str = "";
    has branch: str = "";
    has merged: bool = False;
    has merge_clean: bool = False;
    has provides_helper: bool = False;
}

node AuthorityRoute {
    has route_id: str = "";
    has available: bool = True;
}

node Helper {
    has name: str = "";
    has canonical_on: str = "";
}

# ------------------------------------------------------------------
# Edge archetypes (relationships live on the graph, not as id fields)
# ------------------------------------------------------------------

edge DependsOnBytes { has as_of_ref: str = "EFFECTIVE_MAIN"; }
edge Reuses { has canonical: bool = True; }
edge Contended { has dimension: str = ""; }
edge Authority { has route_id: str = ""; }

# ------------------------------------------------------------------
# Auditor walker — carries an evidence payload across the graph.
# Walks each typed-edge neighbourhood explicitly so we can introspect
# the target node fields directly via `here` in nested visit forms.
# ------------------------------------------------------------------

walker Auditor {
    has as_of_ref: str = "EFFECTIVE_MAIN";
    has visited: list[str] = [];
    has blockers: list[str] = [];
    has evidence: list[str] = [];

    can start with Root entry {
        print(f"Auditor as_of_ref={self.as_of_ref}");
        visit [-->];
    }

    can assess with WorkPackage entry {
        tag = here.wp_id;
        already_seen = False;
        for v in self.visited {
            if v == tag {
                already_seen = True;
            }
        }
        if already_seen {
            visit [-->];
            return;
        }
        self.visited.append(tag);
        print(f"--- assessing {tag} ({here.title}) ---");

        dep_ok = True;
        dep_note = "required bytes evidenced on effective base";
        for pr in [here ->:DependsOnBytes:->] {
            if not pr.merged and pr.provides_helper {
                dep_ok = False;
                dep_note = f"required bytes only on open PR {pr.pr_id}";
            }
        }

        reuse_ok = True;
        reuse_note = "canonical reuse target on effective base";
        for h in [here ->:Reuses:->] {
            if h.canonical_on != "EFFECTIVE_MAIN" {
                reuse_ok = True;
                reuse_note = (
                    f"canonical reuse target {h.name} "
                    f"not on effective base — parallel implementation prohibited"
                );
                dep_ok = False;
                if dep_note == "required bytes evidenced on effective base" {
                    dep_note = reuse_note;
                }
            }
        }

        cont_ok = True;
        cont_note = "no contention reported";
        for w in [here ->:Contended:->] {
            cont_ok = False;
            cont_note = f"contention [{w.wp_id}] reported";
        }

        auth_ok = True;
        auth_note = "authority route available";
        for a in [here ->:Authority:->] {
            if not a.available {
                auth_ok = False;
                auth_note = f"authority route {a.route_id} unavailable";
            }
        }

        final_ok = here.defined and dep_ok and reuse_ok and cont_ok and auth_ok;
        final_note = dep_note;
        if not auth_ok {
            final_note = auth_note;
        }
        if not cont_ok {
            final_note = cont_note;
        }
        if not here.defined {
            final_ok = False;
            final_note = "work package undefined";
        }

        state = "STARTABLE" if final_ok else here.implementation_state;
        here.implementation_state = state;
        self.evidence.append(f"{tag} -> {state} :: {final_note}");
        if not final_ok {
            self.blockers.append(f"{tag}: {final_note}");
        }
        print(f"  conjuncts: {final_note}");
        print(f"  result: {state}");
        visit [-->];
    }
}

walker Scheduler {
    has picks: list[str] = [];
    has frontier: list[str] = [];

    can start with Root entry {
        print("Scheduler: scanning for startable work packages");
        visit [-->];
    }

    can select with WorkPackage entry {
        if here.implementation_state == "STARTABLE" {
            self.picks.append(here.wp_id);
            print(f"  candidate: {here.wp_id} ({here.title})");
        } else {
            self.frontier.append(f"{here.wp_id}: {here.implementation_state}");
        }
        visit [-->];
    }
}

# ------------------------------------------------------------------
# Demonstration wiring
# ------------------------------------------------------------------

with entry {
    fwk074 = WorkPackage(
        wp_id="FWK-074",
        title="Binding layer reusing parser",
        implementation_state="BLOCKED_BY_UNKNOWN"
    );
    fwk070 = WorkPackage(
        wp_id="FWK-070",
        title="Independent uncontended work",
        implementation_state="BLOCKED_BY_UNKNOWN"
    );

    pr134 = PullRequest(
        pr_id="PR-134",
        branch="feature/parser-v2",
        merged=False,
        merge_clean=True,
        provides_helper=True
    );

    parser_helper = Helper(
        name="parse_expression",
        canonical_on="PR-134"
    );

    auth = AuthorityRoute(route_id="merge-gate", available=True);
    auth_other = AuthorityRoute(route_id="ratification", available=False);

    root ++> fwk074 ++> fwk070;

    fwk074 +>:DependsOnBytes(as_of_ref="EFFECTIVE_MAIN"):+> pr134;
    fwk074 +>:Reuses(canonical=True):+> parser_helper;
    fwk074 +>:Authority(route_id="merge-gate"):+> auth;
    fwk074 +>:Authority(route_id="ratification"):+> auth_other;

    print("=== Auditor pass ===");
    root spawn Auditor(as_of_ref="EFFECTIVE_MAIN");

    print("");
    print("=== Scheduler pass ===");
    root spawn Scheduler();

    print("");
    print("=== Final state ===");
    print(f"FWK-074 implementation_state = {fwk074.implementation_state}");
    print(f"FWK-070 implementation_state = {fwk070.implementation_state}");
}
```

