        visit [-->];
    }
}

walker BotGreeter {
    can start with Root entry {
        print("Bot greeter entering");
        visit [-->];
    }

    can greet with Bot entry {
        print(f"[GREET] Hello bot {here.title} ({here.year})");
        visit [-->];
    }
}

with entry {
    root ++> Member(title="alice", year=2019, available=True, reputation=42)
        ++> Admin(title="boss", year=2017, available=True, reputation=100)
        ++> Member(title="carol", year=2022, available=False, reputation=15)
        ++> Bot(title="helper-bot", year=2024)
        ++> Bot(title="scanner-bot", year=2023);

    root spawn Moderator();
    print("---");
    root spawn AdminBooster();
    print("---");
    root spawn BotGreeter();
}
