Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""Reverse import edges for impact analysis.

Models the core scenario from issue #378: a file/package knowledge graph
that tracks both forward (`imports`) and reverse (`imported_by`) edges so
that an impact walker can answer "who imports this node?" by walking
incoming edges instead of being limited to forward traversal.
"""

node Symbol {
    has name: str = "";
    has kind: str = "";  # "file" | "package" | "function"
}

edge Imports {
    has via: str = "";
}

edge ImportedBy {
    has via: str = "";
}

# Forward impact: from a file, walk its outbound imports and report what it
# pulls in (the query the graph already supports).
walker ForwardImpact {
    can start with Root entry {
        visit [-->];
    }

    can descend with Symbol entry {
        print(f"[forward] {here.name} ({here.kind}) imports:");
        visit [->:Imports:->];
    }

    can report with Symbol entry {
        print(f"  -> {here.name} ({here.kind})");
        visit [->:Imports:->];
    }
}

# Reverse impact: from a package or file, walk incoming ImportedBy edges
# to surface every caller. This is the missing capability described in
# issue #378: `memory_impact(node=..., direction="in")`.
walker ReverseImpact {
    can start with Root entry {
        visit [-->];
    }

    can descend with Symbol entry {
        print(f"[reverse] {here.name} ({here.kind}) is imported by:");
        visit [->:ImportedBy:->];
    }

    can report with Symbol entry {
        print(f"  <- {here.name} ({here.kind})");
        # Stop at one level of reverse dependency by default; further
        # nesting would re-trigger descend on caller symbols.
    }
}

with entry {
    # The watched package: contains a function whose callers we want to find.
    watcher_pkg = Symbol(name="internal/watcher", kind="package");
    watcher_file = Symbol(name="internal/watcher/filter.go", kind="file");
    target_fn = Symbol(name="internal/watcher/filter.go::newFileFilter", kind="function");

    # Five callers that import the watcher package.
    main_go = Symbol(name="cmd/nano-brain/main.go", kind="file");
    server_go = Symbol(name="internal/server/server.go", kind="file");
    collection_go = Symbol(name="internal/server/handlers/collection.go", kind="file");
    reindex_go = Symbol(name="internal/server/handlers/reindex.go", kind="file");
    workspace_go = Symbol(name="internal/server/handlers/workspace.go", kind="file");

    # Containment edges (plain `-->`, no semantic edge type needed).
    root ++> watcher_pkg ++> watcher_file ++> target_fn;

    # Caller chain: each caller is its own file, none contain others here.
    root ++> main_go ++> server_go
        ++> collection_go ++> reindex_go ++> workspace_go;

    # Forward edges: file -> imports -> package (existing knowledge).
    main_go +>:Imports:+> watcher_pkg;
    server_go +>:Imports:+> watcher_pkg;
    collection_go +>:Imports:+> watcher_pkg;
    reindex_go +>:Imports:+> watcher_pkg;
    workspace_go +>:Imports:+> watcher_pkg;

    # Reverse edges: package <- imported_by <- file (the missing half).
    watcher_pkg +>:ImportedBy:+> main_go;
    watcher_pkg +>:ImportedBy:+> server_go;
    watcher_pkg +>:ImportedBy:+> collection_go;
    watcher_pkg +>:ImportedBy:+> reindex_go;
    watcher_pkg +>:ImportedBy:+> workspace_go;

    # Also model containment as a reverse relationship so the reverse
    # walker can answer "what contains this function?" too.
    watcher_file +>:ImportedBy(via="contains"):+> target_fn;

    # Demo 1: forward impact from a caller (existing behavior).
    print("=== Forward impact from cmd/nano-brain/main.go ===");
    root spawn ForwardImpact();
    print("");

    # Demo 2: reverse impact on the watched package (the new capability).
    print("=== Reverse impact on internal/watcher ===");
    root spawn ReverseImpact();
    print("");

    # Demo 3: reverse impact on the leaf function symbol.
    print("=== Reverse impact on newFileFilter ===");
    root spawn ReverseImpact();
}
