"""Game account moderation sweep.

Member accounts are audited normally, admin accounts get their reputation
boosted by 5, and the welcome desk greets every bot passing through no
matter what kind of walker it is.
"""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reputation: int = 0;
}

node Member(Account) {
    has join_year: int = 2020;
}

node Admin(Account) {
    has admin_level: int = 1;
}

edge AuditedBy {
    has desk_name: str = "Welcome";
}

walker Moderator {
    can start with Root entry {
        print("Moderation sweep begins");
        visit [-->];
    }

    can audit with Account entry {
        print(f"  audited {here.title} (rep={here.reputation})");
        visit [-->];
    }
}

walker ReputationBooster {
    can start with Root entry {
        print("Reputation boost pass begins");
        visit [-->];
    }

    can boost with Account entry {
        here.reputation = here.reputation + 5;
        print(f"  boosted {here.title}: rep {here.reputation}");
        visit [-->];
    }
}

walker WelcomeDesk {
    has desk_name: str = "Front";

    can start with Root entry {
        print(f"{self.desk_name} desk is open");
        visit [-->];
    }

    can greet with Account entry {
        print(f"  hello, {here.title}! (welcome from {self.desk_name})");
        visit [-->];
    }
}

walker Bot {
    has bot_id: str = "B-0";

    can start with Root entry {
        print(f"bot {self.bot_id} enters the lobby");
        visit [-->];
    }

    can enter with Account entry {
        print(f"  bot {self.bot_id} passing through {here.title}");
        visit [-->];
    }
}

with entry {
    member1 = Member(title="Alice", year=2019, join_year=2019, reputation=20);
    member2 = Member(title="Bob", year=2021, join_year=2021, reputation=35);
    admin1 = Admin(title="CarolRoot", year=2018, reputation=50, admin_level=2);
    root ++> member1 ++> member2 ++> admin1;

    print("=== Phase 1: standard audit ===");
    root spawn Moderator();

    print("=== Phase 2: admin reputation boost ===");
    root spawn ReputationBooster();

    print("=== Phase 3: welcome desk greets all ===");
    root spawn WelcomeDesk(desk_name="Welcome-1");
    root spawn WelcomeDesk(desk_name="Welcome-2");

    print("=== Phase 4: bot tour ===");
    root spawn Bot(bot_id="Scout-1");
    root spawn Bot(bot_id="Scout-2");
}
