```jac
"""Auto-mutation evaluation coordinator.

Models the core scenario from issue #425: a coordinator that walks
approved candidates through analysis, mutation, tiered evaluation,
publication, rollback, and evidence-driven replanning. The graph
relationships (Candidates belong to Plans, Candidates carry Mutation
records, Evaluations and Rollback events form a lineage trail) are
expressed as typed edges, and walker traversal replaces the hand-rolled
recursion/queue machinery of the original.
"""

# ---------- Entity archetypes ----------

node Plan {
    has title: str = "";
    has budget: int = 100;
}

node Candidate {
    has name: str = "";
    has status: str = "pending";   # pending | analyzed | mutated | evaluated | promoted | rolled_back
    has approved: bool = False;
}

node Mutation {
    has kind: str = "";
    has reversible: bool = True;
}

node Evaluation {
    has tier: str = "";            # cheap | standard | full
    has score: float = 0.0;
    has passes_hard: bool = False;
}

node Rollback {
    has reason: str = "";
}

node Artifact {
    has label: str = "";
    has published: bool = False;
}

# ---------- Relationship archetypes ----------

edge Owns { }
edge Carries { }
edge EvaluatedBy { }
edge RollbackOf { }
edge Publishes { }

# ---------- Walker: Coordinator ----------

walker Coordinator {
    has report: list[str] = [];
    has visited: list[str] = [];

    can begin with Root entry {
        # Step into the plan frontier.
        visit [-->];
    }

    can drive with Plan entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
            self.report.append(f"plan:{here.title} budget={here.budget}");
        }
        # Walk owned candidates, mutations, evaluations, rollbacks, artifacts.
        visit [->:Owns:->];
    }

    can audit with Candidate entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.report.append(f"candidate:{here.name} status={here.status} approved={here.approved}");
        }
        visit [->:Carries:->];
        visit [->:EvaluatedBy:->];
        visit [->:RollbackOf:->];
    }

    can log_mutation with Mutation entry {
        self.report.append(f"  mutation kind={here.kind} reversible={here.reversible}");
        visit [-->];
    }

    can log_eval with Evaluation entry {
        outcome = "PASS" if here.passes_hard else "FAIL";
        self.report.append(f"  eval tier={here.tier} score={here.score} -> {outcome}");
        visit [-->];
    }

    can log_rollback with Rollback entry {
        self.report.append(f"  rollback reason={here.reason}");
        visit [-->];
    }

    can log_artifact with Artifact entry {
        pub = "PUBLISHED" if here.published else "DRAFT";
        self.report.append(f"  artifact {here.label} -> {pub}");
        visit [-->];
    }
}

# ---------- Walker: Promotion gate ----------
# Walks Plan -> Candidate via Owns, asserts the hard-constraint passes,
# then publishes the artifact. Demonstrates cycle-safe traversal with a
# visited-set guard (Jac 0.36.1 walkers have no built-in dedupe).

walker Promoter {
    has blocked: list[str] = [];
    has promoted: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can inspect with Plan entry {
        visit [->:Owns:->];
    }

    can decide with Candidate entry {
        if here.approved and here.status == "evaluated" {
            # Read its evaluation via the typed edge; promote only on pass.
            for ev in [->:EvaluatedBy:->] {
                if ev.passes_hard {
                    here.status = "promoted";
                    self.promoted.append(here.name);
                } else {
                    here.status = "rolled_back";
                    self.blocked.append(here.name);
                }
            }
        } else {
            here.status = "rolled_back";
            self.blocked.append(here.name);
        }
        visit [-->];
    }
}

# ---------- Demonstration graph ----------

with entry {
    # Two plans, each owning candidates; candidates carry mutations,
    # have evaluations, and (for one) a rollback event and an artifact.
    plan_a = Plan(title="resnet-quantize", budget=50);
    plan_b = Plan(title="llama-prune", budget=200);

    cand_a1 = Candidate(name="rnet-q8", approved=True);
    cand_a2 = Candidate(name="rnet-q4", approved=False);

    cand_b1 = Candidate(name="llama-prune-30", approved=True);
    cand_b2 = Candidate(name="llama-prune-60", approved=True);

    root ++> plan_a ++> plan_b;

    plan_a +>:Owns:+> cand_a1;
    plan_a +>:Owns:+> cand_a2;
    plan_b +>:Owns:+> cand_b1;
    plan_b +>:Owns:+> cand_b2;

    # Mutations carried by each candidate.
    cand_a1 +>:Carries:+> Mutation(kind="int8-quant", reversible=True);
    cand_a2 +>:Carries:+> Mutation(kind="int4-quant", reversible=True);
    cand_b1 +>:Carries:+> Mutation(kind="mag-prune-30", reversible=True);
    cand_b2 +>:Carries:+> Mutation(kind="mag-prune-60", reversible=True);

    # Evaluations at increasing tiers.
    cand_a1 +>:EvaluatedBy:+> Evaluation(tier="cheap", score=0.81, passes_hard=True);
    cand_a1 +>:EvaluatedBy:+> Evaluation(tier="full", score=0.92, passes_hard=True);

    cand_a2 +>:EvaluatedBy:+> Evaluation(tier="cheap", score=0.40, passes_hard=False);

    cand_b1 +>:EvaluatedBy:+> Evaluation(tier="standard", score=0.77, passes_hard=True);
    cand_b2 +>:EvaluatedBy:+> Evaluation(tier="standard", score=0.55, passes_hard=False);

    # Rollback lineage for the failed prune-60.
    cand_b2 +>:RollbackOf:+> Rollback(reason="hard-constraint fail: accuracy floor");

    # Artifact publication lineage for the successful candidates.
    art_a = Artifact(label="rnet-q8.onnx", published=True);
    cand_a1 +>:Publishes:+> art_a;

    art_b = Artifact(label="llama-prune-30.gguf", published=True);
    cand_b1 +>:Publishes:+> art_b;

    # Pre-set statuses to reflect prior stages.
    cand_a1.status = "evaluated";
    cand_a2.status = "evaluated";
    cand_b1.status = "evaluated";
    cand_b2.status = "evaluated";

    # Phase 1: Coordinator audits the whole evidence graph.
    coord = Coordinator();
    root spawn coord;
    print("=== Coordinator audit ===");
    for line in coord.report {
        print(line);
    }

    # Phase 2: Promoter enforces the gate (only measured hard-constraint
    # passes are promoted; everything else is rolled back).
    prom = Promoter();
    root spawn prom;
    print("\n=== Promotion gate ===");
    print(f"promoted: {prom.promoted}");
    print(f"blocked : {prom.blocked}");
}
