            self.dead_ends += 1;
            print(f"[DEAD END] reached capped valve '{here.label}'");
            visit [-->] else { disengage; }
        } else {
            print(f"flow through {here.label} -> continuing");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
