        ++> Valve(label="Junction-A")
        ++> Valve(label="Junction-B")
        ++> Valve(label="Purifier", capped=True)
        ++> Valve(label="Bypass", capped=True)
        ++> Valve(label="Main-Out");

    tracer = Tracer();
    root spawn tracer;

    print(f"route: {tracer.route}");
    print(f"dead ends hit: {tracer.dead_ends}");
}
