    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stop_count == 3, f"expected stop_count 3, got {res.stop_count}";

    # The first stop printed must correspond to w1 (root's only outgoing waypoint)
    first_waypoint = [root -->][?:Waypoint][0];
    assert first_waypoint == w1, "first waypoint from root should be w1";

    # Confirm the chain is exactly length 3 of Waypoint nodes
    wp_count = 0;
    cur = first_waypoint;
    while cur is not None {
        wp_count += 1;
        nxts = [cur -->];
        if len(nxts) == 0 {
            cur = None;
        } else {
            cur = nxts[0];
        }
    }
    assert wp_count == 3, f"chain should have 3 waypoints, found {wp_count}";
}

