```jac
"""Bug tracker: file tickets off a project node and capture the freshly connected node.

Demonstrates the grouped creation / connection idiom
``root ++> (t := Ticket(...));`` which both wires the ticket onto the project
and returns the new node, so the caller can read its fields immediately
without a separate lookup.
"""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: int = 0;
    has available: bool = True;
}

walker FileTickets {
    has filed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can file with Project entry {
        # Connect and grab: the walrus inside the connection expression
        # returns the freshly created node, so we can read its fields right
        # away instead of running a lookup query afterwards.
        here ++> (t1 := Ticket(title="Login page crashes on Safari", priority=1));
        here ++> (t2 := Ticket(title="CSV export truncates unicode", priority=2));
        here ++> (t3 := Ticket(title="Dark mode toggle flicker", priority=3, available=False));

        print(f"Under project '{here.name}':");
        for t in [t1, t2, t3] {
            label = "OPEN" if t.available else "CLOSED";
            print(f"  [{label}] P{t.priority} - {t.title}");
            self.filed.append(t.title);
        }
        visit [-->];
    }
}

with entry {
    web = Project(name="Web");
    mobile = Project(name="Mobile");

    root ++> web ++> mobile;

    root spawn FileTickets();
}
