"""Tiny dungeon crawler: rooms chained as nodes, hunter walks until treasure is found."""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has treasure_found: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can search with Room entry {
        self.rooms_checked += 1;
        label = "VAULT" if here.is_vault else "room";
        print(f"Inspecting {label}: {here.name} (total checked: {self.rooms_checked})");

        if here.is_vault {
            self.treasure_found = True;
            print(f"Treasure secured in '{here.name}'! Hunter stops.");
            disengage;
        }

        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Dragon's Vault", is_vault=True);
    # Rooms past the vault — must NEVER be visited by the Hunter.
    forbidden = Room(name="Forbidden Crypt");
    beyond = Room(name="Beyond the Vault");

    root ++> entrance ++> hallway ++> armory ++> vault ++> forbidden ++> beyond;

    hunter = Hunter();
    root spawn hunter;

    print(f"Final tally: rooms_checked={hunter.rooms_checked}, "
          f"treasure_found={hunter.treasure_found}");
}
