```jac
"""i18n dead-key sweep: model the pack/reference/namespace audit as a graph.

The hand-rolled machinery the issue complains about is: keys live in a
pack namespace tree, some are referenced by call sites, and a sweep walks
the tree to flag keys that have *no* reference reachable from the consumer
graph. This demo lifts that into typed edges + a walker that classifies
each pack key as CONFIRMED dead, NEEDS-REVIEW, or LIVE.
"""

node PackKey {
    has namespace: str = "";
    has key: str = "";
    has dead: bool = False;
}

node Reference {
    has source: str = "";
    has pattern: str = "";
}

node CallSite {
    has file: str = "";
    has line: int = 0;
}

edge InNamespace {}
edge References {}
edge IndirectlyMentioned {}

walker DeadKeySweeper {
    has confirmed: int = 0;
    has needs_review: int = 0;
    has live: int = 0;

    can start with Root entry {
        visit [->:InNamespace:->];
    }

    can sweep_namespace with PackKey entry {
        has_direct = [here ->:References:->];
        has_indirect = [here ->:IndirectlyMentioned:->];

        if has_direct {
            self.live += 1;
            visit [->:References:->];
        } elif has_indirect {
            self.needs_review += 1;
            visit [->:IndirectlyMentioned:->];
        } else {
            self.confirmed += 1;
            here.dead = True;
        }
    }
}

walker DeadKeyReporter {
    has target: str = "";

    can start with Root entry {
        visit [->:InNamespace:->];
    }

    can report with PackKey entry {
        if here.dead {
            print(f"[CONFIRMED DEAD] {here.namespace}.{here.key}");
        }
        visit [-->];
    }
}

with entry {
    workflow_boundary = PackKey(namespace="workflow", key="boundaryEvent");
    workflow_service = PackKey(namespace="workflow", key="serviceTask");
    workflow_user = PackKey(namespace="workflow", key="userTask");
    workflow_parallel = PackKey(namespace="workflow", key="parallelGateway");
    workflow_export = PackKey(namespace="workflow", key="exportBpmn");

    ov_row_actions = PackKey(namespace="console.objectView", key="rowActions");
    ov_inline_edit = PackKey(namespace="console.objectView", key="inlineEdit");
    ov_hidden = PackKey(namespace="console.objectView", key="hiddenFields");
    ov_filterable = PackKey(namespace="console.objectView", key="filterableFields");
    ov_new = PackKey(namespace="console.objectView", key="new");
    ov_save = PackKey(namespace="console.objectView", key="save");

    call_wf = CallSite(file="ProcessDesigner.tsx", line=42);
    call_ov = CallSite(file="CreateViewDialog.tsx", line=17);

    text_grep = Reference(source="AppCreationWizard.tsx", pattern="appDesigner.layoutSidebar");

    root +>:InNamespace:+> workflow_boundary;
    root +>:InNamespace:+> workflow_service;
    root +>:InNamespace:+> workflow_user;
    root +>:InNamespace:+> workflow_parallel;
    root +>:InNamespace:+> workflow_export;

    root +>:InNamespace:+> ov_row_actions;
    root +>:InNamespace:+> ov_inline_edit;
    root +>:InNamespace:+> ov_hidden;
    root +>:InNamespace:+> ov_filterable;
    root +>:InNamespace:+> ov_new;
    root +>:InNamespace:+> ov_save;

    workflow_boundary +>:IndirectlyMentioned:+> text_grep;
    ov_row_actions +>:IndirectlyMentioned:+> text_grep;

    ov_new +>:References:+> call_ov;
    ov_save +>:References:+> call_ov;

    sweeper = DeadKeySweeper();
    root spawn sweeper;

    print(
        f"sweep complete: {sweeper.confirmed} CONFIRMED dead, "
        f"{sweeper.needs_review} NEEDS-REVIEW, {sweeper.live} LIVE"
    );

    reporter = DeadKeyReporter();
    root spawn reporter;
}
