        ++> Room(name="Hall of Echoes")
        ++> Room(name="Pillar Chamber", is_vault=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Sunken Reliquary");

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter saw {hunter.rooms_seen} room(s) in total.");
}
