"""Tests for the Quiz grader walker.

Verifies the typed-walker behavior:
- `Grader.scores` collects every quiz score in traversal order.
- All collected scores are integers (no string contamination).
- Class average is correctly computed from the collected scores.
- A short chain (single quiz) yields a one-element list with that score.
"""

import io;
import from contextlib { redirect_stdout }

test "grader collects all five scores in order" {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carmen", score=95)
        ++> Quiz(student="Dev", score=61)
        ++> Quiz(student="Esi", score=82);

    grader = Grader();
    root spawn grader;

    expected = [88, 74, 95, 61, 82];
    assert grader.scores == expected, f"got {grader.scores}";
    assert len(grader.scores) == 5, f"got {len(grader.scores)}";
}

test "collected scores are strictly integers" {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carmen", score=95);

    grader = Grader();
    root spawn grader;

    for s in grader.scores {
        assert isinstance(s, int), f"non-int score leaked in: {s!r}";
        assert not isinstance(s, bool), f"bool sneaking in as int: {s!r}";
    }
    # Sanity: the raw list type itself reports int elements.
    assert all(type(s) is int for s in grader.scores), "list contained non-int";
}

test "class average matches hand-computed mean" {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carmen", score=95)
        ++> Quiz(student="Dev", score=61)
        ++> Quiz(student="Esi", score=82);

    grader = Grader();
    root spawn grader;

    total = 0;
    for s in grader.scores {
        total += s;
    }
    avg = total / len(grader.scores);

    # 88+74+95+61+82 = 400, /5 = 80.0
    assert avg == 80.0, f"expected 80.0, got {avg}";
    assert total == 400, f"expected total 400, got {total}";

    # Round-trip through stdout to be sure the demo prints the same value.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        # Re-run the grading (the program's `with entry` does not fire under `jac test`).
        grader2 = Grader();
        root spawn grader2;
        print(f"Class average: {total / len(grader2.scores)}");
    }
    out = buf.getvalue();
    assert "Class average: 80.0" in out, f"missing average line: {out!r}";
}

test "single-quiz chain yields one-element score list" {
    root ++> Quiz(student="Solo", score=42);

    grader = Grader();
    root spawn grader;

    assert grader.scores == [42], f"got {grader.scores}";
    assert len(grader.scores) == 1, f"got {len(grader.scores)}";
}

test "grader state is independent per spawn" {
    # Fresh graph so this test is self-contained.
    root ++> Quiz(student="Alice", score=10)
        ++> Quiz(student="Bob", score=20);

    grader_a = Grader();
    root spawn grader_a;
    assert grader_a.scores == [10, 20], f"first spawn got {grader_a.scores}";

    # A second walker on the same root must not inherit the first walker's list.
    grader_b = Grader();
    root spawn grader_b;
    assert grader_b.scores == [10, 20], f"second spawn got {grader_b.scores}";

    # Mutating one walker's list must not touch the other's.
    grader_a.scores.append(999);
    assert grader_b.scores == [10, 20], f"cross-walker bleed: {grader_b.scores}";
    assert 999 in grader_a.scores, "mutation on walker_a did not stick";
}

