"""Causal graph construction: each add_edge runs a full-graph acyclicity scan."""

node Variable {
    has name: str = "";
}

node CausalGraphHub {
    has label: str = "";
    has cumulative_scan_steps: int = 0;
    has edges_added: int = 0;
    has edges_rejected: int = 0;

    def add_edge(parent: Variable, child: Variable) -> bool {
        auditor = FullGraphScan();
        root spawn auditor;
        self.cumulative_scan_steps += auditor.steps;
        probe = ReachabilityProbe(goal_name=parent.name);
        child spawn probe;
        if probe.found {
            self.edges_rejected += 1;
            print(
                f"REJECT {parent.name}->{child.name}: cycle "
                f"(full scan cost {auditor.steps} steps)"
            );
            return False;
        }
        parent +>:Causes:+> child;
        self.edges_added += 1;
        print(
            f"ADD {parent.name}->{child.name} "
            f"(acyclicity scan: {auditor.steps} steps)"
        );
        return True;
    }
}

edge Causes { }

walker FullGraphScan {
    has steps: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pass_hub with CausalGraphHub entry {
        visit [-->];
    }

    can touch with Variable entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.steps += 1;
        visit [->:Causes:->] else { disengage; };
    }
}

walker ReachabilityProbe {
    has goal_name: str = "";
    has found: bool = False;
    has visited: list[str] = [];

    can probe with Variable entry {
        if here.name == self.goal_name {
            self.found = True;
            disengage;
        }
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        visit [->:Causes:->] else { disengage; };
    }
}

with entry {
    hub = CausalGraphHub(label="rt-cinfer causal demo");
    treatment = Variable(name="treatment");
    mediator = Variable(name="mediator");
    outcome = Variable(name="outcome");
    covariate = Variable(name="covariate");
    root ++> hub;
    root ++> treatment;
    root ++> mediator;
    root ++> outcome;
    root ++> covariate;

    hub.add_edge(treatment, mediator);
    hub.add_edge(mediator, outcome);
    hub.add_edge(outcome, treatment);
    hub.add_edge(treatment, covariate);

    print(
        f"graph {hub.label}: added {hub.edges_added}, "
        f"rejected {hub.edges_rejected}, "
        f"total scan steps {hub.cumulative_scan_steps}"
    );
}
