    assert len([cause ->:Causes:->]) == 1, f"cause out degree mismatch";
    assert effect in [cause ->:Causes:->], f"typed edge missing: {out}";
    assert third in [effect ->:Causes:->], f"typed edge missing: {out}";
    assert hub.cumulative_scan_steps == 3, f"scan steps={hub.cumulative_scan_steps}";
