"""Native exposure graph with speaking-only fatigue and monotonic decay."""

node ExposureStore {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has monotonic_now: float = 0.0;
    has half_life: float = 60.0;
    has semantic_fatigue: float = 0.0;
    has pattern_fatigue: float = 0.0;
    has visit_key: str = "";
}

node Exposure {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has semantic_identity: str = "";
    has story_family: str = "";
    has pattern: str = "";
    has final_text: str = "";
    has tape_channel: str = "";
    has lexical_tail: str = "";
    has lifecycle: str = "PLANNED";
    has playback_accepted: bool = False;
    has actually_spoken: bool = False;
    has observed_monotonic: float = 0.0;
    has base_penalty: float = 1.0;
    has event_penalty_coefficient: float = 1.0;
    has embedding_hint: float = 0.0;
    has visit_key: str = "";
}

node Channel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tape_channel: str = "";
    has pressure: float = 0.0;
    has visit_key: str = "";
}

edge Contains {
    has ordinal: int = 0;
}

edge SourceChannel {
    has tape_channel: str = "";
}

edge Feeds {
    has route: str = "";
}

walker ExposureAuditor {
    has now: float = 0.0;
    has half_life: float = 60.0;
    has visited_keys: list[str] = [];
    has tail_history: list[str] = [];
    has pressure_channels: list[str] = [];
    has pressure_values: list[float] = [];
    has semantic_total: float = 0.0;
    has pattern_total: float = 0.0;

    def already_seen(candidate: str) -> bool {
        return candidate in self.visited_keys;
    }

    def lexical_tail_jaccard(left: str, right: str) -> float {
        left_terms = left.split(" ");
        right_terms = right.split(" ");
        intersection = 0;
        union = len(left_terms);
        for token in right_terms {
            if token in left_terms {
                intersection += 1;
            } else {
                union += 1;
            }
        }
        if union == 0 {
            return 0.0;
        }
        return intersection / union;
    }

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can collect with ExposureStore entry {
        if self.already_seen(here.visit_key) {
            print(f"cycle guard: store {here.title}");
            skip;
        }
        self.visited_keys.append(here.visit_key);
        self.now = here.monotonic_now;
        self.half_life = here.half_life;
        visit [->:Contains:->] else { disengage; }
    }

    can inspect with Exposure entry {
        if self.already_seen(here.visit_key) {
            print(f"cycle guard: exposure {here.semantic_identity}");
            skip;
        }
        self.visited_keys.append(here.visit_key);

        if here.playback_accepted {
            if here.actually_spoken {
                if here.lifecycle == "SPEAKING" {
                    age = self.now - here.observed_monotonic;
                    safe_age = 0.0 if age < 0.0 else age;
                    penalty = here.base_penalty
                        * here.event_penalty_coefficient
                        * (2.0 ** (-safe_age / self.half_life));
                    self.semantic_total += penalty;

                    best_overlap = 0.0;
                    for previous_tail in self.tail_history {
                        overlap = self.lexical_tail_jaccard(
                            here.lexical_tail,
                            previous_tail
                        );
                        if overlap > best_overlap {
                            best_overlap = overlap;
                        }
                    }

                    self.pattern_total += penalty * best_overlap;
                    self.tail_history.append(here.lexical_tail);
                    self.pressure_channels.append(here.tape_channel);
                    self.pressure_values.append(penalty);

                    print(
                        f"spoken {here.tape_channel}: {here.final_text} "
                        f"| decay={penalty} | tail-jaccard={best_overlap}"
                    );
                } else {
                    print(
                        f"ignored {here.semantic_identity}: "
                        "not playback-accepted speaking exposure"
                    );
                }
            } else {
                print(
                    f"ignored {here.semantic_identity}: "
                    "not playback-accepted speaking exposure"
                );
            }
        } else {
            print(
                f"ignored {here.semantic_identity}: "
                "not playback-accepted speaking exposure"
            );
        }

        visit [->:SourceChannel:->] else { skip; }
    }

    can measure with Channel entry {
        if self.already_seen(here.visit_key) {
            print(f"cycle guard: channel {here.tape_channel}");
            skip;
        }

        self.visited_keys.append(here.visit_key);
        total_pressure = 0.0;

        for i in range(len(self.pressure_channels)) {
            if self.pressure_channels[i] == here.tape_channel {
