            }
        }

        here.pressure = total_pressure;
        print(f"channel {here.tape_channel} pressure={here.pressure}");
        visit [->:Feeds:->] else { skip; }
    }

    can finish with Root exit {
        print(
            f"semantic fatigue={self.semantic_total}, "
            f"pattern fatigue={self.pattern_total}"
        );
    }
}

