"""Test annex for the dungeon crawler Hunter walker."""

import io;
import from contextlib { redirect_stdout }

test "hunter stops at vault and never enters forbidden or escape" {
    # Build the canonical 6-room chain: entry -> armory -> library -> vault -> forbidden -> escape
    entry_hall = Room(name="Entry Hall");
    armory = Room(name="Armory");
    library = Room(name="Library");
    vault = Room(name="Vault", is_treasure=True);
    forbidden = Room(name="Forbidden Chamber");
    escape = Room(name="Escape Tunnel");

    root ++> entry_hall
        ++> armory
        ++> library
        ++> vault
        ++> forbidden
        ++> escape;

    buf = io.StringIO();
    hunter = Hunter();
    with redirect_stdout(buf) {
        res = root spawn hunter;
    }
    out = buf.getvalue();

    # Hunter must report finding the treasure in the vault
    assert res.found_treasure, f"hunter did not report finding treasure; out={out}";
    assert res.treasure_room == "Vault", f"expected treasure in 'Vault', got '{res.treasure_room}'";

    # Hunter must have visited exactly the 4 rooms up to and including the vault
    assert res.rooms_seen == 4, f"expected rooms_seen=4 (entry, armory, library, vault), got {res.rooms_seen}";

    # Output must confirm the treasure announcement on the vault
    assert "Treasure found in 'Vault'" in out, f"missing treasure announcement: {out}";

    # Critical: rooms past the vault must NEVER appear in output
    assert "Forbidden Chamber" not in out, f"hunter leaked into Forbidden Chamber; out={out}";
    assert "Escape Tunnel" not in out, f"hunter leaked into Escape Tunnel; out={out}";

    # And the empty-room reports should mention only the 3 rooms before the vault
    assert "Room 'Entry Hall' is empty" in out, f"missing Entry Hall report: {out}";
    assert "Room 'Armory' is empty" in out, f"missing Armory report: {out}";
    assert "Room 'Library' is empty" in out, f"missing Library report: {out}";
}

test "hunter returns fail-closed when no treasure exists in chain" {
