```jac
"""Recursive call graph analyzer: model functions as nodes, calls as typed edges, and
walk the call graph to classify recursion depth (linear vs logarithmic step reduction).
Each recursive cycle is detected by walking forward along Calls edges with an explicit
visited-set guard (jac 0.36.1 walkers do NOT auto-dedupe on cyclic graphs)."""

# --- Edge archetype: a directed call from caller to callee, carrying the source
# argument expression so the analyzer can reason about the step reduction. ---
edge Calls {
    has arg_expr: str = "";
}

# --- Node archetype: a function in the analyzed program. ---
# `arg_expr` is the argument passed at the (one) recursive call site. For a leaf
# function that doesn't recurse, arg_expr is "" and the walker reports "none".
node Function {
    has name: str = "";
    has arg_expr: str = "";
}

# --- Helper predicate: is the argument expression a linear step reduction?
# Linear looks like "n-1", "n - 2", "x-1": a minus operator with a positive
# constant on the right. We check by splitting on "-" and looking for a
# positive integer on the right-hand piece.
def is_linear_step(expr: str) -> bool {
    parts = expr.split("-");
    # Must have exactly one "-" so the right side is a single positive int.
    if len(parts) != 2 {
        return False;
    }
    rhs = parts[1].strip();
    if not rhs.isdigit() {
        return False;
    }
    return int(rhs) > 0;
}

# --- Helper predicate: is the argument expression a logarithmic step reduction?
# Logarithmic looks like "n//2", "n // 2", "n/2".
def is_log_step(expr: str) -> bool {
    return "//" in expr;
}

# --- Walker: visits every function reachable from the seed, follows Calls edges
# forward, detects recursive cycles via an explicit visited set, and classifies
# the recursion shape of the FIRST cycle it closes into O(N) (linear) vs
# O(log N) (logarithmic). ---
walker CallGraphAnalyzer {
    has visited: list[str] = [];
    has verdict: str = "none";

    can start with Root entry {
        visit [-->];
    }

    can analyze with Function entry {
        # Append-then-check: if the function is already on the current path,
        # we've closed a cycle and can classify its shape from the arg_expr
        # stored on the function (the argument passed at the recursive site).
        if here.name in self.visited {
            # Cycle closed. Classify by the recursive call site's arg_expr.
            expr = here.arg_expr;
            shape = "none";
            if is_linear_step(expr) {
                shape = "O(N)";
            } elif is_log_step(expr) {
                shape = "O(log N)";
            }
            self.verdict = shape;
            print(f"cycle closed at {here.name} -> stack depth: {shape}");
            disengage;
        }
        self.visited.append(here.name);
        print(f"visited {here.name} (arg: {here.arg_expr or '-'})");

        # No forward Calls edges means a leaf: stack depth is O(1).
        outgoing = [here->:Calls:->];
        if len(outgoing) == 0 {
            if self.verdict == "none" {
                self.verdict = "O(1)";
            }
            print(f"{here.name} has no recursive calls -> stack depth: {self.verdict}");
            disengage;
        }

        # Step forward along the (single) outgoing recursive call.
        visit [->:Calls:->] else { disengage; }
    }
}

# --- Demonstration graph: three functions, two of them recursive. ---
#   factorial  --(n-1)--> factorial     (linear -> O(N))
#   binsearch  --(n//2)--> binsearch    (logarithmic -> O(log N))
#   helper     --(plain)--> binsearch   (non-recursive -> O(1))
with entry {
    f1 = Function(name="factorial", arg_expr="n-1");
    f2 = Function(name="binsearch", arg_expr="n//2");
    f3 = Function(name="helper", arg_expr="");

    root ++> f1;
    root ++> f2;
    root ++> f3;

    # Recursive self-edges carry the step-reduction argument.
    f1 +>:Calls(arg_expr="n-1"):+> f1;
    f2 +>:Calls(arg_expr="n//2"):+> f2;
    # Non-recursive call carries an empty arg string (or anything that isn't
    # a linear/log step).
    f3 +>:Calls(arg_expr=""):+> f2;

    print("=== analyzing factorial (linear recursion) ===");
    a1 = CallGraphAnalyzer();
    root spawn a1;
    print(f"verdict: {a1.verdict}");

    print("=== analyzing binsearch (logarithmic recursion) ===");
    a2 = CallGraphAnalyzer();
    root spawn a2;
    print(f"verdict: {a2.verdict}");

    print("=== analyzing helper (no recursion) ===");
    a3 = CallGraphAnalyzer();
    root spawn a3;
    print(f"verdict: {a3.verdict}");
}
```

"""Tests for the recursive call graph analyzer.

Covers the three behaviors the issue specifies:
  - linear step reduction (n-1) -> O(N)
  - logarithmic step reduction (n//2) -> O(log N)
  - leaf / non-recursive function -> O(1) (no cycle closed)
"""

import io;
import from contextlib { redirect_stdout }

# --- 1. Linear recursion: a function that calls itself with n-1 -------------

test "linear recursion n-1 is classified as O(N)" {
    root ++> Function(name="factorial", arg_expr="n-1");
    f = [root-->][?:Function][0];
    # Self-edge with the linear step reduction arg.
    f +>:Calls(arg_expr="n-1"):+> f;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = root spawn CallGraphAnalyzer();
    }
    out = buf.getvalue();

    assert w.verdict == "O(N)", f"expected O(N), got {w.verdict}";
    assert out is not None, "stdout was not captured";
    assert "cycle closed at factorial" in out, f"missing cycle marker in: {out}";
    assert "stack depth: O(N)" in out, f"missing stack depth line in: {out}";
}

# --- 2. Logarithmic recursion: a function that calls itself with n//2 -------

test "logarithmic recursion n//2 is classified as O(log N)" {
    root ++> Function(name="binsearch", arg_expr="n//2");
    b = [root-->][?:Function][0];
    b +>:Calls(arg_expr="n//2"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = root spawn CallGraphAnalyzer();
    }
    out = buf.getvalue();

    assert w.verdict == "O(log N)", f"expected O(log N), got {w.verdict}";
    assert out is not None, "stdout was not captured";
    assert "cycle closed at binsearch" in out, f"missing cycle marker in: {out}";
    assert "stack depth: O(log N)" in out, f"missing stack depth line in: {out}";
}

# --- 3. Mutual recursion that does NOT reduce the argument: not classifiable -

test "cycle with non-step-reducing arg is not classified as linear or log" {
    # Two functions that call each other, but the recursive call passes the
    # raw argument unchanged. The walker closes the cycle but the arg_expr
    # matches neither is_linear_step nor is_log_step, so verdict stays "none".
    root ++> Function(name="a", arg_expr="n");
    root ++> Function(name="b", arg_expr="");
    a = [root-->][?:Function][0];
    b = [root-->][?:Function][1];
    a +>:Calls(arg_expr="n"):+> b;
    b +>:Calls(arg_expr=""):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = root spawn CallGraphAnalyzer();
    }
    out = buf.getvalue();

    assert w.verdict == "none", f"expected none, got {w.verdict}";
    assert out is not None, "stdout was not captured";
    assert "cycle closed" in out, f"missing cycle-closed marker in: {out}";
    assert "stack depth: none" in out, f"expected unclassified marker in: {out}";
}

# --- 4. Leaf / non-recursive function: no outgoing Calls edge, no cycle ----

test "leaf function with no recursive calls yields O(1)" {
    root ++> Function(name="leaf", arg_expr="");
    # Intentionally no Calls edge attached -> walker should report O(1).

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = root spawn CallGraphAnalyzer();
    }
    out = buf.getvalue();

    assert w.verdict == "O(1)", f"expected O(1), got {w.verdict}";
    assert out is not None, "stdout was not captured";
    assert "no recursive calls" in out, f"missing leaf marker in: {out}";
    assert "stack depth: O(1)" in out, f"missing O(1) marker in: {out}";
}

# --- 5. Edge shape: Calls edges with the step expression are persisted -----

test "Calls edge preserves the arg expression on the node side" {
    root ++> Function(name="fact", arg_expr="n-1");
    f = [root-->][?:Function][0];
    f +>:Calls(arg_expr="n-1"):+> f;

    outgoing = [f->:Calls:->];
    assert len(outgoing) == 1, f"expected exactly one Calls edge, got {len(outgoing)}";
    assert f in [f ->:Calls:->], "self-edge not present in outgoing Calls";
    assert f.arg_expr == "n-1", f"node arg_expr lost: {f.arg_expr}";
}

