    has actor_authored: bool = False;
}

node InstitutionalConstraint {
    has constraint_id: str = "";
    has rule: str = "";
    has actor_authored: bool = True;
}

node ReconciliationNote {
    has old_id: str = "";
    has new_id: str = "";
    has outcome: str = "ambiguous";
    has reason: str = "";
}

