"""Tests for the wildcard type erasure walker."""

import io;
import from contextlib { redirect_stdout }

test "upper bound wildcard erases to its bound" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        e = TypeParam(name="E", owner="GenericMap");
        w = TypeParam(name="W", owner="TypeParameterErasureRecursion");
        u = TypeParam(name="U", owner="TypeParameterErasureRecursion");
        wildcard = TypeRef(name="? extends E", kind="wildcard", bound="E");
        super_wildcard = TypeRef(name="? super K", kind="wildcard", lower_bounded=True);
        entry_ref = TypeRef(name="Map.Entry<String,E>", kind="plain");
        unwrapped = TypeRef(name="U", kind="param", bound="Object");
        entry_set = Executable(signature="entrySet()", params=["Set<Map.Entry<String,E>>"]);
        unwrap_m = Executable(signature="unwrap(W)", params=["W"]);
        wildcard +>:BoundsTo:+> e;
        e +>:Declares:+> unwrapped;
        unwrapped +>:ParamOf(pos=0):+> unwrap_m;
        super_wildcard +>:BoundsTo:+> super_wildcard;
        root ++> wildcard ++> entry_set ++> entry_ref;
        root ++> super_wildcard;
        root ++> w ++> u;
        root ++> unwrap_m;
        auditor = Eraser();
        res = root spawn auditor;
    }
    out = buf.getvalue();
    assert "erase ? extends E (wildcard) => E" in out, f"missing upper-bound erase: {out}";
    upper_hits = 0;
    for line in out.splitlines() {
        if line.strip() == "erase ? extends E (wildcard) => E" {
            upper_hits += 1;
        }
    }
    assert upper_hits == 1, f"upper-bound erasure must be recorded exactly once, got {upper_hits}: {out}";
}

test "lower bound wildcard erases to Object" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        e = TypeParam(name="E", owner="GenericMap");
        super_wildcard = TypeRef(name="? super K", kind="wildcard", lower_bounded=True);
        super_wildcard +>:BoundsTo:+> super_wildcard;
        root ++> super_wildcard;
        root ++> e;
        auditor = Eraser();
        res = root spawn auditor;
    }
    out = buf.getvalue();
    assert "erase ? super K (wildcard) => Object" in out, f"missing lower-bound erase: {out}";
    assert "erase ? super K (wildcard) => K" not in out, "lower-bound wildcard must NOT use its bound";
    assert "? super K -> Object" in res.erasures, f"erasures list missing lower-bound result: {res.erasures}";
}

test "cycle guard prevents stack overflow on self-loop" {
    # The super_wildcard has a self-loop on BoundsTo: the original bug
    # would recurse infinitely. The cycle guard must short-circuit.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        sw = TypeRef(name="? super K", kind="wildcard", lower_bounded=True);
        sw +>:BoundsTo:+> sw;
        root ++> sw;
        auditor = Eraser();
        res = root spawn auditor;
    }
    out = buf.getvalue();
    assert "erase ? super K (wildcard) => Object" in out, f"first erase missing: {out}";
    assert "[cycle-guard]" in out, f"cycle guard never fired on self-loop: {out}";
    # No recursion overflow means the walker returned without crashing.
    assert len(res.erasures) >= 1, f"erasures list empty: {res.erasures}";
    # The single erase for the self-loopped wildcard must be exactly one entry.
    lower_count = 0;
    for e in res.erasures {
        if e == "? super K -> Object" {
            lower_count += 1;
        }
    }
    assert lower_count == 1, f"expected exactly 1 erase for self-loopped wildcard, got {lower_count}: {res.erasures}";
}

test "executable and type-param visitations are guarded" {
    # The recursive lookup visits an Executable and a TypeParam. The cycle
    # guard (via `mark`) must record them and not loop forever.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        e = TypeParam(name="E", owner="GenericMap");
        unwrapped = TypeRef(name="U", kind="param", bound="Object");
        unwrap_m = Executable(signature="unwrap(W)", params=["W"]);
        e +>:Declares:+> unwrapped;
        unwrapped +>:ParamOf(pos=0):+> unwrap_m;
        root ++> e ++> unwrap_m;
        auditor = Eraser();
        res = root spawn auditor;
    }
    out = buf.getvalue();
    assert "type param E owned by GenericMap" in out, f"TypeParam visit missing: {out}";
    assert "executable unwrap(W) params=['W']" in out, f"Executable visit missing: {out}";
    # Each guarded key appears at most once in the visited list.
    e_key_count = 0;
    exec_key_count = 0;
    for k in res.visited {
        if k == "param:E" {
            e_key_count += 1;
        }
        if k == "exec:unwrap(W)" {
            exec_key_count += 1;
        }
    }
    assert e_key_count == 1, f"TypeParam guard key repeated: {res.visited}";
    assert exec_key_count == 1, f"Executable guard key repeated: {res.visited}";
}

test "plain type reference keeps its declared name" {
    # A non-wildcard, non-param TypeRef must erase to its own name and not
    # be influenced by its neighbors in the graph.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        entry_ref = TypeRef(name="Map.Entry<String,E>", kind="plain");
        root ++> entry_ref;
        auditor = Eraser();
        res = root spawn auditor;
    }
