"""Run a flow from a selected task while preserving downstream order."""

node Flow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has needs_skipped_output: bool = False;
    has output_ready: bool = False;
}

edge NextTask {
    has ordinal: int = 0;
}

walker RunFromHere {
    has selected_task_id: str = "";
    has visited_ids: list[str] = [];
    has started: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_flow with Flow entry {
        visit [-->] else {
            disengage;
        }
    }

    can execute with Task entry {
        if here.task_id in self.visited_ids {
            print(f"Cycle detected at {here.title}; stopping");
            disengage;
        }

        self.visited_ids.append(here.task_id);

        if here.task_id != self.selected_task_id and not self.started {
            print(f"Skipping upstream task: {here.title}");
        } else {
            if not self.started {
                print(f"Run from here: {here.title}");
                self.started = True;
            }

            if here.needs_skipped_output and not here.output_ready {
                print(
                    f"Warning: {here.title} expects output from skipped upstream tasks"
                );
            }

            if not here.available {
                print(f"Skipped unavailable task: {here.title}");
            } else {
                print(f"Executing {here.title}");
                here.output_ready = True;
            }
        }

        visit [->:NextTask:->] else {
            print("Downstream traversal complete");
            disengage;
        }
    }
}

with entry {
    pipeline = Flow(title="Order Flow", year=2025);
    task_a = Task(task_id="A", title="Task A");
    task_b = Task(task_id="B", title="Task B");
    task_c = Task(
        task_id="C",
        title="Task C",
        needs_skipped_output=True
    );
    task_d = Task(task_id="D", title="Task D");

    root ++> pipeline ++> task_a;
    task_a +>:NextTask(ordinal=1):+> task_b;
    task_b +>:NextTask(ordinal=2):+> task_c;
    task_c +>:NextTask(ordinal=3):+> task_d;

    root spawn RunFromHere(selected_task_id="C");
}
