"""Bounded wildcard erasure: model the recursive lookup that overflowed.

The Spoon bug arose from a manual recursion over a graph of type references:
resolving a wildcard's bound asked for the containing executable, whose
erasure re-resolved the same wildcard — a cycle with no cycle guard.

We model the same scenario with three nodes (Wildcard, Executable, Bound)
connected by typed edges. A walker traverses the erasure path. Without an
explicit visited-set (the original bug), it would loop forever; the fix
adds the guard, which is the domain logic that must survive the lift.
"""

# --- Edge archetypes -----------------------------------------------------
edge Bounds   { }
edge Contains { }
edge ErasesTo { }
edge Parent   { }

# --- Node archetypes ------------------------------------------------------
node Wildcard {
    has label: str = "?";
    has upper: str = "";
}

node Bound {
    has name: str = "";
}

node Executable {
    has name: str = "";
    has params: list[str] = [];
}

# --- Walker: fixed erasure lookup (terminates via visited guard) ----------
walker ErasureLookup {
    has target: str = "?";
    has report: list[str] = [];
    has visited: list[str] = [];

    def seen(exec_name: str) -> bool {
        for v in self.visited {
            if v == exec_name {
                return True;
            }
        }
        return False;
    }

    def mark(exec_name: str) {
        self.visited.append(exec_name);
    }

    can begin with Root entry {
        visit [-->];
    }

    can with_wildcard with Wildcard entry {
        label = f"wildcard {here.label} extends {here.upper}";
        self.report.append(label);
        sink = here.upper if here.upper != "" else "Object";
        self.report.append(f"  -> erase to {sink}");
        visit [->:Bounds:->] else { disengage; }
    }

    can with_bound with Bound entry {
        self.report.append(f"bound {here.name}: locate declaring executable");
        visit [->:Contains:->] else { disengage; }
    }

    can with_executable with Executable entry {
        if self.seen(here.name) {
            self.report.append(
                f"  cycle blocked at {here.name}; visited={self.visited}"
            );
            disengage;
        }
        self.mark(here.name);
        self.report.append(f"  exec {here.name}(params={here.params})");
        for p in here.params {
            if p == self.target {
                self.report.append(
                    f"  re-erasing target {p} inside {here.name} -> blocked"
                );
                disengage;
            }
        }
        visit [->:Parent:->] else { disengage; }
    }
}

# --- Walker: naive version that mirrors the bug ---------------------------
walker NaiveErasure {
    has depth_limit: int = 8;
    has depth: int = 0;
    has report: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can with_wildcard with Wildcard entry {
        self.report.append(f"[naive] wildcard {here.label}");
        visit [->:Bounds:->] else { disengage; }
    }

    can with_bound with Bound entry {
        self.report.append(f"[naive] bound {here.name}");
        visit [->:Contains:->] else { disengage; }
    }

    can with_executable with Executable entry {
        if self.depth >= self.depth_limit {
            self.report.append("[naive] depth cap hit -> disengage");
            disengage;
        }
        self.depth += 1;
        self.report.append(f"[naive] exec {here.name} (depth={self.depth})");
        visit [->:Parent:->] else { disengage; }
    }
}

# --- Demonstration graph --------------------------------------------------
with entry {
    wc_bounded = Wildcard(label="?w", upper="E");
    wc_unbounded = Wildcard(label="?u", upper="");

    bound_E = Bound(name="E");
    bound_T = Bound(name="T");
    bound_W = Bound(name="W");

    mapAll = Executable(name="mapAll", params=["T"]);
    consume = Executable(name="consume", params=["T"]);
    iter_method = Executable(name="iterator", params=["U"]);

    wc_bounded   +>:Bounds:+> bound_E;
    wc_unbounded +>:Bounds:+> bound_T;

    bound_E +>:Contains:+> mapAll;
    bound_T +>:Contains:+> mapAll;
    bound_W +>:Contains:+> iter_method;

    mapAll     +>:Parent:+> consume;
    consume    +>:Parent:+> mapAll;

    wc_bounded   +>:ErasesTo:+> Bound(name="Object");
    wc_unbounded +>:ErasesTo:+> Bound(name="Object");

    root ++> wc_bounded
        ++> wc_unbounded
        ++> bound_E
        ++> bound_T
        ++> bound_W
        ++> mapAll
        ++> consume
        ++> iter_method;

    print("=== fixed: visited-set walker ===");
    fixed = ErasureLookup(target="?w");
    root spawn fixed;
    for line in fixed.report {
        print(line);
    }

    print("");
    print("=== naive: no guard, depth-capped ===");
    naive = NaiveErasure();
    root spawn naive;
    for line in naive.report {
        print(line);
    }
}
