"""Test annex for road-trip playlist.

Verifies that three tracks can be created inline in a single chained
connection expression off the root, that they form a linked playlist,
and that the Player walker plays them in order, printing now-playing
lines and accumulating the total runtime.
"""

import io;
import from contextlib { redirect_stdout }

test "three tracks chained inline from root" {
    root ++> (first := Track(title="Highway Sun", artist="The Open Road", runtime_min=4.25))
        ++> (second := Track(title="Desert Wind", artist="Sandy Trails", runtime_min=3.75))
        ++> (third := Track(title="Coastal Glow", artist="Lamp Lite", runtime_min=5.10));

    # Root should have exactly one outgoing edge (to the first track).
    assert len([root-->]) == 1, f"root should link to 1 track, got {len([root-->])}";

    # First track should chain to the second, second to the third.
    children = [first-->];
    assert len(children) == 1, f"first should chain to 1 child, got {len(children)}";
    assert children[0].title == "Desert Wind", f"first child title: {children[0].title}";

    grandchildren = [second-->];
    assert len(grandchildren) == 1, f"second should chain to 1 child, got {len(grandchildren)}";
    assert grandchildren[0].title == "Coastal Glow", f"second child title: {grandchildren[0].title}";

    # Third (last) track should have no outgoing track edges.
    assert len([third-->]) == 0, f"third should be terminal, got {len([third-->])}";

    # Inline-created node field values are preserved.
    assert first.runtime_min == 4.25, f"first runtime: {first.runtime_min}";
    assert second.artist == "Sandy Trails", f"second artist: {second.artist}";
    assert third.title == "Coastal Glow", f"third title: {third.title}";
}

test "Player walker prints now-playing and accumulates total runtime" {
    root ++> (a := Track(title="Highway Sun", artist="The Open Road", runtime_min=4.25))
        ++> (b := Track(title="Desert Wind", artist="Sandy Trails", runtime_min=3.75))
        ++> (c := Track(title="Coastal Glow", artist="Lamp Lite", runtime_min=5.10));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # All three now-playing lines must appear, in chain order.
    assert "Now playing: Highway Sun by The Open Road (4.25 min)" in out, f"missing first line: {out}";
    assert "Now playing: Desert Wind by Sandy Trails (3.75 min)" in out, f"missing second line: {out}";
    assert "Now playing: Coastal Glow by Lamp Lite (5.1 min)" in out, f"missing third line: {out}";

    # Order of playback follows the chained links.
    idx_first = out.index("Highway Sun");
    idx_second = out.index("Desert Wind");
    idx_third = out.index("Coastal Glow");
    assert idx_first < idx_second < idx_third, f"wrong playback order: {out}";

    # Player walker mutates its own has fields during the walk.
    assert res.track_count == 3, f"track_count: {res.track_count}";

    # Total runtime is the sum of all three track runtimes.
    expected_total = 4.25 + 3.75 + 5.10;
    assert res.total_runtime == expected_total, f"total_runtime: {res.total_runtime} vs {expected_total}";

    # Exactly three now-playing lines should be printed.
    line_count = out.count("Now playing:");
    assert line_count == 3, f"now-playing line count: {line_count}";
}

test "Player on a single-track playlist reports one track and that runtime" {
    # The walker should still work for shorter playlists (just root -> one track).
    root ++> (only := Track(title="Solo", artist="One", runtime_min=2.0));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    assert "Now playing: Solo by One (2.0 min)" in out, f"missing solo line: {out}";
    assert res.track_count == 1, f"track_count: {res.track_count}";
    assert res.total_runtime == 2.0, f"total_runtime: {res.total_runtime}";

    # No additional now-playing lines beyond the single one.
    assert out.count("Now playing:") == 1, f"expected 1 line, got: {out}";
}

