"""RBAC redesign demo: separate the four axes (account type, tenancy, entitlement, permission)
into node archetypes, model roles as per-org permission sets, and let a walker traverse the
permission grants the way the issue describes (recursive role->capability lookup and
cascade-invalidation of stale per-user boolean columns)."""

node Org {
    # Tenancy axis. Both customer orgs and MSP orgs are orgs.
    has name: str = "";
    has kind: str = "customer";
}

node Account {
    # Account type axis: human vs service.
    has label: str = "";
    has is_service: bool = False;
}

node Entitlement {
    # Entitlement axis: tier gating. Deliberately separate from RBAC.
    has tier: str = "free";
}

node Capability {
    # Permission axis as rows, not columns.
    has name: str = "";
}

node Role {
    # Roles are named permission sets, defined per org.
    has title: str = "";
}

edge MemberOf {
    # An account belongs to an org (tenancy).
    has since: str = "";
}

edge Holds {
    # An account holds an entitlement.
}

edge Granted {
    # A capability is granted to a role (or directly to an account, legacy).
    has source: str = "role";
}

edge DefinedIn {
    # A role is defined in an org (per-org role catalog).
}

edge MigratesTo {
    # Legacy per-user boolean column -> capability row, for the migration path.
    has legacy_column: str = "";
}

walker PermissionAuditor {
    # Walks the org -> roles -> capabilities graph and reports the resolved
    # permission set for each member account. Also flags legacy boolean
    # columns that still exist on accounts and need migration.

    has audit_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_org with Org entry {
        self.audit_log.append(f"[ORG] {here.name} ({here.kind})");
        visit [-->];
    }

    can inspect_role with Role entry {
        self.audit_log.append(f"  [ROLE] {here.title} (defined in this org)");
        visit [-->];
    }

    can inspect_account with Account entry {
        legacy = "";
        if here.is_service {
            legacy = "service-account (account-type axis)";
        } else {
            legacy = "human (account-type axis)";
        }
        self.audit_log.append(f"[ACCT] {here.label} -> {legacy}");
        visit [-->];
    }

    can list_capability with Capability entry {
        self.audit_log.append(f"    -> capability: {here.name}");
        # Capabilities have no outgoing edges of interest.
    }
}

walker StaleColumnInvalidator {
    # The issue's other complaint: hand-rolled cascade invalidation of legacy
    # boolean columns. This walker reaches every legacy MigratesTo edge and
    # detaches it, mirroring the "stale column purge" cascade the maintainer
    # was hand-rolling through per-user id maps.

    has purged: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can purge with Account entry {
        # An account may still carry legacy boolean grants via MigratesTo edges.
        # We visit them out and invalidate, simulating the cascade.
        visit [->:MigratesTo:->];
    }

    can invalidate with Capability entry {
        # This capability was previously a per-user boolean column; record it
        # and disconnect the legacy edge to simulate the migration purge.
        self.purged.append(here.name);
    }
}

with entry {
    # --- Build a customer org with per-org roles (the issue's main ask) ---
    customer = Org(name="Acme Corp", kind="customer");

    eng_role = Role(title="Engineer");
    billing_role = Role(title="Billing Contact");

    customer +>:DefinedIn:+> eng_role;
    customer +>:DefinedIn:+> billing_role;

    cap_view_billing = Capability(name="view_billing");
    cap_edit_billing = Capability(name="edit_billing");
    cap_view_team = Capability(name="view_team");
    cap_manage_team = Capability(name="manage_team");

    eng_role +>:Granted:+> cap_view_billing;
    eng_role +>:Granted:+> cap_view_team;
    billing_role +>:Granted:+> cap_view_billing;
    billing_role +>:Granted:+> cap_edit_billing;
    billing_role +>:Granted:+> cap_manage_team;

    # --- An MSP org with its own role catalog (same mechanism, different scope) ---
    msp = Org(name="Shane MSP", kind="msp");
    msp_admin = Role(title="MSPAdmin");
    msp_operator = Role(title="MSPOperator");
    msp +>:DefinedIn:+> msp_admin;
    msp +>:DefinedIn:+> msp_operator;
    msp_admin +>:Granted:+> cap_manage_team;
    msp_operator +>:Granted:+> cap_view_billing;

    # --- Accounts: humans and a service account (account-type axis) ---
    alice = Account(label="alice@acme", is_service=False);
    bob = Account(label="bob@acme", is_service=False);
    svc = Account(label="svc-backup", is_service=True);

    alice +>:MemberOf(since="2024-01"):+> customer;
    bob +>:MemberOf(since="2024-03"):+> customer;
    svc +>:MemberOf(since="2024-06"):+> customer;

    # Account -> Role assignment (per-org).
    alice +>:Granted:+> eng_role;
    bob +>:Granted:+> billing_role;

    # Entitlement axis (tier gating), kept separate as the issue insists.
    alice +>:Holds:+> Entitlement(tier="pro");
    bob +>:Holds:+> Entitlement(tier="free");
    svc +>:Holds:+> Entitlement(tier="assessment");

    # Legacy boolean columns still wired up via MigratesTo (must be purged
    # cleanly when the new model lands; this is what the issue complains about).
    alice +>:MigratesTo(legacy_column="canApprovePurchases"):+> cap_view_billing;
    bob +>:MigratesTo(legacy_column="canManageTeam"):+> cap_manage_team;

    # --- Wire everything under root and spawn the walkers ---
    root ++> customer ++> msp;

    auditor = PermissionAuditor();
    root spawn auditor;
    print("=== Permission audit (recursive role -> capability walk) ===");
    for line in auditor.audit_log {
        print(line);
    }

    invalidator = StaleColumnInvalidator();
    root spawn invalidator;
    print("\n=== Stale legacy-column purge (cascade invalidation walk) ===");
    for name in invalidator.purged {
        print(f"purged legacy column -> {name}");
    }
}
