# --- Vocabularies (classification, regulatory tags, residency, etc.) ---

enum Classification {
    PUBLIC = "PUBLIC",
    INTERNAL = "INTERNAL",
    CONFIDENTIAL = "CONFIDENTIAL",
    RESTRICTED = "RESTRICTED",
}

enum Residency {
    EU = "EU",
    US = "US",
    APAC = "APAC",
}

# --- Base archetype: shared governance surface for the union trigger ---

node Governed {
    has name: str = "";

    def audit_label() -> str {
        return self.name;
    }
}

# --- Entity archetypes (inherit the shared governance surface) ---

node InformationAsset(Governed) {
    has classification: Classification = Classification.INTERNAL;
    has owner: str = "";
    has steward: str = "";
    has custodian: str = "";
    has last_review: str = "";
    has retention_days: int = 0;
    has days_since_review: int = 0;
    has redacted: bool = False;

    override def audit_label() -> str {
        return self.name;
    }
}

node DataFlow(Governed) {
    has protocol: str = "";
    has purpose: str = "";
    has residency: Residency = Residency.EU;
    has carries_pii: bool = False;

    override def audit_label() -> str {
        return self.name;
    }
}

node GovernanceTask(Governed) {
    has title: str = "";
    has severity: str = "info";
    has detail: str = "";

    override def audit_label() -> str {
        return self.name;
    }
}

# --- Typed edges: the relationships carry meaning ---

edge FlowsTo { }      # InformationAsset -> DataFlow -> InformationAsset
edge AssignedTo { }   # GovernanceTask -> InformationAsset

# --- Walker: audits the register for governance gaps ---

walker GovernanceAuditor {
    has findings: list[str] = [];

    can begin with Root entry {
        print("Governance audit starting");
        visit [->:FlowsTo:->];
    }

    can check_asset with InformationAsset entry {
        missing: list[str] = [];
        if here.owner == "" {
            missing.append("owner");
        }
        if here.steward == "" {
            missing.append("steward");
        }
        if here.custodian == "" {
            missing.append("custodian");
        }
        if len(missing) > 0 {
            self.findings.append(
                f"missing stewardship on {here.name}: {', '.join(missing)}"
            );
        }
        if here.days_since_review > 90 {
            self.findings.append(
                f"overdue review on {here.name} ({here.days_since_review} days)"
            );
        }
        if here.classification == Classification.RESTRICTED and not here.redacted {
            self.findings.append(
                f"restricted asset {here.name} not redacted in views"
            );
        }
        visit [->:FlowsTo:->];
    }

    can walk_flow with DataFlow entry {
        visit [->:FlowsTo:->];
    }
}

# --- Walker: surfaces cross-boundary data flows ---

walker CrossBoundaryScanner {
    has crossings: list[str] = [];

    can begin with Root entry {
        print("Cross-boundary scanner walking the data-flow graph");
        visit [->:FlowsTo:->];
    }

    can scan with InformationAsset entry {
        visit [->:FlowsTo:->];
    }

    can record with DataFlow entry {
        if here.carries_pii and here.residency != Residency.EU {
            self.crossings.append(
                f"PII flow ({here.purpose}) crossing EU boundary to {here.residency.value}"
            );
        }
        visit [->:FlowsTo:->];
    }
}

