```jac
"""Gallery security console: visitors log generically; curators add an official inspection.

Every visitor triggers a generic entry log on the room. Curators, in addition,
trigger a separate official inspection ability that records the curator's name
on the room and tallies how many rooms they inspected. A plain tourist does
not trigger the official ability at all.
"""

node Room {
    has room_name: str = "";
    has last_inspector: str = "";
}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        print(f"[LOG] Tourist entered {here.room_name}");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        print(f"[LOG] Curator {self.curator_name} entered {here.room_name}");
        visit [-->];
    }

    # Union trigger: fires only for a Curator, never for a Tourist.
    # Records the inspection on the room and tallies the curator's count.
    can inspect with Room entry {
        here.last_inspector = self.curator_name;
        self.rooms_inspected += 1;
        print(f"[INSPECTION] Official inspection by {self.curator_name} "
              f"in {here.room_name}");
    }
}

with entry {
    room_a = Room(room_name="Hall of Modern Art");
    room_b = Room(room_name="Sculpture Garden");
    root ++> room_a ++> room_b;

    tourist = Tourist();
    root spawn tourist;

    curator = Curator(curator_name="Dr. Vance");
    root spawn curator;

    print(f"Tourist triggered generic logs only.");
    print(f"Curator {curator.curator_name} inspected {curator.rooms_inspected} rooms "
          f"as '{curator.curator_name}'.");
    print(f"Difference: curator recorded {curator.rooms_inspected} official "
          f"inspections; the tourist recorded 0.");
}
