    assert "[INSPECTION] Official inspection by Dr. Vance in Sculpture Garden" in out, f"missing Garden inspection: {out}";
    # Every room records the curator's name as last inspector.
    for r in rooms {
        assert r.last_inspector == "Dr. Vance", f"room {r.room_name} inspector = '{r.last_inspector}'";
    }
    # The curator's tally matches the number of rooms inspected.
    assert res.rooms_inspected == 2, f"curator inspected {res.rooms_inspected} rooms, expected 2";
