    assert res.rooms_inspected == 2, f"expected 2 rooms inspected, got {res.rooms_inspected}";
    assert room_a.last_inspector == "Prof. Quill", f"room_a inspector = '{room_a.last_inspector}'";
    assert room_b.last_inspector == "Prof. Quill", f"room_b inspector = '{room_b.last_inspector}'";
    assert res.curator_name == "Prof. Quill", f"curator_name on walker = '{res.curator_name}'";
