"""Chai-Aur-Code DSA progress tracker: topics as nodes, ordered by index, walked in playlist order."""

node Topic {
    has title: str = "";
    has index: int = 0;
    has done: bool = False;
}

edge Next { }

walker PlaylistWalker {
    has visited_count: int = 0;
    has done_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can progress with Topic entry {
        self.visited_count += 1;
        if here.done {
            self.done_count += 1;
            print(f"[x] {here.index:>2}. {here.title}");
        } else {
            print(f"[ ] {here.index:>2}. {here.title}");
        }
        visit [->:Next:->];
    }
}

walker FindNextIncomplete {
    can start with Root entry {
        visit [-->];
    }

    can scan with Topic entry {
        if not here.done {
            print(f"Next topic to study: {here.index}. {here.title}");
            disengage;
        }
        visit [->:Next:->] else { disengage; }
    }
}

with entry {
    intro = Topic(title="Introduction to DSA & Time Complexity", index=1, done=True);
    arrays = Topic(title="Arrays in Python", index=2);
    sll = Topic(title="Singly Linked List in Python", index=3);
    dll = Topic(title="Doubly Linked List in Python", index=4);
    cll = Topic(title="Circular Linked List in Python", index=5);
    stack = Topic(title="Stack Data Structure in Python", index=6);
    queue = Topic(title="Queue Data Structure in Python", index=7);
    recursion = Topic(title="Recursion in Python", index=8);
    tree = Topic(title="Binary Tree Data Structure", index=9);
    traversal = Topic(title="Tree Traversal (Preorder, Inorder, Postorder)", index=10);

    root +>:Next:+> intro
        +>:Next:+> arrays
        +>:Next:+> sll
        +>:Next:+> dll
        +>:Next:+> cll
        +>:Next:+> stack
        +>:Next:+> queue
        +>:Next:+> recursion
        +>:Next:+> tree
        +>:Next:+> traversal;

    print("=== Walking playlist in order ===");
    pw = PlaylistWalker();
    root spawn pw;
    print(f"Walked {pw.visited_count} topics, completed {pw.done_count}");

    print("=== Finding next incomplete topic ===");
    root spawn FindNextIncomplete();
}
