"""Tests for the Chai-Aur-Code DSA progress tracker."""

import io;
import from contextlib { redirect_stdout }

test "playlist walker traverses all topics in order, counting done vs total" {
  `root = Root();

  t1 = Topic(title="Intro", index=1, done=True);
  t2 = Topic(title="Arrays", index=2);
  t3 = Topic(title="SLL", index=3, done=True);
  t4 = Topic(title="DLL", index=4);

  `root +>:Next:+> t1 +>:Next:+> t2 +>:Next:+> t3 +>:Next:+> t4;

  buf = io.StringIO();
  with redirect_stdout(buf) {
    pw = PlaylistWalker();
    `root spawn pw;
  }
  out = buf.getvalue();

  assert pw.visited_count == 4, f"expected 4 visited, got {pw.visited_count}";
  assert pw.done_count == 2, f"expected 2 done, got {pw.done_count}";

  # Playlist order must be preserved in the printed output.
  idx_intro = out.find("Intro");
  idx_arr = out.find("Arrays");
  idx_sll = out.find("SLL");
  idx_dll = out.find("DLL");
  assert idx_intro >= 0 and idx_arr > idx_intro, f"order broken: {out!r}";
  assert idx_sll > idx_arr, f"order broken: {out!r}";
  assert idx_dll > idx_sll, f"order broken: {out!r}";

  # Done markers must appear before not-done markers within their own slot.
  assert "[x]" in out, f"missing done marker in {out!r}";
  assert "[ ]" in out, f"missing pending marker in {out!r}";
}

test "find next incomplete stops at first not-done topic and disengages on remainder" {
  `root = Root();

  a = Topic(title="A done", index=1, done=True);
