  `root +>:Next:+> a +>:Next:+> b +>:Next:+> c +>:Next:+> d;

  buf = io.StringIO();
  with redirect_stdout(buf) {
    `root spawn FindNextIncomplete();
  }
  out = buf.getvalue();

  # Must announce the FIRST incomplete (c), and must NOT announce later ones.
  assert "C pending" in out, f"expected first incomplete to be announced: {out!r}";
  assert "D pending" not in out, f"walker must disengage before later incomplete: {out!r}";

  # The headline phrase must be present.
