```jac
"""Render path telemetry: model the in-raster vs full draw-command metric split.

The issue observes that ``sort_draw_commands`` partitions an array into an
in-frustum prefix (``raster_draws``) and an RT-only tail, then gates a
parallel sort on the prefix length. The recorded metric ``bench_draws_cmds``
measures the whole array, so the in-raster quantity that actually feeds the
gate is never captured. We model that gap with a graph where the typed edge
``PartitionEdge`` carries the split (total length + raster length + tail length),
and a walker audits each render gate against what the bench actually records.
"""

node DrawCommand {
    has label: str = "";
    has cull: bool = True;
}

node RenderGate {
    has gate_name: str = "";
    has threshold: int = 0;
    has branch_taken: str = "";
}

node Partition {
    has total: int = 0;
    has raster_len: int = 0;
    has tail_len: int = 0;
}

node Metric {
    has metric_name: str = "";
    has measured_total: int = 0;
}

edge PartitionEdge {
    has rel: str = "";
}

edge AuditEdge {
    has rel: str = "";
}

walker TelemetryAuditor {
    has missing_columns: list = [];

    can start with Root entry {
        visit [-->];
    }

    can review_gate with RenderGate entry {
        print(f"gate '{here.gate_name}' threshold={here.threshold} branch_taken='{here.branch_taken}' (unfalsifiable from bench)");
        visit [-->];
    }

    can audit_partition with Partition entry {
        print(f"partition: total={here.total} raster={here.raster_len} tail={here.tail_len}");
        raster_len = here.raster_len;
        threshold = 3000;
        actual_branch = "PARALLEL" if raster_len >= threshold else "SERIAL";
        ok_label = "unmeasured-branch";
        print(f"  actual branch from raster_len: {actual_branch} [{ok_label}]");
        visit [-->];
    }

    can audit_metric with Metric entry {
        mname = here.metric_name;
        self.missing_columns.append(mname);
        print(f"  recorded metric '{mname}'={here.measured_total} measures whole array, NOT raster prefix");
        visit [-->] else {
            print(f"audit complete; unfalsifiable columns: {self.missing_columns}");
            disengage;
        }
    }
}

with entry {
    gate = RenderGate(gate_name="DRAW_SORT_PARALLEL", threshold=3000, branch_taken="PARALLEL");
    root ++> gate;

    for i in range(500) {
        cull_flag = True if i < 150 else False;
        gate ++> DrawCommand(label=f"d{i}", cull=cull_flag);
    }

    partition_node = Partition(total=500, raster_len=150, tail_len=350);
    gate +>:PartitionEdge(rel="splits"):+> partition_node;

    metric_node = Metric(metric_name="bench_draws_cmds", measured_total=500);
    partition_node +>:AuditEdge(rel="audited-by"):+> metric_node;

    root spawn TelemetryAuditor();
}
```

import io;
import from contextlib { redirect_stdout }

test "raster prefix below gate selects serial sort" {
    gate = RenderGate(gate_name="DRAW_SORT_PARALLEL", threshold=3000, branch_taken="PARALLEL");
    root ++> gate;
    part = Partition(total=500, raster_len=150, tail_len=350);
    gate +>:PartitionEdge(rel="splits"):+> part;
    metric = Metric(metric_name="bench_draws_cmds", measured_total=500);
    part +>:AuditEdge(rel="audited-by"):+> metric;

