    assert "actual branch from raster_len: PARALLEL [unmeasured-branch]" in out, f"expected PARALLEL from raster_len=3500: {out}";
    assert "partition: total=5000 raster=3500 tail=1500" in out, f"missing partition split: {out}";
}

test "whole-array metric cannot falsify branch when total exceeds raster prefix" {
    gate = RenderGate(gate_name="DRAW_SORT_PARALLEL", threshold=3000, branch_taken="PARALLEL");
