    root ++> gate;
    part = Partition(total=800, raster_len=200, tail_len=600);
    gate +>:PartitionEdge(rel="splits"):+> part;
    metric = Metric(metric_name="bench_draws_cmds", measured_total=800);
    part +>:AuditEdge(rel="audited-by"):+> metric;

