test "partition edge exposes in-raster split separate from total draws" {
    gate = RenderGate(gate_name="DRAW_SORT_PARALLEL", threshold=3000, branch_taken="PARALLEL");
    root ++> gate;
    part = Partition(total=3949, raster_len=1200, tail_len=2749);
    gate +>:PartitionEdge(rel="splits"):+> part;
    metric = Metric(metric_name="bench_draws_cmds", measured_total=3949);
    part +>:AuditEdge(rel="audited-by"):+> metric;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TelemetryAuditor();
    }
    out = buf.getvalue();
    assert "partition: total=3949 raster=1200 tail=2749" in out, f"split not reported: {out}";
    assert "recorded metric 'bench_draws_cmds'=3949" in out, f"bench only sees total: {out}";
    assert "actual branch from raster_len: SERIAL [unmeasured-branch]" in out, f"total above 3000 but raster below gate: {out}";
}

