```jac
"""Deploy pipeline: pre-built venv/wheel cache invalidation across CI runs.

Models the essential scenario from joongsim/fitted issue #66: a CI pipeline
that produces a deploy cache keyed by the lockfile hash, a deploy job that
either consumes a matching cache or falls back to a slow install, and an
auditor walker that traverses the cache history to invalidate stale entries
when the lockfile changes.
"""

node DeployJob {
    has name: str = "";
    has lockfile_hash: str = "";
    has status: str = "pending";
}

node CacheEntry {
    has key: str = "";
    has lockfile_hash: str = "";
    has size_mb: float = 0.0;
    has built_at: str = "";
    has stale: bool = False;
}

node BuildStep {
    has label: str = "";
    has duration_s: int = 0;
}

edge Produced {
    has timestamp: str = "";
}

edge Invalidates { }

edge Step { }

walker CacheAuditor {
    has current_lock_hash: str = "";

    can start with Root entry {
        print(f"Auditing caches against lockfile hash {self.current_lock_hash}");
        visit [->:Produced:->];
    }

    can review with CacheEntry entry {
        is_match = here.lockfile_hash == self.current_lock_hash;
        verdict = "HIT" if is_match else "MISS";
        action = "reuse" if is_match else "rebuild";
        print(f"  cache[{here.key}] hash={here.lockfile_hash} -> {verdict} ({action})");
        visit [->:Invalidates:->];
    }

    can invalidate with CacheEntry entry {
        if not here.stale {
            here.stale = True;
            print(f"  ! invalidated stale cache {here.key} (lockfile drift)");
        }
        visit [->:Step:->];
    }

    can summarize with BuildStep entry {
        print(f"  step[{here.label}] took {here.duration_s}s");
        visit [-->];
    }
}

walker CacheAudit {
    has current_lock_hash: str = "";
    has hits: int = 0;
    has misses: int = 0;

    can start with Root entry {
        visit [->:Produced:->];
    }

    can tally with CacheEntry entry {
        if here.lockfile_hash == self.current_lock_hash {
            self.hits += 1;
        } else {
            self.misses += 1;
        }
        visit [->:Step:->];
    }

    can finish with BuildStep entry {
        print(f"Audit done: {self.hits} hit(s), {self.misses} miss(es)");
        visit [-->] else { disengage; }
    }
}

with entry {
    job = DeployJob(name="deploy-prod", lockfile_hash="abc123");
    root ++> job;

    fresh = CacheEntry(key="cache-v7", lockfile_hash="abc123", size_mb=312.0, built_at="2026-01-15T10:00Z");
    stale1 = CacheEntry(key="cache-v5", lockfile_hash="111111", size_mb=298.0, built_at="2026-01-10T10:00Z", stale=True);
    stale2 = CacheEntry(key="cache-v6", lockfile_hash="222222", size_mb=305.0, built_at="2026-01-12T10:00Z", stale=True);

    job +>:Produced(timestamp="2026-01-15"):+> fresh;
    job +>:Produced(timestamp="2026-01-10"):+> stale1;
    job +>:Produced(timestamp="2026-01-12"):+> stale2;

    fresh +>:Invalidates:+> stale1;
    stale2 +>:Invalidates:+> stale1;

    step_sync = BuildStep(label="uv sync (cold)", duration_s=180);
    step_cache = BuildStep(label="download+unpack cache", duration_s=12);
    fresh +>:Step:+> step_cache;
    stale1 +>:Step:+> step_sync;
    stale2 +>:Step:+> step_sync;

    print("== Walking the pipeline as an auditor (lockfile hash = abc123) ==");
    root spawn CacheAuditor(current_lock_hash="abc123");

    print("");
    print("== Walking the pipeline as an audit counter ==");
    root spawn CacheAudit(current_lock_hash="abc123");
}
