"""NSProxy-style URL session delegate instrumentation: model the crash scenario.

Models the Firebase Performance / PAGWeakProxy scenario where an NSProxy
wrapper holds a weak reference to a URLSession delegate, and CFNetwork
walks a chain of proxies to find a real target that responds to a selector.
We capture the core entities (proxy wrapper, weak target, real delegate,
URL session) as node archetypes and walk the delegate-invalidation
chain with a typed-edge walker.
"""

node Session {
    has name: str = "";
    has invalidated: bool = False;
}

node Proxy {
    has label: str = "";
    has target_alive: bool = True;
}

node Delegate {
    has kind: str = "real";
    has responds: bool = True;
}

edge Wraps {
    has via_weak: bool = True;
}

edge Owns {
}

edge DelegatesTo {
}

walker Invalidate {
    has crash_site: str = "";

    can start with Root entry {
        print(f"Beginning NSURLSession delegate invalidation sweep");
        visit [-->];
    }

    can find_session with Session entry {
        if here.invalidated {
            print(f"session {here.name} already invalidated; stopping walk");
            disengage;
        }
        here.invalidated = True;
        print(f"CFNetwork invalidating session: {here.name}");
        visit [->:DelegatesTo:->];
    }

    can chase_proxy with Proxy entry {
        self.crash_site = f"PAGWeakProxy respondsToSelector: via {here.label}";
        print(f"NSProxy wrapper intercepted: {here.label} (weak target alive={here.target_alive})");
        if not here.target_alive {
            print(f"CRASH: objc_loadWeakRetained returned nil at {here.label}; CFNetwork cannot proceed");
            disengage;
        }
        visit [->:Wraps:->];
    }

    can hit_real with Delegate entry {
        label = "responds" if here.responds else "silent";
        print(f"resolved real delegate ({here.kind}, {label}); invalidation callback dispatched");
    }
}

with entry {
    real = Delegate(kind="NSURLSessionDelegate", responds=True);
    proxy = Proxy(label="PAGWeakProxy", target_alive=False);
    session = Session(name="com.example.api");

    root ++> session;
    session +>:DelegatesTo:+> proxy;
    proxy +>:Wraps(via_weak=True):+> real;

    root spawn Invalidate();
}
```

import io;
import from contextlib { redirect_stdout }

test "dead weak proxy fails closed during invalidation" {
    real = Delegate(kind="NSURLSessionDelegate", responds=True);
    proxy = Proxy(label="PAGWeakProxy", target_alive=False);
    session = Session(name="com.example.api");

    root ++> session;
    session +>:DelegatesTo:+> proxy;
    proxy +>:Wraps(via_weak=True):+> real;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Invalidate();
    }
    out = buf.getvalue();

    assert session.invalidated == True, f"session invalidated={session.invalidated}";
    assert res.crash_site == "PAGWeakProxy respondsToSelector: via PAGWeakProxy", f"got {res.crash_site}";
    assert "CRASH: objc_loadWeakRetained returned nil" in out, f"missing crash marker: {out}";
    assert "invalidation callback dispatched" not in out, f"unexpected callback: {out}";
}

test "live weak proxy resolves the real delegate" {
    real = Delegate(kind="NSURLSessionDelegate", responds=True);
    proxy = Proxy(label="PAGWeakProxy", target_alive=True);
    session = Session(name="com.example.api");

    root ++> session;
    session +>:DelegatesTo:+> proxy;
    proxy +>:Wraps(via_weak=True):+> real;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Invalidate();
    }
    out = buf.getvalue();

    assert session.invalidated == True, f"session invalidated={session.invalidated}";
    assert proxy in [session ->:DelegatesTo:->], f"delegate edge missing";
    assert real in [proxy ->:Wraps:->], f"proxy wrapping edge missing";
    assert "NSProxy wrapper intercepted: PAGWeakProxy" in out, f"missing proxy marker: {out}";
    assert "resolved real delegate (NSURLSessionDelegate, responds)" in out, f"missing resolution: {out}";
    assert "CRASH:" not in out, f"unexpected crash: {out}";
}

test "already invalidated session stops before proxy traversal" {
    proxy = Proxy(label="PAGWeakProxy", target_alive=False);
    session = Session(name="com.example.api", invalidated=True);

    root ++> session;
    session +>:DelegatesTo:+> proxy;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Invalidate();
    }
    out = buf.getvalue();

    assert session.invalidated == True, f"session invalidated={session.invalidated}";
    assert "already invalidated; stopping walk" in out, f"missing stop marker: {out}";
    assert "NSProxy wrapper intercepted" not in out, f"proxy was traversed: {out}";
    assert "CRASH:" not in out, f"unexpected crash: {out}";
}

