"""Wildlife park feeding rounds.

The info kiosk greets every tour party via a union trigger; zookeepers
hand out species-appropriate meals; school groups only observe.
"""

# Base animal node so a union ability can touch shared fields/methods.
node Animal {
    has name: str;
    has fed: bool = False;
    has species: str = "animal";

    def preferred_meal() -> str {
        return "standard feed";
    }
}

node Lion(Animal) {
    override def preferred_meal() -> str {
        return "meat";
    }
}

node Parrot(Animal) {
    override def preferred_meal() -> str {
        return "seed";
    }
}

node Zebra(Animal) {
    override def preferred_meal() -> str {
        return "standard feed";
    }
}

node InfoKiosk {
    has kiosk_name: str;

    # Union trigger: fires for any tour party (zookeeper or school group).
    can greet with Zookeeper | SchoolGroup entry {
        print(f"Welcome {visitor.party_label} to the {self.kiosk_name} info kiosk!");
        visitor.kiosk_visits += 1;
    }
}

walker Zookeeper {
    has party_label: str = "Zookeepers";
    has kiosk_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach_kiosk with InfoKiosk entry {
        visit [-->];
    }

    # Union trigger: serve any animal species with the right meal.
    can feed with Lion | Parrot | Zebra entry {
        meal = here.preferred_meal();
        kind = here.species;
        print(f"Zookeeper feeds {here.name} the {kind}: {meal}");
        here.fed = True;
        visit [-->];
    }
}

walker SchoolGroup {
    has party_label: str = "School Group";
    has kiosk_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach_kiosk with InfoKiosk entry {
        visit [-->];
    }

    can observe with Lion | Parrot | Zebra entry {
        print(f"School group watches {here.name} ({here.preferred_meal()})");
        visit [-->];
    }
}

with entry {
    kiosk = InfoKiosk(kiosk_name="Savannah");
    simba = Lion(name="Simba", species="lion");
    polly = Parrot(name="Polly", species="parrot");
