"""KubeMetal Upgrade Impact Analysis: model an upgrade bundle, its components, and
the dependency/breaking-change graph between them, then walk the graph with an
analyst walker that orders affected components, detects cycles, and emits a
rollout summary."""

node Component {
    has name: str = "";
    has current_version: str = "";
    has target_version: str = "";
    has workload_count: int = 0;
    has critical: bool = False;
    has breaking_notes: str = "";
}

node Risk {
    has severity: str = "";
    has rationale: str = "";
    has evidence_ref: str = "";
}

node ChecklistItem {
    has title: str = "";
    has step: str = "";
    has requires_confidence: bool = True;
}

edge DependsOn {
    has required_min_version: str = "";
}

edge AffectsWorkload {
    has replica_count: int = 0;
    has pdb_min_available: int = 0;
}

edge RaisesRisk {
    has confidence: float = 0.0;
}

walker UpgradeAnalyst {
    has visited: list[str] = [];
    has cycle_flag: bool = False;

    can start with Root entry {
        print("=== KubeMetal Upgrade Impact Analysis (offline / air-gap) ===");
        visit [-->];
    }

    can traverse_component with Component entry {
        if here.name in self.visited {
            self.cycle_flag = True;
            disengage;
        }
        self.visited.append(here.name);

        marker = "[!] " if here.critical else "    ";
        verdict = "BREAK" if here.breaking_notes else "ok  ";
        print(
            f"{marker}{here.name}: {here.current_version} -> {here.target_version}"
            f" | workloads={here.workload_count} | {verdict}"
        );

        visit [->:DependsOn:->];
        visit [->:RaisesRisk:->];
    }

    can inspect_risk with Risk entry {
        print(
            f"    risk[{here.severity}] {here.rationale}"
            f"  (evidence: {here.evidence_ref})"
        );
        visit [-->];
    }

    can inspect_checklist with ChecklistItem entry {
        print(f"    checklist: {here.title}");
        visit [-->];
    }
}

walker RolloutOrderer {
    has order: list[str] = [];
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [->:DependsOn:->];
    }

    can order_component with Component entry {
        if here.name in self.order {
            self.cycle_detected = True;
            print(f"  cycle detected touching {here.name}");
            disengage;
        }
        self.order.append(here.name);
        visit [->:DependsOn:->];
    }
}

