"""Threaded comments with depth limit and cascade invalidation.

Models the issue's concern: recursion over parent/child comment chains
is hand-rolled, and replies beyond a small depth should be capped (Reddit
"Load More" style). We use typed edges for the reply relationship and a
walker that enforces the depth policy while walking the reply forest.
"""

node Article {
    has title: str = "";
}

node Comment {
    has author: str = "";
    has body: str = "";
    has depth: int = 0;
    has open: bool = True;
}

edge ReplyTo {
    has order: int = 0;
}

walker ReplyCrawler {
    has max_depth: int = 2;
    has visited: list[str] = [];
    has report: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can open_article with Article entry {
        print(f"Article: {here.title}");
        print(f"Reply cap depth: {self.max_depth}");
        visit [->:ReplyTo:->];
    }

    can walk_comments with Comment entry {
        key = f"{here.author}:{here.depth}:{id(here)}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        marker = "+" if here.depth <= self.max_depth else "x";
        state = "open" if here.open else "closed";
        self.report.append({
            "author": here.author,
            "depth": here.depth,
            "state": state,
            "marker": marker
        });
        print(f"  {marker} [d={here.depth} {state}] {here.author}: {here.body}");

        if here.depth < self.max_depth {
            visit [->:ReplyTo:->];
        } else {
            print(f"  -> replies beyond depth {self.max_depth} require 'Load More' page");
        }
    }
}

walker CascadeInvalidator {
    has reason: str = "author edited";
    has touched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pick_article with Article entry {
        print(f"Invalidating reply caches for '{here.title}' ({self.reason})");
        visit [->:ReplyTo:->];
    }

    can invalidate with Comment entry {
        if here.open {
            here.open = False;
            self.touched += 1;
            print(f"  closed reply by {here.author} (depth {here.depth})");
        }
        visit [->:ReplyTo:->];
    }
}

with entry {
    post = Article(title="Threaded comments: depth limits & cascade");
    post ++> Comment(author="alice", body="Top-level comment", depth=0)
        +>:ReplyTo(order=1):+> Comment(author="bob", body="First reply", depth=1)
        +>:ReplyTo(order=2):+> Comment(author="carol", body="Nested too deep", depth=2)
        +>:ReplyTo(order=3):+> Comment(author="dave", body="Off the rails", depth=3)
        +>:ReplyTo(order=4):+> Comment(author="eve", body="Way too deep", depth=4);

    post +>:ReplyTo:+> Comment(author="frank", body="Second top-level", depth=0)
        +>:ReplyTo:+> Comment(author="grace", body="Reply to frank", depth=1)
        +>:ReplyTo:+> Comment(author="heidi", body="Reply to grace (cap)", depth=2);

    print("=== ReplyCrawler ===");
    crawler = ReplyCrawler(max_depth=2);
    post spawn crawler;
    print(f"visited {len(crawler.report)} comments, capped at depth {crawler.max_depth}");

    print("\n=== CascadeInvalidator ===");
