```jac
"""Episodic memory history walk that survives supersedes forks.

Models the issue: a fork (one root superseded by two children) loses
one branch when the forward walk is keyed by a single-supersedes Map.
The fix lifts the adjacency to a multi-successor walk over the `Supersedes`
edge, keeping the cycle guard explicit (Jac 0.36.1 has no built-in
visited-set), and reports the full DAG-derived chain rather than a
linear last-writer-wins view.
"""

node Episode {
    has id: str = "";
    has title: str = "";
    has is_root: bool = False;
    has is_fork: bool = False;
}

edge Supersedes {
    has since: str = "";
}

walker HistoryWalker {
    has visited: list[str] = [];
    has chain: list = [];

    can start with Root entry {
        print("em-search --history (multi-successor, fork-safe)");
        visit [-->];
    }

    can descend with Episode entry {
        if here.id in self.visited {
            print(f"[cycle-guard] revisit blocked: {here.id}");
            disengage;
        }
        self.visited.append(here.id);
        self.chain.append(here);

        if here.is_root {
            print(f"root  {here.id}  {here.title}");
        } elif here.is_fork {
            print(f"fork  {here.id}  {here.title}  (branches below)");
        } else {
            print(f"      {here.id}  {here.title}");
        }

        children = [->:Supersedes:->];
        if not children {
            return;
        }
        visit children;
    }
}

with entry {
    # Pre-existing bug shape: one root, two siblings superseding it.
    # Old single-Map walk dropped one child; the typed-edge walk keeps both.
    root_ep = Episode(id="E0", title="origin", is_root=True);
    fork_a  = Episode(id="E1", title="branch-A", is_fork=True);
    fork_b  = Episode(id="E2", title="branch-B", is_fork=True);
    leaf_a  = Episode(id="E3", title="A.terminal");
    leaf_b  = Episode(id="E4", title="B.terminal");

    root_ep +>:Supersedes(since="t1"):+> fork_a;
    root_ep +>:Supersedes(since="t1"):+> fork_b;
    fork_a  +>:Supersedes(since="t2"):+> leaf_a;
    fork_b  +>:Supersedes(since="t2"):+> leaf_b;

    # Wire into the graph root and spawn the walker.
    root ++> root_ep;
    hw = HistoryWalker();
    root spawn hw;

    print(f"\nreport: count={len(hw.chain)}");
    for ep in hw.chain {
        tag = "ROOT" if ep.is_root else ("FORK" if ep.is_fork else "leaf");
        print(f"  [{tag}] {ep.id} {ep.title}");
    }
}
