"""Tiny dungeon crawler: rooms chained as nodes, hunter walker counts rooms and stops at the treasure."""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->];
    }

    can search with Room entry {
