    hallway = Room(name="Damp Hallway");
    armory = Room(name="Abandoned Armory");
    vault = Room(name="Gilded Vault", is_treasure=True);
    cavern = Room(name="Echoing Cavern");
    throne = Room(name="Throne Room");

    root ++> entrance ++> hallway ++> armory ++> vault ++> cavern ++> throne;

    hunter = Hunter();
    root spawn hunter;

    print(f"Rooms inspected: {hunter.rooms_checked}");
    outcome = "TREASURE RECOVERED" if hunter.found else "NO TREASURE";
    print(f"Outcome: {outcome}");
