"""Materialized-view parameter binding and checkpoint traversal demo."""

node MaterializedView {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has query: str = "";
}

node PersistedEvent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: int = 0;
}

node MvParameter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "NonNull";
    has value_json: str = "";
    has present: bool = True;
}

node ProjectionCheckpoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: int = 0;
    has committed: bool = False;
}

edge ViewEvent { }
edge EventParameter { }
edge ParameterCheckpoint { }
edge NextEvent { }

walker ProjectionAuditor {
    has steps: int = 0;
    has max_steps: int = 12;

    can start with Root entry {
        self.steps += 1;
        visit [-->] else {
            disengage;
        }
    }

    can inspect_view with MaterializedView entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the depth guard");
            disengage;
        }
        self.steps += 1;
        print(f"view: {here.title}, query={here.query}");
        visit [->:ViewEvent:->] else {
            disengage;
        }
    }

    can inspect_event with PersistedEvent entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the depth guard");
            disengage;
        }
        self.steps += 1;
        print(f"event revision {here.revision}: {here.title}");
        visit [->:EventParameter:->] else {
            disengage;
        }
    }

    can bind_parameter with MvParameter entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the depth guard");
            disengage;
        }
        self.steps += 1;

        if here.present == False {
            print("parameter absent: omitted from the command");
        } elif here.kind == "Null" {
            print("parameter bound through Dapper as SQL NULL");
        } elif here.value_json == "" {
            print("invalid parameter: non-Null kind has null ValueJson");
        } else {
            print(f"parameter bound as {here.value_json}");
        }

        visit [->:ParameterCheckpoint:->] else {
            disengage;
        }
    }

    can inspect_checkpoint with ProjectionCheckpoint entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the depth guard");
            disengage;
        }
        self.steps += 1;

        if here.committed {
            print(f"committed projection checkpoint at revision {here.revision}");
        } else {
            print(f"uncommitted projection checkpoint at revision {here.revision}");
        }

        visit [->:NextEvent:->] else {
            disengage;
        }
    }
}

with entry {
    view = MaterializedView(
        title="Customer materialized view",
        query="UPDATE customer_projection SET nickname = @Nickname",
        year=2026
    );
    null_event = PersistedEvent(
        title="persisted null nickname",
