        year=2026
    );
    null_parameter = MvParameter(
        title="Nickname",
        kind="Null",
        value_json="null",
        present=True
    );
    null_checkpoint = ProjectionCheckpoint(
        title="checkpoint after null update",
        revision=1,
        committed=True,
        year=2026
    );
    later_event = PersistedEvent(
        title="persisted non-null nickname",
