```jac
"""Shell component dependency scan: model components as nodes, walk consumers
to find orphaned files (like LabelValue.vue left behind after Harvester pkg removal)."""

node Component {
    has name: str = "";
    has package: str = "";
    has size_lines: int = 0;
    has orphaned: bool = False;
}

edge ImportedBy {
    has from_pkg: str = "";
}

walker OrphanHunter {
    has checked: list[str] = [];
    has orphans_found: list[str] = [];
    has target_name: str = "LabelValue";

    can start with Root entry {
        print(f"Scanning component graph for orphaned component: {self.target_name}");
        visit [-->];
    }

    can scan with Component entry {
        if here.name in self.checked {
            visit [-->];
            return;
        }
        self.checked.append(here.name);

        if here.name == self.target_name {
            here.orphaned = True;
            consumer_edges = [here->:ImportedBy:->];
            if not consumer_edges {
                self.orphans_found.append(here.name);
                print(f"[ORPHAN] {here.name} ({here.size_lines} lines, pkg={here.package}) - no consumers remain");
                disengage;
            }
            for c in consumer_edges {
                self.orphans_found.append(here.name);
                print(f"[ORPHAN] {here.name} ({here.size_lines} lines, pkg={here.package}) - last consumer was {c.name}");
            }
        }
        visit [-->];
    }
}

with entry {
    labelvalue = Component(name="LabelValue", package="shell/components", size_lines=42);
    harvester_form = Component(name="HarvesterNodeForm", package="shell/plugins/harvester", size_lines=120);
    harvester_list = Component(name="HarvesterNodeList", package="shell/plugins/harvester", size_lines=95);
    resource_table = Component(name="ResourceTable", package="shell/components", size_lines=260);
    project_release = Component(name="ProjectRelease", package="shell/components", size_lines=180);

    labelvalue +>:ImportedBy(from_pkg="shell/plugins/harvester"):+> harvester_form;
    labelvalue +>:ImportedBy(from_pkg="shell/plugins/harvester"):+> harvester_list;

    harvester_form +>:ImportedBy(from_pkg="shell/components"):+> resource_table;
    resource_table +>:ImportedBy(from_pkg="shell/components"):+> project_release;

    root ++> labelvalue ++> harvester_form ++> harvester_list ++> resource_table ++> project_release;

    root spawn OrphanHunter();
}
