import io;
import from contextlib { redirect_stdout }

test "orphan detected when target has no live consumers" {
    root ++> Component(name="LabelValue", package="shell/components", size_lines=42);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrphanHunter(target_name="LabelValue");
    }
    out = buf.getvalue();
    assert "[ORPHAN]" in out, f"missing orphan marker: {out!r}";
    assert "LabelValue" in out, f"missing component name: {out!r}";
    assert "42 lines" in out, f"missing line count: {out!r}";
    assert "shell/components" in out, f"missing package label: {out!r}";
    assert "no consumers remain" in out, f"missing orphan cause: {out!r}";
    assert "LabelValue" in res.orphans_found, f"orphans_found={res.orphans_found}";
    assert "LabelValue" in res.checked, f"checked={res.checked}";
}

test "orphan detected when only consumers are dead package" {
    labelvalue = Component(name="LabelValue", package="shell/components", size_lines=42);
    dead_form = Component(name="HarvesterNodeForm", package="shell/plugins/harvester", size_lines=120);
    dead_list = Component(name="HarvesterNodeList", package="shell/plugins/harvester", size_lines=95);
    labelvalue +>:ImportedBy(from_pkg="shell/plugins/harvester"):+> dead_form;
    labelvalue +>:ImportedBy(from_pkg="shell/plugins/harvester"):+> dead_list;
    root ++> labelvalue ++> dead_form ++> dead_list;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrphanHunter(target_name="LabelValue");
    }
    out = buf.getvalue();
    assert "[ORPHAN]" in out, f"missing orphan marker: {out!r}";
    # The walker reports each dead consumer it finds in turn.
    assert "last consumer was HarvesterNodeForm" in out, f"missing harvester form consumer: {out!r}";
    assert "last consumer was HarvesterNodeList" in out, f"missing harvester list consumer: {out!r}";
    # The component itself is flagged as orphaned regardless of dead consumers.
    target_nodes = [root-->][?:Component];
    label_nodes = [n for n in target_nodes if n.name == "LabelValue"];
    assert len(label_nodes) == 1, f"expected 1 LabelValue, got {len(label_nodes)}";
    assert label_nodes[0].orphaned is True, f"orphaned flag not set on {label_nodes[0].name}";
}

test "orphan not flagged when target name absent from graph" {
    root ++> Component(name="ResourceTable", package="shell/components", size_lines=260)
         ++> Component(name="ProjectRelease", package="shell/components", size_lines=180);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrphanHunter(target_name="LabelValue");
    }
    out = buf.getvalue();
    assert "[ORPHAN]" not in out, f"should not flag orphan when target absent: {out!r}";
    assert res.orphans_found == [], f"orphans_found should be empty: {res.orphans_found}";
    # Walker still scans every component it visits.
    assert "ResourceTable" in res.checked, f"checked missing ResourceTable: {res.checked}";
    assert "ProjectRelease" in res.checked, f"checked missing ProjectRelease: {res.checked}";
}

test "checklist prevents revisiting same component" {
    a = Component(name="LabelValue", package="shell/components", size_lines=42);
    b = Component(name="ResourceTable", package="shell/components", size_lines=260);
    root ++> a ++> b;
    # Wire a back-edge to create a second path to `b`.
    a +>:ImportedBy(from_pkg="shell/components"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrphanHunter(target_name="LabelValue");
    }
    out = buf.getvalue();
    # b is visited at most once even though two edges can reach it.
    assert res.checked.count("ResourceTable") == 1, f"expected 1 visit to ResourceTable, got {res.checked.count('ResourceTable')}: {res.checked}";
    # Orphan path still resolves cleanly.
    assert "[ORPHAN]" in out, f"missing orphan marker: {out!r}";
}

test "orphan flagged on a standalone target with size captured" {
    lone = Component(name="LabelValue", package="shell/components", size_lines=42);
    root ++> lone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
