```jac
"""RBAC: role hierarchy walker that audits permission reachability through a typed role graph.

Models the core access-control complaint hand-rolled in PHP/Laravel: users belong to
roles, roles inherit from other roles, and permissions propagate through the inheritance
graph. A walker descends the inheritance edges, accumulating granted permissions and
flagging escalation cycles — exactly the machinery the issue says the project rolled
by hand.
"""

node Permission {
    has slug: str = "";
    has description: str = "";
}

node Role {
    has title: str = "";
    has level: int = 0;
    has grants: list[str] = [];
}

edge HoldsRole {
    has granted_at: str = "";
}

edge Inherits {
    has since: str = "";
}

walker RoleAuditor {
    has target_role: str = "";
    has collected: list[str] = [];
    has seen: list[str] = [];
    has depth_limit: int = 4;

    can start with Root entry {
        if self.target_role == "" {
            print("RoleAuditor needs a target_role to investigate");
            disengage;
        }
        print(f"Auditing role: {self.target_role} (depth cap {self.depth_limit})");
        visit [-->];
    }

    can gather with Permission entry {
        visit [-->];
    }

    can climb with Role entry {
        if here.title != self.target_role {
            visit [-->] else { disengage; }
        }
        print(f"  arrived at role: {here.title} (level {here.level})");

        self.seen.append(here.title);
        self.collected.extend(here.grants);
        visit [-->];
    }

    can collect_parents with Role entry {
        if here.title in self.seen {
            print(f"  skip visited parent role: {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        print(f"  inheriting grants from: {here.title} (level {here.level})");
        self.collected.extend(here.grants);
        visit [-->] else { disengage; }
    }

    def summary() -> str {
        unique: list[str] = [];
        for g in self.collected {
            if g not in unique {
                unique.append(g);
            }
        }
        return f"Role '{self.target_role}' resolves to {len(unique)} permissions: {unique}";
    }
}

with entry {
    view_users = Permission(slug="users.read", description="Read user records");
    edit_users = Permission(slug="users.edit", description="Edit user records");
    create_gig = Permission(slug="gig.create", description="Create GIGs");
    manage_orders = Permission(slug="orders.manage", description="Manage orders");
    withdraw_funds = Permission(slug="payments.withdraw", description="Withdraw funds");
    audit_log = Permission(slug="audit.read", description="Read audit log");

    guest = Role(title="Guest", level=0, grants=["users.read"]);
    buyer = Role(title="Buyer", level=1, grants=["gig.create"]);
    seller = Role(title="Seller", level=2, grants=["gig.create", "orders.manage", "payments.withdraw"]);
    admin = Role(title="Admin", level=3, grants=["users.edit", "orders.manage"]);
    super_admin = Role(title="SuperAdmin", level=4, grants=["users.edit", "audit.read"]);

    root ++> view_users ++> create_gig ++> manage_orders
        ++> withdraw_funds ++> audit_log ++> edit_users;

    buyer +>:Inherits(since="v1"):+> guest;
    seller +>:Inherits(since="v1"):+> buyer;
    admin +>:Inherits(since="v1"):+> seller;
    super_admin +>:Inherits(since="v1"):+> admin;

    root +>:HoldsRole(granted_at="init"):+> guest;
    root +>:HoldsRole(granted_at="init"):+> buyer;
    root +>:HoldsRole(granted_at="init"):+> seller;
    root +>:HoldsRole(granted_at="init"):+> admin;
    root +>:HoldsRole(granted_at="init"):+> super_admin;

    auditor = RoleAuditor(target_role="Seller", depth_limit=4);
    root spawn auditor;
    print(auditor.summary());

