"""Program-aware support, reporting, and comms demo.

Models the core scenario from issue #1651: a Program node owns Mentee/Mentor
participants via typed edges, a SupportTicket is filed against a program and
carries priority/category/SLA fields, and a Newsletter issue freezes an
audience snapshot resolved over the program graph at send time. Walkers
traverse the graph natively instead of hand-rolled recursion.
"""

node Program {
    has name: str = "";
    has cohort: str = "";
}

node Mentee {
    has title: str = "";
    has stage: str = "applied";
    has tags: list[str] = [];
}

node Mentor {
    has title: str = "";
    has company: str = "";
}

node SupportTicket {
    has subject: str = "";
    has priority: str = "normal";
    has category: str = "general";
    has status: str = "open";
    has sla_minutes: int = 240;
    has search_terms: list[str] = [];
}

edge BelongsTo {
    has joined: str = "2026-01";
}

edge AssignedTo {
    has role: str = "requester";
}

edge FiledAgainst {
    has opened_at: str = "2026-03-01";
}

walker ProgramReporter {
    has program_name: str = "";
    has mentee_count: int = 0;
    has mentor_count: int = 0;
    has open_tickets: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can count_members with Program entry {
        self.program_name = here.name;
        visit [->:BelongsTo:->];
    }

    can tally with Mentee entry {
        self.mentee_count += 1;
        visit [-->];
    }

    can tally_m with Mentor entry {
        self.mentor_count += 1;
        visit [-->];
    }

    can count_tickets with SupportTicket entry {
        if here.status != "closed" {
            self.open_tickets += 1;
        }
        visit [-->];
    }
}

walker SupportQueueFilter {
    has program_name: str = "";
    has min_priority: str = "low";
    has category: str = "any";
    has search: str = "";
    has kept: list[SupportTicket] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_programs with Program entry {
        self.program_name = here.name;
        visit [->:FiledAgainst:->];
    }

    can scan_tickets with SupportTicket entry {
        rank = {"low": 0, "normal": 1, "high": 2, "urgent": 3};
        here_rank = rank.get(here.priority, 0);
        cutoff = rank.get(self.min_priority, 0);
        cat_ok = (self.category == "any") or (here.category == self.category);
        search_ok = (self.search == "");
        if not search_ok {
            for term in here.search_terms {
                if term == self.search {
                    search_ok = True;
                }
            }
        }
        if (here_rank >= cutoff) and cat_ok and search_ok {
            self.kept.append(here);
        }
        visit [-->];
    }
}

walker NewsletterSend {
    has program_name: str = "";
    has audience: str = "MENTEE";
    has frozen: list[str] = [];
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pick_program with Program entry {
        self.program_name = here.name;
        visit [->:BelongsTo:->];
    }

    can snapshot with Mentee entry {
        if (self.audience == "MENTEE") or (self.audience == "BOTH") {
            self.frozen.append(here.title);
            self.count += 1;
        }
        visit [-->];
    }

    can snapshot_mentor with Mentor entry {
        if (self.audience == "MENTOR") or (self.audience == "BOTH") {
            self.frozen.append(here.title);
            self.count += 1;
        }
        visit [-->];
    }
}

with entry {
