    spring +>:BelongsTo:+> m1;
    spring +>:BelongsTo:+> m2;
    spring +>:BelongsTo:+> mentor_a;
    fall +>:BelongsTo:+> m3;
    fall +>:BelongsTo:+> mentor_b;

    t1 = SupportTicket(
        subject="Login broken",
        priority="urgent",
        category="auth",
        status="open",
        sla_minutes=60,
        search_terms=["login", "auth"]
    );
    t2 = SupportTicket(
        subject="Stipend question",
