    );

    queue = SupportQueueFilter(min_priority="high", category="auth", search="login");
    root spawn queue;
    print(f"[queue] high/critical auth tickets matching 'login': {len(queue.kept)}");

    blast = NewsletterSend(audience="MENTEE");
    root spawn blast;
    print(f"[blast] {blast.program_name} audience={blast.audience} frozen_count={blast.count}");
}
