"""Flight network: priced legs normalize against the scout's peak fare report."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has ticket_price: float = 0.0;
    has origin_code: str = "";
    has dest_code: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.ticket_price / peak;
    }
}

walker Scout {
    has peak_fare: float = 0.0;
    has fare_report: list[float] = [];
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can sweep with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.fare_report.append(leg.ticket_price);
            if leg.ticket_price > self.peak_fare {
                self.peak_fare = leg.ticket_price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");
    bos = Airport(code="BOS");

    root ++> jfk;

    leg_jfk_lax = FlightLeg(
        ticket_price=450.0, origin_code="JFK", dest_code="LAX"
    );
    jfk +>:leg_jfk_lax:+> lax;

    leg_lax_ord = FlightLeg(
        ticket_price=320.0, origin_code="LAX", dest_code="ORD"
    );
    lax +>:leg_lax_ord:+> ord;

    leg_ord_bos = FlightLeg(
        ticket_price=580.0, origin_code="ORD", dest_code="BOS"
    );
    ord +>:leg_ord_bos:+> bos;

    leg_bos_jfk = FlightLeg(
        ticket_price=275.0, origin_code="BOS", dest_code="JFK"
    );
    bos +>:leg_bos_jfk:+> jfk;

    leg_jfk_ord = FlightLeg(
        ticket_price=510.0, origin_code="JFK", dest_code="ORD"
    );
    jfk +>:leg_jfk_ord:+> ord;

    scout = Scout();
    root spawn scout;

    peak = scout.peak_fare;
    print(f"Scout peak fare: ${peak} (reported {len(scout.fare_report)} legs)");

    legs = [
        leg_jfk_lax,
        leg_lax_ord,
        leg_ord_bos,
        leg_bos_jfk,
        leg_jfk_ord,
    ];
    for leg in legs {
        share = leg.fare_fraction(peak);
        print(
            f"{leg.origin_code}->{leg.dest_code} "
            f"${leg.ticket_price} is {share:.2%} of top fare"
        );
    }
}
