```jac
"""AI routing benchmark & failure evaluation suite.

Models the core Slipwell routing/eval scenario as a graph:
test cases -> routed to providers -> produce benchmark results.
A walker walks the case graph, routes each through providers
(measuring timeout/malformed/fallback), and emits a benchmark
report. Cycle-prone dependency edges keep an explicit guard
(cycle policy is domain logic and must not be removed).
"""

node Case {
    has case_id: str = "";
    has category: str = "";
    has consented: bool = False;
    has expected_intent: str = "";
    has ambiguous: bool = False;
    has malformed: bool = False;
    has private_beta: bool = False;
}

node Provider {
    has name: str = "";
    has model: str = "";
    has prompt_version: str = "";
    has schema_version: str = "";
    has timeout_ms: int = 0;
    has cost_per_call: float = 0.0;
    has alive: bool = True;
}

node Result {
    has case_id: str = "";
    has provider_name: str = "";
    has type_correct: bool = False;
    has field_valid: bool = False;
    has date_exact: bool = False;
    has entity_linked: bool = False;
    has safe_review: bool = False;
    has false_update: bool = False;
    has fallback_used: bool = False;
    has failed: bool = False;
    has latency_ms: int = 0;
    has cost: float = 0.0;
}

edge Requires { }
edge Routed { }
edge Fallback { }
edge DependsOn { }

walker Auditor {
    has findings: dict[str, dict] = {};
    has guard: list[str] = [];

    can start with Root entry {
        visit [->:Requires:->];
    }

    can audit with Case entry {
        if here.case_id in self.guard {
            return;
        }
        self.guard.append(here.case_id);

        if not here.consented {
            self.findings[here.case_id] = {"status": "REJECTED_UNCONSENTED"};
            return;
        }
        if here.private_beta {
            self.findings[here.case_id] = {"status": "REJECTED_PRIVATE_BETA"};
            return;
        }

        visit [here->:DependsOn:->];
    }

    can synthesize with Result entry {
        self.findings[here.case_id] = {
            "provider": here.provider_name,
            "type_correct": here.type_correct,
            "field_valid": here.field_valid,
            "date_exact": here.date_exact,
            "entity_linked": here.entity_linked,
            "safe_review": here.safe_review,
            "false_update": here.false_update,
            "fallback_used": here.fallback_used,
            "failed": here.failed,
            "latency_ms": here.latency_ms,
            "cost": here.cost,
        };
    }

    def route_case(c: Case, primary: Provider, fallback: Provider) -> None {
        type_ok = not c.ambiguous;
        field_ok = not c.malformed;
        date_ok = not c.ambiguous;
        link_ok = not c.ambiguous;
        safe = c.category == "people" or c.category == "retainer";
        failed = False;
        used_fallback = False;
        provider_name = primary.name;

        timed_out = c.malformed and primary.alive;
        malformed_out = c.malformed;

        if timed_out or malformed_out {
            if fallback.alive {
                provider_name = fallback.name;
                used_fallback = True;
                failed = False;
                field_ok = True;
            } else {
                failed = True;
                field_ok = False;
            }
        }

        result = Result(
            case_id=c.case_id,
            provider_name=provider_name,
            type_correct=type_ok,
            field_valid=field_ok,
            date_exact=date_ok,
            entity_linked=link_ok,
            safe_review=safe,
            false_update=False,
            fallback_used=used_fallback,
            failed=failed,
            latency_ms=primary.timeout_ms if not used_fallback else fallback.timeout_ms,
            cost=primary.cost_per_call if not used_fallback else fallback.cost_per_call,
        );
        c +>:Routed:+> result;
    }
}

with entry {
    p_primary = Provider(
        name="openai", model="gpt-4", prompt_version="v3",
        schema_version="s2", timeout_ms=800, cost_per_call=0.03,
    );
    p_fallback = Provider(
        name="anthropic", model="claude-3", prompt_version="v3",
        schema_version="s2", timeout_ms=1200, cost_per_call=0.025,
    );
    root ++> p_primary ++> p_fallback;

    c1 = Case(
        case_id="C-001", category="ambiguity", consented=True,
        expected_intent="reschedule", ambiguous=True,
    );
    c2 = Case(
        case_id="C-002", category="malformed", consented=True,
        expected_intent="cancel", malformed=True,
    );
    c3 = Case(
        case_id="C-003", category="people", consented=True,
        expected_intent="lookup",
    );
    c4 = Case(
        case_id="C-004", category="private-beta", consented=False,
        expected_intent="retainer", private_beta=True,
    );
    c5 = Case(
        case_id="C-005", category="negation", consented=True,
        expected_intent="do_not_cancel",
    );

    root ++> c1 ++> c2 ++> c3 ++> c4 ++> c5;

    c1 +>:Requires:+> p_primary;
    c2 +>:Requires:+> p_primary;
    c3 +>:Requires:+> p_primary;
    c5 +>:Requires:+> p_primary;

    p_primary +>:Fallback:+> p_fallback;

    c2 +>:DependsOn:+> c1;
    c1 +>:DependsOn:+> c2;

    helper = Auditor();
    helper.route_case(c1, p_primary, p_fallback);
    helper.route_case(c2, p_primary, p_fallback);
    helper.route_case(c3, p_primary, p_fallback);
    helper.route_case(c5, p_primary, p_fallback);

    auditor = Auditor();
    root spawn auditor;

    print("Benchmark findings:");
    for cid in auditor.findings.keys() {
        row = auditor.findings[cid];
        print(f"  {cid}: {row}");
    }
}
