"""Pet-or-Person social graph: walker recommends only adult human friends, filtering out pet profiles and minors."""

node Profile {
    has name: str = "";
    has species: str = "human";   # "human" or "pet"
    has age: int = 30;
}

edge Friend {
    has strength: int = 1;
}

walker Recommender {
    has raw_seen: int = 0;
    has kept: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can recommend with Profile entry {
        # From each person, look at their raw friend neighbours
        for nbr in [->:Friend:->] {
            self.raw_seen += 1;
        }
        # Now filter: only adult humans survive
        for nbr in [->:Friend:->] {
            if nbr.species == "human" and nbr.age >= 18 {
                self.kept += 1;
            }
        }
        print(f"{here.name} -> raw neighbours={self.raw_seen}, adult-human suggestions={self.kept}");
        visit [-->];
    }
}

with entry {
    alice = Profile(name="Alice", species="human", age=34);
    bob   = Profile(name="Bob",   species="human", age=29);
    teen  = Profile(name="Cara",  species="human", age=16);  # minor: filtered out
    rex   = Profile(name="Rex",   species="pet",   age=7);   # pet: filtered out
    luna  = Profile(name="Luna",  species="pet",   age=3);   # pet: filtered out
    dana  = Profile(name="Dana",  species="human", age=42);

    # Build the graph: Alice & Dana are the seeds; each is linked to a mix of friends
    root ++> alice;
    root ++> dana;

    alice +>:Friend:+> bob;
    alice +>:Friend:+> teen;
    alice +>:Friend:+> rex;

    dana  +>:Friend:+> bob;
    dana  +>:Friend:+> luna;
    dana  +>:Friend:+> alice;

    root spawn Recommender();
}
