```jac
"""Termination-measure demo: lexicographic walk-list traversal over a sort
work-list, modeled after obligation 10 of the evm-asm proof obligations.

The hand-rolled machinery we replace: a work-list loop ``.Lbalsort_pop`` that
needs a lexicographic termination measure (work-list length, then in-run
position). We model it as a walker that drains a ``WorkList`` of ``Run``s,
visiting ``Digit`` nodes along each run. The walker carries the decreasing
measures on typed ``has`` fields and accumulates drained items for the
single exit ``report``.

Two routines recurse on each other through a typed ``Spans`` edge (modeled
after obligation 3's ``rlp_walk_next_shared -> rlp_validate_payload`` cycle):
``Validator`` walks the shared payload, delegates to a ``Nested`` validator,
and the nested validator can return to the outer via the ``Spans`` edge.
Walker abilities carry an explicit guard set (jac 0.36 has no built-in
once-per-node visitation) so cycles terminate.
"""

# --- domain entities ------------------------------------------------------

node Digit {
    has value: int = 0;
    has label: str = "";
}

node Run {
    has run_id: str = "";
    has key: str = "";
}

node WorkList {
    has name: str = "main";
    has remaining: int = 0;
}

# --- edge archetypes ------------------------------------------------------

edge Carries {
    has order: int = 0;
}

edge Spans {
    has span: int = 0;
}

edge NextRun {
    # no payload — empty edge body is the idiomatic choice
}

# --- walker: lexicographic drainer over a sort work-list ------------------
#
# measure(self) = (remaining_runs, in_run_position)
# Termination: remaining strictly decreases each run drained;
#              in-run position strictly decreases each Digit visited.

walker BalsortPop {
    has drained_digits: list[str] = [];
    has drained_runs: list[str] = [];
    has visited: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can begin_drain with WorkList entry {
        print(f"draining worklist {here.name} ({here.remaining} runs)");
        visit [-->];
    }

    can open_run with Run entry {
        if here.run_id in self.visited {
            disengage;
        }
        self.visited.add(here.run_id);
        self.drained_runs.append(here.run_id);
        print(f"  open run {here.run_id} (key={here.key})");
        visit [-->];
    }

    can take_digit with Digit entry {
        if here.label in self.visited {
            disengage;
        }
        self.visited.add(here.label);
        self.drained_digits.append(f"{here.label}={here.value}");
        print(f"    digit {here.label}={here.value}");
        visit [-->];
    }

    # explicit cycle guard: Spans edges form a 2-routine mutual recursion
    # (validate_payload -> nested validate -> Spans -> validate_payload).
    # jac 0.36 has no built-in dedupe; we keep a visited set.
    can validate_spans with Digit entry {
        if here.label in self.visited {
            print(f"    cycle guard: revisiting {here.label}, stopping");
            disengage;
        }
        print(f"    validating span over {here.label}");
    }
}

# --- walker: cascade invalidation along Spans edges -----------------------
#
# Models the obligation-3 mutual recursion: validating a payload invalidates
# any cached nested results reachable through ``Spans``.

walker SpanInvalidator {
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can fan_out with Digit entry {
        self.invalidated.append(here.label);
        print(f"invalidate {here.label}");
        visit [-->];
    }
}

# --- demonstration wiring -------------------------------------------------

with entry {
    # build a sort-shaped chain: root -> WorkList -> Run -> Digit...
    wl = WorkList(name="balsort", remaining=3);
    root ++> wl;

    run_a = Run(run_id="R1", key="alpha");
    run_b = Run(run_id="R2", key="beta");
    run_c = Run(run_id="R3", key="gamma");
    wl ++> run_a ++> run_b ++> run_c;

    d1 = Digit(value=7, label="d1");
    d2 = Digit(value=3, label="d2");
    d3 = Digit(value=9, label="d3");
    d4 = Digit(value=1, label="d4");
    d5 = Digit(value=5, label="d5");
    d6 = Digit(value=8, label="d6");

    run_a +>:Carries(order=0):+> d1;
    run_a +>:Carries(order=1):+> d2;
    run_a +>:Carries(order=2):+> d3;
    run_b +>:Carries(order=0):+> d4;
    run_b +>:Carries(order=1):+> d5;
    run_c +>:Carries(order=0):+> d6;

    # a Spans cycle modeling the obligation-3 mutual recursion:
    # validate(d1) -> spans into nested(d2) -> spans back to validate(d3)
    d1 +>:Spans(span=4):+> d2;
    d2 +>:Spans(span=2):+> d3;
    # and a return edge forming the 2-routine cycle
    d3 +>:Spans(span=1):+> d1;

    # a clean NextRun edge for the third run
    run_c +>:NextRun:+> d6;

    print("=== BalsortPop: lexicographic drain ===");
    root spawn BalsortPop();

    print("");
    print("=== SpanInvalidator: cascade through Spans ===");
    inv = SpanInvalidator();
    root spawn inv;
    print(f"invalidated order: {inv.invalidated}");
}
```

