"""Test annex for the hosted review workflow status mismatch demo."""

import io;
import from contextlib { redirect_stdout }

# --- helpers --------------------------------------------------------------

def run_auditor() -> tuple {
    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    return (auditor, buf.getvalue());
}

# --- 1. Pre-fix workflow emits "timeout" -> walker must flag MISMATCH -----
test "pre-fix payload status must be flagged as MISMATCH" {
    broken_wf = Workflow(name="herd-review (pre-fix)");
    bad_result = ResultFile(
        payload='{"status":"timeout","summary":"Herd Review timed out after 900s"}'
    );
    bad_report = ReportStep(
        allow_list="approved|changes_requested|failed|timeout|unparseable"
    );
    broken_wf +>:Emits(at="workflow_step"):+> bad_result;
    broken_wf +>:Emits(at="workflow_step"):+> bad_report;
    bad_result +>:ParsedBy(at="controlplane"):+> bad_report;
    root ++> broken_wf;

    (auditor, out) = run_auditor();

    # The naive extractor must read the literal "timeout" string out of the
    # payload, which the walker should label as a MISMATCH.
    assert "status=timeout [MISMATCH]" in out, f"expected mismatch verdict, got: {out}";
    matching_findings = [f for f in auditor.findings if "-> timeout" in f and "MISMATCH" in f];
    assert len(matching_findings) == 1, f"expected exactly one timeout-mismatch finding, got {auditor.findings}";
}

# --- 2. Post-fix workflow emits "timed_out" -> walker must accept it ------
test "post-fix payload status must be accepted as canonical timed_out" {
    fixed_wf = Workflow(name="herd-review (post-fix)");
    good_result = ResultFile(
        payload='{"status":"timed_out","summary":"Herd Review timed out after 900s"}'
    );
    good_report = ReportStep(
        allow_list="approved|changes_requested|failed|timed_out|unparseable"
    );
    fixed_wf +>:Emits(at="workflow_step"):+> good_result;
    fixed_wf +>:Emits(at="workflow_step"):+> good_report;
    good_result +>:ParsedBy(at="controlplane"):+> good_report;
    root ++> fixed_wf;

    (auditor, out) = run_auditor();

    assert "status=timed_out [ok]" in out, f"expected canonical ok verdict, got: {out}";
    matching_findings = [f for f in auditor.findings if "-> timed_out" in f and "ok)" in f and "MISMATCH" not in f];
    assert len(matching_findings) == 1, f"expected exactly one timed_out-ok finding, got {auditor.findings}";
}

# --- 3. Report step allow-list must require timed_out and reject timeout -
test "allow-list must include timed_out to satisfy the report-step contract" {
    # Acceptable allow-list: contains "timed_out" as a distinct token. The
    # acceptance rule is "timed_out present" so a list that only has the
    # old "timeout" token fails the contract.
    good_report = ReportStep(
        allow_list="approved|changes_requested|failed|timed_out|unparseable"
    );
    assert "timed_out" in good_report.allow_list, "allow-list must mention timed_out";

    bad_report = ReportStep(
        allow_list="approved|changes_requested|failed|timeout|unparseable"
    );
    assert "timed_out" not in bad_report.allow_list, "old allow-list must not pass";
}

# --- 4. Graph shape: each workflow emits one result file and one report ---
test "each workflow emits exactly one ResultFile and one ReportStep via Emits" {
    wf = Workflow(name="herd-review (shape)");
    r = ResultFile(payload='{"status":"timed_out"}');
