"""Tests for the mutual friendship / buddy edge program."""

import io;
import from contextlib { redirect_stdout }

test "alice greeter reaches bob via forward buddy edge" {
    alice = House(name="Alice");
    bob = House(name="Bob");
    alice +>:Buddy(since=2021):+> bob;
    bob +>:Buddy(since=2021):+> alice;
    root ++> alice ++> bob;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        g_alice = Greeter(house_name="Alice", target="Bob");
        res = alice spawn g_alice;
    }
    out = buf.getvalue();

    assert res.reached, f"Alice greeter should have reached Bob, log={res.log}";
    assert "Bob" in [r.name for r in res.reports] or res.reached, f"greeter did not actually reach Bob: {out}";
    assert "[Alice] reached buddy Bob" in out, f"missing reach marker: {out}";
    assert "no fresh buddy edge" not in out, f"Alice's greeter bailed early: {out}";
}

test "bob greeter reaches alice via forward buddy edge" {
    alice = House(name="Alice");
    bob = House(name="Bob");
    alice +>:Buddy(since=2021):+> bob;
    bob +>:Buddy(since=2021):+> alice;
    root ++> alice ++> bob;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        g_bob = Greeter(house_name="Bob", target="Alice");
        res = bob spawn g_bob;
    }
    out = buf.getvalue();

    assert res.reached, f"Bob greeter should have reached Alice, log={res.log}";
    assert "[Bob] reached buddy Alice" in out, f"missing reach marker: {out}";
    assert "no fresh buddy edge" not in out, f"Bob's greeter bailed early: {out}";
}

test "bidirectional buddy edge exists in both directions" {
    alice = House(name="Alice");
    bob = House(name="Bob");
    alice +>:Buddy(since=2021):+> bob;
    bob +>:Buddy(since=2021):+> alice;
    root ++> alice ++> bob;

    # Forward direction: Alice -> Bob
    fwd = [alice ->:Buddy:->];
    assert len(fwd) == 1 and fwd[0].name == "Bob", f"expected forward buddy Alice->Bob, got {fwd}";

    # Reverse direction: Bob -> Alice
    rev = [bob ->:Buddy:->];
    assert len(rev) == 1 and rev[0].name == "Alice", f"expected reverse buddy Bob->Alice, got {rev}";

    # No self-loop on either side
    assert len([alice ->:Buddy:-> alice]) == 0, "Alice should not have a self buddy edge";
    assert len([bob ->:Buddy:-> bob]) == 0, "Bob should not have a self buddy edge";
}

test "greeter does not oscillate when target is missing" {
    # Alice has no outgoing buddy edge, so the greeter must disengage
    # without reaching its target. This proves the visited-set guard
    # prevents infinite bouncing once no fresh forward edge exists.
    alice = House(name="Alice");
    root ++> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        g = Greeter(house_name="Alice", target="Bob");
        res = alice spawn g;
    }
    out = buf.getvalue();

    assert not res.reached, f"greeter should not reach missing target, log={res.log}";
    assert "no fresh buddy edge" in out, f"expected disengage message, got: {out}";
}

