"""License audit: walk the dependency graph, classify each package's license,
flag anything that is not on the allowlist or missing entirely. Models the
core scenario from issue #243 — transitive license auditing without relying
on Dependabot's version-only surface.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has flagged: bool = False;
}

node LicensePolicy {
    has project_license: str = "MIT";
    has allowlist: list[str] = [];
}

edge DependsOn {
    has depth: int = 0;
}

edge DeclaredBy { }

walker LicenseAuditor {
    has seen: list[str] = [];
    has report: list[dict] = [];
    has project_license: str = "MIT";
    has allow: list[str] = [];

    can begin with Root entry {
        print(f"Auditing project license: {self.project_license}");
        visit [-->];
    }

    can collect with LicensePolicy entry {
        self.project_license = here.project_license;
        self.allow = here.allowlist;
        visit [-->];
    }

    can audit with Package entry {
        if here.name in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.name);

        verdict = "OK";
        reason = "allowlisted";
        if here.license == "" {
            verdict = "FAIL";
            reason = "unknown license";
        } elif here.license not in self.allow {
            verdict = "FAIL";
            reason = f"incompatible ({here.license})";
        }

        if verdict == "FAIL" {
            here.flagged = True;
        }

        entry = {
            "package": here.name,
            "version": here.version,
            "license": here.license if here.license else "<missing>",
            "verdict": verdict,
            "reason": reason,
        };
        self.report.append(entry);
        license_label = here.license if here.license else "<missing>";
        print(f"[{verdict}] {here.name} {here.version} :: {license_label} ({reason})");

        visit [-->];
    }
}

with entry {
    policy = LicensePolicy(
        project_license="MIT",
        allowlist=["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"],
    );

    a = Package(name="IAsyncEnumerable-Extensions", version="1.0.0", license="MIT");
    b = Package(name="Newtonsoft.Json", version="13.0.3", license="MIT");
    c = Package(name="Serilog", version="3.1.0", license="Apache-2.0");
    d = Package(name="Confluent.Kafka", version="2.3.0", license="Apache-2.0");
