    g = Package(name="Ghost-Pkg", version="0.0.1", license="");
    h = Package(name="AGPL-Utility", version="1.2.0", license="AGPL-3.0");

    root ++> policy ++> a;

    a +>:DependsOn(depth=1):+> b;
    a +>:DependsOn(depth=1):+> c;
    a +>:DependsOn(depth=1):+> f;
    a +>:DependsOn(depth=1):+> g;

    c +>:DependsOn(depth=2):+> d;
    d +>:DependsOn(depth=3):+> e;
    d +>:DependsOn(depth=3):+> h;

    policy +>:DeclaredBy:+> a;

    auditor = LicenseAuditor();
    root spawn auditor;

    print("\n=== AUDIT SUMMARY ===");
    fails = 0;
    for entry in auditor.report {
        marker = "  " if entry["verdict"] == "OK" else "!!";
        if entry["verdict"] == "FAIL" {
            fails = fails + 1;
        }
        print(f"{marker} {entry['package']:30s} {entry['license']:20s} {entry['reason']}");
    }
    print(f"\n{fails} package(s) need reviewer approval before release.");
}
