"""Migration tracker: nine service nodes ordered by dependency, walked in
phase sequence with cycle-safe traversal and reachability reporting."""

node Service {
    has name: str = "";
    has issue: str = "";
    has migrated: bool = False;
    has critical: bool = False;
}

node DatabaseTime {
    has name: str = "";
    has issue: str = "";
    has migrated: bool = False;
}

node Prerequisite {
    has title: str = "";
    has issue: str = "";
    has blocking: bool = True;
}

edge DependsOn { has weight: int = 1; }
edge Blocks { has severity: int = 1; }

walker MigrationPlanner {
    has visited: list[str] = [];
    has order: list[str] = [];
    has pending: list[str] = [];

    can start with Root entry {
        print("=== Migration Planner: phase 0 -> phase 4 ===");
        visit [->:DependsOn:->];
    }

    can plan with Service | DatabaseTime entry {
        label = here.name if here.name else "(unnamed)";
        if label in self.visited {
            disengage;
        }
        self.visited.append(label);
        if not here.migrated {
            self.order.append(label);
            print(f"  -> migrate {label} ({here.issue})");
        } else {
            print(f"  skip {label} (already migrated)");
        }
        visit [->:DependsOn:->];
    }

    can audit with Prerequisite entry {
        status = "BLOCKING" if here.blocking else "optional";
        print(f"[{status}] {here.title} ({here.issue})");
        if here.blocking {
            self.pending.append(here.issue);
        }
        visit [->:Blocks:->];
    }

    can finish with Root entry {
        print("--- planned order ---");
        for (i, name) in enumerate(self.order) {
            print(f"  {i + 1}. {name}");
        }
        if self.pending {
            print("--- unresolved prerequisites ---");
            for issue in self.pending {
                print(f"  ! {issue}");
            }
        } else {
            print("no unresolved prerequisites");
        }
    }
}

