Write a Jac test annex (`main.test.jac`) for the program below. Use `test "..." { }` blocks that exercise its public behavior. Return the complete file.

```jac
"""Recursive CTE: model WITH RECURSIVE as a walker that iterates a
working-table over a typed `Produces` edge until a depth guard or cycle
detection disengages. The walker simulates PostgreSQL's recursive
union: seed rows, then repeatedly derive new rows from prior ones."""

# A single row in the CTE working table. `n` is the column the query
# computes on; `depth` tracks the iteration index for safety bounds.
node Row {
    has n: int = 0;
    has depth: int = 0;
}

# The recursive derivation: a row points to the rows it produced on the
# next iteration. Typed edge because the parent/child link is the whole
# point of the working table.
edge Produces { has limit_n: int = 100; }

# The CTE binding `t(n)`. Owns the schema/depth cap; the recursive
# walker is spawned onto it to begin iteration.
node CTE {
    has name: str = "t";
    has max_depth: int = 100;
}

walker Iter {
    # Tracks rows already emitted so the walker doesn't loop forever on
    # a recursive query that never terminates (jac 0.36.1 has no
    # built-in visited-set, so the policy is explicit domain logic).
    has seen: list[int] = [];

    can start with Root entry {
        # Seed: VALUES (1). Build the first row and step into it.
        seed = Row(n=1, depth=0);
        root ++> seed;
        visit [-->];
    }

    can enter_cte with CTE entry {
        # Mirror the WHERE n < 100 stop condition via the typed edge's
        # `limit_n` payload. Cap the iteration by depth as well.
        if here.max_depth <= 0 {
            disengage;
        }
        visit [-->];
    }

    can step with Row entry {
        d = here.depth;
        # Domain rule from the issue: stop when the WHERE clause no
        # longer holds. PostgreSQL emits n+1 until n < 100 fails.
        if here.n >= 100 {
            disengage;
        }
        # Record this row's value so duplicate derivation terminates.
        self.seen.append(here.n);
        # Produce the next row: n+1, just like SELECT n+1 FROM t.
        nxt_n = here.n + 1;
        if nxt_n in self.seen {
            # Cycle detected by value: stop cleanly.
            disengage;
        }
        child = Row(n=nxt_n, depth=d + 1);
        here +>:Produces(limit_n=100):+> child;
        # Continue the recursive union into the new row.
        visit [->:Produces:->];
    }
}

walker SumResult {
    # Accumulates the running total as it walks the finished working
    # table. A single exit report keeps the contract tidy.
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can collect with Row entry {
        self.total += here.n;
        visit [-->];
    }

    can finish with Root exit {
        print(f"sum(n) = {self.total}");
    }
}

with entry {
    cte = CTE(name="t", max_depth=100);
    root ++> cte;

    Iter() spawn root;
    SumResult() spawn root;
}
```

