"""Configurable composer process timeout modeled as graph traversal.

The issue: every shell command ran with a hard-coded 300s timeout, and
composer invocations could not extend it. The fix surfaces
``composerTimeout`` from a YAML-style config and propagates it to both
the Symfony Process timeout and the ``COMPOSER_PROCESS_TIMEOUT`` env
var, while leaving non-composer commands at the legacy 300s default.

In idiomatic Jac we drop the hand-rolled key/value plumbing and model
the up call graph natively: Config -> Project -> (ComposerCommand |
ShellCommand). A walker audits every command node and reports which
timeout was applied, mimicking what the upstream fix must guarantee.
"""

node Config {
    has composer_timeout: int = 300;
    has default_timeout: int = 300;
}

node Project {
    has name: str = "";
}

edge OwnsProject {
    has since: str = "";
}

node Command {
    has label: str = "";
    has is_composer: bool = False;
    has explicit_shell_timeout: bool = False;
    has env_composer_timeout: int = 0;
    has applied_timeout: int = 0;
}

edge RunsCommand {
    has order: int = 0;
}

walker AuditTimeouts {
    has report: list = [];

    can start with Root entry {
        visit [->:OwnsProject:->];
    }

    can enter_project with Project entry {
        visit [->:RunsCommand:->];
    }

    can inspect with Command entry {
        picked = here.env_composer_timeout;
        if here.explicit_shell_timeout {
            picked = here.applied_timeout;
        } elif here.is_composer {
            picked = here.env_composer_timeout;
        } else {
            picked = 300;
        }
        here.applied_timeout = picked;
        self.report.append(f"{here.label}: timeout={picked}s");
        visit [-->];
    }
}

with entry {
    cfg = Config(composer_timeout=1800, default_timeout=300);
    p = Project(name="drupal-updater");
    root +>:OwnsProject(since="2024"):+> cfg;
    root +>:OwnsProject(since="2024"):+> p;

    c1 = Command(label="composer install", is_composer=True,
                 env_composer_timeout=1800);
    c2 = Command(label="composer why -r", is_composer=True,
                 env_composer_timeout=1800);
    c3 = Command(label="timeout 2 composer outdated",
                 is_composer=True, explicit_shell_timeout=True,
                 applied_timeout=2, env_composer_timeout=1800);
    c4 = Command(label="git status", is_composer=False);
    c5 = Command(label="drush status", is_composer=False);

    p +>:RunsCommand(order=1):+> c1;
    p +>:RunsCommand(order=2):+> c2;
    p +>:RunsCommand(order=3):+> c3;
    p +>:RunsCommand(order=4):+> c4;
    p +>:RunsCommand(order=5):+> c5;

    auditor = AuditTimeouts();
    root spawn auditor;

    print("Audit results:");
    for line in auditor.report {
        print(f"  - {line}");
    }
    print(f"composer_timeout from config: {cfg.composer_timeout}s");
}
