```jac
"""Pipeline resume integrity check: model stage dependency, manifest membership,
and cascade-invalidation on stale recorded outputs.

Models the resume-path issue: skipping a stage solely because the manifest says
it completed, without verifying that its recorded outputs still match the
recomputed input hash, lets a corrupted (or truncated / replaced) artifact
silently flow downstream. The fix mirrors `--skip-existing` semantics: every
completed stage is re-hashed and re-verified, and on the first mismatch the
offending stage AND every downstream dependent stage are invalidated.
"""

node Stage {
    has name: str = "";
    has input_hash: str = "";
    has recorded_hash: str = "";
    has outputs_intact: bool = True;
}

node Manifest {
    has run_id: str = "";
}

edge StageLink {}

walker IntegrityAudit {
    has invalidations: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can audit_run with Manifest entry {
        print(f"Resuming run {here.run_id}: re-verifying every completed stage");
        visit [->:StageLink:->];
    }

    can verify_stage with Stage entry {
        mismatch = here.input_hash != here.recorded_hash;
        stale = not here.outputs_intact;
        if mismatch or stale {
            print(f"  [CORRUPT] {here.name} -- input_hash={here.input_hash}, "
                  f"recorded_hash={here.recorded_hash}, intact={here.outputs_intact}");
            self.invalidations.append(here.name);
        } else {
            print(f"  [OK]      {here.name}");
        }
        visit [->:StageLink:->];
    }

    can cascade_invalidate with Stage entry {
        if self.invalidations and here.name not in self.invalidations {
            print(f"  [CASCADE] {here.name} -- downstream of invalidated "
                  f"{self.invalidations[0]}, rerun or abort");
            self.invalidations.append(here.name);
            visit [->:StageLink:->];
        } else {
            visit [->:StageLink:->] else { disengage; }
        }
    }

    def final_report -> str {
        if not self.invalidations {
            return "All stages verified -- resume may proceed.";
        }
        invalid_list = ", ".join(self.invalidations);
        return f"INTEGRITY ERROR: invalidated stages [{invalid_list}] -- rerun or abort.";
    }
}

with entry {
    root ++> Manifest(run_id="run-2024-11-08");

    # features: intact, hashes match -- would normally be skipped on resume.
    features = Stage(
        name="features",
        input_hash="h_feat_in",
        recorded_hash="h_feat_in",
        outputs_intact=True
    );
    # train: pre-existing manifest entry, but the recorded hash no longer
    # matches the recomputed input hash (someone replaced the parquet).
    train = Stage(
        name="train",
        input_hash="h_train_in_new",
        recorded_hash="h_train_in_old",
        outputs_intact=True
    );
    # eval: depends on train -- if train is invalidated, eval must be too.
    eval_stage = Stage(
        name="eval",
        input_hash="h_eval_in",
        recorded_hash="h_eval_in",
        outputs_intact=True
    );

    root +>:StageLink:+> features +>:StageLink:+> train +>:StageLink:+> eval_stage;

    auditor = IntegrityAudit();
    root spawn auditor;
    print(auditor.final_report());
}
