gates the Release; the Release opens the Post-release review.

A walker walks the dependency graph, classifying each node by its
admission category (pilot evidence, deterministic bug, setup blocker,
perf regression, compat defect, privacy/security defect) and asserting
that the hard gate (#453 Release Gate) is reachable only when every
upstream node is GO.
"""

node EpicNode {
    has title: str = "";
    has ticket: str = "";
    has status: str = "PENDING";   # PENDING | GO | BLOCKED
    has category: str = "PILOT";   # PILOT | CALIBRATION | HARDENING | STRATEGY | RELEASE
}

edge DependsOn {
    has rationale: str = "";
}

walker EpicAuditor {
    has visited: list[str] = [];
    has blocked: list[str] = [];
    has go_count: int = 0;
    has blocked_count: int = 0;
    has release_unlocked: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with EpicNode entry {
        key = here.ticket;
        # Cycle safety: re-entry is a defect, mark BLOCKED and stop.
        if key in self.visited {
            here.status = "BLOCKED";
            self.blocked.append(key);
            self.blocked_count += 1;
            print(f"[CYCLE] {key} re-entered -> BLOCKED");
            disengage;
        }
        self.visited.append(key);

        # Domain rule: every upstream must already be GO before this node is GO.
        upstreams = [->:DependsOn:->];
        ready = True;
        for up in upstreams {
            if up.status != "GO" {
                ready = False;
            }
        }

        if ready {
            here.status = "GO";
            self.go_count += 1;
            print(f"[GO]   {here.ticket:>4} {here.title}  ({here.category})");
        } else {
            here.status = "BLOCKED";
            self.blocked.append(here.ticket);
            self.blocked_count += 1;
            print(f"[WAIT] {here.ticket:>4} {here.title}  ({here.category})  waiting on upstreams");
        }

        # Release gate special handling.
        if here.ticket == "#453" and here.status == "GO" {
            self.release_unlocked = True;
        }

        # Forward traverse dependents; dead-end handling prevents hang.
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    # Measurement / Pilot layer.
    protocol = EpicNode(title="Pilot Measurement Protocol", ticket="#445", category="PILOT");
    standard = EpicNode(title="Standard NestJS Pilot", ticket="#446", category="PILOT");
    complex  = EpicNode(title="Complex / Monorepo Pilot", ticket="#447", category="PILOT");
    large    = EpicNode(title="Large / OSS Pilot", ticket="#448", category="PILOT");

    # Calibration / Hardening layer (fed by all three pilots).
    calibration = EpicNode(title="Finding Quality Calibration", ticket="#449", category="CALIBRATION");
    dx_hardening = EpicNode(title="Onboarding / DX Hardening", ticket="#450", category="HARDENING");
    perf_hardening = EpicNode(title="Perf / Compat Hardening", ticket="#451", category="HARDENING");

    # Strategy / Release layer.
    go_no_go  = EpicNode(title="Runtime Evidence Go/No-Go", ticket="#452", category="STRATEGY");
    release   = EpicNode(title="v1.6.1 Release Gate", ticket="#453", category="RELEASE");
    post_rel  = EpicNode(title="Post-release / Next-phase Review", ticket="#454", category="STRATEGY");

    # Wire the dependency graph with typed DependsOn edges carrying
    # rationale payloads (mirrors the mermaid flowchart in the issue).
    protocol +>:DependsOn(rationale="protocol feeds every pilot"):+> standard;
    protocol +>:DependsOn(rationale="protocol feeds every pilot"):+> complex;
    protocol +>:DependsOn(rationale="protocol feeds every pilot"):+> large;

    standard +>:DependsOn(rationale="pilot -> calibration"):+> calibration;
    complex  +>:DependsOn(rationale="pilot -> calibration"):+> calibration;
    large    +>:DependsOn(rationale="pilot -> calibration"):+> calibration;

    standard +>:DependsOn(rationale="pilot -> dx hardening"):+> dx_hardening;
    complex  +>:DependsOn(rationale="pilot -> dx hardening"):+> dx_hardening;
    large    +>:DependsOn(rationale="pilot -> dx hardening"):+> dx_hardening;

    standard +>:DependsOn(rationale="pilot -> perf hardening"):+> perf_hardening;
    complex  +>:DependsOn(rationale="pilot -> perf hardening"):+> perf_hardening;
    large    +>:DependsOn(rationale="pilot -> perf hardening"):+> perf_hardening;

    calibration   +>:DependsOn(rationale="calibration -> go/no-go"):+> go_no_go;
    dx_hardening  +>:DependsOn(rationale="dx hardening -> go/no-go"):+> go_no_go;
    perf_hardening +>:DependsOn(rationale="perf hardening -> go/no-go"):+> go_no_go;

    go_no_go +>:DependsOn(rationale="decision gates release"):+> release;
    release  +>:DependsOn(rationale="release opens post-release"):+> post_rel;

    # Attach the dependency tree under root.
    root ++> protocol;

    # Run the auditor. It will walk the DAG, propagating GO forward
    # once each upstream is satisfied, and report the release verdict.
    auditor = EpicAuditor();
    root spawn auditor;

    verdict = "GO" if auditor.release_unlocked else "BLOCKED";
    print("");
    print(f"audited {auditor.go_count} GO, {auditor.blocked_count} BLOCKED");
    print(f"release gate #453 verdict: {verdict}");
}
