    p1 +>:ContainsKey(recursive=True):+> k2;
    p2 +>:ContainsKey(recursive=True):+> k3;
    p2 +>:ContainsKey(recursive=True):+> k4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
