"""Team-color modification decoding: walk a team's modification chain,
catching a broken/empty token (the boost-test fallback path) so the
decoding walker reports a clean fallback instead of crashing.

Models the wesnoth `~TC()` image-path function: a `TeamColor` node
carries a chain of `Modifier` nodes linked by typed `Next` edges, one
of which is left empty to reproduce the CI failure mode.
"""

node Modifier {
    has token: str = "";
    has value: int = 0;
}

node TeamColor {
    has team_id: str = "";
    has fallback_used: bool = False;
}

edge Next {}

walker DecodeTC {
    has default_rgb: tuple = (128, 128, 128);

    can start with Root entry {
        visit [->:Next:->];
    }

    can read with TeamColor entry {
        visit [->:Next:->];
    }

    can decode with Modifier entry {
        # Decode the token; an empty token mimics the empty-string
        # case the boost test exercises on the failure path.
        if here.token == "" {
            # The fallback path: mark the team as having used its
            # fallback and stop walking (mirrors the early-return
            # in the C++ catch block).
            print(f"[fallback] empty token -> default {self.default_rgb}");
            disengage;
        } elif here.token == "TC" {
            print(f"[TC] team tint = {here.value}");
            visit [->:Next:->];
        } else {
            print(f"[skip] unknown token {here.token}");
            visit [->:Next:->];
        }
    }
}

with entry {
    team = TeamColor(team_id="side_1");
    m1 = Modifier(token="TC", value=255);
    m2 = Modifier(token="");  # the empty-string failure case
    m3 = Modifier(token="TC", value=64);

    root +>:Next:+> team;
    team +>:Next:+> m1;
    m1 +>:Next:+> m2;
    m2 +>:Next:+> m3;

    root spawn DecodeTC();
}
