"""Tests for the TeamColor ~TC() decoding walker — empty-token fallback path."""

import io;
import from contextlib { redirect_stdout }

test "empty token mid-chain triggers fallback and disengages" {
    rt = Root();
    team = TeamColor(team_id="side_1");
    m1 = Modifier(token="TC", value=255);
    m2 = Modifier(token="");  # the empty-string failure case
    m3 = Modifier(token="TC", value=64);

    rt +>:Next:+> team;
    team +>:Next:+> m1;
    m1 +>:Next:+> m2;
    m2 +>:Next:+> m3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn DecodeTC();
    }
    out = buf.getvalue();

    # The first TC should print, the empty token must trigger the fallback
    # marker, and the trailing TC(64) must NOT appear (walker disengages).
    assert "[TC] team tint = 255" in out, f"missing first TC: {out}";
    assert "[fallback] empty token -> default" in out, f"missing fallback: {out}";
    assert "[TC] team tint = 64" not in out, f"walker failed to disengage: {out}";
    # Graph intact — disengage does not mutate topology.
    assert len([m3 <--]) == 1, "m3 should still be linked from m2";
}

