"""Hiking trail: chain waypoints from trailhead to summit and count each stop."""

node Trailhead {
    has name: str = "Trailhead";
}

node Waypoint {
    has name: str = "";
}

node Summit {
    has name: str = "Summit";
}

walker Hiker {
    has stop: int = 0;
    has expected: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can depart with Trailhead entry {
        print(f"Trailhead: {here.name}");
        visit [-->];
    }

    can pass_waypoint with Waypoint entry {
        self.stop += 1;
        label = here.name if here.name else f"Waypoint {self.stop}";
        print(f"Stop {self.stop}: {label}");
        visit [-->];
    }

    can arrive with Summit entry {
        if self.stop >= self.expected {
            print(
                f"Summit reached — trail complete after {self.stop} waypoints"
            );
        } else {
            print(
                f"Summit reached — only {self.stop} of {self.expected} "
                f"waypoints passed"
            );
        }
        disengage;
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint(name="Creek Crossing")
        ++> Waypoint(name="Pine Ridge")
        ++> Waypoint(name="Switchback Turn")
        ++> Summit();
    root spawn Hiker(expected=3);
}
