```jac
"""Compiler-owned artifact cache with reverse-dependency invalidation.

Models the scenario from the issue: an in-memory cache admits compiler
artifact families (e.g. HIR, PIR-A, compile-interface), keys them by
complete inputs, and uses typed edges to track the reverse-dependency
graph so an interface change cascades invalidation to importers and
downstream artifacts. A walker performs the cascade walk.
"""

# --- Edge archetypes: relationships that carry meaning -------------------

# Reverse-dep link: "this artifact depends on that artifact".
# Carries the family name so we know which cache family owns the link.
edge Rdep {
    has family: str = "";
}

# Forward compile interface relationship: "module X re-exports / exposes
# the compile interface of module Y". Edits to Y's interface must
# invalidate X.
edge CompilesTo {
}

# --- Node archetypes ------------------------------------------------------

# A cached compiler artifact (HIR, PIR-A, module state, etc.).
node Artifact {
    has family: str = "";
    has key_digest: str = "";
    has schema_version: str = "";
    has profile: str = "";
    has size: int = 0;
    has valid: bool = True;
}

# A module under compilation. Holds its logical identity and the
# generation counter bumped on edits.
node Module {
    has path: str = "";
    has generation: int = 0;
    has source_digest: str = "";
}

# A compile interface (PIR-A public surface). Modules that import a
# module depend on its compile interface.
node Interface {
    has interface_id: str = "";
    has schema_version: str = "";
    has generation: int = 0;
}

# The cache service root. Bounded slot accounting + status reporting.
node CacheService {
    has capacity: int = 8;
    has stored: int = 0;
    has hits: int = 0;
    has misses: int = 0;
    has invalidations: int = 0;
}

# --- Walkers --------------------------------------------------------------

# Cascade invalidator: spawned when a source module or its interface
# changes. Walks the reverse-dependency graph, marks dependent artifacts
# stale, and reports the invalidated set.
walker CascadeInvalidator {
    has source_path: str = "";
    has touched: list[str] = [];

    can start with CacheService entry {
        print(f"[cache] cascade from source={self.source_path} "
              f"stored={here.stored} cap={here.capacity}");
        visit [->:Rdep:->];
    }

    can hit with Artifact entry {
        if here.valid {
            here.valid = False;
            here.size = 0;
            self.touched.append(here.key_digest);
            print(f"[cache] invalidate artifact family={here.family} "
                  f"key={here.key_digest}");
        }
        visit [->:Rdep:->];
    }

    can report with CacheService exit {
        print(f"[cache] invalidated {len(self.touched)} dependents; "
              f"capacity now used={here.stored}/{here.capacity}");
        report self.touched;
    }
}

# Reachability auditor: walks the forward compile-interface edges from
# each module, collects every interface and artifact reached, and
# reports counts so we can verify the graph is consistent.
walker ReachabilityAuditor {
    has visited: list[str] = [];

    can begin with CacheService entry {
        print("[audit] starting reachability walk");
        visit [-->];
    }

    can step_module with Module entry {
        self.visited.append(f"module:{here.path}");
        visit [->:CompilesTo:->];
    }

    can step_interface with Interface entry {
        self.visited.append(f"iface:{here.interface_id}@g{here.generation}");
        visit [->:Rdep:->];
    }

    can step_artifact with Artifact entry {
        self.visited.append(f"artifact:{here.family}:{here.key_digest}");
    }

    can done with CacheService exit {
        print(f"[audit] reached {len(self.visited)} nodes");
        for v in self.visited {
            print(f"  - {v}");
        }
        report self.visited;
    }
}

# --- Demo wiring ----------------------------------------------------------

with entry {
    cache = CacheService(capacity=8);

    # Three modules. m2 imports m1, m3 imports m2 -> m1.
    m1 = Module(path="src/a.pm", generation=1, source_digest="da");
    m2 = Module(path="src/b.pm", generation=1, source_digest="db");
    m3 = Module(path="src/c.pm", generation=1, source_digest="dc");

    iface_a = Interface(interface_id="A-iface", schema_version="pirA-1", generation=1);
    iface_b = Interface(interface_id="B-iface", schema_version="pirA-1", generation=1);
    iface_c = Interface(interface_id="C-iface", schema_version="pirA-1", generation=1);

    # Per-module cached artifacts keyed by (path, source_digest, profile).
    hir_a = Artifact(family="HIR", key_digest="HIR:A:da:default",
                     schema_version="hir-2", profile="default", size=128);
    pir_a = Artifact(family="PIR-A", key_digest="PIR:A:da:default",
                     schema_version="pirA-1", profile="default", size=64);
    hir_b = Artifact(family="HIR", key_digest="HIR:B:db:default",
                     schema_version="hir-2", profile="default", size=96);
    pir_b = Artifact(family="PIR-A", key_digest="PIR:B:db:default",
                     schema_version="pirA-1", profile="default", size=48);
    hir_c = Artifact(family="HIR", key_digest="HIR:C:dc:default",
                     schema_version="hir-2", profile="default", size=160);
    pir_c = Artifact(family="PIR-A", key_digest="PIR:C:dc:default",
                     schema_version="pirA-1", profile="default", size=80);

    # Wire: each module -> its interface (CompilesTo); each interface
    # -> its artifacts (Rdep); each downstream interface -> upstream
    # interface (Rdep) representing import-time dependency.
    m1 +>:CompilesTo:+> iface_a;
    m2 +>:CompilesTo:+> iface_b;
    m3 +>:CompilesTo:+> iface_c;

    iface_a +>:Rdep(family="HIR"):+> hir_a;
    iface_a +>:Rdep(family="PIR-A"):+> pir_a;
    iface_b +>:Rdep(family="HIR"):+> hir_b;
    iface_b +>:Rdep(family="PIR-A"):+> pir_b;
    iface_c +>:Rdep(family="HIR"):+> hir_c;
    iface_c +>:Rdep(family="PIR-A"):+> pir_c;

    # Import edges: c depends on b depends on a.
    iface_b +>:Rdep(family="import"):+> iface_a;
    iface_c +>:Rdep(family="import"):+> iface_b;

    cache ++> m1 ++> m2 ++> m3;
    cache ++> iface_a ++> iface_b ++> iface_c;
    cache ++> hir_a ++> hir_b ++> hir_c;
    cache ++> pir_a ++> pir_b ++> pir_c;

    cache.stored = 11;
    print("[demo] cache wired with 3 modules, 3 interfaces, 6 artifacts, "
          "capacity=8 (oversubscribed -> eviction pressure baseline)");

    # Reachability audit first.
    cache spawn ReachabilityAuditor();

    # Edit m1's source: bump generation, invalidate everything that
    # depends on its interface transitively.
    m1.generation = 2;
    m1.source_digest = "da2";
    print(f"[demo] edited source={m1.path} gen={m1.generation} "
          f"digest={m1.source_digest}");
    cache spawn CascadeInvalidator(source_path="src/a.pm");
}
```

