"""Mutual friendships in a neighborhood: houses are nodes connected by bidirectional buddy edges."""

node House {
    has name: str = "";
    has color: str = "";
}

edge Buddy {
    has since: int = 2024;
}

walker Greeter {
    has origin: str = "";
    has hops: int = 0;

    can start with House entry {
        self.hops = self.hops + 1;
        print(f"Greeter from {self.origin} arrived at {here.name} after {self.hops} hop(s)");
        if here.name != self.origin {
            print(f"  -> reached buddy {here.name} from {self.origin}!");
            disengage;
        }
        next_houses = [-->];
        visit next_houses else {
            print(f"  -> {self.origin} found no buddy");
            disengage;
        }
    }

    can land with Root entry {
        print(f"Greeter from {self.origin} ended at root with nowhere else to go");
        disengage;
    }
}

with entry {
    maple = House(name="Maple", color="red");
    oak = House(name="Oak", color="brown");
    elm = House(name="Elm", color="green");

    maple +>:Buddy(since=2010):+> oak;
    oak +>:Buddy(since=2010):+> maple;

    maple +>:Buddy(since=2015):+> elm;
    elm +>:Buddy(since=2015):+> maple;

    oak +>:Buddy(since=2018):+> elm;
    elm +>:Buddy(since=2018):+> oak;

    root ++> maple;
    root ++> oak;
    root ++> elm;

    maple spawn Greeter(origin="Maple");
    oak spawn Greeter(origin="Oak");
}
