import io;
import from contextlib { redirect_stdout }

test "typed calls form a forward reachability closure" {
    entry_node = EntryPoint(name="main_handler");
    caller = Function(name="route_request");
    target = Function(name="unsafe_eval");
    helper = Function(name="helper_function");
    dead = Function(name="dead_code");

    root ++> entry_node;
    entry_node ++> caller;
    entry_node ++> helper;
    root ++> dead;
    root +>:Call:+> caller;
    caller +>:Call:+> target;

    res = root spawn ReachabilityAnalyzer();

    assert len(res.visited) == 2, f"visited {res.visited}";
    assert caller.reachable, f"caller reachable={caller.reachable}";
    assert target.reachable, f"target reachable={target.reachable}";
    assert not helper.reachable, f"helper reachable={helper.reachable}";
    assert not dead.reachable, f"dead reachable={dead.reachable}";
}

test "unrecorded calls receive the not exploitable verdict" {
