            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(amount=100.0)
        ++> Order(amount=50.0, valid=False)
        ++> Order(amount=200.0)
        ++> Order(amount=999.0, fraud=True)
