"""Tests for OrderAuditor: skip-invalid continues, fraud halts."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: fraud halts the walk immediately ----------
test "fraud halts walk before later orders are visited" {
    root ++> Order(amount=100.0)
        ++> Order(amount=50.0, valid=False)
        ++> Order(amount=200.0)
        ++> Order(amount=999.0, fraud=True)
        ++> Order(amount=300.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # The first HALT line must be the fraud order (amount=999.0)
    halt_line = f"[HALT] fraud flagged order amount=999.0";
    assert halt_line in out, f"expected HALT line not found; got:\n{out}";

    # The amount=300.0 order appears AFTER the fraud node in the chain,
    # so it must NOT have been visited (fraud disengaged the walker first).
    assert "amount=300.0" not in out, (
        f"walker continued past fraud order; got:\n{out}"
    );
}

# ---------- Test 2: invalid order is skipped, walk continues ----------
test "invalid order skipped but walk proceeds to next valid order" {
    root ++> Order(amount=100.0)
        ++> Order(amount=50.0, valid=False)
        ++> Order(amount=200.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Beginning banner
    assert "OrderAuditor: beginning audit" in out, f"missing banner; got:\n{out}";

    # The invalid order must produce a SKIP line
    skip_line = f"[SKIP] invalid order amount=50.0";
    assert skip_line in out, f"expected SKIP line not found; got:\n{out}";

    # The following valid order (amount=200.0) must still be audited
    audit_line = f"[AUDIT] valid order amount=200.0";
    assert audit_line in out, f"walk did not continue past invalid; got:\n{out}";

    # The first valid order (amount=100.0) must also be audited
    first_audit = f"[AUDIT] valid order amount=100.0";
    assert first_audit in out, f"missing first audit; got:\n{out}";

    # No fraud in this graph -> no HALT line at all
    assert "[HALT]" not in out, f"unexpected HALT in clean graph; got:\n{out}";
}

# ---------- Test 3: fraud positioned first halts before any audit ----------
test "fraud as first order halts before any AUDIT line" {
    root ++> Order(amount=7.0, fraud=True)
        ++> Order(amount=200.0)
        ++> Order(amount=300.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Banner still printed (entry ability fires on Root before disengage)
    assert "OrderAuditor: beginning audit" in out, f"missing banner; got:\n{out}";

    # The HALT line appears
    assert "[HALT] fraud flagged order amount=7.0" in out, (
        f"missing HALT; got:\n{out}"
    );

    # No AUDIT lines should appear because the very first order is fraud
    assert "[AUDIT]" not in out, f"audit ran on fraud-first chain; got:\n{out}";
    assert "[SKIP]" not in out, f"unexpected SKIP in fraud-first chain; got:\n{out}";
}

# ---------- Test 4: multiple invalid orders, no fraud -> all skipped, walk continues ----------
test "multiple invalid orders all skipped and walk finishes" {
    root ++> Order(amount=10.0, valid=False)
        ++> Order(amount=20.0, valid=False)
        ++> Order(amount=30.0, valid=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP] invalid order amount=10.0" in out, f"missing skip 10; got:\n{out}";
    assert "[SKIP] invalid order amount=20.0" in out, f"missing skip 20; got:\n{out}";
    assert "[SKIP] invalid order amount=30.0" in out, f"missing skip 30; got:\n{out}";

    # No audit and no halt expected
    assert "[AUDIT]" not in out, f"unexpected audit; got:\n{out}";
    assert "[HALT]" not in out, f"unexpected halt; got:\n{out}";
