```jac
"""UAX decomposition: canonical span entities witness grammar/provider relations.

This demo models the core complaint of issue #98: a maintainer hand-rolled
recursive reminting of overlapping text content for UAX29/Tree-sitter providers,
encoding provider/kind/byte-range/depth/media metadata INTO the content identity
itself. The fix is structural: canonical span entities are identified solely from
their exact child content, while provider/kind/byte-range/depth/media are separate
witnessed relations. Repeated identical bytes at different offsets resolve to the
same canonical span; provider/range changes alter witness records only.

Nodes:
  Span           - canonical text entity, identified only by its child content.
  Grapheme, Word, Sentence - UAX29 unit kinds that own child spans via typed edges.
  Parser         - provider that witnesses spans it observed.
Edges:
  Children       - typed composition: a unit span's canonical children.
  Witness        - typed parser occurrence: a provider saw a span at a range/depth.
Walkers:
  CanonicalCensus  - walks Children edges, counts unique canonical spans,
                     flags any cycle (canonical span referenced by ancestor).
  WitnessAudit     - walks Witness edges from parsers to count observed occurrences.
"""

node Span {
    has text: str = "";
    has media: str = "";
}

node Grapheme {
    has kind: str = "grapheme";
}

node Word {
    has kind: str = "word";
}

node Sentence {
    has kind: str = "sentence";
}

node Parser {
    has name: str = "";
}

edge Children {
    has order: int = 0;
}

edge Witness {
    has kind: str = "";
    has byte_start: int = 0;
    has byte_end: int = 0;
    has depth: int = 0;
}

walker CanonicalCensus {
    """Walks the canonical spine, counting unique spans and detecting cycles."""

    has seen: list[str] = [];
    has unique_count: int = 0;
    has cycles: int = 0;

    can start with Root entry {
        print("Census starting at root");
        visit [-->];
    }

    can descend with Span entry {
        sig = here.text;
        if sig in self.seen {
            self.cycles = self.cycles + 1;
            print(f"  cycle detected at span text={here.text!r} media={here.media!r}");
            disengage;
        } else {
            self.seen = self.seen + [sig];
            self.unique_count = self.unique_count + 1;
            print(f"  canonical span text={here.text!r} media={here.media!r}");
            visit [->:Children:->] else { disengage; }
        }
    }

    can step with Grapheme | Word | Sentence entry {
        # Unit nodes are witnesses over spans — step through their Children.
        visit [->:Children:->] else { disengage; }
    }
}

walker WitnessAudit {
    """Walks Witness edges from parsers to count observed occurrences."""

    has observations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can record with Parser entry {
        witnesses = [->:Witness:->];
        for w in witnesses {
            label = f"{here.name}/{w.kind}@{w.byte_start}-{w.byte_end}/d{w.depth}";
            self.observations = self.observations + [label];
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Shared canonical atoms — same bytes, different media (NFC vs NFD).
    a = Span(text="a", media="NFC");
    a_nfd = Span(text="a", media="NFD");
    exclamation = Span(text="!");
    hello = Span(text="hello");
    world = Span(text="world");
    greeting = Span(text="hello world");
    punctuation = Span(text="!");

    # UAX29 unit nodes — these witness, not own, the bytes.
    g1 = Grapheme();
    g2 = Grapheme();
    w1 = Word();
    s1 = Sentence();

    # Tree-sitter provider witness over the same span at a different offset.
    ts = Parser(name="tree-sitter");
    pcre = Parser(name="pcre");

    # Composition: graphemes hold children, words hold graphemes, sentences hold words.
    g1 +>:Children(order=0):+> a;
    g1 +>:Children(order=1):+> a_nfd;
    g2 +>:Children(order=0):+> exclamation;
    w1 +>:Children(order=0):+> g1;
    w1 +>:Children(order=1):+> g2;
    s1 +>:Children(order=0):+> w1;

    # Provider witnesses — same canonical span observed at two ranges/depths.
    a +>:Witness(kind="grapheme", byte_start=10, byte_end=11, depth=1):+> ts;
    a_nfd +>:Witness(kind="grapheme", byte_start=20, byte_end=21, depth=1):+> pcre;
    hello +>:Witness(kind="word", byte_start=0, byte_end=5, depth=2):+> ts;
    world +>:Witness(kind="word", byte_start=6, byte_end=11, depth=2):+> ts;
    greeting +>:Witness(kind="sentence", byte_start=0, byte_end=11, depth=3):+> ts;

    root ++> s1 ++> ts ++> pcre;

    print("=== Canonical census (unique spans + cycle check) ===");
