"""Percona GR bootstrap startup-probe race during full-cluster-crash recovery.

Models the essential scenario from issue #1467: members of a Group
Replication cluster traverse a recovery state machine while a startup
probe repeatedly inspects them. On transient "no peers" states the
bootstrap binary historically calls os.Exit(1); with failureThreshold:1
that kills the container — including a clone donor mid-flight — and the
recovery loop restarts. Here the walker represents the kubelet startup
probe. Transient peer-loss states return Exit-1 unless the cluster
recovery marker (full-cluster-crash) is present, in which case the
walker tolerates the transient state and waits — the same fix the issue
asks for.
"""

node Member {
    has name: str = "";
    has role: str = "secondary";
    has available: bool = True;
    has donating: bool = False;
}

node ClusterState {
    has label: str = "";
    has peers_online: int = 0;
    has full_cluster_crash: bool = False;
}

edge BelongsTo { has since: str = ""; }
edge PeerLink { has weight: int = 1; }
edge Recovery { has attempt: int = 0; }

walker StartupProbe {
    has failures: int = 0;
    has tolerated: int = 0;
    has killed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_cluster with ClusterState entry {
        state = here;
        # The recovery marker bypass added for readiness/liveness probes
        # in #1392 should also apply to the startup probe: while the
        # operator is mid-recovery, transient "no peers" states must NOT
        # kill the container — the whole point of failureThreshold:1 is
        # defeated otherwise.
        if state.peers_online == 0 and not state.full_cluster_crash {
            self.failures += 1;
            label = "FATAL" if self.failures >= 1 else "WARN";
            print(f"[{label}] {state.label}: no peers, bootstrap would exit(1)");
            for m in [-->](?:Member) {
                self.killed = self.killed + [m.name];
                print(f"  -> kubelet SIGTERM {m.name} (donor={m.donating})");
            }
        } elif state.peers_online == 0 and state.full_cluster_crash {
            self.tolerated += 1;
            print(f"[WAIT] {state.label}: recovery in progress, tolerating transient no-peers state");
            for m in [-->](?:Member) {
                if m.donating {
                    print(f"  -> protecting clone donor {m.name} from premature kill");
                }
            }
        } else {
            print(f"[OK] {state.label}: {state.peers_online} peers reachable");
        }
        visit [-->];
    }
}

with entry {
    primary = Member(name="mysql-0", role="primary", donating=True);
    joiner_a = Member(name="mysql-1", role="secondary", donating=False);
    joiner_b = Member(name="mysql-2", role="secondary", donating=False);

    state_mid_clone = ClusterState(label="mid-clone", peers_online=0, full_cluster_crash=True);
    state_post_recovery = ClusterState(label="post-recovery", peers_online=3, full_cluster_crash=False);
    state_steady = ClusterState(label="steady", peers_online=3, full_cluster_crash=False);

    root +>:BelongsTo(since="boot"):+> state_mid_clone;
    root +>:BelongsTo(since="boot"):+> state_post_recovery;
    root +>:BelongsTo(since="boot"):+> state_steady;

    state_mid_clone +>:PeerLink:+> primary;
    state_mid_clone +>:PeerLink:+> joiner_a;
    state_mid_clone +>:PeerLink:+> joiner_b;
    state_post_recovery +>:PeerLink:+> primary;
    state_post_recovery +>:PeerLink:+> joiner_a;
    state_post_recovery +>:PeerLink:+> joiner_b;
    state_steady +>:PeerLink:+> primary;
    state_steady +>:PeerLink:+> joiner_a;
    state_steady +>:PeerLink:+> joiner_b;

