```jac
"""Deep document update with materialized-path repair.

Models the scenario from issue #8 of janez89/mongoose-materialized: a
maintainer wants to dynamically update a deeply-nested document, then
recompute the materialized path of the updated node AND every
descendant. The hand-rolled machinery in the original (manual recursion
over children, queue-based traversal, repeated `findById` calls) is
replaced by a walker that traverses typed `ParentOf` edges, with an
explicit cycle guard (jac 0.36.1 walkers have no built-in
once-per-node visitation, so the guard set is domain logic and must
survive the lift).
"""

node Doc {
    has title: str = "";
    has path: str = "";
}

edge ParentOf { }

walker DeepUpdater {
    has new_parent_path: str = "";
    has guard: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can rewire with Doc entry {
        here.path = self.new_parent_path + "/" + here.title;
        print(f"repathed {here.title} -> {here.path}");
        self.guard.append(here.title);
        visit [->:ParentOf:->];
    }
}

walker CascadeRepath {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Doc entry {
        if here.title in self.seen {
            print(f"cycle guard hit at {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        print(f"visited {here.title} path={here.path}");
        visit [->:ParentOf:->];
    }
}

with entry {
    a = Doc(title="root-a");
    b = Doc(title="child-b");
    c = Doc(title="grandchild-c");
    d = Doc(title="leaf-d");

    root ++> a +>:ParentOf:+> b +>:ParentOf:+> c +>:ParentOf:+> d;

    updater = DeepUpdater(new_parent_path="/org/team");
    a spawn updater;

    print("--- cascade check ---");
    cascade = CascadeRepath();
    a spawn cascade;
}
```

```jac
"""Test annex for the deep materialized-path repair demo.

Exercises the two walkers declared in main.jac:
- DeepUpdater: rewrites `here.path` on the spawned Doc and every
  descendant reachable via ParentOf, using a guard list to avoid
  re-processing.
- CascadeRepath: a separate traversal that visits every reachable node
  in the same chain, with its own cycle guard.
"""

import io;
import from contextlib { redirect_stdout }

test "deep updater rewrites spawned node and cascades to every descendant" {
    rt = Root();
    a = rt ++> Doc(title="root-a");
    b = a +>:ParentOf:+> Doc(title="child-b");
    c = b +>:ParentOf:+> Doc(title="grandchild-c");
    d = c +>:ParentOf:+> Doc(title="leaf-d");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        updater = DeepUpdater(new_parent_path="/org/team");
        a spawn updater;
    }
    out = buf.getvalue();

    # the spawned node itself must be repathed
    assert a.path == "/org/team/root-a", f"a.path = {a.path}";
    # every descendant's path must include the new prefix and its own title
    assert b.path == "/org/team/child-b", f"b.path = {b.path}";
    assert c.path == "/org/team/grandchild-c", f"c.path = {c.path}";
    assert d.path == "/org/team/leaf-d", f"d.path = {d.path}";
    # the updater must report every node in the chain
    assert "repathed root-a" in out, f"missing root-a: {out}";
    assert "repathed child-b" in out, f"missing child-b: {out}";
    assert "repathed grandchild-c" in out, f"missing grandchild-c: {out}";
    assert "repathed leaf-d" in out, f"missing leaf-d: {out}";
    # exactly four nodes should be repathed — no over/under-traversal
    repath_lines = [
        ln
        for ln in out.splitlines()
        if ln.startswith("repathed ")
    ];
    assert len(repath_lines) == 4, f"repathed count = {len(repath_lines)}: {out}";
}

test "deep updater with no children only rewrites the spawned node" {
    rt = Root();
    only = rt ++> Doc(title="only");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        updater = DeepUpdater(new_parent_path="/x");
        only spawn updater;
    }
    out = buf.getvalue();

    assert only.path == "/x/only", f"only.path = {only.path}";
    assert "repathed only" in out, f"missing only: {out}";
    # a leaf should produce exactly one repathed line
    repath_lines = [
        ln
        for ln in out.splitlines()
        if ln.startswith("repathed ")
    ];
    assert len(repath_lines) == 1, f"repathed count = {len(repath_lines)}: {out}";
}

test "cascade walker visits every reachable node and reports the materialized path" {
    rt = Root();
    p = rt ++> Doc(title="p");
    q = p +>:ParentOf:+> Doc(title="q");
    r = q +>:ParentOf:+> Doc(title="r");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        cascade = CascadeRepath();
        p spawn cascade;
    }
    out = buf.getvalue();

    # every node in the chain should be visited exactly once
    assert "visited p" in out, f"missing p: {out}";
    assert "visited q" in out, f"missing q: {out}";
    assert "visited r" in out, f"missing r: {out}";
    visited_lines = [
        ln
        for ln in out.splitlines()
        if ln.startswith("visited ")
    ];
    assert len(visited_lines) == 3, f"visited count = {len(visited_lines)}: {out}";
    # cascade must NOT repath — it only walks
    assert "repathed" not in out, f"cascade should not repath: {out}";
}

test "deep updater guard list records every rewritten node exactly once" {
    rt = Root();
    a = rt ++> Doc(title="alpha");
    b = a +>:ParentOf:+> Doc(title="beta");
    c = b +>:ParentOf:+> Doc(title="gamma");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        updater = DeepUpdater(new_parent_path="/base");
        a spawn updater;
    }
    out = buf.getvalue();

    # the guard is what keeps a hand-rolled recursive descent from
    # double-visiting; verify it captured the full chain in order
    guard = updater.guard;
    assert len(guard) == 3, f"guard size = {len(guard)}: {guard}";
    assert guard == ["alpha", "beta", "gamma"], f"guard order = {guard}";
    # guard must NOT contain duplicates
    assert len(set(guard)) == len(guard), f"guard had duplicates: {guard}";
    # and the printed output agrees with the guard
    for title in guard {
        assert f"repathed {title}" in out, f"missing {title} in: {out}";
    }
}
```

