}

node ExtensionArtifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_is_immutable: bool = False;
    has artifact_matches: bool = False;
    has inventory_matches: bool = False;
    has undeclared_components: bool = False;
    has forbidden_authority: bool = False;
    has reconciliation_state: str = "pending";
}

node AdmissionEvidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has noema_released: bool = False;
    has appguardrail_released: bool = False;
    has policy_verified: bool = False;
    has receipt_stale: bool = True;
    has reconciliation_state: str = "pending";
}

node WorkstationScope {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pack_code: str = "";
    has client_code: str = "";
    has role_code: str = "";
    has repository_class: str = "";
    has permits_install: bool = False;
    has scope_matches: bool = False;
    has reconciliation_state: str = "pending";
}

edge Contains { }
edge Admits { }
edge VerifiedBy { }
edge ScopedTo { }

walker Reconciler {
    has installed_count: int = 0;
    has discovery_count: int = 0;
    has blocked_count: int = 0;
    has denied_count: int = 0;

    can start with Root entry {
        print("reconciliation started");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_receipt with ActivationReceipt entry {
        print(f"receipt: {here.plugin_name} v{here.plugin_version}");

        if here.denied {
            here.reconciliation_state = "blocked_by_deny_list";
            self.denied_count += 1;
            print("blocked by independent deny list");
        } else {
            if (not here.valid_now or not here.released_evidence or not here.scope_matches) {
                here.reconciliation_state = "blocked_before_installer";
                self.blocked_count += 1;
                print("blocked before installer");
            } else {
                if here.activation_mode == "discovery_only" {
                    here.reconciliation_state = "inventory_only";
                    print("discovery only: inventory permitted, install forbidden");
                } else {
                    here.reconciliation_state = "approved_pilot_pending_verification";
                    print("approved pilot: verifying exact artifact");
                }
                visit [->:Admits:->] else { disengage; }
            }
        }
    }

    can inspect_artifact with ExtensionArtifact entry {
        if (not here.source_is_immutable or not here.artifact_matches or not here.inventory_matches or here.undeclared_components or here.forbidden_authority) {
            here.reconciliation_state = "blocked_artifact_or_authority";
            self.blocked_count += 1;
            print("blocked: artifact, inventory, or authority mismatch");
        } else {
            here.reconciliation_state = "artifact_verified";
            print("artifact verified at admitted digest");
            visit [->:VerifiedBy:->] else { disengage; }
        }
    }

    can inspect_evidence with AdmissionEvidence entry {
        if (not here.noema_released or not here.appguardrail_released or not here.policy_verified or here.receipt_stale) {
            here.reconciliation_state = "blocked_missing_released_evidence";
            self.blocked_count += 1;
            print("blocked: released owner evidence is missing or stale");
        } else {
            here.reconciliation_state = "evidence_verified";
            print("released owner evidence verified");
            visit [-->] else { disengage; }
        }
    }

    can apply_scope with WorkstationScope entry {
        if not here.scope_matches {
            here.reconciliation_state = "blocked_scope";
            self.blocked_count += 1;
            print("blocked: workstation scope does not match");
        } else {
            if here.permits_install {
                here.reconciliation_state = "installed_exact_artifact";
                self.installed_count += 1;
                print("installed exact admitted artifact");
            } else {
                here.reconciliation_state = "dry_run_only";
                self.discovery_count += 1;
                print("dry run: no installation call");
            }
        }
    }
}

