```jac
"""WRC ↔ HCC no-op write-storm model.

Models the scenario from issue #460: a workflow-recipe controller (WRC)
reconciles shared resources unconditionally, hashing them to detect changes.
The hash gate is wired on one path but missing on the adjacent path in the
same module, so an idempotency guard on McpServer writes exists while
Context writes still churn every loop. A reconciler walker demonstrates the
two write paths; an auditor walker exposes the missed gate by inspecting
which writes carry a hash check.
"""

# ---------- Domain nodes ----------

node Resource {
    has name: str = "";
    has generation: int = 0;
    has resource_version: int = 0;
    has spec_hash: str = "";
    has writes: int = 0;
}

node McpServer(Resource) {
    has kind: str = "McpServer";
}

node Context(Resource) {
    has kind: str = "Context";
}

node NetworkPolicy(Resource) {
    has kind: str = "NetworkPolicy";
}

node Recipe {
    has name: str = "";
    has desired_hash: str = "";
}

# ---------- Typed edges ----------

edge Owns {
    has since: str = "";
}

edge Drives {
    has via: str = "";
}

# ---------- Walkers ----------

walker Reconcile {
    has recipe_name: str;
    has desired_hash: str;

    can start with Root entry {
        print(f"WRC reconcile tick for {self.recipe_name} (hash={self.desired_hash})");
        visit [-->];
    }

    can plan with Recipe entry {
        # Carry the desired hash forward by stashing on self so write
        # abilities can compare without re-resolving the recipe node.
        print(f"  planning recipe {here.name}");
        visit [-->];
    }

    can write_mcpserver with McpServer entry {
        # FIXED path: idempotency gate via specHashUnchanged is wired here.
        guard = "SKIP" if here.spec_hash == self.desired_hash else "WRITE";
        if guard == "SKIP" {
            print(f"  [McpServer/{here.name}] specHashUnchanged -> SKIP write");
        } else {
            here.writes += 1;
            here.generation += 1;
            here.resource_version += 1;
            here.spec_hash = self.desired_hash;
            print(f"  [McpServer/{here.name}] WRITE gen={here.generation} rv={here.resource_version}");
        }
        visit [-->];
    }

    can write_context with Context entry {
        # BUGGY path: gate exists in the same module but was never wired here,
        # so the unconditional replace keeps bumping resourceVersion every tick.
        here.writes += 1;
        here.generation += 1;
        here.resource_version += 1;
        here.spec_hash = self.desired_hash;
        print(f"  [Context/{here.name}] UNCONDITIONAL WRITE gen={here.generation} rv={here.resource_version}");
        visit [-->];
    }

    can write_networkpolicy with NetworkPolicy entry {
        # Downstream effect: HCC watches Context rv bumps and rewrites NPs.
        here.writes += 1;
        here.generation += 1;
        here.resource_version += 1;
        print(f"  [NetworkPolicy/{here.name}] HCC recompute (no-op write storm) gen={here.generation}");
        visit [-->];
    }
}

walker OrderAuditor {
    has report: list = [];

    can start with Root entry {
        print("Auditor: scanning resource write counts across the graph");
        visit [-->];
    }

    can count with McpServer | Context | NetworkPolicy entry {
        self.report.append((here.kind, here.name, here.writes, here.generation));
        print(f"  audit {here.kind}/{here.name}: writes={here.writes} gen={here.generation}");
    }
}

# ---------- Demo wiring ----------

with entry {
    helpdesk = Recipe(name="recipe-helpdesk-v1-0-0", desired_hash="h-helpdesk-001");
    brain = Recipe(name="recipe-evenfire-dev-brain-plugin-v0-1-5", desired_hash="h-brain-001");
    vul = Recipe(name="evenfire-vulnerability-plugin", desired_hash="h-vul-001");
    work = Recipe(name="recipe-evenfire-worktracker-v1-1-0", desired_hash="h-work-001");
    root ++> helpdesk ++> brain ++> vul ++> work;

    shared_ctx = Context(name="shared-context-1");
    root +>:Owns(since="2026-08-26"):+> shared_ctx;

    mcp_a = McpServer(name="recipe-helpdesk-mcp");
    mcp_b = McpServer(name="recipe-worktracker-mcp");
    shared_ctx +>:Drives(via="mcp"):+> mcp_a;
    shared_ctx +>:Drives(via="mcp"):+> mcp_b;

    np_ctx = NetworkPolicy(name="np-context-ingress");
    np_mcp = NetworkPolicy(name="np-mcp-egress");
    shared_ctx +>:Drives(via="np"):+> np_ctx;
    shared_ctx +>:Drives(via="np"):+> np_mcp;

    # Pre-seed the McpServer spec_hash so the gate is observable on tick 1.
    mcp_a.spec_hash = "h-helpdesk-001";
    mcp_b.spec_hash = "h-work-001";

    # Three reconcile ticks, each recipe takes a turn at the shared resources.
    root spawn Reconcile(recipe_name=helpdesk.name, desired_hash=helpdesk.desired_hash);
    root spawn Reconcile(recipe_name=work.name, desired_hash=work.desired_hash);
    root spawn Reconcile(recipe_name=helpdesk.name, desired_hash=helpdesk.desired_hash);

    auditor = OrderAuditor();
    root spawn auditor;
    print(f"final audit snapshot: {auditor.report}");
}
