"""Regression tests for the road-trip playlist program."""

import io;
import from contextlib { redirect_stdout }

test "inline chain creates a chain not fan-out from root" {
    root ++> Track(title="Highway Star", artist="Deep Purple", runtime_min=6.5)
        ++> Track(title="Life is a Highway", artist="Rascal Flatts", runtime_min=4.4)
        ++> Track(title="Take It Easy", artist="Eagles", runtime_min=3.7);

    # Chain semantics: each ++> links its left operand to its right operand,
    # so root has exactly one direct child, with three nodes total reachable.
    assert len([root-->]) == 1, f"root should have 1 direct child, got {len([root-->])}";

    first = [root-->][0];
    assert len([first-->]) == 1, f"first track should have 1 child, got {len([first-->])}";

    second = [first-->][0];
    assert len([second-->]) == 1, f"second track should have 1 child, got {len([second-->])}";

    third = [second-->][0];
    assert len([third-->]) == 0, f"third (leaf) track should have 0 children, got {len([third-->])}";
}

test "player walker visits all three tracks in chain order" {
    root ++> Track(title="Highway Star", artist="Deep Purple", runtime_min=6.5)
        ++> Track(title="Life is a Highway", artist="Rascal Flatts", runtime_min=4.4)
        ++> Track(title="Take It Easy", artist="Eagles", runtime_min=3.7);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # Header printed on Root entry.
    assert "Hitting the road!" in out, f"missing header: {out}";

    # All three tracks announced, in chain order.
    h_pos = out.find("Highway Star");
    l_pos = out.find("Life is a Highway");
    t_pos = out.find("Take It Easy");
    assert h_pos != -1, f"missing Highway Star: {out}";
    assert l_pos != -1, f"missing Life is a Highway: {out}";
    assert t_pos != -1, f"missing Take It Easy: {out}";
    assert h_pos < l_pos < t_pos, f"tracks not in order: {out}";

    # Now-playing line shape includes title, artist, runtime.
    assert "Deep Purple" in out, f"missing artist Deep Purple: {out}";
    assert "6.5 min" in out, f"missing runtime 6.5 min: {out}";
}

test "player walker accumulates total runtime across all tracks" {
    root ++> Track(title="Highway Star", artist="Deep Purple", runtime_min=6.5)
        ++> Track(title="Life is a Highway", artist="Rascal Flatts", runtime_min=4.4)
        ++> Track(title="Take It Easy", artist="Eagles", runtime_min=3.7);

    res = root spawn Player();

    # 6.5 + 4.4 + 3.7 == 14.6 (allow tiny float drift).
    expected = 6.5 + 4.4 + 3.7;
    assert abs(res.total_min - expected) < 1e-6, f"total_min={res.total_min}, expected {expected}";
}

test "single track chain still plays and totals correctly" {
    root ++> Track(title="On the Road Again", artist="Willie Nelson", runtime_min=2.3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    assert "Hitting the road!" in out, f"missing header: {out}";
    assert "On the Road Again" in out, f"missing track title: {out}";
    assert "Willie Nelson" in out, f"missing artist: {out}";
    assert "2.3 min" in out, f"missing runtime: {out}";
    assert abs(res.total_min - 2.3) < 1e-6, f"total_min={res.total_min}";
}

test "fan-out of three tracks from root does not match chain shape" {
    # Three SEPARATE ++> statements -> fan-out (3 direct children of root).
    root ++> Track(title="A", artist="x", runtime_min=1.0);
    root ++> Track(title="B", artist="x", runtime_min=2.0);
    root ++> Track(title="C", artist="x", runtime_min=3.0);

    assert len([root-->]) == 3, f"fan-out should give 3 direct children, got {len([root-->])}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # Player still traverses all reachable tracks, so totals match.
    expected = 1.0 + 2.0 + 3.0;
    assert abs(res.total_min - expected) < 1e-6, f"total_min={res.total_min}, expected {expected}";

    # All three titles appear in output (order not asserted: fan-out order is unspecified).
    assert "A" in out and "B" in out and "C" in out, f"missing tracks: {out}";
}

