"""Filesystem trie as flow tree: admitted sources, manifest metadata, bundle-v2 identity.

Models the essential scenario from division-sh/swarm#2320: the conventional
filesystem trie is the sole semantic flow topology. Every local and later
published source enters through one immutable AdmittedSourceArtifact,
receives bundle-v2 exact-byte identity, and durable local execution
persists the canonical source blob by hash. manifest.yaml is optional
source-semantic-inert distribution metadata. A walker cascades invalidation
through the trie when a source artifact is superseded.
"""

node Directory {
    has path: str = "";
    has owner: str = "";
}

node SourceFile {
    has path: str = "";
    has sha256: str = "";
    has durable: bool = False;
}

node Manifest {
    has path: str = "";
    has distribution_channel: str = "";
    has version: str = "";
}

edge Contains { }
edge Admits {
    has admitted_at: str = "";
    has bundle_v2: bool = True;
}
edge Describes { }

walker InvalidationCascade {
    has superseded_sha: str = "";
    has invalidated: list[str] = [];
    has guard: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Directory entry {
        if self.superseded_sha != "" {
            print(f"walking subtree {here.path} (owner={here.owner})");
        }
        visit [-->] else { disengage; }
    }

    can check with SourceFile entry {
        here_path = here.path;
        in_guard = here_path in self.guard;
        if in_guard {
            print(f"  cycle guard hit on {here_path}, skipping");
        } elif here.sha256 == self.superseded_sha {
            print(f"  superseding {here_path} (sha={here.sha256})");
            self.invalidated.append(here_path);
            here.durable = False;
            here.sha256 = "PENDING_RECOMPUTE";
        } else {
            print(f"  kept {here_path} (sha={here.sha256})");
        }
    }

    can note with Manifest entry {
        print(f"  manifest {here.path} is source-semantic-inert "
              f"(channel={here.distribution_channel}, version={here.version})");
        visit [-->] else { disengage; }
    }
}

with entry {
    src_dir = Directory(path="src/", owner="core");
    tests_dir = Directory(path="src/tests/", owner="core");
    dist_dir = Directory(path="dist/", owner="release");

    foo_py = SourceFile(path="src/foo.py", sha256="abc123", durable=True);
    bar_py = SourceFile(path="src/tests/bar.py", sha256="abc123", durable=True);
    baz_py = SourceFile(path="src/baz.py", sha256="def456", durable=True);

    manifest = Manifest(
        path="manifest.yaml",
        distribution_channel="nightly",
        version="0.1.0"
    );

    root ++> src_dir ++> tests_dir ++> dist_dir;
    src_dir +>:Contains:+> foo_py;
    src_dir +>:Contains:+> baz_py;
    tests_dir +>:Contains:+> bar_py;
    src_dir +>:Describes:+> manifest;
    foo_py +>:Admits(admitted_at="2026-01-15T00:00:00Z", bundle_v2=True):+> bar_py;

    print("=== before invalidation ===");
    print(f"foo.py durable={foo_py.durable}, sha={foo_py.sha256}");
    print(f"bar.py durable={bar_py.durable}, sha={bar_py.sha256}");
    print(f"baz.py durable={baz_py.durable}, sha={baz_py.sha256}");

    guard_seen: list[str] = ["src/tests/bar.py"];
    invalidator = InvalidationCascade(
        superseded_sha="abc123",
        guard=guard_seen
    );
    root spawn invalidator;

    print("=== after invalidation ===");
    print(f"foo.py durable={foo_py.durable}, sha={foo_py.sha256}");
    print(f"bar.py durable={bar_py.durable}, sha={bar_py.sha256}");
    print(f"baz.py durable={baz_py.durable}, sha={baz_py.sha256}");
    print(f"invalidated paths: {invalidator.invalidated}");
}
