    foo = SourceFile(path="src/foo.py", sha256="abc123", durable=True);
    bar = SourceFile(path="src/tests/bar.py", sha256="abc123", durable=True);
    baz = SourceFile(path="src/baz.py", sha256="def456", durable=True);

    root ++> src_dir ++> tests_dir ++> dist_dir;
    src_dir +>:Contains:+> foo;
    src_dir +>:Contains:+> baz;
    tests_dir +>:Contains:+> bar;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InvalidationCascade(
            superseded_sha="abc123",
            guard=["src/tests/bar.py"]
        );
    }
    out = buf.getvalue();
    assert len([root-->]) == 1, f"root should have one direct child got {len([root-->])}";
    assert "walking subtree src/" in out, f"missing src subtree walk: {out}";
    assert "walking subtree src/tests/" in out, f"missing tests subtree walk: {out}";
    assert "walking subtree dist/" in out, f"missing dist subtree walk: {out}";
    assert "src/foo.py" in res.invalidated, f"foo should be invalidated got {res.invalidated}";
    assert "src/tests/bar.py" not in res.invalidated, f"bar should be guarded got {res.invalidated}";
    assert "src/baz.py" not in res.invalidated, f"baz should be kept got {res.invalidated}";
    assert baz.durable, f"baz durable should remain True got {baz.durable}";
    assert baz.sha256 == "def456", f"baz sha should be unchanged got {baz.sha256}";
}
