"""Tar path filter safety demo with typed parent traversal and depth guards."""

node Archive {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

node TarEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has segment_count: int = 0;
    has selected: bool = False;
}

node PathNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has segment_count: int = 0;
}

edge Contains {
    has role: str = "member";
}

edge ParentPath {
    has component_count: int = 0;
}

walker PathGuard {
    has max_segments: int = 1024;
    has seen_paths: list[str] = [];

    can start with Root entry {
        print("Scanning archive paths");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_archive with Archive entry {
        print(f"Archive: {here.name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_entry with TarEntry entry {
        if here.selected {
            if here.segment_count > self.max_segments {
                here.available = False;
                print(f"Rejected {here.path}: too many path segments");
                disengage;
            }

            if here.path in self.seen_paths {
                print(f"Cycle detected at {here.path}");
                disengage;
            }

            self.seen_paths.append(here.path);
            print(f"Filtering selected entry {here.path}");
            visit [->:ParentPath:->] else {
                disengage;
            }
        } else {
            print(f"Skipping unselected entry {here.path}");
            disengage;
        }
    }

    can inspect_parent with PathNode entry {
        if here.path in self.seen_paths {
            print(f"Cycle detected at {here.path}");
            disengage;
        }

        self.seen_paths.append(here.path);
        print(f"Checking parent {here.path}");

        if here.segment_count > self.max_segments {
            here.available = False;
            print(f"Rejected parent {here.path}: too many path segments");
            disengage;
        }

        visit [->:ParentPath:->] else {
            disengage;
        }
    }
}

with entry {
    archive = Archive(name="incoming.tar", title="Incoming Archive", year=2026);

    safe_entry = TarEntry(
