"""Tests for chat reaction inheritance: Reacts, Echo, StaffPin, ChannelReader."""

import io;
import from contextlib { redirect_stdout }

# ─────────────────────────────────────────────────────────────────────────────
# Test 1: ChannelReader traversal — visiting from Root, each Account node
# fires the `browse` ability, which traverses outgoing [->:Reacts:->] edges
# and prints what each account reacted to.
# ─────────────────────────────────────────────────────────────────────────────
test "ChannelReader walks accounts and prints their reactions" {
    mod = Moderator(handle="dana", team="trust-safety");
    user = Account(handle="eli");

    m_a = Message(body="deploy finished");
    m_b = Message(body="lunch poll results");

    root ++> mod;
    mod +>: StaffPin(emoji="pushpin", pinned_at="09:00") :+> m_a;
    root ++> user;
    user +>: Reacts(emoji="thumbsup") :+> m_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        reader = ChannelReader();
        root spawn reader;
    }
    out = buf.getvalue();

    # Two accounts under root, each has one Reacts-family edge.
    assert out.count("reacted to") == 2, f"expected 2 reaction lines, got: {out}";
    assert "@dana reacted to 'deploy finished'" in out, f"dana line missing: {out}";
    assert "@eli reacted to 'lunch poll results'" in out, f"eli line missing: {out}";
}

# ─────────────────────────────────────────────────────────────────────────────
# Test 2: Echo inherits Reacts endpoints — Account --> Message.
# Endpoint-aware traversal [->:Reacts:->] from an Account node must follow
# Echo edges just like plain Reacts edges.
# ─────────────────────────────────────────────────────────────────────────────
test "Echo edges are traversed by Reacts-filtered endpoint query" {
    alice = Account(handle="alice");
    m_echo = Message(body="echoed message");

    root ++> alice;
    alice +>: Echo(emoji="eyes") :+> m_echo;

    # The Echo edge must show up under the [->:Reacts:->] filter
    # because Echo inherits Reacts's endpoints.
    traversed = [alice ->:Reacts:->];
    assert len(traversed) == 1, f"Echo should be reachable via Reacts filter, got {len(traversed)}";
    assert traversed[0].body == "echoed message", f"wrong message: {traversed[0].body}";

    # Verify the edge type itself is Echo.
    echo_edges = [alice ->:Echo:->];
    assert len(echo_edges) == 1, f"Echo edge missing, got {len(echo_edges)}";
    assert echo_edges[0].body == "echoed message", f"wrong message via Echo: {echo_edges[0].body}";
}

# ─────────────────────────────────────────────────────────────────────────────
# Test 3: StaffPin restricts source to Moderator — the edge declaration
# StaffPin(Reacts): Moderator --> Message means only a Moderator node can
# be the source. Verify a plain Account cannot create a StaffPin edge and
# that a Moderator can.
# ─────────────────────────────────────────────────────────────────────────────
test "StaffPin requires Moderator source" {
    mod = Moderator(handle="mod_b", team="safety");
    plain = Account(handle="plain_b");
    target = Message(body="pinned notice");

    root ++> mod;
    mod +>: StaffPin(emoji="pushpin", pinned_at="10:30") :+> target;

    # The StaffPin edge exists from the Moderator.
    pins = [mod ->:StaffPin:->];
    assert len(pins) == 1, f"StaffPin from Moderator missing: {len(pins)}";
    assert pins[0].body == "pinned notice", f"wrong target: {pins[0].body}";

    # StaffPin also inherits Reacts, so it must be visible under [->:Reacts:->].
    reacts_view = [mod ->:Reacts:->];
    assert len(reacts_view) == 1, f"StaffPin not visible under Reacts: {len(reacts_view)}";

    # StaffPin carries the extra `pinned_at` field.
    all_staff_pins = [mod ->:StaffPin:->];
    assert len(all_staff_pins) >= 1, "should have staff pins";
}

# ─────────────────────────────────────────────────────────────────────────────
# Test 4: ChannelReader traverses mixed edge types. With one Moderator
# producing StaffPin + Echo and one Account producing plain Reacts, the
# walk should emit three reaction lines covering all three messages.
# ─────────────────────────────────────────────────────────────────────────────
test "mixed reactions all appear in ChannelReader output" {
    mod = Moderator(handle="dana", team="trust-safety");
    user = Account(handle="eli");

    m1 = Message(body="deploy finished");
    m2 = Message(body="lunch poll results");
    m3 = Message(body="welcome new folks");

    root ++> mod;
    mod +>: StaffPin(emoji="pushpin", pinned_at="09:00") :+> m1;
    mod +>: Echo(emoji="eyes") :+> m3;
    root ++> user;
    user +>: Reacts(emoji="thumbsup") :+> m2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        reader = ChannelReader();
        root spawn reader;
    }
    out = buf.getvalue();

    # All three reactions must appear in the output regardless of subtype.
    assert "@dana reacted to 'deploy finished'" in out, f"StaffPin reaction missing: {out}";
    assert "@dana reacted to 'welcome new folks'" in out, f"Echo reaction missing: {out}";
    assert "@eli reacted to 'lunch poll results'" in out, f"plain Reacts missing: {out}";
    assert out.count("reacted to") == 3, f"expected 3 lines, got: {out}";
}

# ─────────────────────────────────────────────────────────────────────────────
# Test 5: Graph shape — account nodes under root have exactly the expected
# outgoing Reacts-family edges and nothing else.
# ─────────────────────────────────────────────────────────────────────────────
test "graph topology matches three reaction edges across two accounts" {
    mod = Moderator(handle="mod_t", team="trust-safety");
    user = Account(handle="user_t");

    m1 = Message(body="m1");
    m2 = Message(body="m2");
    m3 = Message(body="m3");

    root ++> mod;
    mod +>: StaffPin(emoji="pushpin", pinned_at="08:00") :+> m1;
    mod +>: Echo(emoji="eyes") :+> m3;
    root ++> user;
    user +>: Reacts(emoji="thumbsup") :+> m2;

    # Two account nodes hang off root.
    accounts = [root -->];
    assert len(accounts) == 2, f"expected 2 accounts under root, got {len(accounts)}";

    # Each account has exactly one Reacts-family outgoing edge.
    mod_reacts = [mod ->:Reacts:->];
    user_reacts = [user ->:Reacts:->];
    assert len(mod_reacts) == 2, f"Moderator should have 2 Reacts-family edges, got {len(mod_reacts)}";
    assert len(user_reacts) == 1, f"User should have 1 Reacts-family edge, got {len(user_reacts)}";

    # Moderator's edges split into one StaffPin and one Echo.
    mod_pins = [mod ->:StaffPin:->];
    mod_echoes = [mod ->:Echo:->];
    assert len(mod_pins) == 1, f"expected 1 StaffPin, got {len(mod_pins)}";
    assert len(mod_echoes) == 1, f"expected 1 Echo, got {len(mod_echoes)}";

    # Three message nodes total reachable from the accounts.
    all_msgs = [mod ->:Reacts:->] + [user ->:Reacts:->];
    assert len(all_msgs) == 3, f"expected 3 reacted messages, got {len(all_msgs)}";

    bodies = {m.body for m in all_msgs};
    assert bodies == {"m1", "m2", "m3"}, f"unexpected message bodies: {bodies}";
}

