```jac
"""Process-tree socket ghost model.

Models the Claude-Code / Bash-tool Windows AF_UNIX socket bug as a graph:

    Root
      +-> BashTool
            +-> ChildProcess (holds a socket file path)
                  +-> SocketGhost (an undeletable name residue)

A ``Probe`` walker walks the tree, mimics the probe script, and reports
which socket paths became "poisoned ghosts" - i.e. nodes the harness
process tree forgot to invalidate, exactly like the user's issue.

The shape captures the essential scenario: a parent process tree
spawns child processes that bind AF_UNIX sockets, and on Windows
inside that tree the socket file is never auto-removed and cannot be
deleted. The walker traverses the ``Spawns`` edge type to reach every
descendant and reports the poisoned names it finds.
"""

node ProcessNode {
    has pid: int = 0;
    has label: str = "";
}

node BashTool {
    has pid: int = 0;
    has label: str = "bash-tool";
}

node ChildProcess {
    has pid: int = 0;
    has label: str = "";
    has socket_path: str = "";
    has socket_closed: bool = False;
    has auto_removed: bool = False;
}

node SocketGhost {
    has pid: int = 0;
    has label: str = "";
    has path: str = "";
    has undeletable: bool = True;
    has name_poisoned: bool = True;
}

edge Spawns { has order: int = 0; }
edge BoundSocket { has path: str = ""; }
edge LeakedAs { has reason: str = ""; }

walker Probe {
    has reports: list[str] = [];
    has healthy_count: int = 0;
    has ghost_count: int = 0;

    can start with Root entry {
        print("== AF_UNIX socket probe over process tree ==");
        visit [->:Spawns:->];
    }

    can enter_tool with BashTool entry {
        print(f"[tool] entered {here.label} (pid {here.pid})");
        visit [->:Spawns:->];
    }

    can inspect_child with ChildProcess entry {
        path = here.socket_path;
        if here.socket_closed {
            if here.auto_removed {
                line = f"OK   pid={here.pid} path={path} auto-removed";
                self.healthy_count += 1;
            } else {
                ghost = SocketGhost(pid=here.pid, label="ghost", path=path);
                here +>:LeakedAs(reason="ERROR_CANT_ACCESS_FILE_1920"):+> ghost;
                line = f"BROKEN pid={here.pid} path={path} -> leaked as ghost";
                self.ghost_count += 1;
            }
            self.reports.append(line);
            print(line);
        } else {
                print(f"skip pid={here.pid} (socket still open)");
        }
        visit [->:Spawns:->];
    }

    can visit_ghost with SocketGhost entry {
        poisoned = "yes" if here.name_poisoned else "no";
        undel = "yes" if here.undeletable else "no";
        note = f"      ghost {here.path} poisoned={poisoned} undeletable={undel}";
        self.reports.append(note);
        print(note);
        visit [-->];
    }

    can summarize with Root entry {
        print("");
        print(f"healthy closes: {self.healthy_count}");
        print(f"poisoned ghosts: {self.ghost_count}");
        print(f"total findings: {len(self.reports)}");
        if self.ghost_count > 0 {
            print("RESULT: BROKEN - socket files leaked as undeletable ghosts");
        } else {
            print("RESULT: healthy - all socket paths cleaned up");
        }
    }
}

with entry {
    bash = BashTool(pid=100, label="BashTool-session-A");

    healthy_child = ChildProcess(
        pid=201,
        label="terminal-pwsh",
        socket_path="C:/Temp/plain-terminal.sock",
