"""Bounded AgentCore goal evidence with typed relationships and safe retention review."""

node Goal {
    has goal_id: str = "";
    has status: str = "ACTIVE";
    has retention_class: str = "UNKNOWN";
}

node Attempt {
    has attempt_id: str = "";
    has outcome: str = "";
    has retry_reason: str = "";
}

node Evidence {
    has label: str = "";
    has classification: str = "REVIEW";
    has selected: bool = False;
    has copied: bool = False;
    has review_required: bool = False;
}

node SourcePointer {
    has reference: str = "";
    has commit_sha: str = "";
}

edge HasAttempt { }
edge Produces { }
edge RetryLeadsTo { }
edge PointsTo { }

walker RetentionAuditor {
    has keep_count: int = 0;
    has archive_count: int = 0;
    has candidate_count: int = 0;
    has review_count: int = 0;
    has hops: int = 0;
    has max_hops: int = 12;

    can start with Root entry {
        print("Auditing one bounded goal/run");
        visit [-->] else { disengage; }
    }

    can inspect_goal with Goal entry {
        print(f"Goal {here.goal_id}: {here.status}");
        if self.hops >= self.max_hops {
            print("Traversal stopped at the safety hop limit");
            disengage;
        } else {
            self.hops += 1;
            visit [->:HasAttempt:->] else { disengage; }
        }
    }

    can inspect_attempt with Attempt entry {
        print(f"Attempt {here.attempt_id}: {here.outcome}");
        if self.hops >= self.max_hops {
            print("Traversal stopped at the safety hop limit");
            disengage;
        } else {
            self.hops += 1;
            visit [->:Produces:->] else { disengage; }
        }
    }

    can classify_evidence with Evidence entry {
        if here.classification == "KEEP" {
            self.keep_count += 1;
            print(f"KEEP {here.label}");
        }
        if here.classification == "ARCHIVE" {
            self.archive_count += 1;
            print(f"ARCHIVE {here.label}");
        }
        if here.classification == "DELETE_CANDIDATE" {
            self.candidate_count += 1;
            print(f"CANDIDATE only: {here.label}");
        }
        if here.classification == "REVIEW" {
            self.review_count += 1;
            here.review_required = True;
            print(f"REVIEW {here.label}");
        }
        if here.copied {
            here.review_required = True;
            print(f"No-copy policy requires review: {here.label}");
        }
        if self.hops >= self.max_hops {
            print("Traversal stopped at the safety hop limit");
            disengage;
        } else {
            self.hops += 1;
