        ++> Pet(name="Olive", species="cat", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print("");
    print("Round complete.");
    print(f"Patients seen: {vet.patients}");
    print(f"Shots given:   {vet.shots_given}");
