"""Generic-style parameter and constraint resolution modeled with typed edges.

Models the essential scenario from issue #34: a graph of type-like nodes
(``Param``, ``Constraint``, ``ConcreteType``) with ``Constrains`` and
``Applies`` relationships. A walker performs inference-first resolution
with deferred substitution, depth limiting, cycle detection, and
constraint evaluation — the same shape as a generics type checker.
"""

node Param {
    has name: str = "";
    has kind: str = "type";
    has resolved: bool = False;
}

node Constraint {
    has expr: str = "";
    has valid: bool = True;
    has reason: str = "";
}

node ConcreteType {
    has name: str = "";
    has base: str = "";
}

edge Constrains {
    has weight: int = 0;
}

edge Applies {
    has site: str = "";
}

edge Depends {
}

walker Resolver {
    has max_depth: int = 8;
    has guard: list[str] = [];
    has depth: int = 0;
    has log: list[str] = [];
    has deferred: list[str] = [];

    can start with Root entry {
        self.depth = 0;
        visit [-->];
    }

    can resolve_param with Param entry {
        if here.resolved {
            self.log.append(f"already resolved: {here.name}");
            disengage;
        }
        self.depth += 1;
        if self.depth > self.max_depth {
            self.log.append(f"depth limit hit at {here.name}");
            self.deferred.append(here.name);
            disengage;
        }
        if here.name in self.guard {
            self.log.append(f"cycle detected at {here.name}");
            self.deferred.append(here.name);
            disengage;
        }
        self.guard.append(here.name);
        self.log.append(f"resolving param {here.name} ({here.kind})");
        visit [->:Constrains:->];
    }

    can check_constraints with Constraint entry {
        passed = here.valid;
        verdict = "valid" if passed else "invalid";
        line = f"constraint '{here.expr}' -> {verdict}";
        if not passed {
            line = f"{line}: {here.reason}";
        }
        self.log.append(line);
        visit [->:Depends:->];
    }

    can record_concrete with ConcreteType entry {
        self.log.append(f"concrete type resolved: {here.name} (base={here.base})");
        visit [-->];
    }
}

with entry {
    T = Param(name="T", kind="type");
    U = Param(name="U", kind="type");
    V = Param(name="V", kind="type");
    W = Param(name="W", kind="type");

    same_kind = Constraint(expr="T == U", valid=True);
    numeric = Constraint(expr="is_numeric(T)", valid=False, reason="T is unbound");
    deferrable = Constraint(expr="has_field(T, .x)", valid=True);

    list_T = ConcreteType(name="List<T>", base="List");
    list_int = ConcreteType(name="List<int>", base="List");

    root ++> T ++> U ++> V ++> W;

    T +>:Constrains(weight=1):+> same_kind;
    T +>:Constrains(weight=2):+> numeric;
    U +>:Constrains(weight=3):+> deferrable;

    same_kind +>:Depends:+> numeric;
    numeric +>:Depends:+> deferrable;

    T +>:Applies(site="List<T>"):+> list_T;
    list_T +>:Applies(site="List<int>"):+> list_int;

    r = Resolver(max_depth=4);
    root spawn r;

    print("resolution log:");
    for entry in r.log {
        print(f"  - {entry}");
    }
    print(f"deferred params: {r.deferred}");
}
