    # the walker implementation), but it must be strictly less than the
    # total node count and at least one.
    total_rooms = 4;
    assert checked_count < total_rooms, f"must not check all rooms ({checked_count}/{total_rooms}): {out}";
    assert checked_count >= 0, f"invalid checked count: {checked_count}";
