import from contextlib { redirect_stdout }

test "unpublished reports return None from access_hook" {
    q1 = Report(title="Q1 Earnings", year=2024);
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    root ++> q1 ++> draft;

    assert q1.access_hook() is None, f"q1 should be closed, got {q1.access_hook()}";
    assert draft.access_hook() is None, f"draft should be closed, got {draft.access_hook()}";
}

test "published report returns READ from access_hook" {
    r = Report(title="Launch Plan", year=2026, published=True);
    root ++> r;

    assert r.access_hook() == "READ", f"expected READ, got {r.access_hook()}";
    assert r.published is True, "published flag should be True";
}

test "publisher walker flips flag and drops grant on matching report" {
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    q1 = Report(title="Q1 Earnings", year=2024);
    root ++> q1 ++> draft;

    assert draft.published is False, "pre: draft should be unpublished";
    assert draft.grant == "board-only", f"pre: grant should be 'board-only', got '{draft.grant}'";

    root spawn Publisher(report_title="Acquisition Memo");

    assert draft.published is True, "post: Publisher should have flipped the flag";
    assert draft.grant == "", f"post: grant should be cleared, got '{draft.grant}'";
    assert draft.access_hook() == "READ", "post: hook should now return READ";
}

test "publisher walker leaves non-matching reports untouched" {
    q1 = Report(title="Q1 Earnings", year=2024, grant="owner-only");
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    root ++> q1 ++> draft;

