    # q1 must be untouched: still unpublished, grant intact, hook returns None.
    assert q1.published is False, "q1 should remain unpublished";
    assert q1.grant == "owner-only", f"q1 grant must be intact, got '{q1.grant}'";
    assert q1.access_hook() is None, f"q1 hook should remain None, got {q1.access_hook()}";
}

