    q1 = Report(title="Q1 Earnings", year=2024);
    q2 = Report(title="Q2 Earnings", year=2024, grant="owner-only");
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    root ++> q1 ++> q2 ++> draft;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # All three are unpublished at this point -> all CLOSED, grants visible.
    assert "[CLOSED] Q1 Earnings" in out, f"missing CLOSED Q1 line: {out}";
    assert "[CLOSED] Q2 Earnings (2024) grant=owner-only" in out, f"missing CLOSED Q2 with grant: {out}";
    assert "[CLOSED] Acquisition Memo (2025) grant=board-only" in out, f"missing CLOSED draft with grant: {out}";
    assert "[READ]" not in out, f"no READ expected before publishing: {out}";

    # Now publish the draft and re-audit; the draft should switch to READ with no grant suffix.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        root spawn Publisher(report_title="Acquisition Memo");
    }
