    assert "grant=" not in out2.split("[READ]")[1].split("\n")[0], f"READ line should omit grant: {out2}";
    assert "[CLOSED] Q1 Earnings" in out2, f"q1 should remain CLOSED: {out2}";
    assert "[CLOSED] Q2 Earnings (2024) grant=owner-only" in out2, f"q2 should still show its grant: {out2}";
