"""Restaurant kitchen line health-inspection walker.

Two checks run at every station — temperature audit (flag anything above
40 C as a violation) and a visit log. Using a union trigger for the
audit lets one ability serve all station node types without duplication.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

node Grill(Station) {}
