        visit [-->];
    }
}

with entry {
    root ++> Grill(name="grill", temperature=180.0)
        ++> Fryer(name="fryer", temperature=35.0)
        ++> ColdPrep(name="cold-prep", temperature=50.0);

    inspector = Inspector();
    root spawn inspector;

    logger = Logger();
    root spawn logger;

    print(f"Stations visited: {inspector.stations_visited}");
    print(f"Violations ({len(inspector.violations)}):");
    for v in inspector.violations {
        print(f"  - {v}");
    }
    print("Visit log:");
    for entry in logger.log {
        print(f"  - {entry}");
    }
}
