```jac
"""GraphVisualizer: per-step BFS/DFS traversal state over a graph.

Models the essential scenario from issue #6: a graph is built as node
archetypes connected by typed edges, and a walker performs the traversal
(BFS with a queue, DFS with a stack) while emitting a VisualizationFrame
per step capturing the visited set, frontier contents, current node, and
the edge just traversed.
"""

# ---------- Entities ----------

node GraphNode {
    has label: str = "";
}

node VisualizationFrame {
    has step: int = 0;
    has visited: list[str] = [];
    has frontier: list[str] = [];
    has current: str = "";
    has edge_taken: str = "";
}

# ---------- Relationships ----------

edge Adjacent { }

# ---------- Walkers ----------

walker GraphVisualizer {
    has mode: str = "BFS";
    has frames: list[VisualizationFrame] = [];
    has frontier: list[str] = [];
    has visited: list[str] = [];
    has last_edge: str = "";
    has last_dst: str = "";

    can start with Root entry {
        print(f"GraphVisualizer starting in {self.mode} mode");
        # Seed the walk at the spawned graph root's first neighbor.
        visit [->:Adjacent:->];
    }

    can snapshot with GraphNode entry {
        # Record the current node as a new frame and update walker state.
        self.last_dst = here.label;
        if here.label not in self.visited {
            self.visited.append(here.label);
        }
        if self.mode == "BFS" {
            if here.label not in self.frontier {
                self.frontier.append(here.label);
            }
        } else {
            if here.label not in self.frontier {
                self.frontier = [here.label] + self.frontier;
            }
        }
        self.frames.append(
            VisualizationFrame(
                step=len(self.frames),
                current=here.label,
                visited=list(self.visited),
                frontier=list(self.frontier),
                edge_taken=self.last_edge
            )
        );
        visit [->:Adjacent:->];
    }
}

walker Reachability {
    has order: list[str] = [];

    can start with Root entry {
        visit [->:Adjacent:->];
    }

    can reach with GraphNode entry {
        if here.label not in self.order {
            self.order.append(here.label);
        }
        visit [->:Adjacent:->];
    }
}

# ---------- Demonstration ----------

with entry {
    # Build a small graph: A - B - C, A - D, D - E.
    a = GraphNode(label="A");
    b = GraphNode(label="B");
    c = GraphNode(label="C");
    d = GraphNode(label="D");
    e = GraphNode(label="E");

    root ++> a;
    a +>:Adjacent:+> b;
    a +>:Adjacent:+> d;
    b +>:Adjacent:+> c;
    d +>:Adjacent:+> e;

    # ---- BFS demonstration ----
    bfs_viz = GraphVisualizer(mode="BFS");
    print("=== BFS traversal frames ===");
    a spawn bfs_viz;

    for f in bfs_viz.frames {
        print(
            f"step {f.step}: current={f.current} "
            f"visited={f.visited} frontier={f.frontier} "
            f"edge={f.edge_taken}"
        );
    }

    # ---- DFS demonstration on the same graph ----
    dfs_viz = GraphVisualizer(mode="DFS");
    print("=== DFS traversal frames ===");
    a spawn dfs_viz;

    for f in dfs_viz.frames {
        print(
            f"step {f.step}: current={f.current} "
            f"visited={f.visited} frontier={f.frontier} "
            f"edge={f.edge_taken}"
        );
    }

    # ---- Independent reachability runs for sanity ----
    bfs = Reachability();
    a spawn bfs;
    print(f"Reach order: {bfs.order}");
}
