"""Tests for GraphVisualizer: BFS/DFS traversal state over a graph."""

import io;
import from contextlib { redirect_stdout }

test "BFS emits per-step frames with visited and frontier" {
    # Graph: A -> B, A -> D, B -> C, D -> E
    a = GraphNode(label="A");
    b = GraphNode(label="B");
    c = GraphNode(label="C");
    d = GraphNode(label="D");
    e = GraphNode(label="E");

    root ++> a;
    a +>:Adjacent:+> b;
    a +>:Adjacent:+> d;
    b +>:Adjacent:+> c;
    d +>:Adjacent:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        viz = GraphVisualizer(mode="BFS");
        a spawn viz;
    }

    # BFS should visit all 5 reachable nodes.
    assert len(viz.frames) == 5, f"expected 5 frames, got {len(viz.frames)}";

    # Steps are 0..4 in order.
    for i in range(5) {
        assert viz.frames[i].step == i, f"frame {i} step = {viz.frames[i].step}";
    }

    # First frame: start at A, A is in visited, A is in frontier.
    f0 = viz.frames[0];
    assert f0.current == "A", f"step 0 current = {f0.current}";
    assert "A" in f0.visited, f"step 0 visited missing A: {f0.visited}";
    assert "A" in f0.frontier, f"step 0 frontier missing A: {f0.frontier}";

    # Visited must grow monotonically (no duplicates) and end with all 5 nodes.
    all_visited = [];
    for f in viz.frames {
        all_visited.append(f.current);
        for v in f.visited {
            assert f.visited.count(v) == 1, f"duplicate {v} in step {f.step} visited";
        }
    }
    assert sorted(set(all_visited)) == ["A", "B", "C", "D", "E"], f"unvisited nodes: {all_visited}";

    # BFS final frontier is non-empty (pending nodes to process).
    final = viz.frames[4];
    assert len(final.frontier) >= 1, f"BFS final frontier should be non-empty, got {final.frontier}";
}

test "DFS emits frames using stack-ordered frontier" {
    # Same graph as BFS test.
    a = GraphNode(label="A");
    b = GraphNode(label="B");
    c = GraphNode(label="C");
    d = GraphNode(label="D");
    e = GraphNode(label="E");

    root ++> a;
    a +>:Adjacent:+> b;
    a +>:Adjacent:+> d;
    b +>:Adjacent:+> c;
    d +>:Adjacent:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        viz = GraphVisualizer(mode="DFS");
        a spawn viz;
    }

    # DFS visits all 5 reachable nodes too.
    assert len(viz.frames) == 5, f"expected 5 DFS frames, got {len(viz.frames)}";

    # Every frame's visited list must include the current node.
    for f in viz.frames {
        assert f.current in f.visited, (
            f"step {f.step}: current {f.current} not in visited {f.visited}"
        );
    }

    # Stack semantics: when we are at a node, it must be the *front* of the frontier.
    # The walker prepends new nodes, so the most recent node is at index 0.
    for f in viz.frames {
        assert f.frontier[0] == f.current, (
            f"step {f.step}: DFS frontier front {f.frontier[0]} != current {f.current}"
        );
    }

    # All nodes visited exactly once across the whole trace.
    seen = [];
    for f in viz.frames {
        seen.append(f.current);
    }
    assert len(seen) == len(set(seen)), f"DFS visited a node twice: {seen}";
    assert sorted(set(seen)) == ["A", "B", "C", "D", "E"], f"DFS unvisited: {seen}";
}

test "Reachability walker reports connected component" {
    # A -> B -> C, with D isolated from the A-B-C component
    # (D is connected only via Root to keep it a separate component).
    a = GraphNode(label="A");
    b = GraphNode(label="B");
    c = GraphNode(label="C");
    d = GraphNode(label="D");

    root ++> a;
    root ++> d;
    a +>:Adjacent:+> b;
    b +>:Adjacent:+> c;
    # d is isolated (no Adjacent edges from d).

    buf = io.StringIO();
    with redirect_stdout(buf) {
        r = Reachability();
        a spawn r;
    }

    # From a, Reachability should reach exactly A, B, C (3 nodes).
    assert len(r.order) == 3, f"expected 3 reachable from A, got {r.order}";
    assert "A" in r.order, f"A missing from {r.order}";
    assert "B" in r.order, f"B missing from {r.order}";
    assert "C" in r.order, f"C missing from {r.order}";
    # No duplicates.
    assert len(r.order) == len(set(r.order)), f"reachability has duplicates: {r.order}";
}

test "VisualizationFrame fields are populated and per-step consistent" {
    # Small linear graph: X -> Y -> Z
    x = GraphNode(label="X");
    y = GraphNode(label="Y");
    z = GraphNode(label="Z");

    root ++> x;
    x +>:Adjacent:+> y;
    y +>:Adjacent:+> z;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        viz = GraphVisualizer(mode="BFS");
        x spawn viz;
    }

    # Three nodes, three frames.
    assert len(viz.frames) == 3, f"expected 3 frames, got {len(viz.frames)}";

    # visited must be monotonically growing (by set size) across steps.
    prev_size = 0;
    for f in viz.frames {
        cur_size = len(f.visited);
        assert cur_size >= prev_size, (
            f"visited shrank at step {f.step}: {prev_size} -> {cur_size}"
        );
        prev_size = cur_size;
    }

    # First frame: edge_taken is empty (we are at the seed node, no edge yet).
    assert viz.frames[0].edge_taken == "", (
        f"first frame edge_taken should be empty, got '{viz.frames[0].edge_taken}'"
    );

    # Every frame: current node must be in visited.
    for f in viz.frames {
        assert f.current in f.visited, (
            f"step {f.step}: current {f.current} not in visited {f.visited}"
        );
    }

    # Final state: all reachable nodes in visited.
    final_visited = viz.frames[2].visited;
    for label in ["X", "Y", "Z"] {
        assert label in final_visited, f"final visited missing {label}: {final_visited}";
    }
}

