"""App Privacy label release-train demo.

Models the Phase 14 release train: a draft PrivacyLabel is produced by task
T122 and finalized by task T126. Each task is a Task node, and the train gate
(G6) is its own node. Walkers traverse the typed DependsOn / ProducedBy /
ApprovedBy graph to verify ordering and to find every draft that still needs
to be finalized before submission.
"""

node Task {
    has task_id: str = "";
    has title: str = "";
    has status: str = "pending";
}

node PrivacyLabel {
    has label_id: str = "";
    has data_collected: str = "";
    has finalized: bool = False;
}

node Gate {
    has gate_id: str = "";
    has evidence_ok: bool = False;
}

# Typed edges carry the meaning of the relationship.
edge DependsOn {
    has phase: str = "";
}

edge ProducedBy {
    has draft_id: str = "";
}

edge ApprovedBy {
    has reviewer: str = "";
}

walker FinalizeAudit {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_tasks with Task entry {
        self.report.append(f"task {here.task_id} [{here.status}] {here.title}");
        visit [->:DependsOn:->];
    }

    can walk_labels with PrivacyLabel entry {
        marker = "FINAL" if here.finalized else "DRAFT";
        self.report.append(f"label {here.label_id} [{marker}] collects: {here.data_collected}");
        if not here.finalized {
            print(f"label {here.label_id} still needs finalization");
        }
        visit [->:ProducedBy:->];
    }

    can walk_gates with Gate entry {
        verdict = "GREEN" if here.evidence_ok else "BLOCKED";
        self.report.append(f"gate {here.gate_id} [{verdict}]");
        if not here.evidence_ok {
            print(f"gate {here.gate_id} blocks submission");
        }
        visit [-->];
    }
}

# Walker that walks ONLY the typed DependsOn edges to verify that T126's
# predecessor tasks are all completed before submission can be attempted.
walker DependencyChecker {
    has todo: list = [];
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can check_task with Task entry {
        if here.task_id in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.task_id);
        if here.status != "done" {
            self.todo.append(here.task_id);
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    t122 = Task(task_id="T122", title="Draft privacy labels", status="done");
    t126 = Task(task_id="T126", title="Finalize privacy labels", status="in_progress");
