"""Tests for the cycle detector walker."""

import io;
import from contextlib { redirect_stdout }

def build_acyclic_graph {
    root ++> Module(name="app");
    app = [root -->][?:Module][0];
    auth = Module(name="auth");
    db = Module(name="db");
    cache = Module(name="cache");
    app +>: DependsOn() :+> auth;
    app +>: DependsOn() :+> db;
    auth +>: DependsOn() :+> db;
    db +>: DependsOn() :+> cache;
    return [root -->][?:Module];
}

def build_cycle_graph {
    root ++> Module(name="app");
    app = [root -->][?:Module][0];
    a = Module(name="a");
    b = Module(name="b");
    c = Module(name="c");
    d = Module(name="d");
    app +>: DependsOn() :+> a;
    a +>: DependsOn() :+> b;
    b +>: DependsOn() :+> c;
    c +>: DependsOn() :+> d;
    # Back edge: d -> b creates cycle b -> c -> d -> b
    d +>: DependsOn() :+> b;
    return [root -->][?:Module];
}

def build_self_loop_graph {
    root ++> Module(name="app");
    app = [root -->][?:Module][0];
    a = Module(name="a");
    b = Module(name="b");
    app +>: DependsOn() :+> a;
    a +>: DependsOn() :+> b;
    # Self-loop on b: b -> b
    b +>: DependsOn() :+> b;
    return [root -->][?:Module];
}

test "acyclic graph reports no cycle" {
    modules = build_acyclic_graph();
    app = modules[0];
    res = app spawn CycleDetector();
