    # Path must include all three members of the cycle, in order, and close the loop.
    assert "b -> c -> d -> b" in res.found, f"cycle path wrong: {res.found}";
    # The entry point (app) and the acyclic branch (a) must NOT appear in the cycle.
    assert "app" not in res.found, f"non-cycle node leaked into path: {res.found}";
    assert " -> a -> " not in res.found, f"non-cycle node leaked into path: {res.found}";
}

test "self loop b->b is detected" {
    modules = build_self_loop_graph();
    app = modules[0];
    res = app spawn CycleDetector();
