    hub +>: DependsOn() :+> x;
    x +>: DependsOn() :+> y;
    y +>: DependsOn() :+> x;  # cycle x -> y -> x

    res = hub spawn CycleDetector();
    assert res.found != "", "expected the x->y->x cycle";
    assert "x -> y -> x" in res.found, f"wrong cycle path: {res.found}";
    assert "clean" not in res.found, f"clean branch leaked into cycle: {res.found}";
    assert "leaf" not in res.found, f"leaf branch leaked into cycle: {res.found}";
