"""Order auditor: invalid orders are skipped (walk continues),
fraud-flagged orders halt the walk immediately. Each order prints
which branch fired."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
