        if here.fraud {
            print(f"[FRAUD HALT] {here.label} amount={here.amount} — disengaging");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] {here.label} amount={here.amount} — invalid, continuing");
            visit [-->];
        }
        print(f"[AUDIT] {here.label} amount={here.amount}");
        visit [-->];
    }
}

