"""Native OSP model of a scripted MockWire fault sequence."""

node MockWire {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has wire_name: str = "";
}

node WireRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has addressed_node: str = "";
    has bit_rate: int = 0;
}

node WireStep {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "Respond";
    has count: int = 0;
    has seed: int = 0;
    has delay_us: int = 0;
    has target_node: str = "";
    has frame_valid: bool = False;
    has copies: int = 1;
}

edge HasSession { }
edge HasRequest { }
edge ScriptStep {
    has position: int = 0;
}
edge NextStep { }

walker WireAuditor {
    has processed: int = 0;
    has max_steps: int = 16;
    has request_rate: int = 0;
    has request_target: str = "";
    has last_outcome: str = "";
    has garbage_steps: int = 0;
    has crc_errors: int = 0;
    has duplicates: int = 0;
    has babbles: int = 0;

    can begin with Root entry {
        print("starting scripted-wire audit");
        visit [-->] else { disengage; }
    }

    can enter_wire with MockWire entry {
        print(f"wire: {here.wire_name}");
        visit [-->] else { disengage; }
    }

    can inspect_request with WireRequest entry {
        self.request_rate = here.bit_rate;
        self.request_target = here.addressed_node;
        print(f"request for {self.request_target} at {self.request_rate} baud");
        visit [->:ScriptStep:->] else { disengage; }
    }

    can inspect_step with WireStep entry {
        if self.processed >= self.max_steps {
            self.last_outcome = "depth guard";
            print(self.last_outcome);
            disengage;
        } else {
            self.processed += 1;
            address_note = "same target" if here.target_node == self.request_target else "different target";
            outcome = "response queued";

            if here.kind == "Garbage" {
                self.garbage_steps += 1;
                outcome = "garbage discarded";
            } elif here.kind == "CrcError" {
                self.crc_errors += 1;
                outcome = "CRC-invalid response discarded";
            } elif here.kind == "Duplicate" {
                self.duplicates += 1;
                outcome = "response duplicated";
            } elif here.kind == "Babble" {
                self.babbles += 1;
                outcome = f"babble outside response window ({address_note})";
            } elif here.kind == "Rate" {
                if self.request_rate == here.count {
                    outcome = "rate matched";
                } else {
                    rate_mode = "silence" if here.seed == 0 else "garbage";
                    outcome = f"wrong-rate branch: {rate_mode}";
                }
            }

            self.last_outcome = outcome;
            print(f"{here.kind}: {outcome}");
            visit [->:NextStep:->] else { disengage; }
        }
    }
}

