"""Cargo-mutants illumos fix: dependency-graph walk after upgrading fs2 → fs4.

Models the essential scenario: package nodes connected by typed
``Depends`` edges, with attributes that mirror what the project tracks
(build status, lock behavior). A walker traverses the dependency graph,
reproducing the recursive walk the issue describes, while enforcing
cycle safety (which the original hand-rolled recursion relied on) and
reporting a topological-feasible evaluation order so an illumos-broken
dependency can be invalidated/cascade-deleted once the upgrade is in.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has illumos_ok: bool = True;
    has resolved: bool = False;
}

edge Depends {
    has depth: int = 0;
}

walker DependencyAuditor {
    has visited: list[str] = [];
    has order: list[str] = [];
    has stack: list[str] = [];

    can begin with Root entry {
        print("starting dependency audit from root");
        visit [-->];
    }

    can audit with Package entry {
        if here.name in self.visited {
            print(f"  cycle detected at {here.name}; disengaging");
            disengage;
        }
        if here.illumos_ok == False {
            print(f"  [INVALIDATE] {here.name} {here.version} fails on illumos");
            disengage;
        }
        self.visited.append(here.name);
        self.stack.append(here.name);
        stack_size = len(self.stack);
        print(f"  visiting {here.name} {here.version} (stack depth {stack_size})");
        self.order.append(here.name);
        visit [->:Depends:->];
    }
}

walker CascadeInvalidator {
    can begin with Root entry {
        visit [-->];
    }

    can invalidate with Package entry {
        if here.illumos_ok == False {
            print(f"  cascade-invalidating {here.name} dependents");
            here.illumos_ok = True;
            here.resolved = True;
            visit [->:Depends:->];
        } else {
            visit [-->];
        }
    }
}

