"""Gallery security console.

Every visitor is logged generically when entering a room, but when a
curator walks in, the room additionally records an official inspection
under the curator's name and increments their inspection count. A
plain tourist only triggers the generic log. Run one tourist and one
curator through two rooms to show the difference.
"""

node Room {
    has name: str = "";
    has inspections: list[str] = [];

    def log_visit(visitor_name: str) -> None {
        print(f"  log: {visitor_name} entered {self.name}");
    }

    def record_inspection(curator_name: str) -> None {
        self.inspections.append(curator_name);
        print(f"  inspection recorded for {curator_name} in {self.name}");
    }
}

walker Tourist {
    has visitor_name: str = "";

    can start with Root entry {
        print(f"Tourist {self.visitor_name} begins tour");
        visit [-->];
    }

    can enter with Room entry {
        here.log_visit(self.visitor_name);
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has inspection_count: int = 0;

    can start with Root entry {
        print(f"Curator {self.curator_name} begins walkthrough");
        visit [-->];
    }

    can enter with Room entry {
        here.log_visit(self.curator_name);
        here.record_inspection(self.curator_name);
        self.inspection_count += 1;
        visit [-->];
    }
}

with entry {
    gallery_a = Room(name="Gallery A");
    gallery_b = Room(name="Gallery B");
    root ++> gallery_a ++> gallery_b;

    print("=== Tourist pass ===");
    t = Tourist(visitor_name="Alice");
    root spawn t;

    print("=== Curator pass ===");
    c = Curator(curator_name="Dr. Bell");
    root spawn c;

    print(
        f"\nFinal tally: tourist logged visits only, "
        f"curator recorded {c.inspection_count} official inspections"
    );
    print(f"Inspections on record: Gallery A -> {gallery_a.inspections}, "
          f"Gallery B -> {gallery_b.inspections}");
}
