"""SEO execution router: model the revenue-first canonical-owner graph
from the SEO12 backlog as typed nodes and edges, then walk it with a
router that performs cascade invalidation and dependency ordering."""

# Canonical SEO owner pages — each owns a slice of the revenue graph.
node OwnerPage {
    has slug: str = "";
    has decision: str = "PENDING";
    has rank: float = 0.0;
    has clicks: int = 0;
    has impressions: int = 0;
}

# Evidence records that justify or block a rewrite decision.
node Evidence {
    has label: str = "";
    has klass: str = "";
    has window_days: int = 0;
}

# Closed subrouters — provenance only, must NOT be re-executed.
node ClosedSubrouter {
    has ticket: str = "";
    has reason: str = "";
}

# Bounded authority handoffs between owners (typed edge carries meaning).
edge AuthorityHandoff {
    has bounded: bool = True;
    has regression_protected: bool = False;
}

# Edge used to flag "competing execution paths" that must not be revived.
edge CompetingPath {
    has ticket: str = "";
}

# Edge marking a closed-subrouter provenance link to its topic owner.
edge Provenance {
    has ticket: str = "";
}

walker Router {
    has visited: list = [];
    has invalidations: list = [];

    can start with Root entry {
        print("=== SEO execution router walk ===");
        visit [-->];
    }

    can scan with OwnerPage entry {
        # Cascade invalidation: if impressions exist but clicks are zero,
        # we cannot safely call it a snippet-only problem — mark for
        # observation window instead of repeat rewrite.
        ctr = (here.clicks / here.impressions) if here.impressions > 0 else 0.0;
        here.decision = "OBSERVATION_WINDOW_ACTIVE" if (here.impressions > 0 and here.clicks == 0) else here.decision;
        self.invalidations.append(
            (here.slug, here.decision, round(ctr, 4))
        );
        self.visited.append(here.slug);
        visit [-->];
    }

    can note_closed with ClosedSubrouter entry {
        print(f"closed provenance: #{here.ticket} — {here.reason}");
        visit [-->];
    }

    can note_evidence with Evidence entry {
        print(f"evidence[{here.klass}] {here.label} window={here.window_days}d");
        visit [-->];
    }
}

with entry {
    # Canonical owners (the ones the router must protect).
    logistics = OwnerPage(
        slug="/services/seo-for-logistics-companies/",
        decision="KEEP_OWNER",
        rank=62.65,
        clicks=0,
        impressions=242
    );
    loadboard = OwnerPage(
        slug="/load-board/",
        decision="CANONICAL_CONTRACT_COMPLETE"
    );
    appleton = OwnerPage(
        slug="/logistics/appleton-wi-vehicle-transport/",
        decision="INTENT_MISMATCH"
    );

    # Closed subrouters — provenance only, do not revive.
    cl1 = ClosedSubrouter(ticket="461", reason="demand activation — engineering complete");
    cl2 = ClosedSubrouter(ticket="465", reason="U.S.-desktop investigation — repo diagnosis complete");
    cl3 = ClosedSubrouter(ticket="377", reason="GSC achievement tracker — duplicate, closed");

    # Evidence checkpoint (the 18-day window that must not be re-baselined).
    checkpoint = Evidence(
        label="owner-provided GSC batch 2026-07-30..2026-08-16",
        klass="OWNER_PROVIDED_HANDOFF",
        window_days=18
    );

    # Wire the graph: root -> owners, owners -> evidence, owners -> closed provenance,
    # and bounded authority handoffs between owners (typed edges).
    root ++> logistics ++> loadboard ++> appleton;
    logistics +>:AuthorityHandoff(bounded=True, regression_protected=True):+> checkpoint;
    loadboard +>:Provenance(ticket="461"):+> cl1;
    appleton +>:Provenance(ticket="465"):+> cl2;
    logistics +>:Provenance(ticket="377"):+> cl3;

    # Spawn the router on root and let it cascade-walk owners + provenance.
    router = Router();
    root spawn router;

    print("--- router summary ---");
    for (slug, decision, ctr) in router.invalidations {
        print(f"{slug}: decision={decision} ctr={ctr}");
    }
}
