    has wording: str = "";
    has level: str = "raw";
    has published: bool = False;
}

node Artifact {
    has title: str = "";
    has digest: str = "";
    has claim_status: str = "raw";
    has endpoint_resolutions_applied: int = 0;
}

node Invalidator {
    has title: str = "";
    has reason: str = "";
}

edge SupportedBy {
    has weight: float = 1.0;
}

edge InvalidatedBy {
}

node Manifest {
    has title: str = "";
    has decision_text: str = "";
}

node Prose {
    has title: str = "";
    has body: str = "";
    has kind: str = "readme";
}

walker TruthGate {
    has failures: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can check_manifest with Manifest entry {
        print(f"[manifest] {here.title}: {here.decision_text}");
        if "bound" in here.decision_text or "certified" in here.decision_text {
