            print(f"  [prose-claim] '{here.title}' asserts bound/certified");
            self.failures += 1;
        }
        visit [-->];
    }

    can check_claim with Claim entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
        }
        level_seen = "raw";
        inv_count = 0;
        for child in [->:SupportedBy:->] {
            if isinstance(child, Artifact) {
