"""Tests for the epistemic claim registry walker (issue #146).

Each test builds a fresh graph, spawns TruthGate, captures stdout, and
asserts the gate's behavior against the issue's required semantics:
- prose claiming "bound"/"certified" while endpoint_resolutions_applied==0 fails
- the failure counter and visited list reflect what was actually walked
- an Invalidator edge is counted but does not mask the upstream violation
- a fully-resolved artifact with matching wording passes
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: the canonical violation from the issue — README/paper/manifest all
# claim "bound/certified" while the underlying artifact has zero endpoint
# resolutions applied. The walker must flag the claim violation (1) plus each
# prose/manifest mention (3) for a total of 4 failures, and must visit the
# claim once.
# ---------------------------------------------------------------------------
test "canonical violation: prose claims bound while resolutions are zero" {
    artifact = Artifact(
        title="V1_MIXED_CANONICAL_PRINCIPAL_LEFT",
        digest="sha256:deadbeef",
        claim_status="high_precision_supported",
        endpoint_resolutions_applied=0
    );
    main_claim = Claim(
        title="component-12 mixed_principal_left",
        wording="component-12 high bound to mixed_principal_right by a certified variational step",
        level="high",
        published=True
    );
    invalidator = Invalidator(
        title="no side-specific continuous evidence yet",
        reason="canonical assembly has not accepted new continuous evidence"
    );
    readme = Prose(
        title="README status",
        body="plus_one component-12 high ... bound ... by a certified variational step",
        kind="readme"
    );
    paper = Prose(
        title="manuscript abstract",
        body="six certified label-invisible event-sign polylines",
        kind="paper"
    );
    manifest = Manifest(
        title="DISCOVERY_RELEASE.json",
        decision_text="component-12 high bound to mixed_principal_right"
    );

    root ++> manifest;
    root ++> readme;
    root ++> paper;
    root ++> main_claim;
    main_claim +>:SupportedBy:+> artifact;
    main_claim +>:InvalidatedBy:+> invalidator;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TruthGate();
    }
    out = buf.getvalue();

    # the claim's wording says "bound"/"certified" and its only artifact has
    # endpoint_resolutions_applied==0 -> exactly one [violation] line.
    assert out.count("[violation]") == 1, f"expected one claim violation, got: {out!r}";
    # three static-text sources (readme, paper, manifest) each assert bound/certified.
    assert out.count("[manifest-claim]") == 1, f"expected one manifest-claim flag: {out!r}";
    assert out.count("[prose-claim]") == 2, f"expected two prose-claim flags (readme+paper): {out!r}";
    # total failures = 1 violation + 1 manifest + 2 prose = 4.
    assert res.failures == 4, f"expected 4 failures, got {res.failures}";
    # the claim itself is visited exactly once (idempotent via the visited list).
    assert res.visited == ["component-12 mixed_principal_left"], f"unexpected visited: {res.visited}";
    # the invalidator edge is counted and reported in the per-claim summary.
    assert "invalidators=1" in out, f"expected invalidators=1 in output: {out!r}";
}

# ---------------------------------------------------------------------------
# Test 2: a clean graph — no "bound"/"certified" wording anywhere, the artifact
# has resolutions applied. The walker must produce zero failures and visit
# the claim without complaint.
# ---------------------------------------------------------------------------
test "clean graph: no bound/certified wording, artifact is resolved" {
    artifact = Artifact(
        title="clean_resolution_artifact",
        digest="sha256:cleanch",
        claim_status="independently_reproduced",
        endpoint_resolutions_applied=3
    );
    clean_claim = Claim(
        title="clean component claim",
        wording="a sampled multi-point polyline piece across the sweep",
        level="sampled",
        published=True
    );
    clean_readme = Prose(
        title="clean README",
        body="sampled event-sign pieces were collected and reported",
        kind="readme"
    );
    clean_paper = Prose(
        title="clean paper",
        body="we enumerate the historical S/U transitions",
        kind="paper"
    );
    clean_manifest = Manifest(
        title="clean manifest",
        decision_text="sampled event-sign pieces collected, no endpoint claimed"
    );

    root ++> clean_manifest;
    root ++> clean_readme;
    root ++> clean_paper;
    root ++> clean_claim;
    clean_claim +>:SupportedBy:+> artifact;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TruthGate();
    }
    out = buf.getvalue();

    assert res.failures == 0, f"clean graph must have 0 failures, got {res.failures}: {out!r}";
    assert "[violation]" not in out, f"clean graph must not emit a violation: {out!r}";
    assert "[manifest-claim]" not in out, f"clean graph must not flag manifest: {out!r}";
    assert "[prose-claim]" not in out, f"clean graph must not flag prose: {out!r}";
    # the claim was still walked and its visited entry recorded.
    assert "clean component claim" in res.visited, f"claim not visited: {res.visited}";
}

# ---------------------------------------------------------------------------
# Test 3: the graph-shape contract — edges of declared types are actually
# wired. The walker reaches the artifact only via SupportedBy and the
# invalidator only via InvalidatedBy.
# ---------------------------------------------------------------------------
test "edge wiring: SupportedBy reaches artifact, InvalidatedBy reaches invalidator" {
    artifact = Artifact(
        title="wired_artifact",
        digest="sha256:wire",
        claim_status="canonically_bound_incidence",
        endpoint_resolutions_applied=2
    );
    claim_node = Claim(
        title="wired claim",
        wording="canonically accepted incidence on the corrected isolated root",
        level="canonically_bound"
    );
    inv = Invalidator(
        title="threshold-dependent attachment",
        reason="attachment is threshold-dependent and not yet continuous"
    );

    root ++> claim_node;
    claim_node +>:SupportedBy:+> artifact;
    claim_node +>:InvalidatedBy:+> inv;

    # structural assertions on the freshly-built graph
    claim_children_sup = [claim_node ->:SupportedBy:->];
    claim_children_inv = [claim_node ->:InvalidatedBy:->];
    assert len(claim_children_sup) == 1, f"SupportedBy edge missing: {claim_children_sup}";
    assert len(claim_children_inv) == 1, f"InvalidatedBy edge missing: {claim_children_inv}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TruthGate();
    }
    out = buf.getvalue();

    # the claim's wording contains "canonically accepted" (no "bound"/"certified"
    # substring on its own), and the artifact has resolutions > 0, so no
    # violation fires even though the wording is strong.
    assert "[violation]" not in out, f"unexpected violation on wired graph: {out!r}";
    # artifact claim_status must be propagated through to the per-claim line.
    assert "artifact_level=canonically_bound_incidence" in out, f"artifact level not propagated: {out!r}";
    assert "invalidators=1" in out, f"invalidator not reached: {out!r}";
    assert res.failures == 0, f"wired graph should have no failures, got {res.failures}: {out!r}";
}

