            print(f"[SHOT] {here.name} the {here.species} got a vaccine");
        } else {
            print(f"[SKIP] {here.name} the {here.species} is up to date");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="dog")
        ++> Pet(name="Pancake", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Pepper", species="cat", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\n--- Round summary ---");
    print(f"Patients seen ({len(vet.patient_log)}): {vet.patient_log}");
    print(f"Shots given: {vet.shots_given}");
}
