# Helper to run the librarian walker against a freshly built graph and
# capture exactly what it prints to stdout.
def _run_librarian(books: list) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        # Build a fresh root -> Book chain for this test invocation.
        for b in books {
            root ++> b;
        }
        root spawn Librarian();
    }
    return buf.getvalue();
}

test "all books are printed with their IN/OUT status" {
    b1 = Book(title="Dune", year=1965);
    b2 = Book(title="Neuromancer", year=1984);
    b3 = Book(title="Circe", year=2018, available=False);

    out = _run_librarian([b1, b2, b3]);

    # Every book must appear in the output.
    assert "[IN] Dune (1965)" in out, f"missing Dune line: {out}";
    assert "[IN] Neuromancer (1984)" in out, f"missing Neuromancer line: {out}";
    assert "[OUT] Circe (2018)" in out, f"missing Circe line: {out}";

    # Count lines: one printed line per Book visited.
    lines = [l for l in out.splitlines() if l.strip()];
    assert len(lines) == 3, f"expected 3 printed lines, got {len(lines)}: {out}";
}

test "available defaults to True and year defaults to 0" {
    b_default = Book(title="Untitled");
    assert b_default.available == True, f"available should default to True, got {b_default.available}";
    assert b_default.year == 0, f"year should default to 0, got {b_default.year}";
    assert b_default.title == "Untitled", f"title should be 'Untitled', got {b_default.title}";

    # Walking this default-valued book should print [IN] ... (0).
    out = _run_librarian([b_default]);
    assert "[IN] Untitled (0)" in out, f"default IN/0 line missing: {out}";
}

test "IN/OUT status reflects the available flag" {
    b_in = Book(title="Alpha", year=2000);            # available defaults True
    b_out = Book(title="Beta", year=2010, available=False);

    out = _run_librarian([b_in, b_out]);

    assert "[IN] Alpha (2000)" in out, f"Alpha should be IN: {out}";
    assert "[OUT] Beta (2010)" in out, f"Beta should be OUT: {out}";

    # Sanity: no misclassified lines.
    assert "[OUT] Alpha" not in out, f"Alpha wrongly printed as OUT: {out}";
    assert "[IN] Beta" not in out, f"Beta wrongly printed as IN: {out}";
}

test "graph shape: root links directly to a chain of books" {
    a = Book(title="A");
    b = Book(title="B");
    c = Book(title="C");

    root ++> a ++> b ++> c;

    # Chain means root has exactly one direct child (a).
    direct = [root -->];
