    assert len([b -->]) == 1, f"b should have 1 direct child, got {len([b -->])}";
    assert [b -->][0] == c, "b's direct child should be c";
    assert len([c -->]) == 0, f"c should have 0 direct children, got {len([c -->])}";
}

test "walker traverses every book reachable from root" {
    b1 = Book(title="One");
    b2 = Book(title="Two");
    b3 = Book(title="Three");

    out = _run_librarian([b1, b2, b3]);

