        }
        if not here.valid {
            print(f"SKIP  invalid order {here.label} (${here.amount:.2f})");
            visit [-->];
        }
        print(f"OK    {here.label} (${here.amount:.2f})");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="A-100", amount=49.99)
        ++> Order(label="A-101", amount=120.00, valid=False)
        ++> Order(label="A-102", amount=310.50)
        ++> Order(label="A-103", amount=85.25, fraud=True)
        ++> Order(label="A-104", amount=22.00);
    root spawn OrderAuditor();
}
