"""Tiny dungeon crawler: a chain of rooms with one treasure vault.

A Hunter walker advances room-by-room, counting how many rooms it has
seen. As soon as it enters the vault (treasure room) it disengages so
that no room downstream of the vault is ever visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        if here.has_treasure {
            print(f"[{self.rooms_seen}] {here.name} -- TREASURE FOUND! Hunter stops here.");
            disengage;
        } else {
            print(f"[{self.rooms_seen}] {here.name} -- empty, pressing on...");
            visit [-->];
        }
    }
}

with entry {
    root ++> Room(name="Entrance Hall")
        ++> Room(name="Mossy Corridor")
        ++> Room(name="Flooded Chamber")
        ++> Room(name="Old Armory")
        ++> Room(name="Treasure Vault", has_treasure=True)
        ++> Room(name="Forbidden Passage")
        ++> Room(name="Dragon's Lair");

    root spawn Hunter();
    print("Hunter has finished the hunt.");
}
