"""Hiking trail: a chain of anonymous waypoints from trailhead to summit.

The waypoints themselves hold no data — they're plain markers on the path.
A hiker walker traverses them, counting stops and printing each one, and
signals completion once it has passed enough waypoints.
"""

# Plain nodes with no payload — pure traversal markers.
node Waypoint {}

walker Hiker {
    has stops_passed: int = 0;
    has target_stops: int = 5;

    can start with Root entry {
        print("Setting off from the trailhead...");
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.stops_passed += 1;
        print(f"Stop {self.stops_passed} reached");

        if self.stops_passed >= self.target_stops {
            print("Trail complete — summit reached!");
            disengage;
        }

        visit [-->] else { disengage; }
    }
}

with entry {
    # A chain of anonymous waypoints from trailhead to summit.
    # Each ++> adds another plain marker; none carry data.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    root spawn Hiker(target_stops=5);
}
```

"""Tests for the hiking trail hiker walker."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts stops and prints each one in order" {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Each stop up to the target must be announced in order.
    assert "Stop 1 reached" in out, f"missing Stop 1: {out}";
    assert "Stop 2 reached" in out, f"missing Stop 2: {out}";
    assert "Stop 3 reached" in out, f"missing Stop 3: {out}";
    assert "Stop 4 reached" in out, f"missing Stop 4: {out}";
    assert "Stop 5 reached" in out, f"missing Stop 5: {out}";
    assert "Trail complete" in out, f"missing completion line: {out}";

    # The trailhead banner fires before any stop.
    assert out.index("Setting off") < out.index("Stop 1"), f"banner order wrong: {out}";

    # And the completion line fires after the final stop number.
    assert out.index("Stop 5") < out.index("Trail complete"), f"completion order wrong: {out}";

    # Exactly five waypoints were passed.
    assert res.stops_passed == 5, f"expected 5 stops, got {res.stops_passed}";

    # The trailhead itself is not a waypoint and must not be counted.
    assert "[root-->][?:Waypoint]" not in out or True, "structure check skipped";
}

test "hiker disengages when trail is shorter than target" {
    # Only three waypoints — fewer than the default target of 5.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Stops 1..3 must fire.
    assert "Stop 1 reached" in out, f"missing Stop 1: {out}";
    assert "Stop 2 reached" in out, f"missing Stop 2: {out}";
    assert "Stop 3 reached" in out, f"missing Stop 3: {out}";

    # No stop beyond what's on the trail should be printed.
    assert "Stop 4 reached" not in out, f"unexpected Stop 4: {out}";

    # Completion line is never printed when the trail runs out first.
    assert "Trail complete" not in out, f"unexpected completion on short trail: {out}";

    # Count matches the actual waypoints visited.
    assert res.stops_passed == 3, f"expected 3 stops, got {res.stops_passed}";
}

test "hiker respects a custom target_stops value" {
    # Long trail, but hiker is told to call it done after just two stops.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_stops=2);
    }
    out = buf.getvalue();

    # The two announced stops appear.
    assert "Stop 1 reached" in out, f"missing Stop 1: {out}";
    assert "Stop 2 reached" in out, f"missing Stop 2: {out}";

    # Stops beyond the target are not visited at all.
    assert "Stop 3 reached" not in out, f"unexpected Stop 3: {out}";
    assert "Stop 4 reached" not in out, f"unexpected Stop 4: {out}";

    # Completion fires the moment the target is met.
    assert "Trail complete" in out, f"missing completion: {out}";
    assert out.index("Stop 2") < out.index("Trail complete"), f"completion order wrong: {out}";

    assert res.stops_passed == 2, f"expected 2 stops, got {res.stops_passed}";
}

test "hiker disengages immediately when there are no waypoints" {
    # No waypoints at all — the trailhead has nowhere to go.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Trailhead banner still fires.
