    assert res.stops_passed == 0, f"expected 0 stops, got {res.stops_passed}";

    # Graph shape: the root has no outgoing waypoint edges.
    waypoints = [root -->];
    assert len(waypoints) == 0, f"expected no waypoints, got {len(waypoints)}";
}

