"""Factory zone monitoring with a single patrol routine for both sensor types.

One walker ability handles two sensor archetypes via a union trigger,
printing each reading as nominal or an alert, and summarizing the
alerts at the end.
"""

node Sensor {
    has label: str = "";
    has reading: float = 0.0;

    def is_alert() -> bool {
        return False;
    }

    def kind() -> str {
        return "Sensor";
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }

    override def kind() -> str {
        return "TempSensor";
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }

    override def kind() -> str {
        return "SmokeSensor";
    }
}

node Zone {
    has name: str = "";
}

walker Patrol {
    has alert_log: list[str] = [];
    has nominal_count: int = 0;
    has alert_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with Zone entry {
        print(f"--- Patrolling zone: {here.name} ---");
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        is_alerting = here.is_alert();
        if is_alerting {
            self.alert_count += 1;
            line = f"[ALERT]   {here.kind()} '{here.label}' -> {here.reading}";
            self.alert_log.append(line);
        } else {
            self.nominal_count += 1;
            line = f"[nominal] {here.kind()} '{here.label}' -> {here.reading}";
        }
        print(line);
    }
}

with entry {
    zone_a = Zone(name="Assembly");
    zone_b = Zone(name="Packaging");

    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="T-A1", reading=68.0, celsius=68.0);
    zone_a ++> TempSensor(label="T-A2", reading=91.5, celsius=91.5);
    zone_a ++> SmokeSensor(label="S-A1", reading=12.0, ppm=12.0);

    zone_b ++> TempSensor(label="T-B1", reading=74.9, celsius=74.9);
    zone_b ++> SmokeSensor(label="S-B1", reading=75.0, ppm=75.0);
    zone_b ++> SmokeSensor(label="S-B2", reading=20.0, ppm=20.0);

    patrol = Patrol();
    root spawn patrol;

    print("");
    print(f"Summary: {patrol.alert_count} alert(s), {patrol.nominal_count} nominal");
    if patrol.alert_count > 0 {
        print("Alerts:");
        for entry in patrol.alert_log {
            print(f"  {entry}");
        }
    }
}
