"""Bug tracker: file tickets off a project node and grab the fresh ticket in one expression.

Each `++>` connection returns the newly attached node, so we can capture
the brand-new ticket and immediately inspect its title and priority
without a follow-up lookup query.
"""

node Project {
    has title: str = "";
}

node Ticket {
    has title: str = "";
    has priority: int = 0;
}

walker Triage {
    can start with Root entry {
        visit [-->];
    }

    can triage with Ticket entry {
        print(f"Ticket: {here.title} (priority {here.priority})");
        visit [-->];
    }
}

with entry {
    # `++>` returns the connected node; capture it inline with `:=`.
    bug1 = root ++> Project(title="Compiler")
        ++> Ticket(title="segfault on lambda capture", priority=1);

    print(f"Filed: {bug1.title} @ priority {bug1.priority}");

    bug2 = root ++> Ticket(title="type error in union trigger", priority=2);
    print(f"Filed: {bug2.title} @ priority {bug2.priority}");

    root spawn Triage();
}
