"""Tests for the bug tracker program: verify that `++>` returns the
freshly-attached node so callers can inspect it inline."""

import io;
import from contextlib { redirect_stdout }

# ---------- test 1: `++>` returns the project it just attached ----------
test "plusplus returns project node inline" {
    root ++> Project(title="Compiler");
    p = root ++> Project(title="Runtime");
    assert isinstance(p, Project), f"++> must return a Project, got {type(p)}";
    assert p.title == "Runtime", f"expected inline title 'Runtime', got {p.title!r}";
}

# ---------- test 2: chained `++>` returns the leaf ticket, not the project ----------
test "chained plusplus returns the final ticket" {
    p = root ++> Project(title="Compiler");
    t = p ++> Ticket(title="segfault on lambda capture", priority=1);
    # The chained expression must hand back the Ticket, not the Project.
    assert isinstance(t, Ticket), f"chained ++> must return Ticket, got {type(t)}";
    assert t.title == "segfault on lambda capture", f"bad title: {t.title!r}";
    assert t.priority == 1, f"bad priority: {t.priority}";
}

# ---------- test 3: full demo shape — root ++> Ticket prints title+priority ----------
test "root plusplus ticket captures inline title and priority" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        bug = root ++> Ticket(title="type error in union trigger", priority=2);
        print(f"Filed: {bug.title} @ priority {bug.priority}");
    }
    out = buf.getvalue();
    assert "Filed: type error in union trigger @ priority 2" in out, (
        f"inline inspection of fresh ticket missing from output: {out!r}"
    );
    # And the ticket is actually attached to root.
    assert bug in [root -->], "fresh ticket must be attached to root via ++>";
    assert bug.priority == 2, f"priority lost: {bug.priority}";
    assert bug.title == "type error in union trigger", f"title lost: {bug.title!r}";
}

# ---------- test 4: graph shape — Project holds its tickets as children ----------
test "project owns its tickets through plusplus" {
    p = root ++> Project(title="Compiler");
    t1 = p ++> Ticket(title="segfault on lambda capture", priority=1);
    t2 = p ++> Ticket(title="missing newline in error", priority=3);
    kids = [p -->];
    assert len(kids) == 2, f"Project should hold 2 tickets, holds {len(kids)}";
    assert t1 in kids and t2 in kids, "both filed tickets must be children of Project";
}

