"""Tests for the build-system dependency auditor.

The program's behavior under test:
- Each unique Task (matched by title) is audited exactly once, even when the
  graph contains a diamond and the walker reaches it via multiple paths.
- The walker accumulates minutes across the whole graph but does not double-
  count the shared task.
- Re-visits of an already-audited task emit a [skip] marker rather than
  adding minutes again.
- A linear (non-diamond) chain still audits every node in order.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. Diamond graph: shared `link-shared` reachable from two paths.
# ---------------------------------------------------------------------------
test "diamond counts shared task exactly once" {
    core = root ++> Task(title="compile-core", minutes=5);
    link_shared = core ++> Task(title="link-shared", minutes=3);
    modA = core ++> Task(title="compile-modA", minutes=4);
    modB = core ++> Task(title="compile-modB", minutes=4);
    pkg_a = modA ++> Task(title="package", minutes=2);
    pkg_b = modB ++> Task(title="package", minutes=2);

    # Note: link_shared --|> package is implicit only if we add it; the
    # program's demo graph does include it, so mirror that.
    pkg_c = link_shared ++> Task(title="package", minutes=2);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    # Every unique task should have been audited exactly once. Five unique
    # titles in this graph; sum of their minutes = 5+3+4+4+2 = 18.
    assert res.total_minutes == 18, f"expected 18 unique minutes, got {res.total_minutes}";

    # visited-set must list each unique title exactly once.
    assert len(res.visited) == 5, f"expected 5 unique visits, got {len(res.visited)}";
    for t in ["compile-core", "link-shared", "compile-modA", "compile-modB", "package"] {
        assert res.visited.count(t) == 1, f"{t} visited {res.visited.count(t)} times, want 1";
    }

    # The diamond's shared task must be reported as audited (not skipped)
    # the first time it is reached.
    assert "[audit] link-shared (3 min)" in out, f"missing link-shared audit: {out!r}";

    # Because `package` is reachable from three predecessors, the walker
    # will hit it more than once. There must be exactly one [audit] for it
    # and at least one [skip].
    audit_pkg = out.count("[audit] package (2 min)");
    skip_pkg = out.count("[skip] package already audited");
    assert audit_pkg == 1, f"expected 1 [audit] for package, got {audit_pkg}: {out!r}";
    assert skip_pkg >= 1, f"expected at least 1 [skip] for package, got {skip_pkg}: {out!r}";
}

# ---------------------------------------------------------------------------
# 2. Linear chain (no diamond): every node audited exactly once, no skips.
# ---------------------------------------------------------------------------
test "linear chain audits every node exactly once" {
    a = root ++> Task(title="a", minutes=1);
    b = a ++> Task(title="b", minutes=2);
    c = b ++> Task(title="c", minutes=3);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.total_minutes == 6, f"linear sum should be 1+2+3=6, got {res.total_minutes}";
    assert len(res.visited) == 3, f"expected 3 unique visits, got {len(res.visited)}";
    assert res.visited == ["a", "b", "c"], f"unexpected order: {res.visited}";

    # No task is reachable twice on a straight chain, so no [skip] lines.
    assert "[skip]" not in out, f"linear chain produced skip lines: {out!r}";

    # Each task should appear in an [audit] line in order.
    assert "[audit] a (1 min)" in out, out;
    assert "[audit] b (2 min)" in out, out;
    assert "[audit] c (3 min)" in out, out;
}

# ---------------------------------------------------------------------------
# 3. Trivial single-task graph: edge case for the visit-set guard.
# ---------------------------------------------------------------------------
test "single task graph audits once and totals its minutes" {
    only = root ++> Task(title="only", minutes=7);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.total_minutes == 7, f"single task minutes should be 7, got {res.total_minutes}";
    assert res.visited == ["only"], f"visited should be ['only'], got {res.visited}";
    assert "[audit] only (7 min)" in out, out;
    assert "[skip]" not in out, out;
}

# ---------------------------------------------------------------------------
# 4. Diamond with a deeper shared suffix: proves the guard works at any depth.
#    Both `mid1` and `mid2` feed into the same `tail` task.
# ---------------------------------------------------------------------------
test "diamond at deeper level is also deduped" {
    head = root ++> Task(title="head", minutes=2);
    mid1 = head ++> Task(title="mid1", minutes=3);
    mid2 = head ++> Task(title="mid2", minutes=4);
    tail_a = mid1 ++> Task(title="tail", minutes=5);
    tail_b = mid2 ++> Task(title="tail", minutes=5);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    # Unique titles: head, mid1, mid2, tail -> 2+3+4+5 = 14.
    assert res.total_minutes == 14, f"expected 14, got {res.total_minutes}";
    assert len(res.visited) == 4, f"expected 4 unique visits, got {len(res.visited)}";
    assert res.visited.count("tail") == 1, f"tail visited {res.visited.count('tail')} times";

    # Exactly one [audit] for the shared tail and at least one [skip].
    assert out.count("[audit] tail (5 min)") == 1, out;
    assert out.count("[skip] tail already audited") >= 1, out;
}

# ---------------------------------------------------------------------------
# 5. Two separate diamonds sharing no tasks: each shared task is still
#    audited exactly once within its own diamond.
# ---------------------------------------------------------------------------
test "multiple disjoint diamonds each dedupe their own shared task" {
    # Diamond 1: a -> b, a -> c, b -> d, c -> d
    a = root ++> Task(title="a", minutes=1);
    b = a ++> Task(title="b", minutes=2);
    c = a ++> Task(title="c", minutes=3);
    d1 = b ++> Task(title="d", minutes=4);
    d2 = c ++> Task(title="d", minutes=4);

    # Diamond 2: separate, no shared titles with diamond 1.
    e = root ++> Task(title="e", minutes=5);
    f = e ++> Task(title="f", minutes=6);
    g = e ++> Task(title="g", minutes=7);
    h1 = f ++> Task(title="h", minutes=8);
    h2 = g ++> Task(title="h", minutes=8);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    # Unique titles: a,b,c,d,e,f,g,h -> 1+2+3+4+5+6+7+8 = 36.
    assert res.total_minutes == 36, f"expected 36, got {res.total_minutes}";
    assert len(res.visited) == 8, f"expected 8 unique visits, got {len(res.visited)}";

    # Each shared sink audited once, skipped at least once.
    assert out.count("[audit] d (4 min)") == 1, out;
    assert out.count("[audit] h (8 min)") == 1, out;
    assert out.count("[skip] d already audited") >= 1, out;
    assert out.count("[skip] h already audited") >= 1, out;
}

