"""Gallery security console.

Generic visitors trigger a plain entry log; curators trigger the same log
PLUS an official inspection record attached to the room and a personal
inspection counter. A union ability on the room handles both cases.
"""

node Room {
    has room_name: str = "";
    has log: list[str] = [];
    has inspections: list[str] = [];
}

walker Visitor {
    has visitor_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"entry: {self.visitor_name}");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # Curator entry: same generic log PLUS an official inspection.
    can inspect with Room entry {
        here.log.append(f"entry: {self.curator_name}");
        here.inspections.append(f"inspection by {self.curator_name}");
        self.rooms_inspected += 1;
        visit [-->];
    }
}

with entry {
    room_a = Room(room_name="Gallery A");
    room_b = Room(room_name="Gallery B");
    root ++> room_a ++> room_b;

    tourist = Visitor(visitor_name="Alice");
    root spawn tourist;

    curator = Curator(curator_name="Dr. Bell");
