"""Beads-style dependency graph with visited-set cycle detection.

Models the core scenario from issue #5887: a tree renderer that recurses
along parent-child and blocks edges without a visited set blows up on a
single cycle (here, an epic blocked by its own child). The idiomatic Jac
form moves the recursion into walkers over typed edges and keeps an
explicit visited set as cycle policy (jac 0.36.1 walkers have no built-in
once-per-node visitation).
"""

node Issue {
    has title: str = "";
    has kind: str = "task";
    has available: bool = True;
}

edge ParentChild { }
edge Blocks { }

walker TreeRender {
    has max_depth: int = 32;
    has report: list[str] = [];
    has seen: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can walk_children with Issue entry {
        key = f"{here.kind}:{here.title}";
        depth = self.report.__len__();
        if depth >= self.max_depth or key in self.seen {
            if key in self.seen {
                self.report.append(f"  ↺ [cycle skipped] {here.title}");
            }
            return;
        }
        self.seen.add(key);
        indent = "  " * (depth if depth < 4 else 4);
        self.report.append(f"{indent}- {here.kind}: {here.title}");
        visit [->:ParentChild:->];
    }

    can walk_blocked with Issue entry {
        key = f"{here.kind}:{here.title}";
        if key in self.seen {
            self.report.append(f"  ↺ [cycle skipped] {here.title}");
            return;
        }
        depth = self.report.__len__();
        self.report.append(f"{'  ' * (depth if depth < 4 else 4)}  [blocks] {here.title}");
        visit [->:Blocks:->];
    }
}

walker VisitGuard {
    has seen: set[str] = set();
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can guard with Issue entry {
        key = f"{here.kind}:{here.title}";
        if key in self.seen {
            self.report.append(f"[cycle skipped] {key}");
            return;
        }
        self.seen.add(key);
        self.report.append(f"visit {key}");
        visit [-->];
    }
}

with entry {
    epic = Issue(title="z6nr.41", kind="epic");
    child = Issue(title="z6nr.40", kind="task");
    root ++> epic ++> child;

    child +>:ParentChild:+> epic;
    epic +>:Blocks:+> child;

    print("=== tree render (bounded, with visited guard) ===");
    tr = TreeRender(max_depth=8);
    root spawn tr;
    for line in tr.report {
        print(line);
    }

    print("\n=== generic VisitGuard walker (mirrors the suggested fix) ===");
    vg = VisitGuard();
    root spawn vg;
    for line in vg.report {
        print(line);
    }

    print("\ncycle present in graph: child -ParentChild-> epic -Blocks-> child");
}
