    has audience: str = "";
    has selected: bool = False;
}

edge HasSession { }
edge OwnsTask { }
edge ReadsDocument { }
edge ContainsSlice { }
edge SelectsSlice { }
edge Spawns {
    has attempt: int = 0;
}

walker RlmExecutor {
    has max_calls: int = 6;
    has max_tokens: int = 64;
    has max_depth: int = 2;
    has attempted_calls: int = 0;
    has completed_calls: int = 0;
