    assert stop_lines[3] == "Stop 4", f"fourth stop wrong: {stop_lines[3]}";
    assert stop_lines[4] == "Stop 5", f"fifth stop wrong: {stop_lines[4]}";

    # The completion line must come after the last Stop line.
