"""Category tree: hierarchical product categories walked via typed parent/child edges.

Models the GET /api/categories scenario: categories form a tree, products
belong to categories, and a walker traverses parent -> child edges to build
a hierarchical view with depth limits and product counts.
"""

node Category {
    has id: str = "";
    has name: str = "";
    has slug: str = "";
    has description: str = "";
    has image_url: str = "";
    has image_alt: str = "";
    has is_active: bool = True;
    has display_order: int = 0;
    has product_count: int = 0;
}

node Product {
    has id: str = "";
    has name: str = "";
    has price: float = 0.0;
}

edge ParentOf {
    has order: int = 0;
}

edge CategorizedAs {
    has assignment_order: int = 0;
}

walker ProductCounter {
    has target: str = "";
    has tally: int = 0;

    can start with Category entry {
        visit [->:CategorizedAs:->];
    }

    can count with Product entry {
        self.tally = self.tally + 1;
    }
}

walker CategoryBrowser {
    has max_depth: int = 2;
    has current_depth: int = 0;
    has include_empty: bool = False;
    has include_count: bool = True;
    has visited_ids: list[str] = [];
    has snapshot: list[dict] = [];
    has report: list[str] = [];

    can start with Root entry {
        self.current_depth = 0;
        self.visited_ids = [];
        self.snapshot = [];
        visit [-->];
    }

    can browse with Category entry {
        if self.current_depth >= self.max_depth {
            disengage;
        }
        for vid in self.visited_ids {
            if vid == here.id {
                disengage;
            }
        }
        self.visited_ids.append(here.id);

        show = self.include_empty or here.product_count > 0;
        if show {
            reported_count = here.product_count if self.include_count else 0;
            indent = "  " * self.current_depth;
            line = f"{indent}- {here.name} (count={reported_count}, order={here.display_order})";
            self.report.append(line);
            entry: dict = {
                "id": here.id,
                "name": here.name,
                "slug": here.slug,
                "description": here.description,
                "isActive": here.is_active,
                "displayOrder": here.display_order,
                "productCount": reported_count,
                "children": []
            };
            self.snapshot.append(entry);
        }
        self.current_depth = self.current_depth + 1;
        visit [->:ParentOf:->];
    }
}

walker EmptyCategoryPruner {
    has pruned_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can prune with Category entry {
        if here.product_count == 0 {
            self.pruned_ids.append(here.id);
        }
        visit [-->];
    }
}

with entry {
    dogs = Category(
        id="cat_001", name="Dogs", slug="dogs",
        description="Everything for your canine companion",
        image_url="https://cdn.example.com/categories/dogs.jpg",
        image_alt="Dogs category", display_order=1
    );
    cats = Category(
        id="cat_002", name="Cats", slug="cats",
        description="Everything for your feline friend",
        display_order=2
    );

    dog_food = Category(
        id="cat_001_001", name="Dog Food", slug="dog-food",
        description="Nutritious food for dogs of all ages",
        display_order=1
    );
    dog_toys = Category(
        id="cat_001_002", name="Dog Toys", slug="dog-toys",
        description="Fun and engaging toys for dogs",
        display_order=2
    );

    dry_food = Category(
        id="cat_001_001_001", name="Dry Food", slug="dry-dog-food",
        display_order=1
    );
    wet_food = Category(
        id="cat_001_001_002", name="Wet Food", slug="wet-dog-food",
        display_order=2
    );

    dogs +>:ParentOf(order=1):+> dog_food;
    dogs +>:ParentOf(order=2):+> dog_toys;
    dog_food +>:ParentOf(order=1):+> dry_food;
    dog_food +>:ParentOf(order=2):+> wet_food;

    dog_food +>:CategorizedAs:+> Product(id="p1", name="Kibble Bag", price=29.99);
    dog_food +>:CategorizedAs:+> Product(id="p2", name="Grain Free Mix", price=42.50);
    dry_food +>:CategorizedAs:+> Product(id="p3", name="Adult Dry 15kg", price=55.00);
    wet_food +>:CategorizedAs:+> Product(id="p4", name="Wet Pouch Pack", price=18.75);
    dog_toys +>:CategorizedAs:+> Product(id="p5", name="Tennis Ball", price=5.99);
    dog_toys +>:CategorizedAs:+> Product(id="p6", name="Rope Tug", price=9.99);

    cats +>:CategorizedAs:+> Product(id="p7", name="Cat Tower", price=89.00);
    cats +>:CategorizedAs:+> Product(id="p8", name="Salmon Pouch", price=12.50);

    counter = ProductCounter(target="cat_001_001");
    dog_food spawn counter;
    dog_food.product_count = counter.tally;

    counter2 = ProductCounter(target="cat_001_001_001");
    dry_food spawn counter2;
