"""Org chart payroll rollup: each manager learns the total salary and headcount of every subtree beneath them, computed bottom-up via walkers over typed edges."""

node Employee {
    has name: str = "";
    has salary: int = 0;
    has subtree_salary: int = 0;
    has subtree_headcount: int = 0;
}

edge ReportsTo {}

walker PayrollAuditor {
    has visited: list[Employee] = [];
    has pending_report: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Employee entry {
        if here in self.visited {
            disengage;
        }
        self.visited.append(here);

        # First, recurse into every direct report so their subtrees
        # are computed before we roll our own totals up.
        for report in [->:ReportsTo:->] {
            child = PayrollAuditor(visited=self.visited);
            child spawn report;
        }

        total_salary = here.salary;
        total_headcount = 1;
        for report in [->:ReportsTo:->] {
            total_salary += report.subtree_salary;
            total_headcount += report.subtree_headcount;
        }

        here.subtree_salary = total_salary;
        here.subtree_headcount = total_headcount;
        print(f"{here.name}: salary={here.salary}, subtree_salary={here.subtree_salary}, subtree_headcount={here.subtree_headcount}");
    }
}

with entry {
