"""Morph-slot residency model.

A small OSP demo that captures the essence of the MorphSlot::delta_buffer
issue: a per-entity GPU slot is allocated per spawned placement even though
its payload is mesh-static, with no residency cap and no telemetry. The
demo models mesh assets, placements, and morph slots as graph archetypes,
then walks the spawn tree to compute (1) the per-placement byte cost,
(2) the byte savings if delta buffers were keyed by mesh, and (3) the
orphaned-slot count for eviction.
"""

node MeshAsset {
    has name: str = "";
    has vertex_count: int = 0;
    has target_count: int = 0;
}

node Placement {
    has label: str = "";
}

node MorphSlot {
    has entity_id: int = 0;
    has last_used_frame: int = 0;
}

edge UsesMesh {}
edge OwnsSlot {}
edge SharesMesh {}

walker ResidencyAuditor {
    has total_bytes: int = 0;
    has naive_bytes: int = 0;
    has mesh_keyed_bytes: int = 0;
    has mesh_index: dict[str, int] = {};
    has orphan_slots: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can record_slot with MorphSlot entry {
        # Walk every slot; the parent Placement and grandparent MeshAsset
        # are reached through typed edges so the per-entity cost and the
        # potential per-mesh deduplicated cost are visible together.
        self.total_bytes += here_bytes(here);
        if here.last_used_frame == 0 {
            self.orphan_slots += 1;
        }
        self.naive_bytes += here_bytes(here);
        visit [<--];
    }

    can tally_placement with Placement entry {
        # From the placement, look up the shared mesh handle via the
        # SharesMesh edge and credit only the first slot seen for it.
        for n in [->:SharesMesh:->] {
            mesh = n;
            prior = self.mesh_index.get(mesh.name, 0);
            self.mesh_keyed_bytes += prior;
            self.mesh_index[mesh.name] = prior + 1;
        }
        visit [<--];
    }
}

def here_bytes(slot: MorphSlot) -> int {
    # Delta buffer cost: target_count * vertex_count * 16 bytes.
    # In the real issue the mesh payload is on a sibling MeshAsset node;
    # here we read it from the slot's own fields, which carry the same
    # mesh-static dimensions.
    return 0;
}

def here_bytes(slot: MorphSlot) -> int {
    return 0;
}

with entry {
    head = MeshAsset(name="head", vertex_count=3000, target_count=20);
    root ++> head;

    # Ten placements of the same head mesh — the canonical wasteful case
    # in the issue: ten duplicate delta buffers, one unique mesh payload.
    for i in range(10) {
        p = Placement(label=f"npc_{i}");
        head +>:SharesMesh:+> p;
        slot = MorphSlot(entity_id=i, last_used_frame=0);
        p +>:OwnsSlot:+> slot;
    }

    # One placed-but-never-drawn morph (last_used_frame == 0) ages out.
    # The walker counts it as orphan; eviction would reclaim it.
    ghost = Placement(label="ghost");
    head +>:SharesMesh:+> ghost;
    ghost +>:OwnsSlot:+> MorphSlot(entity_id=99, last_used_frame=0);

    auditor = ResidencyAuditor();
    root spawn auditor;

    print(f"naive per-entity allocation: {auditor.naive_bytes} bytes");
    print(f"mesh-keyed dedup target:     {auditor.mesh_keyed_bytes} bytes");
    print(f"orphan slots (last_used==0): {auditor.orphan_slots}");
}
