test "orphan slots are detected without recursive root traversal" {
    mesh = MeshAsset(name="head", vertex_count=3000, target_count=20);
    placement = Placement(label="npc");
    slot = MorphSlot(entity_id=1, last_used_frame=0);

    placement +>:SharesMesh:+> mesh;
    placement +>:OwnsSlot:+> slot;

    assert len([placement ->:OwnsSlot:->]) == 1, "missing owned slot";
    res = slot spawn ResidencyAuditor();

    assert res.orphan_slots == 1, f"got {res.orphan_slots}";
}

test "recently used slots are not orphaned" {
    mesh = MeshAsset(name="head", vertex_count=3000, target_count=20);
    placement = Placement(label="npc");
    slot = MorphSlot(entity_id=2, last_used_frame=12);

    placement +>:SharesMesh:+> mesh;
    placement +>:OwnsSlot:+> slot;

    res = slot spawn ResidencyAuditor();

    assert res.orphan_slots == 0, f"got {res.orphan_slots}";
}

test "placements index their shared mesh identity" {
    mesh = MeshAsset(name="head", vertex_count=3000, target_count=20);
    first = Placement(label="npc_0");
    second = Placement(label="npc_1");
    first_slot = MorphSlot(entity_id=10, last_used_frame=4);
    second_slot = MorphSlot(entity_id=11, last_used_frame=4);

    first +>:SharesMesh:+> mesh;
    second +>:SharesMesh:+> mesh;
    first +>:OwnsSlot:+> first_slot;
    second +>:OwnsSlot:+> second_slot;

    first_res = first_slot spawn ResidencyAuditor();
    second_res = second_slot spawn ResidencyAuditor();

    expected_bytes = mesh.vertex_count * mesh.target_count * 16;
    assert expected_bytes == 960000, f"got {expected_bytes}";
    assert first_res.mesh_index.get("head", 0) == 1, f"got {first_res.mesh_index}";
    assert second_res.mesh_index.get("head", 0) == 1, f"got {second_res.mesh_index}";
