"""Vet-clinic round: pets are nodes, a vet walker visits them and tallies shots."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet beginning clinic round");
        visit [-->] else { disengage; }
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"  Vaccinated {here.name} the {here.species}");
        } else {
            print(f"  Checked {here.name} the {here.species} (no shot needed)");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True)
        ++> Pet(name="Bella", species="rabbit", needs_vaccine=False)
        ++> Pet(name="Tucker", species="dog", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\nRound complete: {len(vet.patients)} patients seen, "
          f"{vet.shots_given} shots given");
    print(f"Patient list: {vet.patients}");
}
