"""Tests for the vet-clinic round program."""

import io;
import from contextlib { redirect_stdout }

test "vet visits all pets and tallies patients list" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True)
        ++> Pet(name="Bella", species="rabbit", needs_vaccine=False)
        ++> Pet(name="Tucker", species="dog", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }

    assert len(res.patients) == 4, f"expected 4 patients, got {len(res.patients)}";
    assert res.patients == ["Mochi", "Rex", "Bella", "Tucker"], f"unexpected order: {res.patients}";
}

test "vet only counts shots for pets that need vaccine" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=False)
        ++> Pet(name="Bella", species="rabbit", needs_vaccine=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }

    assert res.shots_given == 1, f"expected 1 shot, got {res.shots_given}";
    assert len(res.patients) == 3, f"expected 3 patients seen, got {len(res.patients)}";
}

test "vet prints beginning and per-pet messages" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
